! Persistent layout for the per-step cross-mesh BACK CFACE gas-side data exchange (see INITIALIZE_BACK_CFACE_EXCHANGE
! and EXCHANGE_BACK_CFACE_DATA). N_CF_BACK_SEND/RECV are the per-process query totals on the requester/owner side.
LOGICAL, SAVE :: CF_BACK_EXCHANGE_ACTIVE=.FALSE.
INTEGER, SAVE :: N_CF_BACK_SEND=0,N_CF_BACK_RECV=0
INTEGER, SAVE, ALLOCATABLE, DIMENSION(:) :: CF_BACK_SEND_CNT3,CF_BACK_SDISPL3,CF_BACK_RECV_CNT3,CF_BACK_RDISPL3
! Requester side: owner mesh and back CFACE index per query. Owner side: owner mesh and resolved local CFACE index.
INTEGER, SAVE, ALLOCATABLE, DIMENSION(:) :: CF_BACK_SEND_NOM,CF_BACK_MAP_IDX
INTEGER, SAVE, ALLOCATABLE, DIMENSION(:) :: CF_BACK_RECV_NOM,CF_BACK_RECV_IDX

! L2 pressure edges gathered once after numbering. Face sides hold the owner and neighbor rows.
!< Thermodynamic rows of this process (CC_SET_THERMO_ROWS), as slots: the volume integrals and owner terms of
!< FINALIZE_FV_L2_THERMODYNAMIC_ROWS; FV_L2_DVOL_FACE and FV_L2_DEL_RHO_D_DEL_Z_FACE hold the face integrals.
!< A row owned on another process: partial sums go from TH_SSLOT to TH_SDEST; the owner adds what it receives at
!< TH_RSLOT and returns the finished rows to TH_RDEST, which land at TH_BSLOT.
INTEGER, SAVE :: TH_NSLOT=0
REAL(EB), SAVE, ALLOCATABLE, DIMENSION(:) :: TH_DIV,TH_RTRM,TH_VOL,TH_ORTRM
REAL(EB), SAVE, ALLOCATABLE, DIMENSION(:,:) :: TH_OCOEFF
INTEGER, SAVE, ALLOCATABLE, DIMENSION(:) :: TH_SSLOT,TH_SDEST,TH_RSLOT,TH_RDEST,TH_BSLOT
!< TH_SROW: global row of each slot this process touches, increasing (TH_ROW_SLOT). FV_L2_FZ_REMOTE(1,slot): species
!< right-hand side partials of rows owned on another process (END_FV_L2_SCALAR_RHS sends them to the owner).
INTEGER, SAVE, ALLOCATABLE, DIMENSION(:) :: TH_SROW
!< Combustion per CV (CC_SET_CVCHEM_LISTS): TH_CVM(slot), the row's CV has more than one member; TH_CVMST(:,slot), its
!< master (mesh, 1 cut or 2 regular, ICC,JCC,0 or I,J,K) when the CV is owned here, 0 otherwise.
LOGICAL, SAVE, ALLOCATABLE, DIMENSION(:) :: TH_CVM
INTEGER, SAVE, ALLOCATABLE, DIMENSION(:,:) :: TH_CVMST
!< The same slots serve the RHOZZ rows; TH_OSLOT(IROW) is the slot of this process's solve row IROW (RZ_Z), 0 if none.
INTEGER, SAVE, ALLOCATABLE, DIMENSION(:) :: TH_OSLOT
!< Per mesh, the members of its link groups that it holds, in one global order (axis, x, y, z): M(1)=1-3 (Cartesian
!< face, axis) or 4 (own cut piece), M(2)=link number, M(3:5)=I,J,K or ICF,JCF, M(6)=1 when this mesh counts the
!< member in the cross-mesh sum; A=area. XG(IL)=cross-mesh group of link number IL, 0 when one mesh holds it all.
!< V=member value stored by L2_BAROCLINIC_MEMBERS (quantity 0 of ACCUM_L2_ORDERED_MEAN and L2_CROSS_SUMS).
TYPE L2_MEAN_TYPE
   INTEGER :: N=-1
   INTEGER, ALLOCATABLE :: M(:,:),XG(:)
   REAL(EB), ALLOCATABLE :: A(:),V(:)
END TYPE L2_MEAN_TYPE
TYPE(L2_MEAN_TYPE), ALLOCATABLE, TARGET, SAVE :: L2_MEAN(:)
REAL(EB), ALLOCATABLE, SAVE :: L2_XS(:,:) !< (1:2,cross-mesh group): sums of u*A and A over all meshes.
INTEGER, SAVE :: N_FV_H_EDGE_GLOBAL=0
INTEGER, SAVE, ALLOCATABLE, DIMENSION(:) :: FV_H_EDGE_ROW,FV_H_EDGE_COL,FV_H_EDGE_ZONE
REAL(EB), SAVE, ALLOCATABLE, DIMENSION(:) :: FV_H_EDGE_BIJ,FV_L2_DVOL_FACE
REAL(EB), SAVE, ALLOCATABLE, DIMENSION(:,:) :: FV_L2_DEL_RHO_D_DEL_Z_FACE,FV_L2_FZ_REMOTE
INTEGER, SAVE :: CFL_NREMOTE=0 !< Held CFL rows whose owner is on another rank.
INTEGER, SAVE, ALLOCATABLE, DIMENSION(:,:) :: CFL_RMAP !< (owner mesh, CFL_XQ entry) of each CFL record received here.
TYPE PH_Z
   INTEGER :: N=0, M=0
   INTEGER, ALLOCATABLE :: ROW(:), DEST(:), IROW(:), FROM(:), BSLOT(:)
   REAL(EB), ALLOCATABLE :: VAL(:), SOL(:)
END TYPE PH_Z
TYPE(PH_Z), ALLOCATABLE, SAVE, TARGET :: PH(:); INTEGER, SAVE :: PH_ZONE=-1

CONTAINS

! ------------------------ INITIALIZE_BACK_CFACE_EXCHANGE ---------------------------
SUBROUTINE INITIALIZE_BACK_CFACE_EXCHANGE

INTEGER :: NM,NOM,IQ,NQ,IIO,JJO,KKO,NOM2,ICFACE,SURF_B,FRONT,OD_INDEX,N_RESOLVED,N_GLOBAL,IP,K,P,TOTAL_SEND,TOTAL_RECV,IERR
REAL(EB) :: POS(3),NBACK(3)
INTEGER,  ALLOCATABLE :: SEND_CNT(:),RECV_CNT(:),SDISPL(:),RDISPL(:),CNT3_S(:),CNT3_R(:),DSP3_S(:),DSP3_R(:),COUNTER(:)
INTEGER,  ALLOCATABLE :: SEND_NOM(:),RECV_NOM(:),REPLY_IDX(:),REPLY_SURF(:),REPLY_DIM(:), &
                         REPLY_BACK(:),REPLY_BSURF(:),REPLY_BDIM(:),MAP_NM(:),MAP_FRONT(:)
REAL(EB), ALLOCATABLE :: SEND_POS(:),RECV_POS(:),SEND_NBACK(:),RECV_NBACK(:)

N_RESOLVED = 0
ALLOCATE(SEND_CNT(0:N_MPI_PROCESSES-1)) ; SEND_CNT = 0
DO NM=LOWER_MESH_INDEX,UPPER_MESH_INDEX
   DO NOM=1,NMESHES
      IF (NOM==NM) CYCLE
      NQ = MESHES(NM)%OMESH(NOM)%N_CFACE_QUERY
      IF (NQ==0) CYCLE
      IF (PROCESS(NOM)==MY_RANK) THEN  ! Owner is on this process: resolve directly.
         DO IQ=1,NQ
            POS(1:3)   = MESHES(NM)%OMESH(NOM)%CFACE_QUERY_XYZ(IAXIS:KAXIS,IQ)
            NBACK(1:3) = MESHES(NM)%OMESH(NOM)%CFACE_QUERY_NBACK(IAXIS:KAXIS,IQ)
            CALL SEARCH_OTHER_MESHES(POS(1),POS(2),POS(3),NOM2,IIO,JJO,KKO)
            IF (NOM2/=NOM) CYCLE
            ICFACE = GET_BACK_CFACE_INDEX(NOM,IIO,JJO,KKO,POS,-1,-1,NBACK)
            IF (ICFACE>0) THEN
               FRONT    = MESHES(NM)%OMESH(NOM)%CFACE_QUERY_FRONT(IQ)
               OD_INDEX = MESHES(NM)%CFACE(FRONT)%OD_INDEX
               IF (OD_INDEX>0) THEN
                  MESHES(NM)%BOUNDARY_ONE_D(OD_INDEX)%BACK_MESH  = NOM
                  MESHES(NM)%BOUNDARY_ONE_D(OD_INDEX)%BACK_INDEX = ICFACE
                  MESHES(NM)%BOUNDARY_ONE_D(OD_INDEX)%BACK_SURF  = MESHES(NOM)%CFACE(ICFACE)%SURF_INDEX
                  N_RESOLVED = N_RESOLVED + 1
               ENDIF
            ENDIF
         ENDDO
      ELSE  ! Owner on another process: count for the all-to-all exchange below.
         SEND_CNT(PROCESS(NOM)) = SEND_CNT(PROCESS(NOM)) + NQ
      ENDIF
   ENDDO
ENDDO

CROSS_PROCESS_IF: IF (N_MPI_PROCESSES>1) THEN

   ALLOCATE(RECV_CNT(0:N_MPI_PROCESSES-1)) ; RECV_CNT = 0
   CALL MPI_ALLTOALL(SEND_CNT,1,MPI_INTEGER,RECV_CNT,1,MPI_INTEGER,MPI_COMM_WORLD,IERR)

   ALLOCATE(SDISPL(0:N_MPI_PROCESSES-1),RDISPL(0:N_MPI_PROCESSES-1))
   ALLOCATE(CNT3_S(0:N_MPI_PROCESSES-1),CNT3_R(0:N_MPI_PROCESSES-1))
   ALLOCATE(DSP3_S(0:N_MPI_PROCESSES-1),DSP3_R(0:N_MPI_PROCESSES-1))
   SDISPL(0) = 0 ; RDISPL(0) = 0
   DO IP=1,N_MPI_PROCESSES-1
      SDISPL(IP) = SDISPL(IP-1) + SEND_CNT(IP-1)
      RDISPL(IP) = RDISPL(IP-1) + RECV_CNT(IP-1)
   ENDDO
   TOTAL_SEND = SDISPL(N_MPI_PROCESSES-1) + SEND_CNT(N_MPI_PROCESSES-1)
   TOTAL_RECV = RDISPL(N_MPI_PROCESSES-1) + RECV_CNT(N_MPI_PROCESSES-1)
   CNT3_S = 3*SEND_CNT ; CNT3_R = 3*RECV_CNT ; DSP3_S = 3*SDISPL ; DSP3_R = 3*RDISPL
   ALLOCATE(SEND_NOM(MAX(TOTAL_SEND,1)),SEND_POS(MAX(3*TOTAL_SEND,1)),SEND_NBACK(MAX(3*TOTAL_SEND,1)), &
            MAP_NM(MAX(TOTAL_SEND,1)), &
            MAP_FRONT(MAX(TOTAL_SEND,1)),REPLY_BACK(MAX(TOTAL_SEND,1)),REPLY_BSURF(MAX(TOTAL_SEND,1)), &
            REPLY_BDIM(MAX(TOTAL_SEND,1)))
   ALLOCATE(RECV_NOM(MAX(TOTAL_RECV,1)),RECV_POS(MAX(3*TOTAL_RECV,1)),RECV_NBACK(MAX(3*TOTAL_RECV,1)), &
            REPLY_IDX(MAX(TOTAL_RECV,1)), &
            REPLY_SURF(MAX(TOTAL_RECV,1)),REPLY_DIM(MAX(TOTAL_RECV,1)))
   ALLOCATE(COUNTER(0:N_MPI_PROCESSES-1)) ; COUNTER = SDISPL

   ! Pack cross-process queries grouped by destination process (matching the SDISPL ordering). MAP_NM and
   ! MAP_FRONT record the local front CFACE associated with each query so the reply can be applied in order.
   DO NM=LOWER_MESH_INDEX,UPPER_MESH_INDEX
      DO NOM=1,NMESHES
         IF (NOM==NM) CYCLE
         IF (PROCESS(NOM)==MY_RANK) CYCLE
         NQ = MESHES(NM)%OMESH(NOM)%N_CFACE_QUERY
         IF (NQ==0) CYCLE
         IP = PROCESS(NOM)
         DO IQ=1,NQ
            P = COUNTER(IP) + 1 ; COUNTER(IP) = P
            SEND_NOM(P)           = NOM
            SEND_POS(3*P-2:3*P)   = MESHES(NM)%OMESH(NOM)%CFACE_QUERY_XYZ(IAXIS:KAXIS,IQ)
            SEND_NBACK(3*P-2:3*P) = MESHES(NM)%OMESH(NOM)%CFACE_QUERY_NBACK(IAXIS:KAXIS,IQ)
            MAP_NM(P)             = NM
            MAP_FRONT(P)          = MESHES(NM)%OMESH(NOM)%CFACE_QUERY_FRONT(IQ)
         ENDDO
      ENDDO
   ENDDO
   CALL MPI_ALLTOALLV(SEND_NOM,SEND_CNT,SDISPL,MPI_INTEGER,RECV_NOM,RECV_CNT,RDISPL,MPI_INTEGER,MPI_COMM_WORLD,IERR)
   CALL MPI_ALLTOALLV(SEND_POS,CNT3_S,DSP3_S,MPI_DOUBLE_PRECISION,RECV_POS,CNT3_R,DSP3_R,MPI_DOUBLE_PRECISION,&
                      MPI_COMM_WORLD,IERR)
   CALL MPI_ALLTOALLV(SEND_NBACK,CNT3_S,DSP3_S,MPI_DOUBLE_PRECISION,RECV_NBACK,CNT3_R,DSP3_R,MPI_DOUBLE_PRECISION,&
                      MPI_COMM_WORLD,IERR)

   ! Owner side: resolve each received query against its local cut-face data.
   DO K=1,TOTAL_RECV
      NOM = RECV_NOM(K)
      POS(1:3)   = RECV_POS(3*K-2:3*K)
      NBACK(1:3) = RECV_NBACK(3*K-2:3*K)
      CALL SEARCH_OTHER_MESHES(POS(1),POS(2),POS(3),NOM2,IIO,JJO,KKO)
      ICFACE = 0 ; SURF_B = 0
      IF (NOM2==NOM) ICFACE = GET_BACK_CFACE_INDEX(NOM,IIO,JJO,KKO,POS,-1,-1,NBACK)
      IF (ICFACE>0) SURF_B = MESHES(NOM)%CFACE(ICFACE)%SURF_INDEX
      REPLY_IDX(K)  = ICFACE
      REPLY_SURF(K) = SURF_B
      REPLY_DIM(K)  = 0 ; IF (ICFACE>0) REPLY_DIM(K) = MESHES(NOM)%N_CFACE_CELLS_DIM
   ENDDO

   ! Reverse all-to-all: return the resolved BACK CFACE index, SURF_INDEX and owner CFACE dimension to requesters.
   CALL MPI_ALLTOALLV(REPLY_IDX, RECV_CNT,RDISPL,MPI_INTEGER,REPLY_BACK, SEND_CNT,SDISPL,MPI_INTEGER,MPI_COMM_WORLD,IERR)
   CALL MPI_ALLTOALLV(REPLY_SURF,RECV_CNT,RDISPL,MPI_INTEGER,REPLY_BSURF,SEND_CNT,SDISPL,MPI_INTEGER,MPI_COMM_WORLD,IERR)
   CALL MPI_ALLTOALLV(REPLY_DIM, RECV_CNT,RDISPL,MPI_INTEGER,REPLY_BDIM, SEND_CNT,SDISPL,MPI_INTEGER,MPI_COMM_WORLD,IERR)

   ! Requester side: store BACK_MESH / BACK_INDEX / BACK_SURF and allocate a ghost CFACE (with its boundary
   ! storage) in MESHES(NOM) so the per-step exchange can deposit the back gas-side state and the solid heat
   ! transfer solver can read it exactly as it reads a same-mesh back CFACE.
   DO P=1,TOTAL_SEND
      ICFACE = REPLY_BACK(P)
      IF (ICFACE>0) THEN
         NM       = MAP_NM(P)
         FRONT    = MAP_FRONT(P)
         NOM      = SEND_NOM(P)
         SURF_B   = REPLY_BSURF(P)
         OD_INDEX = MESHES(NM)%CFACE(FRONT)%OD_INDEX
         IF (OD_INDEX>0) THEN
            MESHES(NM)%BOUNDARY_ONE_D(OD_INDEX)%BACK_MESH  = NOM
            MESHES(NM)%BOUNDARY_ONE_D(OD_INDEX)%BACK_INDEX = ICFACE
            MESHES(NM)%BOUNDARY_ONE_D(OD_INDEX)%BACK_SURF  = SURF_B
            N_RESOLVED = N_RESOLVED + 1
            ! Allocate the ghost CFACE once per (NOM,ICFACE).
            IF (.NOT.ALLOCATED(MESHES(NOM)%CFACE)) THEN
               MESHES(NOM)%N_CFACE_CELLS_DIM = REPLY_BDIM(P)
               ALLOCATE(MESHES(NOM)%CFACE(0:MESHES(NOM)%N_CFACE_CELLS_DIM))
            ENDIF
            IF (ICFACE>UBOUND(MESHES(NOM)%CFACE,1)) THEN
               CALL ALLOCATE_STORAGE(NOM,CFACE_INDEX=ICFACE,SURF_INDEX=SURF_B)
            ELSEIF (MESHES(NOM)%CFACE(ICFACE)%B1_INDEX<=0) THEN
               CALL ALLOCATE_STORAGE(NOM,CFACE_INDEX=ICFACE,SURF_INDEX=SURF_B)
            ENDIF
         ENDIF
      ENDIF
   ENDDO

   ! Define exchange layout so EXCHANGE_BACK_CFACE_DATA can move the back gas-side state every step.
   N_CF_BACK_SEND = TOTAL_SEND
   N_CF_BACK_RECV = TOTAL_RECV
   ALLOCATE(CF_BACK_SEND_CNT3(0:N_MPI_PROCESSES-1),CF_BACK_SDISPL3(0:N_MPI_PROCESSES-1))
   ALLOCATE(CF_BACK_RECV_CNT3(0:N_MPI_PROCESSES-1),CF_BACK_RDISPL3(0:N_MPI_PROCESSES-1))
   CF_BACK_SEND_CNT3 = CNT3_S ; CF_BACK_SDISPL3 = DSP3_S
   CF_BACK_RECV_CNT3 = CNT3_R ; CF_BACK_RDISPL3 = DSP3_R
   ALLOCATE(CF_BACK_SEND_NOM(MAX(TOTAL_SEND,1)),CF_BACK_MAP_IDX(MAX(TOTAL_SEND,1)))
   ALLOCATE(CF_BACK_RECV_NOM(MAX(TOTAL_RECV,1)),CF_BACK_RECV_IDX(MAX(TOTAL_RECV,1)))
   IF (TOTAL_SEND>0) THEN
      CF_BACK_SEND_NOM(1:TOTAL_SEND) = SEND_NOM(1:TOTAL_SEND)
      CF_BACK_MAP_IDX(1:TOTAL_SEND)  = REPLY_BACK(1:TOTAL_SEND)
   ENDIF
   IF (TOTAL_RECV>0) THEN
      CF_BACK_RECV_NOM(1:TOTAL_RECV) = RECV_NOM(1:TOTAL_RECV)
      CF_BACK_RECV_IDX(1:TOTAL_RECV) = REPLY_IDX(1:TOTAL_RECV)
   ENDIF
   N_GLOBAL = TOTAL_SEND
   CALL MPI_ALLREDUCE(MPI_IN_PLACE,N_GLOBAL,1,MPI_INTEGER,MPI_SUM,MPI_COMM_WORLD,IERR)
   IF (N_GLOBAL>0) CF_BACK_EXCHANGE_ACTIVE = .TRUE.

   DEALLOCATE(RECV_CNT,SDISPL,RDISPL,CNT3_S,CNT3_R,DSP3_S,DSP3_R,COUNTER,SEND_NOM,SEND_POS,SEND_NBACK,MAP_NM,MAP_FRONT, &
              REPLY_BACK,REPLY_BSURF,REPLY_BDIM,RECV_NOM,RECV_POS,RECV_NBACK,REPLY_IDX,REPLY_SURF,REPLY_DIM)

ENDIF CROSS_PROCESS_IF
DEALLOCATE(SEND_CNT)

!IF (N_RESOLVED>0) &
!   WRITE(LU_ERR,'(A,I0,A,I0)') ' BACK CFACE exchange: process ',MY_RANK,' resolved cross-mesh back CFACEs: ',N_RESOLVED

END SUBROUTINE INITIALIZE_BACK_CFACE_EXCHANGE


! ------------------------ EXCHANGE_BACK_CFACE_DATA --------------------------------
SUBROUTINE EXCHANGE_BACK_CFACE_DATA

INTEGER :: K,P,NOM,ICFACE,B1,IERR
REAL(EB), ALLOCATABLE :: SBUF(:),RBUF(:)

IF (.NOT.CF_BACK_EXCHANGE_ACTIVE .OR. N_MPI_PROCESSES==1) RETURN
ALLOCATE(SBUF(MAX(3*N_CF_BACK_RECV,1))) ; SBUF = 0._EB
ALLOCATE(RBUF(MAX(3*N_CF_BACK_SEND,1))) ; RBUF = 0._EB

! Owner side: pack the back gas-side state of each resolved CFACE.
DO K=1,N_CF_BACK_RECV
   ICFACE = CF_BACK_RECV_IDX(K)
   IF (ICFACE<=0) CYCLE
   NOM = CF_BACK_RECV_NOM(K)
   B1  = MESHES(NOM)%CFACE(ICFACE)%B1_INDEX
   IF (B1<=0) CYCLE
   SBUF(3*K-2) = MESHES(NOM)%BOUNDARY_PROP1(B1)%TMP_G
   SBUF(3*K-1) = MESHES(NOM)%BOUNDARY_PROP1(B1)%HEAT_TRANS_COEF
   SBUF(3*K  ) = MESHES(NOM)%BOUNDARY_PROP1(B1)%Q_RAD_IN
ENDDO
CALL MPI_ALLTOALLV(SBUF,CF_BACK_RECV_CNT3,CF_BACK_RDISPL3,MPI_DOUBLE_PRECISION, &
                   RBUF,CF_BACK_SEND_CNT3,CF_BACK_SDISPL3,MPI_DOUBLE_PRECISION,MPI_COMM_WORLD,IERR)

! Requester side: deposit the received state into the ghost CFACE so the solver reads it like a same-mesh back CFACE.
DO P=1,N_CF_BACK_SEND
   ICFACE = CF_BACK_MAP_IDX(P)
   IF (ICFACE<=0) CYCLE
   NOM = CF_BACK_SEND_NOM(P)
   B1  = MESHES(NOM)%CFACE(ICFACE)%B1_INDEX
   IF (B1<=0) CYCLE
   MESHES(NOM)%BOUNDARY_PROP1(B1)%TMP_G           = RBUF(3*P-2)
   MESHES(NOM)%BOUNDARY_PROP1(B1)%HEAT_TRANS_COEF = RBUF(3*P-1)
   MESHES(NOM)%BOUNDARY_PROP1(B1)%Q_RAD_IN        = RBUF(3*P)
ENDDO
DEALLOCATE(SBUF,RBUF)

END SUBROUTINE EXCHANGE_BACK_CFACE_DATA


! ------------------------ COPY_UNST_DM_TO_CART -------------------------------------

SUBROUTINE COPY_UNST_DM_TO_CART(NM)
! Assumes POINT_TO_MESH(NM) has been called.
INTEGER, INTENT(IN) :: NM
INTEGER :: ICC,JCC,I,J,K,NS
REAL(EB) :: VOL
TYPE(CC_FV_TYPE), POINTER :: FV
FV=>MESHES(NM)%FV

DO ICC=1,MESHES(NM)%N_CUTCELL_MESH+MESHES(NM)%N_GCCUTCELL_MESH
   CC => CUT_CELL(ICC);  I = CC%IJK(IAXIS); J = CC%IJK(JAXIS);  K = CC%IJK(KAXIS)
   IF(I < 0 .OR. I > IBP1) CYCLE
   IF(J < 0 .OR. J > JBP1) CYCLE
   IF(K < 0 .OR. K > KBP1) CYCLE
   IF (CELL(CELL_INDEX(I,J,K))%SOLID) CYCLE ! Cycle in case Cartesian cell inside OBSTS.
   IF (.NOT.ALLOCATED(MESHES(NM)%D_SOURCE)) CYCLE
   VOL=DX(I)*DY(J)*DZ(K); D_SOURCE(I,J,K) =0._EB; M_DOT_PPP(I,J,K,1:N_TRACKED_SPECIES)=0._EB
   DO JCC=1,CC%NCELL
      ! A piece with no IG row has no solver row in either numbering and contributes to no budget.
      IF (CC%IG(JCC)>=1) THEN
         D_SOURCE(I,J,K)=D_SOURCE(I,J,K)+FV%CV%D_SOURCE(CC%IG(JCC))*CC%VOLUME(JCC)
         DO NS=1,N_TRACKED_SPECIES
            M_DOT_PPP(I,J,K,NS)=M_DOT_PPP(I,J,K,NS)+FV%CV%M_DOT_PPP(NS,CC%IG(JCC))*CC%VOLUME(JCC)
         ENDDO
      ENDIF
   ENDDO
   D_SOURCE(I,J,K) = D_SOURCE(I,J,K)/VOL
   M_DOT_PPP(I,J,K,1:N_TRACKED_SPECIES) = M_DOT_PPP(I,J,K,1:N_TRACKED_SPECIES)/VOL
ENDDO

RETURN
END SUBROUTINE COPY_UNST_DM_TO_CART

! --------------------- GET_OPENBC_TANGENTIAL_CUTFACE_VEL ---------------------------

SUBROUTINE GET_OPENBC_TANGENTIAL_CUTFACE_VEL(APPLY_TO_ESTIMATED_VARIABLES,UPWIND_BOUNDARY,INFLOW_BOUNDARY,&
                                             IEC,II,JJ,KK,IOR,UU,VV,WW,NM)

LOGICAL, INTENT(IN) :: APPLY_TO_ESTIMATED_VARIABLES,UPWIND_BOUNDARY,INFLOW_BOUNDARY
INTEGER, INTENT(IN) :: IEC,II,JJ,KK,IOR,NM
REAL(EB), INTENT(INOUT), POINTER, DIMENSION(:,:,:) :: UU,VV,WW

INTEGER :: I1,J1,K1,I2,J2,K2,AXIS
REAL(EB):: VWND
REAL(EB), POINTER, DIMENSION(:,:,:) :: VELOC

IF (.NOT.UPWIND_BOUNDARY .OR. .NOT.INFLOW_BOUNDARY) THEN  ! For regular OPEN boundary, (free-slip) BCs
   SELECT CASE(IEC)
      CASE(1)
         IF (JJ==0    .AND. IOR== 2) THEN; I1=  II; J1=   0; K1=  KK; I2=  II; J2=   1; K2=  KK; AXIS=KAXIS; VELOC=>WW; ENDIF
         IF (JJ==JBAR .AND. IOR==-2) THEN; I1=  II; J1=JBP1; K1=  KK; I2=  II; J2=JBAR; K2=  KK; AXIS=KAXIS; VELOC=>WW; ENDIF
         IF (KK==0    .AND. IOR== 3) THEN; I1=  II; J1=  JJ; K1=   0; I2=  II; J2=  JJ; K2=   1; AXIS=JAXIS; VELOC=>VV; ENDIF
         IF (KK==KBAR .AND. IOR==-3) THEN; I1=  II; J1=  JJ; K1=KBP1; I2=  II; J2=  JJ; K2=KBAR; AXIS=JAXIS; VELOC=>VV; ENDIF
      CASE(2)
         IF (II==0    .AND. IOR== 1) THEN; I1=   0; J1=  JJ; K1=  KK; I2=   1; J2=  JJ; K2=  KK; AXIS=KAXIS; VELOC=>WW; ENDIF
         IF (II==IBAR .AND. IOR==-1) THEN; I1=IBP1; J1=  JJ; K1=  KK; I2=IBAR; J2=  JJ; K2=  KK; AXIS=KAXIS; VELOC=>WW; ENDIF
         IF (KK==0    .AND. IOR== 3) THEN; I1=  II; J1=  JJ; K1=   0; I2=  II; J2=  JJ; K2=   1; AXIS=IAXIS; VELOC=>UU; ENDIF
         IF (KK==KBAR .AND. IOR==-3) THEN; I1=  II; J1=  JJ; K1=KBP1; I2=  II; J2=  JJ; K2=KBAR; AXIS=IAXIS; VELOC=>UU; ENDIF
      CASE(3)
         IF (II==0    .AND. IOR== 1) THEN; I1=   0; J1=  JJ; K1=  KK; I2=   1; J2=  JJ; K2=  KK; AXIS=JAXIS; VELOC=>VV; ENDIF
         IF (II==IBAR .AND. IOR==-1) THEN; I1=IBP1; J1=  JJ; K1=  KK; I2=IBAR; J2=  JJ; K2=  KK; AXIS=JAXIS; VELOC=>VV; ENDIF
         IF (JJ==0    .AND. IOR== 2) THEN; I1=  II; J1=   0; K1=  KK; I2=  II; J2=   1; K2=  KK; AXIS=IAXIS; VELOC=>UU; ENDIF
         IF (JJ==JBAR .AND. IOR==-2) THEN; I1=  II; J1=JBP1; K1=  KK; I2=  II; J2=JBAR; K2=  KK; AXIS=IAXIS; VELOC=>UU; ENDIF
   END SELECT
   CALL SET_GHOSTFACE_VEL_FREESLIP(I1,J1,K1,I2,J2,K2,AXIS,VELOC)
ELSE ! For upwind, inflow boundaries, use the specified wind field for tangential velocity components
   SELECT CASE(IEC)
      CASE(1)
         IF (JJ==0    .AND. IOR== 2) THEN; I1=  II; J1=   0; K1=  KK; AXIS=KAXIS; VWND=W_WIND(KK); VELOC=>WW; ENDIF
         IF (JJ==JBAR .AND. IOR==-2) THEN; I1=  II; J1=JBP1; K1=  KK; AXIS=KAXIS; VWND=W_WIND(KK); VELOC=>WW; ENDIF
         IF (KK==0    .AND. IOR== 3) THEN; I1=  II; J1=  JJ; K1=   0; AXIS=JAXIS; VWND=V_WIND(KK); VELOC=>VV; ENDIF
         IF (KK==KBAR .AND. IOR==-3) THEN; I1=  II; J1=  JJ; K1=KBP1; AXIS=JAXIS; VWND=V_WIND(KK); VELOC=>VV; ENDIF
      CASE(2)
         IF (II==0    .AND. IOR== 1) THEN; I1=   0; J1=  JJ; K1=  KK; AXIS=KAXIS; VWND=W_WIND(KK); VELOC=>WW; ENDIF
         IF (II==IBAR .AND. IOR==-1) THEN; I1=IBP1; J1=  JJ; K1=  KK; AXIS=KAXIS; VWND=W_WIND(KK); VELOC=>WW; ENDIF
         IF (KK==0    .AND. IOR== 3) THEN; I1=  II; J1=  JJ; K1=   0; AXIS=IAXIS; VWND=U_WIND(KK); VELOC=>UU; ENDIF
         IF (KK==KBAR .AND. IOR==-3) THEN; I1=  II; J1=  JJ; K1=KBP1; AXIS=IAXIS; VWND=U_WIND(KK); VELOC=>UU; ENDIF
      CASE(3)
         IF (II==0    .AND. IOR== 1) THEN; I1=   0; J1=  JJ; K1=  KK; AXIS=JAXIS; VWND=V_WIND(KK); VELOC=>VV; ENDIF
         IF (II==IBAR .AND. IOR==-1) THEN; I1=IBP1; J1=  JJ; K1=  KK; AXIS=JAXIS; VWND=V_WIND(KK); VELOC=>VV; ENDIF
         IF (JJ==0    .AND. IOR== 2) THEN; I1=  II; J1=   0; K1=  KK; AXIS=IAXIS; VWND=U_WIND(KK); VELOC=>UU; ENDIF
         IF (JJ==JBAR .AND. IOR==-2) THEN; I1=  II; J1=JBP1; K1=  KK; AXIS=IAXIS; VWND=U_WIND(KK); VELOC=>UU; ENDIF
   END SELECT
   CALL SET_GHOSTFACE_VEL_WIND(I1,J1,K1,AXIS,VWND,VELOC)
ENDIF

RETURN

CONTAINS

SUBROUTINE CC_FV_SET_OPENBC_FACE_VEL(ICF,VEL_CF,ESTIMATED)
INTEGER, INTENT(IN) :: ICF
REAL(EB), INTENT(IN) :: VEL_CF
LOGICAL, INTENT(IN) :: ESTIMATED
INTEGER :: JCF,IF_
TYPE(CC_FV_TYPE), POINTER :: FV
FV=>MESHES(NM)%FV
DO JCF=1,CUT_FACE(ICF)%NFACE
   IF_=MESHES(NM)%CUT_FACE(ICF)%FC(JCF)
   IF (ESTIMATED) THEN
      FV%FACE%VELS(IF_)=VEL_CF
   ELSE
      FV%FACE%VEL(IF_)=VEL_CF
   ENDIF
ENDDO
END SUBROUTINE CC_FV_SET_OPENBC_FACE_VEL

FUNCTION CC_FV_AREA_AVG_FACE_VEL(ICF,ESTIMATED) RESULT(VEL_AVG)
INTEGER, INTENT(IN) :: ICF
LOGICAL, INTENT(IN) :: ESTIMATED
REAL(EB) :: VEL_AVG,AREAT
AREAT = SUM(CUT_FACE(ICF)%AREA(1:CUT_FACE(ICF)%NFACE))
IF (ESTIMATED) THEN
   VEL_AVG=CC_FV_CUTFACE_MOM_AREA(NM,ICF,CC_FV_MOM_VELS)/AREAT
ELSE
   VEL_AVG=CC_FV_CUTFACE_MOM_AREA(NM,ICF,CC_FV_MOM_VEL)/AREAT
ENDIF
END FUNCTION CC_FV_AREA_AVG_FACE_VEL

SUBROUTINE SET_GHOSTFACE_VEL_FREESLIP(I1,J1,K1,I2,J2,K2,AXIS,VELOC)
INTEGER, INTENT(IN) :: I1,J1,K1,I2,J2,K2,AXIS
REAL(EB), INTENT(INOUT), POINTER, DIMENSION(:,:,:) :: VELOC

TYPE(CC_CUTFACE_TYPE), POINTER :: CF1, CF2
INTEGER :: IFC1, IFC2
REAL(EB):: VEL_CF

IFC1 = FCVAR(I1,J1,K1,CC_IDCF,AXIS); IFC2 = FCVAR(I2,J2,K2,CC_IDCF,AXIS)
IF(IFC1<1 .AND. IFC2<1) RETURN ! Both faces are Regular gas or solid.
IF (IFC1>0) THEN ! Ghost face is gas cut-face.
   IF(IFC2<1) THEN; VEL_CF = VELOC(I2,J2,K2) ! Donor is regular gasphase.
   ELSE; VEL_CF = VELOC(I2,J2,K2)/CUT_FACE(IFC2)%ALPHA_CF ! Donor face is gas cut-face.
   ENDIF
   CF1 => CUT_FACE(IFC1)
   CALL CC_FV_SET_OPENBC_FACE_VEL(IFC1,VEL_CF,APPLY_TO_ESTIMATED_VARIABLES)
   CF1%VEL_CF  = VEL_CF; CF1%VEL_CRT = VEL_CF*CF1%ALPHA_CF
   VELOC(I1,J1,K1) = CF1%VEL_CRT
ELSEIF(FCVAR(I1,J1,K1,CC_FGSC,AXIS)==CC_GASPHASE) THEN ! Ghost face is regular gasphase.
   CF2   => CUT_FACE(IFC2)
   ! Donor is cut-face:
   VELOC(I1,J1,K1)=CC_FV_AREA_AVG_FACE_VEL(IFC2,APPLY_TO_ESTIMATED_VARIABLES)
ENDIF

END SUBROUTINE SET_GHOSTFACE_VEL_FREESLIP

SUBROUTINE SET_GHOSTFACE_VEL_WIND(I1,J1,K1,AXIS,VWND,VELOC)
INTEGER, INTENT(IN) :: I1,J1,K1,AXIS
REAL(EB),INTENT(IN) :: VWND
REAL(EB), INTENT(INOUT), POINTER, DIMENSION(:,:,:) :: VELOC

TYPE(CC_CUTFACE_TYPE), POINTER :: CF1
INTEGER :: IFC1

IFC1 = FCVAR(I1,J1,K1,CC_IDCF,AXIS); IF(IFC1<1) RETURN ! Ghost face is Regular gas or solid.
CF1 => CUT_FACE(IFC1)
CALL CC_FV_SET_OPENBC_FACE_VEL(IFC1,VWND,APPLY_TO_ESTIMATED_VARIABLES)
CF1%VEL_CF  = VWND; CF1%VEL_CRT = VWND*CF1%ALPHA_CF
VELOC(I1,J1,K1) = CF1%VEL_CRT

END SUBROUTINE SET_GHOSTFACE_VEL_WIND

END SUBROUTINE GET_OPENBC_TANGENTIAL_CUTFACE_VEL

! --------------------------- GET_H_GUARD_CUTCELL -----------------------------------

SUBROUTINE GET_H_GUARD_CUTCELL(NM,HP)

! Fill ghost cell H values for cut-cell regions at mesh boundaries.
! Handles: RC faces (cut-cell to regular), cut-faces at interpolated boundaries.
! Assumes POINT_TO_MESH(NM) has been called.
INTEGER, INTENT(IN) :: NM
REAL(EB), INTENT(INOUT), POINTER, DIMENSION(:,:,:) :: HP

! Local Variables:
INTEGER :: IW, II, JJ, KK, IIG, JJG, KKG, ICC_GHOST, ICC_INT, NOM, IIO, JJO, KKO, IOR, ICC_EXT
INTEGER :: X1AXIS, ICF_EXT, ISHF(IAXIS:KAXIS)
REAL(EB) :: H_INT, D_INT, D_GHOST, D_EXT, X_FACE, XFN, SUM_FLUX, A_INT, A_EXT, H_EXT, H_GHOST
TYPE (WALL_TYPE), POINTER :: WC
TYPE (BOUNDARY_COORD_TYPE), POINTER :: BC
TYPE (EXTERNAL_WALL_TYPE), POINTER :: EWC
TYPE (OMESH_TYPE), POINTER :: OM
TYPE (CC_CUTFACE_TYPE), POINTER :: CF

! ULMAT: guard cut pieces need nothing here, the tail GCELL scatter below copies HP into their FV rows.
IF (PRES_FLAG/=ULMAT_FLAG) THEN
   ! EXTERNAL_WALL_CELL approach for GLMAT with refinement support
   WALL_CELL_LOOP : DO IW=1,N_EXTERNAL_WALL_CELLS
      WC => WALL(IW); BC => BOUNDARY_COORD(WC%BC_INDEX)
      IF (ALL((/INTERPOLATED_BOUNDARY, PERIODIC_BOUNDARY/) /= WC%BOUNDARY_TYPE)) CYCLE
      EWC => EXTERNAL_WALL(IW)
      NOM = EWC%NOM; IF (NOM < 1) CYCLE
      OM => OMESH(NOM)

      II  = BC%II;  JJ  = BC%JJ;  KK  = BC%KK
      IIG = BC%IIG; JJG = BC%JJG; KKG = BC%KKG; IOR = BC%IOR; X1AXIS = ABS(IOR)
      ICC_GHOST = CCVAR(II,JJ,KK,CC_IDCC)      ! Ghost cell cut-cell index
      ICC_INT   = CCVAR(IIG,JJG,KKG,CC_IDCC)   ! Internal cell cut-cell index
      IF (ICC_GHOST < 1 .AND. ICC_INT < 1) CYCLE ! This is handled by EXTERNAL_WALL_LOOP in pres.f90

      ! Get H_INT (internal cell)
      IF (ICC_INT > 0) THEN
         IF (PREDICTOR) THEN; H_INT = GET_CUTCELL_H(NM,ICC_INT,1,1._EB)
         ELSE;                H_INT = GET_CUTCELL_H(NM,ICC_INT,1,0._EB)
         ENDIF
      ELSE
         H_INT = HP(IIG,JJG,KKG)
      ENDIF
      ! Get interface location, D_INT, D_GHOST, and A_INT based on face type
      IF (WC%CUT_FACE_INDEX > 0) THEN
         ! Cut-face at boundary
         CF => CUT_FACE(WC%CUT_FACE_INDEX)
         A_INT = SUM(CF%AREA(1:CF%NFACE))  ! Total cut-face area
      ELSE
         ! RC face (regular Cartesian face)
         SELECT CASE(X1AXIS)
         CASE(1); A_INT = DY(JJG) * DZ(KKG)
         CASE(2); A_INT = DX(IIG) * DZ(KKG)
         CASE(3); A_INT = DX(IIG) * DY(JJG)
         END SELECT
      ENDIF
      ! X_FACE location, D_INT and D_GHOST using cut-cell centroids when available
      SELECT CASE(X1AXIS)
      CASE(1)
         IF (IOR > 0) THEN; X_FACE = X(IIG-1); ELSE; X_FACE = X(IIG); ENDIF
         IF (ICC_INT > 0) THEN; D_INT = ABS(CUT_CELL(ICC_INT)%XYZCEN(IAXIS,1) - X_FACE)
         ELSE;                  D_INT = ABS(XC(IIG) - X_FACE)
         ENDIF
         IF (ICC_GHOST > 0) THEN; D_GHOST = ABS(CUT_CELL(ICC_GHOST)%XYZCEN(IAXIS,1) - X_FACE)
         ELSE;                    D_GHOST = ABS(XC(II) - X_FACE)
         ENDIF
      CASE(2)
         IF (IOR > 0) THEN; X_FACE = Y(JJG-1); ELSE; X_FACE = Y(JJG); ENDIF
         IF (ICC_INT > 0) THEN; D_INT = ABS(CUT_CELL(ICC_INT)%XYZCEN(JAXIS,1) - X_FACE)
         ELSE;                  D_INT = ABS(YC(JJG) - X_FACE)
         ENDIF
         IF (ICC_GHOST > 0) THEN; D_GHOST = ABS(CUT_CELL(ICC_GHOST)%XYZCEN(JAXIS,1) - X_FACE)
         ELSE;                    D_GHOST = ABS(YC(JJ) - X_FACE)
         ENDIF
      CASE(3)
         IF (IOR > 0) THEN; X_FACE = Z(KKG-1); ELSE; X_FACE = Z(KKG); ENDIF
         IF (ICC_INT > 0) THEN; D_INT = ABS(CUT_CELL(ICC_INT)%XYZCEN(KAXIS,1) - X_FACE)
         ELSE;                  D_INT = ABS(ZC(KKG) - X_FACE)
         ENDIF
         IF (ICC_GHOST > 0) THEN; D_GHOST = ABS(CUT_CELL(ICC_GHOST)%XYZCEN(KAXIS,1) - X_FACE)
         ELSE;                    D_GHOST = ABS(ZC(KK) - X_FACE)
         ENDIF
      END SELECT

      ! Flux-matched sum over external cells
      SUM_FLUX = 0._EB
      DO KKO = EWC%KKO_MIN, EWC%KKO_MAX
         DO JJO = EWC%JJO_MIN, EWC%JJO_MAX
            DO IIO = EWC%IIO_MIN, EWC%IIO_MAX
               ICC_EXT = MESHES(NOM)%CCVAR(IIO,JJO,KKO,CC_IDCC)
               IF (PREDICTOR) THEN; H_EXT = OM%H(IIO,JJO,KKO)
               ELSE;                H_EXT = OM%HS(IIO,JJO,KKO)
               ENDIF
               ! Neighbor seam-face index in NOM's own frame (opposite side of cell IIO,JJO,KKO).
               ISHF(IAXIS:KAXIS) = 0; IF(IOR < 0) ISHF(X1AXIS) = -1
               SELECT CASE(X1AXIS)
               CASE(1)
                  A_EXT = MESHES(NOM)%DY(JJO) * MESHES(NOM)%DZ(KKO); XFN = MESHES(NOM)%X(IIO+ISHF(IAXIS))
                  IF (ICC_EXT > 0) THEN; D_EXT = ABS(MESHES(NOM)%CUT_CELL(ICC_EXT)%XYZCEN(IAXIS,1) - XFN)
                  ELSE;                  D_EXT = ABS(MESHES(NOM)%XC(IIO) - XFN)
                  ENDIF
               CASE(2)
                  A_EXT = MESHES(NOM)%DX(IIO) * MESHES(NOM)%DZ(KKO); XFN = MESHES(NOM)%Y(JJO+ISHF(JAXIS))
                  IF (ICC_EXT > 0) THEN; D_EXT = ABS(MESHES(NOM)%CUT_CELL(ICC_EXT)%XYZCEN(JAXIS,1) - XFN)
                  ELSE;                  D_EXT = ABS(MESHES(NOM)%YC(JJO) - XFN)
                  ENDIF
               CASE(3)
                  A_EXT = MESHES(NOM)%DX(IIO) * MESHES(NOM)%DY(JJO); XFN = MESHES(NOM)%Z(KKO+ISHF(KAXIS))
                  IF (ICC_EXT > 0) THEN; D_EXT = ABS(MESHES(NOM)%CUT_CELL(ICC_EXT)%XYZCEN(KAXIS,1) - XFN)
                  ELSE;                  D_EXT = ABS(MESHES(NOM)%ZC(KKO) - XFN)
                  ENDIF
               END SELECT
               ! Refinement seam only: match GET_H_MATRIX_CC sub-face selection (skip solid/no-unknown partners).
               IF (WC%BOUNDARY_TYPE == INTERPOLATED_BOUNDARY) THEN
                  IF (ALLOCATED(OM%MUNKH)) THEN; IF (OM%MUNKH(IIO,JJO,KKO) < 1) CYCLE; ENDIF
                  IF (MESHES(NOM)%FCVAR(IIO+ISHF(IAXIS),JJO+ISHF(JAXIS),KKO+ISHF(KAXIS),CC_FGSC,X1AXIS) == CC_SOLID) CYCLE
               ENDIF
               ICF_EXT = MESHES(NOM)%FCVAR(IIO+ISHF(IAXIS),JJO+ISHF(JAXIS),KKO+ISHF(KAXIS),CC_IDCF,X1AXIS)
               IF (ICF_EXT > 0) A_EXT = SUM(MESHES(NOM)%CUT_FACE(ICF_EXT)%AREA(1:MESHES(NOM)%CUT_FACE(ICF_EXT)%NFACE))
               IF (EWC%AREA_RATIO < 0.99_EB) A_EXT = A_INT
               SUM_FLUX = SUM_FLUX + (H_EXT - H_INT) / (D_EXT + D_INT) * A_EXT
            ENDDO
         ENDDO
      ENDDO

      ! Compute ghost cell value
      H_GHOST = H_INT + (D_INT + D_GHOST) / A_INT * SUM_FLUX

      ! Fill ghost cell. Guard cut pieces get this value through the tail GCELL scatter below.
      HP(II,JJ,KK) = H_GHOST
   ENDDO WALL_CELL_LOOP
ENDIF
CALL CC_FV_SCATTER_H_TO_GHOST_GCELLS(NM,HP)
END SUBROUTINE GET_H_GUARD_CUTCELL

! --------------------- CC_FV_SCATTER_H_TO_GHOST_GCELLS -----------------------------

SUBROUTINE CC_FV_SCATTER_H_TO_GHOST_GCELLS(NM,HP)
! Copy Cartesian / flux-matched H into tail GCELL SoA slots. Does not write 1:N_INT.
! Tail hosts are in 0:IBP1 (same window as ALLOC_CELL_STATE_VARS).
INTEGER, INTENT(IN) :: NM
REAL(EB), INTENT(INOUT), POINTER, DIMENSION(:,:,:) :: HP
INTEGER :: IG,I,J,K
TYPE(CC_FV_TYPE), POINTER :: FV
REAL(EB), POINTER, DIMENSION(:) :: FV_HP

FV => MESHES(NM)%FV
IF (FV%GCELL%N_INT>=FV%GCELL%N) RETURN
IF (PREDICTOR) THEN
   FV_HP => FV%CV%H
ELSE
   FV_HP => FV%CV%HS
ENDIF
DO IG=FV%GCELL%N_INT+1,FV%GCELL%N
   I = FV%GCELL%IJK(IAXIS,IG)
   J = FV%GCELL%IJK(JAXIS,IG)
   K = FV%GCELL%IJK(KAXIS,IG)
   FV_HP(IG) = HP(I,J,K)
ENDDO

END SUBROUTINE CC_FV_SCATTER_H_TO_GHOST_GCELLS


! ------------------------ ADD_LINKEDCELL_D_PBAR_DT ---------------------------------

SUBROUTINE ADD_LINKEDCELL_D_PBAR_DT(I,J,K,PBAR_K,D_PBAR_DT_ZONE,RTRM_CV,DIVG)

! ASSUMES POINT_TO_MESH has been called and CCVAR(I,J,K,CC_UNKZ) > 0.

INTEGER, INTENT(IN)    :: I,J,K
REAL(EB),INTENT(IN)    :: PBAR_K,D_PBAR_DT_ZONE,RTRM_CV
REAL(EB),INTENT(INOUT) :: DIVG

REAL(EB):: P_BAR_CV
P_BAR_CV=PBAR_K-P_0(K)+P_0_CV(CCVAR(I,J,K,CC_UNKZ))

DIVG = DIVG - (1._EB/P_BAR_CV-RTRM_CV)*D_PBAR_DT_ZONE

END SUBROUTINE ADD_LINKEDCELL_D_PBAR_DT

! ----------------------- ADD_CUTCELL_D_PBAR_DT -------------------------------------

SUBROUTINE ADD_CUTCELL_D_PBAR_DT(I,J,K,PBAR_K,D_PBAR_DT_ZONE)

! ASSUMES POINT_TO_MESH has been called and CCVAR(I,J,K,CC_UNKZ) > 0.

INTEGER, INTENT(IN)    :: I,J,K
REAL(EB),INTENT(IN)    :: PBAR_K,D_PBAR_DT_ZONE

INTEGER :: JCC,IG
REAL(EB):: P_BAR_CV,RTRM_CC

CC => CUT_CELL(CCVAR(I,J,K,CC_IDCC))

IF(PREDICTOR) THEN
   DO JCC=1,CC%NCELL
      IG = CC%IG(JCC)
      P_BAR_CV=PBAR_K-P_0(K)+P_0_CV(CC%UNKZ(JCC))
      RTRM_CC = CV%RTRM(IG)
      CV%DS(IG) = CV%DS(IG) - (1._EB/P_BAR_CV-RTRM_CC)*D_PBAR_DT_ZONE
   ENDDO
ELSE
   DO JCC=1,CC%NCELL
      IG = CC%IG(JCC)
      P_BAR_CV=PBAR_K-P_0(K)+P_0_CV(CC%UNKZ(JCC))
      RTRM_CC = CV%RTRM(IG)
      CV%D(IG) = CV%D(IG) - (1._EB/P_BAR_CV-RTRM_CC)*D_PBAR_DT_ZONE
   ENDDO
ENDIF

END SUBROUTINE ADD_CUTCELL_D_PBAR_DT

! ------------------------- ADD_LINKEDCELL_PSUM -------------------------------------

SUBROUTINE ADD_LINKEDCELL_PSUM(I,J,K,VC,PBAR_K,RTRM_CV,PSUM_CV)

! ASSUMES POINT_TO_MESH has been called and CCVAR(I,J,K,CC_UNKZ) > 0.

INTEGER, INTENT(IN)    :: I,J,K
REAL(EB),INTENT(IN)    :: VC,PBAR_K,RTRM_CV
REAL(EB),INTENT(INOUT) :: PSUM_CV

REAL(EB):: P_BAR_CV
P_BAR_CV=PBAR_K-P_0(K)+P_0_CV(CCVAR(I,J,K,CC_UNKZ))
PSUM_CV = PSUM_CV + VC*(1._EB/P_BAR_CV-RTRM_CV)

END SUBROUTINE ADD_LINKEDCELL_PSUM

! ------------------------- ADD_CUTCELL_PSUM ----------------------------------------

SUBROUTINE ADD_CUTCELL_PSUM(I,J,K,PBAR_K,PSUM_CV)

! ASSUMES POINT_TO_MESH has been called and CCVAR(I,J,K,CC_IDCC) > 0.

INTEGER, INTENT(IN)    :: I,J,K
REAL(EB),INTENT(IN)    :: PBAR_K
REAL(EB),INTENT(INOUT) :: PSUM_CV

INTEGER :: JCC
REAL(EB):: P_BAR_CV

CC  =>CUT_CELL(CCVAR(I,J,K,CC_IDCC))
DO JCC=1,CC%NCELL
   P_BAR_CV=PBAR_K-P_0(K)+P_0_CV(CC%UNKZ(JCC))
   PSUM_CV = PSUM_CV + CC%VOLUME(JCC)*(1._EB/P_BAR_CV-CV%RTRM(CC%IG(JCC)))
ENDDO

END SUBROUTINE ADD_CUTCELL_PSUM


! -------------------------- CC_SET_MOMENTUM_FACE_LISTS ------------------------------

SUBROUTINE CC_SET_MOMENTUM_FACE_LISTS(NM)
! Face sets the momentum routines visit every call, fixed once the cut cells and the scalar unknowns are set:
! GRAV_FACE, the regular faces with both cells gas and one of them in a scalar CV, by axis, for the gravity correction
! in CC_VELOCITY_FLUX; INB_ZF, the solid Cartesian faces of the in-boundary cut cells, and INB_SF, those with a solid
! cell behind, by cut face (INB_CF, INB_PTR), for CUTFACE_VELOCITIES; the cut faces by status and position (CF_GAS,
! CF_INB, CF_GSV, CF_PRJ; see MESH_TYPE) for the momentum and projection walks.
INTEGER, INTENT(IN) :: NM
TYPE(MESH_TYPE), POINTER :: M
INTEGER :: I,J,K,AX,SGN,ICF,IPASS,N,NC,NS,NZ,IJK(IAXIS:KAXIS),IJKC(IAXIS:KAXIS),LO(IAXIS:KAXIS),HI(IAXIS:KAXIS)
INTEGER, ALLOCATABLE, DIMENSION(:) :: CFL,PTR
INTEGER, ALLOCATABLE, DIMENSION(:,:) :: SF,ZF
LOGICAL, ALLOCATABLE, DIMENSION(:) :: GSV,PRJ
TYPE(CC_CUTFACE_TYPE), POINTER :: CF
M => MESHES(NM)
! Gravity faces, in the order of the scans they replace: count, then fill.
DO IPASS=1,2
   N = 0
   DO AX=IAXIS,KAXIS
      IF (IPASS==2) M%GRAV_PTR(AX) = N+1
      LO = 1; HI = (/M%IBAR,M%JBAR,M%KBAR/); LO(AX) = 0
      DO K=LO(KAXIS),HI(KAXIS)
         DO J=LO(JAXIS),HI(JAXIS)
            DO I=LO(IAXIS),HI(IAXIS)
               IJK = (/I,J,K/); IJK(AX) = IJK(AX)+1
               IF (M%CCVAR(I,J,K,CC_CGSC)/=CC_GASPHASE .OR. M%CCVAR(IJK(1),IJK(2),IJK(3),CC_CGSC)/=CC_GASPHASE) CYCLE
               IF (M%CCVAR(I,J,K,CC_UNKZ)<=0 .AND. M%CCVAR(IJK(1),IJK(2),IJK(3),CC_UNKZ)<=0) CYCLE
               N = N+1
               IF (IPASS==2) M%GRAV_FACE(:,N) = (/I,J,K/)
            ENDDO
         ENDDO
      ENDDO
   ENDDO
   IF (IPASS==1) ALLOCATE(M%GRAV_FACE(3,N),M%GRAV_PTR(IAXIS:KAXIS+1))
ENDDO
M%GRAV_PTR(KAXIS+1) = N+1
! Solid faces of the in-boundary cut cells, in the order of the tests they replace.
ALLOCATE(CFL(M%N_CUTFACE_MESH),PTR(M%N_CUTFACE_MESH+1),SF(4,6*M%N_CUTFACE_MESH),ZF(4,6*M%N_CUTFACE_MESH))
NC = 0; NS = 0; NZ = 0; PTR(1) = 1
DO ICF=1,M%N_CUTFACE_MESH
   IF (M%CUT_FACE(ICF)%STATUS/=CC_INBOUNDARY) CYCLE
   IJKC = M%CUT_FACE(ICF)%IJK(IAXIS:KAXIS)
   N = NS
   DO AX=IAXIS,KAXIS
      DO SGN=-1,1,2
         IJK = IJKC; IF (SGN<0) IJK(AX) = IJK(AX)-1  ! The face on this side.
         IF (M%FCVAR(IJK(1),IJK(2),IJK(3),CC_FGSC,AX)/=CC_SOLID) CYCLE
         NZ = NZ+1; ZF(:,NZ) = (/IJK,AX/)
         IJK = IJKC; IJK(AX) = IJK(AX)+SGN           ! The cell behind it.
         IF (M%CCVAR(IJK(1),IJK(2),IJK(3),CC_CGSC)/=CC_SOLID) CYCLE
         NS = NS+1; SF(:,NS) = ZF(:,NZ)
      ENDDO
   ENDDO
   IF (NS==N) CYCLE
   NC = NC+1; CFL(NC) = ICF; PTR(NC+1) = NS+1
ENDDO
M%INB_CF = CFL(1:NC); M%INB_PTR = PTR(1:NC+1); M%INB_SF = SF(:,1:NS); M%INB_ZF = ZF(:,1:NZ)
DEALLOCATE(CFL,PTR,SF,ZF)
! Cut faces by status and position, in index order.
NC = M%N_CUTFACE_MESH+M%N_GCCUTFACE_MESH
ALLOCATE(GSV(NC),PRJ(NC))
DO ICF=1,NC
   CF => M%CUT_FACE(ICF)
   GSV(ICF) = .FALSE.; PRJ(ICF) = .FALSE.
   IF (CF%STATUS/=CC_GASPHASE) CYCLE
   IJK = CF%IJK(IAXIS:KAXIS); AX = CF%IJK(KAXIS+1)
   GSV(ICF) = ALL(IJK>=0) .AND. ALL(IJK<=(/M%IBP1,M%JBP1,M%KBP1/))
   LO = 1; LO(AX) = 0
   IF (ALL(IJK>=LO) .AND. ALL(IJK<=(/M%IBAR,M%JBAR,M%KBAR/))) PRJ(ICF) = M%FCVAR(IJK(1),IJK(2),IJK(3),CC_IDCF,AX)==ICF
ENDDO
M%CF_GAS = PACK((/(ICF,ICF=1,M%N_CUTFACE_MESH)/),(/(M%CUT_FACE(ICF)%STATUS==CC_GASPHASE,ICF=1,M%N_CUTFACE_MESH)/))
M%CF_INB = PACK((/(ICF,ICF=1,M%N_CUTFACE_MESH)/),(/(M%CUT_FACE(ICF)%STATUS==CC_INBOUNDARY,ICF=1,M%N_CUTFACE_MESH)/))
M%CF_GSV = PACK((/(ICF,ICF=1,NC)/),GSV); M%CF_GSV_G = COUNT(GSV(1:M%N_CUTFACE_MESH))+1
M%CF_PRJ = PACK((/(ICF,ICF=1,NC)/),PRJ)
END SUBROUTINE CC_SET_MOMENTUM_FACE_LISTS


! ------------------------------ CC_SET_CFL_ROWS ------------------------------------

SUBROUTINE CC_SET_CFL_ROWS
! Rows of the linked-cell CFL check (CHECK_CFLVN_LINKED_CELLS), set once. Per mesh: the scalar CV rows its members
! touch, as slots in global row order (MAXLOC keeps the first of equal rows, as over the global rows); the members in
! the order of the loops they replace; the cross-mesh rows (members on more than one mesh), each with its owner mesh
! (FV%CV%GCELL_TO_CV_NM). A row held here and owned on another mesh sends its partial sums to the owner each step
! (FINALIZE_FV_L2_CFLVN_ROWS): the owner's entry is found here on this rank, else for each record it will receive.
INTEGER :: NM,I,J,K,ICC,JCC,IG,IROW,IPASS,NREG,NCUT,N,L,S,O,NS,NR
INTEGER, ALLOCATABLE :: ORD(:),SLOT(:),OWN(:),NSORT(:),DEST(:)
REAL(EB), ALLOCATABLE :: R(:,:),SB(:,:),RB(:,:)
TYPE(MESH_TYPE), POINTER :: M

ALLOCATE(NSORT(LOWER_MESH_INDEX:UPPER_MESH_INDEX))
NS = 0
DO NM=LOWER_MESH_INDEX,UPPER_MESH_INDEX
   M => MESHES(NM)
   ! Members: regular cells K-J-I, then cut cells; the global row in the last entry until the slots are known.
   DO IPASS=1,2
      NREG = 0
      DO K=1,M%KBAR
         DO J=1,M%JBAR
            DO I=1,M%IBAR
               IROW = CFL_ROW(M%CCVAR(I,J,K,CC_UNKZ)); IF (IROW<1) CYCLE
               NREG = NREG+1
               IF (IPASS==2) M%CFL_REG(:,NREG) = (/I,J,K,IROW/)
            ENDDO
         ENDDO
      ENDDO
      NCUT = 0
      DO ICC=1,M%N_CUTCELL_MESH
         DO JCC=1,M%CUT_CELL(ICC)%NCELL
            IROW = CFL_ROW(M%CUT_CELL(ICC)%UNKZ(JCC)); IF (IROW<1) CYCLE
            NCUT = NCUT+1
            IF (IPASS==2) M%CFL_CUT(:,NCUT) = (/ICC,JCC,IROW/)
         ENDDO
      ENDDO
      IF (IPASS==1) ALLOCATE(M%CFL_REG(4,NREG),M%CFL_CUT(3,NCUT))
   ENDDO
   ! Slots: the distinct rows, increasing.
   N = NREG+NCUT
   ALLOCATE(R(1,MAX(1,N)),SLOT(MAX(1,N)),M%CFL_SROW(MAX(1,N)))
   R(1,1:NREG) = REAL(M%CFL_REG(4,1:NREG),EB)
   R(1,NREG+1:N) = REAL(M%CFL_CUT(3,1:NCUT),EB)
   CALL KEY_SORT(R,1,N,ORD)
   S = 0
   DO L=1,N
      IROW = NINT(R(1,ORD(L)))
      IF (S==0) THEN
         S = 1; M%CFL_SROW(1) = IROW
      ELSEIF (IROW/=M%CFL_SROW(S)) THEN
         S = S+1; M%CFL_SROW(S) = IROW
      ENDIF
      SLOT(ORD(L)) = S
   ENDDO
   M%CFL_REG(4,1:NREG) = SLOT(1:NREG)
   M%CFL_CUT(3,1:NCUT) = SLOT(NREG+1:N)
   M%CFL_SROW = M%CFL_SROW(1:S)
   M%CFL_NSLOT = S; NSORT(NM) = S
   ! Owner of each slot: a row whose interior GCELL belongs to a CV of another mesh is held here, sent to that mesh.
   ALLOCATE(OWN(MAX(1,S))); OWN = NM
   DO IG=1,M%FV%GCELL%N_INT
      O = M%FV%CV%GCELL_TO_CV_NM(IG); IF (O<1 .OR. O==NM) CYCLE
      IF (M%FV%GCELL%CELL_TYPE(IG)==CC_GCELL_CUT) THEN
         IROW = CFL_ROW(M%CUT_CELL(M%FV%GCELL%ICC(IG))%UNKZ(M%FV%GCELL%JCC(IG)))
      ELSE
         IROW = CFL_ROW(M%CCVAR(M%FV%GCELL%IJK(IAXIS,IG),M%FV%GCELL%IJK(JAXIS,IG),M%FV%GCELL%IJK(KAXIS,IG),CC_UNKZ))
      ENDIF
      S = FIND_SLOT(NM,IROW); IF (S>0) OWN(S) = O
   ENDDO
   M%CFL_XSLOT = PACK((/(S,S=1,M%CFL_NSLOT)/),OWN(1:M%CFL_NSLOT)/=NM)
   M%CFL_XOWN = PACK(OWN(1:M%CFL_NSLOT),OWN(1:M%CFL_NSLOT)/=NM)
   ALLOCATE(M%CFL_XMAP(SIZE(M%CFL_XSLOT))); M%CFL_XMAP = 0
   NS = NS+COUNT(PROCESS(M%CFL_XOWN)/=MY_RANK)
   DEALLOCATE(R,SLOT,OWN,ORD)
ENDDO
! Each held row: the owner's entry, directly on this rank, else for each record the exchange will deliver there.
ALLOCATE(SB(2,MAX(1,NS)),DEST(MAX(1,NS)))
CFL_NREMOTE = NS
NS = 0
DO NM=LOWER_MESH_INDEX,UPPER_MESH_INDEX
   M => MESHES(NM)
   DO L=1,SIZE(M%CFL_XOWN)
      O = M%CFL_XOWN(L)
      IF (O==NM) CYCLE
      IROW = M%CFL_SROW(M%CFL_XSLOT(L))
      IF (PROCESS(O)==MY_RANK) THEN
         M%CFL_XMAP(L) = OWNED_ENTRY(O,IROW)
      ELSE
         NS = NS+1; SB(:,NS) = (/REAL(IROW,EB),REAL(O,EB)/); DEST(NS) = PROCESS(O)
      ENDIF
   ENDDO
ENDDO
CALL CC_GRID_SEAM_EXCHANGE(2,NS,SB,DEST,NR,RB)
ALLOCATE(CFL_RMAP(2,MAX(1,NR)))
DO L=1,NR
   O = NINT(RB(2,L))
   CFL_RMAP(:,L) = (/O,OWNED_ENTRY(O,NINT(RB(1,L)))/)
ENDDO
DO NM=LOWER_MESH_INDEX,UPPER_MESH_INDEX
   ALLOCATE(MESHES(NM)%CFL_XQ(4,SIZE(MESHES(NM)%CFL_XSLOT))); MESHES(NM)%CFL_XQ = 0._EB
   DEALLOCATE(MESHES(NM)%CFL_SROW)
ENDDO

CONTAINS

INTEGER FUNCTION CFL_ROW(IUNK)
! Storage row of scalar unknown IUNK, 0 when it is not a row of the CFL check.
INTEGER, INTENT(IN) :: IUNK
CFL_ROW = 0
IF (IUNK<1) RETURN
CFL_ROW = IUNK
IF (CFL_ROW>NUNKZ_TOTAL) CFL_ROW = 0
END FUNCTION CFL_ROW

INTEGER FUNCTION FIND_SLOT(NM,IROW)
! Slot of global row IROW on mesh NM, 0 if none: bisection over the member slots, then the slots added for owners.
INTEGER, INTENT(IN) :: NM,IROW
INTEGER :: LO,HI,MID
FIND_SLOT = 0
LO = 1; HI = NSORT(NM)
DO WHILE (LO<=HI)
   MID = (LO+HI)/2
   IF (MESHES(NM)%CFL_SROW(MID)==IROW) THEN
      FIND_SLOT = MID; RETURN
   ELSEIF (MESHES(NM)%CFL_SROW(MID)<IROW) THEN
      LO = MID+1
   ELSE
      HI = MID-1
   ENDIF
ENDDO
DO MID=NSORT(NM)+1,MESHES(NM)%CFL_NSLOT
   IF (MESHES(NM)%CFL_SROW(MID)==IROW) FIND_SLOT = MID
ENDDO
END FUNCTION FIND_SLOT

INTEGER FUNCTION OWNED_ENTRY(NM,IROW)
! Cross-row entry of row IROW on its owner mesh NM, added (with a slot, if no member is here) the first time.
INTEGER, INTENT(IN) :: NM,IROW
INTEGER :: SL
TYPE(MESH_TYPE), POINTER :: MO
MO => MESHES(NM)
SL = FIND_SLOT(NM,IROW)
IF (SL<1) THEN
   MO%CFL_SROW = (/MO%CFL_SROW,IROW/)
   MO%CFL_NSLOT = MO%CFL_NSLOT+1
   SL = MO%CFL_NSLOT
ENDIF
DO OWNED_ENTRY=1,SIZE(MO%CFL_XSLOT)
   IF (MO%CFL_XSLOT(OWNED_ENTRY)==SL) RETURN
ENDDO
MO%CFL_XSLOT = (/MO%CFL_XSLOT,SL/)
MO%CFL_XOWN = (/MO%CFL_XOWN,NM/)
MO%CFL_XMAP = (/MO%CFL_XMAP,0/)
OWNED_ENTRY = SIZE(MO%CFL_XSLOT)
END FUNCTION OWNED_ENTRY

END SUBROUTINE CC_SET_CFL_ROWS


! ----------------------------- CC_SET_THERMO_ROWS ----------------------------------

SUBROUTINE CC_SET_THERMO_ROWS
! Rows of the L2 thermodynamic reduce (FINALIZE_FV_L2_THERMODYNAMIC_ROWS), set once for this process. Slots are the
! scalar CV rows its meshes touch (members, owned CVs, both sides of each FACE row) in global row order, so the face
! integrals add in the order they did into the global rows. Per mesh: the member and owned-CV lists and the side slots
! of each FACE row. A row touched here and owned on another process (its mesh by row range, UNKZ_IND) sends its partial
! sums to the owner's process, which returns the finished row; the two exchanges here fix the order of every later one.
INTEGER :: NM,I,J,K,ICC,JCC,ICV,IF_,IUNK,IPASS,N,L,S,NSORT,NT,NH,NR,NB,P
INTEGER, ALLOCATABLE :: ORD(:),SROW(:),TMP(:)
REAL(EB), ALLOCATABLE :: R(:,:),SB(:,:),RB(:,:)
TYPE(MESH_TYPE), POINTER :: M
TYPE(CC_FV_TYPE), POINTER :: FV

! Lists in the order of the loops they replace, with global rows for now.
NT = 0
DO NM=LOWER_MESH_INDEX,UPPER_MESH_INDEX
   M => MESHES(NM); FV => M%FV
   DO IPASS=1,2
      N = 0
      DO K=1,M%KBAR
         DO J=1,M%JBAR
            DO I=1,M%IBAR
               IUNK = M%CCVAR(I,J,K,CC_UNKZ); IF (IUNK<1) CYCLE
               N = N+1
               IF (IPASS==2) M%TH_REG(:,N) = (/I,J,K,IUNK/)
            ENDDO
         ENDDO
      ENDDO
      IF (IPASS==1) ALLOCATE(M%TH_REG(4,N))
   ENDDO
   ALLOCATE(M%TH_CPTR(M%N_CUTCELL_MESH+1))
   DO IPASS=1,2
      N = 0
      DO ICC=1,M%N_CUTCELL_MESH
         M%TH_CPTR(ICC) = N+1
         DO JCC=1,M%CUT_CELL(ICC)%NCELL
            IUNK = M%CUT_CELL(ICC)%UNKZ(JCC); IF (IUNK<1) CYCLE
            N = N+1
            IF (IPASS==2) M%TH_CUT(:,N) = (/JCC,IUNK/)
         ENDDO
      ENDDO
      M%TH_CPTR(M%N_CUTCELL_MESH+1) = N+1
      IF (IPASS==1) ALLOCATE(M%TH_CUT(2,N))
   ENDDO
   DO IPASS=1,2
      N = 0
      DO ICV=1,FV%CV%N
         IF (FV%CV%N_MEMBER(ICV)<1 .OR. FV%CV%OWNER_NM(ICV)/=NM) CYCLE
         IUNK=FV%CV%UNKZ(ICV); IF (IUNK<1) CYCLE
         N = N+1
         IF (IPASS==2) M%TH_OCV(:,N) = (/ICV,IUNK/)
      ENDDO
      IF (IPASS==1) ALLOCATE(M%TH_OCV(2,N))
   ENDDO
   DO IPASS=1,2
      N = 0
      DO ICC=1,M%N_CUTCELL_MESH
         DO JCC=1,M%CUT_CELL(ICC)%NCELL
            IF (M%CUT_CELL(ICC)%IG(JCC)<1) CYCLE
            N = N+1
            IF (IPASS==2) M%TH_PIECE(:,N) = (/ICC,JCC/)
         ENDDO
      ENDDO
      IF (IPASS==1) ALLOCATE(M%TH_PIECE(2,N))
   ENDDO
   ALLOCATE(M%TH_FSLOT(2,FV%FACE%N_INT)); M%TH_FSLOT = 0
   DO IF_=1,FV%FACE%N_INT
      IUNK = FV%FACE%UNKZ_OWN(IF_)
      IF (IUNK>0) M%TH_FSLOT(1,IF_) = IUNK
      IF (FV%FACE%NBR_CV_NM(IF_)<1 .OR. FV%FACE%NBR_CV(IF_)<1) CYCLE
      IUNK = FV%FACE%UNKZ_NBR(IF_)
      IF (IUNK>0) M%TH_FSLOT(2,IF_) = IUNK
   ENDDO
   NT = NT+SIZE(M%TH_REG,2)+SIZE(M%TH_CUT,2)+SIZE(M%TH_OCV,2)+COUNT(M%TH_FSLOT>0)
ENDDO
! Every row once, increasing.
ALLOCATE(R(1,MAX(1,NT)))
NT = 0
DO NM=LOWER_MESH_INDEX,UPPER_MESH_INDEX
   M => MESHES(NM)
   CALL ADD_ROWS(M%TH_REG(4,:)); CALL ADD_ROWS(M%TH_CUT(2,:)); CALL ADD_ROWS(M%TH_OCV(2,:))
   CALL ADD_ROWS(PACK(M%TH_FSLOT,M%TH_FSLOT>0))
ENDDO
CALL KEY_SORT(R,1,NT,ORD)
ALLOCATE(SROW(MAX(1,NT)))
S = 0
DO L=1,NT
   IUNK = NINT(R(1,ORD(L)))
   IF (S>0) THEN
      IF (SROW(S)==IUNK) CYCLE
   ENDIF
   S = S+1; SROW(S) = IUNK
ENDDO
NSORT = S
TH_SROW = SROW(1:NSORT)
DO NM=LOWER_MESH_INDEX,UPPER_MESH_INDEX
   M => MESHES(NM)
   DO L=1,SIZE(M%TH_REG,2)
      M%TH_REG(4,L) = SLOT(M%TH_REG(4,L))
   ENDDO
   DO L=1,SIZE(M%TH_CUT,2)
      M%TH_CUT(2,L) = SLOT(M%TH_CUT(2,L))
   ENDDO
   DO L=1,SIZE(M%TH_OCV,2)
      M%TH_OCV(2,L) = SLOT(M%TH_OCV(2,L))
   ENDDO
   DO IF_=1,SIZE(M%TH_FSLOT,2)
      IF (M%TH_FSLOT(1,IF_)>0) M%TH_FSLOT(1,IF_) = SLOT(M%TH_FSLOT(1,IF_))
      IF (M%TH_FSLOT(2,IF_)>0) M%TH_FSLOT(2,IF_) = SLOT(M%TH_FSLOT(2,IF_))
   ENDDO
ENDDO
! Rows owned on another process: (row, slot here, this process) to the owner's process; it finds or adds its slot
! and tells each sender, in the order it received them, which of the sender's slots its replies fill.
ALLOCATE(TH_SSLOT(NSORT),TH_SDEST(NSORT),SB(3,MAX(1,NSORT)))
NH = 0
DO L=1,NSORT
   P = PROCESS(ROW_MESH(SROW(L))); IF (P==MY_RANK) CYCLE
   NH = NH+1
   TH_SSLOT(NH) = L; TH_SDEST(NH) = P
   SB(:,NH) = (/REAL(SROW(L),EB),REAL(L,EB),REAL(MY_RANK,EB)/)
ENDDO
TMP = TH_SSLOT(1:NH); CALL MOVE_ALLOC(TMP,TH_SSLOT)
TMP = TH_SDEST(1:NH); CALL MOVE_ALLOC(TMP,TH_SDEST)
CALL CC_GRID_SEAM_EXCHANGE(3,NH,SB,TH_SDEST,NR,RB)
ALLOCATE(TMP(S+NR)); TMP(1:S) = SROW(1:S); CALL MOVE_ALLOC(TMP,SROW)
ALLOCATE(TH_RSLOT(NR),TH_RDEST(NR))
DO L=1,NR
   IUNK = NINT(RB(1,L))
   TH_RSLOT(L) = SLOT(IUNK)
   IF (TH_RSLOT(L)<1) THEN
      S = S+1; SROW(S) = IUNK; TH_RSLOT(L) = S
   ENDIF
   TH_RDEST(L) = NINT(RB(3,L))
ENDDO
DEALLOCATE(SB); ALLOCATE(SB(1,MAX(1,NR)))
SB(1,1:NR) = RB(2,1:NR)
CALL CC_GRID_SEAM_EXCHANGE(1,NR,SB,TH_RDEST,NB,RB)
ALLOCATE(TH_BSLOT(NB))
TH_BSLOT = NINT(RB(1,1:NB))
TH_NSLOT = S
ALLOCATE(TH_OSLOT(NUNKZ_LOCAL))
DO L=1,NUNKZ_LOCAL
   TH_OSLOT(L) = SLOT(UNKZ_IND(NM_START)+L)
ENDDO
ALLOCATE(TH_DIV(MAX(1,S)),TH_RTRM(MAX(1,S)),TH_VOL(MAX(1,S)),TH_ORTRM(MAX(1,S)), &
         TH_OCOEFF(MAX(1,N_TRACKED_SPECIES),MAX(1,S)),FV_L2_DVOL_FACE(MAX(1,S)), &
         FV_L2_DEL_RHO_D_DEL_Z_FACE(MAX(1,N_TRACKED_SPECIES),MAX(1,S)),FV_L2_FZ_REMOTE(1,MAX(1,S)))
FV_L2_DVOL_FACE = 0._EB; FV_L2_DEL_RHO_D_DEL_Z_FACE = 0._EB

CONTAINS

SUBROUTINE ADD_ROWS(ROWS)
INTEGER, INTENT(IN) :: ROWS(:)
R(1,NT+1:NT+SIZE(ROWS)) = REAL(ROWS,EB)
NT = NT+SIZE(ROWS)
END SUBROUTINE ADD_ROWS

INTEGER FUNCTION SLOT(IROW)
! Slot of global row IROW, 0 if none: the sorted slots, then the slots added for owners.
INTEGER, INTENT(IN) :: IROW
INTEGER :: L
SLOT = TH_ROW_SLOT(IROW)
DO L=NSORT+1,S
   IF (SROW(L)==IROW) SLOT = L
ENDDO
END FUNCTION SLOT

INTEGER FUNCTION ROW_MESH(IROW)
! Mesh whose scalar rows UNKZ_IND(NM)+1:UNKZ_IND(NM)+NUNKZ_TOT(NM) hold global row IROW.
INTEGER, INTENT(IN) :: IROW
INTEGER :: LO,HI,MID
LO = 1; HI = NMESHES
DO WHILE (LO<HI)
   MID = (LO+HI+1)/2
   IF (UNKZ_IND(MID)<IROW) THEN
      LO = MID
   ELSE
      HI = MID-1
   ENDIF
ENDDO
ROW_MESH = LO
END FUNCTION ROW_MESH

END SUBROUTINE CC_SET_THERMO_ROWS


SUBROUTINE CC_SET_CVCHEM_LISTS
! Combustion per CV (CV_KEEP, CV_COMBUSTION in fire.f90). TH_CVM(slot): the row's CV has more than one member; a row
! owned on another process has its master there and a member here. TH_CVMST: the master of each owned one. Per mesh,
! CVC_REG and CVC_CUT: the members held here, the master flagged.
INTEGER :: NM,L,ICC,IG,ICV,N,R
TYPE(MESH_TYPE), POINTER :: M
ALLOCATE(TH_CVM(MAX(1,TH_NSLOT)),TH_CVMST(5,MAX(1,TH_NSLOT))); TH_CVM = .FALSE.; TH_CVMST = 0
TH_CVM(TH_SSLOT) = .TRUE.
DO NM=LOWER_MESH_INDEX,UPPER_MESH_INDEX
   M => MESHES(NM)
   DO L=1,SIZE(M%TH_OCV,2)
      ICV = M%TH_OCV(1,L)
      IF (M%FV%CV%N_MEMBER(ICV)<2) CYCLE
      TH_CVM(M%TH_OCV(2,L)) = .TRUE.
      IG = M%FV%CV%OWNER_GCELL(ICV)
      IF (M%FV%GCELL%CELL_TYPE(IG)==CC_GCELL_CUT) THEN
         TH_CVMST(:,M%TH_OCV(2,L)) = (/NM,1,M%FV%GCELL%ICC(IG),M%FV%GCELL%JCC(IG),0/)
      ELSE
         TH_CVMST(:,M%TH_OCV(2,L)) = (/NM,2,M%FV%GCELL%IJK(IAXIS:KAXIS,IG)/)
      ENDIF
   ENDDO
ENDDO
DO NM=LOWER_MESH_INDEX,UPPER_MESH_INDEX
   M => MESHES(NM)
   ALLOCATE(M%CVC_REG(5,SIZE(M%TH_REG,2)),M%CVC_CUT(4,SIZE(M%TH_CUT,2)))
   N = 0
   DO L=1,SIZE(M%TH_REG,2)
      R = CC_CVCHEM_ROLE(NM,2,M%TH_REG(IAXIS,L),M%TH_REG(JAXIS,L),M%TH_REG(KAXIS,L))
      IF (R==0) CYCLE
      N = N+1; M%CVC_REG(:,N) = (/M%TH_REG(:,L),MERGE(1,0,R>0)/)
   ENDDO
   M%CVC_REG = M%CVC_REG(:,1:N)
   N = 0
   DO ICC=1,M%N_CUTCELL_MESH
      DO L=M%TH_CPTR(ICC),M%TH_CPTR(ICC+1)-1
         R = CC_CVCHEM_ROLE(NM,1,ICC,M%TH_CUT(1,L),0)
         IF (R==0) CYCLE
         N = N+1; M%CVC_CUT(:,N) = (/ICC,M%TH_CUT(1,L),M%TH_CUT(2,L),MERGE(1,0,R>0)/)
      ENDDO
   ENDDO
   M%CVC_CUT = M%CVC_CUT(:,1:N)
ENDDO
END SUBROUTINE CC_SET_CVCHEM_LISTS


INTEGER FUNCTION CC_CVCHEM_ROLE(NM,CTYPE,A,B,C)
! Role of a regular cell (CTYPE 2, I,J,K) or cut piece (CTYPE 1, ICC,JCC,0) of mesh NM in combustion per CV: 0 not in a
! CV with more than one member (or no row), -1 another member of one, the row's slot for its master.
INTEGER, INTENT(IN) :: NM,CTYPE,A,B,C
INTEGER :: IUNK,IS
CC_CVCHEM_ROLE = 0
IF (CTYPE==2) THEN
   IUNK = MESHES(NM)%CCVAR(A,B,C,CC_UNKZ)
ELSE
   IUNK = MESHES(NM)%CUT_CELL(A)%UNKZ(B)
ENDIF
IF (IUNK<1) RETURN
IS = TH_ROW_SLOT(IUNK)
IF (.NOT.TH_CVM(IS)) RETURN
CC_CVCHEM_ROLE = -1
IF (ALL(TH_CVMST(:,IS)==(/NM,CTYPE,A,B,C/))) CC_CVCHEM_ROLE = IS
END FUNCTION CC_CVCHEM_ROLE


SUBROUTINE CC_CVCHEM_TO_OWNER(R)
! Partial sums R(:,slot) of the members held here added into the owner's slot of each row.
REAL(EB), INTENT(INOUT) :: R(:,:)
CALL SCALAR_ROWS_TO_OWNER(R,TH_SSLOT,TH_SDEST,TH_RSLOT)
END SUBROUTINE CC_CVCHEM_TO_OWNER


SUBROUTINE CC_CVCHEM_FROM_OWNER(R)
! The per-row combustion results R(:,slot) of the owner to every process holding a member of the row.
REAL(EB), INTENT(INOUT) :: R(:,:)
CALL SCALAR_ROWS_FROM_OWNER(R,TH_RSLOT,TH_RDEST,TH_BSLOT)
END SUBROUTINE CC_CVCHEM_FROM_OWNER


INTEGER FUNCTION TH_ROW_SLOT(IROW)
! Slot of global scalar row IROW among the rows this process touches (TH_SROW), 0 if none.
INTEGER, INTENT(IN) :: IROW
INTEGER :: LO,HI,MID
TH_ROW_SLOT = 0
LO = 1; HI = SIZE(TH_SROW)
DO WHILE (LO<=HI)
   MID = (LO+HI)/2
   IF (TH_SROW(MID)==IROW) THEN
      TH_ROW_SLOT = MID; RETURN
   ELSEIF (TH_SROW(MID)<IROW) THEN
      LO = MID+1
   ELSE
      HI = MID-1
   ENDIF
ENDDO
END FUNCTION TH_ROW_SLOT


! ------------------------------ CUTFACE_VELOCITIES --------------------------------

SUBROUTINE CUTFACE_VELOCITIES(NM,UU,VV,WW,CUTFACES)

INTEGER, INTENT(IN) :: NM
REAL(EB), POINTER, DIMENSION(:,:,:), INTENT(INOUT) :: UU,VV,WW
LOGICAL, INTENT(IN) :: CUTFACES
TYPE(CC_CUTFACE_TYPE), POINTER :: CF
TYPE(CFACE_TYPE), POINTER :: CFA
TYPE(BOUNDARY_COORD_TYPE), POINTER :: BC
TYPE(BOUNDARY_PROP1_TYPE), POINTER :: B1
INTEGER :: ICF,LCF,ICFA,JCF,I,J,K,X1AXIS,N,L
REAL(EB):: AREA,VELN(3),PREDFCT

CUTFACES_IF : IF (CUTFACES) THEN ! USE CUT_FACE(ICF)%VEL_CF (published from FV%FACE by CC_VELOCITY_CUTFACES)
   DO LCF=1,SIZE(MESHES(NM)%CF_GSV)
      ICF=MESHES(NM)%CF_GSV(LCF); CF => CUT_FACE(ICF)
      I = CF%IJK(IAXIS); J = CF%IJK(JAXIS); K = CF%IJK(KAXIS)
      X1AXIS = CF%IJK(KAXIS+1)
      SELECT CASE(X1AXIS)
      CASE(IAXIS); UU(I,J,K) = CF%VEL_CF
      CASE(JAXIS); VV(I,J,K) = CF%VEL_CF
      CASE(KAXIS); WW(I,J,K) = CF%VEL_CF
      END SELECT
   ENDDO

   PREDFCT = 0._EB; IF(PREDICTOR) PREDFCT = 1._EB
   ! Solid Cartesian underlay for VELOCITY_FLUX uses physical B1 normals (not continuum FACE).
   DO N=1,SIZE(MESHES(NM)%INB_CF)
      CF => CUT_FACE(MESHES(NM)%INB_CF(N))
      ! Area Average velocity for boundary CFACEs:
      AREA = 0._EB; VELN(IAXIS:KAXIS) = 0._EB
      DO JCF=1,CF%NFACE
         ICFA=CF%CFACE_INDEX(JCF); IF(ICFA<1) CYCLE
         CFA => CFACE(ICFA)
         BC => BOUNDARY_COORD(CFA%BC_INDEX)
         B1 => BOUNDARY_PROP1(CFA%B1_INDEX)
         AREA = AREA+CFA%AREA
         VELN(IAXIS:KAXIS) = VELN(IAXIS:KAXIS) - &
                             (PREDFCT*B1%U_NORMAL+(1._EB-PREDFCT)*B1%U_NORMAL_S)*CFA%AREA*BC%NVEC(IAXIS:KAXIS)
      ENDDO
      VELN(IAXIS:KAXIS) = VELN(IAXIS:KAXIS)/(AREA+TWENTY_EPSILON_EB)
      ! Distribute into the solid Cartesian faces with a solid cell behind (INB_SF, set once):
      DO L=MESHES(NM)%INB_PTR(N),MESHES(NM)%INB_PTR(N+1)-1
         I = MESHES(NM)%INB_SF(1,L); J = MESHES(NM)%INB_SF(2,L); K = MESHES(NM)%INB_SF(3,L)
         SELECT CASE(MESHES(NM)%INB_SF(4,L))
         CASE(IAXIS); UU(I,J,K) = VELN(IAXIS)
         CASE(JAXIS); VV(I,J,K) = VELN(JAXIS)
         CASE(KAXIS); WW(I,J,K) = VELN(KAXIS)
         END SELECT
      ENDDO
   ENDDO

ELSE CUTFACES_IF ! USE CUT_FACE(ICF)%VEL_CRT
   DO LCF=1,SIZE(MESHES(NM)%CF_GSV)
      ICF=MESHES(NM)%CF_GSV(LCF); CF => CUT_FACE(ICF)
      I = CF%IJK(IAXIS); J = CF%IJK(JAXIS); K = CF%IJK(KAXIS)
      X1AXIS = CF%IJK(KAXIS+1)
      SELECT CASE(X1AXIS)
      CASE(IAXIS); UU(I,J,K) = CF%VEL_CRT
      CASE(JAXIS); VV(I,J,K) = CF%VEL_CRT
      CASE(KAXIS); WW(I,J,K) = CF%VEL_CRT
      END SELECT
   ENDDO

   ! Solid faces of the in-boundary cut cells to zero (INB_ZF, set once):
   DO L=1,SIZE(MESHES(NM)%INB_ZF,2)
      I = MESHES(NM)%INB_ZF(1,L); J = MESHES(NM)%INB_ZF(2,L); K = MESHES(NM)%INB_ZF(3,L)
      SELECT CASE(MESHES(NM)%INB_ZF(4,L))
      CASE(IAXIS); UU(I,J,K) = 0._EB
      CASE(JAXIS); VV(I,J,K) = 0._EB
      CASE(KAXIS); WW(I,J,K) = 0._EB
      END SELECT
   ENDDO

ENDIF CUTFACES_IF
RETURN
END SUBROUTINE CUTFACE_VELOCITIES


! ------------------------------ BEGIN_FV_L2_ROWS -----------------------------------

SUBROUTINE BEGIN_FV_L2_ROWS(MODE)
! Cross-mesh row-reduce open. MODE = CC_FV_L2_THERMO. No-op unless L2.
INTEGER, INTENT(IN) :: MODE
SELECT CASE(MODE)
CASE(CC_FV_L2_THERMO); CALL BEGIN_FV_L2_THERMODYNAMIC_ROWS
END SELECT
END SUBROUTINE BEGIN_FV_L2_ROWS


SUBROUTINE FINALIZE_FV_L2_ROWS(MODE,DT,DT_NEW,T)
! Cross-mesh row-reduce close. Pass DT/DT_NEW/T for CC_FV_L2_CFLVN only.
INTEGER, INTENT(IN) :: MODE
REAL(EB), INTENT(IN), OPTIONAL :: DT,T
REAL(EB), INTENT(INOUT), OPTIONAL :: DT_NEW(:)
SELECT CASE(MODE)
CASE(CC_FV_L2_THERMO)
   CALL FINALIZE_FV_L2_THERMODYNAMIC_ROWS
CASE(CC_FV_L2_CFLVN)
   CALL FINALIZE_FV_L2_CFLVN_ROWS(DT,DT_NEW,T)
END SELECT
END SUBROUTINE FINALIZE_FV_L2_ROWS


! -------------------------- FINALIZE_FV_L2_CFLVN_ROWS -------------------------------

SUBROUTINE FINALIZE_FV_L2_CFLVN_ROWS(DT,DT_NEW,T)
! Cross-mesh rows of the linked-cell CFL check: each held row's partial sums go to its owner mesh (neighbour ranks, in
! the order fixed by CC_SET_CFL_ROWS), and the owner applies the linked-cell DT limit policy to the sums. FDS takes the
! smallest DT_NEW over the meshes.
REAL(EB), INTENT(IN) :: DT,T
REAL(EB), INTENT(INOUT) :: DT_NEW(:)
INTEGER :: NM,L,O,NS,NR
INTEGER, ALLOCATABLE :: DEST(:)
REAL(EB), ALLOCATABLE :: SB(:,:),RB(:,:)
REAL(EB) :: UVW_RATE,VN_RATE,DT_LIMIT
REAL(EB), PARAMETER :: DT_EPS=1.E-10_EB
TYPE(MESH_TYPE), POINTER :: M

IF (.NOT.CC_IBM) RETURN
ALLOCATE(SB(4,MAX(1,CFL_NREMOTE)),DEST(MAX(1,CFL_NREMOTE)))
NS=0
DO NM=LOWER_MESH_INDEX,UPPER_MESH_INDEX
   M=>MESHES(NM)
   DO L=1,SIZE(M%CFL_XOWN)
      O=M%CFL_XOWN(L)
      IF (O==NM) CYCLE
      IF (PROCESS(O)==MY_RANK) THEN
         MESHES(O)%CFL_XQ(:,M%CFL_XMAP(L))=MESHES(O)%CFL_XQ(:,M%CFL_XMAP(L))+M%CFL_XQ(:,L)
      ELSE
         NS=NS+1; SB(:,NS)=M%CFL_XQ(:,L); DEST(NS)=PROCESS(O)
      ENDIF
   ENDDO
ENDDO
CALL CC_GRID_SEAM_EXCHANGE(4,NS,SB,DEST,NR,RB)
DO L=1,NR
   O=CFL_RMAP(1,L)
   MESHES(O)%CFL_XQ(:,CFL_RMAP(2,L))=MESHES(O)%CFL_XQ(:,CFL_RMAP(2,L))+RB(:,L)
ENDDO

UVW_RATE=0._EB; VN_RATE=0._EB
DO NM=LOWER_MESH_INDEX,UPPER_MESH_INDEX
   M=>MESHES(NM)
   DO L=1,SIZE(M%CFL_XOWN)
      IF (M%CFL_XOWN(L)/=NM .OR. M%CFL_XQ(3,L)<=TWO_EPSILON_EB) CYCLE
      UVW_RATE=MAX(UVW_RATE,(M%CFL_XQ(1,L)+M%CFL_XQ(4,L))/M%CFL_XQ(3,L))
      VN_RATE=MAX(VN_RATE,M%CFL_XQ(2,L)/M%CFL_XQ(3,L))
   ENDDO
   M%CFL_XQ=0._EB ! A mesh that skips the check next time adds nothing.
ENDDO
IF (.NOT.LOCK_TIME_STEP) THEN
   IF (DT*UVW_RATE>=CFL_MAX .OR. DT*VN_RATE>=VN_MAX) THEN
      DT_LIMIT=0.9_EB*MIN(CFL_MAX/MAX(UVW_RATE,DT_EPS),VN_MAX/MAX(VN_RATE,DT_EPS))
      DO NM=LOWER_MESH_INDEX,UPPER_MESH_INDEX
         IF (DT_LIMIT>=DT_NEW(NM)) CYCLE
         DT_NEW(NM)=DT_LIMIT
         CHANGE_TIME_STEP_INDEX(NM)=-1
         IF (DT_NEW(NM)<DT_INITIAL*LIMITING_DT_RATIO .AND. T+DT_NEW(NM)<T_END-TWENTY_EPSILON_EB) &
            STOP_STATUS=INSTABILITY_STOP
      ENDDO
   ELSEIF (DT*UVW_RATE>CFL_MIN .OR. DT*VN_RATE>=VN_MIN) THEN
      DO NM=LOWER_MESH_INDEX,UPPER_MESH_INDEX
         IF (CHANGE_TIME_STEP_INDEX(NM)/=1) CYCLE
         DT_NEW(NM)=DT
         CHANGE_TIME_STEP_INDEX(NM)=0
      ENDDO
   ENDIF
ENDIF
END SUBROUTINE FINALIZE_FV_L2_CFLVN_ROWS

! --------------------------- CHECK_CFLVN_LINKED_CELLS --------------------------------

SUBROUTINE CHECK_CFLVN_LINKED_CELLS(NM,DT,UVWMAX,R_DX2,MUTRM)

! This routine assumes POINT_TO_MESH(NM) has been already called, and CFL,ICFL,JCFL,KCFL,VN,I_VN,J_VN,K_VN
! are aveilable.

INTEGER, INTENT(IN) :: NM
REAL(EB),INTENT(IN) :: DT
REAL(EB),INTENT(INOUT) :: UVWMAX,R_DX2,MUTRM

! Local variables:
INTEGER :: I,J,K,ICC,JCC,IROW,IMAX,X1AXIS,ILH,IRC,IFC,IFACE,IFC2,IFACE2,ICFA,LOWHIGH,IROW_BEG,IROW_END,IF_,IG,L
REAL(EB):: MU_TMP,MURDN,AF,VELN,CFLMAX_TMP,VNMAX_TMP,TWOD_FCT,MU_AVG
INTEGER,  ALLOCATABLE, DIMENSION(:,:) :: IJKT
REAL(EB), ALLOCATABLE, DIMENSION(:)   :: UVWA, MUV, MURA, VOL, DIVG
INTEGER, PARAMETER :: VN_DXN_METHOD = 2 ! 1: face-based sum, 2: face-based sum + dx/dy/dz in large CVs.
TYPE(CC_FV_TYPE), POINTER :: FV

IF (NUNKZ_TOTAL<1) RETURN
FV=>MESHES(NM)%FV

! Average velocity components on linked cells, one entry per slot (CC_SET_CFL_ROWS):
IROW_BEG=1
IROW_END=MAX(1,MESHES(NM)%CFL_NSLOT)
ALLOCATE(UVWA(IROW_BEG:IROW_END),MUV(IROW_BEG:IROW_END),MURA(IROW_BEG:IROW_END), &
         IJKT(IAXIS:KAXIS,IROW_BEG:IROW_END),VOL(IROW_BEG:IROW_END),DIVG(IROW_BEG:IROW_END))
UVWA(:)       = 0._EB
MUV(:)        = 0._EB
MURA(:)       = 0._EB
IJKT(:,:)     = 0
VOL(:)        = 0._EB
DIVG(:)       = 0._EB

TWOD_FCT = 1._EB; IF(TWO_D) TWOD_FCT = 0._EB
MU_TMP   = 0._EB
! First Regular cells that have an UNKZ index (CFL_REG, set once):
DO L=1,SIZE(MESHES(NM)%CFL_REG,2)
   I = MESHES(NM)%CFL_REG(1,L); J = MESHES(NM)%CFL_REG(2,L); K = MESHES(NM)%CFL_REG(3,L); IROW = MESHES(NM)%CFL_REG(4,L)
   IF (CHECK_VN) MU_TMP = MAX(D_Z_MAX(I,J,K),MU(I,J,K)/RHOS(I,J,K))
   ! X axis:
   X1AXIS = IAXIS
   DO ILH=-1,0
      IRC  = FCVAR(I+ILH,J,K,CC_IDRC,X1AXIS)
      MURDN = MU_TMP/DX(I)
      IF (IRC>0) THEN
         IF(FV%FACE%ROLE(RC_FACE(IRC)%FC)==CC_FACE_ROLE_INTERNAL) CYCLE
         MURDN = MU_TMP*GET_FV_FACE_RDN(NM,RC_FACE(IRC)%FC,&
                 1._EB/(RC_FACE(IRC)%XCEN(X1AXIS,HIGH_IND)-RC_FACE(IRC)%XCEN(X1AXIS,LOW_IND)))
      ENDIF
      AF   = DY(J)*DZ(K); VELN = US(I+ILH,J,K)
      UVWA(IROW) = UVWA(IROW) + MAX(0._EB,REAL(2*ILH+1,EB)*VELN*AF) ! MAX(u.n A, 0), only positive values.
      MURA(IROW) = MURA(IROW) + MURDN * AF
   ENDDO
   ! Y axis:
   X1AXIS = JAXIS
   DO ILH=-1,0
      IRC  = FCVAR(I,J+ILH,K,CC_IDRC,X1AXIS)
      MURDN = TWOD_FCT * MU_TMP/DY(J)
      IF (IRC>0) THEN
         IF(FV%FACE%ROLE(RC_FACE(IRC)%FC)==CC_FACE_ROLE_INTERNAL) CYCLE
         MURDN = TWOD_FCT*MU_TMP*GET_FV_FACE_RDN(NM,RC_FACE(IRC)%FC,&
                 1._EB/(RC_FACE(IRC)%XCEN(X1AXIS,HIGH_IND)-RC_FACE(IRC)%XCEN(X1AXIS,LOW_IND)))
      ENDIF
      AF   = DX(I)*DZ(K); VELN = VS(I,J+ILH,K)
      UVWA(IROW) = UVWA(IROW) + MAX(0._EB,REAL(2*ILH+1,EB)*VELN*AF)
      MURA(IROW) = MURA(IROW) + MURDN * AF
   ENDDO
   ! Z axis:
   X1AXIS = KAXIS
   DO ILH=-1,0
      IRC  = FCVAR(I,J,K+ILH,CC_IDRC,X1AXIS)
      MURDN = MU_TMP/DZ(K)
      IF (IRC>0) THEN
         IF(FV%FACE%ROLE(RC_FACE(IRC)%FC)==CC_FACE_ROLE_INTERNAL) CYCLE
         MURDN = MU_TMP*GET_FV_FACE_RDN(NM,RC_FACE(IRC)%FC,&
                 1._EB/(RC_FACE(IRC)%XCEN(X1AXIS,HIGH_IND)-RC_FACE(IRC)%XCEN(X1AXIS,LOW_IND)))
      ENDIF
      AF   = DX(I)*DY(J); VELN = WS(I,J,K+ILH)
      UVWA(IROW) = UVWA(IROW) + MAX(0._EB,REAL(2*ILH+1,EB)*VELN*AF)
      MURA(IROW) = MURA(IROW) + MURDN * AF
   ENDDO
   ! Divergence:
   MUV(IROW)  = MUV(IROW)  + MU_TMP * (DX(I)*DY(J)*DZ(K))
   DIVG(IROW) = DIVG(IROW) + ABS(DS(I,J,K)) * (DX(I)*DY(J)*DZ(K))
   VOL(IROW)  = VOL(IROW)  + (DX(I)*DY(J)*DZ(K))
   IJKT(IAXIS:KAXIS,IROW) = (/ I, J, K /)
ENDDO
! Then add Cut-cell contributions:
CUTCELL_DO : DO L=1,SIZE(MESHES(NM)%CFL_CUT,2)
   ICC = MESHES(NM)%CFL_CUT(1,L); JCC = MESHES(NM)%CFL_CUT(2,L); IROW = MESHES(NM)%CFL_CUT(3,L)
   I = CUT_CELL(ICC)%IJK(IAXIS)
   J = CUT_CELL(ICC)%IJK(JAXIS)
   K = CUT_CELL(ICC)%IJK(KAXIS)
   IF (CELL(CELL_INDEX(I,J,K))%SOLID) CYCLE
   IF (CHECK_VN) MU_TMP = MAX(D_Z_MAX(I,J,K),MU(I,J,K)/RHOS(I,J,K))
   IFC_LOOP : DO IFC=1,CUT_CELL(ICC)%CCELEM(1,JCC)
      IFACE = CUT_CELL(ICC)%CCELEM(IFC+1,JCC)
      SELECT CASE(CUT_CELL(ICC)%FACE_LIST(1,IFACE))
      CASE(CC_FTYPE_RCGAS) ! REGULAR GASPHASE
         LOWHIGH = CUT_CELL(ICC)%FACE_LIST(2,IFACE)
         X1AXIS  = CUT_CELL(ICC)%FACE_LIST(3,IFACE)
         ILH     = LOWHIGH - 1
         SELECT CASE(X1AXIS)
         CASE(IAXIS)
            IRC  = FCVAR(I-1+ILH,J,K,CC_IDRC,X1AXIS)
            MURDN = MU_TMP/DX(I)
            IF (IRC>0) THEN
               IF(FV%FACE%ROLE(RC_FACE(IRC)%FC)==CC_FACE_ROLE_INTERNAL) CYCLE
               MURDN = MU_TMP*GET_FV_FACE_RDN(NM,RC_FACE(IRC)%FC,&
                       1._EB/(RC_FACE(IRC)%XCEN(X1AXIS,HIGH_IND)-RC_FACE(IRC)%XCEN(X1AXIS,LOW_IND)))
            ENDIF
            AF   = DY(J)*DZ(K); VELN = US(I-1+ILH,J,K)
         CASE(JAXIS)
            IRC  = FCVAR(I,J-1+ILH,K,CC_IDRC,X1AXIS)
            MURDN = TWOD_FCT * MU_TMP/DY(J)
            IF (IRC>0) THEN
               IF(FV%FACE%ROLE(RC_FACE(IRC)%FC)==CC_FACE_ROLE_INTERNAL) CYCLE
               MURDN=TWOD_FCT*MU_TMP*GET_FV_FACE_RDN(NM,RC_FACE(IRC)%FC,&
                      1._EB/(RC_FACE(IRC)%XCEN(X1AXIS,HIGH_IND)-RC_FACE(IRC)%XCEN(X1AXIS,LOW_IND)))
            ENDIF
            AF   = DX(I)*DZ(K); VELN = VS(I,J-1+ILH,K)
         CASE(KAXIS)
            IRC  = FCVAR(I,J,K-1+ILH,CC_IDRC,X1AXIS)
            MURDN = MU_TMP/DZ(K)
            IF (IRC>0) THEN
               IF(FV%FACE%ROLE(RC_FACE(IRC)%FC)==CC_FACE_ROLE_INTERNAL) CYCLE
               MURDN = MU_TMP*GET_FV_FACE_RDN(NM,RC_FACE(IRC)%FC,&
                       1._EB/(RC_FACE(IRC)%XCEN(X1AXIS,HIGH_IND)-RC_FACE(IRC)%XCEN(X1AXIS,LOW_IND)))
            ENDIF
            AF   = DX(I)*DY(J); VELN = WS(I,J,K-1+ILH)
         END SELECT
         UVWA(IROW) = UVWA(IROW) + MAX(0._EB,REAL(2*ILH-1,EB)*VELN*AF)
         MURA(IROW) = MURA(IROW) + MURDN * AF
      CASE(CC_FTYPE_CFGAS) ! GASPHASE CUT FACE:
         LOWHIGH = CUT_CELL(ICC)%FACE_LIST(2,IFACE)
         ILH     = LOWHIGH - 1
         IFC2    = CUT_CELL(ICC)%FACE_LIST(4,IFACE)
         IFACE2  = CUT_CELL(ICC)%FACE_LIST(5,IFACE)
         IF(FV%FACE%ROLE(CUT_FACE(IFC2)%FC(IFACE2))==CC_FACE_ROLE_INTERNAL) CYCLE ! Face inside one CV.
         X1AXIS  = CUT_FACE(IFC2)%IJK(KAXIS+1)
         AF      = CUT_FACE(IFC2)%AREA(IFACE2)
         IF_=CUT_FACE(IFC2)%FC(IFACE2)
         MURDN   = MU_TMP*GET_FV_FACE_RDN(NM,IF_,&
                    1._EB/(CUT_FACE(IFC2)%XCENHIGH(X1AXIS,IFACE2)-CUT_FACE(IFC2)%XCENLOW(X1AXIS,IFACE2)))
         VELN=CC_FV_CUTFACE_MOM(NM,IFC2,IFACE2,CC_FV_MOM_VELS)
         UVWA(IROW) = UVWA(IROW) + MAX(0._EB,REAL(2*ILH-1,EB)*VELN*AF)
         IF(.NOT.(TWO_D .AND. X1AXIS==JAXIS)) MURA(IROW) = MURA(IROW) + MURDN * AF
      CASE(CC_FTYPE_CFINB) ! INBOUNDARY CUT FACE: Note here we add U_NORMAL with Transpiration velocity due to
                            ! Poisson solver velocity error.
         IFC2    = CUT_CELL(ICC)%FACE_LIST(4,IFACE)
         IFACE2  = CUT_CELL(ICC)%FACE_LIST(5,IFACE)
         ICFA    = CUT_FACE(IFC2)%CFACE_INDEX(IFACE2)
         AF      = CUT_FACE(IFC2)%AREA(IFACE2)
         VELN=CC_FV_CUTFACE_MOM(NM,IFC2,IFACE2,CC_FV_MOM_VELS)
         MURDN   = MU_TMP * BOUNDARY_PROP1(CFACE(ICFA)%B1_INDEX)%RDN
         ! - to use velocity into gasphase, projected area.
         UVWA(IROW) = UVWA(IROW) + MAX(0._EB,-VELN*AF)
         MURA(IROW) = MURA(IROW) + MURDN * AF
      END SELECT
   ENDDO IFC_LOOP
   ! Divergence:
   MUV(IROW)  = MUV(IROW)  + MU_TMP * CUT_CELL(ICC)%VOLUME(JCC)
   IG = CUT_CELL(ICC)%IG(JCC)
   DIVG(IROW) = DIVG(IROW) + ABS(FV%CV%DS(IG)) * CUT_CELL(ICC)%VOLUME(JCC)
   VOL(IROW)  = VOL(IROW)  + CUT_CELL(ICC)%VOLUME(JCC)
   IJKT(IAXIS:KAXIS,IROW) = (/ I, J, K /) ! These might rewrite the I,J,K of some IROWs.
ENDDO CUTCELL_DO

IF (CHECK_HT) THEN
   DO IFACE=1,N_EXTERNAL_CFACE_CELLS+N_INTWALL_CFACE_CELLS+N_INTERNAL_CFACE_CELLS
      CFA=>CFACE(IFACE)
      IF (CFA%BOUNDARY_TYPE/=SOLID_BOUNDARY) CYCLE
      BC=>BOUNDARY_COORD(CFA%BC_INDEX)
      B1=>BOUNDARY_PROP1(CFA%B1_INDEX)
      VELN=(ABS(B1%Q_CON_F)/B1%RHO_F)**ONTH*2._EB*B1%RDN
      CFLMAX_TMP=DT*VELN
      IF (CFLMAX_TMP>CFL) THEN
         UVWMAX=VELN
         CFL=CFLMAX_TMP
         ICFL=BC%IIG
         JCFL=BC%JJG
         KCFL=BC%KKG
      ENDIF
   ENDDO
ENDIF

! Cross-mesh rows (CFL_XSLOT, set once) keep their partial sums for FINALIZE_FV_L2_CFLVN_ROWS; the linked-cell limit
! below takes the rows with every member on this mesh.
DO L=1,SIZE(MESHES(NM)%CFL_XSLOT)
   IROW=MESHES(NM)%CFL_XSLOT(L)
   MESHES(NM)%CFL_XQ(:,L)=(/UVWA(IROW),MURA(IROW),VOL(IROW),DIVG(IROW)/)
   UVWA(IROW)=0._EB; MURA(IROW)=0._EB; MUV(IROW)=0._EB; DIVG(IROW)=0._EB; VOL(IROW)=0._EB
ENDDO

! Add convective term + divergence:
UVWA = UVWA + DIVG

! Average per linked cells control volume:
DO IROW=IROW_BEG,IROW_END
   IF (VOL(IROW)<=TWO_EPSILON_EB) CYCLE
   UVWA(IROW)=UVWA(IROW)/VOL(IROW)
ENDDO
IMAX=IROW_BEG-1+MAXLOC(UVWA,DIM=1)
CFLMAX_TMP = DT * UVWA(IMAX)
IF(CFLMAX_TMP > CFL) THEN
   UVWMAX = UVWA(IMAX)
   CFL = CFLMAX_TMP
   ICFL=IJKT(IAXIS,IMAX)
   JCFL=IJKT(JAXIS,IMAX)
   KCFL=IJKT(KAXIS,IMAX)
ENDIF

IF (CHECK_VN) THEN
   IF (VN_DXN_METHOD==2) THEN
      DO IROW=IROW_BEG,IROW_END
         IF (VOL(IROW)<=TWO_EPSILON_EB) CYCLE
         I = IJKT(IAXIS,IROW); J = IJKT(JAXIS,IROW); K = IJKT(KAXIS,IROW)
         IF (VOL(IROW) >= DEFAULT_VOLFRAC_LINK*DX(I)*DY(J)*DZ(K)) THEN ! For large linked CVs relax VN criterion.
            MU_AVG = MUV(IROW)/VOL(IROW)
            IF (TWO_D) THEN
               MURA(IROW) = 2._EB*MU_AVG*(1._EB/DX(I)**2 + 1._EB/DZ(K)**2)
            ELSE
               MURA(IROW) = 2._EB*MU_AVG*(1._EB/DX(I)**2 + 1._EB/DY(J)**2 + 1._EB/DZ(K)**2)
            ENDIF
         ELSE
            MURA(IROW) = MURA(IROW)/VOL(IROW)
         ENDIF
      ENDDO
   ELSE
      DO IROW=IROW_BEG,IROW_END
         IF (VOL(IROW)<=TWO_EPSILON_EB) CYCLE
         MURA(IROW)=MURA(IROW)/VOL(IROW)
      ENDDO
   ENDIF
   IMAX=IROW_BEG-1+MAXLOC(MURA,DIM=1)
   VNMAX_TMP = DT * MURA(IMAX)
   IF(VNMAX_TMP > VN) THEN
      R_DX2 = MURA(IMAX)*VOL(IMAX)/(2._EB*MUV(IMAX))
      MUTRM = MUV(IMAX)/VOL(IMAX)
      VN    = VNMAX_TMP
      I_VN=IJKT(IAXIS,IMAX)
      J_VN=IJKT(JAXIS,IMAX)
      K_VN=IJKT(KAXIS,IMAX)
   ENDIF
ENDIF
DEALLOCATE ( UVWA,MUV,MURA,IJKT,VOL,DIVG )
RETURN
END SUBROUTINE CHECK_CFLVN_LINKED_CELLS


! ---------------------- UNSTRUCTURED_POISSON_RESIDUAL_RC ----------------------

SUBROUTINE UNSTRUCTURED_POISSON_RESIDUAL_RC(NM,I,J,K,HP,RHOP,P,RES,DO_SEPARABLE)

! NOTE: Assumes POINT_TO_MESH(NM) has been called.

INTEGER, INTENT(IN) :: NM,I,J,K
REAL(EB),INTENT(OUT):: RES
LOGICAL, INTENT(IN) :: DO_SEPARABLE
REAL(EB), POINTER, INTENT(IN), DIMENSION(:,:,:) :: HP,RHOP,P

! Local Dummy vars:
REAL(EB):: RHSS, LHSS

RES=0._EB; IF(CCVAR(I,J,K,CC_UNKZ)<=0) RETURN

CALL GET_RHSLHS_POISSON_RC(NM,I,J,K,HP,RHOP,P,RHSS,LHSS,DO_SEPARABLE)
RES  = ABS(RHSS-LHSS)

RETURN
END SUBROUTINE UNSTRUCTURED_POISSON_RESIDUAL_RC

! --------------------------- GET_RHSLHS_POISSON_RC ----------------------------

SUBROUTINE GET_RHSLHS_POISSON_RC(NM,I,J,K,HP,RHOP,P,RHSS,LHSS,DO_SEPARABLE)

! NOTE: Assumes POINT_TO_MESH(NM) has been called.

INTEGER, INTENT(IN) :: NM,I,J,K
REAL(EB),INTENT(OUT):: RHSS,LHSS
LOGICAL, INTENT(IN) :: DO_SEPARABLE
REAL(EB), POINTER, INTENT(IN), DIMENSION(:,:,:) :: HP,RHOP,P

! Local Dummy vars:
INTEGER :: X1AXIS,IRC,ILH,FCT,ICC,JCC
REAL(EB):: PRFCT, AF, VOL, DIV_FN_VOL, RDN, H1, H2, P1, RHO1, KR1, P2, RHO2, KR2, RHOF, FBC, CCM1, CCP1, FN_B

VOL = DX(I)*DY(J)*DZ(K)
DIV_FN_VOL = 0._EB; LHSS = 0._EB
DO_SEPARABLE_IF : IF (DO_SEPARABLE) THEN

   ! X axis:
   X1AXIS = IAXIS; AF = DY(J)*DZ(K)
   DO ILH=-1,0
      FCT  = 2*ILH+1
      RDN  = RDXN(I+ILH)
      IRC  = FCVAR(I+ILH,J,K,CC_IDRC,X1AXIS)
      IF (IRC>0) RDN = GET_FV_FACE_RDN(NM,RC_FACE(IRC)%FC,&
      1._EB/(RC_FACE(IRC)%XCEN(X1AXIS,HIGH_IND)-RC_FACE(IRC)%XCEN(X1AXIS,LOW_IND)))
      H1   = HP(I+ILH,J,K); H2 = HP(I+ILH+1,J,K)
      FBC = 1._EB; IF (WALL(CELL(CELL_INDEX(I,J,K))%WALL_INDEX(FCT*X1AXIS))%BOUNDARY_TYPE==SOLID_BOUNDARY) FBC = 0._EB
      DIV_FN_VOL = DIV_FN_VOL + REAL(FCT,EB)* FVX(I+ILH,J,K) * AF
      LHSS       = LHSS       + REAL(FCT,EB)* FBC*(H2-H1)*RDN * AF
   ENDDO
   ! Y axis:
   X1AXIS = JAXIS; AF = DX(I)*DZ(K)
   DO ILH=-1,0
      FCT  = 2*ILH+1
      RDN  = RDYN(J+ILH)
      IRC  = FCVAR(I,J+ILH,K,CC_IDRC,X1AXIS)
      IF (IRC>0) RDN = GET_FV_FACE_RDN(NM,RC_FACE(IRC)%FC,&
      1._EB/(RC_FACE(IRC)%XCEN(X1AXIS,HIGH_IND)-RC_FACE(IRC)%XCEN(X1AXIS,LOW_IND)))
      H1   = HP(I,J+ILH,K); H2 = HP(I,J+ILH+1,K)
      FBC = 1._EB; IF (WALL(CELL(CELL_INDEX(I,J,K))%WALL_INDEX(FCT*X1AXIS))%BOUNDARY_TYPE==SOLID_BOUNDARY) FBC = 0._EB
      DIV_FN_VOL = DIV_FN_VOL + REAL(FCT,EB)* FVY(I,J+ILH,K) * AF
      LHSS       = LHSS       + REAL(FCT,EB)* FBC*(H2-H1)*RDN * AF
   ENDDO
   ! Z axis:
   X1AXIS = KAXIS; AF = DX(I)*DY(J)
   DO ILH=-1,0
      FCT  = 2*ILH+1
      RDN  = RDZN(K+ILH)
      IRC  = FCVAR(I,J,K+ILH,CC_IDRC,X1AXIS)
      IF (IRC>0) RDN = GET_FV_FACE_RDN(NM,RC_FACE(IRC)%FC,&
      1._EB/(RC_FACE(IRC)%XCEN(X1AXIS,HIGH_IND)-RC_FACE(IRC)%XCEN(X1AXIS,LOW_IND)))
      H1   = HP(I,J,K+ILH); H2 = HP(I,J,K+ILH+1)
      FBC = 1._EB; IF (WALL(CELL(CELL_INDEX(I,J,K))%WALL_INDEX(FCT*X1AXIS))%BOUNDARY_TYPE==SOLID_BOUNDARY) FBC = 0._EB
      DIV_FN_VOL = DIV_FN_VOL + REAL(FCT,EB)* FVZ(I,J,K+ILH) * AF
      LHSS       = LHSS       + REAL(FCT,EB)* FBC*(H2-H1)*RDN * AF
   ENDDO

ELSE DO_SEPARABLE_IF

   PRFCT=0._EB; IF(PREDICTOR) PRFCT=1._EB

   ! X axis:
   X1AXIS = IAXIS; AF = DY(J)*DZ(K)
   DO ILH=-1,0
      FCT  = 2*ILH+1; FBC = 1._EB
      RDN  = RDXN(I+ILH); CCM1=0.5_EB; CCP1=0.5_EB

      P1   = P(   I+ILH,J,K); P2   = P(   I+ILH+1,J,K)
      KR1  = KRES(I+ILH,J,K); KR2  = KRES(I+ILH+1,J,K)
      RHO1 = RHOP(I+ILH,J,K); RHO2 = RHOP(I+ILH+1,J,K)

      IF (CC_FV_UNKF_REG(NM,I+ILH,J,K,IAXIS)>0) THEN
         FN_B = F_LINK(CC_FV_UNKF_REG(NM,I+ILH,J,K,IAXIS))
      ELSE
         FN_B = -(P(I+ILH,J,K)*RHOP(I+ILH+1,J,K)+P(I+ILH+1,J,K)*RHOP(I+ILH,J,K))*&
                 (1._EB/RHOP(I+ILH+1,J,K)-1._EB/RHOP(I+ILH,J,K))*RDXN(I+ILH)/(RHOP(I+ILH+1,J,K)+RHOP(I+ILH,J,K))
      ENDIF
      IRC  = FCVAR(I+ILH,J,K,CC_IDRC,X1AXIS)
      IF (IRC>0) THEN
         IF(RC_FACE(IRC)%IWC>0 .AND. &
            ANY(WALL(RC_FACE(IRC)%IWC)%BOUNDARY_TYPE==(/NULL_BOUNDARY,MIRROR_BOUNDARY,SOLID_BOUNDARY/))) THEN
            FN_B = 0._EB
         ELSE
            RDN = GET_FV_FACE_RDN(NM,RC_FACE(IRC)%FC,&
                 1._EB/(RC_FACE(IRC)%XCEN(X1AXIS,HIGH_IND)-RC_FACE(IRC)%XCEN(X1AXIS,LOW_IND)))
            CCM1= RDN*(RC_FACE(IRC)%XCEN(X1AXIS,HIGH_IND)-X(I+ILH))
            CCP1= RDN*(X(I+ILH)-RC_FACE(IRC)%XCEN(X1AXIS,LOW_IND) )
            IF(RC_FACE(IRC)%CELL_LIST(1,LOW_IND)==CC_FTYPE_CFGAS) THEN
               ICC  = RC_FACE(IRC)%CELL_LIST(2,LOW_IND)
               JCC  = RC_FACE(IRC)%CELL_LIST(3,LOW_IND)
               RHO1 = GET_CUTCELL_RHOP(NM,ICC,JCC,PRFCT)
            ENDIF
            IF(RC_FACE(IRC)%CELL_LIST(1,HIGH_IND)==CC_FTYPE_CFGAS) THEN
               ICC  = RC_FACE(IRC)%CELL_LIST(2,HIGH_IND)
               JCC  = RC_FACE(IRC)%CELL_LIST(3,HIGH_IND)
               RHO2 = GET_CUTCELL_RHOP(NM,ICC,JCC,PRFCT)
            ENDIF
            IF(CC_FV_UNKF_RC(NM,IRC)>0) THEN
               FN_B = F_LINK(CC_FV_UNKF_RC(NM,IRC))
            ELSE
               CALL GET_RCFACE_BAROCLINIC_TORQUE(NM,PRFCT,IRC,CCM1,CCP1,FN_B,HP,RHOP)
            ENDIF
         ENDIF
      ENDIF
      RHOF = CCM1*RHO1 + CCP1*RHO2

      IF ( (I+ILH>0 .AND. I+ILH<IBAR) .AND. &
            WALL(CELL(CELL_INDEX(I,J,K))%WALL_INDEX(FCT*X1AXIS))%BOUNDARY_TYPE==SOLID_BOUNDARY) FBC = 0._EB
      DIV_FN_VOL = DIV_FN_VOL + REAL(FCT,EB)* ( FVX(I+ILH,J,K) - FBC*FVX_B(I+ILH,J,K) ) * AF
      !LHSS       = LHSS       + REAL(FCT,EB)* FBC*( 1._EB/RHOF * (P2-P1) + (KR2-KR1) )*RDN * AF
      !LHSS       = LHSS       + REAL(FCT,EB)* FBC*( (P2/RHO2-P1/RHO1+KR2-KR1)*RDN + FVX_B(I+ILH,J,K) ) * AF
      LHSS       = LHSS       + REAL(FCT,EB)* FBC*( (P2/RHO2-P1/RHO1+KR2-KR1)*RDN + FN_B ) * AF
   ENDDO
   ! Y axis:
   X1AXIS = JAXIS; AF = DX(I)*DZ(K)
   DO ILH=-1,0
      FCT  = 2*ILH+1; FBC = 1._EB
      RDN  = RDYN(J+ILH); CCM1=0.5_EB; CCP1=0.5_EB

      P1   = P(   I,J+ILH,K); P2   = P(   I,J+ILH+1,K)
      KR1  = KRES(I,J+ILH,K); KR2  = KRES(I,J+ILH+1,K)
      RHO1 = RHOP(I,J+ILH,K); RHO2 = RHOP(I,J+ILH+1,K)

      IF (CC_FV_UNKF_REG(NM,I,J+ILH,K,JAXIS)>0) THEN
         FN_B = F_LINK(CC_FV_UNKF_REG(NM,I,J+ILH,K,JAXIS))
      ELSE
         FN_B = -(P(I,J+ILH,K)*RHOP(I,J+ILH+1,K)+P(I,J+ILH+1,K)*RHOP(I,J+ILH,K))*&
                 (1._EB/RHOP(I,J+ILH+1,K)-1._EB/RHOP(I,J+ILH,K))*RDYN(J+ILH)/ (RHOP(I,J+ILH+1,K)+RHOP(I,J+ILH,K))
      ENDIF
      IRC  = FCVAR(I,J+ILH,K,CC_IDRC,X1AXIS)
      IF (IRC>0) THEN
         IF(RC_FACE(IRC)%IWC>0 .AND. &
            ANY(WALL(RC_FACE(IRC)%IWC)%BOUNDARY_TYPE==(/NULL_BOUNDARY,MIRROR_BOUNDARY,SOLID_BOUNDARY/))) THEN
            FN_B = 0._EB
         ELSE
            RDN = GET_FV_FACE_RDN(NM,RC_FACE(IRC)%FC,&
                 1._EB/(RC_FACE(IRC)%XCEN(X1AXIS,HIGH_IND)-RC_FACE(IRC)%XCEN(X1AXIS,LOW_IND)))
            CCM1= RDN*(RC_FACE(IRC)%XCEN(X1AXIS,HIGH_IND)-Y(J+ILH))
            CCP1= RDN*(Y(J+ILH)-RC_FACE(IRC)%XCEN(X1AXIS,LOW_IND) )
            IF(RC_FACE(IRC)%CELL_LIST(1,LOW_IND)==CC_FTYPE_CFGAS) THEN
               ICC  = RC_FACE(IRC)%CELL_LIST(2,LOW_IND)
               JCC  = RC_FACE(IRC)%CELL_LIST(3,LOW_IND)
               RHO1 = GET_CUTCELL_RHOP(NM,ICC,JCC,PRFCT)
            ENDIF
            IF(RC_FACE(IRC)%CELL_LIST(1,HIGH_IND)==CC_FTYPE_CFGAS) THEN
               ICC  = RC_FACE(IRC)%CELL_LIST(2,HIGH_IND)
               JCC  = RC_FACE(IRC)%CELL_LIST(3,HIGH_IND)
               RHO2 = GET_CUTCELL_RHOP(NM,ICC,JCC,PRFCT)
            ENDIF
            IF(CC_FV_UNKF_RC(NM,IRC)>0) THEN
               FN_B = F_LINK(CC_FV_UNKF_RC(NM,IRC))
            ELSE
               CALL GET_RCFACE_BAROCLINIC_TORQUE(NM,PRFCT,IRC,CCM1,CCP1,FN_B,HP,RHOP)
            ENDIF
         ENDIF
      ENDIF
      RHOF = CCM1*RHO1 + CCP1*RHO2

      IF ( (J+ILH>0 .AND. J+ILH<JBAR) .AND. &
            WALL(CELL(CELL_INDEX(I,J,K))%WALL_INDEX(FCT*X1AXIS))%BOUNDARY_TYPE==SOLID_BOUNDARY) FBC = 0._EB
      DIV_FN_VOL = DIV_FN_VOL + REAL(FCT,EB)* ( FVY(I,J+ILH,K) - FBC*FVY_B(I,J+ILH,K) ) * AF
      !LHSS       = LHSS       + REAL(FCT,EB)* FBC*( 1._EB/RHOF * (P2-P1) + (KR2-KR1) )*RDN * AF
      !LHSS       = LHSS       + REAL(FCT,EB)* FBC*( (P2/RHO2-P1/RHO1+KR2-KR1)*RDN +FVY_B(I,J+ILH,K) ) * AF
      LHSS       = LHSS       + REAL(FCT,EB)* FBC*( (P2/RHO2-P1/RHO1+KR2-KR1)*RDN + FN_B ) * AF
   ENDDO
   ! Z axis:
   X1AXIS = KAXIS; AF = DX(I)*DY(J)
   DO ILH=-1,0
      FCT  = 2*ILH+1; FBC = 1._EB
      RDN  = RDZN(K+ILH); CCM1=0.5_EB; CCP1=0.5_EB

      P1   = P(   I,J,K+ILH); P2   = P(   I,J,K+ILH+1)
      KR1  = KRES(I,J,K+ILH); KR2  = KRES(I,J,K+ILH+1)
      RHO1 = RHOP(I,J,K+ILH); RHO2 = RHOP(I,J,K+ILH+1)

      IF (CC_FV_UNKF_REG(NM,I,J,K+ILH,KAXIS)>0) THEN
         FN_B = F_LINK(CC_FV_UNKF_REG(NM,I,J,K+ILH,KAXIS))
      ELSE
         FN_B = -(P(I,J,K+ILH)*RHOP(I,J,K+ILH+1)+P(I,J,K+ILH+1)*RHOP(I,J,K+ILH))*&
                 (1._EB/RHOP(I,J,K+ILH+1)-1._EB/RHOP(I,J,K+ILH))*RDZN(K+ILH)/ (RHOP(I,J,K+ILH+1)+RHOP(I,J,K+ILH))
      ENDIF
      IRC  = FCVAR(I,J,K+ILH,CC_IDRC,X1AXIS)
      IF (IRC>0) THEN
         IF(RC_FACE(IRC)%IWC>0 .AND. &
            ANY(WALL(RC_FACE(IRC)%IWC)%BOUNDARY_TYPE==(/NULL_BOUNDARY,MIRROR_BOUNDARY,SOLID_BOUNDARY/))) THEN
            FN_B = 0._EB
         ELSE
            RDN = GET_FV_FACE_RDN(NM,RC_FACE(IRC)%FC,&
                 1._EB/(RC_FACE(IRC)%XCEN(X1AXIS,HIGH_IND)-RC_FACE(IRC)%XCEN(X1AXIS,LOW_IND)))
            CCM1= RDN*(RC_FACE(IRC)%XCEN(X1AXIS,HIGH_IND)-Z(K+ILH))
            CCP1= RDN*(Z(K+ILH)-RC_FACE(IRC)%XCEN(X1AXIS,LOW_IND) )
            IF(RC_FACE(IRC)%CELL_LIST(1,LOW_IND)==CC_FTYPE_CFGAS) THEN
               ICC  = RC_FACE(IRC)%CELL_LIST(2,LOW_IND)
               JCC  = RC_FACE(IRC)%CELL_LIST(3,LOW_IND)
               RHO1 = GET_CUTCELL_RHOP(NM,ICC,JCC,PRFCT)
            ENDIF
            IF(RC_FACE(IRC)%CELL_LIST(1,HIGH_IND)==CC_FTYPE_CFGAS) THEN
               ICC  = RC_FACE(IRC)%CELL_LIST(2,HIGH_IND)
               JCC  = RC_FACE(IRC)%CELL_LIST(3,HIGH_IND)
               RHO2 = GET_CUTCELL_RHOP(NM,ICC,JCC,PRFCT)
            ENDIF
            IF(CC_FV_UNKF_RC(NM,IRC)>0) THEN
               FN_B = F_LINK(CC_FV_UNKF_RC(NM,IRC))
            ELSE
               CALL GET_RCFACE_BAROCLINIC_TORQUE(NM,PRFCT,IRC,CCM1,CCP1,FN_B,HP,RHOP)
            ENDIF
         ENDIF
      ENDIF
      RHOF = CCM1*RHO1 + CCP1*RHO2

      IF ( (K+ILH>1 .AND. K+ILH<KBAR) .AND.  &
            WALL(CELL(CELL_INDEX(I,J,K))%WALL_INDEX(FCT*X1AXIS))%BOUNDARY_TYPE==SOLID_BOUNDARY) FBC = 0._EB
      DIV_FN_VOL = DIV_FN_VOL + REAL(FCT,EB)* ( FVZ(I,J,K+ILH) - FBC*FVZ_B(I,J,K+ILH) ) * AF
      !LHSS       = LHSS       + REAL(FCT,EB)* FBC*( 1._EB/RHOF * (P2-P1) + (KR2-KR1) )*RDN * AF
      !LHSS       = LHSS       + REAL(FCT,EB)* FBC*( (P2/RHO2-P1/RHO1+KR2-KR1)*RDN + FVZ_B(I,J,K+ILH) ) * AF
      LHSS       = LHSS       + REAL(FCT,EB)* FBC*( (P2/RHO2-P1/RHO1+KR2-KR1)*RDN + FN_B ) * AF
   ENDDO

ENDIF DO_SEPARABLE_IF

LHSS = LHSS/VOL
RHSS = -(DDDT(I,J,K)*VOL + DIV_FN_VOL)/VOL ! Normalize to cartesian cell volume.

RETURN
END SUBROUTINE GET_RHSLHS_POISSON_RC


! ------------------------UNSTRUCTURED_POISSON_RESIDUAL ------------------------

SUBROUTINE UNSTRUCTURED_POISSON_RESIDUAL(NM,I,J,K,HP,RHOP,P,RES,DO_SEPARABLE)

! NOTE: Assumes POINT_TO_MESH(NM) has been called.

INTEGER, INTENT(IN) :: NM,I,J,K
REAL(EB),INTENT(OUT):: RES
LOGICAL, INTENT(IN) :: DO_SEPARABLE
REAL(EB), POINTER, INTENT(IN), DIMENSION(:,:,:) :: HP,RHOP,P

! Local Variables:
INTEGER :: ICC,JCC
REAL(EB):: RHSS,LHSS,DIV_FN,DIV_FN_VOL,LHSS_CC,PRFCT,DDDT_INT

PRFCT=0._EB
IF(PREDICTOR) PRFCT=1._EB
RES=0._EB; LHSS=0._EB; DIV_FN_VOL = 0._EB
! CUT_CELL entry:
ICC=CCVAR(I,J,K,CC_IDCC)
DO_SEPARABLE_IF : IF (DO_SEPARABLE) THEN
   DO JCC=1,CUT_CELL(ICC)%NCELL
     ! Here we add div(F) in the cut-cell and DDDT:
     CALL GET_FN_DIVERGENCE_CUTCELL(NM,ICC,JCC,DIV_FN,SUBSTRACT_BAROCLINIC=.FALSE.)
     DIV_FN_VOL = DIV_FN_VOL + DIV_FN*CUT_CELL(ICC)%VOLUME(JCC)

     ! Compute int(Grad H dot n) ds for cut-cell:
     CALL GET_LHS_CUTCELL(NM,PRFCT,ICC,JCC,LHSS_CC,I,J,K,HP,RHOP,P,DO_SEPARABLE=.TRUE.)
     LHSS       = LHSS       + LHSS_CC
   ENDDO
   ! Add to RHSS:
   CALL GET_FV_CV_DDDTVOL(NM,ICC,1,DDDT_INT)
   RHSS = -(DDDT_INT*SUM(CUT_CELL(ICC)%VOLUME(1:CUT_CELL(ICC)%NCELL)) + DIV_FN_VOL)
   RES  = ABS(RHSS-LHSS)
ELSE DO_SEPARABLE_IF
   IF(SUM(CUT_CELL(ICC)%VOLUME(1:CUT_CELL(ICC)%NCELL))/(DX(I)*DY(J)*DZ(K)) < V_THRESH_INSPRES) RETURN
   DO JCC=1,CUT_CELL(ICC)%NCELL
     ! Here we add div(F) in the cut-cell and DDDT:
     CALL GET_FN_DIVERGENCE_CUTCELL(NM,ICC,JCC,DIV_FN,SUBSTRACT_BAROCLINIC=.TRUE.)
     DIV_FN_VOL = DIV_FN_VOL + DIV_FN*CUT_CELL(ICC)%VOLUME(JCC)

     ! Compute (1/rho*Grad(p)-Grad(Kres)):
     CALL GET_LHS_CUTCELL(NM,PRFCT,ICC,JCC,LHSS_CC,I,J,K,HP,RHOP,P,DO_SEPARABLE=.FALSE.)
     LHSS       = LHSS       + LHSS_CC
   ENDDO
   ! Add to RHSS:
   CALL GET_FV_CV_DDDTVOL(NM,ICC,1,DDDT_INT)
   RHSS = -(DDDT_INT*SUM(CUT_CELL(ICC)%VOLUME(1:CUT_CELL(ICC)%NCELL)) + DIV_FN_VOL)
   RES  = ABS(RHSS-LHSS)

ENDIF DO_SEPARABLE_IF

RES  = RES/(DX(I)*DY(J)*DZ(K)) ! Normalize to cartesian cell volume.

! IF (DO_SEPARABLE) THEN
! !IF(I==38 .AND. J==10 .AND. K==2) THEN
! IF(RES>1.E-6_EB) &
! WRITE(LU_ERR,*) 'Cut-cell I,J,K,RES=',I,J,K,RHSS,LHSS,RES,SUM(CUT_CELL(ICC)%VOLUME(1:CUT_CELL(ICC)%NCELL)) !,':',&
! !MESHES(NM)%ZONE_MESH(0)%F_H(CUT_CELL(ICC)%UNKH(1))
! !ENDIF
! ENDIF

RETURN
END SUBROUTINE UNSTRUCTURED_POISSON_RESIDUAL


! --------------------------------- GET_LHS_CUTCELL --------------------------------


SUBROUTINE GET_LHS_CUTCELL(NM,PRFCT,ICC,JCC,LHSS_CC,I,J,K,HP,RHOP,P,DO_SEPARABLE)

! NOTE: Assumes POINT_TO_MESH(NM) has been called.

INTEGER, INTENT(IN) :: NM,ICC,JCC,I,J,K
REAL(EB),INTENT(IN) :: PRFCT
REAL(EB),INTENT(OUT):: LHSS_CC
LOGICAL, INTENT(IN) :: DO_SEPARABLE
REAL(EB), POINTER, INTENT(IN), DIMENSION(:,:,:) :: HP,RHOP,P


! Local Variables:
INTEGER :: IFC,IFACE,X1AXIS,LOWHIGH,ILH,ICFA,IFC2,IFACE2,ICLO,ICHI,JCLO,JCHI,IRC,IF_
REAL(EB):: HC1,HC2,X1,X2,XFC,AF,FN,FCT,P1,P2,KR1,KR2,RHO1,RHO2,RHOF,FN_B,CCM1,CCP1,IDX

LHSS_CC = 0._EB

DO_SEPARABLE_IF : IF (DO_SEPARABLE) THEN

   ! Compute int(Grad H dot n) ds for cut-cell:
   IFC_LOOP_1 : DO IFC=1,CUT_CELL(ICC)%CCELEM(1,JCC)
      IFACE = CUT_CELL(ICC)%CCELEM(IFC+1,JCC)
      AF   = 0._EB
      FN   = 0._EB
      SELECT CASE(CUT_CELL(ICC)%FACE_LIST(1,IFACE))
      CASE(CC_FTYPE_RCGAS) ! REGULAR GASPHASE
         LOWHIGH = CUT_CELL(ICC)%FACE_LIST(2,IFACE)
         X1AXIS  = CUT_CELL(ICC)%FACE_LIST(3,IFACE)
         ILH     =        LOWHIGH - 1
         FCT     = REAL(2*LOWHIGH - 3, EB)
         HC1  = HP(I,J,K); HC2 = HC1
         SELECT CASE(X1AXIS)
         CASE(IAXIS)
            AF   = DY(J)*DZ(K)
            IF(LOWHIGH==HIGH_IND) THEN
               HC1  = GET_CUTCELL_H(NM,ICC,JCC,PRFCT)
               HC2  = HP(I+1,J,K)
               X1   = CUT_CELL(ICC)%XYZCEN(X1AXIS,JCC)
               X2   = XC(I+1); IRC  = FCVAR(I,J,K,CC_IDRC,X1AXIS)
               IF(IRC>0) X2=RC_FACE(IRC)%XCEN(X1AXIS,LOWHIGH)
            ELSE
               HC1  = HP(I-1,J,K)
               HC2  = GET_CUTCELL_H(NM,ICC,JCC,PRFCT)
               X1   = XC(I-1); IRC  = FCVAR(I-1,J,K,CC_IDRC,X1AXIS)
               IF(IRC>0) X1=RC_FACE(IRC)%XCEN(X1AXIS,LOWHIGH)
               X2   = CUT_CELL(ICC)%XYZCEN(X1AXIS,JCC)
            ENDIF
         CASE(JAXIS)
            AF   = DX(I)*DZ(K)
            IF(LOWHIGH==HIGH_IND) THEN
               HC1  = GET_CUTCELL_H(NM,ICC,JCC,PRFCT)
               HC2  = HP(I,J+1,K)
               X1   = CUT_CELL(ICC)%XYZCEN(X1AXIS,JCC)
               X2   = YC(J+1); IRC  = FCVAR(I,J,K,CC_IDRC,X1AXIS)
               IF(IRC>0) X2=RC_FACE(IRC)%XCEN(X1AXIS,LOWHIGH)
            ELSE
               HC1  = HP(I,J-1,K)
               HC2  = GET_CUTCELL_H(NM,ICC,JCC,PRFCT)
               X1   = YC(J-1); IRC  = FCVAR(I,J-1,K,CC_IDRC,X1AXIS)
               IF(IRC>0) X1=RC_FACE(IRC)%XCEN(X1AXIS,LOWHIGH)
               X2   = CUT_CELL(ICC)%XYZCEN(X1AXIS,JCC)
            ENDIF
         CASE(KAXIS)
            AF   = DX(I)*DY(J)
            IF(LOWHIGH==HIGH_IND) THEN
               HC1  = GET_CUTCELL_H(NM,ICC,JCC,PRFCT)
               HC2  = HP(I,J,K+1)
               X1   = CUT_CELL(ICC)%XYZCEN(X1AXIS,JCC)
               X2   = ZC(K+1); IRC  = FCVAR(I,J,K,CC_IDRC,X1AXIS)
               IF(IRC>0) X2=RC_FACE(IRC)%XCEN(X1AXIS,LOWHIGH)
            ELSE
               HC1  = HP(I,J,K-1)
               HC2  = GET_CUTCELL_H(NM,ICC,JCC,PRFCT)
               X1   = ZC(K-1); IRC  = FCVAR(I,J,K-1,CC_IDRC,X1AXIS)
               IF(IRC>0) X1=RC_FACE(IRC)%XCEN(X1AXIS,LOWHIGH)
               X2   = CUT_CELL(ICC)%XYZCEN(X1AXIS,JCC)
            ENDIF
         END SELECT
         IF(IRC>0) THEN
            IF( RC_FACE(IRC)%IWC>0 .AND. &
                ANY(WALL(RC_FACE(IRC)%IWC)%BOUNDARY_TYPE==(/SOLID_BOUNDARY,NULL_BOUNDARY,MIRROR_BOUNDARY/)) ) &
                CYCLE IFC_LOOP_1
            IDX = GET_FV_FACE_RDN(NM,RC_FACE(IRC)%FC,1._EB/(X2-X1))
         ELSE
            IDX = 1._EB/(X2-X1)
         ENDIF
         FN   = FCT*(HC2-HC1)*IDX ! Grad H dot n
      CASE(CC_FTYPE_CFGAS) ! GASPHASE CUT FACE:
         LOWHIGH = CUT_CELL(ICC)%FACE_LIST(2,IFACE)
         FCT     = REAL(2*LOWHIGH - 3, EB)
         IFC2    = CUT_CELL(ICC)%FACE_LIST(4,IFACE)
         IF(CUT_FACE(IFC2)%IWC>0 .AND. &
            ANY(WALL(CUT_FACE(IFC2)%IWC)%BOUNDARY_TYPE==(/SOLID_BOUNDARY,NULL_BOUNDARY,MIRROR_BOUNDARY/))) &
            CYCLE IFC_LOOP_1
         IFACE2  = CUT_CELL(ICC)%FACE_LIST(5,IFACE)
         AF      = CUT_FACE(IFC2)%AREA(IFACE2)
         ! Low side H:
         ICLO = CUT_FACE(IFC2)%CELL_LIST(2,LOW_IND,IFACE2); JCLO = CUT_FACE(IFC2)%CELL_LIST(3,LOW_IND,IFACE2);
         !HC1  = HP(CUT_CELL(ICLO)%IJK(IAXIS),CUT_CELL(ICLO)%IJK(JAXIS),CUT_CELL(ICLO)%IJK(KAXIS))
         HC1  = GET_CUTCELL_H(NM,ICLO,JCLO,PRFCT)
         ! High side H:
         ICHI = CUT_FACE(IFC2)%CELL_LIST(2,HIGH_IND,IFACE2); JCHI = CUT_FACE(IFC2)%CELL_LIST(3,HIGH_IND,IFACE2);
         !HC2  = HP(CUT_CELL(ICHI)%IJK(IAXIS),CUT_CELL(ICHI)%IJK(JAXIS),CUT_CELL(ICHI)%IJK(KAXIS))
         HC2  = GET_CUTCELL_H(NM,ICHI,JCHI,PRFCT)

         X1AXIS = CUT_FACE(IFC2)%IJK(KAXIS+1)
         X1   = CUT_FACE(IFC2)%XCENLOW(X1AXIS,IFACE2)
         X2   = CUT_FACE(IFC2)%XCENHIGH(X1AXIS,IFACE2)
         IF_=CUT_FACE(IFC2)%FC(IFACE2)
         IDX = GET_FV_FACE_RDN(NM,IF_,1._EB/(X2-X1))
         FN   = FCT*(HC2-HC1)*IDX ! Grad H dot n
      CASE(CC_FTYPE_CFINB) ! INBOUNDARY CUT FACE
         FCT     = 1._EB    ! Normal vector defined into the body.
         IFC2    = CUT_CELL(ICC)%FACE_LIST(4,IFACE)
         IFACE2  = CUT_CELL(ICC)%FACE_LIST(5,IFACE)
         ICFA    = CUT_FACE(IFC2)%CFACE_INDEX(IFACE2)
         AF      = CUT_FACE(IFC2)%AREA(IFACE2)
         ! FN      = 0._EB
      END SELECT
      LHSS_CC = LHSS_CC + AF*FN
   ENDDO IFC_LOOP_1

ELSE DO_SEPARABLE_IF

   ! Compute (1/rho*Grad(p)+Grad(Kres)):
   CCM1 = 0.5_EB; CCP1 = 0.5_EB
   IFC_LOOP_2 : DO IFC=1,CUT_CELL(ICC)%CCELEM(1,JCC)
      IFACE = CUT_CELL(ICC)%CCELEM(IFC+1,JCC)
      AF    = 0._EB; FN = 0._EB; FN_B = 0._EB
      SELECT CASE(CUT_CELL(ICC)%FACE_LIST(1,IFACE))
      CASE(CC_FTYPE_RCGAS) ! REGULAR GASPHASE
         LOWHIGH = CUT_CELL(ICC)%FACE_LIST(2,IFACE)
         X1AXIS  = CUT_CELL(ICC)%FACE_LIST(3,IFACE)
         ILH     =        LOWHIGH - 1
         FCT     = REAL(2*LOWHIGH - 3, EB)
         P1   = P(I,J,K); P2 = P1
         KR1  = KRES(I,J,K); KR2 = KR1
         RHO1 = GET_CUTCELL_RHOP(NM,ICC,JCC,PRFCT); RHO2=RHO1
         SELECT CASE(X1AXIS)
         CASE(IAXIS)
            AF   = DY(J)*DZ(K); XFC  = X(I-1+ILH)   ! Face location in face normal direction.
            !FN_B = FVX_B(I-1+ILH,J,K)
            IRC  = FCVAR(I-1+ILH,J,K,CC_IDRC,X1AXIS)
            IF(LOWHIGH==HIGH_IND) THEN
               P2   = P(I+1,J,K); KR2 = KRES(I+1,J,K)
               X1   = CUT_CELL(ICC)%XYZCEN(X1AXIS,JCC)
               X2   = XC(I+1); IF(IRC>0) X2=RC_FACE(IRC)%XCEN(X1AXIS,LOWHIGH)
               RHO2 = RHOP(I+1,J,K)
            ELSE
               P1   = P(I-1,J,K); KR1 = KRES(I-1,J,K)
               X1   = XC(I-1); IF(IRC>0) X1=RC_FACE(IRC)%XCEN(X1AXIS,LOWHIGH)
               X2   = CUT_CELL(ICC)%XYZCEN(X1AXIS,JCC)
               RHO1 = RHOP(I-1,J,K)
            ENDIF
         CASE(JAXIS)
            AF   = DX(I)*DZ(K); XFC  = Y(J-1+ILH)   ! Face location in face normal direction.
            !FN_B = FVY_B(I,J-1+ILH,K)
            IRC  = FCVAR(I,J-1+ILH,K,CC_IDRC,X1AXIS)
            IF(LOWHIGH==HIGH_IND) THEN
               P2   = P(I,J+1,K); KR2 = KRES(I,J+1,K)
               X1   = CUT_CELL(ICC)%XYZCEN(X1AXIS,JCC)
               X2   = YC(J+1); IF(IRC>0) X2=RC_FACE(IRC)%XCEN(X1AXIS,LOWHIGH)
               RHO2 = RHOP(I,J+1,K)
            ELSE
               P1   = P(I,J-1,K); KR1 = KRES(I,J-1,K)
               X1   = YC(J-1); IF(IRC>0) X1=RC_FACE(IRC)%XCEN(X1AXIS,LOWHIGH)
               X2   = CUT_CELL(ICC)%XYZCEN(X1AXIS,JCC)
               RHO1 = RHOP(I,J-1,K)
            ENDIF
         CASE(KAXIS)
            AF   = DX(I)*DY(J); XFC  = Z(K-1+ILH)   ! Face location in face normal direction.
            !FN_B = FVZ_B(I,J,K-1+ILH)
            IRC  = FCVAR(I,J,K-1+ILH,CC_IDRC,X1AXIS)
            IF(LOWHIGH==HIGH_IND) THEN
               P2   = P(I,J,K+1); KR2 = KRES(I,J,K+1)
               X1   = CUT_CELL(ICC)%XYZCEN(X1AXIS,JCC)
               X2   = ZC(K+1); IF(IRC>0) X2=RC_FACE(IRC)%XCEN(X1AXIS,LOWHIGH)
               RHO2 = RHOP(I,J,K+1)
            ELSE
               P1   = P(I,J,K-1); KR1 = KRES(I,J,K-1)
               X1   = ZC(K-1); IF(IRC>0) X1=RC_FACE(IRC)%XCEN(X1AXIS,LOWHIGH)
               X2   = CUT_CELL(ICC)%XYZCEN(X1AXIS,JCC)
               RHO1 = RHOP(I,J,K-1)
            ENDIF
         END SELECT
         IF(IRC>0) THEN
            IF( RC_FACE(IRC)%IWC>0 .AND. &
                ANY(WALL(RC_FACE(IRC)%IWC)%BOUNDARY_TYPE==(/SOLID_BOUNDARY,NULL_BOUNDARY,MIRROR_BOUNDARY/)) ) &
                CYCLE IFC_LOOP_2
         ENDIF
         IF(CC_FV_UNKF_RC(NM,IRC)>0) THEN
            FN_B = F_LINK(CC_FV_UNKF_RC(NM,IRC))
         ELSE
            CALL GET_RCFACE_BAROCLINIC_TORQUE(NM,PRFCT,IRC,CCM1,CCP1,FN_B,HP,RHOP)
         ENDIF
         IDX = GET_FV_FACE_RDN(NM,RC_FACE(IRC)%FC,1._EB/(X2-X1))
         CCM1 = (X2-XFC)*IDX; CCP1 = (XFC-X1)*IDX; RHOF = CCM1*RHO1 + CCP1*RHO2
         FN   = FCT * ( (P2/RHO2-P1/RHO1+KR2-KR1)*IDX + FN_B )  ! (Grad(p/rho)-p*Grad(1/rho)+Grad(Kres))
      CASE(CC_FTYPE_CFGAS) ! GASPHASE CUT FACE:
         LOWHIGH = CUT_CELL(ICC)%FACE_LIST(2,IFACE)
         FCT     = REAL(2*LOWHIGH - 3, EB)
         IFC2    = CUT_CELL(ICC)%FACE_LIST(4,IFACE)
         IF(CUT_FACE(IFC2)%IWC>0 .AND. &
            ANY(WALL(CUT_FACE(IFC2)%IWC)%BOUNDARY_TYPE==(/SOLID_BOUNDARY,NULL_BOUNDARY,MIRROR_BOUNDARY/))) &
            CYCLE IFC_LOOP_2
         IFACE2  = CUT_CELL(ICC)%FACE_LIST(5,IFACE)
         AF      = CUT_FACE(IFC2)%AREA(IFACE2)
         ! Low side H:
         ICLO = CUT_FACE(IFC2)%CELL_LIST(2,LOW_IND,IFACE2); JCLO = CUT_FACE(IFC2)%CELL_LIST(3,LOW_IND,IFACE2);
         P1  = P(CUT_CELL(ICLO)%IJK(IAXIS),CUT_CELL(ICLO)%IJK(JAXIS),CUT_CELL(ICLO)%IJK(KAXIS))
         KR1 = KRES(CUT_CELL(ICLO)%IJK(IAXIS),CUT_CELL(ICLO)%IJK(JAXIS),CUT_CELL(ICLO)%IJK(KAXIS))
         RHO1 = GET_CUTCELL_RHOP(NM,ICLO,JCLO,PRFCT)
         ! High side H:
         ICHI = CUT_FACE(IFC2)%CELL_LIST(2,HIGH_IND,IFACE2); JCHI = CUT_FACE(IFC2)%CELL_LIST(3,HIGH_IND,IFACE2);
         P2  = P(CUT_CELL(ICHI)%IJK(IAXIS),CUT_CELL(ICHI)%IJK(JAXIS),CUT_CELL(ICHI)%IJK(KAXIS))
         KR2 = KRES(CUT_CELL(ICHI)%IJK(IAXIS),CUT_CELL(ICHI)%IJK(JAXIS),CUT_CELL(ICHI)%IJK(KAXIS))
         RHO2 = GET_CUTCELL_RHOP(NM,ICHI,JCHI,PRFCT)

         X1AXIS = CUT_FACE(IFC2)%IJK(KAXIS+1)
         XFC    = CUT_FACE(IFC2)%XYZCEN(X1AXIS,IFACE2)
         X1   = CUT_FACE(IFC2)%XCENLOW( X1AXIS,IFACE2)
         X2   = CUT_FACE(IFC2)%XCENHIGH(X1AXIS,IFACE2)
         IF_=CUT_FACE(IFC2)%FC(IFACE2)
         IDX = GET_FV_FACE_RDN(NM,IF_,1._EB/(X2-X1))
         RHOF = (X2-XFC)*IDX*RHO1 + (XFC-X1)*IDX*RHO2 ! CCM1*RHO1 + CCM2*RHO2
         IF(CC_FV_UNKF_CF(NM,IFC2,IFACE2)>0) FN_B = F_LINK(CC_FV_UNKF_CF(NM,IFC2,IFACE2))
         FN = FCT*( (P2/RHO2-P1/RHO1+KR2-KR1)*IDX + FN_B )
      CASE(CC_FTYPE_CFINB) ! INBOUNDARY CUT FACE
         FCT     = 1._EB    ! Normal vector defined into the body.
         IFC2    = CUT_CELL(ICC)%FACE_LIST(4,IFACE)
         IFACE2  = CUT_CELL(ICC)%FACE_LIST(5,IFACE)
         ICFA    = CUT_FACE(IFC2)%CFACE_INDEX(IFACE2)
         AF      = CUT_FACE(IFC2)%AREA(IFACE2)
         ! FN      = 0._EB
      END SELECT
      LHSS_CC = LHSS_CC + AF*FN
   ENDDO IFC_LOOP_2

ENDIF DO_SEPARABLE_IF

RETURN
END SUBROUTINE GET_LHS_CUTCELL

! --------------------------- CC_BAROCLINIC_CORRECTION --------------------------

SUBROUTINE CC_BAROCLINIC_CORRECTION(T,NM)

! This routine assumes POINT_TO_MESH(NM) has been called.

USE MATH_FUNCTIONS, ONLY: EVALUATE_RAMP

INTEGER, INTENT(IN) :: NM
REAL(EB),INTENT(IN) :: T

! Local variables:
INTEGER :: ICF,LCF,JCF,IF_,I,J,K,X1AXIS,II1,II2,JJ1,JJ2,KK1,KK2
REAL(EB):: PRFCT,WG1,WG2,IDX,AT,FRC_B,T_NOW
LOGICAL :: FLG
REAL(EB), POINTER, DIMENSION(:,:,:) :: HP,RHOP
TYPE(CC_FV_TYPE), POINTER :: FV

T_NOW = CURRENT_TIME()
AT=T
FV=>MESHES(NM)%FV
IF (PREDICTOR) THEN
   PRFCT =  1._EB
   RHOP  => RHO
   HP    => H
ELSE
   PRFCT =  0._EB
   RHOP  => RHOS
   HP    => HS
ENDIF

! 1. Substract FV_B from FV coming from baroclinic:
FVX = FVX - FVX_B
FVY = FVY - FVY_B
FVZ = FVZ - FVZ_B

IF (BAROCLINIC_TERMS_ATTACHED) THEN
    DO LCF=1,SIZE(MESHES(NM)%CF_GAS)
       ICF=MESHES(NM)%CF_GAS(LCF); CF => CUT_FACE(ICF)
       DO JCF=1,CF%NFACE
          IF_=MESHES(NM)%CUT_FACE(ICF)%FC(JCF)
          FV%FACE%FN(IF_)=FV%FACE%FN(IF_)-FV%FACE%FN_B(IF_)
       ENDDO
       CF%FV             = CF%FV - CF%FV_B
    ENDDO
ENDIF

! 2. Get Baroclinic torque terms for internal cut-faces:
WG1 = 0.5_EB; WG2 = 0.5_EB
CF_LOOP : DO LCF=1,SIZE(MESHES(NM)%CF_GAS)
   ICF=MESHES(NM)%CF_GAS(LCF); CF => CUT_FACE(ICF)
   IF (ICF<=MESHES(NM)%N_BBCUTFACE_MESH) THEN
      ! Flags consistent with computation of FN=-DUDT in CC_NO_FLUX, SOLID boundaries keep F_B = 0.
      FLG = EXTERNAL_WALL(CF%IWC)%NOM/=0 .AND. &
            .NOT.( ANY(WALL(CF%IWC)%BOUNDARY_TYPE==(/INTERPOLATED_BOUNDARY,PERIODIC_BOUNDARY/)) )
      IF(FLG .OR. ANY(WALL(CF%IWC)%BOUNDARY_TYPE==(/SOLID_BOUNDARY,NULL_BOUNDARY,MIRROR_BOUNDARY/))) CYCLE CF_LOOP
   ELSEIF(CF%IWC>0) THEN
      IF(ANY(WALL(CF%IWC)%BOUNDARY_TYPE==(/SOLID_BOUNDARY,NULL_BOUNDARY,MIRROR_BOUNDARY/))) CYCLE CF_LOOP
   ENDIF

   I = CF%IJK(IAXIS); J = CF%IJK(JAXIS); K = CF%IJK(KAXIS); X1AXIS = CF%IJK(KAXIS+1)
   II1 = I; JJ1 = J; KK1 = K
   II2 = I; JJ2 = J; KK2 = K
   SELECT CASE(X1AXIS)
   CASE(IAXIS); IDX = RDXN(I); II2 = II2+1; AT = CF%ALPHA_CF * (DY(J)*DZ(K))
   CASE(JAXIS); IDX = RDYN(J); JJ2 = JJ2+1; AT = CF%ALPHA_CF * (DZ(K)*DX(I))
   CASE(KAXIS); IDX = RDZN(K); KK2 = KK2+1; AT = CF%ALPHA_CF * (DX(I)*DY(J))
   END SELECT
   DO JCF=1,CF%NFACE
      IF(CC_FV_UNKF_CF(NM,ICF,JCF)<1) CYCLE
      CALL GET_CUTFACE_BAROCLINIC_TORQUE(NM,PRFCT,CF,JCF,IDX,WG1,WG2,II1,JJ1,KK1,II2,JJ2,KK2,FRC_B,HP)
      IF_=MESHES(NM)%CUT_FACE(ICF)%FC(JCF)
      FV%FACE%FN_B(IF_)=FRC_B
   ENDDO
   CF%FV_B = CC_FV_CUTFACE_MOM_AREA(NM,ICF,CC_FV_MOM_FN_B) / AT
ENDDO CF_LOOP

! 2. Get Baroclinic torque terms for RC-faces:
RC_LOOP : DO ICF=1,MESHES(NM)%CC_NRCFACE_Z
   RCF => RC_FACE(ICF);
   SELECT CASE(RCF%IJK(KAXIS+1))
   CASE(IAXIS); FVX_B(RCF%IJK(IAXIS),RCF%IJK(JAXIS),RCF%IJK(KAXIS)) = 0._EB
   CASE(JAXIS); FVY_B(RCF%IJK(IAXIS),RCF%IJK(JAXIS),RCF%IJK(KAXIS)) = 0._EB
   CASE(KAXIS); FVZ_B(RCF%IJK(IAXIS),RCF%IJK(JAXIS),RCF%IJK(KAXIS)) = 0._EB
   END SELECT
   !IF(CC_FV_UNKF_RC(NM,ICF)<1) CYCLE RC_LOOP
   IF (RCF%IWC>0) THEN
      IF(RCF%IWC<=N_EXTERNAL_WALL_CELLS) THEN
         ! Flags consistent with computation of FN=-DUDT, SOLID boundaries keep F_B = 0.
         FLG = EXTERNAL_WALL(RCF%IWC)%NOM/=0 .AND. &
               .NOT.( ANY(WALL(RCF%IWC)%BOUNDARY_TYPE==(/INTERPOLATED_BOUNDARY,PERIODIC_BOUNDARY/)) )
         IF(FLG .OR. ANY(WALL(RCF%IWC)%BOUNDARY_TYPE==(/SOLID_BOUNDARY,NULL_BOUNDARY,MIRROR_BOUNDARY/))) CYCLE RC_LOOP
      ELSEIF(ANY(WALL(RCF%IWC)%BOUNDARY_TYPE==(/SOLID_BOUNDARY,NULL_BOUNDARY,MIRROR_BOUNDARY/))) THEN; CYCLE RC_LOOP
      ENDIF
   ENDIF
   CALL GET_RCFACE_BAROCLINIC_TORQUE(NM,PRFCT,ICF,WG1,WG2,FRC_B,HP,RHOP)

   ! Mirror into FVX_B, FVY_B, FVZ_B for bulk/unmigrated consumers:
   SELECT CASE(RCF%IJK(KAXIS+1))
   CASE(IAXIS); FVX_B(RCF%IJK(IAXIS),RCF%IJK(JAXIS),RCF%IJK(KAXIS))=FRC_B
   CASE(JAXIS); FVY_B(RCF%IJK(IAXIS),RCF%IJK(JAXIS),RCF%IJK(KAXIS))=FRC_B
   CASE(KAXIS); FVZ_B(RCF%IJK(IAXIS),RCF%IJK(JAXIS),RCF%IJK(KAXIS))=FRC_B
   ENDSELECT

ENDDO RC_LOOP

! 3. Linked means of FV_B and adding FV_B back to FV: CC_LINKED_BAROCLINIC_NO_FLUX, once every mesh is done.

T_USED(14) = T_USED(14) + CURRENT_TIME() - T_NOW

RETURN
END SUBROUTINE CC_BAROCLINIC_CORRECTION


SUBROUTINE CC_LINKED_BAROCLINIC_NO_FLUX(DT)

! After BAROCLINIC_CORRECTION on every mesh: FN_B averaged over the face link groups (cross-mesh sums first, so
! one mesh and several give the same mean) and added back to FN; then the no-flux forcing.

REAL(EB), INTENT(IN) :: DT
INTEGER :: NM,ICF,LCF,JCF,IF_
TYPE(CC_FV_TYPE), POINTER :: FV

IF (BAROCLINIC) CALL L2_CROSS_SUMS(CC_FV_MOM_FN_B)
DO NM=LOWER_MESH_INDEX,UPPER_MESH_INDEX
   IF (BAROCLINIC) THEN
      CALL GET_LINKED_FV(NM,DO_BAROCLINIC=.TRUE.)
      FVX = FVX + FVX_B
      FVY = FVY + FVY_B
      FVZ = FVZ + FVZ_B
      FV => MESHES(NM)%FV
      DO LCF=1,SIZE(MESHES(NM)%CF_GAS)
         ICF=MESHES(NM)%CF_GAS(LCF); CF => CUT_FACE(ICF)
         DO JCF=1,CF%NFACE
            IF_ = CF%FC(JCF)
            FV%FACE%FN(IF_) = FV%FACE%FN(IF_)+FV%FACE%FN_B(IF_)
         ENDDO
         CF%FV = CF%FV + CF%FV_B
      ENDDO
   ENDIF
   CALL CC_NO_FLUX(DT,NM,.TRUE.)
ENDDO

END SUBROUTINE CC_LINKED_BAROCLINIC_NO_FLUX


FUNCTION CC_FV_CUTFACE_MOM(NM,ICF,JCF,IVAR) RESULT(VAL)
! VEL, VELS, FN or FN_B of piece JCF of cut-face ICF, from its FACE row FC(JCF).
INTEGER, INTENT(IN) :: NM,ICF,JCF,IVAR
REAL(EB) :: VAL
INTEGER :: IF_
IF_ = MESHES(NM)%CUT_FACE(ICF)%FC(JCF)
SELECT CASE(IVAR)
CASE(CC_FV_MOM_VEL);  VAL = MESHES(NM)%FV%FACE%VEL(IF_)
CASE(CC_FV_MOM_VELS); VAL = MESHES(NM)%FV%FACE%VELS(IF_)
CASE(CC_FV_MOM_FN);   VAL = MESHES(NM)%FV%FACE%FN(IF_)
CASE(CC_FV_MOM_FN_B); VAL = MESHES(NM)%FV%FACE%FN_B(IF_)
END SELECT
END FUNCTION CC_FV_CUTFACE_MOM

FUNCTION CC_FV_UNKF_REG(NM,I,J,K,AX) RESULT(IL)
! Link number of the regular face at (I,J,K,AX). 0 when that position has no FACE row.
INTEGER, INTENT(IN) :: NM,I,J,K,AX
INTEGER :: IL,IF_
IF_ = MESHES(NM)%FCVAR(I,J,K,CC_FROW,AX)
IF (IF_>0) THEN
   IL = MESHES(NM)%FV%FACE%UNKF(IF_)
ELSE
   IL = 0
ENDIF
END FUNCTION CC_FV_UNKF_REG

FUNCTION CC_FV_UNKF_RC(NM,IRC) RESULT(IL)
! Link number of RC face IRC. Every RC face has a FACE row.
INTEGER, INTENT(IN) :: NM,IRC
INTEGER :: IL
IL = MESHES(NM)%FV%FACE%UNKF(MESHES(NM)%RC_FACE(IRC)%FC)
END FUNCTION CC_FV_UNKF_RC

FUNCTION CC_FV_UNKF_CF(NM,ICF,JCF) RESULT(IL)
! Link number of cut-face piece (ICF,JCF). CC_UNDEFINED when the piece has no FACE row.
INTEGER, INTENT(IN) :: NM,ICF,JCF
INTEGER :: IL,IF_
IF_ = 0
IF (ALLOCATED(MESHES(NM)%CUT_FACE(ICF)%FC)) IF_ = MESHES(NM)%CUT_FACE(ICF)%FC(JCF)
IF (IF_>0) THEN
   IL = MESHES(NM)%FV%FACE%UNKF(IF_)
ELSE
   IL = CC_UNDEFINED
ENDIF
END FUNCTION CC_FV_UNKF_CF

FUNCTION CC_FV_CUTFACE_MOM_AREA(NM,ICF,IVAR) RESULT(VA)
! Sum of CC_FV_CUTFACE_MOM times piece area over the pieces of cut-face ICF, in JCF order (the order of
! DOT_PRODUCT(...(1:NFACE),AREA(1:NFACE))). Callers keep their own divisor.
INTEGER, INTENT(IN) :: NM,ICF,IVAR
REAL(EB) :: VA
INTEGER :: JCF
VA = 0._EB
DO JCF=1,MESHES(NM)%CUT_FACE(ICF)%NFACE
   VA = VA + CC_FV_CUTFACE_MOM(NM,ICF,JCF,IVAR)*MESHES(NM)%CUT_FACE(ICF)%AREA(JCF)
ENDDO
END FUNCTION CC_FV_CUTFACE_MOM_AREA


FUNCTION GET_CUTCELL_RHOP(NM_LOC,ICC_LOC,JCC_LOC,PRFCT_LOC) RESULT(RHOP_OUT)
INTEGER, INTENT(IN) :: NM_LOC,ICC_LOC,JCC_LOC
REAL(EB), INTENT(IN) :: PRFCT_LOC
REAL(EB) :: RHOP_OUT
INTEGER :: IG_LOC,I_LOC,J_LOC,K_LOC
TYPE(CC_FV_TYPE), POINTER :: FV_LOC
TYPE(MESH_TYPE), POINTER :: M_LOC
CALL GET_FV_CV_STORAGE_FOR_CUTCELL(NM_LOC,ICC_LOC,JCC_LOC,IG_LOC)
M_LOC => MESHES(NM_LOC)
IF (IG_LOC>=1) THEN
   FV_LOC => M_LOC%FV
   RHOP_OUT = PRFCT_LOC*FV_LOC%CV%RHO(IG_LOC)+(1._EB-PRFCT_LOC)*FV_LOC%CV%RHOS(IG_LOC)
ELSE
   I_LOC = M_LOC%CUT_CELL(ICC_LOC)%IJK(IAXIS)
   J_LOC = M_LOC%CUT_CELL(ICC_LOC)%IJK(JAXIS)
   K_LOC = M_LOC%CUT_CELL(ICC_LOC)%IJK(KAXIS)
   RHOP_OUT = PRFCT_LOC*M_LOC%RHO(I_LOC,J_LOC,K_LOC)+(1._EB-PRFCT_LOC)*M_LOC%RHOS(I_LOC,J_LOC,K_LOC)
ENDIF
END FUNCTION GET_CUTCELL_RHOP


FUNCTION GET_CUTCELL_H(NM_LOC,ICC_LOC,JCC_LOC,PRFCT_LOC) RESULT(H_OUT)
! Predictor/corrector blend of cut-piece pressure H on the FV row IG when the piece has
! one (guards via the tail IG), else the Cartesian host. Same fallback as GET_CUTCELL_RHOP.
INTEGER, INTENT(IN) :: NM_LOC,ICC_LOC,JCC_LOC
REAL(EB), INTENT(IN) :: PRFCT_LOC
REAL(EB) :: H_OUT
INTEGER :: IG_LOC,I_LOC,J_LOC,K_LOC
TYPE(CC_FV_TYPE), POINTER :: FV_LOC
TYPE(MESH_TYPE), POINTER :: M_LOC
CALL GET_FV_CV_STORAGE_FOR_CUTCELL(NM_LOC,ICC_LOC,JCC_LOC,IG_LOC)
M_LOC => MESHES(NM_LOC)
IF (IG_LOC>=1) THEN
   FV_LOC => M_LOC%FV
   H_OUT = PRFCT_LOC*FV_LOC%CV%H(IG_LOC)+(1._EB-PRFCT_LOC)*FV_LOC%CV%HS(IG_LOC)
ELSE
   I_LOC = M_LOC%CUT_CELL(ICC_LOC)%IJK(IAXIS)
   J_LOC = M_LOC%CUT_CELL(ICC_LOC)%IJK(JAXIS)
   K_LOC = M_LOC%CUT_CELL(ICC_LOC)%IJK(KAXIS)
   H_OUT = PRFCT_LOC*M_LOC%H(I_LOC,J_LOC,K_LOC)+(1._EB-PRFCT_LOC)*M_LOC%HS(I_LOC,J_LOC,K_LOC)
ENDIF
END FUNCTION GET_CUTCELL_H


FUNCTION GET_CUTCELL_ZZP(NM_LOC,ICC_LOC,JCC_LOC,N_LOC,PRFCT_LOC) RESULT(ZZ_OUT)
INTEGER, INTENT(IN) :: NM_LOC,ICC_LOC,JCC_LOC,N_LOC
REAL(EB), INTENT(IN) :: PRFCT_LOC
REAL(EB) :: ZZ_OUT
INTEGER :: IG_LOC,I_LOC,J_LOC,K_LOC
TYPE(CC_FV_TYPE), POINTER :: FV_LOC
TYPE(MESH_TYPE), POINTER :: M_LOC
CALL GET_FV_CV_STORAGE_FOR_CUTCELL(NM_LOC,ICC_LOC,JCC_LOC,IG_LOC)
M_LOC => MESHES(NM_LOC)
IF (IG_LOC>=1) THEN
   FV_LOC => M_LOC%FV
   ZZ_OUT = PRFCT_LOC*FV_LOC%CV%ZZ(N_LOC,IG_LOC)+(1._EB-PRFCT_LOC)*FV_LOC%CV%ZZS(N_LOC,IG_LOC)
ELSE
   I_LOC = M_LOC%CUT_CELL(ICC_LOC)%IJK(IAXIS)
   J_LOC = M_LOC%CUT_CELL(ICC_LOC)%IJK(JAXIS)
   K_LOC = M_LOC%CUT_CELL(ICC_LOC)%IJK(KAXIS)
   ZZ_OUT = PRFCT_LOC*M_LOC%ZZ(I_LOC,J_LOC,K_LOC,N_LOC)+(1._EB-PRFCT_LOC)*M_LOC%ZZS(I_LOC,J_LOC,K_LOC,N_LOC)
ENDIF
END FUNCTION GET_CUTCELL_ZZP


FUNCTION GET_CUTCELL_TMP(NM_LOC,ICC_LOC,JCC_LOC) RESULT(TMP_OUT)
INTEGER, INTENT(IN) :: NM_LOC,ICC_LOC,JCC_LOC
REAL(EB) :: TMP_OUT
INTEGER :: IG_LOC,I_LOC,J_LOC,K_LOC
TYPE(CC_FV_TYPE), POINTER :: FV_LOC
TYPE(MESH_TYPE), POINTER :: M_LOC
CALL GET_FV_CV_STORAGE_FOR_CUTCELL(NM_LOC,ICC_LOC,JCC_LOC,IG_LOC)
M_LOC => MESHES(NM_LOC)
IF (IG_LOC>=1) THEN
   FV_LOC => M_LOC%FV
   TMP_OUT = FV_LOC%CV%TMP(IG_LOC)
ELSE
   I_LOC = M_LOC%CUT_CELL(ICC_LOC)%IJK(IAXIS)
   J_LOC = M_LOC%CUT_CELL(ICC_LOC)%IJK(JAXIS)
   K_LOC = M_LOC%CUT_CELL(ICC_LOC)%IJK(KAXIS)
   TMP_OUT = M_LOC%TMP(I_LOC,J_LOC,K_LOC)
ENDIF
END FUNCTION GET_CUTCELL_TMP


FUNCTION GET_CUTCELL_RSUM(NM_LOC,ICC_LOC,JCC_LOC) RESULT(RSUM_OUT)
INTEGER, INTENT(IN) :: NM_LOC,ICC_LOC,JCC_LOC
REAL(EB) :: RSUM_OUT
INTEGER :: IG_LOC,I_LOC,J_LOC,K_LOC
TYPE(CC_FV_TYPE), POINTER :: FV_LOC
TYPE(MESH_TYPE), POINTER :: M_LOC
CALL GET_FV_CV_STORAGE_FOR_CUTCELL(NM_LOC,ICC_LOC,JCC_LOC,IG_LOC)
M_LOC => MESHES(NM_LOC)
IF (IG_LOC>=1) THEN
   FV_LOC => M_LOC%FV
   RSUM_OUT = FV_LOC%CV%RSUM(IG_LOC)
ELSE
   I_LOC = M_LOC%CUT_CELL(ICC_LOC)%IJK(IAXIS)
   J_LOC = M_LOC%CUT_CELL(ICC_LOC)%IJK(JAXIS)
   K_LOC = M_LOC%CUT_CELL(ICC_LOC)%IJK(KAXIS)
   RSUM_OUT = M_LOC%RSUM(I_LOC,J_LOC,K_LOC)
ENDIF
END FUNCTION GET_CUTCELL_RSUM


SUBROUTINE GET_CUTCELL_ZZV(NM_LOC,ICC_LOC,JCC_LOC,PRFCT_LOC,ZZ_OUT)
INTEGER, INTENT(IN) :: NM_LOC,ICC_LOC,JCC_LOC
REAL(EB), INTENT(IN) :: PRFCT_LOC
REAL(EB), INTENT(OUT) :: ZZ_OUT(1:N_TRACKED_SPECIES)
INTEGER :: IG_LOC,I_LOC,J_LOC,K_LOC
TYPE(CC_FV_TYPE), POINTER :: FV_LOC
TYPE(MESH_TYPE), POINTER :: M_LOC
CALL GET_FV_CV_STORAGE_FOR_CUTCELL(NM_LOC,ICC_LOC,JCC_LOC,IG_LOC)
M_LOC => MESHES(NM_LOC)
IF (IG_LOC>=1) THEN
   FV_LOC => M_LOC%FV
   ZZ_OUT(1:N_TRACKED_SPECIES) = PRFCT_LOC*FV_LOC%CV%ZZ(1:N_TRACKED_SPECIES,IG_LOC)+ &
                                 (1._EB-PRFCT_LOC)*FV_LOC%CV%ZZS(1:N_TRACKED_SPECIES,IG_LOC)
ELSE
   I_LOC = M_LOC%CUT_CELL(ICC_LOC)%IJK(IAXIS)
   J_LOC = M_LOC%CUT_CELL(ICC_LOC)%IJK(JAXIS)
   K_LOC = M_LOC%CUT_CELL(ICC_LOC)%IJK(KAXIS)
   ZZ_OUT(1:N_TRACKED_SPECIES) = PRFCT_LOC*M_LOC%ZZ(I_LOC,J_LOC,K_LOC,1:N_TRACKED_SPECIES)+ &
                                 (1._EB-PRFCT_LOC)*M_LOC%ZZS(I_LOC,J_LOC,K_LOC,1:N_TRACKED_SPECIES)
ENDIF
END SUBROUTINE GET_CUTCELL_ZZV


! --------------------------- GET_CUTFACE_BAROCLINIC_TORQUE ------------------------

SUBROUTINE GET_CUTFACE_BAROCLINIC_TORQUE(NM,PRFCT,CF,JCF,IDX,WG1,WG2,II1,JJ1,KK1,II2,JJ2,KK2,FCF_B,HP)

! Assumes POINT_TO_MESH(NM) has been called.

INTEGER, INTENT(IN) :: NM,JCF,II1,JJ1,KK1,II2,JJ2,KK2
REAL(EB),INTENT(IN) :: PRFCT
TYPE(CC_CUTFACE_TYPE), INTENT(IN), POINTER :: CF
REAL(EB),INTENT(INOUT) :: IDX,WG1,WG2
REAL(EB),INTENT(OUT):: FCF_B
REAL(EB), POINTER, DIMENSION(:,:,:), INTENT(IN) :: HP

INTEGER :: ICC,JCC,X1AXIS,IF_
REAL(EB):: X1F,RHO1,RHO2,P1,P2,RHOF

X1AXIS = CF%IJK(KAXIS+1)
IF_=CF%FC(JCF)
IDX=GET_FV_FACE_RDN(NM,IF_,1._EB/(CF%XCENHIGH(X1AXIS,JCF)-CF%XCENLOW(X1AXIS,JCF)))
! Interpolation weights:
X1F = CF%XYZCEN(X1AXIS,JCF)
WG1 = IDX*(CF%XCENHIGH(X1AXIS,JCF)-X1F)
WG2 = IDX*(X1F-CF%XCENLOW(X1AXIS, JCF))
! Cut-cell pressure on low side:
ICC = CF%CELL_LIST(2,LOW_IND,JCF); JCC = CF%CELL_LIST(3,LOW_IND,JCF);
RHO1 = GET_CUTCELL_RHOP(NM,ICC,JCC,PRFCT)
P1  = RHO1*(HP(II1,JJ1,KK1)-KRES(II1,JJ1,KK1))
! Cut-cell pressure on high side:
ICC = CF%CELL_LIST(2,HIGH_IND,JCF); JCC = CF%CELL_LIST(3,HIGH_IND,JCF);
RHO2 = GET_CUTCELL_RHOP(NM,ICC,JCC,PRFCT)
P2  = RHO2*(HP(II2,JJ2,KK2)-KRES(II2,JJ2,KK2))
! Face density
RHOF= WG1*RHO1 + WG2*RHO2
! Baroclinic Term -p Grad(1/rho):
FCF_B = IDX * ( P2*(1._EB/RHOF-1._EB/RHO2) - P1*(1._EB/RHOF-1._EB/RHO1) )
!FCF_B = - (P1*RHO2+P2*RHO1)/(RHO1+RHO2) * IDX * (1._EB/RHO2-1._EB/RHO1)

RETURN
END SUBROUTINE GET_CUTFACE_BAROCLINIC_TORQUE

! -------------------------- GET_RCFACE_BAROCLINIC_TORQUE --------------------------

SUBROUTINE GET_RCFACE_BAROCLINIC_TORQUE(NM,PRFCT,ICF,WG1,WG2,FRC_B,HP,RHOP)

! Assumes POINT_TO_MESH(NM) has been called.

INTEGER, INTENT(IN)   :: NM,ICF
REAL(EB),INTENT(IN)   :: PRFCT
REAL(EB),INTENT(INOUT):: WG1,WG2
REAL(EB),INTENT(OUT)  :: FRC_B
REAL(EB), POINTER, DIMENSION(:,:,:), INTENT(IN) :: HP,RHOP

INTEGER :: ICC,JCC,I,J,K,X1AXIS,II1,II2,JJ1,JJ2,KK1,KK2
REAL(EB):: IDX,X1F,RHO1,RHO2,P1,P2,RHOF

I = RC_FACE(ICF)%IJK(IAXIS); J = RC_FACE(ICF)%IJK(JAXIS); K = RC_FACE(ICF)%IJK(KAXIS)
X1AXIS = RC_FACE(ICF)%IJK(KAXIS+1)
II1 = I; JJ1 = J; KK1 = K
II2 = I; JJ2 = J; KK2 = K
SELECT CASE(X1AXIS)
CASE(IAXIS); X1F=X(I); IDX = RDXN(I); II2 = II2+1
CASE(JAXIS); X1F=Y(J); IDX = RDYN(J); JJ2 = JJ2+1
CASE(KAXIS); X1F=Z(K); IDX = RDZN(K); KK2 = KK2+1
END SELECT
IDX=GET_FV_FACE_RDN(NM,RC_FACE(ICF)%FC,1._EB/(RC_FACE(ICF)%XCEN(X1AXIS,HIGH_IND)-RC_FACE(ICF)%XCEN(X1AXIS,LOW_IND)))
! Interpolation weights:
WG1 = IDX*(RC_FACE(ICF)%XCEN(X1AXIS,HIGH_IND)-X1F)
WG2 = IDX*(X1F-RC_FACE(ICF)%XCEN(X1AXIS, LOW_IND))
RHO1 = RHOP(II1,JJ1,KK1); RHO2 = RHOP(II2,JJ2,KK2)
IF(RC_FACE(ICF)%CELL_LIST(1,LOW_IND)==CC_FTYPE_CFGAS) THEN
   ICC = RC_FACE(ICF)%CELL_LIST(2,LOW_IND); JCC = RC_FACE(ICF)%CELL_LIST(3,LOW_IND)
   RHO1 = GET_CUTCELL_RHOP(NM,ICC,JCC,PRFCT)
ENDIF
IF(RC_FACE(ICF)%CELL_LIST(1,HIGH_IND)==CC_FTYPE_CFGAS) THEN
   ICC = RC_FACE(ICF)%CELL_LIST(2,HIGH_IND); JCC = RC_FACE(ICF)%CELL_LIST(3,HIGH_IND)
   RHO2 = GET_CUTCELL_RHOP(NM,ICC,JCC,PRFCT)
ENDIF
P1   = RHO1*(HP(II1,JJ1,KK1)-KRES(II1,JJ1,KK1))
P2   = RHO2*(HP(II2,JJ2,KK2)-KRES(II2,JJ2,KK2))
! Face density
RHOF = WG1*RHO1 + WG2*RHO2
! Baroclinic torque:
FRC_B = IDX * ( P2*(1._EB/RHOF-1._EB/RHO2) - P1*(1._EB/RHOF-1._EB/RHO1) )
!FRC_B = - (P1*RHO2+P2*RHO1)/(RHO1+RHO2) * IDX * (1._EB/RHO2-1._EB/RHO1)

RETURN
END SUBROUTINE GET_RCFACE_BAROCLINIC_TORQUE

! ------------------------ COMPUTE_LINKED_CUTFACE_BAROCLINIC -----------------------

SUBROUTINE COMPUTE_LINKED_CUTFACE_BAROCLINIC(NM)

! Link-group means of the baroclinic term at the current pressure (F_LINK) for the residual check of mesh NM, from
! the member values and cross-mesh sums of L2_BAROCLINIC_MEMBERS.

INTEGER, INTENT(IN) :: NM

IF(ALLOCATED(F_LINK)) DEALLOCATE(F_LINK,A_LINK)
ALLOCATE(F_LINK(0:MESHES(NM)%NUNK_F),A_LINK(0:MESHES(NM)%NUNK_F)); F_LINK = 0._EB; A_LINK = 0._EB
CALL ACCUM_L2_ORDERED_MEAN(NM,0,F_LINK,A_LINK)
WHERE(A_LINK>TWENTY_EPSILON_EB) F_LINK = F_LINK / A_LINK

END SUBROUTINE COMPUTE_LINKED_CUTFACE_BAROCLINIC


SUBROUTINE L2_BAROCLINIC_MEMBERS

! The baroclinic term -p grad(1/rho) at the current pressure on every held link-group member, as the momentum step
! computes it (zero on the walls it skips), then its cross-mesh sums. Every process calls this before the residual
! checks, which take the group means in COMPUTE_LINKED_CUTFACE_BAROCLINIC.

INTEGER :: NM,P,I,J,K,X1AXIS,IRC,II2,JJ2,KK2
REAL(EB) :: PRFCT,IDX,WG1,WG2,P1,P2
REAL(EB), POINTER, DIMENSION(:,:,:) :: HP,RHOP
TYPE(L2_MEAN_TYPE), POINTER :: LM

PRFCT = 0._EB; IF (PREDICTOR) PRFCT = 1._EB
DO NM=LOWER_MESH_INDEX,UPPER_MESH_INDEX
   CALL POINT_TO_MESH(NM)
   IF (PREDICTOR) THEN
      HP => H;  RHOP => RHO
   ELSE
      HP => HS; RHOP => RHOS
   ENDIF
   LM => L2_MEAN(NM)
   DO P=1,LM%N
      LM%V(P) = 0._EB
      X1AXIS = LM%M(1,P); I = LM%M(3,P); J = LM%M(4,P); K = LM%M(5,P)
      IF (X1AXIS>KAXIS) THEN ! Cut piece J of cut face I.
         CF => CUT_FACE(I)
         IF (BAROCLINIC_WALL_ZERO(CF%IWC)) CYCLE
         II2 = CF%IJK(IAXIS); JJ2 = CF%IJK(JAXIS); KK2 = CF%IJK(KAXIS)
         SELECT CASE(CF%IJK(KAXIS+1))
         CASE(IAXIS); II2 = II2+1
         CASE(JAXIS); JJ2 = JJ2+1
         CASE(KAXIS); KK2 = KK2+1
         END SELECT
         CALL GET_CUTFACE_BAROCLINIC_TORQUE(NM,PRFCT,CF,J,IDX,WG1,WG2,CF%IJK(IAXIS),CF%IJK(JAXIS),CF%IJK(KAXIS), &
                                            II2,JJ2,KK2,LM%V(P),HP)
         CYCLE
      ENDIF
      IRC = FCVAR(I,J,K,CC_IDRC,X1AXIS)
      IF (IRC>0) THEN
         IF (BAROCLINIC_WALL_ZERO(RC_FACE(IRC)%IWC)) CYCLE
         CALL GET_RCFACE_BAROCLINIC_TORQUE(NM,PRFCT,IRC,WG1,WG2,LM%V(P),HP,RHOP)
         CYCLE
      ENDIF
      II2 = I; JJ2 = J; KK2 = K
      SELECT CASE(X1AXIS)
      CASE(IAXIS); II2 = I+1; IDX = RDXN(I)
      CASE(JAXIS); JJ2 = J+1; IDX = RDYN(J)
      CASE(KAXIS); KK2 = K+1; IDX = RDZN(K)
      END SELECT
      P1 = RHOP(I,J,K)*(HP(I,J,K)-KRES(I,J,K))
      P2 = RHOP(II2,JJ2,KK2)*(HP(II2,JJ2,KK2)-KRES(II2,JJ2,KK2))
      LM%V(P) = -(P1*RHOP(II2,JJ2,KK2)+P2*RHOP(I,J,K))*(1._EB/RHOP(II2,JJ2,KK2)-1._EB/RHOP(I,J,K))*IDX/ &
                (RHOP(II2,JJ2,KK2)+RHOP(I,J,K))
   ENDDO
ENDDO
CALL L2_CROSS_SUMS(0)

END SUBROUTINE L2_BAROCLINIC_MEMBERS


LOGICAL FUNCTION BAROCLINIC_WALL_ZERO(IWC)
! A face on wall cell IWC has no baroclinic term on SOLID, NULL or MIRROR walls, nor on an external wall to another
! mesh that is not INTERPOLATED or PERIODIC (consistent with FN=-DUDT in CC_NO_FLUX).
INTEGER, INTENT(IN) :: IWC
BAROCLINIC_WALL_ZERO = .FALSE.
IF (IWC<1) RETURN
BAROCLINIC_WALL_ZERO = ANY(WALL(IWC)%BOUNDARY_TYPE==(/SOLID_BOUNDARY,NULL_BOUNDARY,MIRROR_BOUNDARY/))
IF (IWC<=N_EXTERNAL_WALL_CELLS) BAROCLINIC_WALL_ZERO = BAROCLINIC_WALL_ZERO .OR. (EXTERNAL_WALL(IWC)%NOM/=0 .AND. &
   .NOT.ANY(WALL(IWC)%BOUNDARY_TYPE==(/INTERPOLATED_BOUNDARY,PERIODIC_BOUNDARY/)))
END FUNCTION BAROCLINIC_WALL_ZERO

! --------------------------- CC_VEL_FACE_TO_SOLID_NODE ----------------------------

SUBROUTINE CC_VEL_FACE_TO_SOLID_NODE(NM,I,J,K,VAL)

! Routine to be called from REAL(EB) FUNCTION FACE_VALUE() in a block of the form:
! IF (CC_IBM) THEN
!    SELECT CASE(IND)
!    CASE(6,7,8) ! U,V,W.
!       IF(MESHES(NM)%VERTVAR(I,J,K,CC_VGSC)==CC_SOLID) THEN
!          CALL CC_VEL_FACE_TO_SOLID_NODE(NM,I,J,K,FACE_VALUE)
!          RETURN
!       ENDIF
!    END SELECT
! ENDIF

! Note: Routine assumes POINT_TO_MESH has been called and the node I,J,K is s.t VERTVAR(I,J,K,CC_VGSC)==CC_SOLID.
INTEGER, INTENT(IN) :: NM,I,J,K
REAL(EB),INTENT(OUT):: VAL

! Loval variables:
INTEGER :: DUMMY,II,JJ,KK

! Dummy assignments:
DUMMY=NM
II=I; JJ=J; KK=K

! For now set velocity in CC_SOLID node to zero:
VAL  = 0._EB

! Solid node velocity will depend on if node is inside the geometry or exactly on its boundary (FREE_SLIP).

END SUBROUTINE CC_VEL_FACE_TO_SOLID_NODE


! ----------------------------- GET_CFACE_OPEN_BC_COEF ------------------------------

SUBROUTINE GET_CFACE_OPEN_BC_COEF(NM,ICF,IOR,IDX,BIJ)

! Computes the diagonal coefficient for Laplacian matrix given a Dirichlet BC.
! IDX is initially 1/DXN where DXN depends on IOR.

INTEGER, INTENT(IN) :: NM,ICF,IOR
REAL(EB),INTENT(INOUT):: IDX
REAL(EB),INTENT(OUT):: BIJ

INTEGER :: JCF,X1AXIS,IF_

BIJ = 0._EB; X1AXIS=ABS(IOR)
DO JCF=1,CUT_FACE(ICF)%NFACE
   IF_=CUT_FACE(ICF)%FC(JCF)
   IDX = GET_FV_FACE_RDN(NM,IF_,1._EB/(CUT_FACE(ICF)%XCENHIGH(X1AXIS,JCF)-CUT_FACE(ICF)%XCENLOW(X1AXIS,JCF)))
   BIJ = BIJ + IDX*CUT_FACE(ICF)%AREA(JCF)
ENDDO

RETURN
END SUBROUTINE GET_CFACE_OPEN_BC_COEF

! ----------------------------- GET_FH_FROM_PRHS_AND_BCS ----------------------------

SUBROUTINE GET_FH_FROM_PRHS_AND_BCS(NM,DT,CYL_FCT,UNKH,NUNKH,IPZ,F_H)

! NOTE : This routine assumes POINT_TO_MESH has been called and F_H has been ZEROED for the MPI process.

INTEGER, INTENT(IN) :: NM,NUNKH,UNKH,IPZ
REAL(EB),INTENT(IN) :: DT,CYL_FCT
REAL(EB),INTENT(OUT):: F_H(NUNKH)

! Local variables:
INTEGER :: I,J,K,IROW,IW,IIG,JJG,KKG,IOR,ICFACE,IFACE,JFACE,ILH,JLH,KLH,IRC,IUNK,ICC,IF_
TYPE (WALL_TYPE), POINTER :: WC
TYPE (EXTERNAL_WALL_TYPE), POINTER :: EWC
TYPE(CFACE_TYPE), POINTER :: CFA
REAL(EB) :: IDX, AF, VAL, BCV

! Dummy Assignment.
VAL=DT

! First Source on Cartesian cells with CC_UNKH > 0:
DO K=1,KBAR
   DO J=1,JBAR
      DO I=1,IBAR
         IF (CCVAR(I,J,K,UNKH)<=0 .OR. ZONE_SOLVE(PRESSURE_ZONE(I,J,K))%CONNECTED_ZONE_PARENT/=IPZ) CYCLE
         IUNK=CCVAR(I,J,K,UNKH)
         VAL=PRHS(I,J,K)*((1._EB-CYL_FCT)*DY(J)+CYL_FCT*RC(I))*DX(I)*DZ(K)
         IF (CC_IBM .AND. &
             .NOT.CC_CV_H_PER_MEMBER) THEN
            CALL ADD_FV_L2_PRESSURE_RHS(IUNK,VAL,IPZ,F_H)
         ELSE
            IROW=IUNK-ZONE_SOLVE(IPZ)%UNKH_IND(NM_START)
            F_H(IROW)=F_H(IROW)+VAL
         ENDIF
      ENDDO
   ENDDO
ENDDO

! Rebuild F_H for cut-cells using previously computed CFACE boundary conditions.
IF (CC_IBM) CALL GET_CUTCELL_FH(NM,NUNKH,IPZ,F_H) ! Note: CYL_FCT not used for cut-cells.

! Compute FV in boundary and external CFACEs with DIRICHLET external BCs:
CFACE_LOOP_1 : DO ICFACE=1,N_EXTERNAL_CFACE_CELLS

   CFA => CFACE(ICFACE)
   ! Global matrix solve, skip INTERPOLATED boundaries.
   IF (PRES_FLAG/=ULMAT_FLAG .AND. CFA%BOUNDARY_TYPE==INTERPOLATED_BOUNDARY) CYCLE
   ! Here case where SOLID and OPEN or interpolated are mixed on a boundary:
   IF( CFA%BOUNDARY_TYPE==NULL_BOUNDARY .OR. CFA%BOUNDARY_TYPE==SOLID_BOUNDARY) CYCLE

   IFACE= CFA%CUT_FACE_IND1
   JFACE= CFA%CUT_FACE_IND2
   WC  => WALL(CUT_FACE(IFACE)%IWC)
   EWC => EXTERNAL_WALL(CUT_FACE(IFACE)%IWC)

   ! DIRICHLET boundaries:
   IF_CFACE_DIRICHLET: IF (EWC%PRESSURE_BC_TYPE==DIRICHLET) THEN

      ! Gasphase cell indexes:
      BC => BOUNDARY_COORD(WC%BC_INDEX); IF(ZONE_SOLVE(PRESSURE_ZONE(BC%IIG,BC%JJG,BC%KKG))%CONNECTED_ZONE_PARENT/=IPZ) CYCLE
      IIG = BC%IIG; JJG = BC%JJG; KKG = BC%KKG; IOR = BC%IOR
      ! Define centroid to centroid distance, normal to WC:
      IF_=CUT_FACE(IFACE)%FC(JFACE)
      IDX=GET_FV_FACE_RDN(NM,IF_,1._EB/(CUT_FACE(IFACE)%XCENHIGH(ABS(IOR),JFACE)-CUT_FACE(IFACE)%XCENLOW(ABS(IOR),JFACE)))

      VAL = -2._EB*IDX * CFA%AREA * CFA%PRES_BXN

      IF (CC_IBM .AND. &
          .NOT.CC_CV_H_PER_MEMBER) THEN
         IUNK=CCVAR(IIG,JJG,KKG,UNKH)
         IF (IUNK<=0 .AND. CC_IBM) THEN
            ICC=CCVAR(IIG,JJG,KKG,CC_IDCC)
            IF (ICC>0) IUNK=CUT_CELL(ICC)%UNKH(1)
         ENDIF
         IF (IUNK<=0) CYCLE
         CALL ADD_FV_L2_PRESSURE_RHS(IUNK,VAL,IPZ,F_H)
      ELSE
         ! Row number:
         IROW = CCVAR(IIG,JJG,KKG,UNKH) - ZONE_SOLVE(IPZ)%UNKH_IND(NM_START) ! Local numeration.
         IF (IROW <= 0 .AND. CC_IBM) CALL GET_CC_IROW(IIG,JJG,KKG,IPZ,IROW)
         IF (IROW <= 0) CYCLE
         ! Add to F_H:
         F_H(IROW) = F_H(IROW) + VAL
      ENDIF

   ENDIF IF_CFACE_DIRICHLET

ENDDO CFACE_LOOP_1

! Finally add External Wall cell BCs:
WALL_CELL_LOOP_1: DO IW=1,N_EXTERNAL_WALL_CELLS

   WC => WALL(IW)
   EWC => EXTERNAL_WALL(IW)
   ! Drop if this is a cut-face or NULL Boundary. Dealt with external CFACE.
   IF (WC%CUT_FACE_INDEX>0 .OR. WC%BOUNDARY_TYPE==NULL_BOUNDARY) CYCLE
   ! Gasphase cell indexes:
   BC => BOUNDARY_COORD(WC%BC_INDEX); IF(ZONE_SOLVE(PRESSURE_ZONE(BC%IIG,BC%JJG,BC%KKG))%CONNECTED_ZONE_PARENT/=IPZ) CYCLE
   IIG = BC%IIG; JJG = BC%JJG; KKG = BC%KKG; IOR = BC%IOR

   ! NEUMANN boundaries:
   IF_NEUMANN: IF (EWC%PRESSURE_BC_TYPE==NEUMANN) THEN
      ! Define cell size, normal to WC:
      SELECT CASE (IOR)
      CASE(-1) ! -IAXIS oriented, high face of IIG cell.
         AF  =  ((1._EB-CYL_FCT)*DY(JJG) + CYL_FCT*R(IIG  )) * DZ(KKG)
         VAL = -BXF(JJG,KKG)*AF
      CASE( 1) ! +IAXIS oriented, low face of IIG cell.
         AF  =  ((1._EB-CYL_FCT)*DY(JJG) + CYL_FCT*R(IIG-1)) * DZ(KKG)
         VAL =  BXS(JJG,KKG)*AF
      CASE(-2) ! -JAXIS oriented, high face of JJG cell.
         AF  =  DX(IIG)*DZ(KKG)
         VAL = -BYF(IIG,KKG)*AF
      CASE( 2) ! +JAXIS oriented, low face of JJG cell.
         AF  =  DX(IIG)*DZ(KKG)
         VAL =  BYS(IIG,KKG)*AF
      CASE(-3) ! -KAXIS oriented, high face of KKG cell.
         AF  =  ((1._EB-CYL_FCT)*DY(JJG) + CYL_FCT*RC(IIG  ))* DX(IIG)
         VAL = -BZF(IIG,JJG)*AF
      CASE( 3) ! +KAXIS oriented, low face of KKG cell.
         AF  =  ((1._EB-CYL_FCT)*DY(JJG) + CYL_FCT*RC(IIG  ))* DX(IIG)
         VAL =  BZS(IIG,JJG)*AF
      END SELECT

      IF (CC_IBM .AND. &
          .NOT.CC_CV_H_PER_MEMBER) THEN
         IUNK=CCVAR(IIG,JJG,KKG,UNKH)
         IF (IUNK<=0 .AND. CC_IBM) THEN
            ICC=CCVAR(IIG,JJG,KKG,CC_IDCC)
            IF (ICC>0) IUNK=CUT_CELL(ICC)%UNKH(1)
         ENDIF
         IF (IUNK<=0) CYCLE
         CALL ADD_FV_L2_PRESSURE_RHS(IUNK,VAL,IPZ,F_H)
      ELSE
         ! Row number:
         IROW = CCVAR(IIG,JJG,KKG,UNKH) - ZONE_SOLVE(IPZ)%UNKH_IND(NM_START) ! Local numeration.
         IF (IROW <= 0 .AND. CC_IBM) THEN
            CALL GET_CC_IROW(IIG,JJG,KKG,IPZ,IROW)
            IF (IROW <= 0) CYCLE
         ENDIF
         ! Add to F_H:
         F_H(IROW) = F_H(IROW) + VAL
      ENDIF

   ENDIF IF_NEUMANN

   ! DIRICHLET boundaries:
   IF_DIRICHLET: IF (EWC%PRESSURE_BC_TYPE==DIRICHLET) THEN
      ! Global matrix solve, skip INTERPOLATED boundaries.
      IF (PRES_FLAG/=ULMAT_FLAG .AND. WC%BOUNDARY_TYPE==INTERPOLATED_BOUNDARY) CYCLE
      ! Here case where SOLID and OPEN or interpolated are mixed on a boundary:
      IF( WC%BOUNDARY_TYPE==NULL_BOUNDARY  .OR. &
          WC%BOUNDARY_TYPE==SOLID_BOUNDARY .OR. WC%BOUNDARY_TYPE==MIRROR_BOUNDARY ) CYCLE
      ! Define cell size, normal to WC:
      ILH    = 0; JLH = 0; KLH = 0
      SELECT CASE (IOR)
      CASE(-1) ! -IAXIS oriented, high face of IIG cell.
         IDX = RDXN(IIG+ILH); BCV = BXF(JJG,KKG)
         AF  = ((1._EB-CYL_FCT)*DY(JJG) + CYL_FCT*R(IIG  )) * DZ(KKG)
      CASE( 1) ! +IAXIS oriented, low face of IIG cell.
         ILH = -1; IDX = RDXN(IIG+ILH); BCV = BXS(JJG,KKG)
         AF  = ((1._EB-CYL_FCT)*DY(JJG) + CYL_FCT*R(IIG-1)) * DZ(KKG)
      CASE(-2) ! -JAXIS oriented, high face of JJG cell.
         IDX = RDYN(JJG+JLH); BCV = BYF(IIG,KKG)
         AF  = DX(IIG)*DZ(KKG)
      CASE( 2) ! +JAXIS oriented, low face of JJG cell.
         JLH = -1; IDX = RDYN(JJG+JLH); BCV = BYS(IIG,KKG)
         AF  = DX(IIG)*DZ(KKG)
      CASE(-3) ! -KAXIS oriented, high face of KKG cell.
         IDX = RDZN(KKG+KLH); BCV = BZF(IIG,JJG)
         AF  =  ((1._EB-CYL_FCT)*DY(JJG) + CYL_FCT*RC(IIG  ))* DX(IIG)
      CASE( 3) ! +KAXIS oriented, low face of KKG cell.
         KLH = -1; IDX = RDZN(KKG+KLH); BCV = BZS(IIG,JJG)
         AF  =  ((1._EB-CYL_FCT)*DY(JJG) + CYL_FCT*RC(IIG  ))* DX(IIG)
      END SELECT
      ! Address case of RC face in the boundary:
      IF (CC_IBM) THEN
         IRC = FCVAR(IIG+ILH,JJG+JLH,KKG+KLH,CC_IDRC,ABS(BC%IOR))
         IF(IRC > 0) IDX = GET_FV_FACE_RDN(NM,RC_FACE(IRC)%FC,&
              1._EB/(RC_FACE(IRC)%XCEN(ABS(BC%IOR),HIGH_IND)-RC_FACE(IRC)%XCEN(ABS(BC%IOR),LOW_IND)))
      ENDIF
      VAL=-2._EB*IDX*AF*BCV
      IF (CC_IBM .AND. &
          .NOT.CC_CV_H_PER_MEMBER) THEN
         IUNK=CCVAR(IIG,JJG,KKG,UNKH)
         IF (IUNK<=0 .AND. CC_IBM) THEN
            ICC=CCVAR(IIG,JJG,KKG,CC_IDCC)
            IF (ICC>0) IUNK=CUT_CELL(ICC)%UNKH(1)
         ENDIF
         IF (IUNK<=0) CYCLE
         CALL ADD_FV_L2_PRESSURE_RHS(IUNK,VAL,IPZ,F_H)
      ELSE
         ! Row number:
         IROW = CCVAR(IIG,JJG,KKG,UNKH) - ZONE_SOLVE(IPZ)%UNKH_IND(NM_START) ! Local numeration.
         IF (IROW <= 0 .AND. CC_IBM) CALL GET_CC_IROW(IIG,JJG,KKG,IPZ,IROW)
         IF (IROW <= 0) CYCLE
         ! Add to F_H:
         F_H(IROW) = F_H(IROW) + VAL
      ENDIF

   ENDIF IF_DIRICHLET

ENDDO WALL_CELL_LOOP_1


END SUBROUTINE GET_FH_FROM_PRHS_AND_BCS


! -------------------------------- GET_PRES_CFACE_BCS -------------------------------

SUBROUTINE GET_PRES_CFACE_BCS(NM,T,DT)

USE MATH_FUNCTIONS, ONLY: EVALUATE_RAMP

! NOTE : This routine assumes POINT_TO_MESH has been called.

INTEGER, INTENT(IN) :: NM
REAL(EB),INTENT(IN) :: T,DT

! Local Variables:
INTEGER :: ICF,I,J,K,IOR,IFACE,JFACE,NFACE
REAL(EB):: IDX,HN,TSI,VEL_EDDY,TIME_RAMP_FACTOR,P_EXTERNAL,H0,DX_1
REAL(EB), POINTER, DIMENSION(:,:,:) :: UU,VV,WW,HP
TYPE (VENTS_TYPE), POINTER :: VT
TYPE (WALL_TYPE), POINTER :: WC
TYPE (EXTERNAL_WALL_TYPE), POINTER :: EWC
TYPE (CFACE_TYPE), POINTER :: CFA
TYPE (BOUNDARY_PROP1_TYPE), POINTER :: CFA_B1
TYPE(MESH_TYPE), POINTER :: M2
TYPE (CC_CUTFACE_TYPE), POINTER :: CF2
INTEGER :: IIO,JJO,KKO,NOM,IW,ICFO,JCFO
REAL(EB):: H_OTHER,DA_OTHER,DX_OTHER,DY_OTHER,DZ_OTHER,A_FACE

! Dummy assignment.
I=NM; IDX=DT

IF (PREDICTOR) THEN
   UU => U
   VV => V
   WW => W
   HP => H
ELSE
   UU => US
   VV => VS
   WW => WS
   HP => HS
ENDIF

! Apply pressure boundary conditions at external cells.
! If Neumann, CFACE(ICF)%PRES_BXN contains dH/dx.
! If Dirichlet, CFACE(ICF)%PRES_BXN contains H.

! External mesh CFACEs:
CFACE_LOOP_1 : DO ICF=1,N_EXTERNAL_CFACE_CELLS+N_INTWALL_CFACE_CELLS+N_INTERNAL_CFACE_CELLS

   CFA => CFACE(ICF)
   BC  => BOUNDARY_COORD(CFA%BC_INDEX)
   I   = BC%II
   J   = BC%JJ
   K   = BC%KK
   IOR = BC%IOR

   IFACE=CFA%CUT_FACE_IND1
   JFACE=CFA%CUT_FACE_IND2
   NFACE=CUT_FACE(IFACE)%NFACE

   ! Apply pressure gradients at NEUMANN boundaries: dH/dn = -F_n - d(u_n)/dt

   IF_NEUMANN: IF (CFA%BOUNDARY_TYPE==SOLID_BOUNDARY) THEN
      HN    = 1._EB
      IF (ICF<=N_EXTERNAL_CFACE_CELLS) THEN
         SELECT CASE(IOR)
         CASE( 1); HN = HX(0)
         CASE(-1); HN = HX(IBP1)
         CASE( 2); HN = HY(0)
         CASE(-2); HN = HY(JBP1)
         CASE( 3); HN = HZ(0)
         CASE(-3); HN = HZ(KBP1)
         END SELECT
      ENDIF
      ! dH/Dn where n is pointing out of the gas region.
      CFA%PRES_BXN = -HN*(CC_FV_CUTFACE_MOM(NM,IFACE,JFACE,CC_FV_MOM_FN) + CFA%DUNDT)
   ENDIF IF_NEUMANN

   ! Interpolated and OPEN BCs only in External wall cells:
   EXT_CFACE_IF : IF (ICF<=N_EXTERNAL_CFACE_CELLS) THEN

      IW = CUT_FACE(IFACE)%IWC
      WC=>WALL(IW)
      EWC=>EXTERNAL_WALL(IW)

      ! Interpolated boundary -- set boundary value of H to be average of neighboring cells from previous time step

      INTERPOLATED_ONLY:  IF(PRES_FLAG==ULMAT_FLAG .AND. CFA%BOUNDARY_TYPE==INTERPOLATED_BOUNDARY) THEN

         NOM     = EWC%NOM
         M2      =>MESHES(NOM)

         H_OTHER = 0._EB; DA_OTHER = 0._EB; DX_OTHER = 0._EB; DY_OTHER = 0._EB; DZ_OTHER = 0._EB
         DX_1 = CUT_FACE(IFACE)%XCENHIGH(ABS(IOR),JFACE)-CUT_FACE(IFACE)%XCENLOW(ABS(IOR),JFACE)
         SELECT CASE(IOR)
            CASE( 1)

               DO KKO=EWC%KKO_MIN,EWC%KKO_MAX
                  DO JJO=EWC%JJO_MIN,EWC%JJO_MAX
                     DO IIO=EWC%IIO_MIN,EWC%IIO_MAX
                        IF(M2%CELL(M2%CELL_INDEX(IIO,JJO,KKO))%SOLID) CYCLE
                        IF(M2%FCVAR(IIO,JJO,KKO,CC_FGSC,ABS(IOR))==CC_SOLID) CYCLE

                        ICFO = M2%FCVAR(IIO,JJO,KKO,CC_IDCF,ABS(IOR))
                        IF (ICFO>0) THEN
                           CF2 => M2%CUT_FACE(ICFO); A_FACE = 0._EB
                           DO JCFO=1,CF2%NFACE
                              A_FACE   = A_FACE + CF2%AREA(JCFO)
                              DX_OTHER = DX_OTHER + &
                              (CF2%XCENHIGH(ABS(IOR),JCFO)-CF2%XCENLOW(ABS(IOR),JCFO))*CF2%AREA(JCFO)
                           ENDDO
                        ELSE
                           A_FACE   = M2%DY(JJO)*M2%DZ(KKO)
                           DX_OTHER = DX_OTHER + M2%DX(EWC%IIO_MIN)*A_FACE
                        ENDIF
                        DA_OTHER = DA_OTHER + A_FACE
                        IF (PREDICTOR) H_OTHER = H_OTHER + OMESH(NOM)%H(IIO,JJO,KKO)*A_FACE
                        IF (CORRECTOR) H_OTHER = H_OTHER + OMESH(NOM)%HS(IIO,JJO,KKO)*A_FACE
                     ENDDO
                  ENDDO
               ENDDO
               H_OTHER  = H_OTHER/DA_OTHER
               DX_OTHER = DX_OTHER/DA_OTHER
               CFA%PRES_BXN = (DX_OTHER*HP(1,J,K) + DX_1*H_OTHER)/(DX_1+DX_OTHER) + WALL_WORK1(IW)
               BXS(J,K) = CFA%PRES_BXN
            CASE(-1)

               DO KKO=EWC%KKO_MIN,EWC%KKO_MAX
                  DO JJO=EWC%JJO_MIN,EWC%JJO_MAX
                     DO IIO=EWC%IIO_MIN,EWC%IIO_MAX
                        IF (M2%CELL(M2%CELL_INDEX(IIO,JJO,KKO))%SOLID) CYCLE
                        IF (M2%FCVAR(IIO-1,JJO,KKO,CC_FGSC,ABS(IOR))==CC_SOLID) CYCLE

                        ICFO = M2%FCVAR(IIO-1,JJO,KKO,CC_IDCF,ABS(IOR))
                        IF (ICFO>0) THEN
                           CF2 =>M2%CUT_FACE(ICFO); A_FACE = 0._EB
                           DO JCFO=1,CF2%NFACE
                              A_FACE   = A_FACE + CF2%AREA(JCFO)
                              DX_OTHER = DX_OTHER + &
                              (CF2%XCENHIGH(ABS(IOR),JCFO)-CF2%XCENLOW(ABS(IOR),JCFO))*CF2%AREA(JCFO)
                           ENDDO
                        ELSE
                           A_FACE   = M2%DY(JJO)*M2%DZ(KKO)
                           DX_OTHER = DX_OTHER + M2%DX(EWC%IIO_MIN)*A_FACE
                        ENDIF
                        DA_OTHER = DA_OTHER + A_FACE
                        IF (PREDICTOR) H_OTHER = H_OTHER + OMESH(NOM)%H(IIO,JJO,KKO)*A_FACE
                        IF (CORRECTOR) H_OTHER = H_OTHER + OMESH(NOM)%HS(IIO,JJO,KKO)*A_FACE
                     ENDDO
                  ENDDO
               ENDDO
               H_OTHER  = H_OTHER/DA_OTHER
               DX_OTHER = DX_OTHER/DA_OTHER
               CFA%PRES_BXN = (DX_OTHER*HP(IBAR,J,K) + DX_1*H_OTHER)/(DX_1+DX_OTHER) + WALL_WORK1(IW)
               BXF(J,K) = CFA%PRES_BXN
            CASE( 2)

               DO KKO=EWC%KKO_MIN,EWC%KKO_MAX
                  DO JJO=EWC%JJO_MIN,EWC%JJO_MAX
                     DO IIO=EWC%IIO_MIN,EWC%IIO_MAX
                        IF (M2%CELL(M2%CELL_INDEX(IIO,JJO,KKO))%SOLID) CYCLE
                        IF (M2%FCVAR(IIO,JJO,KKO,CC_FGSC,ABS(IOR))==CC_SOLID) CYCLE

                        ICFO = M2%FCVAR(IIO,JJO,KKO,CC_IDCF,ABS(IOR))
                        IF (ICFO>0) THEN
                           CF2 =>M2%CUT_FACE(ICFO); A_FACE = 0._EB
                           DO JCFO=1,CF2%NFACE
                              A_FACE   = A_FACE + CF2%AREA(JCFO)
                              DY_OTHER = DY_OTHER + &
                              (CF2%XCENHIGH(ABS(IOR),JCFO)-CF2%XCENLOW(ABS(IOR),JCFO))*CF2%AREA(JCFO)
                           ENDDO
                        ELSE
                           A_FACE   = M2%DX(IIO)*M2%DZ(KKO)
                           DY_OTHER = DY_OTHER + M2%DY(EWC%JJO_MIN)*A_FACE
                        ENDIF
                        DA_OTHER = DA_OTHER + A_FACE
                        IF (PREDICTOR) H_OTHER = H_OTHER + OMESH(NOM)%H(IIO,JJO,KKO)*A_FACE
                        IF (CORRECTOR) H_OTHER = H_OTHER + OMESH(NOM)%HS(IIO,JJO,KKO)*A_FACE
                     ENDDO
                  ENDDO
               ENDDO
               H_OTHER = H_OTHER/DA_OTHER
               DY_OTHER = DY_OTHER/DA_OTHER
               CFA%PRES_BXN = (DY_OTHER*HP(I,1,K) + DX_1*H_OTHER)/(DX_1+DY_OTHER) + WALL_WORK1(IW)
               BYS(I,K) = CFA%PRES_BXN
            CASE(-2)

               DO KKO=EWC%KKO_MIN,EWC%KKO_MAX
                  DO JJO=EWC%JJO_MIN,EWC%JJO_MAX
                     DO IIO=EWC%IIO_MIN,EWC%IIO_MAX
                        IF (M2%CELL(M2%CELL_INDEX(IIO,JJO,KKO))%SOLID) CYCLE
                        IF (M2%FCVAR(IIO,JJO-1,KKO,CC_FGSC,ABS(IOR))==CC_SOLID) CYCLE

                        ICFO = M2%FCVAR(IIO,JJO-1,KKO,CC_IDCF,ABS(IOR))
                        IF (ICFO>0) THEN
                           CF2 =>M2%CUT_FACE(ICFO); A_FACE = 0._EB
                           DO JCFO=1,CF2%NFACE
                              A_FACE   = A_FACE + CF2%AREA(JCFO)
                              DY_OTHER = DY_OTHER + &
                              (CF2%XCENHIGH(ABS(IOR),JCFO)-CF2%XCENLOW(ABS(IOR),JCFO))*CF2%AREA(JCFO)
                           ENDDO
                        ELSE
                           A_FACE   = M2%DX(IIO)*M2%DZ(KKO)
                           DY_OTHER = DY_OTHER + M2%DY(EWC%JJO_MIN)*A_FACE
                        ENDIF
                        DA_OTHER = DA_OTHER + A_FACE
                        IF (PREDICTOR) H_OTHER = H_OTHER + OMESH(NOM)%H(IIO,JJO,KKO)*A_FACE
                        IF (CORRECTOR) H_OTHER = H_OTHER + OMESH(NOM)%HS(IIO,JJO,KKO)*A_FACE
                     ENDDO
                  ENDDO
               ENDDO
               H_OTHER  = H_OTHER/DA_OTHER
               DY_OTHER = DY_OTHER/DA_OTHER
               CFA%PRES_BXN = (DY_OTHER*HP(I,JBAR,K) + DX_1*H_OTHER)/(DX_1+DY_OTHER) + WALL_WORK1(IW)
               BYF(I,K) = CFA%PRES_BXN
            CASE( 3)

               DO KKO=EWC%KKO_MIN,EWC%KKO_MAX
                  DO JJO=EWC%JJO_MIN,EWC%JJO_MAX
                     DO IIO=EWC%IIO_MIN,EWC%IIO_MAX
                        IF (M2%CELL(M2%CELL_INDEX(IIO,JJO,KKO))%SOLID) CYCLE
                        IF (M2%FCVAR(IIO,JJO,KKO,CC_FGSC,ABS(IOR))==CC_SOLID) CYCLE

                        ICFO = M2%FCVAR(IIO,JJO,KKO,CC_IDCF,ABS(IOR))
                        IF (ICFO>0) THEN
                           CF2 =>M2%CUT_FACE(ICFO); A_FACE = 0._EB
                           DO JCFO=1,CF2%NFACE
                              A_FACE   = A_FACE + CF2%AREA(JCFO)
                              DZ_OTHER = DZ_OTHER + &
                              (CF2%XCENHIGH(ABS(IOR),JCFO)-CF2%XCENLOW(ABS(IOR),JCFO))*CF2%AREA(JCFO)
                           ENDDO
                        ELSE
                           A_FACE   = M2%DX(IIO)*M2%DY(JJO)
                           DZ_OTHER = DZ_OTHER + M2%DZ(EWC%KKO_MIN)*A_FACE
                        ENDIF
                        DA_OTHER = DA_OTHER + A_FACE
                        IF (PREDICTOR) H_OTHER = H_OTHER + OMESH(NOM)%H(IIO,JJO,KKO)*A_FACE
                        IF (CORRECTOR) H_OTHER = H_OTHER + OMESH(NOM)%HS(IIO,JJO,KKO)*A_FACE
                     ENDDO
                  ENDDO
               ENDDO
               H_OTHER  = H_OTHER/DA_OTHER
               DZ_OTHER = DZ_OTHER/DA_OTHER
               CFA%PRES_BXN = (DZ_OTHER*HP(I,J,1) + DX_1*H_OTHER)/(DX_1+DZ_OTHER) + WALL_WORK1(IW)
               BZS(I,J) = CFA%PRES_BXN
            CASE(-3)

               DO KKO=EWC%KKO_MIN,EWC%KKO_MAX
                  DO JJO=EWC%JJO_MIN,EWC%JJO_MAX
                     DO IIO=EWC%IIO_MIN,EWC%IIO_MAX
                        IF (M2%CELL(M2%CELL_INDEX(IIO,JJO,KKO))%SOLID) CYCLE
                        IF (M2%FCVAR(IIO,JJO,KKO-1,CC_FGSC,ABS(IOR))==CC_SOLID) CYCLE

                        ICFO = M2%FCVAR(IIO,JJO,KKO-1,CC_IDCF,ABS(IOR))
                        IF (ICFO>0) THEN
                           CF2 =>M2%CUT_FACE(ICFO); A_FACE = 0._EB
                           DO JCFO=1,CF2%NFACE
                              A_FACE = A_FACE + CF2%AREA(JCFO)
                              DZ_OTHER = DZ_OTHER + &
                              (CF2%XCENHIGH(ABS(IOR),JCFO)-CF2%XCENLOW(ABS(IOR),JCFO))*CF2%AREA(JCFO)
                           ENDDO
                        ELSE
                           A_FACE   = M2%DX(IIO)*M2%DY(JJO)
                           DZ_OTHER = DZ_OTHER + M2%DZ(EWC%KKO_MIN)*A_FACE
                        ENDIF
                        DA_OTHER = DA_OTHER + A_FACE
                        IF (PREDICTOR) H_OTHER = H_OTHER + OMESH(NOM)%H(IIO,JJO,KKO)*A_FACE
                        IF (CORRECTOR) H_OTHER = H_OTHER + OMESH(NOM)%HS(IIO,JJO,KKO)*A_FACE
                     ENDDO
                  ENDDO
               ENDDO
               H_OTHER  = H_OTHER/DA_OTHER
               DZ_OTHER = DZ_OTHER/DA_OTHER
               CFA%PRES_BXN = (DZ_OTHER*HP(I,J,KBAR) + DX_1*H_OTHER)/(DX_1+DZ_OTHER) + WALL_WORK1(IW)
               BZF(I,J) = CFA%PRES_BXN
         END SELECT

      ENDIF INTERPOLATED_ONLY

      ! OPEN (passive opening to exterior of domain) boundary. Apply inflow/outflow BC.

      OPEN_IF: IF (WC%BOUNDARY_TYPE==OPEN_BOUNDARY) THEN

         VT => VENTS(WC%VENT_INDEX)
         B1 => BOUNDARY_PROP1(WC%B1_INDEX)
         IF (ABS(B1%T_IGN-T_BEGIN)<=TWENTY_EPSILON_EB .AND. VT%PRESSURE_RAMP_INDEX >=1) THEN
            TSI = T
         ELSE
            TSI = T - T_BEGIN
         ENDIF
         TIME_RAMP_FACTOR = EVALUATE_RAMP(TSI,VT%PRESSURE_RAMP_INDEX)
         P_EXTERNAL = TIME_RAMP_FACTOR*VT%DYNAMIC_PRESSURE

         ! Synthetic eddy method for OPEN inflow boundaries
         VEL_EDDY = 0._EB
         IF (VT%N_EDDY>0) THEN
            SELECT CASE(ABS(VT%IOR))
               CASE(1); VEL_EDDY = VT%U_EDDY(J,K)
               CASE(2); VEL_EDDY = VT%V_EDDY(I,K)
               CASE(3); VEL_EDDY = VT%W_EDDY(I,J)
            END SELECT
         ENDIF

         ! Wind inflow boundary conditions

         H0 = 0.5_EB*(U0**2+V0**2+W0**2)
         IF (OPEN_WIND_BOUNDARY) &
         H0 = 0.5_EB*((U_WIND(K)+VEL_EDDY)**2 + (V_WIND(K)+VEL_EDDY)**2 + (W_WIND(K)+VEL_EDDY)**2)

         CFA_B1 => BOUNDARY_PROP1(CFA%B1_INDEX)
         SELECT CASE(IOR)
            CASE( 1)
               IF (UU(0,J,K)<0._EB) THEN
                  CFA%PRES_BXN = P_EXTERNAL/CFA_B1%RHO_F + KRES(1,J,K)
               ELSE
                  CFA%PRES_BXN = P_EXTERNAL/CFA_B1%RHO_F + H0
               ENDIF
               BXS(J,K) = CFA%PRES_BXN
            CASE(-1)
               IF (UU(IBAR,J,K)>0._EB) THEN
                  CFA%PRES_BXN = P_EXTERNAL/CFA_B1%RHO_F + KRES(IBAR,J,K)
               ELSE
                  CFA%PRES_BXN = P_EXTERNAL/CFA_B1%RHO_F + H0
               ENDIF
               BXF(J,K) = CFA%PRES_BXN
            CASE( 2)
               IF (VV(I,0,K)<0._EB) THEN
                  CFA%PRES_BXN = P_EXTERNAL/CFA_B1%RHO_F + KRES(I,1,K)
               ELSE
                  CFA%PRES_BXN = P_EXTERNAL/CFA_B1%RHO_F + H0
               ENDIF
               BYS(I,K) = CFA%PRES_BXN
            CASE(-2)
               IF (VV(I,JBAR,K)>0._EB) THEN
                  CFA%PRES_BXN = P_EXTERNAL/CFA_B1%RHO_F + KRES(I,JBAR,K)
               ELSE
                  CFA%PRES_BXN = P_EXTERNAL/CFA_B1%RHO_F + H0
               ENDIF
               BYF(I,K) = CFA%PRES_BXN
            CASE( 3)
               IF (WW(I,J,0)<0._EB) THEN
                  CFA%PRES_BXN = P_EXTERNAL/CFA_B1%RHO_F + KRES(I,J,1)
               ELSE
                  CFA%PRES_BXN = P_EXTERNAL/CFA_B1%RHO_F + H0
               ENDIF
               BZS(I,J) = CFA%PRES_BXN
            CASE(-3)
               IF (WW(I,J,KBAR)>0._EB) THEN
                  CFA%PRES_BXN = P_EXTERNAL/CFA_B1%RHO_F + KRES(I,J,KBAR)
               ELSE
                  CFA%PRES_BXN = P_EXTERNAL/CFA_B1%RHO_F + H0
               ENDIF
               BZF(I,J) = CFA%PRES_BXN
         END SELECT

      ENDIF OPEN_IF

   ENDIF EXT_CFACE_IF

ENDDO CFACE_LOOP_1

END SUBROUTINE GET_PRES_CFACE_BCS

! --------------------------------- GET_CUTCELL_DDDT --------------------------------

SUBROUTINE CC_FV_SET_CV_PRESSURE_SOURCE(NM,ICC,JCC,DDDTVOL_VALUE,DVOL_PR_VALUE)
INTEGER, INTENT(IN) :: NM,ICC,JCC
REAL(EB), INTENT(IN) :: DDDTVOL_VALUE
REAL(EB), INTENT(IN), OPTIONAL :: DVOL_PR_VALUE
INTEGER :: IROW
TYPE(CC_FV_TYPE), POINTER :: FV

! Store intensive dD/dt on the piece IG row.
FV=>MESHES(NM)%FV
CALL GET_FV_CV_STORAGE_FOR_CUTCELL(NM,ICC,JCC,IROW)
IF (IROW<1) RETURN
FV%CV%DDDTVOL(IROW) = DDDTVOL_VALUE
IF (PRESENT(DVOL_PR_VALUE)) FV%CV%DVOL_PR(IROW)=DVOL_PR_VALUE
END SUBROUTINE CC_FV_SET_CV_PRESSURE_SOURCE

SUBROUTINE GET_CUTCELL_DDDT(DT,NM)

! Here assume CALL POINT_TO_MESH has been made.
REAL(EB), INTENT(IN) :: DT
INTEGER,  INTENT(IN) :: NM
REAL(EB) :: RDT, PRFCT, VOL, DIVVOL, DPCC, DIV_JCC, VCV
INTEGER  :: I,J,K,NCELL,ICC,JCC,IROW,IG
REAL(EB), POINTER, DIMENSION(:) :: D_PBAR_DT_P
TYPE(CC_FV_TYPE), POINTER :: FV

FV=>MESHES(NM)%FV

RDT = 1._EB/DT
SELECT CASE(PREDICTOR)
   CASE(.TRUE.)
      D_PBAR_DT_P => D_PBAR_DT_S
      PRFCT = 1._EB
   CASE(.FALSE.)
      D_PBAR_DT_P => D_PBAR_DT
      PRFCT = 0._EB
END SELECT

PRED_CORR_IF : IF (PREDICTOR) THEN

   ICC_LOOP_1 : DO ICC=1,MESHES(NM)%N_CUTCELL_MESH
      I      = CUT_CELL(ICC)%IJK(IAXIS)
      J      = CUT_CELL(ICC)%IJK(JAXIS)
      K      = CUT_CELL(ICC)%IJK(KAXIS)
      IF (CELL(CELL_INDEX(I,J,K))%SOLID) CYCLE ICC_LOOP_1
      NCELL  = CUT_CELL(ICC)%NCELL
      DIVVOL = 0._EB; DPCC   = 0._EB; VOL    = 0._EB
      DO JCC=1,NCELL
         VCV = CUT_CELL(ICC)%VOLUME(JCC)
         VOL  = VOL + VCV
         CALL GET_VELOC_DIVERGENCE_CUTCELL(NM,ICC,JCC,0._EB,DIV_JCC) ! U,V,W divergence.
         DIVVOL = DIVVOL + DIV_JCC*VCV
         IG = CUT_CELL(ICC)%IG(JCC)
         DPCC= DPCC + ( (1._EB-PRFCT)*FV%CV%D(IG) + PRFCT*FV%CV%DS(IG) )*VCV
      ENDDO
      CALL CC_FV_SET_CV_PRESSURE_SOURCE(NM,ICC,1,(DPCC-DIVVOL)*RDT/VOL,DIVVOL)

   ENDDO ICC_LOOP_1

ELSEIF (CORRECTOR) THEN PRED_CORR_IF

   ICC_LOOP_2 : DO ICC=1,MESHES(NM)%N_CUTCELL_MESH
      I      = CUT_CELL(ICC)%IJK(IAXIS)
      J      = CUT_CELL(ICC)%IJK(JAXIS)
      K      = CUT_CELL(ICC)%IJK(KAXIS)
      IF (CELL(CELL_INDEX(I,J,K))%SOLID) CYCLE ICC_LOOP_2
      NCELL  = CUT_CELL(ICC)%NCELL
      DIVVOL = 0._EB; DPCC   = 0._EB; VOL    = 0._EB
      DO JCC=1,NCELL
         VCV = CUT_CELL(ICC)%VOLUME(JCC)
         VOL  = VOL + VCV
         CALL GET_VELOC_DIVERGENCE_CUTCELL(NM,ICC,JCC,1._EB,DIV_JCC) ! US,VS,WS divergence.
         DIVVOL = DIVVOL + DIV_JCC*VCV
         ! Thermodynamic divergence * vol:
         IG = CUT_CELL(ICC)%IG(JCC)
         DPCC= DPCC + ( (1._EB-PRFCT)*FV%CV%D(IG) + PRFCT*FV%CV%DS(IG) )*VCV
      ENDDO
      ! Define average DDDT for CUT_CELL(ICC):
      CALL GET_FV_CV_STORAGE_FOR_CUTCELL(NM,ICC,1,IROW)
      IF (IROW<1) CYCLE ICC_LOOP_2
      CALL CC_FV_SET_CV_PRESSURE_SOURCE(NM,ICC,1,(2._EB*DPCC-(DIVVOL+FV%CV%DVOL_PR(IROW)))*RDT/VOL)
   ENDDO ICC_LOOP_2

ENDIF PRED_CORR_IF

! DDDTVOL is intensive dD/dt on the piece IG row, not a CV mean.

RETURN
END SUBROUTINE GET_CUTCELL_DDDT


SUBROUTINE CC_FV_PROJECT_CUTFACE_VELOCITY(NM,ICF,JCF,DT,DHDN,DO_VELS)
! Preserve the legacy projection formula and linked-face ordering while making the canonical
! FACE row the runtime state owner.
INTEGER, INTENT(IN) :: NM,ICF,JCF
REAL(EB), INTENT(IN) :: DT,DHDN
LOGICAL, INTENT(IN) :: DO_VELS
INTEGER :: IF_
TYPE(CC_FV_TYPE), POINTER :: FV

FV=>MESHES(NM)%FV
IF_=MESHES(NM)%CUT_FACE(ICF)%FC(JCF)
IF (DO_VELS) THEN
   FV%FACE%VELS(IF_)=FV%FACE%VEL(IF_)-DT*(FV%FACE%FN(IF_)+DHDN)
ELSE
   FV%FACE%VEL(IF_)=0.5_EB*(FV%FACE%VEL(IF_)+FV%FACE%VELS(IF_)-DT*(FV%FACE%FN(IF_)+DHDN))
ENDIF
END SUBROUTINE CC_FV_PROJECT_CUTFACE_VELOCITY

! ------------------------------ CC_PROJECT_VELOCITY -----------------------------

SUBROUTINE CC_PROJECT_VELOCITY(NM,DT,STORE_FLG)
! Predictor U* = U - DT*(F + dH/dn), corrector U = (U_STORE + U* - DT*(F + dH*/dn))/2, on the cut-face pieces (FACE
! rows; the Cartesian face takes their area mean) and on the RC faces, inside and on OPEN boundaries (and interpolated
! ones with ULMAT). A face on a solid, null or mirror wall takes no pressure gradient. Solid Cartesian faces are zero.

USE MEMORY_FUNCTIONS, ONLY: ChkMemErr

INTEGER, INTENT(IN) :: NM
REAL(EB), INTENT(IN):: DT
LOGICAL, INTENT(IN) :: STORE_FLG
REAL(EB), SAVE, ALLOCATABLE, DIMENSION(:,:,:) :: U_STORE,V_STORE,W_STORE
INTEGER :: I,J,K,II,JJ,KK,ICF,LCF,JCF,IZERO,AX,IFACE,IOR,IW,IRC,IVAR
REAL(EB):: IDX,T_NOW,FCTH,VA
REAL(EB), POINTER, DIMENSION(:,:,:) :: HP

T_NOW = CURRENT_TIME()

IF (STORE_FLG) THEN
   ALLOCATE(U_STORE(0:IBP1,0:JBP1,0:KBP1),STAT=IZERO); CALL ChkMemErr('CCIB','U_STORE',IZERO)
   ALLOCATE(V_STORE(0:IBP1,0:JBP1,0:KBP1),STAT=IZERO); CALL ChkMemErr('CCIB','V_STORE',IZERO)
   ALLOCATE(W_STORE(0:IBP1,0:JBP1,0:KBP1),STAT=IZERO); CALL ChkMemErr('CCIB','W_STORE',IZERO)
   U_STORE = U
   V_STORE = V
   W_STORE = W
   T_USED(14) = T_USED(14) + CURRENT_TIME() - T_NOW
   RETURN
ENDIF

HP => H
IVAR = CC_FV_MOM_VELS
IF (.NOT.PREDICTOR) THEN
   HP => HS
   IVAR = CC_FV_MOM_VEL
ENDIF

! In-boundary pieces: no pressure gradient.
DO LCF=1,SIZE(MESHES(NM)%CF_INB)
   ICF=MESHES(NM)%CF_INB(LCF); CF => CUT_FACE(ICF)
   DO JCF=1,CF%NFACE
      CALL CC_FV_PROJECT_CUTFACE_VELOCITY(NM,ICF,JCF,DT,0._EB,DO_VELS=PREDICTOR)
   ENDDO
ENDDO

! Gas cut faces of this mesh's cells (CF_PRJ, the faces FCVAR names there): each piece, then the Cartesian face.
DO LCF=1,SIZE(MESHES(NM)%CF_PRJ)
   ICF=MESHES(NM)%CF_PRJ(LCF); CF => CUT_FACE(ICF)
   I = CF%IJK(IAXIS); J = CF%IJK(JAXIS); K = CF%IJK(KAXIS); AX = CF%IJK(KAXIS+1)
   II = I; JJ = J; KK = K
   SELECT CASE(AX)
   CASE(IAXIS); II = I+1
   CASE(JAXIS); JJ = J+1
   CASE(KAXIS); KK = K+1
   END SELECT
   FCTH = 1._EB
   IF(CF%IWC>0 .AND. ANY(WALL(CF%IWC)%BOUNDARY_TYPE==(/SOLID_BOUNDARY,NULL_BOUNDARY,MIRROR_BOUNDARY/))) FCTH=0._EB
   DO JCF=1,CF%NFACE
      IDX = GET_FV_FACE_RDN(NM,CF%FC(JCF),1._EB/(CF%XCENHIGH(AX,JCF)-CF%XCENLOW(AX,JCF)))
      CALL CC_FV_PROJECT_CUTFACE_VELOCITY(NM,ICF,JCF,DT,FCTH*IDX*(HP(II,JJ,KK)-HP(I,J,K)),DO_VELS=PREDICTOR)
   ENDDO
   VA = CC_FV_CUTFACE_MOM_AREA(NM,ICF,IVAR)
   SELECT CASE(AX)
   CASE(IAXIS)
      IF (PREDICTOR) THEN; US(I,J,K) = VA / (DY(J)*DZ(K)); ELSE; U(I,J,K) = VA / (DY(J)*DZ(K)); ENDIF
   CASE(JAXIS)
      IF (PREDICTOR) THEN; VS(I,J,K) = VA / (DX(I)*DZ(K)); ELSE; V(I,J,K) = VA / (DX(I)*DZ(K)); ENDIF
   CASE(KAXIS)
      IF (PREDICTOR) THEN; WS(I,J,K) = VA / (DY(J)*DX(I)); ELSE; W(I,J,K) = VA / (DY(J)*DX(I)); ENDIF
   END SELECT
ENDDO

! RC faces.
DO IFACE=1,MESHES(NM)%CC_NRCFACE_H
   IRC = MESHES(NM)%RCF_H(IFACE)
   RCF => RC_FACE(IRC)
   FCTH = 1._EB
   IF(RCF%IWC>0 .AND. ANY(WALL(RCF%IWC)%BOUNDARY_TYPE==(/SOLID_BOUNDARY,NULL_BOUNDARY,MIRROR_BOUNDARY/))) FCTH=0._EB
   AX = RCF%IJK(KAXIS+1)
   IDX = GET_FV_FACE_RDN(NM,RCF%FC,1._EB/(RCF%XCEN(AX,HIGH_IND)-RCF%XCEN(AX,LOW_IND)))
   CALL RC_PROJECT(RCF%IJK(IAXIS),RCF%IJK(JAXIS),RCF%IJK(KAXIS),AX,FCTH,IDX)
ENDDO

! RC faces in OPEN boundaries (and interpolated ones with ULMAT).
DO IW=1,N_EXTERNAL_WALL_CELLS
   WC => WALL(IW)
   IF(.NOT.(WC%BOUNDARY_TYPE==OPEN_BOUNDARY .OR. (PRES_FLAG==ULMAT_FLAG .AND. WC%BOUNDARY_TYPE==INTERPOLATED_BOUNDARY))) CYCLE
   BC => BOUNDARY_COORD(WC%BC_INDEX)
   I = BC%IIG; J = BC%JJG; K = BC%KKG; IOR = BC%IOR
   SELECT CASE (IOR)
   CASE( 1); I = BC%IIG-1
   CASE( 2); J = BC%JJG-1
   CASE( 3); K = BC%KKG-1
   END SELECT
   AX = ABS(IOR)
   IRC = FCVAR(I,J,K,CC_IDRC,AX); IF(IRC < 1) CYCLE
   IDX = GET_FV_FACE_RDN(NM,RC_FACE(IRC)%FC,1._EB/(RC_FACE(IRC)%XCEN(AX,HIGH_IND)-RC_FACE(IRC)%XCEN(AX,LOW_IND)))
   CALL RC_PROJECT(I,J,K,AX,-1._EB,IDX)
ENDDO

IF (PREDICTOR) THEN
   WHERE(FCVAR(0:IBAR,1:JBAR,1:KBAR,CC_FGSC,IAXIS)==CC_SOLID) US(0:IBAR,1:JBAR,1:KBAR) = 0._EB
   WHERE(FCVAR(1:IBAR,0:JBAR,1:KBAR,CC_FGSC,JAXIS)==CC_SOLID) VS(1:IBAR,0:JBAR,1:KBAR) = 0._EB
   WHERE(FCVAR(1:IBAR,1:JBAR,0:KBAR,CC_FGSC,KAXIS)==CC_SOLID) WS(1:IBAR,1:JBAR,0:KBAR) = 0._EB
ELSE
   DEALLOCATE(U_STORE,V_STORE,W_STORE)
   WHERE(FCVAR(0:IBAR,1:JBAR,1:KBAR,CC_FGSC,IAXIS)==CC_SOLID) U(0:IBAR,1:JBAR,1:KBAR) = 0._EB
   WHERE(FCVAR(1:IBAR,0:JBAR,1:KBAR,CC_FGSC,JAXIS)==CC_SOLID) V(1:IBAR,0:JBAR,1:KBAR) = 0._EB
   WHERE(FCVAR(1:IBAR,1:JBAR,0:KBAR,CC_FGSC,KAXIS)==CC_SOLID) W(1:IBAR,1:JBAR,0:KBAR) = 0._EB
ENDIF

T_USED(14) = T_USED(14) + CURRENT_TIME() - T_NOW

CONTAINS

SUBROUTINE RC_PROJECT(I,J,K,AX,FCTH,IDX)
! Cartesian RC face (I,J,K) on axis AX. FCTH<0: the boundary form, without the wall factor.
INTEGER, INTENT(IN) :: I,J,K,AX
REAL(EB), INTENT(IN) :: FCTH,IDX
REAL(EB) :: DHDN
SELECT CASE(AX)
CASE(IAXIS)
   DHDN = IDX*(HP(I+1,J,K)-HP(I,J,K)); IF (FCTH>=0._EB) DHDN = FCTH*DHDN
   IF (PREDICTOR) THEN
      US(I,J,K) = U(I,J,K) - DT*( FVX(I,J,K) + DHDN )
   ELSE
      U(I,J,K) = 0.5_EB*( U_STORE(I,J,K) + US(I,J,K) - DT*(FVX(I,J,K) + DHDN) )
   ENDIF
CASE(JAXIS)
   DHDN = IDX*(HP(I,J+1,K)-HP(I,J,K)); IF (FCTH>=0._EB) DHDN = FCTH*DHDN
   IF (PREDICTOR) THEN
      VS(I,J,K) = V(I,J,K) - DT*( FVY(I,J,K) + DHDN )
   ELSE
      V(I,J,K) = 0.5_EB*( V_STORE(I,J,K) + VS(I,J,K) - DT*(FVY(I,J,K) + DHDN) )
   ENDIF
CASE(KAXIS)
   DHDN = IDX*(HP(I,J,K+1)-HP(I,J,K)); IF (FCTH>=0._EB) DHDN = FCTH*DHDN
   IF (PREDICTOR) THEN
      WS(I,J,K) = W(I,J,K) - DT*( FVZ(I,J,K) + DHDN )
   ELSE
      W(I,J,K) = 0.5_EB*( W_STORE(I,J,K) + WS(I,J,K) - DT*(FVZ(I,J,K) + DHDN) )
   ENDIF
END SELECT
END SUBROUTINE RC_PROJECT

END SUBROUTINE CC_PROJECT_VELOCITY

! ------------------------------------ GET_LINKED_VELOCITIES ---------------------------------------

SUBROUTINE GET_LINKED_VELOCITIES(NM,APPLY_TO_ESTIMATED_VARIABLES,CMP_FLG)
! Assumes POINT_TO_MESH(NM) has been called.
! Gather/scatter UNKF-linked velocities in legacy visit order and area formulas.
INTEGER, INTENT(IN) :: NM
LOGICAL, INTENT(IN) :: APPLY_TO_ESTIMATED_VARIABLES, CMP_FLG

INTEGER :: I, J, K, ICF,LCF, JCF, IF_, IL, X1AXIS, IW, IOR, IVAR, N
REAL(EB):: T_NOW
REAL(EB), ALLOCATABLE, DIMENSION(:) :: AREA_LNK
REAL(EB), POINTER, DIMENSION(:,:,:) :: UU,VV,WW
TYPE(CC_FV_TYPE), POINTER :: FV

T_NOW = CURRENT_TIME()
FV=>MESHES(NM)%FV

! Compute linked velocity and populate UN_LNK for MESH(NM):
CMP_FLG_IF : IF (CMP_FLG) THEN
   ! Set linked velocity array to zero:
   UN_LNK = 0._EB
   ALLOCATE(AREA_LNK(0:MESHES(NM)%NUNK_F)); AREA_LNK = 0._EB
   CALL ACCUM_L2_ORDERED_MEAN(NM,MERGE(CC_FV_MOM_VELS,CC_FV_MOM_VEL,APPLY_TO_ESTIMATED_VARIABLES),UN_LNK,AREA_LNK)

   ! Area Average F:
   WHERE (AREA_LNK(1:MESHES(NM)%NUNK_F)>0._EB) &
      UN_LNK(1:MESHES(NM)%NUNK_F) = UN_LNK(1:MESHES(NM)%NUNK_F) / AREA_LNK(1:MESHES(NM)%NUNK_F)

   ! Dump in EWC_UN_LNK(IW) and FACE%VEL_LNK of external boundary regular and cut-faces of type
   ! interpolated boundary:
   EXTERNAL_WALL_LOOP: DO IW=1,MESHES(NM)%N_EXTERNAL_WALL_CELLS
      WC=>WALL(IW)
      IF (WC%BOUNDARY_TYPE/=INTERPOLATED_BOUNDARY) CYCLE EXTERNAL_WALL_LOOP
      EWC=>EXTERNAL_WALL(IW)
      BC =>BOUNDARY_COORD(WC%BC_INDEX)
      I  = BC%II; J = BC%JJ; K = BC%KK
      IOR= BC%IOR; X1AXIS = ABS(IOR)
      SELECT CASE(IOR)
      CASE(-IAXIS); I=I-1
      CASE(-JAXIS); J=J-1
      CASE(-KAXIS); K=K-1
      END SELECT

      ! Default reg faces, unlinked.
      IF(APPLY_TO_ESTIMATED_VARIABLES) THEN
         SELECT CASE(X1AXIS)
         CASE(IAXIS); EWC_UN_LNK(IW) = US(I,J,K)
         CASE(JAXIS); EWC_UN_LNK(IW) = VS(I,J,K)
         CASE(KAXIS); EWC_UN_LNK(IW) = WS(I,J,K)
         END SELECT
      ELSE
         SELECT CASE(X1AXIS)
         CASE(IAXIS); EWC_UN_LNK(IW) = U(I,J,K)
         CASE(JAXIS); EWC_UN_LNK(IW) = V(I,J,K)
         CASE(KAXIS); EWC_UN_LNK(IW) = W(I,J,K)
         END SELECT
      ENDIF
      IF (CC_FV_UNKF_REG(NM,I,J,K,X1AXIS)>0) THEN ! Regular Face, linked.
         EWC_UN_LNK(IW) = UN_LNK(CC_FV_UNKF_REG(NM,I,J,K,X1AXIS))
      ELSEIF(FCVAR(I,J,K,CC_IDRC,X1AXIS)>0) THEN ! RC Face.
         ICF=FCVAR(I,J,K,CC_IDRC,X1AXIS); IL=CC_FV_UNKF_RC(NM,ICF); IF(IL<1) CYCLE EXTERNAL_WALL_LOOP
         EWC_UN_LNK(IW) = UN_LNK(IL)
      ELSEIF(FCVAR(I,J,K,CC_IDCF,X1AXIS)>0) THEN ! Cut-face.
         ICF=FCVAR(I,J,K,CC_IDCF,X1AXIS)
         CF=>CUT_FACE(ICF)
         DO JCF=1,CF%NFACE
            IF_=CF%FC(JCF)
            IF (CC_FV_UNKF_CF(NM,ICF,JCF)>0) THEN
               FV%FACE%VEL_LNK(IF_)=UN_LNK(CC_FV_UNKF_CF(NM,ICF,JCF))
            ELSEIF(APPLY_TO_ESTIMATED_VARIABLES) THEN
               FV%FACE%VEL_LNK(IF_)=CC_FV_CUTFACE_MOM(NM,ICF,JCF,CC_FV_MOM_VELS)
            ELSE
               FV%FACE%VEL_LNK(IF_)=CC_FV_CUTFACE_MOM(NM,ICF,JCF,CC_FV_MOM_VEL)
            ENDIF
         ENDDO
      ENDIF
   ENDDO EXTERNAL_WALL_LOOP

   DEALLOCATE(AREA_LNK)

ELSE CMP_FLG_IF


   ! Restore the linked velocities: the predictor into US,VS,WS and FACE VELS, the corrector into U,V,W and FACE VEL
   ! (it saves the unlinked ones first, on the first pass).
   IF (APPLY_TO_ESTIMATED_VARIABLES) THEN
      UU => US; VV => VS; WW => WS
      IVAR = CC_FV_MOM_VELS
   ELSE
      IF (FIRST_PASS) CALL CC_RESTORE_UVW_UNLINKED(NM,ASSIGN_UNLINKED_VEL=.FALSE.)
      UU => U; VV => V; WW => W
      IVAR = CC_FV_MOM_VEL
   ENDIF
   ! Linked Cartesian (regular and RC) faces, then cut-face pieces.
   DO N=1,SIZE(MESHES(NM)%LNK_CART)
      IF_ = MESHES(NM)%LNK_CART(N)
      I = FV%FACE%IJK_FACE(IAXIS,IF_); J = FV%FACE%IJK_FACE(JAXIS,IF_); K = FV%FACE%IJK_FACE(KAXIS,IF_)
      SELECT CASE(FV%FACE%X1AXIS(IF_))
      CASE(IAXIS); UU(I,J,K) = UN_LNK(FV%FACE%UNKF(IF_))
      CASE(JAXIS); VV(I,J,K) = UN_LNK(FV%FACE%UNKF(IF_))
      CASE(KAXIS); WW(I,J,K) = UN_LNK(FV%FACE%UNKF(IF_))
      END SELECT
   ENDDO
   DO N=1,SIZE(MESHES(NM)%LNK_PIECE)
      IF_ = MESHES(NM)%LNK_PIECE(N)
      CALL SET_PIECE(IF_,UN_LNK(FV%FACE%UNKF(IF_)))
   ENDDO
   DO LCF=1,SIZE(MESHES(NM)%CF_GAS)
      ICF=MESHES(NM)%CF_GAS(LCF); CF => CUT_FACE(ICF)
      IF(TWO_D .AND. CF%IJK(KAXIS+1)==JAXIS) CYCLE
      CALL SET_CARTESIAN(ICF)
   ENDDO
   ! Interpolated boundaries: the matched EWC_UN_LNK(IW) and FACE%VEL_LNK, and the matched OMESH values (for
   ! COMPUTE_VELOCITY_ERROR; the corrector on the first pass only).
   DO IW=1,MESHES(NM)%N_EXTERNAL_WALL_CELLS
      WC=>WALL(IW)
      IF (WC%BOUNDARY_TYPE/=INTERPOLATED_BOUNDARY) CYCLE
      EWC=>EXTERNAL_WALL(IW)
      BC =>BOUNDARY_COORD(WC%BC_INDEX)
      I  = BC%II; J = BC%JJ; K = BC%KK
      IOR= BC%IOR; X1AXIS = ABS(IOR)
      SELECT CASE(IOR)
      CASE(-IAXIS); I=I-1
      CASE(-JAXIS); J=J-1
      CASE(-KAXIS); K=K-1
      END SELECT
      IF(FCVAR(I,J,K,CC_IDCF,X1AXIS)>0) THEN ! Cut-face.
         ICF=FCVAR(I,J,K,CC_IDCF,X1AXIS); CF=>CUT_FACE(ICF)
         DO JCF=1,CF%NFACE
            CALL SET_PIECE(CF%FC(JCF),FV%FACE%VEL_LNK(CF%FC(JCF)))
         ENDDO
         CALL SET_CARTESIAN(ICF)
      ELSE ! All other reg faces, unlinked, yet can be matched to linked velocities in OMESH.
         SELECT CASE(X1AXIS)
         CASE(IAXIS); UU(I,J,K) = EWC_UN_LNK(IW)
         CASE(JAXIS); VV(I,J,K) = EWC_UN_LNK(IW)
         CASE(KAXIS); WW(I,J,K) = EWC_UN_LNK(IW)
         END SELECT
      ENDIF
      IF (APPLY_TO_ESTIMATED_VARIABLES .OR. FIRST_PASS) CALL SET_OMESH(IOR)
   ENDDO

ENDIF CMP_FLG_IF


T_USED(14) = T_USED(14) + CURRENT_TIME() - T_NOW

CONTAINS

SUBROUTINE SET_PIECE(IF_,VAL)
INTEGER, INTENT(IN) :: IF_
REAL(EB), INTENT(IN) :: VAL
IF (APPLY_TO_ESTIMATED_VARIABLES) THEN
   FV%FACE%VELS(IF_) = VAL
ELSE
   FV%FACE%VEL(IF_) = VAL
ENDIF
END SUBROUTINE SET_PIECE

SUBROUTINE SET_CARTESIAN(ICF)
! The Cartesian face of cut face ICF takes the area mean of its pieces.
INTEGER, INTENT(IN) :: ICF
INTEGER :: I,J,K
I = CUT_FACE(ICF)%IJK(IAXIS); J = CUT_FACE(ICF)%IJK(JAXIS); K = CUT_FACE(ICF)%IJK(KAXIS)
SELECT CASE(CUT_FACE(ICF)%IJK(KAXIS+1))
CASE(IAXIS); UU(I,J,K) = CC_FV_CUTFACE_MOM_AREA(NM,ICF,IVAR) / (DY(J)*DZ(K))
CASE(JAXIS); VV(I,J,K) = CC_FV_CUTFACE_MOM_AREA(NM,ICF,IVAR) / (DX(I)*DZ(K))
CASE(KAXIS); WW(I,J,K) = CC_FV_CUTFACE_MOM_AREA(NM,ICF,IVAR) / (DY(J)*DX(I))
END SELECT
END SUBROUTINE SET_CARTESIAN

SUBROUTINE SET_OMESH(IOR)
! The neighbour's faces across wall cell IW: a cut face takes its matched halo row, a regular face U_LNK, V_LNK or W_LNK.
INTEGER, INTENT(IN) :: IOR
INTEGER :: AX,IIO,JJO,KKO,IO,JO,KO,DIJK(IAXIS:KAXIS),ICFO,IROW,NF
TYPE(OMESH_TYPE), POINTER :: OM
TYPE(MESH_TYPE), POINTER :: M2
OM => OMESH(EWC%NOM)
M2 => MESHES(EWC%NOM)
AX = ABS(IOR)
DIJK = 0
IF (IOR<0) DIJK(AX) = -1
DO KKO=EWC%KKO_MIN,EWC%KKO_MAX
   DO JJO=EWC%JJO_MIN,EWC%JJO_MAX
      DO IIO=EWC%IIO_MIN,EWC%IIO_MAX
         IF (M2%CELL(M2%CELL_INDEX(IIO,JJO,KKO))%SOLID) CYCLE
         IO = IIO+DIJK(IAXIS); JO = JJO+DIJK(JAXIS); KO = KKO+DIJK(KAXIS)
         IF (M2%FCVAR(IO,JO,KO,CC_FGSC,AX)==CC_SOLID) CYCLE
         ICFO = M2%FCVAR(IO,JO,KO,CC_IDCF,AX)
         IF (ICFO>0) THEN
            IROW = OM%CFHALO_ROW0(ICFO)
            NF = M2%CUT_FACE(ICFO)%NFACE
            IF (APPLY_TO_ESTIMATED_VARIABLES) THEN
               OM%CFHALO_VELS(IROW:IROW+NF-1) = OM%CFHALO_VEL_LNK(IROW:IROW+NF-1)
            ELSE
               OM%CFHALO_VEL(IROW:IROW+NF-1) = OM%CFHALO_VEL_LNK(IROW:IROW+NF-1)
            ENDIF
         ELSEIF (APPLY_TO_ESTIMATED_VARIABLES) THEN
            SELECT CASE(AX)
            CASE(IAXIS); OM%US(IO,JO,KO) = OM%U_LNK(IO,JO,KO)
            CASE(JAXIS); OM%VS(IO,JO,KO) = OM%V_LNK(IO,JO,KO)
            CASE(KAXIS); OM%WS(IO,JO,KO) = OM%W_LNK(IO,JO,KO)
            END SELECT
         ELSE
            SELECT CASE(AX)
            CASE(IAXIS); OM%U(IO,JO,KO) = OM%U_LNK(IO,JO,KO)
            CASE(JAXIS); OM%V(IO,JO,KO) = OM%V_LNK(IO,JO,KO)
            CASE(KAXIS); OM%W(IO,JO,KO) = OM%W_LNK(IO,JO,KO)
            END SELECT
         ENDIF
      ENDDO
   ENDDO
ENDDO
END SUBROUTINE SET_OMESH

END SUBROUTINE GET_LINKED_VELOCITIES

SUBROUTINE ACCUM_L2_ORDERED_MEAN(NM,KQ,SUM_LNK,AREA_LNK)
! Sum quantity KQ (a CC_FV_MOM_* selector, or 0 for LM%V) over each link group's members in one global order (axis, then x, y,
! z), so one mesh and several give the same mean. A group held by several meshes takes the sums of L2_CROSS_SUMS.
INTEGER, INTENT(IN) :: NM,KQ
REAL(EB), INTENT(INOUT) :: SUM_LNK(0:),AREA_LNK(0:)
INTEGER :: P,IL
REAL(EB), POINTER, DIMENSION(:,:,:) :: PX,PY,PZ
TYPE(L2_MEAN_TYPE), POINTER :: LM
LM => L2_MEAN(NM)
CALL L2_KQ_ARRAYS(KQ,PX,PY,PZ)
DO P=1,LM%N
   IL = LM%M(2,P)
   IF (LM%XG(IL)>0) CYCLE
   SUM_LNK(IL) = SUM_LNK(IL)+L2_MEMBER_VAL(NM,LM,P,KQ,PX,PY,PZ)*LM%A(P)
   AREA_LNK(IL) = AREA_LNK(IL)+LM%A(P)
ENDDO
DO IL=1,MESHES(NM)%NUNK_F
   IF (LM%XG(IL)<1) CYCLE
   SUM_LNK(IL) = L2_XS(1,LM%XG(IL))
   AREA_LNK(IL) = L2_XS(2,LM%XG(IL))
ENDDO
END SUBROUTINE ACCUM_L2_ORDERED_MEAN

SUBROUTINE L2_KQ_ARRAYS(KQ,PX,PY,PZ)
! Cartesian face arrays of quantity KQ for the mesh pointed to.
INTEGER, INTENT(IN) :: KQ
REAL(EB), POINTER, DIMENSION(:,:,:), INTENT(OUT) :: PX,PY,PZ
SELECT CASE(KQ)
CASE(CC_FV_MOM_VEL);  PX => U;     PY => V;     PZ => W
CASE(CC_FV_MOM_VELS); PX => US;    PY => VS;    PZ => WS
CASE(CC_FV_MOM_FN);   PX => FVX;   PY => FVY;   PZ => FVZ
CASE(CC_FV_MOM_FN_B); PX => FVX_B; PY => FVY_B; PZ => FVZ_B
CASE DEFAULT;         NULLIFY(PX,PY,PZ)
END SELECT
END SUBROUTINE L2_KQ_ARRAYS

REAL(EB) FUNCTION L2_MEMBER_VAL(NM,LM,P,KQ,PX,PY,PZ)
! Quantity KQ of held link-group member P (mesh NM pointed to; PX, PY, PZ from L2_KQ_ARRAYS); KQ=0: LM%V(P).
INTEGER, INTENT(IN) :: NM,P,KQ
TYPE(L2_MEAN_TYPE), INTENT(IN) :: LM
REAL(EB), POINTER, DIMENSION(:,:,:), INTENT(IN) :: PX,PY,PZ
IF (KQ==0) THEN
   L2_MEMBER_VAL = LM%V(P)
   RETURN
ENDIF
SELECT CASE(LM%M(1,P))
CASE(IAXIS);  L2_MEMBER_VAL = PX(LM%M(3,P),LM%M(4,P),LM%M(5,P))
CASE(JAXIS);  L2_MEMBER_VAL = PY(LM%M(3,P),LM%M(4,P),LM%M(5,P))
CASE(KAXIS);  L2_MEMBER_VAL = PZ(LM%M(3,P),LM%M(4,P),LM%M(5,P))
CASE DEFAULT; L2_MEMBER_VAL = CC_FV_CUTFACE_MOM(NM,LM%M(3,P),LM%M(4,P),KQ)
END SELECT
END FUNCTION L2_MEMBER_VAL

SUBROUTINE L2_CROSS_SUMS(KQ)
! Sums of q*A and A, q = quantity KQ (a CC_FV_MOM_* selector), of every link group held by several meshes; a
! member counts once, on its lowest mesh. Every process calls this before the per-mesh means.
USE MPI_F08
INTEGER, INTENT(IN) :: KQ
INTEGER :: NM,P,X,IERR
REAL(EB), POINTER, DIMENSION(:,:,:) :: PX,PY,PZ
TYPE(L2_MEAN_TYPE), POINTER :: LM
IF (.NOT.ALLOCATED(L2_XS)) RETURN
L2_XS = 0._EB
DO NM=LOWER_MESH_INDEX,UPPER_MESH_INDEX
   CALL POINT_TO_MESH(NM)
   CALL L2_KQ_ARRAYS(KQ,PX,PY,PZ)
   LM => L2_MEAN(NM)
   DO P=1,LM%N
      X = LM%XG(LM%M(2,P))
      IF (X<1 .OR. LM%M(6,P)==0) CYCLE
      L2_XS(1,X) = L2_XS(1,X)+L2_MEMBER_VAL(NM,LM,P,KQ,PX,PY,PZ)*LM%A(P)
      L2_XS(2,X) = L2_XS(2,X)+LM%A(P)
   ENDDO
ENDDO
CALL MPI_ALLREDUCE(MPI_IN_PLACE,L2_XS,SIZE(L2_XS),MPI_DOUBLE_PRECISION,MPI_SUM,MPI_COMM_WORLD,IERR)
END SUBROUTINE L2_CROSS_SUMS

SUBROUTINE L2_ADD_GUARD_CF_REQUEST(NM,NOM,DO_FILL,NBASE)
! Numbered guard cuts whose owner face is not already on the interpolated-wall list.
INTEGER, INTENT(IN) :: NM,NOM,NBASE
LOGICAL, INTENT(IN) :: DO_FILL
INTEGER :: IW,IIO,JJO,KKO,IIOF,JJOF,KKOF,ICF,ICF2,JCF,JC2,AX,SLOT
LOGICAL, ALLOCATABLE :: SEEN(:)
TYPE(MESH_TYPE), POINTER :: M1,M2
TYPE(OMESH_TYPE), POINTER :: M3
TYPE(WALL_TYPE), POINTER :: WC
TYPE(EXTERNAL_WALL_TYPE), POINTER :: EWC
TYPE(BOUNDARY_COORD_TYPE), POINTER :: BC
TYPE(CC_CUTFACE_TYPE), POINTER :: CF,CF2
REAL(EB) :: XX,YY,ZZ
IF (NM==NOM) RETURN
M1 => MESHES(NM)
M2 => MESHES(NOM)
M3 => MESHES(NM)%OMESH(NOM)
IF (M1%N_GCCUTFACE_MESH<1) RETURN
ALLOCATE(SEEN(M2%N_CUTFACE_MESH+M2%N_GCCUTFACE_MESH))
SEEN = .FALSE.
CALL POINT_TO_MESH(NM)
DO IW=1,N_EXTERNAL_WALL_CELLS
   WC => WALL(IW)
   IF (WC%BOUNDARY_TYPE/=INTERPOLATED_BOUNDARY) CYCLE
   EWC => EXTERNAL_WALL(IW)
   IF (EWC%NOM/=NOM) CYCLE
   BC => BOUNDARY_COORD(WC%BC_INDEX)
   DO KKO=EWC%KKO_MIN,EWC%KKO_MAX
      DO JJO=EWC%JJO_MIN,EWC%JJO_MAX
         DO IIO=EWC%IIO_MIN,EWC%IIO_MAX
            IIOF = IIO; JJOF = JJO; KKOF = KKO
            SELECT CASE(-BC%IOR)
            CASE( IAXIS); IIOF = IIO-1
            CASE( JAXIS); JJOF = JJO-1
            CASE( KAXIS); KKOF = KKO-1
            END SELECT
            ICF = MESHES(NOM)%FCVAR(IIOF,JJOF,KKOF,CC_IDCF,ABS(BC%IOR))
            IF (ICF>=1 .AND. ICF<=SIZE(SEEN)) SEEN(ICF) = .TRUE.
         ENDDO
      ENDDO
   ENDDO
ENDDO
SLOT = NBASE
DO ICF=M1%N_CUTFACE_MESH+1,M1%N_CUTFACE_MESH+M1%N_GCCUTFACE_MESH
   CF => M1%CUT_FACE(ICF)
   IF (CF%STATUS/=CC_GASPHASE) CYCLE
   IF (.NOT.ALLOCATED(CF%XYZCEN)) CYCLE
   AX = CF%IJK(KAXIS+1)
   DO JCF=1,CF%NFACE
      IF (CC_FV_UNKF_CF(NM,ICF,JCF)<1) CYCLE
      IF (JCF>SIZE(CF%XYZCEN,DIM=2)) CYCLE
      XX = CF%XYZCEN(IAXIS,JCF)
      YY = CF%XYZCEN(JAXIS,JCF)
      ZZ = CF%XYZCEN(KAXIS,JCF)
      DO ICF2=1,M2%N_CUTFACE_MESH
         IF (SEEN(ICF2)) CYCLE
         CF2 => M2%CUT_FACE(ICF2)
         IF (CF2%STATUS/=CC_GASPHASE) CYCLE
         IF (CF2%IJK(KAXIS+1)/=AX) CYCLE
         IF (.NOT.ALLOCATED(CF2%XYZCEN)) CYCLE
         DO JC2=1,CF2%NFACE
            IF (JC2>SIZE(CF2%XYZCEN,DIM=2)) CYCLE
            IF (ABS(CF2%XYZCEN(IAXIS,JC2)-XX)>1.E-7_EB) CYCLE
            IF (ABS(CF2%XYZCEN(JAXIS,JC2)-YY)>1.E-7_EB) CYCLE
            IF (ABS(CF2%XYZCEN(KAXIS,JC2)-ZZ)>1.E-7_EB) CYCLE
            SEEN(ICF2) = .TRUE.
            IF (DO_FILL) THEN
               SLOT = SLOT+1
               M3%ICF_UFFB_CF_R(4*SLOT-3:4*SLOT) = (/CF2%IJK(IAXIS),CF2%IJK(JAXIS),CF2%IJK(KAXIS),AX/)
            ELSE
               M3%NICF_R(1) = M3%NICF_R(1)+1
               M3%NICF_R(2) = M3%NICF_R(2)+CF2%NFACE
            ENDIF
            EXIT
         ENDDO
         IF (SEEN(ICF2)) EXIT
      ENDDO
   ENDDO
ENDDO
END SUBROUTINE L2_ADD_GUARD_CF_REQUEST



! --------------------------- CC_RESTORE_UVW_UNLINKED -------------------------

SUBROUTINE CC_RESTORE_UVW_UNLINKED(NM,ASSIGN_UNLINKED_VEL)
! Save (ASSIGN_UNLINKED_VEL false) or put back (true) the unlinked velocities of the linked faces and of the faces on
! interpolated boundaries, in one order: the linked Cartesian faces, the linked cut pieces, then the external
! wall cells (ALLOC_LINK_STORAGE sizes UN_ULNK the same way).
! NOTE : If ASSIGN_UNLINKED_VEL=.FALSE. assumes point to mesh has been called.
INTEGER, INTENT(IN) :: NM
LOGICAL, INTENT(IN) :: ASSIGN_UNLINKED_VEL
INTEGER :: I,J,K,AX,ICF,JCF,IF_,COUNT,IW,N
REAL(EB):: T_NOW
TYPE(CC_FV_TYPE), POINTER :: FV

T_NOW = CURRENT_TIME()
FV=>MESHES(NM)%FV
COUNT = 0
IF (ASSIGN_UNLINKED_VEL) CALL POINT_TO_MESH(NM)

DO N=1,SIZE(MESHES(NM)%LNK_CART)
   IF_ = MESHES(NM)%LNK_CART(N)
   I = FV%FACE%IJK_FACE(IAXIS,IF_); J = FV%FACE%IJK_FACE(JAXIS,IF_); K = FV%FACE%IJK_FACE(KAXIS,IF_)
   SELECT CASE(FV%FACE%X1AXIS(IF_))
   CASE(IAXIS); CALL SWAP(U(I,J,K))
   CASE(JAXIS); CALL SWAP(V(I,J,K))
   CASE(KAXIS); CALL SWAP(W(I,J,K))
   END SELECT
ENDDO
DO N=1,SIZE(MESHES(NM)%LNK_PIECE)
   CALL SWAP(FV%FACE%VEL(MESHES(NM)%LNK_PIECE(N)))
ENDDO
DO IW=1,MESHES(NM)%N_EXTERNAL_WALL_CELLS
   WC=>WALL(IW)
   IF (WC%BOUNDARY_TYPE/=INTERPOLATED_BOUNDARY) CYCLE
   EWC=>EXTERNAL_WALL(IW)
   BC =>BOUNDARY_COORD(WC%BC_INDEX)
   I  = BC%II; J = BC%JJ; K = BC%KK; AX = ABS(BC%IOR)
   SELECT CASE(BC%IOR)
   CASE(-IAXIS); I=I-1
   CASE(-JAXIS); J=J-1
   CASE(-KAXIS); K=K-1
   END SELECT
   IF(FCVAR(I,J,K,CC_IDCF,AX)>0) THEN ! Cut-face.
      ICF=FCVAR(I,J,K,CC_IDCF,AX); CF=>CUT_FACE(ICF)
      DO JCF=1,CF%NFACE
         CALL SWAP(FV%FACE%VEL(CF%FC(JCF)))
      ENDDO
      IF (ASSIGN_UNLINKED_VEL) THEN
         SELECT CASE(AX)
         CASE(IAXIS); U(I,J,K) = CC_FV_CUTFACE_MOM_AREA(NM,ICF,CC_FV_MOM_VEL) / (DY(J)*DZ(K))
         CASE(JAXIS); V(I,J,K) = CC_FV_CUTFACE_MOM_AREA(NM,ICF,CC_FV_MOM_VEL) / (DX(I)*DZ(K))
         CASE(KAXIS); W(I,J,K) = CC_FV_CUTFACE_MOM_AREA(NM,ICF,CC_FV_MOM_VEL) / (DY(J)*DX(I))
         END SELECT
      ENDIF
   ELSE ! All other reg faces.
      SELECT CASE(AX)
      CASE(IAXIS); CALL SWAP(U(I,J,K))
      CASE(JAXIS); CALL SWAP(V(I,J,K))
      CASE(KAXIS); CALL SWAP(W(I,J,K))
      END SELECT
   ENDIF
ENDDO

T_USED(14) = T_USED(14) + CURRENT_TIME() - T_NOW

CONTAINS

SUBROUTINE SWAP(X)
REAL(EB), INTENT(INOUT) :: X
COUNT = COUNT+1
IF (ASSIGN_UNLINKED_VEL) THEN
   X = UN_ULNK(COUNT)
ELSE
   UN_ULNK(COUNT) = X
ENDIF
END SUBROUTINE SWAP

END SUBROUTINE CC_RESTORE_UVW_UNLINKED


! ------------------------------- CC_COMPUTE_KRES -----------------------------

SUBROUTINE CC_COMPUTE_KRES(APPLY_TO_ESTIMATED_VARIABLES,NM)

LOGICAL, INTENT(IN) :: APPLY_TO_ESTIMATED_VARIABLES
INTEGER, INTENT(IN) :: NM

INTEGER :: ICC,I,J,K,JCC
REAL(EB):: T_NOW,PRFCT,UVWAV(MAX_DIM),ATOTV(MAX_DIM),UVWAV_AUX(MAX_DIM),ATOTV_AUX(MAX_DIM),KRES_CC
TYPE(CC_FV_TYPE), POINTER :: FV

T_NOW = CURRENT_TIME()
FV=>MESHES(NM)%FV

PRFCT = 0._EB; IF(APPLY_TO_ESTIMATED_VARIABLES) PRFCT = 1._EB
CUTCELL_DO : DO ICC=1,MESHES(NM)%N_CUTCELL_MESH
   CC => CUT_CELL(ICC); I = CC%IJK(IAXIS); J = CC%IJK(JAXIS); K = CC%IJK(KAXIS); IF (CELL(CELL_INDEX(I,J,K))%SOLID) CYCLE
   ATOTV(:) = 0._EB; UVWAV(:) = 0._EB
   DO JCC=1,CC%NCELL
      CALL CC_CUTCELL_VELOCITY(NM,PRFCT,ICC,JCC,UVWAV_AUX,ATOTV_AUX,RETURN_INTEGRALS=.TRUE.)
      UVWAV = UVWAV + UVWAV_AUX
      ATOTV = ATOTV + ATOTV_AUX
   ENDDO
   WHERE(ATOTV>TWENTY_EPSILON_EB) UVWAV = UVWAV / ATOTV
   KRES_CC = 0.5_EB*(UVWAV(IAXIS)**2._EB+UVWAV(JAXIS)**2._EB+UVWAV(KAXIS)**2._EB)
   DO JCC=1,CC%NCELL
      FV%CV%KRES(CC%IG(JCC)) = KRES_CC
   ENDDO
   KRES(I,J,K) = KRES_CC
ENDDO CUTCELL_DO

T_USED(14) = T_USED(14) + CURRENT_TIME() - T_NOW
RETURN
END SUBROUTINE CC_COMPUTE_KRES


! ------------------------------- CC_CUTCELL_VELOCITY -------------------------------

SUBROUTINE CC_CUTCELL_VELOCITY(NM,PRFCT,ICC,JCC,UVWAV,ATOTV,RETURN_INTEGRALS)

! Routine computes area averaged velocity vector for a cut-cell ICC, JCC.
! Areas used for each component are the projected areas in the component direction.

INTEGER,  INTENT(IN) :: NM,ICC,JCC
REAL(EB), INTENT(IN) :: PRFCT  ! If 1._EB use US,VS,WS velocities, if 0._EB use U,V,W velocities.
REAL(EB), INTENT(OUT):: UVWAV(MAX_DIM),ATOTV(MAX_DIM)
LOGICAL,  INTENT(IN) :: RETURN_INTEGRALS

! Local Variables:
INTEGER :: I,J,K,IFC,IFACE,LOWHIGH,X1AXIS,ILH,IFC2,IFACE2,ICFA,IRC
REAL(EB):: AUI,AF,VELN

ATOTV(:) = 0._EB; UVWAV(:) = 0._EB
CC => CUT_CELL(ICC); I = CC%IJK(IAXIS); J = CC%IJK(JAXIS); K = CC%IJK(KAXIS)

IFC_LOOP : DO IFC=1,CC%CCELEM(1,JCC)
   IFACE = CC%CCELEM(IFC+1,JCC)
   SELECT CASE(CC%FACE_LIST(1,IFACE))
   CASE(CC_FTYPE_RCGAS) ! REGULAR GASPHASE
      LOWHIGH = CC%FACE_LIST(2,IFACE)
      X1AXIS  = CC%FACE_LIST(3,IFACE)
      ILH     = LOWHIGH - 1
      SELECT CASE(X1AXIS)
      CASE(IAXIS); IRC=FCVAR(I-1+ILH,J,K,CC_IDRC,IAXIS)
      CASE(JAXIS); IRC=FCVAR(I,J-1+ILH,K,CC_IDRC,JAXIS)
      CASE(KAXIS); IRC=FCVAR(I,J,K-1+ILH,CC_IDRC,KAXIS)
      END SELECT
      SELECT CASE(X1AXIS)
      CASE(IAXIS); AF=DY(J)*DZ(K); VELN=PRFCT*US(I-1+ILH,J,K)+(1._EB-PRFCT)*U(I-1+ILH,J,K)
      CASE(JAXIS); AF=DX(I)*DZ(K); VELN=PRFCT*VS(I,J-1+ILH,K)+(1._EB-PRFCT)*V(I,J-1+ILH,K)
      CASE(KAXIS); AF=DX(I)*DY(J); VELN=PRFCT*WS(I,J,K-1+ILH)+(1._EB-PRFCT)*W(I,J,K-1+ILH)
      END SELECT
      ATOTV(X1AXIS) = ATOTV(X1AXIS) + AF
      UVWAV(X1AXIS) = UVWAV(X1AXIS) + VELN * AF
   CASE(CC_FTYPE_CFGAS) ! GASPHASE CUT FACE:
      LOWHIGH = CC%FACE_LIST(2,IFACE)
      IFC2    = CC%FACE_LIST(4,IFACE)
      IFACE2  = CC%FACE_LIST(5,IFACE)
      X1AXIS  = CUT_FACE(IFC2)%IJK(KAXIS+1)
      AF      = CUT_FACE(IFC2)%AREA(IFACE2)
      VELN = PRFCT*CC_FV_CUTFACE_MOM(NM,IFC2,IFACE2,CC_FV_MOM_VELS) + &
             (1._EB-PRFCT)*CC_FV_CUTFACE_MOM(NM,IFC2,IFACE2,CC_FV_MOM_VEL)
      ATOTV(X1AXIS) = ATOTV(X1AXIS) + AF
      UVWAV(X1AXIS) = UVWAV(X1AXIS) + VELN * AF
   CASE(CC_FTYPE_CFINB) ! INBOUNDARY CUT FACE: Note here we add U_NORMAL with Transpiration velocity due to
                           ! Poisson solver velocity error.
      IFC2    = CC%FACE_LIST(4,IFACE)
      IFACE2  = CC%FACE_LIST(5,IFACE)
      ICFA    = CUT_FACE(IFC2)%CFACE_INDEX(IFACE2)
      AF      = CUT_FACE(IFC2)%AREA(IFACE2)
      VELN = (1._EB-PRFCT)*CC_FV_CUTFACE_MOM(NM,IFC2,IFACE2,CC_FV_MOM_VEL) + &
             PRFCT*CC_FV_CUTFACE_MOM(NM,IFC2,IFACE2,CC_FV_MOM_VELS)
      ! - to use velocity into gasphase, projected area.
      BC => MESHES(NM)%BOUNDARY_COORD(CFACE(ICFA)%BC_INDEX)
      DO X1AXIS=IAXIS,KAXIS
         AUI  = ABS(BC%NVEC(X1AXIS)*AF)
         ATOTV(X1AXIS) = ATOTV(X1AXIS) + AUI
         UVWAV(X1AXIS) = UVWAV(X1AXIS) - VELN*BC%NVEC(X1AXIS)*AUI
      ENDDO
   END SELECT
ENDDO IFC_LOOP
IF(.NOT.RETURN_INTEGRALS) WHERE(ATOTV>TWENTY_EPSILON_EB) UVWAV = UVWAV / ATOTV

END SUBROUTINE CC_CUTCELL_VELOCITY

! --------------------------- CC_EXCHANGE_UNPACKING_ARRAYS --------------------------

SUBROUTINE CC_EXCHANGE_UNPACKING_ARRAYS()

! Local Variables:
INTEGER :: NM,NOM,NOOM,IFEP,ICD_SGN
TYPE (MESH_TYPE), POINTER :: M
TYPE (OMESH_TYPE), POINTER :: M2
INTEGER :: EP,INPE,INT_NPE_LO,INT_NPE_HI,VIND,IEDGE

RECV_MESH_LOOP: DO NOM=LOWER_MESH_INDEX,UPPER_MESH_INDEX

   M =>MESHES(NOM)

   SEND_MESH_LOOP: DO NM=1,NMESHES

      M2=>MESHES(NOM)%OMESH(NM)

      ! Boundary and gasphase cut-faces and rcedges, face centered variables for interpolation:
      CF_FC_IF : IF(M2%NFCC_R(1)>0) THEN
         ! RCEDGES:
         ! Count:
         DO IEDGE=1,M%CC_NRCEDGE
            DO EP=1,INT_N_EXT_PTS  ! External point for face IEDGE
               DO VIND=IAXIS,KAXIS ! Velocity component U, V or W for external point EP
                  INT_NPE_LO = M%CC_RCEDGE(IEDGE)%INT_NPE(LOW_IND,VIND,EP,0)
                  INT_NPE_HI = M%CC_RCEDGE(IEDGE)%INT_NPE(HIGH_IND,VIND,EP,0)
                  DO INPE=INT_NPE_LO+1,INT_NPE_LO+INT_NPE_HI
                     NOOM   = M%CC_RCEDGE(IEDGE)%INT_NOMIND( LOW_IND,INPE); IF (NOOM /= NM) CYCLE
                     M2%NFEP_R(3) = M2%NFEP_R(3) + 1
                  ENDDO
               ENDDO
            ENDDO
         ENDDO
         IF (M2%NFEP_R(3) > 0) THEN
            ! Allocate:
            IF (ALLOCATED(M2%IFEP_R_3)) DEALLOCATE(M2%IFEP_R_3)
            ALLOCATE(M2%IFEP_R_3(LOW_IND:HIGH_IND,M2%NFEP_R(3))); M2%IFEP_R_3 = CC_UNDEFINED
            ! Add index entries:
            IFEP = 0
            DO IEDGE=1,M%CC_NRCEDGE
               DO EP=1,INT_N_EXT_PTS  ! External point for face IEDGE
                  DO VIND=IAXIS,KAXIS ! Velocity component U, V or W for external point EP
                     INT_NPE_LO = M%CC_RCEDGE(IEDGE)%INT_NPE(LOW_IND,VIND,EP,0)
                     INT_NPE_HI = M%CC_RCEDGE(IEDGE)%INT_NPE(HIGH_IND,VIND,EP,0)
                     DO INPE=INT_NPE_LO+1,INT_NPE_LO+INT_NPE_HI
                        NOOM   = M%CC_RCEDGE(IEDGE)%INT_NOMIND( LOW_IND,INPE); IF (NOOM /= NM) CYCLE
                        IFEP = IFEP + 1
                        M2%IFEP_R_3( LOW_IND:HIGH_IND,IFEP) = (/ IEDGE, INPE /)
                     ENDDO
                  ENDDO
               ENDDO
            ENDDO
         ENDIF

         ! Then IBEDGES:
         ! Count:
         DO IEDGE=1,M%CC_NIBEDGE
            DO ICD_SGN=-2,2
               IF(ICD_SGN==0) CYCLE
               DO EP=1,INT_N_EXT_PTS  ! External point for face IEDGE
                  DO VIND=IAXIS,KAXIS ! Velocity component U, V or W for external point EP
                    INT_NPE_LO = M%CC_IBEDGE(IEDGE)%INT_NPE(LOW_IND,VIND,EP,ICD_SGN)
                    INT_NPE_HI = M%CC_IBEDGE(IEDGE)%INT_NPE(HIGH_IND,VIND,EP,ICD_SGN)
                    DO INPE=INT_NPE_LO+1,INT_NPE_LO+INT_NPE_HI
                       NOOM   = M%CC_IBEDGE(IEDGE)%INT_NOMIND( LOW_IND,INPE); IF (NOOM /= NM) CYCLE
                       M2%NFEP_R(4) = M2%NFEP_R(4) + 1
                    ENDDO
                 ENDDO
               ENDDO
            ENDDO
         ENDDO
         IF (M2%NFEP_R(4) > 0) THEN
            ! Allocate:
            IF (ALLOCATED(M2%IFEP_R_4)) DEALLOCATE(M2%IFEP_R_4)
            ALLOCATE(M2%IFEP_R_4(LOW_IND:HIGH_IND,M2%NFEP_R(4))); M2%IFEP_R_4 = CC_UNDEFINED
            ! Add index entries:
            IFEP = 0
            DO IEDGE=1,M%CC_NIBEDGE
               DO ICD_SGN=-2,2
                  IF(ICD_SGN==0) CYCLE
                  DO EP=1,INT_N_EXT_PTS  ! External point for face IEDGE
                     DO VIND=IAXIS,KAXIS ! Velocity component U, V or W for external point EP
                        INT_NPE_LO = M%CC_IBEDGE(IEDGE)%INT_NPE(LOW_IND,VIND,EP,ICD_SGN)
                        INT_NPE_HI = M%CC_IBEDGE(IEDGE)%INT_NPE(HIGH_IND,VIND,EP,ICD_SGN)
                        DO INPE=INT_NPE_LO+1,INT_NPE_LO+INT_NPE_HI
                           NOOM   = M%CC_IBEDGE(IEDGE)%INT_NOMIND( LOW_IND,INPE); IF (NOOM /= NM) CYCLE
                           IFEP = IFEP + 1
                           M2%IFEP_R_4( LOW_IND:HIGH_IND,IFEP) = (/ IEDGE, INPE /)
                        ENDDO
                     ENDDO
                  ENDDO
               ENDDO
            ENDDO
         ENDIF
      ENDIF CF_FC_IF

      ! Boundary cut-faces, cell centered variables for interpolation:
      BNDCF_CC_IF : IF(M2%NFCC_R(2)>0) THEN
         VIND = 0 ! Cell centered variables.
         ! Case of IBEDGES:
         ! Count:
         DO IEDGE=1,M%CC_NIBEDGE
            DO ICD_SGN=-2,2
               IF(ICD_SGN==0) CYCLE
               DO EP=1,INT_N_EXT_PTS  ! External point for face IEDGE
                  INT_NPE_LO = M%CC_IBEDGE(IEDGE)%INT_NPE(LOW_IND,VIND,EP,ICD_SGN)
                  INT_NPE_HI = M%CC_IBEDGE(IEDGE)%INT_NPE(HIGH_IND,VIND,EP,ICD_SGN)
                  DO INPE=INT_NPE_LO+1,INT_NPE_LO+INT_NPE_HI
                     NOOM   = M%CC_IBEDGE(IEDGE)%INT_NOMIND( LOW_IND,INPE); IF (NOOM /= NM) CYCLE
                     M2%NFEP_R(5) = M2%NFEP_R(5) + 1
                  ENDDO
               ENDDO
            ENDDO
         ENDDO
         IF (M2%NFEP_R(5)>0) THEN
            ! Allocate:
            IF (ALLOCATED(M2%IFEP_R_5)) DEALLOCATE(M2%IFEP_R_5)
            ALLOCATE(M2%IFEP_R_5(LOW_IND:HIGH_IND,M2%NFEP_R(5))); M2%IFEP_R_5 = CC_UNDEFINED
            ! Add index entries:
            IFEP = 0
            DO IEDGE=1,M%CC_NIBEDGE
               DO ICD_SGN=-2,2
                  IF(ICD_SGN==0) CYCLE
                  DO EP=1,INT_N_EXT_PTS  ! External point for face IEDGE
                     INT_NPE_LO = M%CC_IBEDGE(IEDGE)%INT_NPE(LOW_IND,VIND,EP,ICD_SGN)
                     INT_NPE_HI = M%CC_IBEDGE(IEDGE)%INT_NPE(HIGH_IND,VIND,EP,ICD_SGN)
                     DO INPE=INT_NPE_LO+1,INT_NPE_LO+INT_NPE_HI
                        NOOM   = M%CC_IBEDGE(IEDGE)%INT_NOMIND( LOW_IND,INPE); IF (NOOM /= NM) CYCLE
                        IFEP = IFEP + 1
                        M2%IFEP_R_5( LOW_IND:HIGH_IND,IFEP) = (/ IEDGE, INPE /)
                     ENDDO
                  ENDDO
               ENDDO
            ENDDO
         ENDIF

      ENDIF BNDCF_CC_IF
   ENDDO SEND_MESH_LOOP
ENDDO RECV_MESH_LOOP

RETURN
END SUBROUTINE CC_EXCHANGE_UNPACKING_ARRAYS



! ------------------------------- MESH_CC_EXCHANGE ---------------------------------

SUBROUTINE MESH_CC_EXCHANGE(CODE)

USE MPI_F08

INTEGER, INTENT(IN) :: CODE

! Local Variables:
INTEGER :: NM,NOM,RNODE,SNODE,IERR
INTEGER :: II1,JJ1,KK1,NCELL,ICC,ICC1,NQT2,JCC,LL,NN
INTEGER :: I,J,K,II,JJ,KK,IFC,ICF,X1AXIS,ICF1,JCF,ICV,IG
TYPE (MESH_TYPE), POINTER :: M,M1
TYPE (OMESH_TYPE), POINTER :: M2,M3
TYPE (CC_FV_TYPE), POINTER :: FV
REAL(EB), POINTER, DIMENSION(:,:,:) :: UP,UP2,VP,VP2,WP,WP2
LOGICAL, SAVE :: INITIALIZE_CC_SCALARS_FORC=.TRUE.
LOGICAL :: USE_FV

INTEGER :: EP,INPE,INT_NPE_LO,INT_NPE_HI,VIND,ICELL,IEDGE,IFEP
REAL(EB) :: TNOW,TINTP

! On the end-of-step (CODE=6) exchange, move the gas-side state of cross-mesh BACK CFACEs.
IF (CODE==6) CALL EXCHANGE_BACK_CFACE_DATA

! For solid phase only return. All variables exchanged currently here are gas-phase.
IF (SOLID_PHASE_ONLY) RETURN
! In case of initialization code from main return.
! Initialization of cut-cell communications needs to be done later in the main.f90 sequence and will be done using
! INITIALIZE_CC_SCALARS/VELOCITY logicals.
IF (CODE == 0 .OR. CODE==2 .OR. CODE>6) RETURN
! No need to do mesh exchange within pressure iteration scheme here, when no IBM forcing, or call to fill GLMAT H ghost cells.
IF (.NOT.CC_MATVEC_DEFINED) RETURN
IF (CODE == 3 .AND. CALL_FROM_GLMAT_SETUP) RETURN

TNOW = CURRENT_TIME()

! First Allocate and setup persistent send-receives for scalars:
INITIALIZE_CC_SCALARS_FORC_COND : IF (INITIALIZE_CC_SCALARS_FORC) THEN

   ! Allocate REQ11, for scalar transport quantities, reduced cycling conditionals:
   N_REQ11=0
   DO NM=LOWER_MESH_INDEX,UPPER_MESH_INDEX
      DO NOM=1,NMESHES
         M3=>MESHES(NM)%OMESH(NOM)
         IF (M3%NICC_S(1)==0 .AND. M3%NICC_R(1)==0) CYCLE
         N_REQ11 = N_REQ11+1
      ENDDO
   ENDDO
   ALLOCATE(REQ11(N_REQ11*4)); N_REQ11=0


   ! Allocate REQ112: Exchange cut-face data in block boundaries.
   N_REQ112=0
   DO NM=LOWER_MESH_INDEX,UPPER_MESH_INDEX
      DO NOM=1,NMESHES
         M3=>MESHES(NM)%OMESH(NOM)
         IF (M3%NICF_S(1)==0 .AND. M3%NICF_R(1)==0 .AND. M3%NLKF_S==0 .AND. M3%NLKF_R==0) CYCLE
         N_REQ112 = N_REQ112+1
      ENDDO
   ENDDO
   ALLOCATE(REQ112(N_REQ112*4)); N_REQ112=0

   ! Allocate REQ12: Dual use, IBM forcing or TAU,OMG computation vars.
   N_REQ12=0
   DO NM=LOWER_MESH_INDEX,UPPER_MESH_INDEX
      DO NOM=1,NMESHES
         M3=>MESHES(NM)%OMESH(NOM)
         IF (M3%NFCC_S(1)==0 .AND. M3%NFCC_R(1)==0) CYCLE
         N_REQ12 = N_REQ12+1
      ENDDO
   ENDDO
   ALLOCATE(REQ12(N_REQ12*4)); N_REQ12=0

   ! Allocate REQ13, for end of step H and RHO_0*W interpolation (cell) quantities:
   N_REQ13=0
   DO NM=LOWER_MESH_INDEX,UPPER_MESH_INDEX
      DO NOM=1,NMESHES
         M3=>MESHES(NM)%OMESH(NOM)
         IF (M3%NFCC_S(2)==0 .AND. M3%NFCC_R(2)==0) CYCLE
         N_REQ13 = N_REQ13+1
      ENDDO
   ENDDO
   ALLOCATE(REQ13(N_REQ13*4)); N_REQ13=0


   ! 1. Receives:
   MESH_LOOP_1: DO NM=LOWER_MESH_INDEX,UPPER_MESH_INDEX

      RNODE = PROCESS(NM)

      ! REQ11:
      OTHER_MESH_LOOP_11: DO NOM=1,NMESHES
         M3=>MESHES(NM)%OMESH(NOM)
         ! Drop leftover CCHALO rows before the NICC_R skip.
         CALL DEALLOCATE_CCHALO(M3)
         IF (M3%NICC_R(1)==0) CYCLE OTHER_MESH_LOOP_11
         SNODE = PROCESS(NOM)
         IF (M3%NICC_R(1)>0) THEN
            ! Cell centered variables on cut-cells:
            ALLOCATE(M3%REAL_RECV_PKG11(M3%NICC_R(2)*(4+N_TOTAL_SCALARS)))
            ! Halo rows use the same NICC_R(2) and N_TOTAL_SCALARS as the buffer.
            IF (M3%NICC_R(2)>=1) CALL ALLOCATE_CCHALO(M3,NM,NOM)
            IF (RNODE/=SNODE) THEN
               N_REQ11 = N_REQ11 + 1
               CALL MPI_RECV_INIT(M3%REAL_RECV_PKG11(1),SIZE(M3%REAL_RECV_PKG11),MPI_DOUBLE_PRECISION, &
                                  SNODE,NOM,MPI_COMM_WORLD,REQ11(N_REQ11),IERR)
            ENDIF
         ENDIF
      ENDDO OTHER_MESH_LOOP_11

      ! REQ112:
      OTHER_MESH_LOOP_112: DO NOM=1,NMESHES
         M3=>MESHES(NM)%OMESH(NOM)
         IF (M3%NICF_R(1)==0 .AND. M3%NLKF_R==0) CYCLE OTHER_MESH_LOOP_112
         SNODE = PROCESS(NOM)
         ! Cut-face centered variables: FN or VEL/VELS plus VEL_LNK. Linked faces follow, 3 reals each.
         ALLOCATE(M3%REAL_RECV_PKG112(M3%NICF_R(2) * 2 + M3%NLKF_R * 3))
         IF (M3%NICF_R(1)>0) CALL ALLOCATE_CFHALO(M3,NOM)
         IF (RNODE/=SNODE) THEN
            N_REQ112 = N_REQ112 + 1
            CALL MPI_RECV_INIT(M3%REAL_RECV_PKG112(1),SIZE(M3%REAL_RECV_PKG112),MPI_DOUBLE_PRECISION, &
                               SNODE,NOM,MPI_COMM_WORLD,REQ112(N_REQ112),IERR)
         ENDIF
      ENDDO OTHER_MESH_LOOP_112

      ! REQ12:
      OTHER_MESH_LOOP_12: DO NOM=1,NMESHES
         M3=>MESHES(NM)%OMESH(NOM)
         IF (M3%NFCC_R(1)==0) CYCLE OTHER_MESH_LOOP_12
         SNODE = PROCESS(NOM)
         ! Face centered variables Ux1, Fvx1, dHdx1:
         ALLOCATE(M3%REAL_RECV_PKG12(M3%NFCC_R(1) * 2))
         IF (RNODE/=SNODE) THEN
            N_REQ12 = N_REQ12 + 1
            CALL MPI_RECV_INIT(M3%REAL_RECV_PKG12(1),SIZE(M3%REAL_RECV_PKG12),MPI_DOUBLE_PRECISION, &
                               SNODE,NOM,MPI_COMM_WORLD,REQ12(N_REQ12),IERR)
         ENDIF
      ENDDO OTHER_MESH_LOOP_12

      ! REQ13:
      OTHER_MESH_LOOP_13: DO NOM=1,NMESHES
         M3=>MESHES(NM)%OMESH(NOM)
         IF (M3%NFCC_R(2)==0) CYCLE OTHER_MESH_LOOP_13
         SNODE = PROCESS(NOM)
         ! Cell centered variables:
         ALLOCATE(M3%REAL_RECV_PKG13(M3%NFCC_R(2)*(NQT2C+N_TRACKED_SPECIES)))
         IF (RNODE/=SNODE) THEN
            N_REQ13 = N_REQ13 + 1
            CALL MPI_RECV_INIT(M3%REAL_RECV_PKG13(1),SIZE(M3%REAL_RECV_PKG13),MPI_DOUBLE_PRECISION, &
                               SNODE,NOM,MPI_COMM_WORLD,REQ13(N_REQ13),IERR)
         ENDIF
      ENDDO OTHER_MESH_LOOP_13

   ENDDO MESH_LOOP_1

   ! 2. Sends:
   SENDING_MESH_LOOP_1: DO NM=LOWER_MESH_INDEX,UPPER_MESH_INDEX

      RNODE = PROCESS(NM)
      M =>MESHES(NM)

      ! REQ11:
      RECEIVING_MESH_LOOP_11: DO NOM=1,NMESHES
         M3=>MESHES(NM)%OMESH(NOM)
         SNODE = PROCESS(NOM)
         ! Initialize persistent send requests
         IF (M3%NICC_S(1)>0 .AND. RNODE/=SNODE) THEN
            ALLOCATE(M3%REAL_SEND_PKG11(M3%NICC_S(2)*(4+N_TOTAL_SCALARS)))
            N_REQ11 = N_REQ11 + 1
            CALL MPI_SEND_INIT(M3%REAL_SEND_PKG11(1),SIZE(M3%REAL_SEND_PKG11),MPI_DOUBLE_PRECISION, &
                               SNODE,NM,MPI_COMM_WORLD,REQ11(N_REQ11),IERR)
         ENDIF
      ENDDO RECEIVING_MESH_LOOP_11

      ! REQ112:
      RECEIVING_MESH_LOOP_112: DO NOM=1,NMESHES
         M3=>MESHES(NM)%OMESH(NOM)
         IF (M3%NICF_S(1)==0 .AND. M3%NLKF_S==0)  CYCLE RECEIVING_MESH_LOOP_112
         SNODE = PROCESS(NOM)
         ! Initialize persistent send requests
         IF ((M3%NICF_S(1)>0 .OR. M3%NLKF_S>0) .AND. RNODE/=SNODE) THEN
            ALLOCATE(M3%REAL_SEND_PKG112(M3%NICF_S(2) * 2 + M3%NLKF_S * 3))
            N_REQ112 = N_REQ112 + 1
            CALL MPI_SEND_INIT(M3%REAL_SEND_PKG112(1),SIZE(M3%REAL_SEND_PKG112),MPI_DOUBLE_PRECISION, &
                               SNODE,NM,MPI_COMM_WORLD,REQ112(N_REQ112),IERR)
         ENDIF
      ENDDO RECEIVING_MESH_LOOP_112

      ! REQ12:
      RECEIVING_MESH_LOOP_12: DO NOM=1,NMESHES
         M3=>MESHES(NM)%OMESH(NOM)
         IF (M3%NFCC_S(1)==0)  CYCLE RECEIVING_MESH_LOOP_12
         SNODE = PROCESS(NOM)
         ! Initialize persistent send requests
         IF (M3%NFCC_S(1)>0 .AND. RNODE/=SNODE) THEN
            ALLOCATE(M3%REAL_SEND_PKG12(M3%NFCC_S(1) * 2))
            N_REQ12 = N_REQ12 + 1
            CALL MPI_SEND_INIT(M3%REAL_SEND_PKG12(1),SIZE(M3%REAL_SEND_PKG12),MPI_DOUBLE_PRECISION, &
                               SNODE,NM,MPI_COMM_WORLD,REQ12(N_REQ12),IERR)
         ENDIF
      ENDDO RECEIVING_MESH_LOOP_12

      ! REQ13:
      RECEIVING_MESH_LOOP_13: DO NOM=1,NMESHES
         M3=>MESHES(NM)%OMESH(NOM)
         IF (M3%NFCC_S(2)==0)  CYCLE RECEIVING_MESH_LOOP_13
         SNODE = PROCESS(NOM)
         ! Initialize persistent send requests
         IF (M3%NFCC_S(2)>0 .AND. RNODE/=SNODE) THEN
            ALLOCATE(M3%REAL_SEND_PKG13(M3%NFCC_S(2)*(NQT2C+N_TRACKED_SPECIES)))
            N_REQ13 = N_REQ13 + 1
            CALL MPI_SEND_INIT(M3%REAL_SEND_PKG13(1),SIZE(M3%REAL_SEND_PKG13),MPI_DOUBLE_PRECISION, &
                               SNODE,NM,MPI_COMM_WORLD,REQ13(N_REQ13),IERR)
         ENDIF
      ENDDO RECEIVING_MESH_LOOP_13

   ENDDO SENDING_MESH_LOOP_1

   INITIALIZE_CC_SCALARS_FORC = .FALSE.

ENDIF INITIALIZE_CC_SCALARS_FORC_COND


! Exchange Scalars in cut-cells:
SENDING_MESH_LOOP_2: DO NM=LOWER_MESH_INDEX,UPPER_MESH_INDEX

   M =>MESHES(NM)
   FV=>M%FV
   ! CV pack is on whenever CV thermo is allocated.
   USE_FV = ALLOCATED(FV%CV%RHO)
   RECEIVING_MESH_LOOP_2: DO NOM=1,NMESHES

      M1=>MESHES(NOM)
      M3=>MESHES(NM)%OMESH(NOM)

      SNODE = PROCESS(NOM)
      RNODE = PROCESS(NM)

      ! Exchange of density and species mass fractions following the PREDICTOR update

      IF (CODE==1 .AND. M3%NICC_S(1)>0) THEN
         NQT2 = 4+N_TOTAL_SCALARS
         LL = 0
         IF (RNODE/=SNODE) THEN
            PACK_REAL_SEND_PKG11: DO ICC1=1,M3%NICC_S(1)
               ICC=M3%ICC_UNKZ_CC_S(ICC1)
               NCELL=M%CUT_CELL(ICC)%NCELL
               II1=M%CUT_CELL(ICC)%IJK(IAXIS)
               JJ1=M%CUT_CELL(ICC)%IJK(JAXIS)
               KK1=M%CUT_CELL(ICC)%IJK(KAXIS)
               DO JCC=1,NCELL
                  LL = LL + 1
                  ICV=0
                  IG = M%CUT_CELL(ICC)%IG(JCC)
                  IF (USE_FV) CALL GET_FV_CV_FOR_CUTCELL(NM,ICC,JCC,ICV)
                  IF (IG>=1) THEN
                     M3%REAL_SEND_PKG11(NQT2*(LL-1)+1) = FV%CV%RHOS(IG)
                     M3%REAL_SEND_PKG11(NQT2*(LL-1)+2) = FV%CV%TMP(IG)
                     M3%REAL_SEND_PKG11(NQT2*(LL-1)+3) = FV%CV%RSUM(IG)
                     IF (ICV>0) THEN
                        M3%REAL_SEND_PKG11(NQT2*(LL-1)+4) = FV%CV%D(ICV)
                     ELSE
                        M3%REAL_SEND_PKG11(NQT2*(LL-1)+4) = FV%CV%D(IG)
                     ENDIF
                     DO NN=1,N_TOTAL_SCALARS
                        M3%REAL_SEND_PKG11(NQT2*(LL-1)+4+NN) = FV%CV%ZZS(NN,IG)
                     ENDDO
                  ELSE
                     M3%REAL_SEND_PKG11(NQT2*(LL-1)+1) = M%RHOS(II1,JJ1,KK1)
                     M3%REAL_SEND_PKG11(NQT2*(LL-1)+2) = M%TMP(II1,JJ1,KK1)
                     M3%REAL_SEND_PKG11(NQT2*(LL-1)+3) = M%RSUM(II1,JJ1,KK1)
                     M3%REAL_SEND_PKG11(NQT2*(LL-1)+4) = M%D(II1,JJ1,KK1)
                     DO NN=1,N_TOTAL_SCALARS
                        M3%REAL_SEND_PKG11(NQT2*(LL-1)+4+NN) = M%ZZS(II1,JJ1,KK1,NN)
                     ENDDO
                  ENDIF
               ENDDO
            ENDDO PACK_REAL_SEND_PKG11
         ENDIF
      ENDIF

      ! Information for cell centered variables:
      IF (CODE==1 .AND. M3%NFCC_S(2)>0) THEN
         NQT2 = NQT2C+N_TOTAL_SCALARS
         LL = 0
         IF (RNODE/=SNODE) THEN
            PACK_REAL_SEND_PKG213 : DO ICC=1,M3%NFCC_S(2)
               I     = M3%IIO_CC_S(ICC)
               J     = M3%JJO_CC_S(ICC)
               K     = M3%KKO_CC_S(ICC)
               LL = LL + 1
               M3%REAL_SEND_PKG13(NQT2*(LL-1)+1) = M%HS(I,J,K)                            ! Prev H in cell I,J,K
               M3%REAL_SEND_PKG13(NQT2*(LL-1)+2) = M%RHO_0(K)                             ! RHO_0 in cell I,J,K
               M3%REAL_SEND_PKG13(NQT2*(LL-1)+3) = 0.5_EB*(M%W(I,J,K-1)+M%W(I,J,K))       ! Wcen^n in I,J,K.
               M3%REAL_SEND_PKG13(NQT2*(LL-1)+4) = M%RHOS(I,J,K)                          ! RHO^*
               M3%REAL_SEND_PKG13(NQT2*(LL-1)+5) = M%TMP(I,J,K)                           ! TMP^*
               M3%REAL_SEND_PKG13(NQT2*(LL-1)+6) = M%RSUM(I,J,K)                          ! RSUM^*
               M3%REAL_SEND_PKG13(NQT2*(LL-1)+7) = M%MU(I,J,K)                            ! MU^n
               M3%REAL_SEND_PKG13(NQT2*(LL-1)+8) = M%MU_DNS(I,J,K)                        ! MU_DNS^n
               M3%REAL_SEND_PKG13(NQT2*(LL-1)+NQT2C)= M%RHO(I,J,K)*(M%HS(I,J,K)-M%KRES(I,J,K)) ! Previous substep pressure.
               DO NN=1,N_TOTAL_SCALARS
                  M3%REAL_SEND_PKG13(NQT2*(LL-1)+NQT2C+NN)= M%ZZS(I,J,K,NN)
               ENDDO
            ENDDO PACK_REAL_SEND_PKG213
         ENDIF
      ENDIF

      ! Exchange momentum rhs FN for cut-faces, in PREDICTOR, IBM forcing:
      IF (CODE==5 .AND. PREDICTOR .AND. M3%NICF_S(1)>0) THEN
         NQT2 = 2
         LL   = 0
         IF (RNODE/=SNODE) THEN
            PACK_REAL_SEND_PKG112A: DO ICF1=1,M3%NICF_S(1)
               ICF=M3%ICF_UFFB_CF_S(ICF1); CF => M%CUT_FACE(ICF)
               DO JCF=1,CF%NFACE
                  LL = LL + 1
                  M3%REAL_SEND_PKG112(NQT2*(LL-1)+1) = CC_FV_CUTFACE_MOM(NM,ICF,JCF,CC_FV_MOM_FN)
               ENDDO
            ENDDO PACK_REAL_SEND_PKG112A
         ELSE
            M2=>MESHES(NOM)%OMESH(NM)
            PACK_REAL_SEND_PKG112A2: DO ICF1=1,M3%NICF_S(1)
               ICF=M3%ICF_UFFB_CF_S(ICF1); CF => M%CUT_FACE(ICF)
               DO JCF=1,CF%NFACE
                  LL = LL + 1
                  M2%CFHALO_FN(LL) = CC_FV_CUTFACE_MOM(NM,ICF,JCF,CC_FV_MOM_FN)
               ENDDO
            ENDDO PACK_REAL_SEND_PKG112A2
         ENDIF
      ENDIF

      ! Exchange Velocity at end of PREDICTOR: To be used in RCEDGEs estimation of OMEGA and TAU at next substep.

      IF (CODE==3 .AND. M3%NICF_S(1)>0) THEN
         NQT2 = 2
         LL   = 0
         IF (RNODE/=SNODE) THEN
            PACK_REAL_SEND_PKG112A3: DO ICF1=1,M3%NICF_S(1)
               ICF=M3%ICF_UFFB_CF_S(ICF1); CF => M%CUT_FACE(ICF)
               DO JCF=1,CF%NFACE
                  LL = LL + 1
                  M3%REAL_SEND_PKG112(NQT2*(LL-1)+1) = CC_FV_CUTFACE_MOM(NM,ICF,JCF,CC_FV_MOM_VELS)
                  M3%REAL_SEND_PKG112(NQT2*(LL-1)+2) = FV%FACE%VEL_LNK(CF%FC(JCF))
               ENDDO
            ENDDO PACK_REAL_SEND_PKG112A3
         ELSE
            M2=>MESHES(NOM)%OMESH(NM)
            PACK_REAL_SEND_PKG112A4: DO ICF1=1,M3%NICF_S(1)
               ICF=M3%ICF_UFFB_CF_S(ICF1); CF => M%CUT_FACE(ICF)
               DO JCF=1,CF%NFACE
                  LL = LL + 1
                  M2%CFHALO_VELS(LL) = CC_FV_CUTFACE_MOM(NM,ICF,JCF,CC_FV_MOM_VELS)
                  M2%CFHALO_VEL_LNK(LL) = FV%FACE%VEL_LNK(CF%FC(JCF))
               ENDDO
            ENDDO PACK_REAL_SEND_PKG112A4
         ENDIF
      ENDIF
      IF (CODE==3 .AND. M3%NFCC_S(1)>0) THEN
         NQT2 = 1
         LL = 0
         IF (RNODE/=SNODE) THEN
            PACK_REAL_SEND_PKG121 : DO IFC=1,M3%NFCC_S(1)
               I     = M3%IIO_FC_S(IFC)
               J     = M3%JJO_FC_S(IFC)
               K     = M3%KKO_FC_S(IFC)
               X1AXIS= M3%AXS_FC_S(IFC)
               LL = LL + 1
               SELECT CASE(X1AXIS)
               CASE(IAXIS)
                  M3%REAL_SEND_PKG12(NQT2*(LL-1)+1) = M%US(I,J,K)                           ! U^* in x face I,J,K
               CASE(JAXIS)
                  M3%REAL_SEND_PKG12(NQT2*(LL-1)+1) = M%VS(I,J,K)                           ! V^* in y face I,J,K
               CASE(KAXIS)
                  M3%REAL_SEND_PKG12(NQT2*(LL-1)+1) = M%WS(I,J,K)                           ! W^* in z face I,J,K
               END SELECT
            ENDDO PACK_REAL_SEND_PKG121
         ELSE
            M2=>MESHES(NOM)%OMESH(NM)
            ! Second Loop cut-edges:
            PACK_REAL_RECV_PKG121E: DO IFEP=1,M2%NFEP_R(3)
               IEDGE= M2%IFEP_R_3( LOW_IND,IFEP)
               INPE = M2%IFEP_R_3(HIGH_IND,IFEP)
               LL   = M1%CC_RCEDGE(IEDGE)%INT_NOMIND(HIGH_IND,INPE)
               I     = M3%IIO_FC_S(LL)
               J     = M3%JJO_FC_S(LL)
               K     = M3%KKO_FC_S(LL)
               X1AXIS= M3%AXS_FC_S(LL)
               SELECT CASE(X1AXIS)
               CASE(IAXIS)
                  M1%CC_RCEDGE(IEDGE)%INT_FVARS(INT_VEL_IND,INPE) = M%US(I,J,K)               ! U^* in x face I,J,K
               CASE(JAXIS)
                  M1%CC_RCEDGE(IEDGE)%INT_FVARS(INT_VEL_IND,INPE) = M%VS(I,J,K)               ! V^* in y face I,J,K
               CASE(KAXIS)
                  M1%CC_RCEDGE(IEDGE)%INT_FVARS(INT_VEL_IND,INPE) = M%WS(I,J,K)               ! W^* in z face I,J,K
               END SELECT
            ENDDO PACK_REAL_RECV_PKG121E
            PACK_REAL_RECV_PKG121EIB: DO IFEP=1,M2%NFEP_R(4)
               IEDGE= M2%IFEP_R_4( LOW_IND,IFEP)
               INPE = M2%IFEP_R_4(HIGH_IND,IFEP)
               LL   = M1%CC_IBEDGE(IEDGE)%INT_NOMIND(HIGH_IND,INPE)
               I     = M3%IIO_FC_S(LL)
               J     = M3%JJO_FC_S(LL)
               K     = M3%KKO_FC_S(LL)
               X1AXIS= M3%AXS_FC_S(LL)
               SELECT CASE(X1AXIS)
               CASE(IAXIS)
                  M1%CC_IBEDGE(IEDGE)%INT_FVARS(INT_VEL_IND,INPE) = M%US(I,J,K)               ! U^* in x face I,J,K
               CASE(JAXIS)
                  M1%CC_IBEDGE(IEDGE)%INT_FVARS(INT_VEL_IND,INPE) = M%VS(I,J,K)               ! V^* in y face I,J,K
               CASE(KAXIS)
                  M1%CC_IBEDGE(IEDGE)%INT_FVARS(INT_VEL_IND,INPE) = M%WS(I,J,K)               ! W^* in z face I,J,K
               END SELECT
            ENDDO PACK_REAL_RECV_PKG121EIB
         ENDIF
      ENDIF

      ! Exchange of density and species mass fractions following the CORRECTOR update

      IF (CODE==4 .AND. M3%NICC_S(1)>0) THEN
         NQT2 = 4+N_TOTAL_SCALARS
         LL = 0
         IF (RNODE/=SNODE) THEN
            PACK_REAL_SEND_PKG111: DO ICC1=1,M3%NICC_S(1)
               ICC=M3%ICC_UNKZ_CC_S(ICC1)
               NCELL=M%CUT_CELL(ICC)%NCELL
               II1=M%CUT_CELL(ICC)%IJK(IAXIS)
               JJ1=M%CUT_CELL(ICC)%IJK(JAXIS)
               KK1=M%CUT_CELL(ICC)%IJK(KAXIS)
               DO JCC=1,NCELL
                  LL = LL + 1
                  ICV=0
                  IG = M%CUT_CELL(ICC)%IG(JCC)
                  IF (USE_FV) CALL GET_FV_CV_FOR_CUTCELL(NM,ICC,JCC,ICV)
                  IF (IG>=1) THEN
                     M3%REAL_SEND_PKG11(NQT2*(LL-1)+1) = FV%CV%RHO(IG)
                     M3%REAL_SEND_PKG11(NQT2*(LL-1)+2) = FV%CV%TMP(IG)
                     M3%REAL_SEND_PKG11(NQT2*(LL-1)+3) = FV%CV%RSUM(IG)
                     IF (ICV>0) THEN
                        M3%REAL_SEND_PKG11(NQT2*(LL-1)+4) = FV%CV%DS(ICV)
                     ELSE
                        M3%REAL_SEND_PKG11(NQT2*(LL-1)+4) = FV%CV%DS(IG)
                     ENDIF
                     DO NN=1,N_TOTAL_SCALARS
                        M3%REAL_SEND_PKG11(NQT2*(LL-1)+4+NN) = FV%CV%ZZ(NN,IG)
                     ENDDO
                  ELSE
                     M3%REAL_SEND_PKG11(NQT2*(LL-1)+1) = M%RHO(II1,JJ1,KK1)
                     M3%REAL_SEND_PKG11(NQT2*(LL-1)+2) = M%TMP(II1,JJ1,KK1)
                     M3%REAL_SEND_PKG11(NQT2*(LL-1)+3) = M%RSUM(II1,JJ1,KK1)
                     M3%REAL_SEND_PKG11(NQT2*(LL-1)+4) = M%DS(II1,JJ1,KK1)
                     DO NN=1,N_TOTAL_SCALARS
                        M3%REAL_SEND_PKG11(NQT2*(LL-1)+4+NN) = M%ZZ(II1,JJ1,KK1,NN)
                     ENDDO
                  ENDIF
               ENDDO
            ENDDO PACK_REAL_SEND_PKG111
         ENDIF
      ENDIF

      ! Information for cell centered variables:
      IF (CODE==4 .AND. M3%NFCC_S(2)>0) THEN
         NQT2 = NQT2C+N_TOTAL_SCALARS
         LL = 0
         IF (RNODE/=SNODE) THEN
            PACK_REAL_SEND_PKG313 : DO ICC=1,M3%NFCC_S(2)
               I     = M3%IIO_CC_S(ICC)
               J     = M3%JJO_CC_S(ICC)
               K     = M3%KKO_CC_S(ICC)
               LL = LL + 1
               M3%REAL_SEND_PKG13(NQT2*(LL-1)+1) = M%H(I,J,K)                             ! Prev H in cell I,J,K
               M3%REAL_SEND_PKG13(NQT2*(LL-1)+2) = M%RHO_0(K)                             ! RHO_0 in cell I,J,K
               M3%REAL_SEND_PKG13(NQT2*(LL-1)+3) = 0.5_EB*(M%WS(I,J,K-1)+M%WS(I,J,K))     ! Wcen^* in I,J,K.
               M3%REAL_SEND_PKG13(NQT2*(LL-1)+4) = M%RHO(I,J,K)                           ! RHO^n+1
               M3%REAL_SEND_PKG13(NQT2*(LL-1)+5) = M%TMP(I,J,K)                           ! TMP^n+1
               M3%REAL_SEND_PKG13(NQT2*(LL-1)+6) = M%RSUM(I,J,K)                          ! RSUM^n+1
               M3%REAL_SEND_PKG13(NQT2*(LL-1)+7) = M%MU(I,J,K)                            ! MU^*
               M3%REAL_SEND_PKG13(NQT2*(LL-1)+8) = M%MU_DNS(I,J,K)                        ! MU_DNS^*
               M3%REAL_SEND_PKG13(NQT2*(LL-1)+NQT2C)= M%RHOS(I,J,K)*(M%H(I,J,K)-M%KRES(I,J,K)) ! Previous substep pressure.
               DO NN=1,N_TOTAL_SCALARS
                  M3%REAL_SEND_PKG13(NQT2*(LL-1)+NQT2C+NN)= M%ZZ(I,J,K,NN)
               ENDDO
            ENDDO PACK_REAL_SEND_PKG313
         ENDIF
      ENDIF


      ! Exchange momentum rhs FN for cut-faces, in CORRECTOR, IBM forcing:
      IF (CODE==5 .AND. CORRECTOR .AND. M3%NICF_S(1)>0) THEN
         NQT2 = 2
         LL   = 0
         IF (RNODE/=SNODE) THEN
            PACK_REAL_SEND_PKG112B: DO ICF1=1,M3%NICF_S(1)
               ICF=M3%ICF_UFFB_CF_S(ICF1); CF => M%CUT_FACE(ICF)
               DO JCF=1,CF%NFACE
                  LL = LL + 1
                  M3%REAL_SEND_PKG112(NQT2*(LL-1)+1) = CC_FV_CUTFACE_MOM(NM,ICF,JCF,CC_FV_MOM_FN)
               ENDDO
            ENDDO PACK_REAL_SEND_PKG112B
         ELSE
            M2=>MESHES(NOM)%OMESH(NM)
            PACK_REAL_SEND_PKG112B2: DO ICF1=1,M3%NICF_S(1)
               ICF=M3%ICF_UFFB_CF_S(ICF1); CF => M%CUT_FACE(ICF)
               DO JCF=1,CF%NFACE
                  LL = LL + 1
                  M2%CFHALO_FN(LL) = CC_FV_CUTFACE_MOM(NM,ICF,JCF,CC_FV_MOM_FN)
               ENDDO
            ENDDO PACK_REAL_SEND_PKG112B2
         ENDIF
      ENDIF

      ! Exchange Velocity at end of CORRECTOR: To be used in RCEDGEs estimation of OMEGA and TAU next substep.

      IF (CODE==6 .AND. M3%NICF_S(1)>0) THEN
         NQT2 = 2
         LL   = 0
         IF (RNODE/=SNODE) THEN
            PACK_REAL_SEND_PKG112B3: DO ICF1=1,M3%NICF_S(1)
               ICF=M3%ICF_UFFB_CF_S(ICF1); CF => M%CUT_FACE(ICF)
               DO JCF=1,CF%NFACE
                  LL = LL + 1
                  M3%REAL_SEND_PKG112(NQT2*(LL-1)+1) = CC_FV_CUTFACE_MOM(NM,ICF,JCF,CC_FV_MOM_VEL)
                  M3%REAL_SEND_PKG112(NQT2*(LL-1)+2) = FV%FACE%VEL_LNK(CF%FC(JCF))
               ENDDO
            ENDDO PACK_REAL_SEND_PKG112B3
         ELSE
            M2=>MESHES(NOM)%OMESH(NM)
            PACK_REAL_SEND_PKG112B4: DO ICF1=1,M3%NICF_S(1)
               ICF=M3%ICF_UFFB_CF_S(ICF1); CF => M%CUT_FACE(ICF)
               DO JCF=1,CF%NFACE
                  LL = LL + 1
                  M2%CFHALO_VEL(LL) = CC_FV_CUTFACE_MOM(NM,ICF,JCF,CC_FV_MOM_VEL)
                  M2%CFHALO_VEL_LNK(LL) = FV%FACE%VEL_LNK(CF%FC(JCF))
               ENDDO
            ENDDO PACK_REAL_SEND_PKG112B4
         ENDIF
      ENDIF
      IF ((CODE==3 .OR. CODE==6) .AND. M3%NLKF_S>0) THEN
         IF (CODE==3) THEN
            UP => M%US ; VP => M%VS ; WP => M%WS
         ELSE
            UP => M%U  ; VP => M%V  ; WP => M%W
         ENDIF
         IF (RNODE/=SNODE) THEN
            LL = 2 * M3%NICF_S(2)
            DO KK=M3%K_MIN_S,M3%K_MAX_S
               DO JJ=M3%J_MIN_S,M3%J_MAX_S
                  DO II=M3%I_MIN_S,M3%I_MAX_S
                     ! U linked Velocity:
                     M3%REAL_SEND_PKG112(LL+1) = UP(II,JJ,KK)
                     IF (CC_FV_UNKF_REG(NM,II,JJ,KK,IAXIS)>0) THEN ! Regular Face
                        M3%REAL_SEND_PKG112(LL+1) = M%UN_LNK(CC_FV_UNKF_REG(NM,II,JJ,KK,IAXIS))
                     ELSEIF(M%FCVAR(II,JJ,KK,CC_IDRC,IAXIS)>0) THEN ! RC Face.
                        ICF=M%FCVAR(II,JJ,KK,CC_IDRC,IAXIS); IF(CC_FV_UNKF_RC(NM,ICF)>0) &
                        M3%REAL_SEND_PKG112(LL+1) = M%UN_LNK(CC_FV_UNKF_RC(NM,ICF))
                     ENDIF
                     ! V linked Velocity:
                     M3%REAL_SEND_PKG112(LL+2) = VP(II,JJ,KK)
                     IF (CC_FV_UNKF_REG(NM,II,JJ,KK,JAXIS)>0) THEN ! Regular Face
                        M3%REAL_SEND_PKG112(LL+2) = M%UN_LNK(CC_FV_UNKF_REG(NM,II,JJ,KK,JAXIS))
                     ELSEIF(M%FCVAR(II,JJ,KK,CC_IDRC,JAXIS)>0) THEN ! RC Face.
                        ICF=M%FCVAR(II,JJ,KK,CC_IDRC,JAXIS); IF(CC_FV_UNKF_RC(NM,ICF)>0) &
                        M3%REAL_SEND_PKG112(LL+2) = M%UN_LNK(CC_FV_UNKF_RC(NM,ICF))
                     ENDIF
                     ! W linked velocity:
                     M3%REAL_SEND_PKG112(LL+3) = WP(II,JJ,KK)
                     IF (CC_FV_UNKF_REG(NM,II,JJ,KK,KAXIS)>0) THEN ! Regular Face
                        M3%REAL_SEND_PKG112(LL+3) = M%UN_LNK(CC_FV_UNKF_REG(NM,II,JJ,KK,KAXIS))
                     ELSEIF(M%FCVAR(II,JJ,KK,CC_IDRC,KAXIS)>0) THEN ! RC Face.
                        ICF=M%FCVAR(II,JJ,KK,CC_IDRC,KAXIS); IF(CC_FV_UNKF_RC(NM,ICF)>0) &
                        M3%REAL_SEND_PKG112(LL+3) = M%UN_LNK(CC_FV_UNKF_RC(NM,ICF))
                     ENDIF
                     LL = LL+3
                  ENDDO
               ENDDO
            ENDDO
         ELSE
            M2=>MESHES(NOM)%OMESH(NM)
            UP2 => M2%U_LNK ; VP2 => M2%V_LNK ; WP2 => M2%W_LNK
            DO KK=M3%K_MIN_S,M3%K_MAX_S
               DO JJ=M3%J_MIN_S,M3%J_MAX_S
                  DO II=M3%I_MIN_S,M3%I_MAX_S
                     ! U linked Velocity:
                     UP2(II,JJ,KK) = UP(II,JJ,KK)
                     IF (CC_FV_UNKF_REG(NM,II,JJ,KK,IAXIS)>0) THEN ! Regular Face
                        UP2(II,JJ,KK) = M%UN_LNK(CC_FV_UNKF_REG(NM,II,JJ,KK,IAXIS))
                     ELSEIF(M%FCVAR(II,JJ,KK,CC_IDRC,IAXIS)>0) THEN ! RC Face.
                        ICF=M%FCVAR(II,JJ,KK,CC_IDRC,IAXIS); IF(CC_FV_UNKF_RC(NM,ICF)>0) &
                        UP2(II,JJ,KK) = M%UN_LNK(CC_FV_UNKF_RC(NM,ICF))
                     ENDIF
                     ! V linked Velocity:
                     VP2(II,JJ,KK) = VP(II,JJ,KK)
                     IF (CC_FV_UNKF_REG(NM,II,JJ,KK,JAXIS)>0) THEN ! Regular Face
                        VP2(II,JJ,KK) = M%UN_LNK(CC_FV_UNKF_REG(NM,II,JJ,KK,JAXIS))
                     ELSEIF(M%FCVAR(II,JJ,KK,CC_IDRC,JAXIS)>0) THEN ! RC Face.
                        ICF=M%FCVAR(II,JJ,KK,CC_IDRC,JAXIS); IF(CC_FV_UNKF_RC(NM,ICF)>0) &
                        VP2(II,JJ,KK) = M%UN_LNK(CC_FV_UNKF_RC(NM,ICF))
                     ENDIF
                     ! W linked velocity:
                     WP2(II,JJ,KK) = WP(II,JJ,KK)
                     IF (CC_FV_UNKF_REG(NM,II,JJ,KK,KAXIS)>0) THEN ! Regular Face
                        WP2(II,JJ,KK) = M%UN_LNK(CC_FV_UNKF_REG(NM,II,JJ,KK,KAXIS))
                     ELSEIF(M%FCVAR(II,JJ,KK,CC_IDRC,KAXIS)>0) THEN ! RC Face.
                        ICF=M%FCVAR(II,JJ,KK,CC_IDRC,KAXIS); IF(CC_FV_UNKF_RC(NM,ICF)>0) &
                        WP2(II,JJ,KK) = M%UN_LNK(CC_FV_UNKF_RC(NM,ICF))
                     ENDIF
                  ENDDO
               ENDDO
            ENDDO
         ENDIF
      ENDIF
      IF (CODE==6 .AND. M3%NFCC_S(1)>0) THEN
         NQT2 = 1
         LL   = 0
         IF (RNODE/=SNODE) THEN
            PACK_REAL_SEND_PKG122 : DO IFC=1,M3%NFCC_S(1)
               I     = M3%IIO_FC_S(IFC)
               J     = M3%JJO_FC_S(IFC)
               K     = M3%KKO_FC_S(IFC)
               X1AXIS= M3%AXS_FC_S(IFC)
               LL = LL + 1
               SELECT CASE(X1AXIS)
               CASE(IAXIS)
                  M3%REAL_SEND_PKG12(NQT2*(LL-1)+1) = M%U(I,J,K)                            ! U^n+1 in x face I,J,K
               CASE(JAXIS)
                  M3%REAL_SEND_PKG12(NQT2*(LL-1)+1) = M%V(I,J,K)                            ! V^n+1 in y face I,J,K
               CASE(KAXIS)
                  M3%REAL_SEND_PKG12(NQT2*(LL-1)+1) = M%W(I,J,K)                            ! W^n+1 in z face I,J,K
               END SELECT
            ENDDO PACK_REAL_SEND_PKG122
         ELSE
            M2=>MESHES(NOM)%OMESH(NM)
            ! Second Loop cut-edges:
            PACK_REAL_RECV_PKG122E: DO IFEP=1,M2%NFEP_R(3)
               IEDGE= M2%IFEP_R_3( LOW_IND,IFEP)
               INPE = M2%IFEP_R_3(HIGH_IND,IFEP)
               LL   = M1%CC_RCEDGE(IEDGE)%INT_NOMIND(HIGH_IND,INPE)
               I     = M3%IIO_FC_S(LL)
               J     = M3%JJO_FC_S(LL)
               K     = M3%KKO_FC_S(LL)
               X1AXIS= M3%AXS_FC_S(LL)
               SELECT CASE(X1AXIS)
               CASE(IAXIS)
                  M1%CC_RCEDGE(IEDGE)%INT_FVARS(INT_VEL_IND,INPE) = M%U(I,J,K)             ! U^n+1 in x face I,J,K
               CASE(JAXIS)
                  M1%CC_RCEDGE(IEDGE)%INT_FVARS(INT_VEL_IND,INPE) = M%V(I,J,K)             ! V^n+1 in y face I,J,K
               CASE(KAXIS)
                  M1%CC_RCEDGE(IEDGE)%INT_FVARS(INT_VEL_IND,INPE) = M%W(I,J,K)             ! W^n+1 in z face I,J,K
               END SELECT
            ENDDO PACK_REAL_RECV_PKG122E
            PACK_REAL_RECV_PKG122EIB: DO IFEP=1,M2%NFEP_R(4)
               IEDGE= M2%IFEP_R_4( LOW_IND,IFEP)
               INPE = M2%IFEP_R_4(HIGH_IND,IFEP)
               LL   = M1%CC_IBEDGE(IEDGE)%INT_NOMIND(HIGH_IND,INPE)
               I     = M3%IIO_FC_S(LL)
               J     = M3%JJO_FC_S(LL)
               K     = M3%KKO_FC_S(LL)
               X1AXIS= M3%AXS_FC_S(LL)
               SELECT CASE(X1AXIS)
               CASE(IAXIS)
                  M1%CC_IBEDGE(IEDGE)%INT_FVARS(INT_VEL_IND,INPE) = M%U(I,J,K)             ! U^n+1 in x face I,J,K
               CASE(JAXIS)
                  M1%CC_IBEDGE(IEDGE)%INT_FVARS(INT_VEL_IND,INPE) = M%V(I,J,K)             ! V^n+1 in y face I,J,K
               CASE(KAXIS)
                  M1%CC_IBEDGE(IEDGE)%INT_FVARS(INT_VEL_IND,INPE) = M%W(I,J,K)             ! W^n+1 in z face I,J,K
               END SELECT
            ENDDO PACK_REAL_RECV_PKG122EIB
         ENDIF
      ENDIF

      ! Exchange H, RHO_0 and W velocity averaged to cell center, at PREDICTOR end of step:

      IF (CODE==3 .AND. M3%NFCC_S(2)>0) THEN
         NQT2 = 4
         LL   = 0
         IF (RNODE/=SNODE) THEN
            PACK_REAL_SEND_PKG13 : DO ICC=1,M3%NFCC_S(2)
               I     = M3%IIO_CC_S(ICC)
               J     = M3%JJO_CC_S(ICC)
               K     = M3%KKO_CC_S(ICC)
               LL = LL + 1
               M3%REAL_SEND_PKG13(NQT2*(LL-1)+1) = M%H(I,J,K)                             ! H^n in cell I,J,K
               M3%REAL_SEND_PKG13(NQT2*(LL-1)+2) = M%RHO_0(K)                             ! RHO_0 in cell I,J,K
               M3%REAL_SEND_PKG13(NQT2*(LL-1)+3) = 0.5_EB*(M%WS(I,J,K-1)+M%WS(I,J,K))     ! Wcen^* in I,J,K.
               M3%REAL_SEND_PKG13(NQT2*(LL-1)+4) = M%MU(I,J,K)                            ! MU in I,J,K
            ENDDO PACK_REAL_SEND_PKG13
         ELSE
            M2=>MESHES(NOM)%OMESH(NM)
            PACK_REAL_RECV_PKG13: DO ICC=1,M3%NFCC_S(2)
               I     = M3%IIO_CC_S(ICC)
               J     = M3%JJO_CC_S(ICC)
               K     = M3%KKO_CC_S(ICC)
               LL = LL + 1
               M2%REAL_RECV_PKG13(NQT2*(LL-1)+1) = M%H(I,J,K)                             ! H^n in cell I,J,K
               M2%REAL_RECV_PKG13(NQT2*(LL-1)+2) = M%RHO_0(K)                             ! RHO_0 in cell I,J,K
               M2%REAL_RECV_PKG13(NQT2*(LL-1)+3) = 0.5_EB*(M%WS(I,J,K-1)+M%WS(I,J,K))     ! Wcen^* in I,J,K.
               M2%REAL_RECV_PKG13(NQT2*(LL-1)+4) = M%MU(I,J,K)                            ! MU in I,J,K
            ENDDO PACK_REAL_RECV_PKG13
         ENDIF
      ENDIF

      ! Exchange H, RHO_0 and W velocity averaged to cell center, at CORRECTOR end of step:

      IF (CODE==6 .AND. M3%NFCC_S(2)>0) THEN
         NQT2 = 4
         LL   = 0
         IF (RNODE/=SNODE) THEN
            PACK_REAL_SEND_PKG113 : DO ICC=1,M3%NFCC_S(2)
               I     = M3%IIO_CC_S(ICC)
               J     = M3%JJO_CC_S(ICC)
               K     = M3%KKO_CC_S(ICC)
               LL = LL + 1
               M3%REAL_SEND_PKG13(NQT2*(LL-1)+1) = M%HS(I,J,K)                            ! H^* in cell I,J,K
               M3%REAL_SEND_PKG13(NQT2*(LL-1)+2) = M%RHO_0(K)                             ! RHO_0 in cell I,J,K
               M3%REAL_SEND_PKG13(NQT2*(LL-1)+3) = 0.5_EB*(M%W(I,J,K-1)+M%W(I,J,K))       ! Wcen  in I,J,K.
               M3%REAL_SEND_PKG13(NQT2*(LL-1)+4) = M%MU(I,J,K)                            ! MU in I,J,K
            ENDDO PACK_REAL_SEND_PKG113
         ELSE
            M2=>MESHES(NOM)%OMESH(NM)
            PACK_REAL_RECV_PKG113: DO ICC=1,M3%NFCC_S(2)
               I     = M3%IIO_CC_S(ICC)
               J     = M3%JJO_CC_S(ICC)
               K     = M3%KKO_CC_S(ICC)
               LL = LL + 1
               M2%REAL_RECV_PKG13(NQT2*(LL-1)+1) = M%HS(I,J,K)                            ! H^* in cell I,J,K
               M2%REAL_RECV_PKG13(NQT2*(LL-1)+2) = M%RHO_0(K)                             ! RHO_0 in cell I,J,K
               M2%REAL_RECV_PKG13(NQT2*(LL-1)+3) = 0.5_EB*(M%W(I,J,K-1)+M%W(I,J,K))       ! Wcen  in I,J,K.
               M2%REAL_RECV_PKG13(NQT2*(LL-1)+4) = M%MU(I,J,K)                            ! MU in I,J,K
            ENDDO PACK_REAL_RECV_PKG113
         ENDIF
      ENDIF

   ENDDO RECEIVING_MESH_LOOP_2
ENDDO SENDING_MESH_LOOP_2

! Exchange Scalars:
IF (N_MPI_PROCESSES>1 .AND. (CODE==1.OR.CODE==4) .AND. N_REQ11>0) THEN
   CALL MPI_STARTALL(N_REQ11,REQ11(1:N_REQ11),IERR)
   CALL CC_TIMEOUT('REQ11',N_REQ11,REQ11(1:N_REQ11))
ENDIF

! Exchange FVX,FVY,FVZ data for gas cut-faces:
IF (N_MPI_PROCESSES>1 .AND. ANY(CODE==(/3,5,6/)) .AND. N_REQ112>0) THEN
   CALL MPI_STARTALL(N_REQ112,REQ112(1:N_REQ112),IERR)
   CALL CC_TIMEOUT('REQ112',N_REQ112,REQ112(1:N_REQ112))
ENDIF

! Exchange End of Step velocity data for RCEDGEs:
IF (N_MPI_PROCESSES>1 .AND. (CODE==3.OR.CODE==6) .AND. N_REQ12>0) THEN
   CALL MPI_STARTALL(N_REQ12,REQ12(1:N_REQ12),IERR)
   CALL CC_TIMEOUT('REQ12',N_REQ12,REQ12(1:N_REQ12))
ENDIF

! Exchange scalar data End of step cell-centered data:
IF (N_MPI_PROCESSES>1 .AND. (CODE==1.OR.CODE==4.OR.CODE==3.OR.CODE==6) .AND. N_REQ13>0) THEN
   CALL MPI_STARTALL(N_REQ13,REQ13(1:N_REQ13),IERR)
   CALL CC_TIMEOUT('REQ13',N_REQ13,REQ13(1:N_REQ13))
ENDIF

! Receive the information sent above into the appropriate arrays.

RECV_MESH_LOOP: DO NOM=LOWER_MESH_INDEX,UPPER_MESH_INDEX

   M =>MESHES(NOM)

   SEND_MESH_LOOP: DO NM=1,NMESHES

      M2=>MESHES(NOM)%OMESH(NM)

      RNODE = PROCESS(NOM)
      SNODE = PROCESS(NM)

      RNODE_SNODE_IF: IF (RNODE/=SNODE) THEN

         ! Unpack densities and species mass fractions following PREDICTOR exchange

         IF (CODE==1 .AND. M2%NICC_R(1)>0) THEN
            NQT2 = 4+N_TOTAL_SCALARS
            LL   = 0
            ! Unpack from sender-validated ICC_UNKZ_CC_R list (avoids stale CCVAR for ghost cut-cells
            ! rejected by the sender's validation pass).
            DO ICC1=1,M2%NICC_R(1)
               ICC = M2%ICC_UNKZ_CC_R(ICC1)
               IF (ICC < 1) CYCLE
               DO JCC=1,MESHES(NM)%CUT_CELL(ICC)%NCELL
                  LL = LL + 1
                  IF (ALLOCATED(M2%CCHALO_RHOS)) THEN
                     M2%CCHALO_RHOS(LL) = M2%REAL_RECV_PKG11(NQT2*(LL-1)+1)
                     M2%CCHALO_TMP(LL)  = M2%REAL_RECV_PKG11(NQT2*(LL-1)+2)
                     M2%CCHALO_RSUM(LL) = M2%REAL_RECV_PKG11(NQT2*(LL-1)+3)
                     M2%CCHALO_D(LL)    = M2%REAL_RECV_PKG11(NQT2*(LL-1)+4)
                     DO NN=1,N_TOTAL_SCALARS
                        M2%CCHALO_ZZS(NN,LL) = M2%REAL_RECV_PKG11(NQT2*(LL-1)+4+NN)
                     ENDDO
                  ENDIF
               ENDDO
            ENDDO
         ENDIF

         ! Unpack momentum rhs FN for cut-faces, in PREDICTOR or CORRECTOR, IBM forcing:
         IF (CODE==5  .AND. M2%NICF_R(1)>0) THEN
            NQT2 = 2
            LL   = 0
            DO ICF1=1,M2%NICF_R(1)
               ICF = M2%ICF_UFFB_CF_R(ICF1)
               IF (ICF > 0) THEN
                  CF => MESHES(NM)%CUT_FACE(ICF)
                  DO JCF=1,CF%NFACE
                     LL = LL + 1
                     M2%CFHALO_FN(LL) = M2%REAL_RECV_PKG112(NQT2*(LL-1)+1)
                  ENDDO
               ENDIF
            ENDDO
         ENDIF

         IF (CODE==3 .AND. M2%NFCC_R(1)>0) THEN
            NQT2 = 1
            ! Second Loop cut-edges:
            DO IFEP=1,M2%NFEP_R(3)
               IEDGE= M2%IFEP_R_3( LOW_IND,IFEP)
               INPE = M2%IFEP_R_3(HIGH_IND,IFEP)
               LL   = M%CC_RCEDGE(IEDGE)%INT_NOMIND(HIGH_IND,INPE)
               M%CC_RCEDGE(IEDGE)%INT_FVARS(INT_VEL_IND,INPE)= M2%REAL_RECV_PKG12(NQT2*(LL-1)+1) ! Vel^*, added to INT_VEL_IND pos.
            ENDDO
            DO IFEP=1,M2%NFEP_R(4)
               IEDGE= M2%IFEP_R_4( LOW_IND,IFEP)
               INPE = M2%IFEP_R_4(HIGH_IND,IFEP)
               LL   = M%CC_IBEDGE(IEDGE)%INT_NOMIND(HIGH_IND,INPE)
               M%CC_IBEDGE(IEDGE)%INT_FVARS(INT_VEL_IND,INPE)= M2%REAL_RECV_PKG12(NQT2*(LL-1)+1) ! Vel^*, added to INT_VEL_IND pos.
            ENDDO
         ENDIF
         IF(CODE==3 .AND. M2%NICF_R(1)>0) THEN
            NQT2 = 2
            LL   = 0
            DO ICF1=1,M2%NICF_R(1)
               ICF = M2%ICF_UFFB_CF_R(ICF1)
               IF (ICF > 0) THEN
                  CF => MESHES(NM)%CUT_FACE(ICF)
                  DO JCF=1,CF%NFACE
                     LL = LL + 1
                     M2%CFHALO_VELS(LL) = M2%REAL_RECV_PKG112(NQT2*(LL-1)+1)
                     M2%CFHALO_VEL_LNK(LL) = M2%REAL_RECV_PKG112(NQT2*(LL-1)+2)
                  ENDDO
               ENDIF
            ENDDO
         ENDIF

         ! Unpack densities and species mass fractions following CORRECTOR exchange

         IF (CODE==4 .AND. M2%NICC_R(1)>0) THEN
            NQT2 = 4+N_TOTAL_SCALARS
            LL   = 0
            ! Unpack from sender-validated ICC_UNKZ_CC_R list (avoids stale CCVAR for ghost cut-cells
            ! rejected by the sender's validation pass).
            DO ICC1=1,M2%NICC_R(1)
               ICC = M2%ICC_UNKZ_CC_R(ICC1)
               IF (ICC < 1) CYCLE
               DO JCC=1,MESHES(NM)%CUT_CELL(ICC)%NCELL
                  LL = LL + 1
                  IF (ALLOCATED(M2%CCHALO_RHO)) THEN
                     M2%CCHALO_RHO(LL)  = M2%REAL_RECV_PKG11(NQT2*(LL-1)+1)
                     M2%CCHALO_TMP(LL)  = M2%REAL_RECV_PKG11(NQT2*(LL-1)+2)
                     M2%CCHALO_RSUM(LL) = M2%REAL_RECV_PKG11(NQT2*(LL-1)+3)
                     M2%CCHALO_DS(LL)   = M2%REAL_RECV_PKG11(NQT2*(LL-1)+4)
                     DO NN=1,N_TOTAL_SCALARS
                        M2%CCHALO_ZZ(NN,LL) = M2%REAL_RECV_PKG11(NQT2*(LL-1)+4+NN)
                     ENDDO
                  ENDIF
               ENDDO
            ENDDO
         ENDIF

         IF (CODE==6 .AND. M2%NFCC_R(1)>0) THEN
            NQT2 = 1
            ! Second Loop cut-edges:
            DO IFEP=1,M2%NFEP_R(3)
               IEDGE= M2%IFEP_R_3( LOW_IND,IFEP)
               INPE = M2%IFEP_R_3(HIGH_IND,IFEP)
               LL   = M%CC_RCEDGE(IEDGE)%INT_NOMIND(HIGH_IND,INPE)
               M%CC_RCEDGE(IEDGE)%INT_FVARS(INT_VEL_IND,INPE)= M2%REAL_RECV_PKG12(NQT2*(LL-1)+1) ! Vel^n+1
            ENDDO
            DO IFEP=1,M2%NFEP_R(4)
               IEDGE= M2%IFEP_R_4( LOW_IND,IFEP)
               INPE = M2%IFEP_R_4(HIGH_IND,IFEP)
               LL   = M%CC_IBEDGE(IEDGE)%INT_NOMIND(HIGH_IND,INPE)
               M%CC_IBEDGE(IEDGE)%INT_FVARS(INT_VEL_IND,INPE)= M2%REAL_RECV_PKG12(NQT2*(LL-1)+1) ! Vel^n+1
            ENDDO
         ENDIF
         IF(CODE==6 .AND. M2%NICF_R(1)>0) THEN
            NQT2 = 2
            LL   = 0
            DO ICF1=1,M2%NICF_R(1)
               ICF = M2%ICF_UFFB_CF_R(ICF1)
               IF (ICF > 0) THEN
                  CF => MESHES(NM)%CUT_FACE(ICF)
                  DO JCF=1,CF%NFACE
                     LL = LL + 1
                     M2%CFHALO_VEL(LL) = M2%REAL_RECV_PKG112(NQT2*(LL-1)+1)
                     M2%CFHALO_VEL_LNK(LL) = M2%REAL_RECV_PKG112(NQT2*(LL-1)+2)
                  ENDDO
               ENDIF
            ENDDO
         ENDIF
         IF ((CODE==3.OR.CODE==6) .AND. M2%NLKF_R>0) THEN
            UP2 => M2%U_LNK ; VP2 => M2%V_LNK ; WP2 => M2%W_LNK
            LL = 2 * M2%NICF_R(2)
            DO KK=M2%K_MIN_R,M2%K_MAX_R
               DO JJ=M2%J_MIN_R,M2%J_MAX_R
                  DO II=M2%I_MIN_R,M2%I_MAX_R
                     UP2(II,JJ,KK) = M2%REAL_RECV_PKG112(LL+1)
                     VP2(II,JJ,KK) = M2%REAL_RECV_PKG112(LL+2)
                     WP2(II,JJ,KK) = M2%REAL_RECV_PKG112(LL+3)
                     LL = LL+3
                  ENDDO
               ENDDO
            ENDDO
         ENDIF

      ENDIF RNODE_SNODE_IF

      ! Unpack H, RHO_0 and W velocity averaged to cell center, at PREDICTOR or CORRECTOR end of step:

      IF ( (CODE==3 .OR. CODE==6) .AND. M2%NFCC_R(2)>0) THEN
         NQT2 = 4
         ! First loop cut-cells:
         VIND = 0
         DO ICC=1,M%N_CUTCELL_MESH
            DO ICELL=0,M%CUT_CELL(ICC)%NCELL
               DO EP=1,INT_N_EXT_PTS  ! External point for cell ICELL
                  INT_NPE_LO = M%CUT_CELL(ICC)%INT_NPE(LOW_IND,VIND,EP,ICELL)
                  INT_NPE_HI = M%CUT_CELL(ICC)%INT_NPE(HIGH_IND,VIND,EP,ICELL)
                  DO INPE=INT_NPE_LO+1,INT_NPE_LO+INT_NPE_HI
                     IF (M%CUT_CELL(ICC)%INT_NOMIND( LOW_IND,INPE) /= NM) CYCLE
                     LL     = M%CUT_CELL(ICC)%INT_NOMIND(HIGH_IND,INPE)
                     M%CUT_CELL(ICC)%INT_CCVARS(   INT_H_IND,INPE)= M2%REAL_RECV_PKG13(NQT2*(LL-1)+1) ! H^n, or H^s
                     M%CUT_CELL(ICC)%INT_CCVARS(INT_RHO0_IND,INPE)= M2%REAL_RECV_PKG13(NQT2*(LL-1)+2) ! RHO_0
                     M%CUT_CELL(ICC)%INT_CCVARS(INT_WCEN_IND,INPE)= M2%REAL_RECV_PKG13(NQT2*(LL-1)+3) ! Wcen^*, or Wcen^n+1
                  ENDDO
               ENDDO
            ENDDO
         ENDDO
         ! Then Loop IBEDGES:
         DO IFEP=1,M2%NFEP_R(5)
            IEDGE= M2%IFEP_R_5( LOW_IND,IFEP)
            INPE = M2%IFEP_R_5(HIGH_IND,IFEP)
            LL   = M%CC_IBEDGE(IEDGE)%INT_NOMIND(HIGH_IND,INPE)
            M%CC_IBEDGE(IEDGE)%INT_CVARS(INT_MU_IND,INPE)= M2%REAL_RECV_PKG13(NQT2*(LL-1)+4) ! MU.
         ENDDO
      ENDIF

   ENDDO SEND_MESH_LOOP
ENDDO RECV_MESH_LOOP

T_USED(11) = T_USED(11) + CURRENT_TIME() - TNOW ! Add communication time to COMM column.

TINTP= CURRENT_TIME()
IF(CODE==1 .OR. CODE==4) THEN
  CALL FILL_GCCUTCELL_SPECIES
ELSEIF(CODE==3 .OR. CODE==6) THEN
   CALL CC_H_INTERP
   CALL CC_RHO0W_INTERP
ENDIF
T_USED(14) = T_USED(14) + CURRENT_TIME() - TINTP ! Add interpolation time to GEOM column.

IF (TIME_CC_IBM) T_CC_USED(MESH_CC_EXCHANGE_TIME_INDEX) = T_CC_USED(MESH_CC_EXCHANGE_TIME_INDEX) + CURRENT_TIME() - TNOW

RETURN

CONTAINS

SUBROUTINE FILL_GCCUTCELL_SPECIES


REAL(EB):: VCELL, RHO_CC, TMP_CC, RSUM_CC, D_CC, ZZ_CC(1:N_TOTAL_SCALARS), VOL
TYPE(CC_CUTCELL_TYPE), POINTER :: OCC
TYPE(CC_FV_TYPE), POINTER :: FV_SRC,FV_DST
TYPE(OMESH_TYPE), POINTER :: OM
INTEGER :: NM,NOM,NN,ICC,JCC,IW,IIO,JJO,KKO,ICV,IROW,IG
LOGICAL :: VALID_SOURCE_CC,USE_FV_SRC,SOURCE_REMOTE,USE_CCHALO

! Here inject OMESH cut-cell info obtained in MESH_CC_EXCHANGE into ghost-cell cc containers:
MESH_LOOP : DO NM=LOWER_MESH_INDEX,UPPER_MESH_INDEX
   CALL POINT_TO_MESH(NM)
   FV_DST=>MESHES(NM)%FV
   EXTERNAL_WALL_LOOP : DO IW=1,N_EXTERNAL_WALL_CELLS
      WC=>WALL(IW)
      IF (.NOT.(WC%BOUNDARY_TYPE == INTERPOLATED_BOUNDARY)) CYCLE EXTERNAL_WALL_LOOP
      BC=>BOUNDARY_COORD(WC%BC_INDEX)
      EWC=>EXTERNAL_WALL(IW)
      IF (CCVAR(BC%II,BC%JJ,BC%KK,CC_CGSC) /= CC_CUTCFE) CYCLE EXTERNAL_WALL_LOOP
      ! Do volume average to a cell container for ghost cell II,JJ,KK:
      NOM = EWC%NOM
      FV_SRC=>MESHES(NOM)%FV
      USE_FV_SRC = ALLOCATED(FV_SRC%CV%RHO)
      RHO_CC=0._EB; TMP_CC=0._EB; RSUM_CC=0._EB; D_CC=0._EB; ZZ_CC(1:N_TOTAL_SCALARS)=0._EB; VOL=0._EB
      DO KKO=EWC%KKO_MIN,EWC%KKO_MAX
         DO JJO=EWC%JJO_MIN,EWC%JJO_MAX
            DO IIO=EWC%IIO_MIN,EWC%IIO_MAX
              IF (MESHES(NOM)%CELL(MESHES(NOM)%CELL_INDEX(IIO,JJO,KKO))%SOLID) CYCLE
              ICC   = MESHES(NOM)%CCVAR(IIO,JJO,KKO,CC_IDCC)
              ! For remote NOM, only accept the cut-cell entry if it appears in the sender-validated
              ! ICC_UNKZ_CC_R list. Otherwise the OMESH cut-cell scalars haven't been filled by
              ! MESH_CC_EXCHANGE and reading them would mix in stale/zero state.
              VALID_SOURCE_CC = ICC > 0 .AND. (PROCESS(NOM)==MY_RANK .OR. NM==NOM)
              IF (ICC > 0 .AND. .NOT.VALID_SOURCE_CC .AND. ALLOCATED(MESHES(NM)%OMESH(NOM)%ICC_UNKZ_CC_R)) THEN
                 IF (ALLOCATED(MESHES(NM)%OMESH(NOM)%ICC_UNKZ_CC_R_MASK)) THEN
                    IF (ICC <= SIZE(MESHES(NM)%OMESH(NOM)%ICC_UNKZ_CC_R_MASK)) &
                       VALID_SOURCE_CC = MESHES(NM)%OMESH(NOM)%ICC_UNKZ_CC_R_MASK(ICC)
                 ENDIF
              ENDIF
              IF (VALID_SOURCE_CC) THEN ! Cut-cells:
                 OCC => MESHES(NOM)%CUT_CELL(ICC)
                 ! PKG11 (and therefore CCHALO state) is populated only for a remote
                 ! source: the same-rank test is PROCESS(NOM)==MY_RANK .OR. NM==NOM.
                 SOURCE_REMOTE = .NOT.(PROCESS(NOM)==MY_RANK .OR. NM==NOM)
                 USE_CCHALO = .FALSE.
                 IF (SOURCE_REMOTE) THEN
                    OM => MESHES(NM)%OMESH(NOM)
                    IF (ALLOCATED(OM%CCHALO_ROW0) .AND. ALLOCATED(OM%CCHALO_VOLUME) .AND. &
                        ALLOCATED(OM%CCHALO_TMP) .AND. ALLOCATED(OM%CCHALO_RSUM)) THEN
                       IF (PREDICTOR) THEN
                          USE_CCHALO = ALLOCATED(OM%CCHALO_RHOS) .AND. ALLOCATED(OM%CCHALO_D) .AND. &
                                       ALLOCATED(OM%CCHALO_ZZS)
                       ELSE
                          USE_CCHALO = ALLOCATED(OM%CCHALO_RHO) .AND. ALLOCATED(OM%CCHALO_DS) .AND. &
                                       ALLOCATED(OM%CCHALO_ZZ)
                       ENDIF
                       IF (USE_CCHALO) THEN
                          IF (ICC<1 .OR. ICC>SIZE(OM%CCHALO_ROW0)) THEN
                             USE_CCHALO = .FALSE.
                          ELSEIF (OM%CCHALO_ROW0(ICC)<1) THEN
                             USE_CCHALO = .FALSE.
                          ENDIF
                       ENDIF
                    ENDIF
                 ENDIF
                 DO JCC=1,OCC%NCELL
                    IROW = 0
                    IF (USE_CCHALO) THEN
                       IROW = OM%CCHALO_ROW0(ICC) + JCC - 1
                       IF (IROW<1 .OR. IROW>OM%NICC_R(2)) IROW = 0
                    ENDIF
                    IF (IROW>0) THEN
                       VCELL   = OM%CCHALO_VOLUME(IROW)
                       TMP_CC  = TMP_CC  + OM%CCHALO_TMP(IROW)*VCELL
                       RSUM_CC = RSUM_CC + OM%CCHALO_RSUM(IROW)*VCELL
                       IF (PREDICTOR) THEN
                          RHO_CC = RHO_CC + OM%CCHALO_RHOS(IROW)*VCELL
                          D_CC   = D_CC   + OM%CCHALO_D(IROW)*VCELL
                          DO NN=1,N_TOTAL_SCALARS
                             ZZ_CC(NN) = ZZ_CC(NN) + OM%CCHALO_ZZS(NN,IROW)*VCELL
                          ENDDO
                       ELSE
                          RHO_CC = RHO_CC + OM%CCHALO_RHO(IROW)*VCELL
                          D_CC   = D_CC   + OM%CCHALO_DS(IROW)*VCELL
                          DO NN=1,N_TOTAL_SCALARS
                             ZZ_CC(NN) = ZZ_CC(NN) + OM%CCHALO_ZZ(NN,IROW)*VCELL
                          ENDDO
                       ENDIF
                       VOL = VOL + VCELL
                    ELSE IF (.NOT.SOURCE_REMOTE) THEN
                       VCELL   = OCC%VOLUME(JCC)
                       ICV=0
                       IG = OCC%IG(JCC)
                       IF (USE_FV_SRC) CALL GET_FV_CV_FOR_CUTCELL(NOM,ICC,JCC,ICV)
                       IF (IG>=1) THEN
                          TMP_CC  = TMP_CC  + FV_SRC%CV%TMP(IG)*VCELL
                          RSUM_CC = RSUM_CC + FV_SRC%CV%RSUM(IG)*VCELL
                          IF (PREDICTOR) THEN
                             RHO_CC = RHO_CC + FV_SRC%CV%RHOS(IG)*VCELL
                             DO NN=1,N_TOTAL_SCALARS
                                ZZ_CC(NN) = ZZ_CC(NN) + FV_SRC%CV%ZZS(NN,IG)*VCELL
                             ENDDO
                             IF (ICV>0) THEN
                                D_CC = D_CC + FV_SRC%CV%D(ICV)*VCELL
                             ELSE
                                D_CC = D_CC + FV_SRC%CV%D(IG)*VCELL
                             ENDIF
                          ELSE
                             RHO_CC = RHO_CC + FV_SRC%CV%RHO(IG)*VCELL
                             DO NN=1,N_TOTAL_SCALARS
                                ZZ_CC(NN) = ZZ_CC(NN) + FV_SRC%CV%ZZ(NN,IG)*VCELL
                             ENDDO
                             IF (ICV>0) THEN
                                D_CC = D_CC + FV_SRC%CV%DS(ICV)*VCELL
                             ELSE
                                D_CC = D_CC + FV_SRC%CV%DS(IG)*VCELL
                             ENDIF
                          ENDIF
                       ELSE
                          TMP_CC  = TMP_CC  + MESHES(NOM)%TMP(IIO,JJO,KKO)*VCELL
                          RSUM_CC = RSUM_CC + MESHES(NOM)%RSUM(IIO,JJO,KKO)*VCELL
                          IF (PREDICTOR) THEN
                             RHO_CC = RHO_CC + MESHES(NOM)%RHOS(IIO,JJO,KKO)*VCELL
                             D_CC   = D_CC   + MESHES(NOM)%D(IIO,JJO,KKO)*VCELL
                             DO NN=1,N_TOTAL_SCALARS
                                ZZ_CC(NN) = ZZ_CC(NN) + MESHES(NOM)%ZZS(IIO,JJO,KKO,NN)*VCELL
                             ENDDO
                          ELSE
                             RHO_CC = RHO_CC + MESHES(NOM)%RHO(IIO,JJO,KKO)*VCELL
                             D_CC   = D_CC   + MESHES(NOM)%DS(IIO,JJO,KKO)*VCELL
                             DO NN=1,N_TOTAL_SCALARS
                                ZZ_CC(NN) = ZZ_CC(NN) + MESHES(NOM)%ZZ(IIO,JJO,KKO,NN)*VCELL
                             ENDDO
                          ENDIF
                       ENDIF
                       VOL = VOL + VCELL
                    ENDIF
                 ENDDO
              ELSEIF(MESHES(NOM)%CCVAR(IIO,JJO,KKO,CC_CGSC) == CC_GASPHASE .OR. ICC > 0) THEN
                 ! Regular cell or unvalidated remote cut-cell.
                 VCELL = MESHES(NOM)%DX(IIO)*MESHES(NOM)%DY(JJO)*MESHES(NOM)%DZ(KKO)
                 TMP_CC  = TMP_CC + TMP(BC%II,BC%JJ,BC%KK)*VCELL
                 IF (PREDICTOR) THEN
                    RHO_CC = RHO_CC + RHOS(BC%II,BC%JJ,BC%KK)*VCELL
                    D_CC   = D_CC   + D(BC%II,BC%JJ,BC%KK)*VCELL
                    DO NN=1,N_TOTAL_SCALARS
                       ZZ_CC(NN) = ZZ_CC(NN) + ZZS(BC%II,BC%JJ,BC%KK,NN)*VCELL
                    ENDDO
                 ELSE
                    RHO_CC = RHO_CC + RHO(BC%II,BC%JJ,BC%KK)*VCELL
                    D_CC   = D_CC   + DS(BC%II,BC%JJ,BC%KK)*VCELL
                    DO NN=1,N_TOTAL_SCALARS
                       ZZ_CC(NN) = ZZ_CC(NN) + ZZ(BC%II,BC%JJ,BC%KK,NN)*VCELL
                    ENDDO
                 ENDIF
                 VOL     = VOL + VCELL
              ENDIF
            ENDDO
         ENDDO
      ENDDO
      ! Add volume averaged variables into ghost cut-cell; publish mapped rows to FV first:
      ICC   = CCVAR(BC%II,BC%JJ,BC%KK,CC_IDCC)
      IF (PREDICTOR) THEN
         DO JCC=1,CUT_CELL(ICC)%NCELL
            IG = CUT_CELL(ICC)%IG(JCC)
            IF (IG>=1) THEN
               FV_DST%CV%RHOS(IG) = RHO_CC/VOL
               FV_DST%CV%TMP(IG)  = TMP_CC/VOL
               FV_DST%CV%RSUM(IG) = RSUM_CC/VOL
               FV_DST%CV%ZZS(1:N_TOTAL_SCALARS,IG) = ZZ_CC(1:N_TOTAL_SCALARS)/VOL
               FV_DST%CV%D(IG)    = D_CC/VOL
            ENDIF
         ENDDO
      ELSE
         DO JCC=1,CUT_CELL(ICC)%NCELL
            IG = CUT_CELL(ICC)%IG(JCC)
            IF (IG>=1) THEN
               FV_DST%CV%RHO(IG) = RHO_CC/VOL
               FV_DST%CV%TMP(IG)  = TMP_CC/VOL
               FV_DST%CV%ZZ(1:N_TOTAL_SCALARS,IG) = ZZ_CC(1:N_TOTAL_SCALARS)/VOL
               FV_DST%CV%DS(IG)   = D_CC/VOL
            ENDIF
         ENDDO
     ENDIF
   ENDDO EXTERNAL_WALL_LOOP
ENDDO MESH_LOOP


END SUBROUTINE FILL_GCCUTCELL_SPECIES


SUBROUTINE CC_TIMEOUT(RNAME,NR,RR)

REAL(EB) :: START_TIME,WAIT_TIME
INTEGER :: NR
TYPE (MPI_REQUEST), DIMENSION(:) :: RR
LOGICAL :: FLAG
CHARACTER(*) :: RNAME

IF (.NOT.PROFILING) THEN

   START_TIME = MPI_WTIME()
   FLAG = .FALSE.
   DO WHILE(.NOT.FLAG)
      CALL MPI_TESTALL(NR,RR(1:NR),FLAG,MPI_STATUSES_IGNORE,IERR)
      WAIT_TIME = MPI_WTIME() - START_TIME
      IF (WAIT_TIME>MPI_TIMEOUT) THEN
         WRITE(LU_ERR,'(A,A,A,I6,A,A)') 'CC_TIMEOUT Error: ',TRIM(RNAME),' timed out for MPI process ',MY_RANK
         CALL MPI_ABORT(MPI_COMM_WORLD,0,IERR)
      ENDIF
   ENDDO
ELSE

   CALL MPI_WAITALL(NR,RR(1:NR),MPI_STATUSES_IGNORE,IERR)

ENDIF

END SUBROUTINE CC_TIMEOUT

SUBROUTINE DEALLOCATE_CCHALO(OM)
TYPE(OMESH_TYPE), INTENT(INOUT) :: OM
IF (ALLOCATED(OM%CCHALO_VOLUME)) DEALLOCATE(OM%CCHALO_VOLUME)
IF (ALLOCATED(OM%CCHALO_RHO))    DEALLOCATE(OM%CCHALO_RHO)
IF (ALLOCATED(OM%CCHALO_RHOS))   DEALLOCATE(OM%CCHALO_RHOS)
IF (ALLOCATED(OM%CCHALO_TMP))    DEALLOCATE(OM%CCHALO_TMP)
IF (ALLOCATED(OM%CCHALO_RSUM))   DEALLOCATE(OM%CCHALO_RSUM)
IF (ALLOCATED(OM%CCHALO_D))      DEALLOCATE(OM%CCHALO_D)
IF (ALLOCATED(OM%CCHALO_DS))     DEALLOCATE(OM%CCHALO_DS)
IF (ALLOCATED(OM%CCHALO_ZZ))     DEALLOCATE(OM%CCHALO_ZZ)
IF (ALLOCATED(OM%CCHALO_ZZS))    DEALLOCATE(OM%CCHALO_ZZS)
IF (ALLOCATED(OM%CCHALO_ROW0))   DEALLOCATE(OM%CCHALO_ROW0)
END SUBROUTINE DEALLOCATE_CCHALO

SUBROUTINE ALLOCATE_CCHALO(OM,NM_RECV,NOM_SEND)
TYPE(OMESH_TYPE), INTENT(INOUT) :: OM
INTEGER, INTENT(IN) :: NM_RECV,NOM_SEND
INTEGER :: ICC1,ICC,JCC,IROW,N_ROW0
IF (NM_RECV<1 .OR. NOM_SEND<1) RETURN
IROW = 0
N_ROW0 = MESHES(NOM_SEND)%N_CUTCELL_MESH + MESHES(NOM_SEND)%N_GCCUTCELL_MESH
ALLOCATE(OM%CCHALO_VOLUME(OM%NICC_R(2)))
ALLOCATE(OM%CCHALO_RHO(OM%NICC_R(2)))
ALLOCATE(OM%CCHALO_RHOS(OM%NICC_R(2)))
ALLOCATE(OM%CCHALO_TMP(OM%NICC_R(2)))
ALLOCATE(OM%CCHALO_RSUM(OM%NICC_R(2)))
ALLOCATE(OM%CCHALO_D(OM%NICC_R(2)))
ALLOCATE(OM%CCHALO_DS(OM%NICC_R(2)))
ALLOCATE(OM%CCHALO_ZZ(1:N_TOTAL_SCALARS,1:OM%NICC_R(2)))
ALLOCATE(OM%CCHALO_ZZS(1:N_TOTAL_SCALARS,1:OM%NICC_R(2)))
ALLOCATE(OM%CCHALO_ROW0(N_ROW0))
OM%CCHALO_VOLUME = 0._EB
OM%CCHALO_RHO = 0._EB
OM%CCHALO_RHOS = 0._EB
OM%CCHALO_TMP = 0._EB
OM%CCHALO_RSUM = 0._EB
OM%CCHALO_D = 0._EB
OM%CCHALO_DS = 0._EB
OM%CCHALO_ZZ = 0._EB
OM%CCHALO_ZZS = 0._EB
OM%CCHALO_ROW0 = 0
! Same walk as the PKG11 unpack: ICC1 over NICC_R(1), ICC=ICC_UNKZ_CC_R(ICC1),
! skip ICC<1 without advancing the row counter, then JCC=1..NCELL.
! CCHALO_ROW0(ICC) is the first row of that contiguous JCC=1..NCELL block.
DO ICC1=1,OM%NICC_R(1)
   ICC = OM%ICC_UNKZ_CC_R(ICC1)
   IF (ICC < 1) CYCLE
   DO JCC=1,MESHES(NOM_SEND)%CUT_CELL(ICC)%NCELL
      IROW = IROW + 1
      OM%CCHALO_VOLUME(IROW) = MESHES(NOM_SEND)%CUT_CELL(ICC)%VOLUME(JCC)
      IF (ICC<=N_ROW0) THEN
         IF (OM%CCHALO_ROW0(ICC)==0) OM%CCHALO_ROW0(ICC) = IROW
      ENDIF
   ENDDO
ENDDO
END SUBROUTINE ALLOCATE_CCHALO

SUBROUTINE ALLOCATE_CFHALO(OM,NOM_SEND)
TYPE(OMESH_TYPE), INTENT(INOUT) :: OM
INTEGER, INTENT(IN) :: NOM_SEND
INTEGER :: ICF1,ICF,IROW,N_ROW0
N_ROW0 = SIZE(MESHES(NOM_SEND)%CUT_FACE)
ALLOCATE(OM%CFHALO_VEL(OM%NICF_R(2)))
ALLOCATE(OM%CFHALO_VELS(OM%NICF_R(2)))
ALLOCATE(OM%CFHALO_VEL_LNK(OM%NICF_R(2)))
ALLOCATE(OM%CFHALO_FN(OM%NICF_R(2)))
ALLOCATE(OM%CFHALO_ROW0(N_ROW0))
OM%CFHALO_VEL = 0._EB
OM%CFHALO_VELS = 0._EB
OM%CFHALO_VEL_LNK = 0._EB
OM%CFHALO_FN = 0._EB
OM%CFHALO_ROW0 = 0
! Same walk as the PKG112 unpack: ICF1 over NICF_R(1), skip ICF<1, then JCF=1..NFACE.
! CFHALO_ROW0(ICF) is the first row of that piece block. A repeated ICF keeps the first row.
IROW = 1
DO ICF1=1,OM%NICF_R(1)
   ICF = OM%ICF_UFFB_CF_R(ICF1)
   IF (ICF<1) CYCLE
   IF (OM%CFHALO_ROW0(ICF)==0) OM%CFHALO_ROW0(ICF) = IROW
   IROW = IROW + MESHES(NOM_SEND)%CUT_FACE(ICF)%NFACE
ENDDO
END SUBROUTINE ALLOCATE_CFHALO

END SUBROUTINE MESH_CC_EXCHANGE


SUBROUTINE CC_MATCH_VELOCITY_FLUX(NM)

! NOTE : Assumes POINT_TO_MESH(NM) has been called.

INTEGER, INTENT(IN) :: NM

! Local Variables:
INTEGER  :: NOM,II,JJ,KK,IOR,IW,IIO,JJO,KKO,ICF,JCF,ICFO,JCFO,IF_,IROW
REAL(EB) :: T_NOW,DA_OTHER,FN_OTHER
TYPE (OMESH_TYPE), POINTER :: OM
TYPE (MESH_TYPE), POINTER :: M2
TYPE (CC_CUTFACE_TYPE), POINTER :: CFO
TYPE (CC_FV_TYPE), POINTER :: FV
CALL POINT_TO_MESH(NM)

T_NOW = CURRENT_TIME()

! Assign local variable names

CALL POINT_TO_MESH(NM)
FV=>MESHES(NM)%FV

! Loop over all cell edges and determine the appropriate velocity BCs

EXTERNAL_WALL_LOOP: DO IW=1,N_EXTERNAL_WALL_CELLS

   WC=>WALL(IW)
   EWC=>EXTERNAL_WALL(IW)
   IF (WC%BOUNDARY_TYPE/=INTERPOLATED_BOUNDARY) CYCLE EXTERNAL_WALL_LOOP

   BC => BOUNDARY_COORD(WC%BC_INDEX)
   II  = BC%II
   JJ  = BC%JJ
   KK  = BC%KK
   IOR = BC%IOR
   NOM = EWC%NOM
   OM => OMESH(NOM)
   M2 => MESHES(NOM)

   ! Determine the area of the interpolated cell face

   DA_OTHER = 0._EB
   FN_OTHER = 0._EB

   ! Determine the normal component of velocity flux from the other mesh and use it for average

   SELECT CASE(IOR)

      CASE( 1)

         ICF = FCVAR(0,JJ,KK,CC_IDCF,ABS(IOR))
         DO KKO=EWC%KKO_MIN,EWC%KKO_MAX
            DO JJO=EWC%JJO_MIN,EWC%JJO_MAX
               DO IIO=EWC%IIO_MIN,EWC%IIO_MAX

                  IF (M2%CELL(M2%CELL_INDEX(IIO,JJO,KKO))%SOLID) CYCLE ! Drop if OMESH cell is solid.
                  IF (M2%FCVAR(IIO,JJO,KKO,CC_FGSC,ABS(IOR))==CC_SOLID) CYCLE  ! Drop if solid cart face.
                  ICFO = M2%FCVAR(IIO,JJO,KKO,CC_IDCF,ABS(IOR))
                  IF(ICFO>0) THEN
                     CFO => M2%CUT_FACE(ICFO)
                     DO JCFO=1,CFO%NFACE
                        IROW = OM%CFHALO_ROW0(ICFO)+JCFO-1
                        DA_OTHER = DA_OTHER + CFO%AREA(JCFO)
                        FN_OTHER = FN_OTHER + OM%CFHALO_FN(IROW)*CFO%AREA(JCFO)
                     ENDDO
                  ELSE
                     DA_OTHER = DA_OTHER + M2%DY(JJO)*M2%DZ(KKO)
                     FN_OTHER = FN_OTHER + OM%FVX(IIO,JJO,KKO)*M2%DY(JJO)*M2%DZ(KKO)
                  ENDIF
               ENDDO
            ENDDO
         ENDDO
         IF(ICF<1) FVX(0,JJ,KK) = 0.5_EB*(FVX(0,JJ,KK) + FN_OTHER/DA_OTHER)

      CASE(-1)

         ICF = FCVAR(IBAR,JJ,KK,CC_IDCF,ABS(IOR))
         DO KKO=EWC%KKO_MIN,EWC%KKO_MAX
            DO JJO=EWC%JJO_MIN,EWC%JJO_MAX
               DO IIO=EWC%IIO_MIN,EWC%IIO_MAX

                  IF (M2%CELL(M2%CELL_INDEX(IIO,JJO,KKO))%SOLID) CYCLE
                  IF (M2%FCVAR(IIO-1,JJO,KKO,CC_FGSC,ABS(IOR))==CC_SOLID) CYCLE

                  ICFO = M2%FCVAR(IIO-1,JJO,KKO,CC_IDCF,ABS(IOR))
                  IF(ICFO>0) THEN
                     CFO => M2%CUT_FACE(ICFO)
                     DO JCFO=1,CFO%NFACE
                        IROW = OM%CFHALO_ROW0(ICFO)+JCFO-1
                        DA_OTHER = DA_OTHER + CFO%AREA(JCFO)
                        FN_OTHER = FN_OTHER + OM%CFHALO_FN(IROW)*CFO%AREA(JCFO)
                     ENDDO
                  ELSE
                     DA_OTHER = DA_OTHER + M2%DY(JJO)*M2%DZ(KKO)
                     FN_OTHER = FN_OTHER + OM%FVX(IIO-1,JJO,KKO)*M2%DY(JJO)*M2%DZ(KKO)
                  ENDIF
               ENDDO
            ENDDO
         ENDDO
         IF(ICF<1) FVX(IBAR,JJ,KK) = 0.5_EB*(FVX(IBAR,JJ,KK) + FN_OTHER/DA_OTHER)

      CASE( 2)

         ICF = FCVAR(II,0,KK,CC_IDCF,ABS(IOR))
         DO KKO=EWC%KKO_MIN,EWC%KKO_MAX
            DO JJO=EWC%JJO_MIN,EWC%JJO_MAX
               DO IIO=EWC%IIO_MIN,EWC%IIO_MAX

                  IF (M2%CELL(M2%CELL_INDEX(IIO,JJO,KKO))%SOLID) CYCLE
                  IF (M2%FCVAR(IIO,JJO,KKO,CC_FGSC,ABS(IOR))==CC_SOLID) CYCLE

                  ICFO = M2%FCVAR(IIO,JJO,KKO,CC_IDCF,ABS(IOR))
                  IF(ICFO>0) THEN
                     CFO => M2%CUT_FACE(ICFO)
                     DO JCFO=1,CFO%NFACE
                        IROW = OM%CFHALO_ROW0(ICFO)+JCFO-1
                        DA_OTHER = DA_OTHER + CFO%AREA(JCFO)
                        FN_OTHER = FN_OTHER + OM%CFHALO_FN(IROW)*CFO%AREA(JCFO)
                     ENDDO
                  ELSE
                     DA_OTHER = DA_OTHER + M2%DX(IIO)*M2%DZ(KKO)
                     FN_OTHER = FN_OTHER + OM%FVY(IIO,JJO,KKO)*M2%DX(IIO)*M2%DZ(KKO)
                  ENDIF
               ENDDO
            ENDDO
         ENDDO
         IF(ICF<1) FVY(II,0,KK) = 0.5_EB*(FVY(II,0,KK) + FN_OTHER/DA_OTHER)

      CASE(-2)

         ICF = FCVAR(II,JBAR,KK,CC_IDCF,ABS(IOR))
         DO KKO=EWC%KKO_MIN,EWC%KKO_MAX
            DO JJO=EWC%JJO_MIN,EWC%JJO_MAX
               DO IIO=EWC%IIO_MIN,EWC%IIO_MAX

                  IF (M2%CELL(M2%CELL_INDEX(IIO,JJO,KKO))%SOLID) CYCLE
                  IF (M2%FCVAR(IIO,JJO-1,KKO,CC_FGSC,ABS(IOR))==CC_SOLID) CYCLE

                  ICFO = M2%FCVAR(IIO,JJO-1,KKO,CC_IDCF,ABS(IOR))
                  IF(ICFO>0) THEN
                     CFO => M2%CUT_FACE(ICFO)
                     DO JCFO=1,CFO%NFACE
                        IROW = OM%CFHALO_ROW0(ICFO)+JCFO-1
                        DA_OTHER = DA_OTHER + CFO%AREA(JCFO)
                        FN_OTHER = FN_OTHER + OM%CFHALO_FN(IROW)*CFO%AREA(JCFO)
                     ENDDO
                  ELSE
                     DA_OTHER = DA_OTHER + M2%DX(IIO)*M2%DZ(KKO)
                     FN_OTHER = FN_OTHER + OM%FVY(IIO,JJO-1,KKO)*M2%DX(IIO)*M2%DZ(KKO)
                  ENDIF
             ENDDO
          ENDDO
       ENDDO
       IF(ICF<1) FVY(II,JBAR,KK) = 0.5_EB*(FVY(II,JBAR,KK) + FN_OTHER/DA_OTHER)


      CASE( 3)

         ICF = FCVAR(II,JJ,0,CC_IDCF,ABS(IOR))
         DO KKO=EWC%KKO_MIN,EWC%KKO_MAX
            DO JJO=EWC%JJO_MIN,EWC%JJO_MAX
               DO IIO=EWC%IIO_MIN,EWC%IIO_MAX

                  IF (M2%CELL(M2%CELL_INDEX(IIO,JJO,KKO))%SOLID) CYCLE
                  IF (M2%FCVAR(IIO,JJO,KKO,CC_FGSC,ABS(IOR))==CC_SOLID) CYCLE

                  ICFO = M2%FCVAR(IIO,JJO,KKO,CC_IDCF,ABS(IOR))
                  IF(ICFO>0) THEN
                     CFO => M2%CUT_FACE(ICFO)
                     DO JCFO=1,CFO%NFACE
                        IROW = OM%CFHALO_ROW0(ICFO)+JCFO-1
                        DA_OTHER = DA_OTHER + CFO%AREA(JCFO)
                        FN_OTHER = FN_OTHER + OM%CFHALO_FN(IROW)*CFO%AREA(JCFO)
                     ENDDO
                  ELSE
                     DA_OTHER = DA_OTHER + M2%DX(IIO)*M2%DY(JJO)
                     FN_OTHER = FN_OTHER + OM%FVZ(IIO,JJO,KKO)*M2%DX(IIO)*M2%DY(JJO)
                  ENDIF
               ENDDO
            ENDDO
         ENDDO
         IF(ICF<1) FVZ(II,JJ,0) = 0.5_EB*(FVZ(II,JJ,0) + FN_OTHER/DA_OTHER)

      CASE(-3)

         ICF = FCVAR(II,JJ,KBAR,CC_IDCF,ABS(IOR))
         DO KKO=EWC%KKO_MIN,EWC%KKO_MAX
            DO JJO=EWC%JJO_MIN,EWC%JJO_MAX
               DO IIO=EWC%IIO_MIN,EWC%IIO_MAX

                  IF (M2%CELL(M2%CELL_INDEX(IIO,JJO,KKO))%SOLID) CYCLE
                  IF (M2%FCVAR(IIO,JJO,KKO-1,CC_FGSC,ABS(IOR))==CC_SOLID) CYCLE

                  ICFO = M2%FCVAR(IIO,JJO,KKO-1,CC_IDCF,ABS(IOR))
                  IF(ICFO>0) THEN
                     CFO => M2%CUT_FACE(ICFO)
                     DO JCFO=1,CFO%NFACE
                        IROW = OM%CFHALO_ROW0(ICFO)+JCFO-1
                        DA_OTHER = DA_OTHER + CFO%AREA(JCFO)
                        FN_OTHER = FN_OTHER + OM%CFHALO_FN(IROW)*CFO%AREA(JCFO)
                     ENDDO
                  ELSE
                     DA_OTHER = DA_OTHER + M2%DX(IIO)*M2%DY(JJO)
                     FN_OTHER = FN_OTHER + OM%FVZ(IIO,JJO,KKO-1)*M2%DX(IIO)*M2%DY(JJO)
                  ENDIF
               ENDDO
            ENDDO
         ENDDO
         IF(ICF<1) FVZ(II,JJ,KBAR) = 0.5_EB*(FVZ(II,JJ,KBAR) + FN_OTHER/DA_OTHER)

   END SELECT

   ! IF EWC has a cut-face match the cut-face FN:
   IF(ICF>0) THEN
      CF => CUT_FACE(ICF)
      DO JCF=1,CF%NFACE
         IF_=MESHES(NM)%CUT_FACE(ICF)%FC(JCF)
         FV%FACE%FN(IF_)=0.5_EB*(FV%FACE%FN(IF_)+FN_OTHER/DA_OTHER)
      ENDDO
      CF%FV = CC_FV_CUTFACE_MOM_AREA(NM,ICF,CC_FV_MOM_FN)/SUM(CF%AREA(1:CF%NFACE))

   ENDIF


ENDDO EXTERNAL_WALL_LOOP

T_USED(4)=T_USED(4)+CURRENT_TIME()-T_NOW

RETURN
END SUBROUTINE CC_MATCH_VELOCITY_FLUX


! ------------------------------ CC_MATCH_VELOCITY ----------------------------

SUBROUTINE CC_MATCH_VELOCITY(NM,APPLY_TO_ESTIMATED_VARIABLES,DO_U_GHOST)

! Assumes POINT_TO_MESH(NM) has NOT been called.

INTEGER, INTENT(IN) :: NM
LOGICAL, INTENT(IN) :: APPLY_TO_ESTIMATED_VARIABLES,DO_U_GHOST

! Local Variables:
INTEGER  :: NOM,II,JJ,KK,IOR,IW,IIO,JJO,KKO,ICF,JCF,IF_,ICFO,JCFO,IROW !,I,J,K,X1AXIS
REAL(EB) :: T_NOW,DA_OTHER,VEL_OTHER,VEL_LNK_OTHER,PRFCT,NOM_CELLS
REAL(EB) :: AU,AU1,AV,AV1,AW,AW1
REAL(EB), POINTER, DIMENSION(:,:,:) :: UU,VV,WW,OM_UU,OM_VV,OM_WW
TYPE (OMESH_TYPE), POINTER :: OM
TYPE (MESH_TYPE), POINTER :: M2
TYPE (CC_CUTFACE_TYPE), POINTER :: CFO
TYPE(CC_FV_TYPE), POINTER :: FV
CALL POINT_TO_MESH(NM)

T_NOW = CURRENT_TIME()
FV=>MESHES(NM)%FV

IF (APPLY_TO_ESTIMATED_VARIABLES) THEN
   UU => US
   VV => VS
   WW => WS
   PRFCT = 1._EB
ELSE
   UU => U
   VV => V
   WW => W
   PRFCT = 0._EB
ENDIF

! NOTE : Loop here is done by N_EXTERNAL_WALL_CELLS. For single pressure variable per cut-cell
! cut faces should be averaged with underlying omesh cut-faces. To Do.
EXTERNAL_WALL_LOOP: DO IW=1,MESHES(NM)%N_EXTERNAL_WALL_CELLS

   WC=>WALL(IW)
   EWC=>EXTERNAL_WALL(IW)
   EWC%BOUNDARY_TYPE_PREVIOUS = WC%BOUNDARY_TYPE

   IF (WC%BOUNDARY_TYPE/=INTERPOLATED_BOUNDARY) CYCLE EXTERNAL_WALL_LOOP

   BC =>BOUNDARY_COORD(WC%BC_INDEX)
   II  = BC%II
   JJ  = BC%JJ
   KK  = BC%KK
   IOR = BC%IOR
   NOM = EWC%NOM
   OM => OMESH(NOM)
   M2 => MESHES(NOM)

   ! Get velocity average from the Other mesh, average with local cut-face or reg face velocity for this
   ! wall cell:
   DA_OTHER      = 0._EB
   VEL_OTHER     = 0._EB
   VEL_LNK_OTHER = 0._EB

   SELECT CASE(IOR)
   CASE( IAXIS)

      IF (APPLY_TO_ESTIMATED_VARIABLES) THEN; OM_UU => OM%US; ELSE; OM_UU => OM%U; ENDIF
      ! Note id current EWC contains cut-faces, assume first cut-face velocity for OMESH VEL averaging:
      ICF = FCVAR(0,JJ,KK,CC_IDCF,ABS(IOR)); JCF = 1;
      DO KKO=EWC%KKO_MIN,EWC%KKO_MAX
         DO JJO=EWC%JJO_MIN,EWC%JJO_MAX
            DO IIO=EWC%IIO_MIN,EWC%IIO_MAX

               IF (M2%CELL(M2%CELL_INDEX(IIO,JJO,KKO))%SOLID) CYCLE ! Drop if OMESH cell is solid.
               IF (M2%FCVAR(IIO,JJO,KKO,CC_FGSC,ABS(IOR))==CC_SOLID) CYCLE  ! Drop if cartesian face tagged solid.

               ICFO = M2%FCVAR(IIO,JJO,KKO,CC_IDCF,ABS(IOR))
               IF(ICFO>0) THEN
                  CFO => M2%CUT_FACE(ICFO)
                  DO JCFO=1,CFO%NFACE
                     IROW = OM%CFHALO_ROW0(ICFO)+JCFO-1
                     DA_OTHER      = DA_OTHER  + CFO%AREA(JCFO)
                     VEL_OTHER     = VEL_OTHER + &
                                     (PRFCT*OM%CFHALO_VELS(IROW)+(1._EB-PRFCT)*OM%CFHALO_VEL(IROW))*CFO%AREA(JCFO)
                     VEL_LNK_OTHER = VEL_LNK_OTHER + OM%CFHALO_VEL_LNK(IROW)*CFO%AREA(JCFO)
                     IF (EWC%AREA_RATIO>0.9_EB) THEN ! Flux match OMESH cut-face vel.
                        IF(ICF>0) THEN
                           IF(APPLY_TO_ESTIMATED_VARIABLES) THEN
                              OM%CFHALO_VELS(IROW) = 0.5_EB*(OM%CFHALO_VELS(IROW)+CC_FV_CUTFACE_MOM(NM,ICF,JCF,CC_FV_MOM_VELS))
                           ELSE
                              OM%CFHALO_VEL(IROW)  = 0.5_EB*(OM%CFHALO_VEL(IROW)+CC_FV_CUTFACE_MOM(NM,ICF,JCF,CC_FV_MOM_VEL))
                           ENDIF
                           OM%CFHALO_VEL_LNK(IROW) = 0.5_EB*(OM%CFHALO_VEL_LNK(IROW)+FV%FACE%VEL_LNK(CUT_FACE(ICF)%FC(JCF)))
                        ELSE
                           IF(APPLY_TO_ESTIMATED_VARIABLES) THEN
                              OM%CFHALO_VELS(IROW) = 0.5_EB*(OM%CFHALO_VELS(IROW)+UU(0,JJ,KK))
                           ELSE
                              OM%CFHALO_VEL(IROW)  = 0.5_EB*(OM%CFHALO_VEL(IROW)+UU(0,JJ,KK))
                           ENDIF
                           OM%CFHALO_VEL_LNK(IROW) = 0.5_EB*(OM%CFHALO_VEL_LNK(IROW)+EWC_UN_LNK(IW))
                        ENDIF
                     ENDIF
                  ENDDO
               ELSE
                  DA_OTHER      = DA_OTHER  + M2%DY(JJO)*M2%DZ(KKO)
                  VEL_OTHER     = VEL_OTHER + OM_UU(IIO,JJO,KKO)*M2%DY(JJO)*M2%DZ(KKO)
                  VEL_LNK_OTHER = VEL_LNK_OTHER + OM%U_LNK(IIO,JJO,KKO)*M2%DY(JJO)*M2%DZ(KKO)
                  ! Flux match OMESH reg face vel.
                  IF (EWC%AREA_RATIO>0.9_EB) THEN
                     IF(ICF>0) THEN
                        OM_UU(IIO,JJO,KKO)    = 0.5_EB*(OM_UU(IIO,JJO,KKO)+ &
                        PRFCT*CC_FV_CUTFACE_MOM(NM,ICF,JCF,CC_FV_MOM_VELS)+ &
                        (1._EB-PRFCT)*CC_FV_CUTFACE_MOM(NM,ICF,JCF,CC_FV_MOM_VEL))
                        OM%U_LNK(IIO,JJO,KKO) = 0.5_EB*(OM%U_LNK(IIO,JJO,KKO)+FV%FACE%VEL_LNK(CUT_FACE(ICF)%FC(JCF)))
                     ELSE
                        OM_UU(IIO,JJO,KKO)    = 0.5_EB*(OM_UU(IIO,JJO,KKO)+UU(0,JJ,KK))
                        OM%U_LNK(IIO,JJO,KKO) = 0.5_EB*(OM%U_LNK(IIO,JJO,KKO)+EWC_UN_LNK(IW))
                     ENDIF
                  ENDIF
               ENDIF
            ENDDO
         ENDDO
      ENDDO
      IF(ICF<1) THEN ! This is a regular, or RC face.
         UVW_SAVE(IW)   = UU(0,JJ,KK) ! This is the original U saved in MATCH_VELOCITY previously.
         UU(0,JJ,KK)    = 0.5_EB*(UU(0,JJ,KK) + VEL_OTHER/DA_OTHER)
         EWC_UN_LNK(IW) = 0.5_EB*(EWC_UN_LNK(IW) + VEL_LNK_OTHER/DA_OTHER)
      ENDIF

   CASE(-IAXIS)

      IF (APPLY_TO_ESTIMATED_VARIABLES) THEN; OM_UU => OM%US; ELSE; OM_UU => OM%U; ENDIF
      ICF = FCVAR(IBAR,JJ,KK,CC_IDCF,ABS(IOR)); JCF = 1;
      DO KKO=EWC%KKO_MIN,EWC%KKO_MAX
         DO JJO=EWC%JJO_MIN,EWC%JJO_MAX
            DO IIO=EWC%IIO_MIN,EWC%IIO_MAX

               IF (M2%CELL(M2%CELL_INDEX(IIO,JJO,KKO))%SOLID) CYCLE
               IF (M2%FCVAR(IIO-1,JJO,KKO,CC_FGSC,ABS(IOR))==CC_SOLID) CYCLE

               ICFO = M2%FCVAR(IIO-1,JJO,KKO,CC_IDCF,ABS(IOR))
               IF(ICFO>0) THEN
                  CFO => M2%CUT_FACE(ICFO)
                  DO JCFO=1,CFO%NFACE
                     IROW = OM%CFHALO_ROW0(ICFO)+JCFO-1
                     DA_OTHER      = DA_OTHER  + CFO%AREA(JCFO)
                     VEL_OTHER     = VEL_OTHER + &
                                     (PRFCT*OM%CFHALO_VELS(IROW)+(1._EB-PRFCT)*OM%CFHALO_VEL(IROW))*CFO%AREA(JCFO)
                     VEL_LNK_OTHER = VEL_LNK_OTHER + OM%CFHALO_VEL_LNK(IROW)*CFO%AREA(JCFO)
                     IF (EWC%AREA_RATIO>0.9_EB) THEN ! Flux match OMESH cut-face vel.
                        IF(ICF>0) THEN
                           IF(APPLY_TO_ESTIMATED_VARIABLES) THEN
                              OM%CFHALO_VELS(IROW) = 0.5_EB*(OM%CFHALO_VELS(IROW)+CC_FV_CUTFACE_MOM(NM,ICF,JCF,CC_FV_MOM_VELS))
                           ELSE
                              OM%CFHALO_VEL(IROW)  = 0.5_EB*(OM%CFHALO_VEL(IROW)+CC_FV_CUTFACE_MOM(NM,ICF,JCF,CC_FV_MOM_VEL))
                           ENDIF
                           OM%CFHALO_VEL_LNK(IROW) = 0.5_EB*(OM%CFHALO_VEL_LNK(IROW)+FV%FACE%VEL_LNK(CUT_FACE(ICF)%FC(JCF)))
                        ELSE
                           IF(APPLY_TO_ESTIMATED_VARIABLES) THEN
                              OM%CFHALO_VELS(IROW) = 0.5_EB*(OM%CFHALO_VELS(IROW)+UU(IBAR,JJ,KK))
                           ELSE
                              OM%CFHALO_VEL(IROW)  = 0.5_EB*(OM%CFHALO_VEL(IROW)+UU(IBAR,JJ,KK))
                           ENDIF
                           OM%CFHALO_VEL_LNK(IROW) = 0.5_EB*(OM%CFHALO_VEL_LNK(IROW)+EWC_UN_LNK(IW))
                        ENDIF
                     ENDIF
                  ENDDO
               ELSE
                  DA_OTHER      = DA_OTHER  + M2%DY(JJO)*M2%DZ(KKO)
                  VEL_OTHER     = VEL_OTHER + OM_UU(IIO-1,JJO,KKO)*M2%DY(JJO)*M2%DZ(KKO)
                  VEL_LNK_OTHER = VEL_LNK_OTHER + OM%U_LNK(IIO-1,JJO,KKO)*M2%DY(JJO)*M2%DZ(KKO)
                  IF (EWC%AREA_RATIO>0.9_EB) THEN
                     IF(ICF>0) THEN
                        OM_UU(IIO-1,JJO,KKO)    = 0.5_EB*(OM_UU(IIO-1,JJO,KKO)+ &
                        PRFCT*CC_FV_CUTFACE_MOM(NM,ICF,JCF,CC_FV_MOM_VELS)+ &
                        (1._EB-PRFCT)*CC_FV_CUTFACE_MOM(NM,ICF,JCF,CC_FV_MOM_VEL))
                        OM%U_LNK(IIO-1,JJO,KKO) = 0.5_EB*(OM%U_LNK(IIO-1,JJO,KKO)+FV%FACE%VEL_LNK(CUT_FACE(ICF)%FC(JCF)))
                     ELSE
                        OM_UU(IIO-1,JJO,KKO)    = 0.5_EB*(OM_UU(IIO-1,JJO,KKO)+UU(IBAR,JJ,KK))
                        OM%U_LNK(IIO-1,JJO,KKO) = 0.5_EB*(OM%U_LNK(IIO-1,JJO,KKO)+EWC_UN_LNK(IW))
                     ENDIF
                  ENDIF
               ENDIF
            ENDDO
         ENDDO
      ENDDO
      IF(ICF<1) THEN
         UVW_SAVE(IW)   =  UU(IBAR,JJ,KK)
         UU(IBAR,JJ,KK) = 0.5_EB*(UU(IBAR,JJ,KK) + VEL_OTHER/DA_OTHER)
         EWC_UN_LNK(IW) = 0.5_EB*(EWC_UN_LNK(IW) + VEL_LNK_OTHER/DA_OTHER)
      ENDIF

   CASE( JAXIS)

      IF (APPLY_TO_ESTIMATED_VARIABLES) THEN; OM_VV => OM%VS; ELSE; OM_VV => OM%V; ENDIF
      ICF = FCVAR(II,0,KK,CC_IDCF,ABS(IOR)); JCF = 1
      DO KKO=EWC%KKO_MIN,EWC%KKO_MAX
         DO JJO=EWC%JJO_MIN,EWC%JJO_MAX
            DO IIO=EWC%IIO_MIN,EWC%IIO_MAX

               IF (M2%CELL(M2%CELL_INDEX(IIO,JJO,KKO))%SOLID) CYCLE
               IF (M2%FCVAR(IIO,JJO,KKO,CC_FGSC,ABS(IOR))==CC_SOLID) CYCLE

               ICFO = M2%FCVAR(IIO,JJO,KKO,CC_IDCF,ABS(IOR))
               IF(ICFO>0) THEN
                  CFO => M2%CUT_FACE(ICFO)
                  DO JCFO=1,CFO%NFACE
                     IROW = OM%CFHALO_ROW0(ICFO)+JCFO-1
                     DA_OTHER      = DA_OTHER  + CFO%AREA(JCFO)
                     VEL_OTHER     = VEL_OTHER + &
                                     (PRFCT*OM%CFHALO_VELS(IROW)+(1._EB-PRFCT)*OM%CFHALO_VEL(IROW))*CFO%AREA(JCFO)
                     VEL_LNK_OTHER = VEL_LNK_OTHER + OM%CFHALO_VEL_LNK(IROW)*CFO%AREA(JCFO)
                     IF (EWC%AREA_RATIO>0.9_EB) THEN ! Flux match OMESH cut-face vel.
                        IF(ICF>0) THEN
                           IF(APPLY_TO_ESTIMATED_VARIABLES) THEN
                              OM%CFHALO_VELS(IROW) = 0.5_EB*(OM%CFHALO_VELS(IROW)+CC_FV_CUTFACE_MOM(NM,ICF,JCF,CC_FV_MOM_VELS))
                           ELSE
                              OM%CFHALO_VEL(IROW)  = 0.5_EB*(OM%CFHALO_VEL(IROW)+CC_FV_CUTFACE_MOM(NM,ICF,JCF,CC_FV_MOM_VEL))
                           ENDIF

                           OM%CFHALO_VEL_LNK(IROW) = 0.5_EB*(OM%CFHALO_VEL_LNK(IROW)+FV%FACE%VEL_LNK(CUT_FACE(ICF)%FC(JCF)))
                        ELSE
                           IF(APPLY_TO_ESTIMATED_VARIABLES) THEN
                              OM%CFHALO_VELS(IROW) = 0.5_EB*(OM%CFHALO_VELS(IROW)+VV(II,0,KK))
                           ELSE
                              OM%CFHALO_VEL(IROW)  = 0.5_EB*(OM%CFHALO_VEL(IROW)+VV(II,0,KK))
                           ENDIF
                           OM%CFHALO_VEL_LNK(IROW) = 0.5_EB*(OM%CFHALO_VEL_LNK(IROW)+EWC_UN_LNK(IW))
                        ENDIF
                     ENDIF
                  ENDDO
               ELSE
                  DA_OTHER      = DA_OTHER  + M2%DX(IIO)*M2%DZ(KKO)
                  VEL_OTHER     = VEL_OTHER + OM_VV(IIO,JJO,KKO)*M2%DX(IIO)*M2%DZ(KKO)
                  VEL_LNK_OTHER = VEL_LNK_OTHER + OM%V_LNK(IIO,JJO,KKO)*M2%DX(IIO)*M2%DZ(KKO)
                  IF (EWC%AREA_RATIO>0.9_EB) THEN
                     IF(ICF>0) THEN
                        OM_VV(IIO,JJO,KKO)    = 0.5_EB*(OM_VV(IIO,JJO,KKO)+ &
                        PRFCT*CC_FV_CUTFACE_MOM(NM,ICF,JCF,CC_FV_MOM_VELS)+ &
                        (1._EB-PRFCT)*CC_FV_CUTFACE_MOM(NM,ICF,JCF,CC_FV_MOM_VEL))
                        OM%V_LNK(IIO,JJO,KKO) = 0.5_EB*(OM%V_LNK(IIO,JJO,KKO)+FV%FACE%VEL_LNK(CUT_FACE(ICF)%FC(JCF)))
                     ELSE
                        OM_VV(IIO,JJO,KKO)    = 0.5_EB*(OM_VV(IIO,JJO,KKO)+VV(II,0,KK))
                        OM%V_LNK(IIO,JJO,KKO) = 0.5_EB*(OM%V_LNK(IIO,JJO,KKO)+EWC_UN_LNK(IW))
                     ENDIF
                  ENDIF
               ENDIF
            ENDDO
         ENDDO
      ENDDO
      IF(ICF<1) THEN
         UVW_SAVE(IW)   = VV(II,0,KK)
         VV(II,0,KK)    = 0.5_EB*(VV(II,0,KK) + VEL_OTHER/DA_OTHER)
         EWC_UN_LNK(IW) = 0.5_EB*(EWC_UN_LNK(IW) + VEL_LNK_OTHER/DA_OTHER)
      ENDIF

   CASE(-JAXIS)

      IF (APPLY_TO_ESTIMATED_VARIABLES) THEN; OM_VV => OM%VS; ELSE; OM_VV => OM%V; ENDIF
      ICF = FCVAR(II,JBAR,KK,CC_IDCF,ABS(IOR)); JCF = 1
      DO KKO=EWC%KKO_MIN,EWC%KKO_MAX
         DO JJO=EWC%JJO_MIN,EWC%JJO_MAX
            DO IIO=EWC%IIO_MIN,EWC%IIO_MAX

               IF (M2%CELL(M2%CELL_INDEX(IIO,JJO,KKO))%SOLID) CYCLE
               IF (M2%FCVAR(IIO,JJO-1,KKO,CC_FGSC,ABS(IOR))==CC_SOLID) CYCLE

               ICFO = M2%FCVAR(IIO,JJO-1,KKO,CC_IDCF,ABS(IOR))
               IF(ICFO>0) THEN
                  CFO => M2%CUT_FACE(ICFO)
                  DO JCFO=1,CFO%NFACE
                     IROW = OM%CFHALO_ROW0(ICFO)+JCFO-1
                     DA_OTHER      = DA_OTHER  + CFO%AREA(JCFO)
                     VEL_OTHER     = VEL_OTHER + &
                                     (PRFCT*OM%CFHALO_VELS(IROW)+(1._EB-PRFCT)*OM%CFHALO_VEL(IROW))*CFO%AREA(JCFO)
                     VEL_LNK_OTHER = VEL_LNK_OTHER + OM%CFHALO_VEL_LNK(IROW)*CFO%AREA(JCFO)
                     IF (EWC%AREA_RATIO>0.9_EB) THEN ! Flux match OMESH cut-face vel.
                        IF(ICF>0) THEN
                           IF(APPLY_TO_ESTIMATED_VARIABLES) THEN
                              OM%CFHALO_VELS(IROW) = 0.5_EB*(OM%CFHALO_VELS(IROW)+CC_FV_CUTFACE_MOM(NM,ICF,JCF,CC_FV_MOM_VELS))
                           ELSE
                              OM%CFHALO_VEL(IROW)  = 0.5_EB*(OM%CFHALO_VEL(IROW)+CC_FV_CUTFACE_MOM(NM,ICF,JCF,CC_FV_MOM_VEL))
                           ENDIF
                           OM%CFHALO_VEL_LNK(IROW) = 0.5_EB*(OM%CFHALO_VEL_LNK(IROW)+FV%FACE%VEL_LNK(CUT_FACE(ICF)%FC(JCF)))
                        ELSE
                           IF(APPLY_TO_ESTIMATED_VARIABLES) THEN
                              OM%CFHALO_VELS(IROW) = 0.5_EB*(OM%CFHALO_VELS(IROW)+VV(II,JBAR,KK))
                           ELSE
                              OM%CFHALO_VEL(IROW)  = 0.5_EB*(OM%CFHALO_VEL(IROW)+VV(II,JBAR,KK))
                           ENDIF
                           OM%CFHALO_VEL_LNK(IROW) = 0.5_EB*(OM%CFHALO_VEL_LNK(IROW)+EWC_UN_LNK(IW))
                        ENDIF
                     ENDIF
                  ENDDO
               ELSE
                  DA_OTHER      = DA_OTHER  + M2%DX(IIO)*M2%DZ(KKO)
                  VEL_OTHER     = VEL_OTHER + OM_VV(IIO,JJO-1,KKO)*M2%DX(IIO)*M2%DZ(KKO)
                  VEL_LNK_OTHER = VEL_LNK_OTHER + OM%V_LNK(IIO,JJO-1,KKO)*M2%DX(IIO)*M2%DZ(KKO)
                  IF (EWC%AREA_RATIO>0.9_EB) THEN
                     IF(ICF>0) THEN
                        OM_VV(IIO,JJO-1,KKO)    = 0.5_EB*(OM_VV(IIO,JJO-1,KKO)+ &
                        PRFCT*CC_FV_CUTFACE_MOM(NM,ICF,JCF,CC_FV_MOM_VELS)+ &
                        (1._EB-PRFCT)*CC_FV_CUTFACE_MOM(NM,ICF,JCF,CC_FV_MOM_VEL))
                        OM%V_LNK(IIO,JJO-1,KKO) = 0.5_EB*(OM%V_LNK(IIO,JJO-1,KKO)+FV%FACE%VEL_LNK(CUT_FACE(ICF)%FC(JCF)))
                     ELSE
                        OM_VV(IIO,JJO-1,KKO)    = 0.5_EB*(OM_VV(IIO,JJO-1,KKO)+VV(II,JBAR,KK))
                        OM%V_LNK(IIO,JJO-1,KKO) = 0.5_EB*(OM%V_LNK(IIO,JJO-1,KKO)+EWC_UN_LNK(IW))
                     ENDIF
                  ENDIF
               ENDIF
            ENDDO
         ENDDO
      ENDDO
      IF(ICF<1) THEN
         UVW_SAVE(IW)   = VV(II,JBAR,KK)
         VV(II,JBAR,KK) = 0.5_EB*(VV(II,JBAR,KK) + VEL_OTHER/DA_OTHER)
         EWC_UN_LNK(IW) = 0.5_EB*(EWC_UN_LNK(IW) + VEL_LNK_OTHER/DA_OTHER)
      ENDIF

   CASE( KAXIS)

      IF (APPLY_TO_ESTIMATED_VARIABLES) THEN; OM_WW => OM%WS; ELSE; OM_WW => OM%W; ENDIF
      ICF = FCVAR(II,JJ,0,CC_IDCF,ABS(IOR)); JCF = 1
      DO KKO=EWC%KKO_MIN,EWC%KKO_MAX
         DO JJO=EWC%JJO_MIN,EWC%JJO_MAX
            DO IIO=EWC%IIO_MIN,EWC%IIO_MAX

               IF (M2%CELL(M2%CELL_INDEX(IIO,JJO,KKO))%SOLID) CYCLE
               IF (M2%FCVAR(IIO,JJO,KKO,CC_FGSC,ABS(IOR))==CC_SOLID) CYCLE

               ICFO = M2%FCVAR(IIO,JJO,KKO,CC_IDCF,ABS(IOR))
               IF(ICFO>0) THEN
                  CFO => M2%CUT_FACE(ICFO)
                  DO JCFO=1,CFO%NFACE
                     IROW = OM%CFHALO_ROW0(ICFO)+JCFO-1
                     DA_OTHER      = DA_OTHER  + CFO%AREA(JCFO)
                     VEL_OTHER     = VEL_OTHER + &
                                     (PRFCT*OM%CFHALO_VELS(IROW)+(1._EB-PRFCT)*OM%CFHALO_VEL(IROW))*CFO%AREA(JCFO)
                     VEL_LNK_OTHER = VEL_LNK_OTHER + OM%CFHALO_VEL_LNK(IROW)*CFO%AREA(JCFO)
                     IF (EWC%AREA_RATIO>0.9_EB) THEN ! Flux match OMESH cut-face vel.
                        IF(ICF>0) THEN
                           IF(APPLY_TO_ESTIMATED_VARIABLES) THEN
                              OM%CFHALO_VELS(IROW) = 0.5_EB*(OM%CFHALO_VELS(IROW)+CC_FV_CUTFACE_MOM(NM,ICF,JCF,CC_FV_MOM_VELS))
                           ELSE
                              OM%CFHALO_VEL(IROW)  = 0.5_EB*(OM%CFHALO_VEL(IROW)+CC_FV_CUTFACE_MOM(NM,ICF,JCF,CC_FV_MOM_VEL))
                           ENDIF
                           OM%CFHALO_VEL_LNK(IROW) = 0.5_EB*(OM%CFHALO_VEL_LNK(IROW)+FV%FACE%VEL_LNK(CUT_FACE(ICF)%FC(JCF)))
                        ELSE
                           IF(APPLY_TO_ESTIMATED_VARIABLES) THEN
                              OM%CFHALO_VELS(IROW) = 0.5_EB*(OM%CFHALO_VELS(IROW)+WW(II,JJ,0))
                           ELSE
                              OM%CFHALO_VEL(IROW)  = 0.5_EB*(OM%CFHALO_VEL(IROW)+WW(II,JJ,0))
                           ENDIF
                           OM%CFHALO_VEL_LNK(IROW) = 0.5_EB*(OM%CFHALO_VEL_LNK(IROW)+EWC_UN_LNK(IW))
                        ENDIF
                     ENDIF
                  ENDDO
               ELSE
                  DA_OTHER      = DA_OTHER  + M2%DX(IIO)*M2%DY(JJO)
                  VEL_OTHER     = VEL_OTHER + OM_WW(IIO,JJO,KKO)*M2%DX(IIO)*M2%DY(JJO)
                  VEL_LNK_OTHER = VEL_LNK_OTHER + OM%W_LNK(IIO,JJO,KKO)*M2%DX(IIO)*M2%DY(JJO)
                  IF (EWC%AREA_RATIO>0.9_EB) THEN
                     IF(ICF>0) THEN
                        OM_WW(IIO,JJO,KKO)    = 0.5_EB*(OM_WW(IIO,JJO,KKO)+ &
                        PRFCT*CC_FV_CUTFACE_MOM(NM,ICF,JCF,CC_FV_MOM_VELS)+ &
                        (1._EB-PRFCT)*CC_FV_CUTFACE_MOM(NM,ICF,JCF,CC_FV_MOM_VEL))
                        OM%W_LNK(IIO,JJO,KKO) = 0.5_EB*(OM%W_LNK(IIO,JJO,KKO)+FV%FACE%VEL_LNK(CUT_FACE(ICF)%FC(JCF)))
                     ELSE
                        OM_WW(IIO,JJO,KKO)    = 0.5_EB*(OM_WW(IIO,JJO,KKO)+WW(II,JJ,0))
                        OM%W_LNK(IIO,JJO,KKO) = 0.5_EB*(OM%W_LNK(IIO,JJO,KKO)+EWC_UN_LNK(IW))
                     ENDIF
                  ENDIF
               ENDIF
            ENDDO
         ENDDO
      ENDDO
      IF(ICF<1) THEN
         UVW_SAVE(IW)   = WW(II,JJ,0)
         WW(II,JJ,0)    = 0.5_EB*(WW(II,JJ,0) + VEL_OTHER/DA_OTHER)
         EWC_UN_LNK(IW) = 0.5_EB*(EWC_UN_LNK(IW) + VEL_LNK_OTHER/DA_OTHER)
      ENDIF

   CASE(-KAXIS)

      IF (APPLY_TO_ESTIMATED_VARIABLES) THEN; OM_WW => OM%WS; ELSE; OM_WW => OM%W; ENDIF
      ICF = FCVAR(II,JJ,KBAR,CC_IDCF,ABS(IOR)); JCF = 1
      DO KKO=EWC%KKO_MIN,EWC%KKO_MAX
         DO JJO=EWC%JJO_MIN,EWC%JJO_MAX
            DO IIO=EWC%IIO_MIN,EWC%IIO_MAX

               IF (M2%CELL(M2%CELL_INDEX(IIO,JJO,KKO))%SOLID) CYCLE
               IF (M2%FCVAR(IIO,JJO,KKO-1,CC_FGSC,ABS(IOR))==CC_SOLID) CYCLE

               ICFO = M2%FCVAR(IIO,JJO,KKO-1,CC_IDCF,ABS(IOR))
               IF(ICFO>0) THEN
                  CFO => M2%CUT_FACE(ICFO)
                  DO JCFO=1,CFO%NFACE
                     IROW = OM%CFHALO_ROW0(ICFO)+JCFO-1
                     DA_OTHER      = DA_OTHER  + CFO%AREA(JCFO)
                     VEL_OTHER     = VEL_OTHER + &
                                     (PRFCT*OM%CFHALO_VELS(IROW)+(1._EB-PRFCT)*OM%CFHALO_VEL(IROW))*CFO%AREA(JCFO)
                     VEL_LNK_OTHER = VEL_LNK_OTHER + OM%CFHALO_VEL_LNK(IROW)*CFO%AREA(JCFO)
                     IF (EWC%AREA_RATIO>0.9_EB) THEN ! Flux match OMESH cut-face vel.
                        IF(ICF>0) THEN
                           IF(APPLY_TO_ESTIMATED_VARIABLES) THEN
                              OM%CFHALO_VELS(IROW) = 0.5_EB*(OM%CFHALO_VELS(IROW)+CC_FV_CUTFACE_MOM(NM,ICF,JCF,CC_FV_MOM_VELS))
                           ELSE
                              OM%CFHALO_VEL(IROW)  = 0.5_EB*(OM%CFHALO_VEL(IROW)+CC_FV_CUTFACE_MOM(NM,ICF,JCF,CC_FV_MOM_VEL))
                           ENDIF
                           OM%CFHALO_VEL_LNK(IROW) = 0.5_EB*(OM%CFHALO_VEL_LNK(IROW)+FV%FACE%VEL_LNK(CUT_FACE(ICF)%FC(JCF)))
                        ELSE
                           IF(APPLY_TO_ESTIMATED_VARIABLES) THEN
                              OM%CFHALO_VELS(IROW) = 0.5_EB*(OM%CFHALO_VELS(IROW)+WW(II,JJ,KBAR))
                           ELSE
                              OM%CFHALO_VEL(IROW)  = 0.5_EB*(OM%CFHALO_VEL(IROW)+WW(II,JJ,KBAR))
                           ENDIF
                           OM%CFHALO_VEL_LNK(IROW) = 0.5_EB*(OM%CFHALO_VEL_LNK(IROW)+EWC_UN_LNK(IW))
                        ENDIF
                     ENDIF
                  ENDDO
               ELSE
                  DA_OTHER      = DA_OTHER  + M2%DX(IIO)*M2%DY(JJO)
                  VEL_OTHER     = VEL_OTHER + OM_WW(IIO,JJO,KKO-1)*M2%DX(IIO)*M2%DY(JJO)
                  VEL_LNK_OTHER = VEL_LNK_OTHER + OM%W_LNK(IIO,JJO,KKO-1)*M2%DX(IIO)*M2%DY(JJO)
                  IF (EWC%AREA_RATIO>0.9_EB) THEN
                     IF(ICF>0) THEN
                        OM_WW(IIO,JJO,KKO-1)    = 0.5_EB*(OM_WW(IIO,JJO,KKO-1)+ &
                        PRFCT*CC_FV_CUTFACE_MOM(NM,ICF,JCF,CC_FV_MOM_VELS)+ &
                        (1._EB-PRFCT)*CC_FV_CUTFACE_MOM(NM,ICF,JCF,CC_FV_MOM_VEL))
                        OM%W_LNK(IIO,JJO,KKO-1) = 0.5_EB*(OM%W_LNK(IIO,JJO,KKO-1)+FV%FACE%VEL_LNK(CUT_FACE(ICF)%FC(JCF)))
                     ELSE
                        OM_WW(IIO,JJO,KKO-1)    = 0.5_EB*(OM_WW(IIO,JJO,KKO-1)+WW(II,JJ,KBAR))
                        OM%W_LNK(IIO,JJO,KKO-1) = 0.5_EB*(OM%W_LNK(IIO,JJO,KKO-1)+EWC_UN_LNK(IW))
                     ENDIF
                  ENDIF
               ENDIF
            ENDDO
         ENDDO
      ENDDO
      IF(ICF<1) THEN
         UVW_SAVE(IW)   = WW(II,JJ,KBAR)
         WW(II,JJ,KBAR) = 0.5_EB*(WW(II,JJ,KBAR) + VEL_OTHER/DA_OTHER)
         EWC_UN_LNK(IW) = 0.5_EB*(EWC_UN_LNK(IW) + VEL_LNK_OTHER/DA_OTHER)
      ENDIF

   END SELECT

   ! IF EWC has a cut-face match the cut-face velocity:
   ! VEL_OTHER is averaged, so assumes single cut-face per Cartesian face, single pressure zone per Cut-Cell.
   IF(ICF>0) THEN
      CF => CUT_FACE(ICF)
      IF (APPLY_TO_ESTIMATED_VARIABLES) THEN
         DO JCF=1,CF%NFACE
            IF_=MESHES(NM)%CUT_FACE(ICF)%FC(JCF)
            FV%FACE%VEL_SAVE(IF_)=FV%FACE%VELS(IF_)
            FV%FACE%VELS(IF_)=0.5_EB*(FV%FACE%VELS(IF_)+VEL_OTHER/DA_OTHER)
         ENDDO
      ELSE
         DO JCF=1,CF%NFACE
            IF_=MESHES(NM)%CUT_FACE(ICF)%FC(JCF)
            FV%FACE%VEL_SAVE(IF_)=FV%FACE%VEL(IF_)
            FV%FACE%VEL(IF_)=0.5_EB*(FV%FACE%VEL(IF_)+VEL_OTHER/DA_OTHER)
         ENDDO
      ENDIF
      DO JCF=1,CF%NFACE
         IF_=CF%FC(JCF)
         FV%FACE%VEL_LNK(IF_)=0.5_EB*(FV%FACE%VEL_LNK(IF_)+VEL_LNK_OTHER/DA_OTHER)
      ENDDO
   ENDIF

   IF (DO_U_GHOST) THEN
      ! Save velocity components at the ghost cell midpoint

      U_GHOST(IW) = 0._EB
      V_GHOST(IW) = 0._EB
      W_GHOST(IW) = 0._EB

      IF (APPLY_TO_ESTIMATED_VARIABLES) THEN; OM_UU => OM%US; ELSE; OM_UU => OM%U; ENDIF
      IF (APPLY_TO_ESTIMATED_VARIABLES) THEN; OM_VV => OM%VS; ELSE; OM_VV => OM%V; ENDIF
      IF (APPLY_TO_ESTIMATED_VARIABLES) THEN; OM_WW => OM%WS; ELSE; OM_WW => OM%W; ENDIF

      DO KKO=EWC%KKO_MIN,EWC%KKO_MAX
         DO JJO=EWC%JJO_MIN,EWC%JJO_MAX
            DO IIO=EWC%IIO_MIN,EWC%IIO_MAX
               AU =1._EB; ICF=M2%FCVAR(IIO  ,JJO,KKO,CC_IDCF,IAXIS); IF(ICF>0) AU =M2%CUT_FACE(ICF)%ALPHA_CF
               AU1=1._EB; ICF=M2%FCVAR(IIO-1,JJO,KKO,CC_IDCF,IAXIS); IF(ICF>0) AU1=M2%CUT_FACE(ICF)%ALPHA_CF
               AV =1._EB; ICF=M2%FCVAR(IIO,JJO  ,KKO,CC_IDCF,JAXIS); IF(ICF>0) AV =M2%CUT_FACE(ICF)%ALPHA_CF
               AV1=1._EB; ICF=M2%FCVAR(IIO,JJO-1,KKO,CC_IDCF,JAXIS); IF(ICF>0) AV1=M2%CUT_FACE(ICF)%ALPHA_CF
               AW =1._EB; ICF=M2%FCVAR(IIO,JJO,KKO  ,CC_IDCF,KAXIS); IF(ICF>0) AW =M2%CUT_FACE(ICF)%ALPHA_CF
               AW1=1._EB; ICF=M2%FCVAR(IIO,JJO,KKO-1,CC_IDCF,KAXIS); IF(ICF>0) AW1=M2%CUT_FACE(ICF)%ALPHA_CF
               U_GHOST(IW) = U_GHOST(IW) + (OM_UU(IIO,JJO,KKO)*AU+OM_UU(IIO-1,JJO,KKO)*AU1)/(AU+AU1)
               V_GHOST(IW) = V_GHOST(IW) + (OM_VV(IIO,JJO,KKO)*AV+OM_VV(IIO,JJO-1,KKO)*AV1)/(AV+AV1)
               W_GHOST(IW) = W_GHOST(IW) + (OM_WW(IIO,JJO,KKO)*AW+OM_WW(IIO,JJO,KKO-1)*AW1)/(AW+AW1)
            ENDDO
         ENDDO
      ENDDO

      NOM_CELLS = REAL((EWC%IIO_MAX-EWC%IIO_MIN+1)*(EWC%JJO_MAX-EWC%JJO_MIN+1)*(EWC%KKO_MAX-EWC%KKO_MIN+1),EB)
      U_GHOST(IW) = U_GHOST(IW)/NOM_CELLS
      V_GHOST(IW) = V_GHOST(IW)/NOM_CELLS
      W_GHOST(IW) = W_GHOST(IW)/NOM_CELLS
   ENDIF

ENDDO EXTERNAL_WALL_LOOP

T_USED(4) = T_USED(4) + CURRENT_TIME() - T_NOW

END SUBROUTINE CC_MATCH_VELOCITY


! ----------------------------- CC_COMPUTE_VISCOSITY -------------------------

SUBROUTINE CC_COMPUTE_VISCOSITY(DT,NM)

USE TURBULENCE, ONLY: WALE_VISCOSITY

REAL(EB), INTENT(IN):: DT
INTEGER, INTENT(IN) :: NM

! Local Variables:
INTEGER :: I,J,K
REAL(EB), POINTER, DIMENSION(:,:,:) :: RHOP,UU,VV,WW
REAL(EB), POINTER, DIMENSION(:,:,:,:) :: ZZP
REAL(EB) :: NU_EDDY,DELTA,A_IJ(3,3),DUDX,DUDY,DUDZ,DVDX,DVDY,DVDZ,DWDX,DWDY,DWDZ

REAL(EB) :: TNOW

! Dummy assignments:
TNOW = DT
I    = NM

TNOW = CURRENT_TIME()

IF (PREDICTOR) THEN
   RHOP => RHO
   UU   => U
   VV   => V
   WW   => W
   ZZP  => ZZ
ELSE
   RHOP => RHOS
   UU   => US
   VV   => VS
   WW   => WS
   ZZP  => ZZS
ENDIF

! No need to compute WALE model turbulent viscosity on cut-cell region.
LES_IF : IF (SIM_MODE/=DNS_MODE) THEN

   ! WALE model on cells belonging to cut-cell region:
   DO K=1,KBAR
      DO J=1,JBAR
         DO I=1,IBAR
             IF (CELL(CELL_INDEX(I,J,K))%SOLID) CYCLE
             IF (CCVAR(I,J,K,CC_CGSC)==CC_SOLID) THEN; MU(I,J,K) = MU_DNS(I,J,K); CYCLE; ENDIF
             IF (CCVAR(I,J,K,CC_IDCF)<1) CYCLE ! Cycle everything except cut-cells with boundary CFACEs.

             DELTA = LES_FILTER_WIDTH(I,J,K)
             ! compute velocity gradient tensor
             DUDX = RDX(I)*(UU(I,J,K)-UU(I-1,J,K))
             DVDY = RDY(J)*(VV(I,J,K)-VV(I,J-1,K))
             DWDZ = RDZ(K)*(WW(I,J,K)-WW(I,J,K-1))
             DUDY = 0.25_EB*RDY(J)*(UU(I,J+1,K)-UU(I,J-1,K)+UU(I-1,J+1,K)-UU(I-1,J-1,K))
             DUDZ = 0.25_EB*RDZ(K)*(UU(I,J,K+1)-UU(I,J,K-1)+UU(I-1,J,K+1)-UU(I-1,J,K-1))
             DVDX = 0.25_EB*RDX(I)*(VV(I+1,J,K)-VV(I-1,J,K)+VV(I+1,J-1,K)-VV(I-1,J-1,K))
             DVDZ = 0.25_EB*RDZ(K)*(VV(I,J,K+1)-VV(I,J,K-1)+VV(I,J-1,K+1)-VV(I,J-1,K-1))
             DWDX = 0.25_EB*RDX(I)*(WW(I+1,J,K)-WW(I-1,J,K)+WW(I+1,J,K-1)-WW(I-1,J,K-1))
             DWDY = 0.25_EB*RDY(J)*(WW(I,J+1,K)-WW(I,J-1,K)+WW(I,J+1,K-1)-WW(I,J-1,K-1))
             A_IJ(1,1)=DUDX; A_IJ(1,2)=DUDY; A_IJ(1,3)=DUDZ
             A_IJ(2,1)=DVDX; A_IJ(2,2)=DVDY; A_IJ(2,3)=DVDZ
             A_IJ(3,1)=DWDX; A_IJ(3,2)=DWDY; A_IJ(3,3)=DWDZ

             CALL WALE_VISCOSITY(NU_EDDY,A_IJ,DELTA)

             MU(I,J,K) = MU_DNS(I,J,K) + RHOP(I,J,K)*NU_EDDY

         ENDDO
      ENDDO
   ENDDO

ENDIF LES_IF

T_USED(14) = T_USED(14) + CURRENT_TIME() - TNOW
IF (TIME_CC_IBM) &
   T_CC_USED(CC_COMPUTE_VISCOSITY_TIME_INDEX) = T_CC_USED(CC_COMPUTE_VISCOSITY_TIME_INDEX) + CURRENT_TIME() - TNOW


RETURN
END SUBROUTINE CC_COMPUTE_VISCOSITY


! -------------------------------- ADD_Q_DOT_CUTCELLS ------------------------------

SUBROUTINE ADD_Q_DOT_CUTCELLS(NM,QCOMB,QRAD,QPRES,SP_ENTH)

! This routine assumes POINT_TO_MESH(NM) has already been called for mesh NM.

USE PHYSICAL_FUNCTIONS, ONLY : GET_SENSIBLE_ENTHALPY

INTEGER, INTENT(IN) :: NM
REAL(EB), INTENT(INOUT) :: QCOMB,QRAD,QPRES,SP_ENTH

! Local Variables:
INTEGER :: ICC,JCC,I,J,K,IG
REAL(EB):: VC,ZZ_GET(1:N_TRACKED_SPECIES),H_S
TYPE(CC_FV_TYPE), POINTER :: FV

FV=>MESHES(NM)%FV

DO ICC=1,MESHES(NM)%N_CUTCELL_MESH
   I = CUT_CELL(ICC)%IJK(IAXIS)
   J = CUT_CELL(ICC)%IJK(JAXIS)
   K = CUT_CELL(ICC)%IJK(KAXIS)
   VC = DX(I)*DY(J)*DZ(K)
   QPRES = QPRES + 0.5_EB*(D_PBAR_DT_S(PRESSURE_ZONE(I,J,K))+D_PBAR_DT(PRESSURE_ZONE(I,J,K)))*VC
   DO JCC=1,CUT_CELL(ICC)%NCELL
      IG = CUT_CELL(ICC)%IG(JCC)
      ! A piece with no IG row has no solver row in either numbering and contributes to no budget.
      IF (IG>=1) THEN
         QCOMB=QCOMB+FV%CV%Q(IG)*CUT_CELL(ICC)%VOLUME(JCC)
         QRAD=QRAD+FV%CV%QR(IG)*CUT_CELL(ICC)%VOLUME(JCC)
         CALL GET_CUTCELL_ZZV(NM,ICC,JCC,1._EB,ZZ_GET)
         CALL GET_SENSIBLE_ENTHALPY(ZZ_GET,H_S,GET_CUTCELL_TMP(NM,ICC,JCC))
         SP_ENTH = SP_ENTH + GET_CUTCELL_RHOP(NM,ICC,JCC,1._EB)*H_S*CUT_CELL(ICC)%VOLUME(JCC)
      ENDIF
   ENDDO
ENDDO

RETURN
END SUBROUTINE ADD_Q_DOT_CUTCELLS


! -------------------------- CFACE_PREDICT_NORMAL_VELOCITY -------------------------

SUBROUTINE CFACE_PREDICT_NORMAL_VELOCITY(T,DT)


USE MATH_FUNCTIONS, ONLY : EVALUATE_RAMP

REAL(EB), INTENT(IN) :: T, DT

! Local variables:
INTEGER :: ICF
TYPE(SURFACE_TYPE), POINTER :: SF
REAL(EB), POINTER, DIMENSION(:,:) :: PBAR_P
REAL(EB) :: TSI, TIME_RAMP_FACTOR, RDT

RDT = 1._EB/DT

SELECT CASE(PREDICTOR)
   CASE(.TRUE.)
      PBAR_P => PBAR_S
   CASE(.FALSE.)
      PBAR_P => PBAR
END SELECT

PREDICT_NORMALS: IF (PREDICTOR) THEN

   ! Run computation for External and Internal CFACE cells:
   CFACE_LOOP: DO ICF=1,N_EXTERNAL_CFACE_CELLS+N_INTWALL_CFACE_CELLS+N_INTERNAL_CFACE_CELLS

      CFA => CFACE(ICF)
      B1  => BOUNDARY_PROP1(CFA%B1_INDEX)

      WALL_CELL_TYPE: SELECT CASE (CFA%BOUNDARY_TYPE)

         CASE (NULL_BOUNDARY)

            B1%U_NORMAL_S = 0._EB

         CASE (SOLID_BOUNDARY)

            SF => SURFACE(CFA%SURF_INDEX)

            IF (SF%SPECIES_BC_INDEX==SPECIFIED_MASS_FLUX .OR. &
                B1%NODE_INDEX > 0                 .OR. &
                ANY(SF%LEAK_PATH>0))                          &
                CYCLE CFACE_LOOP

            IF (ABS(B1%T_IGN-T_BEGIN) < SPACING(B1%T_IGN) .AND. SF%RAMP(TIME_VELO)%INDEX>=1) THEN
               TSI = T + DT
            ELSE
               TSI = T + DT - B1%T_IGN
               IF (TSI<0._EB) THEN
                  B1%U_NORMAL_S = 0._EB
                  CYCLE CFACE_LOOP
               ENDIF
            ENDIF
            TIME_RAMP_FACTOR = EVALUATE_RAMP(TSI,SF%RAMP(TIME_VELO)%INDEX,TAU=SF%RAMP(TIME_VELO)%TAU)
            B1%U_NORMAL_S = TIME_RAMP_FACTOR*B1%U_NORMAL_0

            ! Special Cases
            ! NEUMANN_IF: IF (SF%SPECIFIED_NORMAL_GRADIENT) THEN
            ! TO DO, following PREDICT_NORMAL_VELOCITY.

            IF (ABS(SURFACE(CFA%SURF_INDEX)%MASS_FLUX_TOTAL)>=TWENTY_EPSILON_EB) B1%U_NORMAL_S = &
                                                                              B1%U_NORMAL_S*RHOA/B1%RHO_F

            ! VENT_IF: IF (WC%VENT_INDEX>0) THEN
            ! TO DO, following PREDICT_NORMAL_VELOCITY.

      END SELECT WALL_CELL_TYPE

   ENDDO CFACE_LOOP

   DO ICF=1,N_EXTERNAL_CFACE_CELLS+N_INTWALL_CFACE_CELLS+N_INTERNAL_CFACE_CELLS
      CFA => CFACE(ICF)
      B1  => BOUNDARY_PROP1(CFA%B1_INDEX)
      CFA%DUNDT = RDT*(B1%U_NORMAL_S-B1%U_NORMAL)
   ENDDO

ELSE PREDICT_NORMALS

   ! In the CORRECTOR step, the normal component of velocity, U_NORMAL, is the same as the predicted value, U_NORMAL_S.
   ! However, for species mass fluxes and HVAC, U_NORMAL is computed elsewhere (wall.f90).

   CFACE_LOOPC: DO ICF=1,N_EXTERNAL_CFACE_CELLS+N_INTWALL_CFACE_CELLS+N_INTERNAL_CFACE_CELLS
      CFA => CFACE(ICF)
      B1  => BOUNDARY_PROP1(CFA%B1_INDEX)
      IF (CFA%BOUNDARY_TYPE==SOLID_BOUNDARY) THEN
         SF => SURFACE(CFA%SURF_INDEX)
         IF (SF%SPECIES_BC_INDEX==SPECIFIED_MASS_FLUX .OR. &
             B1%NODE_INDEX > 0                 .OR. &
             ANY(SF%LEAK_PATH>0) ) CYCLE
      ENDIF
      B1%U_NORMAL = B1%U_NORMAL_S
   ENDDO CFACE_LOOPC

   DO ICF=1,N_EXTERNAL_CFACE_CELLS+N_INTWALL_CFACE_CELLS+N_INTERNAL_CFACE_CELLS
      CFA => CFACE(ICF)
      B1 => BOUNDARY_PROP1(CFA%B1_INDEX)
      CFA%DUNDT = CFA%DUNDT + 2._EB*RDT*(B1%U_NORMAL-B1%U_NORMAL_S)
   ENDDO

ENDIF PREDICT_NORMALS

RETURN

END SUBROUTINE CFACE_PREDICT_NORMAL_VELOCITY


! ---------------------------- ROTATED_CUBE_VELOCITY_FLUX --------------------------

SUBROUTINE ROTATED_CUBE_VELOCITY_FLUX(NM,TLEVEL)

INTEGER, INTENT(IN) :: NM
REAL(EB), INTENT(IN):: TLEVEL

! Local Variables:
REAL(EB) :: XGLOB(2,1), XLOC(2,1), FGLOB(2,1), FLOC(2,1), X_I, Y_J, NU
INTEGER  :: I,J,K
REAL(EB), POINTER, DIMENSION(:,:,:) :: RHOP
REAL(EB) :: SIN_T, COS_T, COS_KX, SIN_KX, COS_KY, SIN_KY

CALL POINT_TO_MESH(NM)

IF (PREDICTOR) THEN
   RHOP => RHO
ELSE
   RHOP => RHOS
ENDIF

ROTANG = 0._EB
IF(PERIODIC_TEST==21) THEN
   ROTANG = 0._EB ! No rotation.
ELSEIF(PERIODIC_TEST==22) THEN
   ROTANG = ATAN(1._EB/2._EB) ! ~27 Degrees.
ELSEIF(PERIODIC_TEST==23) THEN
   ROTANG = ATAN(1._EB)       ! 45 degrees.
ELSE
   RETURN
ENDIF
ROTMAT(1,1) = COS(ROTANG); ROTMAT(1,2) = -SIN(ROTANG);
ROTMAT(2,1) = SIN(ROTANG); ROTMAT(2,2) =  COS(ROTANG);
TROTMAT = TRANSPOSE(ROTMAT)

COS_T = COS(TLEVEL)
SIN_T = SIN(TLEVEL)

! X Force:
DO K=1,KBAR
   DO J=1,JBAR
      DO I=0,IBAR
         IF (CC_IBM) THEN
            IF (FCVAR(I,J,K,CC_FGSC,IAXIS) == CC_SOLID) CYCLE    ! Stress method.
         ENDIF
         ! Kinematic Viscosity:
         NU = 0.5_EB*(MU(I,J,K)/RHOP(I,J,K) + MU(I+1,J,K)/RHOP(I+1,J,K))

         ! Global position:
         XGLOB(1:2,1) = (/ X(I), ZC(K) /)

         ! Local position:
         XGLOB(1:2,1) = XGLOB(1:2,1) - DISPL
         XLOC         = MATMUL(TROTMAT, XGLOB )
         XLOC( 1:2,1) = XLOC( 1:2,1) - DISPXY(1:2,1)

         X_I = XLOC(1,1); Y_J = XLOC(2,1)

         COS_KX = COS(NWAVE*X_I)
         SIN_KX = SIN(NWAVE*X_I)

         COS_KY = COS(NWAVE*Y_J)
         SIN_KY = SIN(NWAVE*Y_J)

         FLOC(1,1)=2._EB*COS_KY*SIN_KX**2._EB*SIN_KY*COS_T - &
         4._EB*NWAVE*SIN_KY*SIN_T*(COS_KX*SIN_KX**3._EB*SIN_KY*SIN_T + &
         NWAVE*NU*COS_KX**2._EB*COS_KY - 3._EB*NWAVE*NU*COS_KY*SIN_KX**2._EB) + &
         NWAVE*COS_KX*SIN_KX*SIN_T*(2._EB*COS_KY**2._EB + 1._EB);


         FLOC(2,1)= NWAVE*COS_KY*SIN_KY*SIN_T*(2._EB*COS_KX**2._EB + 1._EB) - &
         2._EB*COS_KX*SIN_KX*SIN_KY**2._EB*COS_T - &
         4._EB*NWAVE*SIN_KX*SIN_T*(COS_KY*SIN_KX*SIN_KY**3._EB*SIN_T - &
         NWAVE*NU*COS_KX*COS_KY**2._EB + 3._EB*NWAVE*NU*COS_KX*SIN_KY**2._EB);

         FGLOB        = MATMUL(ROTMAT, FLOC )

         FVX(I,J,K)   = FVX(I,J,K) + 0.5_EB*(RHOP(I,J,K)+RHOP(I+1,J,K))*FGLOB(IAXIS,1)

      ENDDO
   ENDDO
ENDDO


! Z Force:
DO K=0,KBAR
   DO J=1,JBAR
      DO I=1,IBAR
         IF (CC_IBM) THEN
            IF (FCVAR(I,J,K,CC_FGSC,KAXIS) == CC_SOLID) CYCLE    ! Stress method.
         ENDIF
         ! Kinematic Viscosity:
         NU = 0.5_EB*(MU(I,J,K)/RHOP(I,J,K) + MU(I,J,K+1)/RHOP(I,J,K+1))

         ! Global position:
         XGLOB(1:2,1) = (/ XC(I), Z(K) /)

         ! Local position:
         XGLOB(1:2,1) = XGLOB(1:2,1) - DISPL
         XLOC         = MATMUL(TROTMAT, XGLOB )
         XLOC( 1:2,1) = XLOC( 1:2,1) - DISPXY(1:2,1)

         X_I = XLOC(1,1); Y_J = XLOC(2,1)

         COS_KX = COS(NWAVE*X_I)
         SIN_KX = SIN(NWAVE*X_I)

         COS_KY = COS(NWAVE*Y_J)
         SIN_KY = SIN(NWAVE*Y_J)

         FLOC(1,1)=2._EB*COS_KY*SIN_KX**2._EB*SIN_KY*COS_T - &
         4._EB*NWAVE*SIN_KY*SIN_T*(COS_KX*SIN_KX**3._EB*SIN_KY*SIN_T + &
         NWAVE*NU*COS_KX**2._EB*COS_KY - 3._EB*NWAVE*NU*COS_KY*SIN_KX**2._EB) + &
         NWAVE*COS_KX*SIN_KX*SIN_T*(2._EB*COS_KY**2._EB + 1._EB);


         FLOC(2,1)= NWAVE*COS_KY*SIN_KY*SIN_T*(2._EB*COS_KX**2._EB + 1._EB) - &
         2._EB*COS_KX*SIN_KX*SIN_KY**2._EB*COS_T - &
         4._EB*NWAVE*SIN_KX*SIN_T*(COS_KY*SIN_KX*SIN_KY**3._EB*SIN_T - &
         NWAVE*NU*COS_KX*COS_KY**2._EB + 3._EB*NWAVE*NU*COS_KX*SIN_KY**2._EB);

         FGLOB        = MATMUL(ROTMAT, FLOC )

         FVZ(I,J,K)   = FVZ(I,J,K) + 0.5_EB*(RHOP(I,J,K)+RHOP(I,J,K+1))*FGLOB(JAXIS,1)

      ENDDO
   ENDDO
ENDDO


RETURN
END SUBROUTINE ROTATED_CUBE_VELOCITY_FLUX

! ------------------------------ ROTATED_CUBE_ANN_SOLN ----------------------------

SUBROUTINE ROTATED_CUBE_ANN_SOLN(NM,TLEVEL)

INTEGER, INTENT(IN) :: NM
REAL(EB), INTENT(IN):: TLEVEL

! Local Variables:
REAL(EB) :: XGLOB(2,1), XLOC(2,1), UGLOB(2,1), ULOC(2,1), VEL_CF
INTEGER :: I,J,K,NFACE,X1AXIS,ICF,ICF2,IF_

ROTANG = 0._EB
IF(PERIODIC_TEST==21) THEN
   ROTANG = 0._EB ! No rotation.
ELSEIF(PERIODIC_TEST==22) THEN
   ROTANG = ATAN(1._EB/2._EB) ! ~27 Degrees.
ELSEIF(PERIODIC_TEST==23) THEN
   ROTANG = ATAN(1._EB)       ! 45 degrees.
ELSE
   RETURN
ENDIF
ROTMAT(1,1) = COS(ROTANG); ROTMAT(1,2) = -SIN(ROTANG);
ROTMAT(2,1) = SIN(ROTANG); ROTMAT(2,2) =  COS(ROTANG);
TROTMAT = TRANSPOSE(ROTMAT)

CALL POINT_TO_MESH(NM)


! X Velocities:
DO K=0,KBP1
   DO J=0,JBP1
      DO I=0,IBAR
         ! Global position:
         XGLOB(1:2,1) = (/ X(I), ZC(K) /)

         ! Local position:
         XGLOB(1:2,1) = XGLOB(1:2,1) - DISPL
         XLOC         = MATMUL(TROTMAT, XGLOB )
         XLOC( 1:2,1) = XLOC( 1:2,1) - DISPXY(1:2,1)

         ! Velocity field in local axes:
         ULOC(IAXIS,1)= -SIN(NWAVE*XLOC(IAXIS,1))**2._EB * SIN(2._EB*NWAVE*XLOC(JAXIS,1))
         ULOC(JAXIS,1)=  SIN(2._EB*NWAVE*XLOC(IAXIS,1))  * SIN(NWAVE*XLOC(JAXIS,1))**2._EB

         ! Velocity field in global axes:
         UGLOB        = MATMUL(ROTMAT,ULOC)
         U(I,J,K)     = SIN(TLEVEL) * UGLOB(IAXIS,1)

      ENDDO
   ENDDO
ENDDO

! Y Velocities:
V(:,:,:)=0._EB

! Z Velocities:
DO K=0,KBAR
   DO J=0,JBP1
      DO I=0,IBP1
         ! Global position:
         XGLOB(1:2,1) = (/ XC(I), Z(K) /)

         ! Local position:
         XGLOB(1:2,1) = XGLOB(1:2,1) - DISPL
         XLOC         = MATMUL(TROTMAT, XGLOB )
         XLOC( 1:2,1) = XLOC( 1:2,1) - DISPXY(1:2,1)

         ! Velocity field in local axes:
         ULOC(IAXIS,1)= -SIN(NWAVE*XLOC(IAXIS,1))**2._EB * SIN(2._EB*NWAVE*XLOC(JAXIS,1))
         ULOC(JAXIS,1)=  SIN(2._EB*NWAVE*XLOC(IAXIS,1))  * SIN(NWAVE*XLOC(JAXIS,1))**2._EB

         ! Velocity field in global axes:
         UGLOB        = MATMUL(ROTMAT,ULOC)
         W(I,J,K)     = SIN(TLEVEL) * UGLOB(JAXIS,1)

      ENDDO
   ENDDO
ENDDO

! Now GASPHASE cut-faces:
IF (CC_IBM) THEN
   CUTFACE_LOOP : DO ICF=1,MESHES(NM)%N_CUTFACE_MESH
      NFACE  = CUT_FACE(ICF)%NFACE
      IF (CUT_FACE(ICF)%STATUS == CC_GASPHASE) THEN
         I      = CUT_FACE(ICF)%IJK(IAXIS)
         J      = CUT_FACE(ICF)%IJK(JAXIS)
         K      = CUT_FACE(ICF)%IJK(KAXIS)
         X1AXIS = CUT_FACE(ICF)%IJK(KAXIS+1)
         DO ICF2=1,NFACE
            ! Global position:
            XGLOB(1:2,1) = (/ CUT_FACE(ICF)%XYZCEN(IAXIS,ICF2), CUT_FACE(ICF)%XYZCEN(KAXIS,ICF2) /)

            ! Local position:
            XGLOB(1:2,1) = XGLOB(1:2,1) - DISPL
            XLOC         = MATMUL(TROTMAT, XGLOB )
            XLOC( 1:2,1) = XLOC( 1:2,1) - DISPXY(1:2,1)

            ! Velocity field in local axes:
            ULOC(IAXIS,1)= -SIN(NWAVE*XLOC(IAXIS,1))**2._EB * SIN(2._EB*NWAVE*XLOC(JAXIS,1))
            ULOC(JAXIS,1)=  SIN(2._EB*NWAVE*XLOC(IAXIS,1))  * SIN(NWAVE*XLOC(JAXIS,1))**2._EB

            ! Velocity field in global axes:
            UGLOB        = MATMUL(ROTMAT,ULOC)
            SELECT CASE(X1AXIS)
            CASE(IAXIS)
               VEL_CF = SIN(TLEVEL) * UGLOB(IAXIS,1)
            CASE(JAXIS)
               VEL_CF = 0._EB
            CASE(KAXIS)
               VEL_CF = SIN(TLEVEL) * UGLOB(JAXIS,1)
            END SELECT

            IF_=MESHES(NM)%CUT_FACE(ICF)%FC(ICF2)
            MESHES(NM)%FV%FACE%VEL(IF_)=VEL_CF
            MESHES(NM)%FV%FACE%VELS(IF_)=VEL_CF

         ENDDO

      ELSE ! CC_INBOUNDARY

         VEL_CF = 0._EB
         DO ICF2=1,NFACE
            IF_=MESHES(NM)%CUT_FACE(ICF)%FC(ICF2)
            MESHES(NM)%FV%FACE%VEL(IF_)=VEL_CF
            MESHES(NM)%FV%FACE%VELS(IF_)=VEL_CF
         ENDDO

      ENDIF
   ENDDO CUTFACE_LOOP
ENDIF

! Fields for scalars:
! Regular cells:
DO K=0,KBP1
   DO J=0,JBP1
      DO I=0,IBP1
         IF (CELL(CELL_INDEX(I,J,K))%SOLID) CYCLE
         ! Global position:
         XGLOB(1:2,1) = (/ XC(I), ZC(K) /)

         ! Local position:
         XGLOB(1:2,1) = XGLOB(1:2,1) - DISPL
         XLOC         = MATMUL(TROTMAT, XGLOB )
         XLOC( 1:2,1) = XLOC( 1:2,1) - DISPXY(1:2,1)

         ZZ(I,J,K,N_SPEC_NEUMN) = AMP_Z/3._EB*SIN(TLEVEL)*(1._EB-COS(2._EB*NWAVE*(XLOC(IAXIS,1)-GAM))) * &
                                                          (1._EB-COS(2._EB*NWAVE*(XLOC(JAXIS,1)-GAM)))   &
                                                          -AMP_Z/3._EB*SIN(TLEVEL) + MEAN_Z
         ZZ(I,J,K,N_SPEC_BACKG) = 1._EB - ZZ(I,J,K,N_SPEC_NEUMN)

      ENDDO
   ENDDO
ENDDO


RETURN

END SUBROUTINE ROTATED_CUBE_ANN_SOLN

! ------------------------------ ROTATED_CUBE_RHS_ZZ -----------------------------------

SUBROUTINE ROTATED_CUBE_RHS_ZZ(TLEVEL,DT,NM)

USE MATH_FUNCTIONS, ONLY: INTERPOLATE1D_UNIFORM

REAL(EB), INTENT(IN) :: TLEVEL,DT
INTEGER, INTENT(IN)  :: NM

! Local Variables:
INTEGER :: I, J ,K
REAL(EB), POINTER, DIMENSION(:,:,:)   :: RHOP
REAL(EB), POINTER, DIMENSION(:,:,:,:) :: ZZP
REAL(EB) :: D_Z_N(0:I_MAX_TEMP),XLOC(2,1),XGLOB(2,1),Q_ZN,D_Z_TEMP,RHO_IJK,DTFC
REAL(EB) :: SIN_T, COS_T

ROTANG = 0._EB
IF(PERIODIC_TEST==21) THEN
   ROTANG = 0._EB ! No rotation.
ELSEIF(PERIODIC_TEST==22) THEN
   ROTANG = ATAN(1._EB/2._EB) ! ~27 Degrees.
ELSEIF(PERIODIC_TEST==23) THEN
   ROTANG = ATAN(1._EB)       ! 45 degrees.
ELSE
   RETURN
ENDIF
ROTMAT(1,1) = COS(ROTANG); ROTMAT(1,2) = -SIN(ROTANG);
ROTMAT(2,1) = SIN(ROTANG); ROTMAT(2,2) =  COS(ROTANG);
TROTMAT = TRANSPOSE(ROTMAT)

SIN_T    = SIN(TLEVEL)
COS_T    = COS(TLEVEL)

CALL POINT_TO_MESH(NM)

IF (PREDICTOR) THEN
   RHOP => RHO
   ZZP  => ZZS
   DTFC = 1._EB
ELSE
   RHOP => RHOS
   ZZP  => ZZ
   DTFC = 0.5_EB
ENDIF

D_Z_N=D_Z(:,N_SPEC_NEUMN)

! Add Q_Z on regular cells:
DO K=1,KBAR
   DO J=1,JBAR
      DO I=1,IBAR
         IF (CELL(CELL_INDEX(I,J,K))%SOLID) CYCLE
         IF (CC_IBM) THEN
            IF(CCVAR(I,J,K,CC_CGSC)/=CC_GASPHASE) CYCLE
            IF(CCVAR(I,J,K,CC_UNKZ)>0) CYCLE
         ENDIF
         ! Global position:
         XGLOB(1:2,1) = (/ XC(I), ZC(K) /)
         ! Local position:
         XGLOB(1:2,1) = XGLOB(1:2,1) - DISPL
         XLOC         = MATMUL(TROTMAT, XGLOB )
         XLOC( 1:2,1) = XLOC( 1:2,1) - DISPXY(1:2,1)
         RHO_IJK = RHOP(I,J,K)
         CALL INTERPOLATE1D_UNIFORM(LBOUND(D_Z_N,1),D_Z_N,TMP(I,J,K),D_Z_TEMP)
         CALL ROTATED_CUBE_NEUMN_FZ(SIN_T,COS_T,RHO_IJK,D_Z_TEMP,XLOC,Q_ZN)

         ! Update species:
         ZZP(I,J,K,N_SPEC_NEUMN) = ZZP(I,J,K,N_SPEC_NEUMN) + DTFC*DT*Q_ZN
         ZZP(I,J,K,N_SPEC_BACKG) = ZZP(I,J,K,N_SPEC_BACKG) - DTFC*DT*Q_ZN
      ENDDO
   ENDDO
ENDDO


RETURN
END SUBROUTINE ROTATED_CUBE_RHS_ZZ

! ------------------------- CC_ROTATED_CUBE_RHS_ZZ -------------------------------

SUBROUTINE CC_ROTATED_CUBE_RHS_ZZ(TLEVEL,N)

USE MATH_FUNCTIONS, ONLY: INTERPOLATE1D_UNIFORM

REAL(EB), INTENT(IN) :: TLEVEL
INTEGER, INTENT(IN)  :: N

! Local Variables:
INTEGER :: NM, I, J ,K, ICC, JCC
REAL(EB), POINTER, DIMENSION(:,:,:) :: RHOP
REAL(EB) :: PREDFCT,D_Z_N(0:I_MAX_TEMP),XLOC(2,1),XGLOB(2,1),Q_Z,D_Z_TEMP,RHO_IJK,FCT
REAL(EB) :: SIN_T, COS_T

ROTANG = 0._EB
IF(PERIODIC_TEST==21) THEN
   ROTANG = 0._EB ! No rotation.
ELSEIF(PERIODIC_TEST==22) THEN
   ROTANG = ATAN(1._EB/2._EB) ! ~27 Degrees.
ELSEIF(PERIODIC_TEST==23) THEN
   ROTANG = ATAN(1._EB)       ! 45 degrees.
ELSE
   RETURN
ENDIF
ROTMAT(1,1) = COS(ROTANG); ROTMAT(1,2) = -SIN(ROTANG);
ROTMAT(2,1) = SIN(ROTANG); ROTMAT(2,2) =  COS(ROTANG);
TROTMAT = TRANSPOSE(ROTMAT)

SIN_T    = SIN(TLEVEL)
COS_T    = COS(TLEVEL)

MESH_LOOP : DO NM=LOWER_MESH_INDEX,UPPER_MESH_INDEX

   CALL POINT_TO_MESH(NM)

   IF (PREDICTOR) THEN
      PREDFCT=1._EB
      RHOP => RHO
   ELSE
      PREDFCT=0._EB
      RHOP => RHOS
   ENDIF

   D_Z_N = D_Z(:,N)

   ! First add Q_Z on regular cells to source F_Z:
   IF (N==N_SPEC_BACKG) THEN
      FCT=-1._EB
   ELSEIF (N==N_SPEC_NEUMN) THEN
      FCT=1._EB
   ENDIF

   DO K=1,KBAR
      DO J=1,JBAR
         DO I=1,IBAR
            IF(CCVAR(I,J,K,CC_UNKZ) <= 0) CYCLE
            ! Global position:
            XGLOB(1:2,1) = (/ XC(I), ZC(K) /)
            ! Local position:
            XGLOB(1:2,1) = XGLOB(1:2,1) - DISPL
            XLOC         = MATMUL(TROTMAT, XGLOB )
            XLOC( 1:2,1) = XLOC( 1:2,1) - DISPXY(1:2,1)
            CALL INTERPOLATE1D_UNIFORM(LBOUND(D_Z_N,1),D_Z_N,TMP(I,J,K),D_Z_TEMP)
            RHO_IJK = RHOP(I,J,K)
            CALL ROTATED_CUBE_NEUMN_FZ(SIN_T,COS_T,RHO_IJK,D_Z_TEMP,XLOC,Q_Z)
               CALL ADD_FV_L2_SCALAR_RHS(CCVAR(I,J,K,CC_UNKZ),-FCT*Q_Z*DX(I)*DY(J)*DZ(K))
         ENDDO
      ENDDO
   ENDDO
   ! Then add Cut-cell contributions to F_Z:
   DO ICC=1,MESHES(NM)%N_CUTCELL_MESH
      DO JCC=1,CUT_CELL(ICC)%NCELL
         ! Global position:
         XGLOB(1:2,1) = (/ CUT_CELL(ICC)%XYZCEN(IAXIS,JCC), CUT_CELL(ICC)%XYZCEN(KAXIS,JCC) /)
         ! Local position:
         XGLOB(1:2,1) = XGLOB(1:2,1) - DISPL
         XLOC         = MATMUL(TROTMAT, XGLOB )
         XLOC( 1:2,1) = XLOC( 1:2,1) - DISPXY(1:2,1)
         CALL INTERPOLATE1D_UNIFORM(LBOUND(D_Z_N,1),D_Z_N,GET_CUTCELL_TMP(NM,ICC,JCC),D_Z_TEMP)
         RHO_IJK = GET_CUTCELL_RHOP(NM,ICC,JCC,PREDFCT)
         CALL ROTATED_CUBE_NEUMN_FZ(SIN_T,COS_T,RHO_IJK,D_Z_TEMP,XLOC,Q_Z)
            CALL ADD_FV_L2_SCALAR_RHS(CUT_CELL(ICC)%UNKZ(JCC),-FCT*Q_Z*CUT_CELL(ICC)%VOLUME(JCC))
      ENDDO
   ENDDO

ENDDO MESH_LOOP


RETURN
END SUBROUTINE CC_ROTATED_CUBE_RHS_ZZ

! ---------------------------------- ROTATED_CUBE_NEUMN_FZ ---------------------------------

SUBROUTINE ROTATED_CUBE_NEUMN_FZ(SIN_T,COS_T,RHO_IJK,D_Z_TEMP,XLOC,Q_Z)

REAL(EB), INTENT(IN) :: SIN_T,COS_T, RHO_IJK, D_Z_TEMP, XLOC(2,1)
REAL(EB), INTENT(OUT):: Q_Z

! Local Variables:
REAL(EB) :: COS_2KGX, COS_2KGZ, SIN_2KGX, SIN_2KGZ
REAL(EB) :: COS_KX, COS_KZ, SIN_KX, SIN_KZ
REAL(EB) :: SIN_2KX, SIN_2KZ

Q_Z=0._EB

COS_2KGX = COS(2._EB*NWAVE*(GAM - XLOC(IAXIS,1)))
COS_2KGZ = COS(2._EB*NWAVE*(GAM - XLOC(JAXIS,1)))

SIN_2KGX = SIN(2._EB*NWAVE*(GAM - XLOC(IAXIS,1)))
SIN_2KGZ = SIN(2._EB*NWAVE*(GAM - XLOC(JAXIS,1)))

COS_KX   = COS(NWAVE*XLOC(IAXIS,1))
COS_KZ   = COS(NWAVE*XLOC(JAXIS,1))
SIN_KX   = SIN(NWAVE*XLOC(IAXIS,1))
SIN_KZ   = SIN(NWAVE*XLOC(JAXIS,1))

SIN_2KX  = SIN(2._EB*NWAVE*XLOC(IAXIS,1))
SIN_2KZ  = SIN(2._EB*NWAVE*XLOC(JAXIS,1))

Q_Z = (4._EB*AMP_Z*D_Z_TEMP*NWAVE**2*RHO_IJK*COS_2KGX*SIN_T*(COS_2KGZ - 1._EB))/3._EB - &
       RHO_IJK*((AMP_Z*COS_T)/3._EB - (AMP_Z*COS_T*(COS_2KGX - 1._EB)*(COS_2KGZ - 1._EB))/3._EB) + &
      (4._EB*AMP_Z*D_Z_TEMP*NWAVE**2*RHO_IJK*COS_2KGZ*SIN_T*(COS_2KGX - 1._EB))/3._EB - &
       2._EB*NWAVE*RHO_IJK*COS_KX*SIN_KX*SIN_2KZ*SIN_T*(MEAN_Z - &
      (AMP_Z*SIN_T)/3._EB + (AMP_Z*SIN_T*(COS_2KGX - 1._EB)*(COS_2KGZ - 1._EB))/3._EB) + &
       2._EB*NWAVE*RHO_IJK*COS_KZ*SIN_2KX*SIN_KZ*SIN_T*(MEAN_Z - (AMP_Z*SIN_T)/3._EB + &
      (AMP_Z*SIN_T*(COS_2KGX - 1._EB)*(COS_2KGZ - 1._EB))/3._EB) + &
      (2._EB*AMP_Z*NWAVE*RHO_IJK*SIN_2KX*SIN_KZ**2*SIN_2KGZ*SIN_T**2*(COS_2KGX - 1._EB))/3._EB - &
      (2._EB*AMP_Z*NWAVE*RHO_IJK*SIN_KX**2*SIN_2KZ*SIN_2KGX*SIN_T**2*(COS_2KGZ - 1._EB))/3._EB


RETURN
END SUBROUTINE ROTATED_CUBE_NEUMN_FZ


! --------------------------------- GET_SHUNN3_QZ --------------------------------

SUBROUTINE GET_SHUNN3_QZ(T,N)

USE MANUFACTURED_SOLUTIONS, ONLY: UF_MMS,WF_MMS,VD2D_MMS_Z_SRC

REAL(EB),INTENT(IN) :: T
INTEGER, INTENT(IN) :: N

! Local Variables:
INTEGER I,J,K,NM,ICC,JCC
REAL(EB) :: FCT,XHAT,ZHAT,Q_Z

FCT=REAL(2*(1-N)+1,EB)

! Mesh Loop:
MESH_LOOP : DO NM=LOWER_MESH_INDEX,UPPER_MESH_INDEX

   CALL POINT_TO_MESH(NM)

   ! First add Q_Z on regular cells to source F_Z:
   DO K=1,KBAR
      DO J=1,JBAR
         DO I=1,IBAR
            IF(CCVAR(I,J,K,CC_UNKZ) <= 0) CYCLE
            ! divergence from EOS
            XHAT = XC(I) - UF_MMS*T
            ZHAT = ZC(K) - WF_MMS*T
            Q_Z = VD2D_MMS_Z_SRC(XHAT,ZHAT,T)
               CALL ADD_FV_L2_SCALAR_RHS(CCVAR(I,J,K,CC_UNKZ),FCT*Q_Z*DX(I)*DY(J)*DZ(K))
         ENDDO
      ENDDO
   ENDDO

   ! Then add Cut-cell contributions to F_Z:
   DO ICC=1,MESHES(NM)%N_CUTCELL_MESH
      DO JCC=1,CUT_CELL(ICC)%NCELL
         ! divergence from EOS
         XHAT = CUT_CELL(ICC)%XYZCEN(IAXIS,JCC) - UF_MMS*T
         ZHAT = CUT_CELL(ICC)%XYZCEN(KAXIS,JCC) - WF_MMS*T
         Q_Z = VD2D_MMS_Z_SRC(XHAT,ZHAT,T)
            CALL ADD_FV_L2_SCALAR_RHS(CUT_CELL(ICC)%UNKZ(JCC),FCT*Q_Z*CUT_CELL(ICC)%VOLUME(JCC))
      ENDDO
   ENDDO

ENDDO MESH_LOOP

RETURN
END SUBROUTINE GET_SHUNN3_QZ


! ---------------------------------- GET_MUDNS_CFACE --------------------------------

SUBROUTINE GET_MUDNS_CFACE(MU_WALL,IND1,IND2)

USE PHYSICAL_FUNCTIONS, ONLY : GET_VISCOSITY

REAL(EB), INTENT(OUT)::  MU_WALL
INTEGER, INTENT(IN) :: IND1,IND2

! Local Variables:
INTEGER :: ICC, IIG, JJG, KKG

! Underlying cell value:
ICC = CUT_FACE(IND1)%CELL_LIST(2,LOW_IND,IND2)
IIG = CUT_CELL(ICC)%IJK(1)
JJG = CUT_CELL(ICC)%IJK(2)
KKG = CUT_CELL(ICC)%IJK(3)
MU_WALL = MU_DNS(IIG,JJG,KKG)

RETURN
END SUBROUTINE GET_MUDNS_CFACE

! ---------------------------------- GET_UVWGAS_CFACE --------------------------------

SUBROUTINE GET_UVWGAS_CFACE(U_CELL,V_CELL,W_CELL,IND1,IND2,UP,VP,WP,PREDFCT,NM)

INTEGER, INTENT(IN) :: IND1,IND2,NM
REAL(EB),INTENT(OUT):: U_CELL,V_CELL,W_CELL
REAL(EB), POINTER, DIMENSION(:,:,:), INTENT(IN) :: UP,VP,WP
REAL(EB), INTENT(IN) :: PREDFCT

! Local Variables:
REAL(EB):: AF,VELN, U_AREA, V_AREA, W_AREA, NX, NY, NZ
INTEGER :: ICC, JCC, I, J, K, NFCELL, ICCF, IFACE, LOWHIGH, X1AXIS, ILH, IFC2, IFACE2, IBOD, IWSEL

U_CELL=0._EB; V_CELL=0._EB; W_CELL=0._EB
U_AREA= 0._EB; V_AREA= 0._EB; W_AREA= 0._EB
! Finally U velocity: Compute the Area average component on each direction:
ICC = CUT_FACE(IND1)%CELL_LIST(2,LOW_IND,IND2)
JCC = CUT_FACE(IND1)%CELL_LIST(3,LOW_IND,IND2)
I = CUT_CELL(ICC)%IJK(IAXIS)
J = CUT_CELL(ICC)%IJK(JAXIS)
K = CUT_CELL(ICC)%IJK(KAXIS)
NFCELL=CUT_CELL(ICC)%CCELEM(1,JCC)
DO ICCF=1,NFCELL
   IFACE=CUT_CELL(ICC)%CCELEM(ICCF+1,JCC)
   SELECT CASE(CUT_CELL(ICC)%FACE_LIST(1,IFACE))
   CASE(CC_FTYPE_RCGAS) ! REGULAR GASPHASE
      LOWHIGH = CUT_CELL(ICC)%FACE_LIST(2,IFACE)
      X1AXIS  = CUT_CELL(ICC)%FACE_LIST(3,IFACE)
      ILH     = LOWHIGH - 1
      SELECT CASE(X1AXIS)
      CASE(IAXIS)
         AF     = DY(J)*DZ(K)
         U_CELL = U_CELL + AF*UP(I-1+ILH,J,K); U_AREA = U_AREA + AF
      CASE(JAXIS)
         AF     = DX(I)*DZ(K)
         V_CELL = V_CELL + AF*VP(I,J-1+ILH,K); V_AREA = V_AREA + AF
      CASE(KAXIS)
         AF     = DX(I)*DY(J)
         W_CELL = W_CELL + AF*WP(I,J,K-1+ILH); W_AREA = W_AREA + AF
      END SELECT

   CASE(CC_FTYPE_CFGAS)
      LOWHIGH = CUT_CELL(ICC)%FACE_LIST(2,IFACE)
      IFC2    = CUT_CELL(ICC)%FACE_LIST(4,IFACE)
      IFACE2  = CUT_CELL(ICC)%FACE_LIST(5,IFACE)
      X1AXIS  = CUT_FACE(IFC2)%IJK(KAXIS+1)
      AF      = CUT_FACE(IFC2)%AREA(IFACE2)
      VELN = PREDFCT*CC_FV_CUTFACE_MOM(NM,IFC2,IFACE2,CC_FV_MOM_VEL) + &
             (1._EB-PREDFCT)*CC_FV_CUTFACE_MOM(NM,IFC2,IFACE2,CC_FV_MOM_VELS)

      SELECT CASE(X1AXIS)
      CASE(IAXIS); U_CELL= U_CELL + AF*VELN; U_AREA = U_AREA + AF
      CASE(JAXIS); V_CELL= V_CELL + AF*VELN; V_AREA = V_AREA + AF
      CASE(KAXIS); W_CELL= W_CELL + AF*VELN; W_AREA = W_AREA + AF
      END SELECT

   CASE(CC_FTYPE_CFINB)
      IFC2    = CUT_CELL(ICC)%FACE_LIST(4,IFACE)
      IFACE2  = CUT_CELL(ICC)%FACE_LIST(5,IFACE)

      AF      = CUT_FACE(IFC2)%AREA(IFACE2)
      ! Normal velocity defined into the body. We want velocity in direction of normal out of bod.
      VELN = -1._EB*(PREDFCT*CC_FV_CUTFACE_MOM(NM,IFC2,IFACE2,CC_FV_MOM_VEL) + &
                     (1._EB-PREDFCT)*CC_FV_CUTFACE_MOM(NM,IFC2,IFACE2,CC_FV_MOM_VELS))

      ! Fetch normal out of body on surface triangle this cface lives in:
      IBOD =CUT_FACE(IFC2)%BODTRI(1,IFACE2)
      IWSEL=CUT_FACE(IFC2)%BODTRI(2,IFACE2)
      NX = GEOMETRY(IBOD)%FACES_NORMAL(IAXIS,IWSEL)
      NY = GEOMETRY(IBOD)%FACES_NORMAL(JAXIS,IWSEL)
      NZ = GEOMETRY(IBOD)%FACES_NORMAL(KAXIS,IWSEL)
      U_CELL = U_CELL + AF*VELN*NX; U_AREA = U_AREA + AF*ABS(NX)
      V_CELL = V_CELL + AF*VELN*NY; V_AREA = V_AREA + AF*ABS(NY)
      W_CELL = W_CELL + AF*VELN*NZ; W_AREA = W_AREA + AF*ABS(NZ)
   END SELECT
ENDDO
! Normalize by area:
IF(U_AREA > TWENTY_EPSILON_EB) U_CELL = U_CELL / U_AREA
IF(V_AREA > TWENTY_EPSILON_EB) V_CELL = V_CELL / V_AREA
IF(W_AREA > TWENTY_EPSILON_EB) W_CELL = W_CELL / W_AREA

RETURN
END SUBROUTINE GET_UVWGAS_CFACE

! ----------------------------------- GET_CFACE_RAD_NVEC ---------------------------------
FUNCTION GET_CFACE_RAD_NVEC(CFA) RESULT(NVEC)

TYPE(CFACE_TYPE), INTENT(IN) :: CFA
REAL(EB) :: NVEC(IAXIS:KAXIS)
INTEGER :: IBOD,IWSEL

NVEC(IAXIS:KAXIS) = BOUNDARY_COORD(CFA%BC_INDEX)%NVEC(IAXIS:KAXIS)
IBOD = CUT_FACE(CFA%CUT_FACE_IND1)%BODTRI(1,CFA%CUT_FACE_IND2)
IWSEL= CUT_FACE(CFA%CUT_FACE_IND1)%BODTRI(2,CFA%CUT_FACE_IND2)
IF (IBOD>=1 .AND. IWSEL>=1) NVEC(IAXIS:KAXIS) = GEOMETRY(IBOD)%FACES_NORMAL(IAXIS:KAXIS,IWSEL)

END FUNCTION GET_CFACE_RAD_NVEC

! ----------------------------------- GET_PRES_CFACE ---------------------------------

SUBROUTINE GET_PRES_CFACE(PRESS,IND1,IND2,CFA)

TYPE(CFACE_TYPE), INTENT(IN) :: CFA
INTEGER,  INTENT( IN) :: IND1, IND2
REAL(EB), INTENT(OUT) :: PRESS

! Local Variables:
INTEGER :: ICC, IIG, JJG, KKG
TYPE(BOUNDARY_PROP1_TYPE), POINTER :: B1

B1 => BOUNDARY_PROP1(CFA%B1_INDEX)
! Underlying cell values corresponding to cut-cell:
ICC = CUT_FACE(IND1)%CELL_LIST(2,LOW_IND,IND2)
IIG = CUT_CELL(ICC)%IJK(IAXIS)
JJG = CUT_CELL(ICC)%IJK(JAXIS)
KKG = CUT_CELL(ICC)%IJK(KAXIS)
PRESS=B1%RHO_G*(H(IIG,JJG,KKG)-KRES(IIG,JJG,KKG))

RETURN
END SUBROUTINE GET_PRES_CFACE

! ----------------------------------- GET_PRES_CFACE_TEST ---------------------------------

SUBROUTINE GET_PRES_CFACE_TEST(PRESS,IND1,IND2,CFA)

TYPE(CFACE_TYPE), INTENT(IN) :: CFA
INTEGER,  INTENT( IN) :: IND1, IND2
REAL(EB), INTENT(OUT) :: PRESS
TYPE(BOUNDARY_PROP1_TYPE), POINTER :: B1

! Local Variables:
INTEGER :: ICC, IIG, JJG, KKG

B1 => BOUNDARY_PROP1(CFA%B1_INDEX)
! Underlying cell approximate value (the cut-face interpolation stencil formerly used here was never built):
ICC = CUT_FACE(IND1)%CELL_LIST(2,LOW_IND,IND2)
IIG = CUT_CELL(ICC)%IJK(1)
JJG = CUT_CELL(ICC)%IJK(2)
KKG = CUT_CELL(ICC)%IJK(3)
PRESS=B1%RHO_G*H(IIG,JJG,KKG)

RETURN
END SUBROUTINE GET_PRES_CFACE_TEST

! ------------------------------- CFACE_THERMAL_GASVARS ------------------------------

SUBROUTINE CFACE_THERMAL_GASVARS(NM,ICF,SF,B1,T)
USE MATH_FUNCTIONS, ONLY: EVALUATE_RAMP
TYPE(SURFACE_TYPE), POINTER :: SF
TYPE(BOUNDARY_PROP1_TYPE) :: B1
INTEGER, INTENT(IN) :: NM,ICF
REAL(EB),INTENT(IN) :: T

! Local Variables:
INTEGER :: IND1,IND2,ICC,JCC,I,J,K
REAL(EB):: PREDFCT,U_CAVG,V_CAVG,W_CAVG,K_G
REAL(EB), POINTER, DIMENSION(:,:,:) :: UP,VP,WP
TYPE(CFACE_TYPE),          POINTER :: CFA
TYPE(BOUNDARY_COORD_TYPE), POINTER :: BC

CFA => CFACE(ICF)
BC => BOUNDARY_COORD(CFA%BC_INDEX)
! Load indexes {ICF,IFACE} in CUT_FACE, for CFACE {ICFACE}:
IND1=CFA%CUT_FACE_IND1
IND2=CFA%CUT_FACE_IND2

IF (PREDICTOR) THEN
   PREDFCT=1._EB
   UP => U ! Corrector final velocities.
   VP => V
   WP => W
ELSE
   PREDFCT=0._EB
   UP => US ! Predictor final velocities.
   VP => VS
   WP => WS
ENDIF
SELECT CASE(CUT_FACE(IND1)%CELL_LIST(1,LOW_IND,IND2))
CASE(CC_FTYPE_CFGAS) ! Cut-cell -> use value from CUT_CELL data struct:

   ICC = CUT_FACE(IND1)%CELL_LIST(2,LOW_IND,IND2)
   JCC = CUT_FACE(IND1)%CELL_LIST(3,LOW_IND,IND2)

   I = CUT_CELL(ICC)%IJK(IAXIS)
   J = CUT_CELL(ICC)%IJK(JAXIS)
   K = CUT_CELL(ICC)%IJK(KAXIS)

   IF (SF%TMP_GAS_FRONT > 0._EB) THEN
      B1%TMP_G = TMPA + EVALUATE_RAMP(T-T_BEGIN,SF%RAMP(TIME_TGF)%INDEX)*(SF%TMP_GAS_FRONT-TMPA)
   ELSE
      B1%TMP_G = GET_CUTCELL_TMP(NM,ICC,JCC)
   ENDIF

   CFA%RSUM_G = GET_CUTCELL_RSUM(NM,ICC,JCC)
   B1%RHO_G   = GET_CUTCELL_RHOP(NM,ICC,JCC,1._EB-PREDFCT)
   CALL GET_CUTCELL_ZZV(NM,ICC,JCC,1._EB-PREDFCT,B1%ZZ_G)

   ! Viscosity, Use MU from bearing cartesian cell:
   CFA%MU_G = MU(I,J,K)

   ! Gas conductivity:
   CALL GET_CC_CELL_CONDUCTIVITY(B1%ZZ_G(1:N_TRACKED_SPECIES),MU(I,J,K),MU_DNS(I,J,K),B1%TMP_G,K_G)
   B1%K_G = K_G

   CALL GET_UVWGAS_CFACE(U_CAVG,V_CAVG,W_CAVG,IND1,IND2,UP,VP,WP,PREDFCT,NM)

   ! U_TANG use the norm of CC centroid area averaged velocity:
   B1%U_TANG = SQRT( U_CAVG**2._EB + V_CAVG**2._EB + W_CAVG**2._EB )

END SELECT

END SUBROUTINE CFACE_THERMAL_GASVARS

! -------------------------- CC_VELOCITY_CUTFACES ----------------------------

SUBROUTINE CC_VELOCITY_CUTFACES(APPLY_TO_ESTIMATED_VARIABLES)

LOGICAL, INTENT(IN) :: APPLY_TO_ESTIMATED_VARIABLES

! Local Variables:
INTEGER  :: NM,ICF,LCF,JCF,I,J,K,X1AXIS
REAL(EB) :: AREATOT,A_CART,VEL_AREA
REAL(EB), POINTER, DIMENSION(:,:,:) :: UP,VP,WP
TYPE(CC_CUTFACE_TYPE), POINTER :: CF

! Mesh Loop:
MESH_LOOP : DO NM=LOWER_MESH_INDEX,UPPER_MESH_INDEX
   CALL POINT_TO_MESH(NM)
   IF (APPLY_TO_ESTIMATED_VARIABLES) THEN
      UP => US ! Predictor final velocities.
      VP => VS
      WP => WS
   ELSE
      UP => U  ! Corrector final velocities.
      VP => V
      WP => W
   ENDIF

   ! Cut-face Loop:
   CUTFACE_LOOP_1 : DO LCF=1,SIZE(MESHES(NM)%CF_GAS)
      ICF=MESHES(NM)%CF_GAS(LCF); CF => CUT_FACE(ICF)
      I  =  CF%IJK(IAXIS); J = CF%IJK(JAXIS); K = CF%IJK(KAXIS); X1AXIS = CF%IJK(KAXIS+1)
      AREATOT= SUM(CF%AREA(1:CF%NFACE))
      VEL_AREA=0._EB
      DO JCF=1,CF%NFACE
         IF (APPLY_TO_ESTIMATED_VARIABLES) THEN
            VEL_AREA=VEL_AREA+CC_FV_CUTFACE_MOM(NM,ICF,JCF,CC_FV_MOM_VELS)*CF%AREA(JCF)
         ELSE
            VEL_AREA=VEL_AREA+CC_FV_CUTFACE_MOM(NM,ICF,JCF,CC_FV_MOM_VEL)*CF%AREA(JCF)
         ENDIF
      ENDDO
      CF%VEL_CF=VEL_AREA/AREATOT
      SELECT CASE(X1AXIS)
      CASE(IAXIS); A_CART = DY(J)*DZ(K); CF%VEL_CRT= CF%VEL_CF*AREATOT/A_CART; UP(I,J,K) = CF%VEL_CRT
      CASE(JAXIS); A_CART = DZ(K)*DX(I); CF%VEL_CRT= CF%VEL_CF*AREATOT/A_CART; VP(I,J,K) = CF%VEL_CRT
      CASE(KAXIS); A_CART = DX(I)*DY(J); CF%VEL_CRT= CF%VEL_CF*AREATOT/A_CART; WP(I,J,K) = CF%VEL_CRT
      END SELECT
   ENDDO CUTFACE_LOOP_1

ENDDO MESH_LOOP


RETURN
END SUBROUTINE CC_VELOCITY_CUTFACES


! ----------------------------- CC_RHO0W_INTERP ------------------------------

SUBROUTINE CC_RHO0W_INTERP

! Local Variables:
REAL(EB), POINTER, DIMENSION(:,:,:) :: WP
INTEGER :: NM, ICC, ICELL, IG
INTEGER :: INBFC_CCCEN(1:3)
REAL(EB):: XYZ_PP(MAX_DIM)
REAL(EB):: TNOW
INTEGER :: INPE,INT_NPE_LO,INT_NPE_HI,EP,VIND
REAL(EB):: WCEN_EP,WCEN_BP,COEF_EP,COEF_BP
TYPE(CC_FV_TYPE), POINTER :: FV

! W at cut-piece centers when stratification is on. RHO_0 is not stored from this walk.

IF (.NOT. STRATIFICATION) RETURN
IF (PERIODIC_TEST == 103 .OR. PERIODIC_TEST == 11 .OR. PERIODIC_TEST==7) RETURN

TNOW = CURRENT_TIME()

MESH_LOOP : DO NM=LOWER_MESH_INDEX,UPPER_MESH_INDEX

   CALL POINT_TO_MESH(NM)
   FV => MESHES(NM)%FV

   IF (PREDICTOR) THEN
      WP => WS
   ELSE
      WP => W
   ENDIF

   VIND = 0
   DO IG=1,FV%GCELL%N_CUT
      ICC=FV%GCELL%ICC(IG); ICELL=FV%GCELL%JCC(IG)
      WCEN_EP = 0._EB
      DO EP=1,INT_N_EXT_PTS
         INT_NPE_LO = CUT_CELL(ICC)%INT_NPE(LOW_IND,VIND,EP,ICELL)
         INT_NPE_HI = CUT_CELL(ICC)%INT_NPE(HIGH_IND,VIND,EP,ICELL)
         DO INPE=INT_NPE_LO+1,INT_NPE_LO+INT_NPE_HI
            WCEN_EP = WCEN_EP + CUT_CELL(ICC)%INT_COEF(INPE)* &
                                CUT_CELL(ICC)%INT_CCVARS(INT_WCEN_IND,INPE)
         ENDDO
      ENDDO

      XYZ_PP(IAXIS:KAXIS) = CUT_CELL(ICC)%INT_XYZBF(IAXIS:KAXIS,ICELL)
      INBFC_CCCEN(1:3)    = CUT_CELL(ICC)%INT_INBFC(1:3,ICELL)
      CALL GET_BOUND_VEL(KAXIS,INBFC_CCCEN,XYZ_PP,WCEN_BP)
      COEF_EP = 0._EB
      IF (ABS(CUT_CELL(ICC)%INT_XN(1,ICELL)) > TWENTY_EPSILON_EB) &
         COEF_EP = CUT_CELL(ICC)%INT_XN(0,ICELL)/CUT_CELL(ICC)%INT_XN(1,ICELL)
      COEF_BP = 1._EB - COEF_EP
      FV%CV%WVEL(IG) = COEF_BP*WCEN_BP + COEF_EP*WCEN_EP
   ENDDO

   NULLIFY(WP)

ENDDO MESH_LOOP

T_USED(14) = T_USED(14) + CURRENT_TIME() - TNOW
RETURN
END SUBROUTINE CC_RHO0W_INTERP

! ------------------------------- CC_H_INTERP --------------------------------

SUBROUTINE CC_H_INTERP

! Local Variables:
REAL(EB), POINTER, DIMENSION(:,:,:) :: UP,VP,WP,HP
INTEGER :: NM, I, J, K, IG
TYPE(CC_FV_TYPE), POINTER :: FV

! Copy the Cartesian H of each active cut piece onto its CV row.

MESH_LOOP : DO NM=LOWER_MESH_INDEX,UPPER_MESH_INDEX

   CALL POINT_TO_MESH(NM)
   FV => MESHES(NM)%FV

   IF (PREDICTOR) THEN
      HP => H
      UP => US
      VP => VS
      WP => WS
      DO IG=1,FV%GCELL%N_CUT
         I=FV%GCELL%IJK(IAXIS,IG); J=FV%GCELL%IJK(JAXIS,IG); K=FV%GCELL%IJK(KAXIS,IG)
         FV%CV%H(IG) = HP(I,J,K)
      ENDDO
   ELSE
      HP => HS
      UP => U
      VP => V
      WP => W
      DO IG=1,FV%GCELL%N_CUT
         I=FV%GCELL%IJK(IAXIS,IG); J=FV%GCELL%IJK(JAXIS,IG); K=FV%GCELL%IJK(KAXIS,IG)
         FV%CV%HS(IG) = HP(I,J,K)
      ENDDO
   ENDIF

   ! Finally set HP to zero inside immersed solids:
   WHERE(MESHES(NM)%CCVAR(0:IBP1,0:JBP1,0:KBP1,CC_CGSC)==CC_SOLID) HP(0:IBP1,0:JBP1,0:KBP1) = 0._EB

   ! Set velocities on solid faces to zero:
   WHERE(MESHES(NM)%FCVAR(0:IBAR,1:JBAR,1:KBAR,CC_FGSC,IAXIS)==CC_SOLID) UP(0:IBAR,1:JBAR,1:KBAR) = 0._EB
   WHERE(MESHES(NM)%FCVAR(1:IBAR,0:JBAR,1:KBAR,CC_FGSC,JAXIS)==CC_SOLID) VP(1:IBAR,0:JBAR,1:KBAR) = 0._EB
   WHERE(MESHES(NM)%FCVAR(1:IBAR,1:JBAR,0:KBAR,CC_FGSC,KAXIS)==CC_SOLID) WP(1:IBAR,1:JBAR,0:KBAR) = 0._EB

   NULLIFY(UP,VP,WP,HP)

ENDDO MESH_LOOP

RETURN
END SUBROUTINE CC_H_INTERP


! ----------------------------- CCCOMPUTE_RADIATION --------------------------------

SUBROUTINE CCCOMPUTE_RADIATION(T,NM,ITER)

! This is a temporary container where to add QR=-CHI_R*Q

INTEGER, INTENT(IN) :: NM,ITER
REAL(EB), INTENT(IN) :: T

! Local Variables:
INTEGER ICC,JCC,I,J,K,IG
REAL(EB):: DUMMY1
INTEGER :: DUMMY2
REAL(EB) :: TNOW
TYPE(CC_FV_TYPE), POINTER :: FV

DUMMY1=T
DUMMY2=ITER

TNOW = CURRENT_TIME()
FV=>MESHES(NM)%FV

IF(.NOT.RADIATION) THEN
   IF (N_REACTIONS>0) THEN
      DO ICC=1,MESHES(NM)%N_CUTCELL_MESH
         DO JCC=1,CUT_CELL(ICC)%NCELL
            IG = CUT_CELL(ICC)%IG(JCC); IF (IG<1) CYCLE
            FV%CV%QR(IG) = -FV%CV%CHI_R(IG)*FV%CV%Q(IG)
         ENDDO
      ENDDO
   ENDIF
ELSE
   ! Solution for QR in underlaying Cartesian cell, coming from RADIATION_FVM
   DO ICC=1,MESHES(NM)%N_CUTCELL_MESH
      I = CUT_CELL(ICC)%IJK(IAXIS)
      J = CUT_CELL(ICC)%IJK(JAXIS)
      K = CUT_CELL(ICC)%IJK(KAXIS)
      DO JCC=1,CUT_CELL(ICC)%NCELL
         IG = CUT_CELL(ICC)%IG(JCC); IF (IG<1) CYCLE
         FV%CV%QR(IG) = QR(I,J,K)
      ENDDO
   ENDDO
ENDIF

T_USED(14) = T_USED(14) + CURRENT_TIME() - TNOW
IF (TIME_CC_IBM) T_CC_USED(CCCOMPUTE_RADIATION_TIME_INDEX) = T_CC_USED(CCCOMPUTE_RADIATION_TIME_INDEX) + CURRENT_TIME() - TNOW
RETURN
END SUBROUTINE CCCOMPUTE_RADIATION


! -------------------------------- CC_SET_DATA ----------------------------------

SUBROUTINE CC_SET_DATA(FIRST_CALL)

USE MEMORY_FUNCTIONS, ONLY: EXCHANGE_GEOMETRY_INFO

LOGICAL, INTENT(IN) :: FIRST_CALL

! Local Variables:
INTEGER :: NM,ICALL
REAL(EB):: LX,LY,LZ,MAX_DIST
REAL(EB):: TNOW,TNOW2,TDEL,MIN_XS(1:3),MAX_XF(1:3)

INTEGER :: ICF, IG
CHARACTER(80) :: FN_CCTIME
CHARACTER(200)::TCFORM
CHARACTER(20) :: CC_SETUP_DRIVER

INTEGER :: ICC,JCC,I,J,K,ICC2,JCC2,JCF,IFACE,FTYPE,IFC2,IFACE2,ICF2,JCF2
REAL(EB):: ACRT
TYPE(CC_CUTCELL_TYPE), POINTER :: CC2
TYPE(CC_CUTFACE_TYPE), POINTER :: CF2

TNOW2 = CURRENT_TIME()

SET_CUTCELLS_CALL_IF : IF(FIRST_CALL) THEN

! Plane by plane Evaluation of stesses for IBEDGES, a la OBSTS.
CC_ONLY_IBEDGES_FLAG=.FALSE.
THRES_FCT_EP = -1._EB

IF (N_GEOMETRY==0 .AND. .NOT.(PERIODIC_TEST==103 .OR. PERIODIC_TEST==11 .OR. PERIODIC_TEST==7)) THEN
   IF (MY_RANK==0) THEN
      WRITE(LU_ERR,*) ' '
      WRITE(LU_ERR,*) 'CCIBM Setup Error : &MISC CC_IBM=.TRUE., but no &GEOM namelist defined on input file.'
      WRITE(LU_ERR,*) ' '
   ENDIF
   STOP_STATUS = SETUP_STOP
   RETURN
ENDIF

! Defined relative GEOMEPS:
! Find largest domain distance to define relative epsilon:
MIN_XS(1:3) = (/ MESHES(1)%XS, MESHES(1)%YS, MESHES(1)%ZS /)
MAX_XF(1:3) = (/ MESHES(1)%XF, MESHES(1)%YF, MESHES(1)%ZF /)
DO NM=2,NMESHES
   MIN_XS(1) = MIN(0._EB,MIN_XS(1),MESHES(NM)%XS)
   MIN_XS(2) = MIN(0._EB,MIN_XS(2),MESHES(NM)%YS)
   MIN_XS(3) = MIN(0._EB,MIN_XS(3),MESHES(NM)%ZS)
   MAX_XF(1) = MAX(0._EB,MAX_XF(1),MESHES(NM)%XF)
   MAX_XF(2) = MAX(0._EB,MAX_XF(2),MESHES(NM)%YF)
   MAX_XF(3) = MAX(0._EB,MAX_XF(3),MESHES(NM)%ZF)
ENDDO
LX = MAX_XF(1) - MIN_XS(1)
LY = MAX_XF(2) - MIN_XS(2)
LZ = MAX_XF(3) - MIN_XS(3)
MAX_DIST=MAX(LX,LY,LZ)

! Now test against GEOMETRY size:
DO IG=1,N_GEOMETRY
   LX = GEOMETRY(IG)%GEOM_BOX(HIGH_IND,IAXIS) - GEOMETRY(IG)%GEOM_BOX( LOW_IND,IAXIS)
   LY = GEOMETRY(IG)%GEOM_BOX(HIGH_IND,JAXIS) - GEOMETRY(IG)%GEOM_BOX( LOW_IND,JAXIS)
   LZ = GEOMETRY(IG)%GEOM_BOX(HIGH_IND,KAXIS) - GEOMETRY(IG)%GEOM_BOX( LOW_IND,KAXIS)
   MAX_DIST=MAX(MAX_DIST,LX,LY,LZ)
ENDDO

! Set relative epsilon for cut-cell definition:
MAX_DIST= MAX(1._EB,MAX_DIST)
GEOMEPS = GEOMEPS*MAX_DIST
CALL CC_GRID_SET_CV_CANON_XYZ_TOL

IF(MY_RANK==0 .AND. GET_CUTCELLS_VERBOSE) THEN
   WRITE(LU_ERR,*) 'GEOMETRY intersection computation THRESHOLD GEOMEPS=',GEOMEPS
ENDIF

! Set CCVOL_LINK an epsilon higher than defined value to have all cells/faces around defined value linked.
CCVOL_LINK = CCVOL_LINK + GEOMEPS

CC_SETUP_DRIVER = 'SET_CVS_3D'
IF (MY_RANK==0 .AND. GET_CUTCELLS_VERBOSE) THEN
   WRITE(LU_ERR,'(A,A)') ' CC setup driver: ',TRIM(CC_SETUP_DRIVER)
ENDIF

IF (PERIODIC_TEST == 105) THEN ! Set cc-guard to zero, i.e. do not compute guard-cell cut-cells, for timings.
   NGUARD = 2
   CCGUARD= NGUARD-2
ENDIF

TNOW = CURRENT_TIME()
CALL SET_CVS_3D                      ! Always build CUT_CELL plus GCELL/CV/FACE; solver consumption is a separate flag.
IF (STOP_STATUS/=NO_STOP) RETURN

TDEL = CURRENT_TIME() - TNOW

IF (PERIODIC_TEST == 105) THEN ! Cut-cell definition timings test.
    IF(MY_RANK==0) WRITE(LU_ERR,*) ' '
    ICALL = 1
    IF(MY_RANK==0) WRITE(LU_ERR,*) 'CALL number ',ICALL,' to ',TRIM(CC_SETUP_DRIVER),' finished. Max Time=',TDEL,' sec.'
    DO ICALL=2,N_SET_CUTCELLS_3D_CALLS
       TNOW = CURRENT_TIME()
       CALL SET_CVS_3D
       TDEL = CURRENT_TIME() - TNOW
       IF(MY_RANK==0) WRITE(LU_ERR,*) 'CALL number ',ICALL,' to ',TRIM(CC_SETUP_DRIVER),' finished. Max Time=',TDEL,' sec.'
    ENDDO
    WRITE_SET_CUTCELLS_TIMINGS = .TRUE.
ENDIF

! Write out SET_CUTCELLS_3D loop time:
IF (WRITE_SET_CUTCELLS_TIMINGS) THEN

   ! Total number of cut-cells and faces computed does not consider guard-cells:
   N_CUTCELLS_PROC     = 0
   N_INB_CUTFACES_PROC = 0
   N_REG_CUTFACES_PROC = 0
   DO NM=LOWER_MESH_INDEX,UPPER_MESH_INDEX
      CALL POINT_TO_MESH(NM)
      ! Cut-cells:
      N_CUTCELLS_PROC = N_CUTCELLS_PROC + MESHES(NM)%N_CUTCELL_MESH
      ! Cut-faces:
      DO ICF=1,MESHES(NM)%N_CUTFACE_MESH
         SELECT CASE(CUT_FACE(ICF)%STATUS)
         CASE(CC_GASPHASE)
            N_REG_CUTFACES_PROC = N_REG_CUTFACES_PROC + CUT_FACE(ICF)%NFACE
         CASE(CC_INBOUNDARY)
            N_INB_CUTFACES_PROC = N_INB_CUTFACES_PROC + CUT_FACE(ICF)%NFACE
         END SELECT
      ENDDO
   ENDDO

   ! Write xxx_cc_cpu_0001.csv
   ! This csv file contains the following fields (14):
   ! N_CUTCELLS, N_INB_CUTFACES, N_REG_CUTFACES, SET_CUTCELLS_TIME, GET_BODINT_PLANE_TIME, GET_X2_INTERSECTIONS_TIME, &
   ! GET_X2_VERTVAR_TIME, GET_CARTEDGE_CUTEDGES_TIME, GET_BODX2X3_INTERSECTIONS_TIME, GET_CARTFACE_CUTEDGES_TIME, &
   ! GET_CARTCELL_CUTEDGES_TIME, GET_CARTFACE_CUTFACES_TIME, GET_CARTCELL_CUTFACES_TIME, GET_CARTCELL_CUTCELLS_TIME
   WRITE(FN_CCTIME,'(A,A,I3.3,A)') TRIM(CHID),'_cc_cpu_',MY_RANK,'.csv'
   OPEN(333,FILE=TRIM(FN_CCTIME),STATUS='UNKNOWN')
   WRITE(333,'(A,A,A,A)') "N_CUTCELLS, N_INB_CUTFACES, N_REG_CUTFACES, SET_CUTCELLS_TIME, GET_BODINT_PLANE_TIME, ",   &
                          "GET_X2_INTERSECTIONS_TIME, GET_X2_VERTVAR_TIME, GET_CARTEDGE_CUTEDGES_TIME, ",             &
                          "GET_BODX2X3_INTERSECTIONS_TIME, GET_CARTFACE_CUTEDGES_TIME, GET_CARTCELL_CUTEDGES_TIME, ", &
                          "GET_CARTFACE_CUTFACES_TIME, GET_CARTCELL_CUTFACES_TIME, GET_CARTCELL_CUTCELLS_TIME"
   WRITE(TCFORM,'(23A)')  "(I6,',',I6,',',I6,',',",FMT_R,",',',",FMT_R,",',',",FMT_R,",',',",FMT_R,",',',",           &
                          FMT_R,",',',",FMT_R,",',',",FMT_R,",',',",FMT_R,",',',",FMT_R,",',',",FMT_R,",',',",FMT_R,")"
   WRITE(333,TCFORM) N_CUTCELLS_PROC,N_INB_CUTFACES_PROC,N_REG_CUTFACES_PROC, &
                     T_CC_USED(SET_CUTCELLS_TIME_INDEX:GET_CARTCELL_CUTCELLS_TIME_INDEX)/ &
                     REAL(N_SET_CUTCELLS_3D_CALLS,EB)
   CLOSE(333)


   IF (MY_RANK == 0) THEN
      WRITE(LU_ERR,*) ' '
      WRITE(LU_ERR,*) 'Spheres NVERTS,NFACES',GEOMETRY(1)%N_VERTS,GEOMETRY(1)%N_FACES
      WRITE(LU_ERR,*) 'SET_CUTCELLS_3D loop time by process ',MY_RANK,' =',T_CC_USED(SET_CUTCELLS_TIME_INDEX), &
                      ' sec., cut-cells=',N_CUTCELLS_PROC,', cut-faces=',N_INB_CUTFACES_PROC,N_REG_CUTFACES_PROC
   ENDIF
ENDIF

! Redefine interpolated external wall_cells inside Geoms: We assume them SOLID_BOUNDARY
CALL BLOCK_CC_SOLID_EXTWALLCELLS(FIRST_CALL)

ELSE SET_CUTCELLS_CALL_IF

IF (GET_CUTCELLS_VERBOSE .AND. MY_RANK==0) THEN
   CALL CPU_TIME(TNOW)
ENDIF

! Redefine wall_cells inside Geoms: This is done before EDGE info as edges with WALL_CELL type NULL_BOUNDARY will be taken
! care of by GEOM edges. Note EDGE_INDEX will be reassigned the IBEDGE position in OMEGA, TAU arrays for velocity flux to
! be computed correctly.

CALL BLOCK_CC_SOLID_EXTWALLCELLS(FIRST_CALL)

! Reallocate and populate FDS edge and cell topology variables

DO NM=LOWER_MESH_INDEX,UPPER_MESH_INDEX
   IF (.NOT.CC_ONLY_IBEDGES_FLAG) CALL GET_REGULAR_CUT_EDGES_BC(NM)
   CALL GET_SOLID_CUTCELL_EDGES_BC(NM)
ENDDO

CALL EXCHANGE_GEOMETRY_INFO

CALL GET_CRTCFCC_INT_STENCILS ! Computes interpolation stencils for face and cell centers.
IF (GET_CUTCELLS_VERBOSE .AND. MY_RANK==0) THEN
   CALL CPU_TIME(TDEL)
   WRITE(LU_ERR,'(A,F8.3,A)') ' Executed GET_CRTCFCC_INT_STENCILS. Time taken : ',TDEL-TNOW,' sec.'
ENDIF
CALL SET_CC_MATVEC_DATA              ! Defines data for discretization matrix-vectors.
IF (GET_CUTCELLS_VERBOSE) THEN
   DO NM=LOWER_MESH_INDEX,UPPER_MESH_INDEX
      CALL DUMP_CC_LINK_MAP(NM)
   ENDDO
ENDIF
IF (GET_CUTCELLS_VERBOSE .AND. MY_RANK==0) THEN
   CALL CPU_TIME(TNOW)
   WRITE(LU_ERR,'(A,F8.3,A)') ' Executing SET_CC_MATVEC_DATA. Time taken : ',TNOW-TDEL,' sec.'
ENDIF
CALL SET_CFACES_P1_RDN               ! Set inverse DXN for CFACES, uses cell linking information.
DO NM=LOWER_MESH_INDEX,UPPER_MESH_INDEX
   CALL CC_SET_MOMENTUM_FACE_LISTS(NM)
ENDDO
CALL CC_SET_CFL_ROWS
CALL CC_SET_THERMO_ROWS
CALL CC_SET_CVCHEM_LISTS
CALL CC_SET_DENSITY_LISTS
IF (GET_CUTCELLS_VERBOSE .AND. MY_RANK==0) THEN
   CALL CPU_TIME(TDEL)
   WRITE(LU_ERR,'(A,F8.3,A)') ' Executing SET_CFACES_P1_RDN. Time taken : ',TDEL-TNOW,' sec.'
ENDIF

! Give information for a particular cell:
IF (DEBUG_MATVEC_DATA) THEN
   NM = 1; I = 17; J = 24; K = 19
   CALL POINT_TO_MESH(NM)
   IF (CCVAR(I,J,K,CC_IDCC)<1) THEN
      WRITE(LU_ERR,*) 'No cut-cells in cell NM,I,J,K=',NM,I,J,K
   ELSE
      ICC = CCVAR(I,J,K,CC_IDCC); CC=>CUT_CELL(ICC)
      WRITE(LU_ERR,*) 'Cut Cell in cell NM,I,J,K : ICC,NCELL=',NM,I,J,K,':',ICC,CC%NCELL
      DO JCC=1,CC%NCELL
         ! Linking Info on cut-cell ICC,JCC
         WRITE(LU_ERR,*) 'JCC,ALPHA_CC, CC%IJK_LINK(:,JCC) : CC%LINK_LEV(JCC), UNKZ=',&
         JCC,CC%VOLUME(JCC)/(DX(I)*DY(J)*DZ(K)),CC%IJK_LINK(:,JCC),':',CC%LINK_LEV(JCC),CC%UNKZ(JCC)
         IF (CC%IJK_LINK(1,JCC)==CC_CUTCFE) THEN
            ICC2=CCVAR(CC%IJK_LINK(2,JCC),CC%IJK_LINK(3,JCC),CC%IJK_LINK(4,JCC),CC_IDCC);
            JCC2=CC%IJK_LINK(5,JCC)
            CC2 => CUT_CELL(ICC2)
            ! Linking Info on Parent if it is a cut-face:
            WRITE(LU_ERR,*) 'Parent CC2 I,J,K,JCC2 : ALPHA_CC2, CC2%IJK_LINK(:,JCC2) : CC2%LINK_LEV(JCC2) UNKZ=',&
            CC%IJK_LINK(2:5,JCC),':',CC2%VOLUME(JCC2)/(DX(I)*DY(J)*DZ(K)),CC2%IJK_LINK(:,JCC2),':',&
            CC2%LINK_LEV(JCC2),CC2%UNKZ(JCC2)
         ENDIF
         ! Linking info on cut-faces for ICC,JCC:
         DO JCF=2,CC%CCELEM(1,JCC)+1
            IFACE = CC%CCELEM(JCF,JCC)
            FTYPE = CC%FACE_LIST(1,IFACE)
            IF (FTYPE==CC_FTYPE_CFGAS) THEN
               IFC2    = CC%FACE_LIST(4,IFACE)
               IFACE2  = CC%FACE_LIST(5,IFACE)
               CF => CUT_FACE(IFC2)
               IF(CF%IJK(KAXIS+1)==IAXIS) ACRT = DY(J)*DZ(K)
               IF(CF%IJK(KAXIS+1)==JAXIS) ACRT = DX(I)*DZ(K)
               IF(CF%IJK(KAXIS+1)==KAXIS) ACRT = DX(I)*DY(J)
               WRITE(LU_ERR,*) 'CC Cut-face JFC,ICF,JCF,ALPHA_CF : CF%LINK_LEV(JCF),CC_FV_UNKF_CF(NM,ICF,JCF)=',&
               JCF,IFC2,IFACE2,CF%AREA(IFACE2)/ACRT,':',CF%LINK_LEV(IFACE2),CC_FV_UNKF_CF(NM,IFC2,IFACE2)
               WRITE(LU_ERR,*) 'CUT-FACES with UNKF(JCF) : ',CC_FV_UNKF_CF(NM,IFC2,IFACE2)
               DO ICF2=1,MESHES(NM)%N_CUTFACE_MESH
                  CF2=>CUT_FACE(ICF2); IF(CF2%STATUS/=CC_GASPHASE) CYCLE
                  DO JCF2=1,CF2%NFACE
                     IF(CC_FV_UNKF_CF(NM,ICF2,JCF2)==CC_FV_UNKF_CF(NM,IFC2,IFACE2)) THEN
                        WRITE(LU_ERR,*) 'CF with UNKF(JCF) ICF2,JCF2,I2,J2,K2,AX2,ALPHA_2,LINK_LEV2=',&
                        ICF2,JCF2,CF2%IJK(1:4),CF2%AREA(JCF2)/ACRT,':',CF2%LINK_LEV(JCF2),CC_FV_UNKF_CF(NM,ICF2,JCF2)
                     ENDIF
                  ENDDO
               ENDDO
            ENDIF
         ENDDO
      ENDDO
   ENDIF
ENDIF



IF(GET_CUTCELLS_VERBOSE) CLOSE(LU_SETCC)

! Set flag that specifies cut-cell data as defined:
CC_MATVEC_DEFINED=.TRUE.

ENDIF SET_CUTCELLS_CALL_IF

T_USED(14) = T_USED(14) + CURRENT_TIME() - TNOW2

IF (TIME_CC_IBM) T_CC_USED(CC_SET_DATA_TIME_INDEX) = T_CC_USED(CC_SET_DATA_TIME_INDEX) + CURRENT_TIME() - TNOW2
RETURN

CONTAINS

! ------------------------ SET_CFACES_P1_RDN ---------------------------------

SUBROUTINE SET_CFACES_P1_RDN

USE MPI_F08
! Local Variables:
INTEGER :: ICF,IFACE,NROW_CV,IERR
INTEGER :: ICC, JCC, I, J, K
INTEGER :: IFACE_CELL, ICF_CELL, IROW
INTEGER :: IROW_DELTA
REAL(EB):: AREAI
REAL(EB), ALLOCATABLE, DIMENSION(:) :: DXN_UNKZ_LOC, AREA_UNKZ_LOC, VOL_UNKZ_LOC
INTEGER, PARAMETER :: RDN_METHOD = 3 ! 1: VOL/SOLIDAREA, 2: bbox projection, 3: 2x normal distance to linked-CV centroid
REAL(EB), PARAMETER :: RDN_STIFF_MAX = 4._EB/3._EB ! Method 3: largest RDN*AREA/(VOL*R_DX2); a Cartesian wall cell has 1/3
REAL(EB), ALLOCATABLE, DIMENSION(:,:) :: XYZMIN_UNKZ, XYZMAX_UNKZ, XYZC_UNKZ
REAL(EB) :: DELTA_X, DELTA_Y, DELTA_Z, DXN, NVEC_ABS(MAX_DIM), R_DX2_CF
TYPE(CFACE_TYPE), POINTER :: CFA
TYPE(BOUNDARY_COORD_TYPE), POINTER :: BC

! ALLOCATE local arrays
   NROW_CV=MAX(1,NUNKZ_TOTAL)
ALLOCATE(DXN_UNKZ_LOC(1:NROW_CV));  DXN_UNKZ_LOC=0._EB
ALLOCATE(AREA_UNKZ_LOC(1:NROW_CV)); AREA_UNKZ_LOC=0._EB
ALLOCATE(VOL_UNKZ_LOC(1:NROW_CV));  VOL_UNKZ_LOC=0._EB
IF (RDN_METHOD==1) THEN
   ! Main Loop:
   MESH_LOOP_01 : DO NM=LOWER_MESH_INDEX,UPPER_MESH_INDEX

      CALL POINT_TO_MESH(NM)

      ! Do a volume weighted average of distance to wall from linked cells, if one of them is a regular cell use 1/2 the
      ! distance of corner to corner sqrt(DX^2+DY^2+DZ^2).
      ! 1. Regular GASPHASE cells within the cc-region:
      DO K=1,KBAR
         DO J=1,JBAR
            DO I=1,IBAR
               IF (CCVAR(I,J,K,CC_UNKZ) <= 0 ) CYCLE ! Drop if regular gas cell has not been assigned unknown number.
               IROW=CCVAR(I,J,K,CC_UNKZ)
               IF (IROW<1 .OR. IROW>NROW_CV) CYCLE
               VOL_UNKZ_LOC(IROW) = VOL_UNKZ_LOC(IROW) + (DX(I)*DY(J)*DZ(K))
            ENDDO
         ENDDO
      ENDDO
      ! 2. Cut-cells:
      DO ICC=1,MESHES(NM)%N_CUTCELL_MESH
         CC => CUT_CELL(ICC); I = CC%IJK(IAXIS); J = CC%IJK(JAXIS); K = CC%IJK(KAXIS)
         IF (CELL(CELL_INDEX(I,J,K))%SOLID) CYCLE
         DO JCC=1,CC%NCELL
            IROW=CC%UNKZ(JCC)
            IF (IROW<1 .OR. IROW>NROW_CV) CYCLE
            ! Mean INBOUNDARY cut-face distance to this cut-cell center, projected to cut-face normal:
            AREAI = 0._EB
            DO ICF_CELL=1,CC%CCELEM(1,JCC)
               IFACE_CELL = CC%CCELEM(ICF_CELL+1,JCC)
               IF (CC%FACE_LIST(1,IFACE_CELL) /= CC_FTYPE_CFINB) CYCLE
               ! Indexes of INBOUNDARY cutface on CUT_FACE:
               ICF   = CC%FACE_LIST(4,IFACE_CELL)
               IFACE = CC%FACE_LIST(5,IFACE_CELL)
               ! Area sum:
               AREAI = AREAI + CUT_FACE(ICF)%AREA(IFACE)
            ENDDO
            AREA_UNKZ_LOC(IROW) = AREA_UNKZ_LOC(IROW) + AREAI
            VOL_UNKZ_LOC(IROW) = VOL_UNKZ_LOC(IROW) + CC%VOLUME(JCC)
         ENDDO
      ENDDO

   ENDDO MESH_LOOP_01

      CALL MPI_ALLREDUCE(MPI_IN_PLACE,VOL_UNKZ_LOC,SIZE(VOL_UNKZ_LOC),MPI_DOUBLE_PRECISION,MPI_SUM,MPI_COMM_WORLD,IERR)
      CALL MPI_ALLREDUCE(MPI_IN_PLACE,AREA_UNKZ_LOC,SIZE(AREA_UNKZ_LOC),MPI_DOUBLE_PRECISION,MPI_SUM,MPI_COMM_WORLD,IERR)
   ! Compute average DXN of all linked cells:
   DXN_UNKZ_LOC = VOL_UNKZ_LOC / (AREA_UNKZ_LOC + TWO_EPSILON_EB)
ELSE
   ALLOCATE(XYZMIN_UNKZ(IAXIS:KAXIS,1:NROW_CV))
   ALLOCATE(XYZMAX_UNKZ(IAXIS:KAXIS,1:NROW_CV))
   CALL GET_LINKED_CELLS_BBOX(XYZMIN_UNKZ,XYZMAX_UNKZ)
   IF (ALLOCATED(DELTA_UNKZ)) THEN
      IF (SIZE(DELTA_UNKZ,DIM=2) /= NROW_CV) DEALLOCATE(DELTA_UNKZ)
   ENDIF
   IF (.NOT.ALLOCATED(DELTA_UNKZ)) ALLOCATE(DELTA_UNKZ(IAXIS:KAXIS,1:NROW_CV))
   DO IROW_DELTA=1,NROW_CV
      DELTA_UNKZ(IAXIS,IROW_DELTA) = MAX(0._EB,XYZMAX_UNKZ(IAXIS,IROW_DELTA)-XYZMIN_UNKZ(IAXIS,IROW_DELTA))
      DELTA_UNKZ(JAXIS,IROW_DELTA) = MAX(0._EB,XYZMAX_UNKZ(JAXIS,IROW_DELTA)-XYZMIN_UNKZ(JAXIS,IROW_DELTA))
      DELTA_UNKZ(KAXIS,IROW_DELTA) = MAX(0._EB,XYZMAX_UNKZ(KAXIS,IROW_DELTA)-XYZMIN_UNKZ(KAXIS,IROW_DELTA))
   ENDDO
ENDIF

IF (RDN_METHOD==3) THEN
   ! Volume weighted centroid, volume and INBOUNDARY area of each linked control volume.
   ! Same row as method 1: the scalar storage row.
   ALLOCATE(XYZC_UNKZ(IAXIS:KAXIS,1:NROW_CV)); XYZC_UNKZ = 0._EB
   MESH_LOOP_03 : DO NM=LOWER_MESH_INDEX,UPPER_MESH_INDEX
      CALL POINT_TO_MESH(NM)
      DO K=1,KBAR
         DO J=1,JBAR
            DO I=1,IBAR
               IF (CCVAR(I,J,K,CC_UNKZ) <= 0 ) CYCLE
               IROW = CCVAR(I,J,K,CC_UNKZ)
               IF (IROW<1 .OR. IROW>NROW_CV) CYCLE
               VOL_UNKZ_LOC(IROW) = VOL_UNKZ_LOC(IROW) + DX(I)*DY(J)*DZ(K)
               XYZC_UNKZ(IAXIS:KAXIS,IROW) = XYZC_UNKZ(IAXIS:KAXIS,IROW) + DX(I)*DY(J)*DZ(K)*(/XC(I),YC(J),ZC(K)/)
            ENDDO
         ENDDO
      ENDDO
      DO ICC=1,MESHES(NM)%N_CUTCELL_MESH
         CC => CUT_CELL(ICC); I = CC%IJK(IAXIS); J = CC%IJK(JAXIS); K = CC%IJK(KAXIS)
         IF (CELL(CELL_INDEX(I,J,K))%SOLID) CYCLE
         DO JCC=1,CC%NCELL
            IF (CC%UNKZ(JCC) <= 0) CYCLE
            IROW = CC%UNKZ(JCC)
            IF (IROW<1 .OR. IROW>NROW_CV) CYCLE
            VOL_UNKZ_LOC(IROW) = VOL_UNKZ_LOC(IROW) + CC%VOLUME(JCC)
            XYZC_UNKZ(IAXIS:KAXIS,IROW) = XYZC_UNKZ(IAXIS:KAXIS,IROW) + CC%VOLUME(JCC)*CC%XYZCEN(IAXIS:KAXIS,JCC)
            DO ICF_CELL=1,CC%CCELEM(1,JCC)
               IFACE_CELL = CC%CCELEM(ICF_CELL+1,JCC)
               IF (CC%FACE_LIST(1,IFACE_CELL) /= CC_FTYPE_CFINB) CYCLE
               ICF   = CC%FACE_LIST(4,IFACE_CELL)
               IFACE = CC%FACE_LIST(5,IFACE_CELL)
               AREA_UNKZ_LOC(IROW) = AREA_UNKZ_LOC(IROW) + CUT_FACE(ICF)%AREA(IFACE)
            ENDDO
         ENDDO
      ENDDO
   ENDDO MESH_LOOP_03
      CALL MPI_ALLREDUCE(MPI_IN_PLACE,VOL_UNKZ_LOC,SIZE(VOL_UNKZ_LOC),MPI_DOUBLE_PRECISION,MPI_SUM,MPI_COMM_WORLD,IERR)
      CALL MPI_ALLREDUCE(MPI_IN_PLACE,AREA_UNKZ_LOC,SIZE(AREA_UNKZ_LOC),MPI_DOUBLE_PRECISION,MPI_SUM,MPI_COMM_WORLD,IERR)
      CALL MPI_ALLREDUCE(MPI_IN_PLACE,XYZC_UNKZ,SIZE(XYZC_UNKZ),MPI_DOUBLE_PRECISION,MPI_SUM,MPI_COMM_WORLD,IERR)
   DO IROW=1,NROW_CV
      IF (VOL_UNKZ_LOC(IROW)>TWO_EPSILON_EB) XYZC_UNKZ(IAXIS:KAXIS,IROW) = XYZC_UNKZ(IAXIS:KAXIS,IROW)/VOL_UNKZ_LOC(IROW)
   ENDDO
ENDIF

! Finally Define B1%RDN:
MESH_LOOP_02 : DO NM=LOWER_MESH_INDEX,UPPER_MESH_INDEX
   CALL POINT_TO_MESH(NM)
   DO ICF=1,MESHES(NM)%N_CUTFACE_MESH
      CF => CUT_FACE(ICF); IF(CF%STATUS /= CC_INBOUNDARY) CYCLE
      I = CF%IJK(IAXIS); J = CF%IJK(JAXIS); K = CF%IJK(KAXIS); IF (CELL(CELL_INDEX(I,J,K))%SOLID) CYCLE
      DO IFACE=1,CF%NFACE
         IF (CF%CELL_LIST(1,LOW_IND,IFACE) /= CC_FTYPE_CFGAS) CYCLE
         ICC = CF%CELL_LIST(2,LOW_IND,IFACE)
         JCC = CF%CELL_LIST(3,LOW_IND,IFACE)
         IROW=CUT_CELL(ICC)%UNKZ(JCC)
         IF (IROW<1 .OR. IROW>NROW_CV) CYCLE
         SELECT CASE (RDN_METHOD)
         CASE (1)
            BOUNDARY_PROP1(CFACE(CF%CFACE_INDEX(IFACE))%B1_INDEX)%RDN = 1._EB/DXN_UNKZ_LOC(IROW)
         CASE (2)
            CFA => CFACE(CF%CFACE_INDEX(IFACE))
            BC  => BOUNDARY_COORD(CFA%BC_INDEX)
            DELTA_X = XYZMAX_UNKZ(IAXIS,IROW) - XYZMIN_UNKZ(IAXIS,IROW)
            DELTA_Y = XYZMAX_UNKZ(JAXIS,IROW) - XYZMIN_UNKZ(JAXIS,IROW)
            DELTA_Z = XYZMAX_UNKZ(KAXIS,IROW) - XYZMIN_UNKZ(KAXIS,IROW)
            NVEC_ABS(IAXIS:KAXIS) = ABS(BC%NVEC(IAXIS:KAXIS))
            DXN = DELTA_X*NVEC_ABS(IAXIS) + DELTA_Y*NVEC_ABS(JAXIS) + DELTA_Z*NVEC_ABS(KAXIS)
            BOUNDARY_PROP1(CFA%B1_INDEX)%RDN = 1._EB/(DXN + TWO_EPSILON_EB)
         CASE (3)
            ! Twice the normal distance from the CFACE centroid to the linked-CV centroid, floored so that the explicit wall flux
            ! stiffness RDN*AREA/VOL of the linked CV stays below RDN_STIFF_MAX*R_DX2, then capped at the bbox projection. The cap
            ! goes last: RDN must not drop below the method 2 value, which CHECK_CFLVN_LINKED_CELLS uses for small CVs.
            CFA => CFACE(CF%CFACE_INDEX(IFACE))
            BC  => BOUNDARY_COORD(CFA%BC_INDEX)
            DELTA_X = XYZMAX_UNKZ(IAXIS,IROW) - XYZMIN_UNKZ(IAXIS,IROW)
            DELTA_Y = XYZMAX_UNKZ(JAXIS,IROW) - XYZMIN_UNKZ(JAXIS,IROW)
            DELTA_Z = XYZMAX_UNKZ(KAXIS,IROW) - XYZMIN_UNKZ(KAXIS,IROW)
            NVEC_ABS(IAXIS:KAXIS) = ABS(BC%NVEC(IAXIS:KAXIS))
            DXN = 2._EB*( BC%NVEC(IAXIS)*(XYZC_UNKZ(IAXIS,IROW)-BC%X) + BC%NVEC(JAXIS)*(XYZC_UNKZ(JAXIS,IROW)-BC%Y) + &
                          BC%NVEC(KAXIS)*(XYZC_UNKZ(KAXIS,IROW)-BC%Z) )
            IF (TWO_D) THEN
               R_DX2_CF = RDX(I)**2 + RDZ(K)**2
            ELSE
               R_DX2_CF = RDX(I)**2 + RDY(J)**2 + RDZ(K)**2
            ENDIF
            DXN = MAX(DXN, AREA_UNKZ_LOC(IROW)/(RDN_STIFF_MAX*R_DX2_CF*VOL_UNKZ_LOC(IROW) + TWO_EPSILON_EB))
            DXN = MIN(DXN, DELTA_X*NVEC_ABS(IAXIS) + DELTA_Y*NVEC_ABS(JAXIS) + DELTA_Z*NVEC_ABS(KAXIS))
            BOUNDARY_PROP1(CFA%B1_INDEX)%RDN = 1._EB/(DXN + TWO_EPSILON_EB)
         END SELECT
      ENDDO
   ENDDO
ENDDO MESH_LOOP_02
IF (ALLOCATED(XYZC_UNKZ)) DEALLOCATE(XYZC_UNKZ)
IF (ALLOCATED(XYZMIN_UNKZ)) DEALLOCATE(XYZMIN_UNKZ, XYZMAX_UNKZ)
DEALLOCATE(DXN_UNKZ_LOC, VOL_UNKZ_LOC, AREA_UNKZ_LOC)

RETURN
END SUBROUTINE SET_CFACES_P1_RDN

! ---------------------- GET_LINKED_CELLS_BBOX --------------------------------

SUBROUTINE GET_LINKED_CELLS_BBOX(XYZMIN_UNKZ,XYZMAX_UNKZ)

USE MPI_F08
! Local Variables:
INTEGER :: I,J,K,ICC,JCC,IROW,IERR,NROW_CV
INTEGER :: IFACE, IFC, FTYPE, X1AXIS, LOWHIGH, ILH, IFC2, IFACE2, NVFACE, IPT, IVERT
REAL(EB) :: XLO, XHI, YLO, YHI, ZLO, ZHI
REAL(EB), INTENT(OUT) :: XYZMIN_UNKZ(:,:),XYZMAX_UNKZ(:,:)

NROW_CV=SIZE(XYZMIN_UNKZ,2)
XYZMIN_UNKZ =  HUGE(1._EB); XYZMAX_UNKZ = -HUGE(1._EB)
MESH_LOOP_01 : DO NM=LOWER_MESH_INDEX,UPPER_MESH_INDEX
   CALL POINT_TO_MESH(NM)
   DO K=1,KBAR
      DO J=1,JBAR
         DO I=1,IBAR
            IF (CCVAR(I,J,K,CC_UNKZ) <= 0 ) CYCLE
            IROW=CCVAR(I,J,K,CC_UNKZ)
            IF (IROW<1 .OR. IROW>NROW_CV) CYCLE
            XLO = X(I-1); XHI = X(I)
            YLO = Y(J-1); YHI = Y(J)
            ZLO = Z(K-1); ZHI = Z(K)
            XYZMIN_UNKZ(IAXIS,IROW) = MIN(XYZMIN_UNKZ(IAXIS,IROW),XLO)
            XYZMIN_UNKZ(JAXIS,IROW) = MIN(XYZMIN_UNKZ(JAXIS,IROW),YLO)
            XYZMIN_UNKZ(KAXIS,IROW) = MIN(XYZMIN_UNKZ(KAXIS,IROW),ZLO)
            XYZMAX_UNKZ(IAXIS,IROW) = MAX(XYZMAX_UNKZ(IAXIS,IROW),XHI)
            XYZMAX_UNKZ(JAXIS,IROW) = MAX(XYZMAX_UNKZ(JAXIS,IROW),YHI)
            XYZMAX_UNKZ(KAXIS,IROW) = MAX(XYZMAX_UNKZ(KAXIS,IROW),ZHI)
         ENDDO
      ENDDO
   ENDDO

   DO ICC=1,MESHES(NM)%N_CUTCELL_MESH
      CC => CUT_CELL(ICC); I = CC%IJK(IAXIS); J = CC%IJK(JAXIS); K = CC%IJK(KAXIS)
      IF (CELL(CELL_INDEX(I,J,K))%SOLID) CYCLE
      DO JCC=1,CC%NCELL
         IROW=CC%UNKZ(JCC)
         IF (IROW<1 .OR. IROW>NROW_CV) CYCLE
         XLO =  HUGE(1._EB); XHI = -HUGE(1._EB)
         YLO =  HUGE(1._EB); YHI = -HUGE(1._EB)
         ZLO =  HUGE(1._EB); ZHI = -HUGE(1._EB)
         DO IFC=1,CC%CCELEM(1,JCC)
            IFACE = CC%CCELEM(IFC+1,JCC)
            FTYPE = CC%FACE_LIST(1,IFACE)
            SELECT CASE (FTYPE)
            CASE (CC_FTYPE_CFGAS,CC_FTYPE_CFINB)
               IFC2   = CC%FACE_LIST(4,IFACE)
               IFACE2 = CC%FACE_LIST(5,IFACE)
               NVFACE = CUT_FACE(IFC2)%CFELEM(1,IFACE2)
               DO IPT=1,NVFACE
                  IVERT = CUT_FACE(IFC2)%CFELEM(IPT+1,IFACE2)
                  XLO = MIN(XLO,CUT_FACE(IFC2)%XYZVERT(IAXIS,IVERT))
                  XHI = MAX(XHI,CUT_FACE(IFC2)%XYZVERT(IAXIS,IVERT))
                  YLO = MIN(YLO,CUT_FACE(IFC2)%XYZVERT(JAXIS,IVERT))
                  YHI = MAX(YHI,CUT_FACE(IFC2)%XYZVERT(JAXIS,IVERT))
                  ZLO = MIN(ZLO,CUT_FACE(IFC2)%XYZVERT(KAXIS,IVERT))
                  ZHI = MAX(ZHI,CUT_FACE(IFC2)%XYZVERT(KAXIS,IVERT))
               ENDDO
            CASE (CC_FTYPE_RCGAS)
               LOWHIGH = CC%FACE_LIST(2,IFACE)
               X1AXIS  = CC%FACE_LIST(3,IFACE)
               ILH     = LOWHIGH - 1
               SELECT CASE (X1AXIS)
               CASE (IAXIS)
                  XLO = MIN(XLO,X(I-1+ILH)); XHI = MAX(XHI,X(I-1+ILH))
                  YLO = MIN(YLO,Y(J-1));     YHI = MAX(YHI,Y(J))
                  ZLO = MIN(ZLO,Z(K-1));     ZHI = MAX(ZHI,Z(K))
               CASE (JAXIS)
                  XLO = MIN(XLO,X(I-1));     XHI = MAX(XHI,X(I))
                  YLO = MIN(YLO,Y(J-1+ILH)); YHI = MAX(YHI,Y(J-1+ILH))
                  ZLO = MIN(ZLO,Z(K-1));     ZHI = MAX(ZHI,Z(K))
               CASE (KAXIS)
                  XLO = MIN(XLO,X(I-1));     XHI = MAX(XHI,X(I))
                  YLO = MIN(YLO,Y(J-1));     YHI = MAX(YHI,Y(J))
                  ZLO = MIN(ZLO,Z(K-1+ILH)); ZHI = MAX(ZHI,Z(K-1+ILH))
               END SELECT
            END SELECT
         ENDDO
         IF (XLO > XHI) THEN
            XLO = X(I-1); XHI = X(I)
            YLO = Y(J-1); YHI = Y(J)
            ZLO = Z(K-1); ZHI = Z(K)
         ENDIF
         XYZMIN_UNKZ(IAXIS,IROW) = MIN(XYZMIN_UNKZ(IAXIS,IROW),XLO)
         XYZMIN_UNKZ(JAXIS,IROW) = MIN(XYZMIN_UNKZ(JAXIS,IROW),YLO)
         XYZMIN_UNKZ(KAXIS,IROW) = MIN(XYZMIN_UNKZ(KAXIS,IROW),ZLO)
         XYZMAX_UNKZ(IAXIS,IROW) = MAX(XYZMAX_UNKZ(IAXIS,IROW),XHI)
         XYZMAX_UNKZ(JAXIS,IROW) = MAX(XYZMAX_UNKZ(JAXIS,IROW),YHI)
         XYZMAX_UNKZ(KAXIS,IROW) = MAX(XYZMAX_UNKZ(KAXIS,IROW),ZHI)
      ENDDO
   ENDDO
ENDDO MESH_LOOP_01

   CALL MPI_ALLREDUCE(MPI_IN_PLACE,XYZMIN_UNKZ,SIZE(XYZMIN_UNKZ),MPI_DOUBLE_PRECISION,MPI_MIN,MPI_COMM_WORLD,IERR)
   CALL MPI_ALLREDUCE(MPI_IN_PLACE,XYZMAX_UNKZ,SIZE(XYZMAX_UNKZ),MPI_DOUBLE_PRECISION,MPI_MAX,MPI_COMM_WORLD,IERR)

RETURN
END SUBROUTINE GET_LINKED_CELLS_BBOX

END SUBROUTINE CC_SET_DATA

! ------------------------------- CC_END_STEP --------------------------------

SUBROUTINE CC_END_STEP(T,DT,DIAGNOSTICS)

REAL(EB),INTENT(IN) :: T,DT
LOGICAL, INTENT(IN) :: DIAGNOSTICS

! Local Variables:
INTEGER :: NM
REAL(EB):: TNOW
LOGICAL :: DUMLOG
REAL(EB):: TNOW2

IF (FREEZE_VELOCITY .OR. SOLID_PHASE_ONLY) RETURN

TNOW = CURRENT_TIME()
TNOW2= TNOW

! Populate Linked velocity arrays:
CALL L2_CROSS_SUMS(MERGE(CC_FV_MOM_VELS,CC_FV_MOM_VEL,PREDICTOR))
DO NM=LOWER_MESH_INDEX,UPPER_MESH_INDEX
   CALL POINT_TO_MESH(NM)
   CALL GET_LINKED_VELOCITIES(NM,PREDICTOR,CMP_FLG=.TRUE.)
ENDDO

! Flux match Cartesian face velocity back to cut-faces:
CALL CC_VELOCITY_CUTFACES(PREDICTOR)

IF (DEBUG_CC_SCALAR_TRANSPORT) THEN
   DUMLOG = DIAGNOSTICS
   IF (PREDICTOR) CALL CC_CHECK_DIVERGENCE(T,DT,.TRUE.)
   IF (CORRECTOR) CALL CC_CHECK_DIVERGENCE(T,DT,.FALSE.)
ELSE
   IF (CORRECTOR .AND. (DIAGNOSTICS .OR. STORE_CUTCELL_DIVERGENCE)) CALL CC_CHECK_DIVERGENCE(T,DT,.FALSE.)
ENDIF

T_USED(14) = T_USED(14) + CURRENT_TIME() - TNOW
IF (TIME_CC_IBM) T_CC_USED(CC_END_STEP_TIME_INDEX) = T_CC_USED(CC_END_STEP_TIME_INDEX) + CURRENT_TIME() - TNOW2
RETURN

END SUBROUTINE CC_END_STEP

! ----------------------------- INIT_CUTCELL_DATA -------------------------------

SUBROUTINE INIT_CUTCELL_DATA(T,DT,FIRST_CALL)

! This routine assumes INITIALIZE_MESH_VARIABLES_1(DT,NM) has already been called.

USE PHYSICAL_FUNCTIONS, ONLY: GET_SPECIFIC_GAS_CONSTANT
USE MATH_FUNCTIONS, ONLY: EVALUATE_RAMP
USE TYPES, ONLY: INITIALIZATION_TYPE, INITIALIZATION
USE MPI_F08
REAL(EB), INTENT(IN) :: T, DT
LOGICAL, INTENT(IN)  :: FIRST_CALL
! Local Variables:
INTEGER :: NM,I,J,K,N,ICC,JCC,X1AXIS,NFACE,ICF,JCF,IF_,IG
TYPE(INITIALIZATION_TYPE), POINTER :: IN
REAL(EB) TMP_CC,RHO_CC,AREAT,VEL_CF !,Z_CC,TMP_0_CC,P_0_CC
REAL(EB), ALLOCATABLE, DIMENSION(:) :: ZZ_CC
! Init-only control-volume scratch arrays (auto-deallocated on return):
REAL(EB), ALLOCATABLE, DIMENSION(:) :: ZCEN_CV,XCEN_CV,YCEN_CV,TMP_0_CV,TMP_CV,RHO_CV,VOL_CV,RSUM_CV
REAL(EB), ALLOCATABLE, DIMENSION(:,:) :: ZZ_ROW
REAL(EB), DIMENSION(N_TRACKED_SPECIES) :: VF
INTEGER :: IW,IROW_LOC,NROW_CV,IERR,NS
TYPE(CC_FV_TYPE), POINTER :: FV

REAL(EB) :: TNOW

TNOW = CURRENT_TIME()

   NROW_CV=MAX(1,NUNKZ_TOTAL)
ALLOCATE( ZZ_CC(1:N_TOTAL_SCALARS) )
ALLOCATE(ZCEN_CV(1:NROW_CV),XCEN_CV(1:NROW_CV),YCEN_CV(1:NROW_CV),TMP_0_CV(1:NROW_CV), &
         TMP_CV(1:NROW_CV),RHO_CV(1:NROW_CV),VOL_CV(1:NROW_CV))

! Loop Meshes:
! Get Z location of linked cells centroids, then P_0_CV for the control volumes:
ZCEN_CV=0._EB; XCEN_CV=0._EB; YCEN_CV=0._EB; VOL_CV=0._EB
MESH_LOOP_0 : DO NM=LOWER_MESH_INDEX,UPPER_MESH_INDEX

   CALL POINT_TO_MESH(NM)

   DO K=1,KBAR
      DO J=1,JBAR
         DO I=1,IBAR
            IF (CCVAR(I,J,K,CC_UNKZ) <= 0) CYCLE
            IROW_LOC=CCVAR(I,J,K,CC_UNKZ)
            IF (IROW_LOC<1 .OR. IROW_LOC>NROW_CV) CYCLE
            VOL_CV(IROW_LOC)=VOL_CV(IROW_LOC)+DX(I)*DY(J)*DZ(K)
            XCEN_CV(IROW_LOC) = XCEN_CV(IROW_LOC) + XC(I)*DX(I)*DY(J)*DZ(K)
            YCEN_CV(IROW_LOC) = YCEN_CV(IROW_LOC) + YC(J)*DX(I)*DY(J)*DZ(K)
            ZCEN_CV(IROW_LOC) = ZCEN_CV(IROW_LOC) + ZC(K)*DX(I)*DY(J)*DZ(K)
         ENDDO
      ENDDO
   ENDDO

   DO ICC=1,MESHES(NM)%N_CUTCELL_MESH
      CC => CUT_CELL(ICC); IF (CELL(CELL_INDEX(CC%IJK(IAXIS),CC%IJK(JAXIS),CC%IJK(KAXIS)))%SOLID) CYCLE
      DO JCC=1,CC%NCELL
         IROW_LOC=CC%UNKZ(JCC)
         IF (IROW_LOC<1 .OR. IROW_LOC>NROW_CV) CYCLE
         VOL_CV(IROW_LOC)=VOL_CV(IROW_LOC)+CC%VOLUME(JCC)
         XCEN_CV(IROW_LOC) = XCEN_CV(IROW_LOC) + CC%XYZCEN(IAXIS,JCC)*CC%VOLUME(JCC)
         YCEN_CV(IROW_LOC) = YCEN_CV(IROW_LOC) + CC%XYZCEN(JAXIS,JCC)*CC%VOLUME(JCC)
         ZCEN_CV(IROW_LOC) = ZCEN_CV(IROW_LOC) + CC%XYZCEN(KAXIS,JCC)*CC%VOLUME(JCC)
      ENDDO
   ENDDO
ENDDO MESH_LOOP_0
   CALL MPI_ALLREDUCE(MPI_IN_PLACE,VOL_CV,SIZE(VOL_CV),MPI_DOUBLE_PRECISION,MPI_SUM,MPI_COMM_WORLD,IERR)
   CALL MPI_ALLREDUCE(MPI_IN_PLACE,XCEN_CV,SIZE(XCEN_CV),MPI_DOUBLE_PRECISION,MPI_SUM,MPI_COMM_WORLD,IERR)
   CALL MPI_ALLREDUCE(MPI_IN_PLACE,YCEN_CV,SIZE(YCEN_CV),MPI_DOUBLE_PRECISION,MPI_SUM,MPI_COMM_WORLD,IERR)
   CALL MPI_ALLREDUCE(MPI_IN_PLACE,ZCEN_CV,SIZE(ZCEN_CV),MPI_DOUBLE_PRECISION,MPI_SUM,MPI_COMM_WORLD,IERR)
DO IROW_LOC=1,NROW_CV
   IF (VOL_CV(IROW_LOC)<=TWO_EPSILON_EB) CYCLE
   XCEN_CV(IROW_LOC)=XCEN_CV(IROW_LOC)/VOL_CV(IROW_LOC)
   YCEN_CV(IROW_LOC)=YCEN_CV(IROW_LOC)/VOL_CV(IROW_LOC)
   ZCEN_CV(IROW_LOC)=ZCEN_CV(IROW_LOC)/VOL_CV(IROW_LOC)
ENDDO

! Reference (hydrostatic background) state per control volume, sampled at the CV centroid.
! Used as the buoyancy/pressure baseline (CV%RHO_0, P_BAR_CV). Keep ambient/stratification.
P_0_CV(:)  = P_INF
TMP_0_CV(:)= TMPA
IF (STRATIFICATION) THEN
   DO IROW_LOC=1,NROW_CV
      P_0_CV(IROW_LOC)  = EVALUATE_RAMP(ZCEN_CV(IROW_LOC),I_RAMP_P0_Z)
      TMP_0_CV(IROW_LOC)= TMPA*EVALUATE_RAMP(ZCEN_CV(IROW_LOC),I_RAMP_TMP0_Z)
   ENDDO
ENDIF
DO IROW_LOC=1,NROW_CV
   RHO_0_CV(IROW_LOC) = P_0_CV(IROW_LOC)/(TMP_0_CV(IROW_LOC)*RSUM0)
ENDDO

! Actual initial state per control volume: start from the hydrostatic background (so the
! stratification/no-INIT case is unchanged), then override with any &INIT region that
! contains the CV centroid, mirroring the cell-center logic in INITIALIZE_MESH_VARIABLES_1.
! Species use the same centroid test, so the row density is the equation of state for that
! composition. A row that straddles a boundary takes the region that contains its centroid.
TMP_CV(:) = TMP_0_CV(:)
ALLOCATE(ZZ_ROW(N_TRACKED_SPECIES,NROW_CV),RSUM_CV(NROW_CV))
DO NS=1,N_TRACKED_SPECIES
   ZZ_ROW(NS,:) = SPECIES_MIXTURE(NS)%ZZ0
ENDDO
RSUM_CV(:) = RSUM0
DO N=1,N_INIT
   IN => INITIALIZATION(N)
   IF (IN%NODE_ID/='null') CYCLE
   IF (.NOT.IN%ADJUST_INITIAL_CONDITIONS) CYCLE
   IF (IN%RAMP_TMP_Z_INDEX<=0 .AND. IN%TEMPERATURE<=0._EB .AND. &
       .NOT.IN%MASS_FRACTIONS_SPECIFIED .AND. .NOT.IN%VOLUME_FRACTIONS_SPECIFIED) CYCLE
   DO IROW_LOC=1,NROW_CV
      IF (XCEN_CV(IROW_LOC)<IN%X1 .OR. XCEN_CV(IROW_LOC)>IN%X2 .OR. &
          YCEN_CV(IROW_LOC)<IN%Y1 .OR. YCEN_CV(IROW_LOC)>IN%Y2 .OR. &
          ZCEN_CV(IROW_LOC)<IN%Z1 .OR. ZCEN_CV(IROW_LOC)>IN%Z2) CYCLE
      IF (IN%VOLUME_FRACTIONS_SPECIFIED) THEN
         VF = 0._EB
         DO NS=2,N_TRACKED_SPECIES
            IF (IN%RAMP_VF_Z_INDEX(NS)>0) THEN
               VF(NS) = EVALUATE_RAMP(ZCEN_CV(IROW_LOC),IN%RAMP_VF_Z_INDEX(NS))
            ELSE
               VF(NS) = IN%VOLUME_FRACTION(NS)
            ENDIF
         ENDDO
         VF(1) = 1._EB - SUM(VF)
         ZZ_ROW(1:N_TRACKED_SPECIES,IROW_LOC) = VF(1:N_TRACKED_SPECIES)*SPECIES_MIXTURE(1:N_TRACKED_SPECIES)%MW / &
            SUM(VF(1:N_TRACKED_SPECIES)*SPECIES_MIXTURE(1:N_TRACKED_SPECIES)%MW)
      ELSEIF (IN%MASS_FRACTIONS_SPECIFIED) THEN
         DO NS=2,N_TRACKED_SPECIES
            IF (IN%RAMP_MF_Z_INDEX(NS)>0) THEN
               ZZ_ROW(NS,IROW_LOC) = EVALUATE_RAMP(ZCEN_CV(IROW_LOC),IN%RAMP_MF_Z_INDEX(NS))
            ELSE
               ZZ_ROW(NS,IROW_LOC) = IN%MASS_FRACTION(NS)
            ENDIF
         ENDDO
         ZZ_ROW(1,IROW_LOC) = 1._EB - SUM(ZZ_ROW(2:N_TRACKED_SPECIES,IROW_LOC))
      ENDIF
      IF (IN%MASS_FRACTIONS_SPECIFIED .OR. IN%VOLUME_FRACTIONS_SPECIFIED) &
         CALL GET_SPECIFIC_GAS_CONSTANT(ZZ_ROW(1:N_TRACKED_SPECIES,IROW_LOC),RSUM_CV(IROW_LOC))
      IF (IN%RAMP_TMP_Z_INDEX>0) THEN
         TMP_CV(IROW_LOC) = TMPM + EVALUATE_RAMP(ZCEN_CV(IROW_LOC),IN%RAMP_TMP_Z_INDEX)
      ELSEIF (IN%TEMPERATURE>0._EB) THEN
         TMP_CV(IROW_LOC) = IN%TEMPERATURE
      ENDIF
   ENDDO
ENDDO
DO IROW_LOC=1,NROW_CV
   RHO_CV(IROW_LOC) = P_0_CV(IROW_LOC)/(TMP_CV(IROW_LOC)*RSUM_CV(IROW_LOC))
ENDDO

MESH_LOOP_1 : DO NM=LOWER_MESH_INDEX,UPPER_MESH_INDEX

   CALL POINT_TO_MESH(NM)
   FV=>MESHES(NM)%FV

   ! Default initialization:
   IF(.NOT.RESTART .AND. PERIODIC_TEST/=11 .AND. PERIODIC_TEST/=7) THEN
      DO K=1,KBAR ! Linked cells get initialized to the control volume actual TMP and RHO
         DO J=1,JBAR
            DO I=1,IBAR
               IF(CCVAR(I,J,K,CC_UNKZ) <= 0) CYCLE
               IROW_LOC=CCVAR(I,J,K,CC_UNKZ)
               IF (IROW_LOC<1 .OR. IROW_LOC>NROW_CV) CYCLE
               TMP(I,J,K) = TMP_CV(IROW_LOC)
               RHO(I,J,K) = RHO_CV(IROW_LOC)
               RHOS(I,J,K)= RHO_CV(IROW_LOC)
            ENDDO
         ENDDO
      ENDDO
   ENDIF

   ! Cut-cells inherit underlying Cartesian cell values of rho,T,Z, etc.:
   DO ICC=1,MESHES(NM)%N_CUTCELL_MESH
      CC => CUT_CELL(ICC);  I=CC%IJK(IAXIS); J=CC%IJK(JAXIS);  K=CC%IJK(KAXIS); IF (CELL(CELL_INDEX(I,J,K))%SOLID) CYCLE
      TMP_CC = TMP(I,J,K)
      RHO_CC = RHO(I,J,K)
      ZZ_CC(1:N_TOTAL_SCALARS) = ZZ(I,J,K,1:N_TOTAL_SCALARS)
      DO JCC=1,CC%NCELL
         IROW_LOC=CC%UNKZ(JCC)
         IF (IROW_LOC<1 .OR. IROW_LOC>NROW_CV) CYCLE
         MESHES(NM)%FV%CV%RHO_0(CC%IG(JCC))=RHO_0_CV(IROW_LOC)
         IF (.NOT.RESTART .AND. PERIODIC_TEST/=11 .AND. PERIODIC_TEST/=7) THEN
           TMP_CC = TMP_CV(IROW_LOC)
           RHO_CC = RHO_CV(IROW_LOC)
         ENDIF

         IG = CC%IG(JCC); IF (IG<1) CYCLE
         MESHES(NM)%FV%CV%MIX_TIME(IG)=DT
         FV%CV%TMP(IG)=TMP_CC
         CALL GET_SPECIFIC_GAS_CONSTANT(ZZ_CC(1:N_TRACKED_SPECIES),FV%CV%RSUM(IG))
         FV%CV%RHO(IG)=RHO_CC; FV%CV%RHOS(IG)=RHO_CC
         FV%CV%ZZ(1:N_TOTAL_SCALARS,IG)=ZZ_CC(1:N_TOTAL_SCALARS)
         FV%CV%ZZS(1:N_TRACKED_SPECIES,IG)=ZZ_CC(1:N_TRACKED_SPECIES)
         FV%CV%D(IG)        = 0._EB
         FV%CV%DS(IG)       = 0._EB
         FV%CV%D_SOURCE(IG) = 0._EB
         FV%CV%Q(IG)        = 0._EB
         FV%CV%QR(IG)       = 0._EB
         FV%CV%M_DOT_PPP(:,IG) = 0._EB
         IF(RESTART) THEN
            FV%CV%D(IG)        = D(I,J,K)/CC%ALPHA_CC
            IF (ALLOCATED(MESHES(NM)%D_SOURCE)) FV%CV%D_SOURCE(IG) = D_SOURCE(I,J,K)/CC%ALPHA_CC
            FV%CV%Q(IG)        = Q(I,J,K)/CC%ALPHA_CC
            FV%CV%QR(IG)       = QR(I,J,K) ! Not needed for radiation.
            IF (ALLOCATED(MESHES(NM)%M_DOT_PPP)) FV%CV%M_DOT_PPP(1:N_TRACKED_SPECIES,IG) = &
                                                    M_DOT_PPP(I,J,K,1:N_TRACKED_SPECIES)/CC%ALPHA_CC
         ENDIF
      ENDDO
      IF (ALLOCATED(MESHES(NM)%D_SOURCE)) THEN
         D_SOURCE(I,J,K) = 0._EB
         M_DOT_PPP(I,J,K,1:N_TRACKED_SPECIES) = 0._EB
      ENDIF
   ENDDO


   ! Init guardcell cut-cells:
   DO ICC=MESHES(NM)%N_CUTCELL_MESH+1,MESHES(NM)%N_CUTCELL_MESH+MESHES(NM)%N_GCCUTCELL_MESH
      CC => CUT_CELL(ICC);  I = CC%IJK(IAXIS); J = CC%IJK(JAXIS);  K = CC%IJK(KAXIS)
      IF(I < 0 .OR. I > IBP1) CYCLE
      IF(J < 0 .OR. J > JBP1) CYCLE
      IF(K < 0 .OR. K > KBP1) CYCLE
      TMP_CC = TMP(I,J,K)
      RHO_CC = RHO(I,J,K)
      ZZ_CC(1:N_TOTAL_SCALARS) = ZZ(I,J,K,1:N_TOTAL_SCALARS)
      DO JCC=1,CC%NCELL
         IG = CC%IG(JCC); IF (IG<1) CYCLE
         FV%CV%TMP(IG)=TMP_CC
         CALL GET_SPECIFIC_GAS_CONSTANT(ZZ_CC(1:N_TRACKED_SPECIES),FV%CV%RSUM(IG))
         FV%CV%RHO(IG)=RHO_CC; FV%CV%RHOS(IG)=RHO_CC
         FV%CV%ZZ(1:N_TOTAL_SCALARS,IG)=ZZ_CC(1:N_TOTAL_SCALARS)
         FV%CV%ZZS(1:N_TRACKED_SPECIES,IG)=ZZ_CC(1:N_TRACKED_SPECIES)
         FV%CV%D(IG)  = 0._EB
         FV%CV%DS(IG) = 0._EB
         IF (RESTART) FV%CV%D(IG) = D(I,J,K)/CC%ALPHA_CC
      ENDDO
      IF (ALLOCATED(MESHES(NM)%D_SOURCE)) THEN
         D_SOURCE(I,J,K) = 0._EB
         M_DOT_PPP(I,J,K,1:N_TRACKED_SPECIES) = 0._EB
      ENDIF
   ENDDO

   ! Gasphase Cut-faces inherit underlying Cartesian face values of Velocity (flux matched or not):
   PERIODIC_TEST_COND : IF (PERIODIC_TEST /= 21 .AND. PERIODIC_TEST /= 22 .AND. PERIODIC_TEST /= 24) THEN

      ! First GASPHASe cut-faces:
      CUTFACE_LOOP : DO ICF=1,MESHES(NM)%N_CUTFACE_MESH+MESHES(NM)%N_GCCUTFACE_MESH
         NFACE  = CUT_FACE(ICF)%NFACE
         IF (CUT_FACE(ICF)%STATUS /= CC_GASPHASE) CYCLE
         I      = CUT_FACE(ICF)%IJK(IAXIS); IF(I<0 .OR. I>IBP1) CYCLE
         J      = CUT_FACE(ICF)%IJK(JAXIS); IF(J<0 .OR. J>JBP1) CYCLE
         K      = CUT_FACE(ICF)%IJK(KAXIS); IF(K<0 .OR. K>KBP1) CYCLE
         X1AXIS = CUT_FACE(ICF)%IJK(KAXIS+1)

         AREAT  = SUM( CUT_FACE(ICF)%AREA(1:NFACE) )

         ! Flux matched U to cut-face centroids, they all get same velocity:
         IF(RESTART) THEN
            SELECT CASE(X1AXIS)
            CASE(IAXIS); VEL_CF = (DY(J)*DZ(K))/(AREAT+TWENTY_EPSILON_EB) * U(I,J,K)
            CASE(JAXIS); VEL_CF = (DX(I)*DZ(K))/(AREAT+TWENTY_EPSILON_EB) * V(I,J,K)
            CASE(KAXIS); VEL_CF = (DX(I)*DY(J))/(AREAT+TWENTY_EPSILON_EB) * W(I,J,K)
            END SELECT
         ELSE
            SELECT CASE(X1AXIS)
            CASE(IAXIS); VEL_CF = U(I,J,K)
            CASE(JAXIS); VEL_CF = V(I,J,K)
            CASE(KAXIS); VEL_CF = W(I,J,K)
            END SELECT
         ENDIF

         CUT_FACE(ICF)%VEL_CF        = VEL_CF
         DO JCF=1,NFACE
            IF_=MESHES(NM)%CUT_FACE(ICF)%FC(JCF)
            FV%FACE%VEL(IF_)=VEL_CF; FV%FACE%VELS(IF_)=VEL_CF
         ENDDO
      ENDDO CUTFACE_LOOP

      ! Push cut-face velocities down to cartesian velocities:
      DO ICF=1,MESHES(NM)%N_CUTFACE_MESH+MESHES(NM)%N_GCCUTFACE_MESH
         NFACE  = CUT_FACE(ICF)%NFACE
         IF (CUT_FACE(ICF)%STATUS /= CC_GASPHASE) CYCLE
         I      = CUT_FACE(ICF)%IJK(IAXIS); IF(I<0 .OR. I>IBP1) CYCLE
         J      = CUT_FACE(ICF)%IJK(JAXIS); IF(J<0 .OR. J>JBP1) CYCLE
         K      = CUT_FACE(ICF)%IJK(KAXIS); IF(K<0 .OR. K>KBP1) CYCLE
         X1AXIS = CUT_FACE(ICF)%IJK(KAXIS+1)
         VEL_CF = CC_FV_CUTFACE_MOM_AREA(NM,ICF,CC_FV_MOM_VEL)
         SELECT CASE(X1AXIS)
         CASE(IAXIS); U(I,J,K) = VEL_CF/(DY(J)*DZ(K)); CUT_FACE(ICF)%VEL_CRT=U(I,J,K)
         CASE(JAXIS); V(I,J,K) = VEL_CF/(DX(I)*DZ(K)); CUT_FACE(ICF)%VEL_CRT=V(I,J,K)
         CASE(KAXIS); W(I,J,K) = VEL_CF/(DX(I)*DY(J)); CUT_FACE(ICF)%VEL_CRT=W(I,J,K)
         END SELECT
      ENDDO

      ! INBOUNDARY cut-faces keep their allocation 0._EB velocity. The solid normal velocity is
      ! B1%U_NORMAL, set in CFACE_PREDICT_NORMAL_VELOCITY.

   ENDIF PERIODIC_TEST_COND

   ! Force velocities in CC_SOLID faces to zero
   WHERE(FCVAR(0:IBP1,0:JBP1,0:KBP1,CC_FGSC,IAXIS)==CC_SOLID) U(0:IBP1,0:JBP1,0:KBP1) = 0._EB
   WHERE(FCVAR(0:IBP1,0:JBP1,0:KBP1,CC_FGSC,JAXIS)==CC_SOLID) V(0:IBP1,0:JBP1,0:KBP1) = 0._EB
   WHERE(FCVAR(0:IBP1,0:JBP1,0:KBP1,CC_FGSC,KAXIS)==CC_SOLID) W(0:IBP1,0:JBP1,0:KBP1) = 0._EB
   US = U; VS = V; WS = W

   ! External mesh CFACEs initialize P1 BCs:
   DO ICF=1,N_EXTERNAL_CFACE_CELLS+N_INTWALL_CFACE_CELLS
      CFA  => CFACE(ICF)
      IW = CUT_FACE(CFA%CUT_FACE_IND1)%IWC
      CALL INIT_CFACE_CELL(NM,CFA%CUT_FACE_IND1,CFA%CUT_FACE_IND2,ICF,CFA%SURF_INDEX,INTEGER_THREE,&
                           IS_INB=.FALSE.,IW=IW)
   ENDDO

   ! Geometry boundary CFACES initialize P1 BCs:
   IF(.NOT.RESTART) THEN ! Only if not restarting, otherwise the Boundary P1 vars are read from restart file.
      DO ICF=INTERNAL_CFACE_CELLS_LB+1,INTERNAL_CFACE_CELLS_LB+N_INTERNAL_CFACE_CELLS
         CFA  => CFACE(ICF)
         CALL INIT_CFACE_CELL(NM,CFA%CUT_FACE_IND1,CFA%CUT_FACE_IND2,ICF,CFA%SURF_INDEX,INTEGER_THREE,IS_INB=.TRUE.)
      ENDDO
   ENDIF

ENDDO MESH_LOOP_1

DEALLOCATE( ZZ_CC)
IF(((.NOT.RESTART .AND. FIRST_CALL) .OR. (RESTART .AND. .NOT.FIRST_CALL)) .AND. N_GEOMETRY>0) DEALLOCATE(FDS_AREA_GEOM)

! Populate Linked velocity arrays:
CALL L2_CROSS_SUMS(CC_FV_MOM_VEL)
DO NM=LOWER_MESH_INDEX,UPPER_MESH_INDEX
   CALL POINT_TO_MESH(NM)
   CALL GET_LINKED_VELOCITIES(NM,APPLY_TO_ESTIMATED_VARIABLES=.FALSE.,CMP_FLG=.TRUE.)
ENDDO

! Flux match Cartesian face velocity back to cut-faces:
CALL CC_VELOCITY_CUTFACES(APPLY_TO_ESTIMATED_VARIABLES=.FALSE.)


CALL MESH_CC_EXCHANGE(1)
CALL MESH_CC_EXCHANGE(4)
CALL MESH_CC_EXCHANGE(6)

CALL CC_H_INTERP
CALL CC_RHO0W_INTERP

! Recompute initial CC_VELOCITY_BC with RESTART data if needed
IF (RESTART .AND. .NOT. FIRST_CALL) THEN
   DO NM=LOWER_MESH_INDEX,UPPER_MESH_INDEX
      CALL POINT_TO_MESH(NM)
      DRAG_UVWMAX = 0._EB
      CALL CC_VELOCITY_BC(T,NM,APPLY_TO_ESTIMATED_VARIABLES=.FALSE.,DO_IBEDGES=.TRUE.)
   ENDDO
ENDIF

! Check divergence of initial velocity field:
IF(GET_CUTCELLS_VERBOSE) CALL CC_CHECK_DIVERGENCE(T,DT,.FALSE.)

T_USED(14) = T_USED(14) + CURRENT_TIME() - TNOW
IF (TIME_CC_IBM) T_CC_USED(INIT_CUTCELL_DATA_TIME_INDEX) = T_CC_USED(INIT_CUTCELL_DATA_TIME_INDEX) + CURRENT_TIME() - TNOW
RETURN
END SUBROUTINE INIT_CUTCELL_DATA


! ------------------------------ SET_EXIMDIFFLX_3D ------------------------------

SUBROUTINE SET_EXIMDIFFLX_3D(NM,RHO_D_DZDX,RHO_D_DZDY,RHO_D_DZDZ)

INTEGER, INTENT(IN) :: NM
REAL(EB), INTENT(IN), POINTER, DIMENSION(:,:,:,:) :: RHO_D_DZDX,RHO_D_DZDY,RHO_D_DZDZ

! Local Variables:
INTEGER :: I,J,K,X1AXIS,IFACE,IF_
TYPE(CC_REGFACEZ_TYPE),  POINTER, DIMENSION(:) :: REGFACE_Z
TYPE(CC_FV_TYPE), POINTER :: FV

FV => MESHES(NM)%FV

! First, set all diffusive fluxes to zero on CC_SOLID faces:
! IAXIS:
X1AXIS = IAXIS
DO K=1,MESHES(NM)%KBAR
   DO J=1,MESHES(NM)%JBAR
      DO I=0,MESHES(NM)%IBAR
         IF (MESHES(NM)%FCVAR(I,J,K,CC_FGSC,X1AXIS) /= CC_SOLID ) CYCLE
         RHO_D_DZDX(I,J,K,1:N_TOTAL_SCALARS) = 0._EB
      ENDDO
   ENDDO
ENDDO
! JAXIS:
X1AXIS = JAXIS
DO K=1,MESHES(NM)%KBAR
   DO J=0,MESHES(NM)%JBAR
      DO I=1,MESHES(NM)%IBAR
         IF (MESHES(NM)%FCVAR(I,J,K,CC_FGSC,X1AXIS) /= CC_SOLID ) CYCLE
         RHO_D_DZDY(I,J,K,1:N_TOTAL_SCALARS) = 0._EB
      ENDDO
   ENDDO
ENDDO
! KAXIS:
X1AXIS = KAXIS
DO K=0,MESHES(NM)%KBAR
   DO J=1,MESHES(NM)%JBAR
      DO I=1,MESHES(NM)%IBAR
         IF (MESHES(NM)%FCVAR(I,J,K,CC_FGSC,X1AXIS) /= CC_SOLID ) CYCLE
         RHO_D_DZDZ(I,J,K,1:N_TOTAL_SCALARS) = 0._EB
      ENDDO
   ENDDO
ENDDO

! Cartesian diffusive flux does not survive: SWORK1-3 are later overwritten by FX_ZZ.
AXIS_DO : DO X1AXIS = IAXIS,KAXIS
   SELECT CASE(X1AXIS)
   CASE(IAXIS)
      REGFACE_Z => CC_REGFACE_IAXIS_Z
   CASE(JAXIS)
      REGFACE_Z => CC_REGFACE_JAXIS_Z
   CASE(KAXIS)
      REGFACE_Z => CC_REGFACE_KAXIS_Z
   END SELECT
   IFACE_DO : DO IFACE=1,MESHES(NM)%CC_NREGFACE_Z(X1AXIS)
      IF_ = REGFACE_Z(IFACE)%FC
      I  = REGFACE_Z(IFACE)%IJK(IAXIS)
      J  = REGFACE_Z(IFACE)%IJK(JAXIS)
      K  = REGFACE_Z(IFACE)%IJK(KAXIS)
      SELECT CASE(X1AXIS)
      CASE(IAXIS)
         FV%FACE%DIFF_FLUX(1:N_TOTAL_SCALARS,IF_) = RHO_D_DZDX(I,J,K,1:N_TOTAL_SCALARS)
      CASE(JAXIS)
         FV%FACE%DIFF_FLUX(1:N_TOTAL_SCALARS,IF_) = RHO_D_DZDY(I,J,K,1:N_TOTAL_SCALARS)
      CASE(KAXIS)
         FV%FACE%DIFF_FLUX(1:N_TOTAL_SCALARS,IF_) = RHO_D_DZDZ(I,J,K,1:N_TOTAL_SCALARS)
      END SELECT
   ENDDO IFACE_DO
ENDDO AXIS_DO

RETURN
END SUBROUTINE SET_EXIMDIFFLX_3D


! -------------------------------- FINISH_CC ---------------------------------

SUBROUTINE FINISH_CC

USE MPI_F08

! Local variables:
INTEGER :: I, TLB, TUB, LU_TCC, IERR
CHARACTER(MESSAGE_LENGTH) :: CC_CPU_FILE
REAL(EB), ALLOCATABLE, DIMENSION(:) :: T_CC_USED_MIN, T_CC_USED_MAX, T_CC_USED_MEA
CHARACTER(30) :: FRMT

IF (TIME_CC_IBM) THEN
   TLB = LBOUND(T_CC_USED,DIM=1)
   TUB = UBOUND(T_CC_USED,DIM=1)
   ALLOCATE(T_CC_USED_MIN(TLB:TUB),T_CC_USED_MAX(TLB:TUB),T_CC_USED_MEA(TLB:TUB))
   IF (N_MPI_PROCESSES > 1) THEN
      CALL MPI_ALLREDUCE(T_CC_USED(TLB) , T_CC_USED_MIN(TLB) , TUB-TLB+1, MPI_DOUBLE_PRECISION, MPI_MIN, MPI_COMM_WORLD, IERR)
      CALL MPI_ALLREDUCE(T_CC_USED(TLB) , T_CC_USED_MAX(TLB) , TUB-TLB+1, MPI_DOUBLE_PRECISION, MPI_MAX, MPI_COMM_WORLD, IERR)
      CALL MPI_ALLREDUCE(T_CC_USED(TLB) , T_CC_USED_MEA(TLB) , TUB-TLB+1, MPI_DOUBLE_PRECISION, MPI_SUM, MPI_COMM_WORLD, IERR)
      T_CC_USED_MEA = T_CC_USED_MEA / REAL(N_MPI_PROCESSES,EB)
   ELSE
      T_CC_USED_MIN(TLB:TUB) = T_CC_USED(TLB:TUB)
      T_CC_USED_MAX(TLB:TUB) = T_CC_USED(TLB:TUB)
      T_CC_USED_MEA(TLB:TUB) = T_CC_USED(TLB:TUB)
   ENDIF
   IF (MY_RANK==0) THEN
      WRITE(CC_CPU_FILE,'(A,A)') TRIM(CHID),'_cc_cpu.csv'
      LU_TCC = GET_FILE_NUMBER()
      OPEN(LU_TCC,FILE=TRIM(CC_CPU_FILE),STATUS='UNKNOWN')
      WRITE(LU_TCC,'(A,A,A)') 'CCCOMPUTE_RADIATION, CC_DENSITY, CC_VELOCITY_FLUX, CC_COMPUTE_VISCOSITY, ',&
                              'CC_INTERP_FACE_VEL, CC_DIVERGENCE_PART_1, CC_END_STEP, CC_TARGET_VELOCITY, ',&
                              'CC_NO_FLUX, CC_COMPUTE_VELOCITY_ERROR, MESH_CC_EXCHANGE (s)'
      WRITE(FRMT,'(A,I2.2,A)') '(',MESH_CC_EXCHANGE_TIME_INDEX-CCCOMPUTE_RADIATION_TIME_INDEX+1,'(",",ES10.3))'
      WRITE(LU_TCC,FRMT) (T_CC_USED_MIN(I),I=CCCOMPUTE_RADIATION_TIME_INDEX,MESH_CC_EXCHANGE_TIME_INDEX)
      WRITE(LU_TCC,FRMT) (T_CC_USED_MAX(I),I=CCCOMPUTE_RADIATION_TIME_INDEX,MESH_CC_EXCHANGE_TIME_INDEX)
      WRITE(LU_TCC,FRMT) (T_CC_USED_MEA(I),I=CCCOMPUTE_RADIATION_TIME_INDEX,MESH_CC_EXCHANGE_TIME_INDEX)
      CLOSE(LU_TCC)
   ENDIF
   DEALLOCATE(T_CC_USED_MIN,T_CC_USED_MAX,T_CC_USED_MEA)
ENDIF

! Release Requests:
DO I=1,N_REQ11  ; CALL MPI_REQUEST_FREE(REQ11(I) ,IERR) ; ENDDO
DO I=1,N_REQ12  ; CALL MPI_REQUEST_FREE(REQ12(I) ,IERR) ; ENDDO
DO I=1,N_REQ13  ; CALL MPI_REQUEST_FREE(REQ13(I) ,IERR) ; ENDDO

RETURN
END SUBROUTINE FINISH_CC


! -------------------------- CC_DIVERGENCE_PART_1 --------------------------

SUBROUTINE CC_DIVERGENCE_PART_1(T,DT,NM)

USE PHYSICAL_FUNCTIONS, ONLY: GET_SPECIFIC_HEAT,GET_SENSIBLE_ENTHALPY_Z, &
                              GET_SENSIBLE_ENTHALPY,GET_VISCOSITY,GET_MOLECULAR_WEIGHT
USE MANUFACTURED_SOLUTIONS, ONLY: UF_MMS,WF_MMS,VD2D_MMS_Z_SRC

REAL(EB), INTENT(IN) :: T,DT
INTEGER,  INTENT(IN) :: NM
! Recompute divergence terms in cut-cell region and surrounding cells.
! Use velocity divergence equivalence to define divergence on cut-cell underlying Cartesian cells.

! Local Variables:
INTEGER :: N,I,J,K,ICC,JCC,ICF,ICV,IF_,IG,L
REAL(EB), POINTER, DIMENSION(:,:,:) :: DP,DPVOL,RHOP,RTRM,CP,R_H_G,U_DOT_DEL_RHO_Z_VOL
REAL(EB), POINTER, DIMENSION(:,:) :: PBAR_P
REAL(EB), POINTER, DIMENSION(:,:,:,:) :: ZZP
REAL(EB) :: RDT,CCM1,CCP1,IDX,H_S,TNOW,RHOPV(-2:1),TMPV(-1:0),PRFCT,PRFCTV, &
            CPV(-1:0)
REAL(EB), ALLOCATABLE, DIMENSION(:) :: ZZ_GET
REAL(EB), POINTER, DIMENSION(:,:,:) :: UU,VV,WW
TYPE(SPECIES_MIXTURE_TYPE), POINTER :: SM
TYPE(CC_FV_TYPE), POINTER :: FV

REAL(EB) :: DUMMY,R_H_G_CC,RTRM_CC
TYPE(MESH_TYPE), POINTER :: M

LOGICAL, PARAMETER :: DO_CONDUCTION_HEAT_FLUX=.TRUE.
INTEGER :: DIFFHFLX_IND, JFLX_IND

LOGICAL, PARAMETER :: SET_DIV_TO_ZERO  = .FALSE.
LOGICAL, PARAMETER :: SET_CCDIV_TO_ZERO= .FALSE.


! Pressure sums re-integration vars:
INTEGER :: IW

! Shunn MMS test case vars:
REAL(EB) :: XHAT, ZHAT, Q_Z, TT

! Dummy on T:
DUMMY = T

! Check whether to skip this routine

IF (SOLID_PHASE_ONLY) RETURN

TNOW=CURRENT_TIME()

DIFFHFLX_IND = LOW_IND  ! -rho Da Grad(Za)
JFLX_IND     = LOW_IND

CALL POINT_TO_MESH(NM)
M=>MESHES(NM)
FV=>M%FV

RDT = 1._EB/DT

SELECT CASE(PREDICTOR)
   CASE(.TRUE.)
      DP     => DS
      PBAR_P => PBAR_S
      RHOP   => RHOS
      PRFCT  = 0._EB ! Use star cut-cell quantities.
   CASE(.FALSE.)
      DP     => D
      PBAR_P => PBAR
      RHOP   => RHO
      PRFCT  = 1._EB ! Use end of step cut-cell quantities.
END SELECT


R_PBAR = 1._EB/PBAR_P
DPVOL  => DP
RTRM   => WORK1

! Set DP to zero in Cartesian cells of type: CC_SOLID, CC_CUTCFE, and CC_GASPHASE where CC_UNKZ > 0:
DO K=1,KBAR
   DO J=1,JBAR
      DO I=1,IBAR
         IF ((CCVAR(I,J,K,CC_CGSC) == CC_GASPHASE) .AND. (CCVAR(I,J,K,CC_UNKZ) <= 0)) CYCLE
         DPVOL(I,J,K) = 0._EB
         DEL_RHO_D_DEL_Z(I,J,K,1:N_TOTAL_SCALARS) = 0._EB
      ENDDO
   ENDDO
ENDDO
! Members: regular cells with a scalar row (TH_REG) and cut pieces with a GCELL (TH_PIECE), built once.
DO L=1,SIZE(M%TH_PIECE,2)
   FV%CV%DVOL(CUT_CELL(M%TH_PIECE(1,L))%IG(M%TH_PIECE(2,L)))=0._EB
ENDDO
FV%CV%DEL_RHO_D_DEL_Z_VOL=0._EB
FV%CV%U_DOT_DEL_RHO_Z_VOL=0._EB
IF (CORRECTOR) THEN
   IF (ALLOCATED(MESHES(NM)%D_SOURCE)) THEN
      ! Up to here in D_SOURCE(I,J,K), M_DOT_PPP(I,J,K,1:N_TOTAL_SCALARS) we have contributions by particles.
      ! Add these contributions in corresponding cut-cells:
      ! NOTE : Assumes the source from particles is distributed evenly over CCs of the Cartesian cell.
      DO L=1,SIZE(M%TH_PIECE,2)
         ICC=M%TH_PIECE(1,L); IG=CUT_CELL(ICC)%IG(M%TH_PIECE(2,L))
         I=CUT_CELL(ICC)%IJK(IAXIS); J=CUT_CELL(ICC)%IJK(JAXIS); K=CUT_CELL(ICC)%IJK(KAXIS)
         FV%CV%D_SOURCE(IG)=FV%CV%D_SOURCE(IG)+D_SOURCE(I,J,K)
         FV%CV%M_DOT_PPP(1:N_TOTAL_SCALARS,IG)= &
            FV%CV%M_DOT_PPP(1:N_TOTAL_SCALARS,IG)+M_DOT_PPP(I,J,K,1:N_TOTAL_SCALARS)
      ENDDO
   ENDIF
ENDIF

IF (SET_DIV_TO_ZERO) THEN
   DP = 0._EB ! Set to zero divg on all cells.
   RETURN
ENDIF
IF (SET_CCDIV_TO_ZERO) RETURN

! Point to corresponding ZZ array:
SELECT CASE(PREDICTOR)
   CASE(.TRUE.)
      ZZP => ZZS
   CASE(.FALSE.)
      ZZP => ZZ
END SELECT

ALLOCATE(ZZ_GET(N_TRACKED_SPECIES))

! Add species diffusion terms to divergence expression and compute diffusion term for species equations
SPECIES_GT_1_IF: IF (N_TOTAL_SCALARS>1) THEN

   ! 1. Diffusive Heat flux = - Grad dot (h_s rho D Grad Z_n):
   ! In FV form: use faces to add corresponding face integral terms, for face k
   ! (sum_a{h_{s,a} rho D_a Grad z_a) dot \hat{n}_k A_k, where \hat{n}_k is the versor outside of cell
   ! at face k.
   CALL CC_DIFFUSIVE_MASS_FLUXES(NM)

   ! Zero out DEL_RHO_D_DEL_Z for impregion regular cells:
   DO L=1,SIZE(M%TH_REG,2)
      DEL_RHO_D_DEL_Z(M%TH_REG(IAXIS,L),M%TH_REG(JAXIS,L),M%TH_REG(KAXIS,L),1:N_TOTAL_SCALARS) = 0._EB
   ENDDO

   ! 1. Diffusive heat flux  = - hs,a (Da Grad(rho*Ya) - Da/rho Grad(rho) (rho Ya)):
   CALL CC_DIFFUSIVE_HEAT_FLUXES
   CALL ZERO_FV_L2_MEMBER_DIFFUSION(NM,.TRUE.)

ENDIF SPECIES_GT_1_IF


CONDUCTION_HEAT_IF : IF( DO_CONDUCTION_HEAT_FLUX ) THEN
   ! 2. Conduction heat flux = - k Grad(T):
   CALL CC_CONDUCTION_HEAT_FLUX
ENDIF CONDUCTION_HEAT_IF


! Add \dot{q}''' and QR to DP:
! Regular cells:
DO L=1,SIZE(M%TH_REG,2)
   I=M%TH_REG(IAXIS,L); J=M%TH_REG(JAXIS,L); K=M%TH_REG(KAXIS,L)
   ! Add \dot{q}''' and QR to DP*Vii:
   DPVOL(I,J,K) = DPVOL(I,J,K) + (Q(I,J,K) + QR(I,J,K)) * DX(I)*DY(J)*DZ(K)
ENDDO

! HERE Cut-cells \dot{q}'''*VOL and QR*VOL:
DO L=1,SIZE(M%TH_PIECE,2)
   ICC=M%TH_PIECE(1,L); JCC=M%TH_PIECE(2,L); IG=CUT_CELL(ICC)%IG(JCC)
   FV%CV%DVOL(IG) = FV%CV%DVOL(IG)+ &
                    (FV%CV%Q(IG)+FV%CV%QR(IG))*CUT_CELL(ICC)%VOLUME(JCC)
ENDDO

! 3. Enthalpy advection term = - \bar{ u dot Grad (rho h_s) }:
! R_H_G = 1/(Cp * T)
! RTRM  = 1/(rho * Cp * T)
! Point to the appropriate velocity components

IF (PREDICTOR) THEN
   UU=>U
   VV=>V
   WW=>W
   PRFCTV = 1._EB
ELSE
   UU=>US
   VV=>VS
   WW=>WS
   PRFCTV = 0._EB
ENDIF

! Constant gamma makes rho*h_s uniform only when the background pressure is uniform (no stratification).
CONST_GAMMA_IF_1: IF (.NOT.CONSTANT_SPECIFIC_HEAT_RATIO .OR. STRATIFICATION) THEN
   CALL CCENTHALPY_ADVECTION ! Compute u dot grad rho h_s in FV form and add to DP in regular + cut-cells.
ENDIF CONST_GAMMA_IF_1


! Loop through regular cells in the implicit region, as well as cut-cells and compute R_H_G, and RTRM:
CP    => WORK5
R_H_G => WORK9
RTRM  => WORK1
! Regular cells:
DO L=1,SIZE(M%TH_REG,2)
   I=M%TH_REG(IAXIS,L); J=M%TH_REG(JAXIS,L); K=M%TH_REG(KAXIS,L)
   ZZ_GET(1:N_TRACKED_SPECIES) = ZZP(I,J,K,1:N_TRACKED_SPECIES)
   CALL GET_SPECIFIC_HEAT(ZZ_GET,CP(I,J,K),TMP(I,J,K))
   R_H_G(I,J,K) = 1._EB/(CP(I,J,K)*TMP(I,J,K))
   RTRM(I,J,K)  = R_H_G(I,J,K)/RHOP(I,J,K)
   DPVOL(I,J,K) = RTRM(I,J,K)*DPVOL(I,J,K)
ENDDO

! Cut-cells: per-piece R_H_G / RTRM live on the IG CV row. Do not CSR-mean
! onto the owner ICV — that index is the master's IG, so a mean would clobber
! the piece value (same trap as DDDTVOL / L1 per-member H).
DO L=1,SIZE(M%TH_PIECE,2)
   ICC=M%TH_PIECE(1,L); JCC=M%TH_PIECE(2,L); CC => CUT_CELL(ICC)
   IF (CELL(CELL_INDEX(CC%IJK(IAXIS),CC%IJK(JAXIS),CC%IJK(KAXIS)))%SOLID) CYCLE
   TMPV(0) = GET_CUTCELL_TMP(NM,ICC,JCC)
   CALL GET_CUTCELL_ZZV(NM,ICC,JCC,PRFCT,ZZ_GET)
   RHOPV(0) = GET_CUTCELL_RHOP(NM,ICC,JCC,PRFCT)
   CALL GET_SPECIFIC_HEAT(ZZ_GET,CPV(0),TMPV(0))
   R_H_G_CC = 1._EB/(CPV(0)*TMPV(0))
   RTRM_CC = R_H_G_CC/RHOPV(0)
   IG = CC%IG(JCC)
   FV%CV%R_H_G(IG) = R_H_G_CC
   FV%CV%RTRM(IG)  = RTRM_CC
   FV%CV%DVOL(IG) = RTRM_CC*FV%CV%DVOL(IG)
ENDDO


! 4. Enthalpy flux due to mass diffusion and advection:
! sum_n [\bar{W}/W_n - h_{s,n}*R_H_G] ( Grad dot (rho D_\alpha Grad Z_n) - \bar{u dot Grad (rho Z_n)})
! For constant gamma, Wbar/W_alpha-h_s,alpha/(cp*T) is zero even with stratification.

CONST_GAMMA_IF_2: IF (.NOT.CONSTANT_SPECIFIC_HEAT_RATIO) THEN

   SPECIES_LOOP: DO N=1,N_TRACKED_SPECIES

      CALL CCSPECIES_ADVECTION ! Compute u dot grad rho Z_n

      SM  => SPECIES_MIXTURE(N)

      ! Regular cells:
      DO L=1,SIZE(M%TH_REG,2)
         I=M%TH_REG(IAXIS,L); J=M%TH_REG(JAXIS,L); K=M%TH_REG(KAXIS,L)
         CALL GET_SENSIBLE_ENTHALPY_Z(N,TMP(I,J,K),H_S)
         DPVOL(I,J,K) = DPVOL(I,J,K) + (SM%RCON/RSUM(I,J,K) - H_S*R_H_G(I,J,K))* &
                                       (DEL_RHO_D_DEL_Z(I,J,K,N) - U_DOT_DEL_RHO_Z_VOL(I,J,K))/RHOP(I,J,K)
         ! Values of DEL_RHO_D_DEL_Z(I,J,K,N) have been filled previously.
         ! RSUM was computed in the implicit region advance routine for scalars CCDENSITY.
      ENDDO

      ! Cut-cells:
      DO L=1,SIZE(M%TH_PIECE,2)
         ICC=M%TH_PIECE(1,L); JCC=M%TH_PIECE(2,L); CC => CUT_CELL(ICC)
         IF (CELL(CELL_INDEX(CC%IJK(IAXIS),CC%IJK(JAXIS),CC%IJK(KAXIS)))%SOLID) CYCLE
         IG = CC%IG(JCC)
         ICV = CC%ICV(JCC); IF (ICV<1) CYCLE
         TMPV(0) = GET_CUTCELL_TMP(NM,ICC,JCC)
         CALL GET_SENSIBLE_ENTHALPY_Z(N,TMPV(0),H_S)
         R_H_G_CC = FV%CV%R_H_G(IG)
         FV%CV%DVOL(IG) = FV%CV%DVOL(IG) + (SM%RCON/GET_CUTCELL_RSUM(NM,ICC,JCC) - H_S*R_H_G_CC)/ &
                                          GET_CUTCELL_RHOP(NM,ICC,JCC,PRFCT) * &
                                          (MERGE(FV%CV%DEL_RHO_D_DEL_Z_VOL(N,ICV),0._EB,FV%CV%OWNER_GCELL(ICV)==IG) &
                                           -FV%CV%U_DOT_DEL_RHO_Z_VOL(N,IG))
      ENDDO

   ENDDO SPECIES_LOOP

ENDIF CONST_GAMMA_IF_2

! Add contribution of reactions

IF (ALLOCATED(MESHES(NM)%D_SOURCE)) THEN

   ! Regular Cells on the implicit region:
   DO L=1,SIZE(M%TH_REG,2)
      I=M%TH_REG(IAXIS,L); J=M%TH_REG(JAXIS,L); K=M%TH_REG(KAXIS,L)
      DPVOL(I,J,K) = DPVOL(I,J,K) + D_SOURCE(I,J,K)*DX(I)*DY(J)*DZ(K)
   ENDDO

   ! Cut cells:
   DO L=1,SIZE(M%TH_PIECE,2)
      CC => CUT_CELL(M%TH_PIECE(1,L)); IF (CELL(CELL_INDEX(CC%IJK(IAXIS),CC%IJK(JAXIS),CC%IJK(KAXIS)))%SOLID) CYCLE
      JCC=M%TH_PIECE(2,L); IG=CC%IG(JCC)
      FV%CV%DVOL(IG)=FV%CV%DVOL(IG)+FV%CV%D_SOURCE(IG)*CC%VOLUME(JCC)
   ENDDO

ENDIF

! Atmospheric stratification term

IF (STRATIFICATION) THEN
   ! Regular Cells on the implicit region:
   DO L=1,SIZE(M%TH_REG,2)
      I=M%TH_REG(IAXIS,L); J=M%TH_REG(JAXIS,L); K=M%TH_REG(KAXIS,L)
      DPVOL(I,J,K) = DPVOL(I,J,K) + &
      RTRM(I,J,K)*0.5_EB*(WW(I,J,K)+WW(I,J,K-1))* &
      RHO_0_CV(CCVAR(I,J,K,CC_UNKZ))*GVEC(KAXIS)*DX(I)*DY(J)*DZ(K)
   ENDDO
   DO L=1,SIZE(M%TH_PIECE,2)
      CC => CUT_CELL(M%TH_PIECE(1,L)); IF (CELL(CELL_INDEX(CC%IJK(IAXIS),CC%IJK(JAXIS),CC%IJK(KAXIS)))%SOLID) CYCLE
      ! D = D + w*rho_0*g/(rho*Cp*T)*Vii
      JCC=M%TH_PIECE(2,L); IG=CC%IG(JCC)
      RTRM_CC = FV%CV%RTRM(IG)
      FV%CV%DVOL(IG)=FV%CV%DVOL(IG)+RTRM_CC*FV%CV%WVEL(IG)*FV%CV%RHO_0(IG)*GVEC(KAXIS)*CC%VOLUME(JCC)
   ENDDO
ENDIF

! Manufactured solution

MMS_IF: IF (PERIODIC_TEST==7) THEN
   IF (PREDICTOR) TT=T+DT
   IF (CORRECTOR) TT=T
   ! Regular cells on cut-cell region:
   DO L=1,SIZE(M%TH_REG,2)
      I=M%TH_REG(IAXIS,L); J=M%TH_REG(JAXIS,L); K=M%TH_REG(KAXIS,L)
      ! this term is similar to D_REACTION from fire
      XHAT = XC(I) - UF_MMS*TT
      ZHAT = ZC(K) - WF_MMS*TT
      DO N=1,N_TRACKED_SPECIES
         SM => SPECIES_MIXTURE(N)
         SELECT CASE(N)
            CASE(1); Q_Z = -VD2D_MMS_Z_SRC(XHAT,ZHAT,TT)
            CASE(2); Q_Z =  VD2D_MMS_Z_SRC(XHAT,ZHAT,TT)
         END SELECT
         CALL GET_SENSIBLE_ENTHALPY_Z(N,TMP(I,J,K),H_S)
         DPVOL(I,J,K) = DPVOL(I,J,K) + ( SM%RCON/RSUM(I,J,K) - H_S*R_H_G(I,J,K) )*Q_Z/RHOP(I,J,K)*DX(I)*DY(J)*DZ(K)
      ENDDO
   ENDDO
   ! Cut-cells:
   DO L=1,SIZE(M%TH_PIECE,2)
      ICC=M%TH_PIECE(1,L); JCC=M%TH_PIECE(2,L)
      I = CUT_CELL(ICC)%IJK(IAXIS); J = CUT_CELL(ICC)%IJK(JAXIS); K = CUT_CELL(ICC)%IJK(KAXIS)
      IF (CELL(CELL_INDEX(I,J,K))%SOLID) CYCLE
      ! this term is similar to D_REACTION from fire
      XHAT = CUT_CELL(ICC)%XYZCEN(IAXIS,JCC) - UF_MMS*TT
      ZHAT = CUT_CELL(ICC)%XYZCEN(KAXIS,JCC) - WF_MMS*TT
      TMPV(0) = GET_CUTCELL_TMP(NM,ICC,JCC)
      IG = CUT_CELL(ICC)%IG(JCC)
      DO N=1,N_TRACKED_SPECIES
         SM => SPECIES_MIXTURE(N)
         SELECT CASE(N)
            CASE(1); Q_Z = -VD2D_MMS_Z_SRC(XHAT,ZHAT,TT)
            CASE(2); Q_Z =  VD2D_MMS_Z_SRC(XHAT,ZHAT,TT)
         END SELECT
         CALL GET_SENSIBLE_ENTHALPY_Z(N,TMPV(0),H_S)
         R_H_G_CC = FV%CV%R_H_G(IG)
         FV%CV%DVOL(IG)=FV%CV%DVOL(IG)+ &
            (SM%RCON/GET_CUTCELL_RSUM(NM,ICC,JCC)-H_S*R_H_G_CC)* &
            Q_Z/GET_CUTCELL_RHOP(NM,ICC,JCC,PRFCT)*CUT_CELL(ICC)%VOLUME(JCC)
      ENDDO
   ENDDO
ENDIF MMS_IF

   ! Preserve volume-integrated member contributions until every local mesh has completed.
   ! FINALIZE_FV_L2_THERMODYNAMIC_ROWS performs the global UNKZ reduction and scatter.
   DEALLOCATE(ZZ_GET)
   T_USED(14) = T_USED(14) + CURRENT_TIME() - TNOW
   IF (TIME_CC_IBM) &
      T_CC_USED(CC_DIVERGENCE_PART_1_TIME_INDEX) = T_CC_USED(CC_DIVERGENCE_PART_1_TIME_INDEX) + CURRENT_TIME() - TNOW
   RETURN

CONTAINS

FUNCTION GET_BOUNDARY_CUTFACE_VEL(ICF_LOC,JCF_LOC,PRFCT_VEL) RESULT(VEL_OUT)

INTEGER, INTENT(IN) :: ICF_LOC,JCF_LOC
REAL(EB), INTENT(IN) :: PRFCT_VEL
REAL(EB) :: VEL_OUT

VEL_OUT = (1._EB-PRFCT_VEL)*CC_FV_CUTFACE_MOM(NM,ICF_LOC,JCF_LOC,CC_FV_MOM_VEL) + &
          PRFCT_VEL*CC_FV_CUTFACE_MOM(NM,ICF_LOC,JCF_LOC,CC_FV_MOM_VELS)

END FUNCTION GET_BOUNDARY_CUTFACE_VEL


SUBROUTINE ADD_CC_THERMODYNAMIC_VALUE(ICC_LOC,JCC_LOC,QUANTITY,NQ,VALUE)

INTEGER, INTENT(IN) :: ICC_LOC,JCC_LOC,QUANTITY,NQ
REAL(EB), INTENT(IN) :: VALUE
INTEGER :: IROW

IF (QUANTITY==CC_FV_ADVECT_SPECIES) THEN
   CALL GET_FV_CV_STORAGE_FOR_CUTCELL(NM,ICC_LOC,JCC_LOC,IROW)
   IF (IROW>=1) FV%CV%U_DOT_DEL_RHO_Z_VOL(NQ,IROW)=FV%CV%U_DOT_DEL_RHO_Z_VOL(NQ,IROW)+VALUE
ELSE
   IG = CUT_CELL(ICC_LOC)%IG(JCC_LOC); IF (IG>=1) FV%CV%DVOL(IG)=FV%CV%DVOL(IG)+VALUE
ENDIF
END SUBROUTINE ADD_CC_THERMODYNAMIC_VALUE



! ---------------------------- CCSPECIES_ADVECTION ------------------------------

SUBROUTINE CCSPECIES_ADVECTION
! One gas walk and one wall walk over external FV faces. The per-side correction is the
! old one: (face flux - cell rho*Y)*velocity*area, with the low side positive and the
! high side negative. The limiter stencil stays in increasing-index order and the
! velocity keeps its signed component, including zero, so a mirror reverses both together.

REAL(EB) :: RHO_Z_PV(-2:1),VELC,FN_ZZ,RZ,AF
REAL(EB), PARAMETER :: SGN=1._EB
INTEGER :: IREG,AX,IH,JH,KH,JCF
LOGICAL :: DO_LO,DO_HI,WALL_FACE
TYPE(BOUNDARY_PROP1_TYPE), POINTER :: B1
REAL(EB), POINTER, DIMENSION(:,:,:,:) :: FX_ZZ,FY_ZZ,FZ_ZZ

U_DOT_DEL_RHO_Z_VOL=>WORK7
U_DOT_DEL_RHO_Z_VOL=0._EB
FX_ZZ=>SWORK1; FY_ZZ=>SWORK2; FZ_ZZ=>SWORK3
U_TEMP=>U_WORK; F_TEMP=>F_WORK; Z_TEMP=>Z_WORK
FV%CV%U_DOT_DEL_RHO_Z_VOL(N,:)=0._EB

! Past N_INT: the regular-face tail and unclaimed RC rows. The legacy loops included them.
! Guard cut-faces in that tail are dropped by the ICF bound below.
DO IF_=1,FV%FACE%N
   IF (FV%FACE%ROLE(IF_)/=CC_FACE_ROLE_EXTERNAL) CYCLE
   SELECT CASE(FV%FACE%FTYPE(IF_))
   CASE(CC_FTYPE_RGGAS)
      IREG=FV%FACE%SRC_IREG(IF_)
      IF (IREG<1) CYCLE
      AX=FV%FACE%X1AXIS(IF_)
      CALL ADV_REG_IJK(AX,IREG,I,J,K,IW,DO_LO,DO_HI)
      CALL ADV_HIGH(AX,I,J,K,IH,JH,KH)
      CALL ADV_AREA_VEL(AX,I,J,K,AF,VELC)
      WALL_FACE=.FALSE.
      IF (IW>0) THEN
         IF (WALL(IW)%BOUNDARY_TYPE/=INTERPOLATED_BOUNDARY) THEN
            IF (WALL(IW)%BOUNDARY_TYPE/=PERIODIC_BOUNDARY) WALL_FACE=.TRUE.
         ENDIF
      ENDIF
      IF (WALL_FACE) THEN
         CALL ADV_WALL_SPECIES(0,I,J,K,AX,IW,AF,VELC,.FALSE.)
      ELSE
         IF (IW>0) THEN
            IF (WALL(IW)%BOUNDARY_TYPE==INTERPOLATED_BOUNDARY) VELC=UVW_SAVE(IW)
         ENDIF
         IF (IW<1) THEN
            SELECT CASE(AX)
            CASE(IAXIS); FN_ZZ=FX_ZZ(I,J,K,N)
            CASE(JAXIS); FN_ZZ=FY_ZZ(I,J,K,N)
            CASE(KAXIS); FN_ZZ=FZ_ZZ(I,J,K,N)
            END SELECT
         ELSE
            B1=>BOUNDARY_PROP1(WALL(IW)%B1_INDEX)
            FN_ZZ=B1%RHO_F*B1%ZZ_F(N)
         ENDIF
         CALL ADV_RHOZ(0,I,J,K,RZ); RHO_Z_PV(-1)=RZ
         CALL ADV_RHOZ(0,IH,JH,KH,RZ); RHO_Z_PV(0)=RZ
         IF (DO_LO) CALL ADV_PUT(.FALSE.,0,0,I,J,K,SGN*(FN_ZZ-RHO_Z_PV(-1))*VELC*AF,.TRUE.)
         IF (DO_HI) CALL ADV_PUT(.FALSE.,0,0,IH,JH,KH,-SGN*(FN_ZZ-RHO_Z_PV(0))*VELC*AF,.TRUE.)
      ENDIF
   CASE(CC_FTYPE_RCGAS)
      ICF=FV%FACE%SRC_IRC(IF_)
      IF (ICF<1 .OR. ICF>MESHES(NM)%CC_NRCFACE_Z) CYCLE
      CALL ADV_RC_GEOM(ICF,I,J,K,AX,IW,AF,VELC)
      IF (IW>0) THEN
         IF (WALL(IW)%BOUNDARY_TYPE==NULL_BOUNDARY) CYCLE
         CALL ADV_WALL_SPECIES(ICF,I,J,K,AX,IW,AF,VELC,.TRUE.)
      ELSE
         CALL ADV_LIMIT_SPECIES(I,J,K,AX,ICF,0,0,VELC,FN_ZZ,RHO_Z_PV)
         CALL ADV_BOTH_SIDES(ICF,0,I,J,K,AX,FN_ZZ,VELC,AF,RHO_Z_PV,SGN,.TRUE.)
      ENDIF
   CASE(CC_FTYPE_CFGAS)
      ICF=FV%FACE%SRC_ICF(IF_); JCF=FV%FACE%SRC_JCF(IF_)
      IF (ICF<1 .OR. ICF>MESHES(NM)%N_CUTFACE_MESH) CYCLE
      IF (CUT_FACE(ICF)%STATUS/=CC_GASPHASE) CYCLE
      IW=CUT_FACE(ICF)%IWC
      I=CUT_FACE(ICF)%IJK(IAXIS); J=CUT_FACE(ICF)%IJK(JAXIS); K=CUT_FACE(ICF)%IJK(KAXIS)
      AX=CUT_FACE(ICF)%IJK(KAXIS+1)
      AF=CUT_FACE(ICF)%AREA(JCF)
      IF (IW>0) THEN
         IF (WALL(IW)%BOUNDARY_TYPE==NULL_BOUNDARY) CYCLE
         CALL ADV_CF_WALL_SPECIES(ICF,JCF,I,J,K,AX,IW,AF)
      ELSE
         VELC=GET_BOUNDARY_CUTFACE_VEL(ICF,JCF,1._EB-PRFCTV)
         CALL ADV_LIMIT_SPECIES(I,J,K,AX,0,ICF,JCF,VELC,FN_ZZ,RHO_Z_PV)
         CALL ADV_BOTH_SIDES(0,JCF,I,J,K,AX,FN_ZZ,VELC,AF,RHO_Z_PV,SGN,.TRUE.)
      ENDIF
   CASE(CC_FTYPE_CFINB)
      CALL ADV_INBOUNDARY(IF_,SGN,.TRUE.)
   END SELECT
ENDDO
! Regular and cut walls that the gas cases skipped are handled above when WALL_FACE is true
! for RGGAS. RC and cut walls are called from their cases. Nothing further.
RETURN
END SUBROUTINE CCSPECIES_ADVECTION


! ---------------------------- CCENTHALPY_ADVECTION -----------------------------

SUBROUTINE CCENTHALPY_ADVECTION
! Same two walks as species, for rho*h_s. The sign is the opposite of species, which is
! what the axis loops did. Sensible enthalpy is evaluated once per GCELL.

REAL(EB) :: RHO_H(-2:1),VELC,FN_H,RH,AF
REAL(EB), PARAMETER :: SGN=-1._EB
REAL(EB), ALLOCATABLE :: HSG(:)
INTEGER :: IREG,AX,IH,JH,KH,JCF,IGC,II,JJ,KK
LOGICAL :: DO_LO,DO_HI,WALL_FACE
TYPE(BOUNDARY_PROP1_TYPE), POINTER :: B1
REAL(EB), POINTER, DIMENSION(:,:,:) :: FX_H,FY_H,FZ_H

U_TEMP=>U_WORK; F_TEMP=>F_WORK; Z_TEMP=>Z_WORK
FX_H=>WORK2; FY_H=>WORK3; FZ_H=>WORK4
IF (FV%GCELL%N>0) THEN
   ALLOCATE(HSG(FV%GCELL%N))
   DO IGC=1,FV%GCELL%N
      II=FV%GCELL%IJK(IAXIS,IGC); JJ=FV%GCELL%IJK(JAXIS,IGC); KK=FV%GCELL%IJK(KAXIS,IGC)
      IF (FV%GCELL%CELL_TYPE(IGC)==CC_GCELL_CUT) THEN
         ICC=FV%GCELL%ICC(IGC); JCC=FV%GCELL%JCC(IGC)
         CALL GET_CUTCELL_ZZV(NM,ICC,JCC,PRFCT,ZZ_GET)
         TMPV(0)=GET_CUTCELL_TMP(NM,ICC,JCC)
      ELSE
         ZZ_GET(1:N_TRACKED_SPECIES)=ZZP(II,JJ,KK,1:N_TRACKED_SPECIES)
         TMPV(0)=TMP(II,JJ,KK)
      ENDIF
      CALL GET_SENSIBLE_ENTHALPY(ZZ_GET,HSG(IGC),TMPV(0))
   ENDDO
ENDIF

! Same tail as species: regular faces and unclaimed RC rows live past N_INT.
DO IF_=1,FV%FACE%N
   IF (FV%FACE%ROLE(IF_)/=CC_FACE_ROLE_EXTERNAL) CYCLE
   SELECT CASE(FV%FACE%FTYPE(IF_))
   CASE(CC_FTYPE_RGGAS)
      IREG=FV%FACE%SRC_IREG(IF_)
      IF (IREG<1) CYCLE
      AX=FV%FACE%X1AXIS(IF_)
      CALL ADV_REG_IJK(AX,IREG,I,J,K,IW,DO_LO,DO_HI)
      CALL ADV_HIGH(AX,I,J,K,IH,JH,KH)
      CALL ADV_AREA_VEL(AX,I,J,K,AF,VELC)
      WALL_FACE=.FALSE.
      IF (IW>0) THEN
         IF (WALL(IW)%BOUNDARY_TYPE/=INTERPOLATED_BOUNDARY) THEN
            IF (WALL(IW)%BOUNDARY_TYPE/=PERIODIC_BOUNDARY) WALL_FACE=.TRUE.
         ENDIF
      ENDIF
      IF (WALL_FACE) THEN
         CALL ADV_REG_WALL_H(I,J,K,AX,IW,AF,VELC,HSG,SGN)
      ELSE
         IF (IW>0) THEN
            IF (WALL(IW)%BOUNDARY_TYPE==INTERPOLATED_BOUNDARY) VELC=UVW_SAVE(IW)
         ENDIF
         IF (IW<1) THEN
            SELECT CASE(AX)
            CASE(IAXIS); FN_H=FX_H(I,J,K)
            CASE(JAXIS); FN_H=FY_H(I,J,K)
            CASE(KAXIS); FN_H=FZ_H(I,J,K)
            END SELECT
         ELSE
            B1=>BOUNDARY_PROP1(WALL(IW)%B1_INDEX)
            ZZ_GET(1:N_TRACKED_SPECIES)=B1%ZZ_F(1:N_TRACKED_SPECIES)
            CALL GET_SENSIBLE_ENTHALPY(ZZ_GET,H_S,B1%TMP_F)
            FN_H=B1%RHO_F*H_S
         ENDIF
         CALL ADV_RHOH(HSG,ADV_SIDE_IG(IF_,.TRUE.),I,J,K,RH); RHO_H(-1)=RH
         CALL ADV_RHOH(HSG,ADV_SIDE_IG(IF_,.FALSE.),IH,JH,KH,RH); RHO_H(0)=RH
         IF (DO_LO) CALL ADV_PUT(.FALSE.,0,0,I,J,K,SGN*(FN_H-RHO_H(-1))*VELC*AF,.FALSE.)
         IF (DO_HI) CALL ADV_PUT(.FALSE.,0,0,IH,JH,KH,-SGN*(FN_H-RHO_H(0))*VELC*AF,.FALSE.)
      ENDIF
   CASE(CC_FTYPE_RCGAS)
      ICF=FV%FACE%SRC_IRC(IF_)
      IF (ICF<1) CYCLE
      IW=RC_FACE(ICF)%IWC
      IF (IW>0) THEN
         IF (ICF>MESHES(NM)%CC_NBBRCFACE_Z) CYCLE
         IF (WALL(IW)%BOUNDARY_TYPE==NULL_BOUNDARY) CYCLE
         CALL ADV_RC_GEOM(ICF,I,J,K,AX,IW,AF,VELC)
         CALL ADV_WALL_H(ICF,I,J,K,AX,IW,AF,VELC,HSG,SGN)
      ELSE
         IF (ICF>MESHES(NM)%CC_NRCFACE_Z) CYCLE
         CALL ADV_RC_GEOM(ICF,I,J,K,AX,IW,AF,VELC)
         CALL ADV_LIMIT_H(HSG,I,J,K,AX,ICF,0,0,VELC,FN_H,RHO_H)
         CALL ADV_BOTH_SIDES(ICF,0,I,J,K,AX,FN_H,VELC,AF,RHO_H,SGN,.FALSE.)
      ENDIF
   CASE(CC_FTYPE_CFGAS)
      ICF=FV%FACE%SRC_ICF(IF_); JCF=FV%FACE%SRC_JCF(IF_)
      IF (ICF<1 .OR. ICF>MESHES(NM)%N_CUTFACE_MESH) CYCLE
      IF (CUT_FACE(ICF)%STATUS/=CC_GASPHASE) CYCLE
      IW=CUT_FACE(ICF)%IWC
      I=CUT_FACE(ICF)%IJK(IAXIS); J=CUT_FACE(ICF)%IJK(JAXIS); K=CUT_FACE(ICF)%IJK(KAXIS)
      AX=CUT_FACE(ICF)%IJK(KAXIS+1); AF=CUT_FACE(ICF)%AREA(JCF)
      IF (IW>0) THEN
         IF (WALL(IW)%BOUNDARY_TYPE==NULL_BOUNDARY) CYCLE
         CALL ADV_CF_WALL_H(ICF,JCF,I,J,K,AX,IW,AF,HSG,SGN)
      ELSE
         VELC=GET_BOUNDARY_CUTFACE_VEL(ICF,JCF,1._EB-PRFCTV)
         CALL ADV_LIMIT_H(HSG,I,J,K,AX,0,ICF,JCF,VELC,FN_H,RHO_H)
         CALL ADV_BOTH_SIDES(0,JCF,I,J,K,AX,FN_H,VELC,AF,RHO_H,SGN,.FALSE.)
      ENDIF
   CASE(CC_FTYPE_CFINB)
      CALL ADV_INBOUNDARY_H(IF_,HSG,SGN)
   END SELECT
ENDDO
RETURN
END SUBROUTINE CCENTHALPY_ADVECTION

SUBROUTINE ADV_REG_IJK(AX,IREG,I,J,K,IW,DO_LO,DO_HI)
INTEGER, INTENT(IN) :: AX,IREG
INTEGER, INTENT(OUT) :: I,J,K,IW
LOGICAL, INTENT(OUT) :: DO_LO,DO_HI
SELECT CASE(AX)
CASE(IAXIS)
   I=CC_REGFACE_IAXIS_Z(IREG)%IJK(IAXIS); J=CC_REGFACE_IAXIS_Z(IREG)%IJK(JAXIS)
   K=CC_REGFACE_IAXIS_Z(IREG)%IJK(KAXIS); IW=CC_REGFACE_IAXIS_Z(IREG)%IWC
   DO_LO=CC_REGFACE_IAXIS_Z(IREG)%DO_LO_IND; DO_HI=CC_REGFACE_IAXIS_Z(IREG)%DO_HI_IND
CASE(JAXIS)
   I=CC_REGFACE_JAXIS_Z(IREG)%IJK(IAXIS); J=CC_REGFACE_JAXIS_Z(IREG)%IJK(JAXIS)
   K=CC_REGFACE_JAXIS_Z(IREG)%IJK(KAXIS); IW=CC_REGFACE_JAXIS_Z(IREG)%IWC
   DO_LO=CC_REGFACE_JAXIS_Z(IREG)%DO_LO_IND; DO_HI=CC_REGFACE_JAXIS_Z(IREG)%DO_HI_IND
CASE(KAXIS)
   I=CC_REGFACE_KAXIS_Z(IREG)%IJK(IAXIS); J=CC_REGFACE_KAXIS_Z(IREG)%IJK(JAXIS)
   K=CC_REGFACE_KAXIS_Z(IREG)%IJK(KAXIS); IW=CC_REGFACE_KAXIS_Z(IREG)%IWC
   DO_LO=CC_REGFACE_KAXIS_Z(IREG)%DO_LO_IND; DO_HI=CC_REGFACE_KAXIS_Z(IREG)%DO_HI_IND
END SELECT
END SUBROUTINE ADV_REG_IJK

SUBROUTINE ADV_HIGH(AX,I,J,K,IH,JH,KH)
INTEGER, INTENT(IN) :: AX,I,J,K
INTEGER, INTENT(OUT) :: IH,JH,KH
IH=I; JH=J; KH=K
SELECT CASE(AX)
CASE(IAXIS); IH=I+1
CASE(JAXIS); JH=J+1
CASE(KAXIS); KH=K+1
END SELECT
END SUBROUTINE ADV_HIGH

SUBROUTINE ADV_CELL(AX,I,J,K,OFF,IS,JS,KS)
INTEGER, INTENT(IN) :: AX,I,J,K,OFF
INTEGER, INTENT(OUT) :: IS,JS,KS
IS=I; JS=J; KS=K
SELECT CASE(AX)
CASE(IAXIS); IS=I+OFF
CASE(JAXIS); JS=J+OFF
CASE(KAXIS); KS=K+OFF
END SELECT
END SUBROUTINE ADV_CELL

SUBROUTINE ADV_AREA_VEL(AX,I,J,K,AF,VEL)
INTEGER, INTENT(IN) :: AX,I,J,K
REAL(EB), INTENT(OUT) :: AF,VEL
SELECT CASE(AX)
CASE(IAXIS); AF=DY(J)*DZ(K); VEL=UU(I,J,K)
CASE(JAXIS); AF=DX(I)*DZ(K); VEL=VV(I,J,K)
CASE(KAXIS); AF=DX(I)*DY(J); VEL=WW(I,J,K)
END SELECT
END SUBROUTINE ADV_AREA_VEL

SUBROUTINE ADV_RC_GEOM(IRC,I,J,K,AX,IW,AF,VEL)
INTEGER, INTENT(IN) :: IRC
INTEGER, INTENT(OUT) :: I,J,K,AX,IW
REAL(EB), INTENT(OUT) :: AF,VEL
I=RC_FACE(IRC)%IJK(IAXIS); J=RC_FACE(IRC)%IJK(JAXIS); K=RC_FACE(IRC)%IJK(KAXIS)
AX=RC_FACE(IRC)%IJK(KAXIS+1); IW=RC_FACE(IRC)%IWC
CALL ADV_AREA_VEL(AX,I,J,K,AF,VEL)
END SUBROUTINE ADV_RC_GEOM

! IG>=1 is a cut piece (CV rho and Y). IG=0, or a regular GCELL, is the Cartesian
! cell (I,J,K). A side with no GCELL is that Cartesian cell: the neighbor outside
! the FV set, or a mesh-interface ghost.
SUBROUTINE ADV_RHOZ(IG,I,J,K,RZ)
INTEGER, INTENT(IN) :: IG,I,J,K
REAL(EB), INTENT(OUT) :: RZ
REAL(EB) :: RHO,ZZN
IF (IG>=1) THEN
   IF (FV%GCELL%CELL_TYPE(IG)==CC_GCELL_CUT) THEN
      RHO=PRFCT*FV%CV%RHO(IG)+(1._EB-PRFCT)*FV%CV%RHOS(IG)
      ZZN=PRFCT*FV%CV%ZZ(N,IG)+(1._EB-PRFCT)*FV%CV%ZZS(N,IG)
      RZ=RHO*ZZN
      RETURN
   ENDIF
ENDIF
RZ=RHOP(I,J,K)*ZZP(I,J,K,N)
END SUBROUTINE ADV_RHOZ

SUBROUTINE ADV_RHOH(HSG,IG,I,J,K,RH)
REAL(EB), ALLOCATABLE, INTENT(IN) :: HSG(:)
INTEGER, INTENT(IN) :: IG,I,J,K
REAL(EB), INTENT(OUT) :: RH
REAL(EB) :: RHO
INTEGER :: II,JJ,KK
IF (IG>=1) THEN
   ! HSG was evaluated once for this GCELL. Cut pieces use the CV density blend.
   ! A regular GCELL uses the Cartesian blend at that GCELL's own IJK.
   IF (FV%GCELL%CELL_TYPE(IG)==CC_GCELL_CUT) THEN
      RHO=PRFCT*FV%CV%RHO(IG)+(1._EB-PRFCT)*FV%CV%RHOS(IG)
   ELSE
      II=FV%GCELL%IJK(IAXIS,IG); JJ=FV%GCELL%IJK(JAXIS,IG); KK=FV%GCELL%IJK(KAXIS,IG)
      RHO=RHOP(II,JJ,KK)
   ENDIF
   RH=RHO*HSG(IG)
   RETURN
ENDIF
! No GCELL: Cartesian cell (I,J,K). That is a neighbor outside the FV set, or a mesh-interface ghost.
ZZ_GET(1:N_TRACKED_SPECIES)=ZZP(I,J,K,1:N_TRACKED_SPECIES)
CALL GET_SENSIBLE_ENTHALPY(ZZ_GET,H_S,TMP(I,J,K))
RH=RHOP(I,J,K)*H_S
END SUBROUTINE ADV_RHOH

INTEGER FUNCTION ADV_SIDE_IG(IF_,LOW_SIDE)
INTEGER, INTENT(IN) :: IF_
LOGICAL, INTENT(IN) :: LOW_SIDE
INTEGER :: AX,IGL,IGH
ADV_SIDE_IG=0
AX=FV%FACE%X1AXIS(IF_)
IGL=FV%FACE%OWNER_GCELL(IF_); IGH=FV%FACE%NBR_GCELL(IF_)
IF (FV%FACE%NVEC(AX,IF_)<0._EB) THEN
   ADV_SIDE_IG=IGL; IGL=IGH; IGH=ADV_SIDE_IG
ENDIF
IF (LOW_SIDE) THEN; ADV_SIDE_IG=IGL; ELSE; ADV_SIDE_IG=IGH; ENDIF
END FUNCTION ADV_SIDE_IG

SUBROUTINE ADV_PUT(IS_CUT,ICC,JCC,I,J,K,VAL,FOR_ZZ)
LOGICAL, INTENT(IN) :: IS_CUT,FOR_ZZ
INTEGER, INTENT(IN) :: ICC,JCC,I,J,K
REAL(EB), INTENT(IN) :: VAL
IF (IS_CUT) THEN
   IF (ICC<1) RETURN
   IF (ICC>MESHES(NM)%N_CUTCELL_MESH) RETURN
   IF (FOR_ZZ) THEN
      CALL ADD_CC_THERMODYNAMIC_VALUE(ICC,JCC,CC_FV_ADVECT_SPECIES,N,VAL)
   ELSE
      CALL ADD_CC_THERMODYNAMIC_VALUE(ICC,JCC,CC_FV_ADVECT_ENTHALPY,1,VAL)
   ENDIF
ELSE
   IF (FOR_ZZ) THEN
      U_DOT_DEL_RHO_Z_VOL(I,J,K)=U_DOT_DEL_RHO_Z_VOL(I,J,K)+VAL
   ELSE
      DPVOL(I,J,K)=DPVOL(I,J,K)+VAL
   ENDIF
ENDIF
END SUBROUTINE ADV_PUT

SUBROUTINE ADV_GODUNOV(VEL,Z4,FN)
REAL(EB), INTENT(IN) :: VEL,Z4(-2:1)
REAL(EB), INTENT(OUT) :: FN
! Stencil in increasing index order. Velocity is the signed component, including 0.
Z_TEMP(0:3,1,1)=Z4(-2:1)
U_TEMP(1,1,1)=VEL
CALL GET_SCALAR_FACE_VALUE(U_TEMP,Z_TEMP,F_TEMP,1,1,1,1,1,1,1,I_FLUX_LIMITER)
FN=F_TEMP(1,1,1)
END SUBROUTINE ADV_GODUNOV

SUBROUTINE ADV_LIMIT_SPECIES(I,J,K,AX,IRC,ICF,JCF,VEL,FN,SIDE)
INTEGER, INTENT(IN) :: I,J,K,AX,IRC,ICF,JCF
REAL(EB), INTENT(IN) :: VEL
REAL(EB), INTENT(OUT) :: FN,SIDE(-2:1)
INTEGER :: ISIDE,IS,JS,KS,ICC,JCC,IG
REAL(EB) :: RZ
SIDE(-2:1)=0._EB
DO ISIDE=-1,0
   CALL ADV_CELL(AX,I,J,K,1+ISIDE,IS,JS,KS)
   IG=-1
   IF (IRC>0) THEN
      IF (RC_FACE(IRC)%CELL_LIST(1,ISIDE+2)==CC_FTYPE_CFGAS) THEN
         ICC=RC_FACE(IRC)%CELL_LIST(2,ISIDE+2); JCC=RC_FACE(IRC)%CELL_LIST(3,ISIDE+2)
         IG=CUT_CELL(ICC)%IG(JCC)
      ENDIF
   ENDIF
   IF (ICF>0) THEN
      IF (CUT_FACE(ICF)%CELL_LIST(1,ISIDE+2,JCF)==CC_FTYPE_CFGAS) THEN
         ICC=CUT_FACE(ICF)%CELL_LIST(2,ISIDE+2,JCF); JCC=CUT_FACE(ICF)%CELL_LIST(3,ISIDE+2,JCF)
         IG=CUT_CELL(ICC)%IG(JCC)
      ENDIF
   ENDIF
   CALL ADV_RHOZ(IG,IS,JS,KS,RZ)
   SIDE(ISIDE)=RZ
ENDDO
CALL ADV_CELL(AX,I,J,K,-1,IS,JS,KS)
IF (CELL(CELL_INDEX(IS,JS,KS))%SOLID .OR. CCVAR(IS,JS,KS,CC_CGSC)==CC_SOLID) THEN
   SIDE(-2)=SIDE(-1)
ELSE
   CALL ADV_RHOZ(0,IS,JS,KS,SIDE(-2))
ENDIF
CALL ADV_CELL(AX,I,J,K,2,IS,JS,KS)
IF (CELL(CELL_INDEX(IS,JS,KS))%SOLID .OR. CCVAR(IS,JS,KS,CC_CGSC)==CC_SOLID) THEN
   SIDE(1)=SIDE(0)
ELSE
   CALL ADV_RHOZ(0,IS,JS,KS,SIDE(1))
ENDIF
CALL ADV_GODUNOV(VEL,SIDE,FN)
END SUBROUTINE ADV_LIMIT_SPECIES

SUBROUTINE ADV_LIMIT_H(HSG,I,J,K,AX,IRC,ICF,JCF,VEL,FN,SIDE)
REAL(EB), ALLOCATABLE, INTENT(IN) :: HSG(:)
REAL(EB), INTENT(IN) :: VEL
INTEGER, INTENT(IN) :: I,J,K,AX,IRC,ICF,JCF
REAL(EB), INTENT(OUT) :: FN,SIDE(-2:1)
INTEGER :: ISIDE,IS,JS,KS,ICC,JCC,IG
REAL(EB) :: RH
SIDE(-2:1)=0._EB
DO ISIDE=-1,0
   CALL ADV_CELL(AX,I,J,K,1+ISIDE,IS,JS,KS)
   RH=0._EB
   IF (IRC>0) THEN
      ! RC regular side is Cartesian rho*h_s. A cut piece uses the GCELL cache, or the
      ! Cartesian host of that side when the piece has no GCELL.
      IG=0
      IF (RC_FACE(IRC)%CELL_LIST(1,ISIDE+2)==CC_FTYPE_CFGAS) THEN
         ICC=RC_FACE(IRC)%CELL_LIST(2,ISIDE+2); JCC=RC_FACE(IRC)%CELL_LIST(3,ISIDE+2)
         IG=CUT_CELL(ICC)%IG(JCC)
         IF (IG<1) IG=0
      ENDIF
      CALL ADV_RHOH(HSG,IG,IS,JS,KS,RH)
   ELSEIF (ICF>0) THEN
      IF (CUT_FACE(ICF)%CELL_LIST(1,ISIDE+2,JCF)==CC_FTYPE_CFGAS) THEN
         ICC=CUT_FACE(ICF)%CELL_LIST(2,ISIDE+2,JCF); JCC=CUT_FACE(ICF)%CELL_LIST(3,ISIDE+2,JCF)
         IG=CUT_CELL(ICC)%IG(JCC)
         IF (IG<1) IG=0
         CALL ADV_RHOH(HSG,IG,IS,JS,KS,RH)
      ELSE
         ! Not a cut piece: rho was initialized to -1 and h_s is evaluated at T=-1, ZZ=0.
         ZZ_GET=0._EB
         CALL GET_SENSIBLE_ENTHALPY(ZZ_GET,H_S,-1._EB)
         RH=-H_S
      ENDIF
   ENDIF
   SIDE(ISIDE)=RH
ENDDO
CALL ADV_CELL(AX,I,J,K,-1,IS,JS,KS)
IF (CELL(CELL_INDEX(IS,JS,KS))%SOLID .OR. CCVAR(IS,JS,KS,CC_CGSC)==CC_SOLID) THEN
   SIDE(-2)=SIDE(-1)
ELSE
   CALL ADV_RHOH(HSG,0,IS,JS,KS,SIDE(-2))
ENDIF
CALL ADV_CELL(AX,I,J,K,2,IS,JS,KS)
IF (CELL(CELL_INDEX(IS,JS,KS))%SOLID .OR. CCVAR(IS,JS,KS,CC_CGSC)==CC_SOLID) THEN
   SIDE(1)=SIDE(0)
ELSE
   CALL ADV_RHOH(HSG,0,IS,JS,KS,SIDE(1))
ENDIF
CALL ADV_GODUNOV(VEL,SIDE,FN)
END SUBROUTINE ADV_LIMIT_H

SUBROUTINE ADV_BOTH_SIDES(IRC,JCF,I,J,K,AX,FN,VEL,AF,SIDE,SGN,FOR_ZZ)
INTEGER, INTENT(IN) :: IRC,JCF,I,J,K,AX
REAL(EB), INTENT(IN) :: FN,VEL,AF,SIDE(-2:1),SGN
LOGICAL, INTENT(IN) :: FOR_ZZ
INTEGER :: ISIDE,IS,JS,KS,ICC,JCC,ICF
REAL(EB) :: FCT
LOGICAL :: IS_CUT
ICF=0
IF (IRC==0) ICF=FV%FACE%SRC_ICF(IF_)
DO ISIDE=-1,0
   FCT=-REAL(2*ISIDE+1,EB)
   CALL ADV_CELL(AX,I,J,K,1+ISIDE,IS,JS,KS)
   IS_CUT=.FALSE.; ICC=0; JCC=0
   IF (IRC>0) THEN
      IF (RC_FACE(IRC)%CELL_LIST(1,ISIDE+2)==CC_FTYPE_CFGAS) THEN
         IS_CUT=.TRUE.
         ICC=RC_FACE(IRC)%CELL_LIST(2,ISIDE+2); JCC=RC_FACE(IRC)%CELL_LIST(3,ISIDE+2)
      ELSEIF (RC_FACE(IRC)%CELL_LIST(1,ISIDE+2)/=CC_FTYPE_RGGAS) THEN
         CYCLE
      ENDIF
   ENDIF
   IF (IRC==0) THEN
      IF (CUT_FACE(ICF)%CELL_LIST(1,ISIDE+2,JCF)==CC_FTYPE_CFGAS) THEN
         IS_CUT=.TRUE.
         ICC=CUT_FACE(ICF)%CELL_LIST(2,ISIDE+2,JCF); JCC=CUT_FACE(ICF)%CELL_LIST(3,ISIDE+2,JCF)
      ELSE
         CYCLE
      ENDIF
   ENDIF
   IF (IS_CUT) THEN
      IF (ICC>MESHES(NM)%N_CUTCELL_MESH) CYCLE
   ENDIF
   CALL ADV_PUT(IS_CUT,ICC,JCC,IS,JS,KS,SGN*FCT*(FN-SIDE(ISIDE))*VEL*AF,FOR_ZZ)
ENDDO
END SUBROUTINE ADV_BOTH_SIDES

SUBROUTINE ADV_WALL_SPECIES(IRC,I,J,K,AX,IW,AF,VEL,RC_ROW)
INTEGER, INTENT(IN) :: IRC,I,J,K,AX,IW
REAL(EB), INTENT(IN) :: AF,VEL
LOGICAL, INTENT(IN) :: RC_ROW
INTEGER :: IOR,ISIDE,IS,JS,KS,ICC,JCC
REAL(EB) :: VELC,FN,RZ,FCT
LOGICAL :: IS_CUT
TYPE(WALL_TYPE), POINTER :: WC
TYPE(BOUNDARY_PROP1_TYPE), POINTER :: B1
TYPE(BOUNDARY_COORD_TYPE), POINTER :: BC
WC=>WALL(IW); B1=>BOUNDARY_PROP1(WC%B1_INDEX); BC=>BOUNDARY_COORD(WC%BC_INDEX)
IOR=BC%IOR
ISIDE=-1+(SIGN(1,IOR)+1)/2
FCT=-REAL(2*ISIDE+1,EB)
VELC=VEL
FN=B1%RHO_F*B1%ZZ_F(N)
IF (WC%BOUNDARY_TYPE==SOLID_BOUNDARY) THEN
   IF (PREDICTOR) VELC=-SIGN(1._EB,REAL(IOR,EB))*B1%U_NORMAL_S
   IF (CORRECTOR) VELC=-SIGN(1._EB,REAL(IOR,EB))*B1%U_NORMAL
ENDIF
IF (WC%BOUNDARY_TYPE==INTERPOLATED_BOUNDARY) THEN
   VELC=UVW_SAVE(IW)
   CALL GET_CCIFACE_SCALAR_LIM(AX,I,J,K,N,IW,PRFCT,FN)
ENDIF
CALL ADV_CELL(AX,I,J,K,1+ISIDE,IS,JS,KS)
IS_CUT=.FALSE.; ICC=0; JCC=0
IF (RC_ROW) THEN
   IF (RC_FACE(IRC)%CELL_LIST(1,ISIDE+2)==CC_FTYPE_CFGAS) THEN
      IS_CUT=.TRUE.
      ICC=RC_FACE(IRC)%CELL_LIST(2,ISIDE+2); JCC=RC_FACE(IRC)%CELL_LIST(3,ISIDE+2)
      CALL ADV_RHOZ(CUT_CELL(ICC)%IG(JCC),IS,JS,KS,RZ)
   ELSE
      CALL ADV_RHOZ(0,IS,JS,KS,RZ)
   ENDIF
ELSE
   CALL ADV_RHOZ(0,IS,JS,KS,RZ)
ENDIF
CALL ADV_PUT(IS_CUT,ICC,JCC,IS,JS,KS,FCT*(FN-RZ)*VELC*AF,.TRUE.)
END SUBROUTINE ADV_WALL_SPECIES

SUBROUTINE ADV_CF_WALL_SPECIES(ICF,JCF,I,J,K,AX,IW,AF)
INTEGER, INTENT(IN) :: ICF,JCF,I,J,K,AX,IW
REAL(EB), INTENT(IN) :: AF
INTEGER :: IOR,ISIDE,ICC,JCC,IG,IS,JS,KS
REAL(EB) :: VELC,FN,RZ,FCT
TYPE(WALL_TYPE), POINTER :: WC
TYPE(BOUNDARY_PROP1_TYPE), POINTER :: B1
TYPE(BOUNDARY_COORD_TYPE), POINTER :: BC
WC=>WALL(IW); B1=>BOUNDARY_PROP1(WC%B1_INDEX); BC=>BOUNDARY_COORD(WC%BC_INDEX)
IOR=BC%IOR; FN=B1%RHO_F*B1%ZZ_F(N)
IF (WC%BOUNDARY_TYPE==INTERPOLATED_BOUNDARY) CALL GET_CCIFACE_SCALAR_LIM(AX,I,J,K,N,IW,PRFCT,FN)
ISIDE=-1+(SIGN(1,IOR)+1)/2
FCT=-REAL(2*ISIDE+1,EB)
IF (WC%BOUNDARY_TYPE==SOLID_BOUNDARY .AND. .NOT.WC%THIN) THEN
   FCT=1._EB
   B1=>BOUNDARY_PROP1(CFACE(CUT_FACE(ICF)%CFACE_INDEX(JCF))%B1_INDEX)
   VELC=PRFCT*B1%U_NORMAL+(1._EB-PRFCT)*B1%U_NORMAL_S
ELSEIF (WC%BOUNDARY_TYPE==INTERPOLATED_BOUNDARY) THEN
   VELC=FV%FACE%VEL_SAVE(CUT_FACE(ICF)%FC(JCF))
ELSE
   VELC=GET_BOUNDARY_CUTFACE_VEL(ICF,JCF,PRFCT)
ENDIF
IF (CUT_FACE(ICF)%CELL_LIST(1,ISIDE+2,JCF)/=CC_FTYPE_CFGAS) RETURN
ICC=CUT_FACE(ICF)%CELL_LIST(2,ISIDE+2,JCF); JCC=CUT_FACE(ICF)%CELL_LIST(3,ISIDE+2,JCF)
IG=CUT_CELL(ICC)%IG(JCC)
IS=CUT_CELL(ICC)%IJK(IAXIS); JS=CUT_CELL(ICC)%IJK(JAXIS); KS=CUT_CELL(ICC)%IJK(KAXIS)
CALL ADV_RHOZ(IG,IS,JS,KS,RZ)
CALL ADV_PUT(.TRUE.,ICC,JCC,IS,JS,KS,FCT*(FN-RZ)*VELC*AF,.TRUE.)
END SUBROUTINE ADV_CF_WALL_SPECIES

SUBROUTINE ADV_INBOUNDARY(IF_,SGN,FOR_ZZ)
INTEGER, INTENT(IN) :: IF_
REAL(EB), INTENT(IN) :: SGN
LOGICAL, INTENT(IN) :: FOR_ZZ
INTEGER :: ICF,JCF,ICFA,ICC,JCC,I,J,K
REAL(EB) :: AF,VELC,FN,RZ
TYPE(BOUNDARY_PROP1_TYPE), POINTER :: B1
TYPE(CFACE_TYPE), POINTER :: CFA
ICF=FV%FACE%SRC_ICF(IF_); JCF=FV%FACE%SRC_JCF(IF_)
IF (ICF<1) RETURN
ICFA=CUT_FACE(ICF)%CFACE_INDEX(JCF)
IF (ICFA<INTERNAL_CFACE_CELLS_LB+1) RETURN
IF (ICFA>INTERNAL_CFACE_CELLS_LB+N_INTERNAL_CFACE_CELLS) RETURN
CFA=>CFACE(ICFA); B1=>BOUNDARY_PROP1(CFA%B1_INDEX)
ICC=CUT_FACE(ICF)%CELL_LIST(2,LOW_IND,JCF); JCC=CUT_FACE(ICF)%CELL_LIST(3,LOW_IND,JCF)
AF=CFA%AREA
VELC=PRFCT*B1%U_NORMAL+(1._EB-PRFCT)*B1%U_NORMAL_S
FN=B1%RHO_F*B1%ZZ_F(N)
I=CUT_CELL(ICC)%IJK(IAXIS); J=CUT_CELL(ICC)%IJK(JAXIS); K=CUT_CELL(ICC)%IJK(KAXIS)
CALL ADV_RHOZ(CUT_CELL(ICC)%IG(JCC),I,J,K,RZ)
CALL ADV_PUT(.TRUE.,ICC,JCC,I,J,K,SGN*(FN-RZ)*VELC*AF,FOR_ZZ)
END SUBROUTINE ADV_INBOUNDARY

SUBROUTINE ADV_REG_WALL_H(I,J,K,AX,IW,AF,VEL,HSG,SGN)
INTEGER, INTENT(IN) :: I,J,K,AX,IW
REAL(EB), ALLOCATABLE, INTENT(IN) :: HSG(:)
REAL(EB), INTENT(IN) :: AF,VEL,SGN
INTEGER :: IOR,ISIDE,IS,JS,KS
REAL(EB) :: VELC,VELC2,TMP_F,FN,RH,FCT
TYPE(WALL_TYPE), POINTER :: WC
TYPE(BOUNDARY_PROP1_TYPE), POINTER :: B1
TYPE(BOUNDARY_COORD_TYPE), POINTER :: BC
WC=>WALL(IW); B1=>BOUNDARY_PROP1(WC%B1_INDEX); BC=>BOUNDARY_COORD(WC%BC_INDEX)
IOR=BC%IOR; ISIDE=-1+(SIGN(1,IOR)+1)/2; FCT=-REAL(2*ISIDE+1,EB)
CALL ADV_CELL(AX,I,J,K,1+ISIDE,IS,JS,KS)
CALL ADV_RHOH(HSG,0,IS,JS,KS,RH)
VELC=VEL; VELC2=PRFCT*B1%U_NORMAL+(1._EB-PRFCT)*B1%U_NORMAL_S; TMP_F=B1%TMP_F
IF (WC%BOUNDARY_TYPE==SOLID_BOUNDARY) THEN
   VELC=-SIGN(1._EB,REAL(IOR,EB))*VELC2
   IF (VELC2>0._EB) TMP_F=TMP(BC%IIG,BC%JJG,BC%KKG)
ENDIF
ZZ_GET(1:N_TRACKED_SPECIES)=B1%ZZ_F(1:N_TRACKED_SPECIES)
CALL GET_SENSIBLE_ENTHALPY(ZZ_GET,H_S,TMP_F)
FN=B1%RHO_F*H_S
CALL ADV_PUT(.FALSE.,0,0,IS,JS,KS,SGN*FCT*(FN-RH)*VELC*AF,.FALSE.)
END SUBROUTINE ADV_REG_WALL_H

SUBROUTINE ADV_WALL_H(IRC,I,J,K,AX,IW,AF,VEL,HSG,SGN)
INTEGER, INTENT(IN) :: IRC,I,J,K,AX,IW
REAL(EB), ALLOCATABLE, INTENT(IN) :: HSG(:)
REAL(EB), INTENT(IN) :: AF,VEL,SGN
INTEGER :: IOR,ISIDE,IS,JS,KS,ICC,JCC,IG
REAL(EB) :: VELC,VELC2,TMP_F,FN,RH,FCT
LOGICAL :: IS_CUT
TYPE(WALL_TYPE), POINTER :: WC
TYPE(BOUNDARY_PROP1_TYPE), POINTER :: B1
TYPE(BOUNDARY_COORD_TYPE), POINTER :: BC
WC=>WALL(IW); B1=>BOUNDARY_PROP1(WC%B1_INDEX); BC=>BOUNDARY_COORD(WC%BC_INDEX)
IOR=BC%IOR; ISIDE=-1+(SIGN(1,IOR)+1)/2; FCT=-REAL(2*ISIDE+1,EB)
CALL ADV_CELL(AX,I,J,K,1+ISIDE,IS,JS,KS)
IS_CUT=.FALSE.; ICC=0; JCC=0; IG=0
IF (RC_FACE(IRC)%CELL_LIST(1,ISIDE+2)==CC_FTYPE_CFGAS) THEN
   IS_CUT=.TRUE.
   ICC=RC_FACE(IRC)%CELL_LIST(2,ISIDE+2); JCC=RC_FACE(IRC)%CELL_LIST(3,ISIDE+2)
   IG=CUT_CELL(ICC)%IG(JCC)
ENDIF
CALL ADV_RHOH(HSG,IG,IS,JS,KS,RH)
VELC=VEL; VELC2=PRFCT*B1%U_NORMAL+(1._EB-PRFCT)*B1%U_NORMAL_S; TMP_F=B1%TMP_F
IF (WC%BOUNDARY_TYPE==SOLID_BOUNDARY) THEN
   VELC=-SIGN(1._EB,REAL(IOR,EB))*VELC2
   IF (VELC2>0._EB) TMP_F=TMP(BC%IIG,BC%JJG,BC%KKG)
ENDIF
IF (WC%BOUNDARY_TYPE==INTERPOLATED_BOUNDARY) VELC=UVW_SAVE(IW)
ZZ_GET(1:N_TRACKED_SPECIES)=B1%ZZ_F(1:N_TRACKED_SPECIES)
CALL GET_SENSIBLE_ENTHALPY(ZZ_GET,H_S,TMP_F)
FN=B1%RHO_F*H_S
IF (WC%BOUNDARY_TYPE==INTERPOLATED_BOUNDARY) CALL GET_CCIFACE_SCALAR_LIM(AX,I,J,K,0,IW,PRFCT,FN)
CALL ADV_PUT(IS_CUT,ICC,JCC,IS,JS,KS,SGN*FCT*(FN-RH)*VELC*AF,.FALSE.)
END SUBROUTINE ADV_WALL_H

SUBROUTINE ADV_CF_WALL_H(ICF,JCF,I,J,K,AX,IW,AF,HSG,SGN)
INTEGER, INTENT(IN) :: ICF,JCF,I,J,K,AX,IW
REAL(EB), ALLOCATABLE, INTENT(IN) :: HSG(:)
REAL(EB), INTENT(IN) :: AF,SGN
INTEGER :: IOR,ISIDE,ICC,JCC,IG,IS,JS,KS
REAL(EB) :: VELC,VELC2,TMP_F,FN,RH,FCT
TYPE(WALL_TYPE), POINTER :: WC
TYPE(BOUNDARY_PROP1_TYPE), POINTER :: B1
TYPE(BOUNDARY_COORD_TYPE), POINTER :: BC
WC=>WALL(IW); B1=>BOUNDARY_PROP1(WC%B1_INDEX); BC=>BOUNDARY_COORD(WC%BC_INDEX)
IOR=BC%IOR
VELC2=PRFCT*B1%U_NORMAL+(1._EB-PRFCT)*B1%U_NORMAL_S; TMP_F=B1%TMP_F
IF (WC%BOUNDARY_TYPE==SOLID_BOUNDARY .AND. VELC2>0._EB) TMP_F=TMP(BC%IIG,BC%JJG,BC%KKG)
ZZ_GET(1:N_TRACKED_SPECIES)=B1%ZZ_F(1:N_TRACKED_SPECIES)
CALL GET_SENSIBLE_ENTHALPY(ZZ_GET,H_S,TMP_F)
FN=B1%RHO_F*H_S
IF (WC%BOUNDARY_TYPE==INTERPOLATED_BOUNDARY) CALL GET_CCIFACE_SCALAR_LIM(AX,I,J,K,0,IW,PRFCT,FN)
ISIDE=-1+(SIGN(1,IOR)+1)/2; FCT=-REAL(2*ISIDE+1,EB)
IF (WC%BOUNDARY_TYPE==SOLID_BOUNDARY .AND. .NOT.WC%THIN) THEN
   FCT=1._EB
   B1=>BOUNDARY_PROP1(CFACE(CUT_FACE(ICF)%CFACE_INDEX(JCF))%B1_INDEX)
   VELC=PRFCT*B1%U_NORMAL+(1._EB-PRFCT)*B1%U_NORMAL_S
ELSEIF (WC%BOUNDARY_TYPE==INTERPOLATED_BOUNDARY) THEN
   VELC=FV%FACE%VEL_SAVE(CUT_FACE(ICF)%FC(JCF))
ELSE
   VELC=GET_BOUNDARY_CUTFACE_VEL(ICF,JCF,PRFCT)
ENDIF
IF (CUT_FACE(ICF)%CELL_LIST(1,ISIDE+2,JCF)/=CC_FTYPE_CFGAS) RETURN
ICC=CUT_FACE(ICF)%CELL_LIST(2,ISIDE+2,JCF); JCC=CUT_FACE(ICF)%CELL_LIST(3,ISIDE+2,JCF)
IG=CUT_CELL(ICC)%IG(JCC)
IS=CUT_CELL(ICC)%IJK(IAXIS); JS=CUT_CELL(ICC)%IJK(JAXIS); KS=CUT_CELL(ICC)%IJK(KAXIS)
CALL ADV_RHOH(HSG,IG,IS,JS,KS,RH)
CALL ADV_PUT(.TRUE.,ICC,JCC,IS,JS,KS,SGN*FCT*(FN-RH)*VELC*AF,.FALSE.)
END SUBROUTINE ADV_CF_WALL_H

SUBROUTINE ADV_INBOUNDARY_H(IF_,HSG,SGN)
INTEGER, INTENT(IN) :: IF_
REAL(EB), ALLOCATABLE, INTENT(IN) :: HSG(:)
REAL(EB), INTENT(IN) :: SGN
INTEGER :: ICF,JCF,ICFA,ICC,JCC,I,J,K
REAL(EB) :: AF,VELC,TMP_F,FN,RH
TYPE(BOUNDARY_PROP1_TYPE), POINTER :: B1
TYPE(CFACE_TYPE), POINTER :: CFA
ICF=FV%FACE%SRC_ICF(IF_); JCF=FV%FACE%SRC_JCF(IF_)
IF (ICF<1) RETURN
ICFA=CUT_FACE(ICF)%CFACE_INDEX(JCF)
IF (ICFA<INTERNAL_CFACE_CELLS_LB+1) RETURN
IF (ICFA>INTERNAL_CFACE_CELLS_LB+N_INTERNAL_CFACE_CELLS) RETURN
CFA=>CFACE(ICFA); B1=>BOUNDARY_PROP1(CFA%B1_INDEX)
ICC=CUT_FACE(ICF)%CELL_LIST(2,LOW_IND,JCF); JCC=CUT_FACE(ICF)%CELL_LIST(3,LOW_IND,JCF)
AF=CFA%AREA; VELC=PRFCT*B1%U_NORMAL+(1._EB-PRFCT)*B1%U_NORMAL_S; TMP_F=B1%TMP_F
IF (VELC>0._EB) TMP_F=B1%TMP_G
ZZ_GET(1:N_TRACKED_SPECIES)=B1%ZZ_F(1:N_TRACKED_SPECIES)
CALL GET_SENSIBLE_ENTHALPY(ZZ_GET,H_S,TMP_F)
FN=B1%RHO_F*H_S
I=CUT_CELL(ICC)%IJK(IAXIS); J=CUT_CELL(ICC)%IJK(JAXIS); K=CUT_CELL(ICC)%IJK(KAXIS)
CALL ADV_RHOH(HSG,CUT_CELL(ICC)%IG(JCC),I,J,K,RH)
CALL ADV_PUT(.TRUE.,ICC,JCC,I,J,K,SGN*(FN-RH)*VELC*AF,.FALSE.)
END SUBROUTINE ADV_INBOUNDARY_H

! ----------------------- CC_DIFFUSIVE_HEAT_FLUXES ------------------------

SUBROUTINE CC_DIFFUSIVE_HEAT_FLUXES
! Sensible enthalpy carried by the species flux, one walk over external faces.
! Regular faces build it here. Cut and RC faces already stored it with the mass flux.
! SRC_IREG<1 is not a regular face. IRC>CC_NRCFACE_Z and ICF>N_CUTFACE_MESH are the
! old gas-loop ends. IRC>CC_NBBRCFACE_Z is the old boundary-RC loop. The CFACE index
! test is the old internal-CFACE loop.

INTEGER :: AX,IRC,ICF,JCF,ICFA,IW,ILO,JLO,KLO,IHI,JHI,KHI,IIG,JJG,KKG,N,IF_
REAL(EB) :: UN_P,H_SUM,TMP_G,H_S
LOGICAL :: WALL_BC
TYPE(WALL_TYPE), POINTER :: WC
TYPE(BOUNDARY_PROP1_TYPE), POINTER :: B1
TYPE(BOUNDARY_COORD_TYPE), POINTER :: BC
TYPE(CFACE_TYPE), POINTER :: CFA
REAL(EB) :: HLOCAL(1:N_TOTAL_SCALARS)

DO IF_=1,FV%FACE%N_INT
   IF (FV%FACE%ROLE(IF_) /= CC_FACE_ROLE_EXTERNAL) CYCLE
   WALL_BC = .FALSE.
   IW = FV%FACE%IWC(IF_)
   IF (IW > 0) THEN
      SELECT CASE(WALL(IW)%BOUNDARY_TYPE)
      CASE(INTERPOLATED_BOUNDARY,PERIODIC_BOUNDARY)
      CASE DEFAULT
         WALL_BC = .TRUE.
      END SELECT
   ENDIF
   IF (WALL_BC) CYCLE
   SELECT CASE(FV%FACE%FTYPE(IF_))
   CASE(CC_FTYPE_RGGAS)
      IF (FV%FACE%SRC_IREG(IF_) < 1) CYCLE
      AX = FV%FACE%X1AXIS(IF_)
      ILO = FV%FACE%IJK_FACE(IAXIS,IF_)
      JLO = FV%FACE%IJK_FACE(JAXIS,IF_)
      KLO = FV%FACE%IJK_FACE(KAXIS,IF_)
      IHI = ILO; JHI = JLO; KHI = KLO
      SELECT CASE(AX)
      CASE(IAXIS); IHI = ILO+1
      CASE(JAXIS); JHI = JLO+1
      CASE(KAXIS); KHI = KLO+1
      END SELECT
      TMP_G = 0.5_EB*(TMP(IHI,JHI,KHI)+TMP(ILO,JLO,KLO))
      H_SUM = 0._EB
      DO N=1,N_TOTAL_SCALARS
         CALL GET_SENSIBLE_ENTHALPY_Z(N,TMP_G,H_S)
         H_SUM = H_SUM + H_S*FV%FACE%DIFF_FLUX(N,IF_)
      ENDDO
      FV%FACE%DIFF_H_FLUX(IF_) = H_SUM
      CALL CC_FV_ADD_DIFFUSION_FACE(NM,IF_)
   CASE(CC_FTYPE_RCGAS)
      IRC = FV%FACE%SRC_IRC(IF_)
      IF (IRC > MESHES(NM)%CC_NRCFACE_Z) CYCLE
      CALL CC_FV_ADD_DIFFUSION_FACE(NM,IF_)
   CASE(CC_FTYPE_CFGAS)
      ICF = FV%FACE%SRC_ICF(IF_)
      IF (ICF > MESHES(NM)%N_CUTFACE_MESH) CYCLE
      IF (CUT_FACE(ICF)%STATUS /= CC_GASPHASE) CYCLE
      CALL CC_FV_ADD_DIFFUSION_FACE(NM,IF_)
   END SELECT
ENDDO

DO IF_=1,FV%FACE%N_INT
   IF (FV%FACE%ROLE(IF_) /= CC_FACE_ROLE_EXTERNAL) CYCLE
   SELECT CASE(FV%FACE%FTYPE(IF_))
   CASE(CC_FTYPE_CFINB)
      ICF = FV%FACE%SRC_ICF(IF_)
      JCF = FV%FACE%SRC_JCF(IF_)
      IF (ICF > MESHES(NM)%N_CUTFACE_MESH) CYCLE
      ICFA = CUT_FACE(ICF)%CFACE_INDEX(JCF)
      IF (ICFA < INTERNAL_CFACE_CELLS_LB+1) CYCLE
      IF (ICFA > INTERNAL_CFACE_CELLS_LB+N_INTERNAL_CFACE_CELLS) CYCLE
      CFA => CFACE(ICFA)
      B1 => BOUNDARY_PROP1(CFA%B1_INDEX)
      UN_P = PRFCT*B1%U_NORMAL+(1._EB-PRFCT)*B1%U_NORMAL_S
      TMP_G = B1%TMP_F
      IF (UN_P > 0._EB) TMP_G = B1%TMP_G
      DO N=1,N_TOTAL_SCALARS
         CALL GET_SENSIBLE_ENTHALPY_Z(N,TMP_G,H_S)
         HLOCAL(N) = H_S*FV%FACE%DIFF_FLUX(N,IF_)
      ENDDO
      FV%FACE%DIFF_H_FLUX(IF_) = SUM(HLOCAL(1:N_TOTAL_SCALARS))
      CALL CC_FV_ADD_DIFFUSION_FACE(NM,IF_)
   CASE(CC_FTYPE_RGGAS)
      IF (FV%FACE%SRC_IREG(IF_) < 1) CYCLE
      IW = FV%FACE%IWC(IF_)
      IF (IW < 1) CYCLE
      SELECT CASE(WALL(IW)%BOUNDARY_TYPE)
      CASE(NULL_BOUNDARY,INTERPOLATED_BOUNDARY,PERIODIC_BOUNDARY)
         CYCLE
      END SELECT
      WC => WALL(IW)
      B1 => BOUNDARY_PROP1(WC%B1_INDEX)
      BC => BOUNDARY_COORD(WC%BC_INDEX)
      IIG = BC%IIG; JJG = BC%JJG; KKG = BC%KKG
      AX = FV%FACE%X1AXIS(IF_)
      ILO = FV%FACE%IJK_FACE(IAXIS,IF_)
      JLO = FV%FACE%IJK_FACE(JAXIS,IF_)
      KLO = FV%FACE%IJK_FACE(KAXIS,IF_)
      UN_P = PRFCT*B1%U_NORMAL+(1._EB-PRFCT)*B1%U_NORMAL_S
      TMP_G = B1%TMP_F
      IF (WC%BOUNDARY_TYPE==SOLID_BOUNDARY) THEN
         IF (UN_P > 0._EB) TMP_G = TMP(IIG,JJG,KKG)
      ENDIF
      IF (WC%BOUNDARY_TYPE==OPEN_BOUNDARY) THEN
         IHI = ILO; JHI = JLO; KHI = KLO
         SELECT CASE(AX)
         CASE(IAXIS); IHI = ILO+1
         CASE(JAXIS); JHI = JLO+1
         CASE(KAXIS); KHI = KLO+1
         END SELECT
         TMP_G = 0.5_EB*(TMP(IHI,JHI,KHI)+TMP(ILO,JLO,KLO))
      ENDIF
      H_SUM = 0._EB
      DO N=1,N_TOTAL_SCALARS
         CALL GET_SENSIBLE_ENTHALPY_Z(N,TMP_G,H_S)
         H_SUM = H_SUM + H_S*FV%FACE%DIFF_FLUX(N,IF_)
      ENDDO
      FV%FACE%DIFF_H_FLUX(IF_) = H_SUM
      CALL CC_FV_ADD_DIFFUSION_FACE(NM,IF_)
   CASE(CC_FTYPE_RCGAS)
      IRC = FV%FACE%SRC_IRC(IF_)
      IF (IRC > MESHES(NM)%CC_NBBRCFACE_Z) CYCLE
      IW = RC_FACE(IRC)%IWC
      IF (IW < 1) CYCLE
      SELECT CASE(WALL(IW)%BOUNDARY_TYPE)
      CASE(NULL_BOUNDARY,INTERPOLATED_BOUNDARY,PERIODIC_BOUNDARY)
         CYCLE
      END SELECT
      CALL CC_FV_ADD_DIFFUSION_FACE(NM,IF_)
   CASE(CC_FTYPE_CFGAS)
      ICF = FV%FACE%SRC_ICF(IF_)
      IF (ICF > MESHES(NM)%N_CUTFACE_MESH) CYCLE
      IF (CUT_FACE(ICF)%STATUS /= CC_GASPHASE) CYCLE
      IF (CUT_FACE(ICF)%IWC < 1) CYCLE
      IW = CUT_FACE(ICF)%IWC
      SELECT CASE(WALL(IW)%BOUNDARY_TYPE)
      CASE(NULL_BOUNDARY,INTERPOLATED_BOUNDARY,PERIODIC_BOUNDARY)
         CYCLE
      END SELECT
      CALL CC_FV_ADD_DIFFUSION_FACE(NM,IF_)
   END SELECT
ENDDO

END SUBROUTINE CC_DIFFUSIVE_HEAT_FLUXES





! ----------------------- CC_CONDUCTION_HEAT_FLUX --------------------------



SUBROUTINE CC_CONDUCTION_HEAT_FLUX
! k grad(T) on gas faces and wall heat flux on wall faces, one walk each.
! The flux is added to the CV here. Nothing else reads a stored conduction flux.
! A regular gas face divides by DX, DY or DZ. Cut and RC faces keep the face spacing.

INTEGER :: AX,IRC,ICF,JCF,ICFA,IW,ILO,JLO,KLO,IHI,JHI,KHI,II,JJ,KK
INTEGER :: IIG,JJG,KKG,IOR,ISIDE,ICC,JCC,IG,IGL,IGH
REAL(EB) :: KPV(-1:0),FD,DL,KP_GAS,AF,X1F
REAL(EB), ALLOCATABLE :: KG(:)
LOGICAL :: WALL_BC
TYPE(WALL_TYPE), POINTER :: WC
TYPE(BOUNDARY_PROP1_TYPE), POINTER :: B1
TYPE(BOUNDARY_COORD_TYPE), POINTER :: BC
TYPE(CFACE_TYPE), POINTER :: CFA

IF (FV%GCELL%N>0) THEN
   ALLOCATE(KG(FV%GCELL%N))
   DO IG=1,FV%GCELL%N
      II=FV%GCELL%IJK(IAXIS,IG); JJ=FV%GCELL%IJK(JAXIS,IG); KK=FV%GCELL%IJK(KAXIS,IG)
      IF (FV%GCELL%CELL_TYPE(IG)==CC_GCELL_CUT) THEN
         ICC=FV%GCELL%ICC(IG); JCC=FV%GCELL%JCC(IG)
         TMPV(-1)=GET_CUTCELL_TMP(NM,ICC,JCC)
         CALL GET_CUTCELL_ZZV(NM,ICC,JCC,PRFCT,ZZ_GET)
      ELSE
         ZZ_GET(1:N_TRACKED_SPECIES)=ZZP(II,JJ,KK,1:N_TRACKED_SPECIES); TMPV(-1)=TMP(II,JJ,KK)
      ENDIF
      CALL GET_CC_CELL_CONDUCTIVITY(ZZ_GET,MU(II,JJ,KK),MU_DNS(II,JJ,KK),TMPV(-1),KG(IG))
   ENDDO
ENDIF

! Gas faces: the old regular, RC (1:CC_NRCFACE_Z) and gas cut-face loops.
! SRC_IREG<1 is not in that regular-face list. IRC>CC_NRCFACE_Z and ICF>N_CUTFACE_MESH
! are those loops' ends. ICC>N_CUTCELL_MESH is their guard-cell skip. A non-external
! row is dropped by CC_FV_ADD_CONDUCTION_FACE, so it is not computed here.
DO IF_=1,FV%FACE%N_INT
   IF (FV%FACE%ROLE(IF_) /= CC_FACE_ROLE_EXTERNAL) CYCLE
   WALL_BC = .FALSE.
   IW = FV%FACE%IWC(IF_)
   IF (IW > 0) THEN
      SELECT CASE(WALL(IW)%BOUNDARY_TYPE)
      CASE(INTERPOLATED_BOUNDARY,PERIODIC_BOUNDARY)
      CASE DEFAULT
         WALL_BC = .TRUE.
      END SELECT
   ENDIF
   IF (WALL_BC) CYCLE
   SELECT CASE(FV%FACE%FTYPE(IF_))
   CASE(CC_FTYPE_RGGAS)
      IF (FV%FACE%SRC_IREG(IF_) < 1) CYCLE
      AX = FV%FACE%X1AXIS(IF_)
      ILO = FV%FACE%IJK_FACE(IAXIS,IF_)
      JLO = FV%FACE%IJK_FACE(JAXIS,IF_)
      KLO = FV%FACE%IJK_FACE(KAXIS,IF_)
      IHI = ILO; JHI = JLO; KHI = KLO
      SELECT CASE(AX)
      CASE(IAXIS); IHI = ILO+1; DL = DX(ILO)
      CASE(JAXIS); JHI = JLO+1; DL = DY(JLO)
      CASE(KAXIS); KHI = KLO+1; DL = DZ(KLO)
      END SELECT
      TMPV(-1) = TMP(ILO,JLO,KLO)
      TMPV(0)  = TMP(IHI,JHI,KHI)
      IGL=FV%FACE%OWNER_GCELL(IF_); IGH=FV%FACE%NBR_GCELL(IF_)
      IF (FV%FACE%NVEC(AX,IF_)<0._EB) THEN; IG=IGL; IGL=IGH; IGH=IG; ENDIF
      CALL K_OF(KG,IGL,ILO,JLO,KLO,TMPV(-1),KPV(-1))
      CALL K_OF(KG,IGH,IHI,JHI,KHI,TMPV(0),KPV(0))
      FD = 0.5_EB*(KPV(-1)+KPV(0))*(TMPV(0)-TMPV(-1))/DL
      CALL CC_FV_ADD_CONDUCTION_FACE(NM,IF_,FV%FACE%NVEC(AX,IF_)*FD)
   CASE(CC_FTYPE_RCGAS)
      IRC = FV%FACE%SRC_IRC(IF_)
      IF (IRC > MESHES(NM)%CC_NRCFACE_Z) CYCLE
      AX = RC_FACE(IRC)%IJK(KAXIS+1)
      ILO = RC_FACE(IRC)%IJK(IAXIS)
      JLO = RC_FACE(IRC)%IJK(JAXIS)
      KLO = RC_FACE(IRC)%IJK(KAXIS)
      IHI = ILO; JHI = JLO; KHI = KLO
      SELECT CASE(AX)
      CASE(IAXIS); IHI = ILO+1
      CASE(JAXIS); JHI = JLO+1
      CASE(KAXIS); KHI = KLO+1
      END SELECT
      CALL CC_FV_SET_DIFFUSION_GEOM(NM,IF_,IDX,CCM1,CCP1)
      DO ISIDE=-1,0
         ZZ_GET(1:N_TRACKED_SPECIES) = 0._EB
         TMPV(ISIDE) = -1._EB
         IF (ISIDE == -1) THEN
            II = ILO; JJ = JLO; KK = KLO
         ELSE
            II = IHI; JJ = JHI; KK = KHI
         ENDIF
         IG=-1
         SELECT CASE(RC_FACE(IRC)%CELL_LIST(1,ISIDE+2))
         CASE(CC_FTYPE_RGGAS)
            TMPV(ISIDE)=TMP(II,JJ,KK)
            IG=FV%FACE%NBR_GCELL(IF_)
         CASE(CC_FTYPE_CFGAS)
            ICC=RC_FACE(IRC)%CELL_LIST(2,ISIDE+2); JCC=RC_FACE(IRC)%CELL_LIST(3,ISIDE+2)
            TMPV(ISIDE)=GET_CUTCELL_TMP(NM,ICC,JCC)
            IG=CUT_CELL(ICC)%IG(JCC)
         END SELECT
         CALL K_OF(KG,IG,II,JJ,KK,TMPV(ISIDE),KPV(ISIDE))
      ENDDO
      FD = (CCM1*KPV(-1)+CCP1*KPV(0))*(TMPV(0)-TMPV(-1))*IDX
      CALL CC_FV_ADD_CONDUCTION_FACE(NM,IF_,FV%FACE%NVEC(FV%FACE%X1AXIS(IF_),IF_)*FD)
   CASE(CC_FTYPE_CFGAS)
      ICF = FV%FACE%SRC_ICF(IF_)
      JCF = FV%FACE%SRC_JCF(IF_)
      IF (ICF > MESHES(NM)%N_CUTFACE_MESH) CYCLE
      IF (CUT_FACE(ICF)%STATUS /= CC_GASPHASE) CYCLE
      AX = CUT_FACE(ICF)%IJK(KAXIS+1)
      ILO = CUT_FACE(ICF)%IJK(IAXIS)
      JLO = CUT_FACE(ICF)%IJK(JAXIS)
      KLO = CUT_FACE(ICF)%IJK(KAXIS)
      IHI = ILO; JHI = JLO; KHI = KLO
      SELECT CASE(AX)
      CASE(IAXIS); IHI = ILO+1
      CASE(JAXIS); JHI = JLO+1
      CASE(KAXIS); KHI = KLO+1
      END SELECT
      CALL CC_FV_SET_DIFFUSION_GEOM(NM,IF_,IDX,CCM1,CCP1)
      DO ISIDE=-1,0
         ZZ_GET(1:N_TRACKED_SPECIES) = 0._EB
         TMPV(ISIDE) = -1._EB
         IF (ISIDE == -1) THEN
            II = ILO; JJ = JLO; KK = KLO
         ELSE
            II = IHI; JJ = JHI; KK = KHI
         ENDIF
         IG=-1
         SELECT CASE(CUT_FACE(ICF)%CELL_LIST(1,ISIDE+2,JCF))
         CASE(CC_FTYPE_CFGAS)
            ICC=CUT_FACE(ICF)%CELL_LIST(2,ISIDE+2,JCF); JCC=CUT_FACE(ICF)%CELL_LIST(3,ISIDE+2,JCF)
            TMPV(ISIDE)=GET_CUTCELL_TMP(NM,ICC,JCC)
            IG=CUT_CELL(ICC)%IG(JCC)
         END SELECT
         CALL K_OF(KG,IG,II,JJ,KK,TMPV(ISIDE),KPV(ISIDE))
      ENDDO
      FD = (CCM1*KPV(-1)+CCP1*KPV(0))*(TMPV(0)-TMPV(-1))*IDX
      CALL CC_FV_ADD_CONDUCTION_FACE(NM,IF_,FV%FACE%NVEC(FV%FACE%X1AXIS(IF_),IF_)*FD)
   END SELECT
ENDDO

! Wall faces. IRC>CC_NBBRCFACE_Z is the old boundary-RC loop. The CFACE index test is
! the old internal-CFACE loop. Open boundaries recompute the gas gradient.
DO IF_=1,FV%FACE%N_INT
   IF (FV%FACE%ROLE(IF_) /= CC_FACE_ROLE_EXTERNAL) CYCLE
   SELECT CASE(FV%FACE%FTYPE(IF_))
   CASE(CC_FTYPE_CFINB)
      ICF = FV%FACE%SRC_ICF(IF_)
      JCF = FV%FACE%SRC_JCF(IF_)
      IF (ICF > MESHES(NM)%N_CUTFACE_MESH) CYCLE
      ICFA = CUT_FACE(ICF)%CFACE_INDEX(JCF)
      IF (ICFA < INTERNAL_CFACE_CELLS_LB+1) CYCLE
      IF (ICFA > INTERNAL_CFACE_CELLS_LB+N_INTERNAL_CFACE_CELLS) CYCLE
      CFA => CFACE(ICFA)
      B1 => BOUNDARY_PROP1(CFA%B1_INDEX)
      CALL CC_FV_ADD_CONDUCTION_FACE(NM,IF_,-B1%AREA_ADJUST*B1%Q_CON_F)
   CASE(CC_FTYPE_RGGAS)
      IF (FV%FACE%SRC_IREG(IF_) < 1) CYCLE
      IW = FV%FACE%IWC(IF_)
      IF (IW < 1) CYCLE
      SELECT CASE(WALL(IW)%BOUNDARY_TYPE)
      CASE(NULL_BOUNDARY,INTERPOLATED_BOUNDARY,PERIODIC_BOUNDARY)
         CYCLE
      END SELECT
      AX = FV%FACE%X1AXIS(IF_)
      WC => WALL(IW)
      B1 => BOUNDARY_PROP1(WC%B1_INDEX)
      BC => BOUNDARY_COORD(WC%BC_INDEX)
      IIG = BC%IIG; JJG = BC%JJG; KKG = BC%KKG
      IF (WC%BOUNDARY_TYPE == OPEN_BOUNDARY) THEN
         CALL K_OF(KG,FV%FACE%OWNER_GCELL(IF_),IIG,JJG,KKG,TMP(IIG,JJG,KKG),KP_GAS)
         ILO = FV%FACE%IJK_FACE(IAXIS,IF_)
         JLO = FV%FACE%IJK_FACE(JAXIS,IF_)
         KLO = FV%FACE%IJK_FACE(KAXIS,IF_)
         SELECT CASE(AX)
         CASE(IAXIS); FD = KP_GAS*(TMP(ILO+1,JLO,KLO)-TMP(ILO,JLO,KLO))*RDXN(ILO)
         CASE(JAXIS); FD = KP_GAS*(TMP(ILO,JLO+1,KLO)-TMP(ILO,JLO,KLO))*RDYN(JLO)
         CASE(KAXIS); FD = KP_GAS*(TMP(ILO,JLO,KLO+1)-TMP(ILO,JLO,KLO))*RDZN(KLO)
         END SELECT
         CALL CC_FV_ADD_CONDUCTION_FACE(NM,IF_,FV%FACE%NVEC(AX,IF_)*FD)
      ELSE
         SELECT CASE(AX)
         CASE(IAXIS); AF = DY(JJG)*DZ(KKG)
         CASE(JAXIS); AF = DX(IIG)*DZ(KKG)
         CASE(KAXIS); AF = DX(IIG)*DY(JJG)
         END SELECT
         FD = -B1%AREA_ADJUST*B1%Q_CON_F+B1%Q_LEAK*DX(IIG)*DY(JJG)*DZ(KKG)/AF
         CALL CC_FV_ADD_CONDUCTION_FACE(NM,IF_,FD)
      ENDIF
   CASE(CC_FTYPE_RCGAS)
      IRC = FV%FACE%SRC_IRC(IF_)
      IF (IRC > MESHES(NM)%CC_NBBRCFACE_Z) CYCLE
      IW = RC_FACE(IRC)%IWC
      IF (IW < 1) CYCLE
      SELECT CASE(WALL(IW)%BOUNDARY_TYPE)
      CASE(NULL_BOUNDARY,INTERPOLATED_BOUNDARY,PERIODIC_BOUNDARY)
         CYCLE
      END SELECT
      AX = RC_FACE(IRC)%IJK(KAXIS+1)
      WC => WALL(IW)
      B1 => BOUNDARY_PROP1(WC%B1_INDEX)
      BC => BOUNDARY_COORD(WC%BC_INDEX)
      IIG = BC%IIG; JJG = BC%JJG; KKG = BC%KKG
      IOR = BC%IOR
      ISIDE = -1+(SIGN(1,IOR)+1)/2
      SELECT CASE(AX)
      CASE(IAXIS); AF = DY(JJG)*DZ(KKG)
      CASE(JAXIS); AF = DX(IIG)*DZ(KKG)
      CASE(KAXIS); AF = DX(IIG)*DY(JJG)
      END SELECT
      SELECT CASE(RC_FACE(IRC)%CELL_LIST(1,ISIDE+2))
      CASE(CC_FTYPE_CFGAS)
         ICC = RC_FACE(IRC)%CELL_LIST(2,ISIDE+2)
         IF (ICC > MESHES(NM)%N_CUTCELL_MESH) CYCLE
         JCC = RC_FACE(IRC)%CELL_LIST(3,ISIDE+2)
         FD = -B1%AREA_ADJUST*B1%Q_CON_F+B1%Q_LEAK*CUT_CELL(ICC)%VOLUME(JCC)/AF
         CALL CC_FV_ADD_CONDUCTION_FACE(NM,IF_,FD)
      END SELECT
   CASE(CC_FTYPE_CFGAS)
      ICF = FV%FACE%SRC_ICF(IF_)
      JCF = FV%FACE%SRC_JCF(IF_)
      IF (ICF > MESHES(NM)%N_CUTFACE_MESH) CYCLE
      IF (CUT_FACE(ICF)%STATUS /= CC_GASPHASE .OR. CUT_FACE(ICF)%IWC < 1) CYCLE
      IW = CUT_FACE(ICF)%IWC
      SELECT CASE(WALL(IW)%BOUNDARY_TYPE)
      CASE(NULL_BOUNDARY,INTERPOLATED_BOUNDARY,PERIODIC_BOUNDARY)
         CYCLE
      END SELECT
      WC => WALL(IW)
      B1 => BOUNDARY_PROP1(WC%B1_INDEX)
      IOR = BOUNDARY_COORD(WC%BC_INDEX)%IOR
      ISIDE = -1+(SIGN(1,IOR)+1)/2
      AX = CUT_FACE(ICF)%IJK(KAXIS+1)
      IF (WC%BOUNDARY_TYPE == OPEN_BOUNDARY) THEN
         SELECT CASE(CUT_FACE(ICF)%CELL_LIST(1,ISIDE+2,JCF))
         CASE(CC_FTYPE_CFGAS)
            X1F = CUT_FACE(ICF)%XYZCEN(AX,JCF)
            IF (IOR > 0) THEN
               IDX = 0.5_EB/(CUT_FACE(ICF)%XCENHIGH(AX,JCF)-X1F)
            ELSE
               IDX = 0.5_EB/(X1F-CUT_FACE(ICF)%XCENLOW(AX,JCF))
            ENDIF
            ILO = CUT_FACE(ICF)%IJK(IAXIS)
            JLO = CUT_FACE(ICF)%IJK(JAXIS)
            KLO = CUT_FACE(ICF)%IJK(KAXIS)
            IHI = ILO; JHI = JLO; KHI = KLO
            SELECT CASE(AX)
            CASE(IAXIS); IHI = ILO+1
            CASE(JAXIS); JHI = JLO+1
            CASE(KAXIS); KHI = KLO+1
            END SELECT
            KPV(-1) = MU(ILO,JLO,KLO)*CPOPR
            KPV(0)  = MU(IHI,JHI,KHI)*CPOPR
            TMPV(-1) = TMP(ILO,JLO,KLO)
            TMPV(0)  = TMP(IHI,JHI,KHI)
            ICC = CUT_FACE(ICF)%CELL_LIST(2,ISIDE+2,JCF)
            IF (ICC > MESHES(NM)%N_CUTCELL_MESH) CYCLE
            JCC = CUT_FACE(ICF)%CELL_LIST(3,ISIDE+2,JCF)
            TMPV(ISIDE) = GET_CUTCELL_TMP(NM,ICC,JCC)
            IF (ISIDE == -1) THEN
               II = ILO; JJ = JLO; KK = KLO
            ELSE
               II = IHI; JJ = JHI; KK = KHI
            ENDIF
            CALL K_OF(KG,FV%FACE%OWNER_GCELL(IF_),II,JJ,KK,TMPV(ISIDE),KPV(ISIDE))
            FD = 0.5_EB*(KPV(-1)+KPV(0))*(TMPV(0)-TMPV(-1))*IDX
            CALL CC_FV_ADD_CONDUCTION_FACE(NM,IF_,FV%FACE%NVEC(FV%FACE%X1AXIS(IF_),IF_)*FD)
         END SELECT
      ELSE
         SELECT CASE(CUT_FACE(ICF)%CELL_LIST(1,ISIDE+2,JCF))
         CASE(CC_FTYPE_CFGAS)
            AF = CUT_FACE(ICF)%AREA(JCF)
            ICC = CUT_FACE(ICF)%CELL_LIST(2,ISIDE+2,JCF)
            IF (ICC > MESHES(NM)%N_CUTCELL_MESH) CYCLE
            JCC = CUT_FACE(ICF)%CELL_LIST(3,ISIDE+2,JCF)
            FD = -B1%AREA_ADJUST*B1%Q_CON_F+B1%Q_LEAK*CUT_CELL(ICC)%VOLUME(JCC)/AF
            CALL CC_FV_ADD_CONDUCTION_FACE(NM,IF_,FD)
         END SELECT
      ENDIF
   END SELECT
ENDDO

END SUBROUTINE CC_CONDUCTION_HEAT_FLUX

SUBROUTINE K_OF(KG,IG,I,J,K,TMPS,KP)
! IG>=1 reads KG. IG=0: Cartesian cell with no GCELL. IG<0: non-gas side, ZZ and T already set.
REAL(EB), ALLOCATABLE, INTENT(IN) :: KG(:)
INTEGER, INTENT(IN) :: IG,I,J,K
REAL(EB), INTENT(IN) :: TMPS
REAL(EB), INTENT(OUT) :: KP
IF (IG>=1) THEN; KP=KG(IG); RETURN; ENDIF
IF (IG==0) ZZ_GET(1:N_TRACKED_SPECIES)=ZZP(I,J,K,1:N_TRACKED_SPECIES)
CALL GET_CC_CELL_CONDUCTIVITY(ZZ_GET,MU(I,J,K),MU_DNS(I,J,K),TMPS,KP)
END SUBROUTINE K_OF






END SUBROUTINE CC_DIVERGENCE_PART_1


! ------------------------ GET_CC_CELL_DIFFUSIVITY -------------------------

SUBROUTINE GET_CC_CELL_DIFFUSIVITY(RHO_CELL,D_Z_N,MU_CELL,MU_DNS_CELL,TMP_CELL,D_Z_TEMP)

USE MATH_FUNCTIONS, ONLY: INTERPOLATE1D_UNIFORM
USE MANUFACTURED_SOLUTIONS, ONLY: DIFF_MMS

REAL(EB), INTENT(IN) :: RHO_CELL,D_Z_N(0:I_MAX_TEMP),MU_CELL,MU_DNS_CELL,TMP_CELL
REAL(EB), INTENT(OUT):: D_Z_TEMP

REAL(EB) :: D_Z_TEMP_DNS

SELECT CASE(SIM_MODE)
CASE(LES_MODE)
   CALL INTERPOLATE1D_UNIFORM(LBOUND(D_Z_N,1),D_Z_N,TMP_CELL,D_Z_TEMP_DNS)
   D_Z_TEMP = D_Z_TEMP_DNS + MAX(0._EB,MU_CELL-MU_DNS_CELL)*RSC_T/RHO_CELL
CASE(DNS_MODE)
   IF(PERIODIC_TEST==7) THEN
      D_Z_TEMP = DIFF_MMS / RHO_CELL
   ELSE
      CALL INTERPOLATE1D_UNIFORM(LBOUND(D_Z_N,1),D_Z_N,TMP_CELL,D_Z_TEMP)
   ENDIF
CASE DEFAULT
   D_Z_TEMP = MU_CELL*RSC_T/RHO_CELL ! VLES
END SELECT

RETURN
END SUBROUTINE GET_CC_CELL_DIFFUSIVITY

! ----------------------- GET_CC_CELL_CONDUCTIVITY -------------------------

SUBROUTINE GET_CC_CELL_CONDUCTIVITY(ZZ_CELL,MU_CELL,MU_DNS_CELL,TMP_CELL,KP_CELL)

USE PHYSICAL_FUNCTIONS, ONLY: GET_CONDUCTIVITY,GET_SPECIFIC_HEAT

REAL(EB), INTENT(IN)  :: ZZ_CELL(1:N_TRACKED_SPECIES),MU_CELL,MU_DNS_CELL,TMP_CELL
REAL(EB), INTENT(OUT) :: KP_CELL

! Local Vars:
REAL(EB) :: CP_CELL

IF (SIM_MODE==DNS_MODE .OR. SIM_MODE==LES_MODE) THEN
   CALL GET_CONDUCTIVITY(ZZ_CELL,KP_CELL,TMP_CELL)
   IF (SIM_MODE==LES_MODE) THEN
      IF (.NOT.CONSTANT_SPECIFIC_HEAT_RATIO) THEN
         CALL GET_SPECIFIC_HEAT(ZZ_CELL,CP_CELL,TMP_CELL)
         KP_CELL = KP_CELL + MAX(0._EB,MU_CELL-MU_DNS_CELL)*CP_CELL*RPR_T
      ELSE
         KP_CELL = KP_CELL + MAX(0._EB,MU_CELL-MU_DNS_CELL)*CPOPR
      ENDIF
   ENDIF
ELSE ! VLES
   KP_CELL = MU_CELL*CPOPR
ENDIF

RETURN
END SUBROUTINE GET_CC_CELL_CONDUCTIVITY

! ----------------------- CC_DIFFUSIVE_MASS_FLUXES -------------------------

SUBROUTINE CC_DIFFUSIVE_MASS_FLUXES(NM)
! One walk over external faces. Cut-cell state is the CV array picked once
! above the walk; IG<1 reads the Cartesian host. No GET_CUTCELL call in here.

USE PHYSICAL_FUNCTIONS, ONLY: GET_SENSIBLE_ENTHALPY_Z

INTEGER, INTENT(IN) :: NM

INTEGER :: N,I,J,K,X1AXIS,ISIDE,IFACE,ICC,JCC,ICF,JCF,IF_,IRC,IW
INTEGER :: AX,ILO,JLO,KLO,IHI,JHI,KHI,IG,II,JJ,KK,IS,JS,KS,N_ZZ_MAX
REAL(EB), POINTER, DIMENSION(:,:,:) :: RHOP
REAL(EB), POINTER, DIMENSION(:,:,:,:) :: ZZP
REAL(EB), POINTER, DIMENSION(:) :: CVRHO,CVTMP
REAL(EB), POINTER, DIMENSION(:,:) :: CVZZ
REAL(EB) :: CCM1,CCP1,IDX,DIFF_FACE,D_Z_TEMP(-1:0)
REAL(EB) :: RHOPV(-1:0),TMPV(-1:0),ZZPV(-1:0),X1F,TMP_FACE,RHO_D_DZDN
REAL(EB) :: FLUX(1:N_TOTAL_SCALARS),ZZF(1:N_TOTAL_SCALARS)
REAL(EB) :: ZZM(-1:0,1:N_TOTAL_SCALARS)
REAL(EB) :: ZZ_GET(1:N_TRACKED_SPECIES),RHO_D_DZDN_GET(1:N_TRACKED_SPECIES)
TYPE(CC_FV_TYPE), POINTER :: FV
TYPE(CFACE_TYPE), POINTER :: CFA

IF (PREDICTOR) THEN
   RHOP => RHOS
   ZZP => ZZS
   CVRHO => MESHES(NM)%FV%CV%RHOS
   CVZZ => MESHES(NM)%FV%CV%ZZS
ELSE
   RHOP => RHO
   ZZP => ZZ
   CVRHO => MESHES(NM)%FV%CV%RHO
   CVZZ => MESHES(NM)%FV%CV%ZZ
ENDIF
CVTMP => MESHES(NM)%FV%CV%TMP
FV => MESHES(NM)%FV

! Gas faces. A regular face keeps the Cartesian flux and gathers the sum into
! its largest species. IRC>CC_NRCFACE_Z and ICF>N_CUTFACE_MESH are the old
! gas-loop ends. SRC_IREG<1 is not a regular face.
DO IF_=1,FV%FACE%N_INT
   IF (FV%FACE%ROLE(IF_) /= CC_FACE_ROLE_EXTERNAL) CYCLE
   SELECT CASE(FV%FACE%FTYPE(IF_))
   CASE(CC_FTYPE_RGGAS)
      IW = FV%FACE%IWC(IF_)
      IF (IW > 0) THEN
         SELECT CASE(WALL(IW)%BOUNDARY_TYPE)
         CASE(INTERPOLATED_BOUNDARY,PERIODIC_BOUNDARY)
         CASE DEFAULT
            CYCLE
         END SELECT
      ENDIF
      IF (FV%FACE%SRC_IREG(IF_) < 1) CYCLE
      ILO = FV%FACE%IJK_FACE(IAXIS,IF_)
      JLO = FV%FACE%IJK_FACE(JAXIS,IF_)
      KLO = FV%FACE%IJK_FACE(KAXIS,IF_)
      AX = FV%FACE%X1AXIS(IF_)
      CALL APPLY_REGULAR_FIX(ILO,JLO,KLO,AX,IF_)
   CASE(CC_FTYPE_RCGAS)
      IRC = FV%FACE%SRC_IRC(IF_)
      IF (IRC > MESHES(NM)%CC_NRCFACE_Z) CYCLE
      IW = RC_FACE(IRC)%IWC
      IF (IW > 0) THEN
         SELECT CASE(WALL(IW)%BOUNDARY_TYPE)
         CASE(INTERPOLATED_BOUNDARY,PERIODIC_BOUNDARY)
         CASE DEFAULT
            CYCLE
         END SELECT
      ENDIF
      ILO = RC_FACE(IRC)%IJK(IAXIS)
      JLO = RC_FACE(IRC)%IJK(JAXIS)
      KLO = RC_FACE(IRC)%IJK(KAXIS)
      IHI = ILO; JHI = JLO; KHI = KLO
      AX = RC_FACE(IRC)%IJK(KAXIS+1)
      SELECT CASE(AX)
      CASE(IAXIS); IHI = ILO+1
      CASE(JAXIS); JHI = JLO+1
      CASE(KAXIS); KHI = KLO+1
      END SELECT
      CALL CC_FV_SET_DIFFUSION_GEOM(NM,IF_,IDX,CCM1,CCP1)
      TMPV(-1) = TMP(ILO,JLO,KLO)
      TMPV(0) = TMP(IHI,JHI,KHI)
      RHOPV(-1) = RHOP(ILO,JLO,KLO)
      RHOPV(0) = RHOP(IHI,JHI,KHI)
      ZZM(-1,1:N_TOTAL_SCALARS) = ZZP(ILO,JLO,KLO,1:N_TOTAL_SCALARS)
      ZZM(0,1:N_TOTAL_SCALARS) = ZZP(IHI,JHI,KHI,1:N_TOTAL_SCALARS)
      DO ISIDE=-1,0
         IF (RC_FACE(IRC)%CELL_LIST(1,ISIDE+2)==CC_FTYPE_CFGAS) THEN
            ICC = RC_FACE(IRC)%CELL_LIST(2,ISIDE+2)
            JCC = RC_FACE(IRC)%CELL_LIST(3,ISIDE+2)
            IG = CUT_CELL(ICC)%IG(JCC)
            IF (IG >= 1) THEN
               TMPV(ISIDE) = CVTMP(IG)
               RHOPV(ISIDE) = CVRHO(IG)
               ZZM(ISIDE,1:N_TOTAL_SCALARS) = CVZZ(1:N_TOTAL_SCALARS,IG)
            ELSE
               II = CUT_CELL(ICC)%IJK(IAXIS)
               JJ = CUT_CELL(ICC)%IJK(JAXIS)
               KK = CUT_CELL(ICC)%IJK(KAXIS)
               TMPV(ISIDE) = TMP(II,JJ,KK)
               RHOPV(ISIDE) = RHOP(II,JJ,KK)
               ZZM(ISIDE,1:N_TOTAL_SCALARS) = ZZP(II,JJ,KK,1:N_TOTAL_SCALARS)
            ENDIF
         ENDIF
      ENDDO
      DO N=1,N_TOTAL_SCALARS
         ZZPV(-1) = ZZM(-1,N)
         ZZPV(0) = ZZM(0,N)
         DO ISIDE=-1,0
            IF (ISIDE == -1) THEN
               IS = ILO; JS = JLO; KS = KLO
            ELSE
               IS = IHI; JS = JHI; KS = KHI
            ENDIF
            CALL GET_CC_CELL_DIFFUSIVITY(RHOPV(ISIDE),D_Z(:,N),MU(IS,JS,KS), &
                 MU_DNS(IS,JS,KS),TMPV(ISIDE),D_Z_TEMP(ISIDE))
         ENDDO
         DIFF_FACE = CCM1*RHOPV(-1)*D_Z_TEMP(-1)+CCP1*RHOPV(0)*D_Z_TEMP(0)
         FLUX(N) = DIFF_FACE*IDX*(ZZPV(0)-ZZPV(-1))
         ZZF(N) = CCM1*ZZPV(-1)+CCP1*ZZPV(0)
      ENDDO
      TMP_FACE = CCM1*TMPV(-1)+CCP1*TMPV(0)
      CALL APPLY_TRACKED_FIX
      CALL COMMIT_FACE_DIFF(IF_,TMP_FACE)
   CASE(CC_FTYPE_CFGAS)
      ICF = FV%FACE%SRC_ICF(IF_)
      JCF = FV%FACE%SRC_JCF(IF_)
      IF (ICF > MESHES(NM)%N_CUTFACE_MESH) CYCLE
      IF (CUT_FACE(ICF)%STATUS /= CC_GASPHASE) CYCLE
      IW = CUT_FACE(ICF)%IWC
      IF (IW > 0) THEN
         SELECT CASE(WALL(IW)%BOUNDARY_TYPE)
         CASE(INTERPOLATED_BOUNDARY,PERIODIC_BOUNDARY)
         CASE DEFAULT
            CYCLE
         END SELECT
      ENDIF
      ILO = CUT_FACE(ICF)%IJK(IAXIS)
      JLO = CUT_FACE(ICF)%IJK(JAXIS)
      KLO = CUT_FACE(ICF)%IJK(KAXIS)
      IHI = ILO; JHI = JLO; KHI = KLO
      AX = CUT_FACE(ICF)%IJK(KAXIS+1)
      SELECT CASE(AX)
      CASE(IAXIS); IHI = ILO+1
      CASE(JAXIS); JHI = JLO+1
      CASE(KAXIS); KHI = KLO+1
      END SELECT
      CALL CC_FV_SET_DIFFUSION_GEOM(NM,IF_,IDX,CCM1,CCP1)
      TMPV(-1:0) = -1._EB
      RHOPV(-1:0) = -1._EB
      ZZM(-1,1:N_TOTAL_SCALARS) = -1._EB
      ZZM(0,1:N_TOTAL_SCALARS) = -1._EB
      DO ISIDE=-1,0
         IF (CUT_FACE(ICF)%CELL_LIST(1,ISIDE+2,JCF)==CC_FTYPE_CFGAS) THEN
            ICC = CUT_FACE(ICF)%CELL_LIST(2,ISIDE+2,JCF)
            JCC = CUT_FACE(ICF)%CELL_LIST(3,ISIDE+2,JCF)
            IG = CUT_CELL(ICC)%IG(JCC)
            IF (IG >= 1) THEN
               TMPV(ISIDE) = CVTMP(IG)
               RHOPV(ISIDE) = CVRHO(IG)
               ZZM(ISIDE,1:N_TOTAL_SCALARS) = CVZZ(1:N_TOTAL_SCALARS,IG)
            ELSE
               II = CUT_CELL(ICC)%IJK(IAXIS)
               JJ = CUT_CELL(ICC)%IJK(JAXIS)
               KK = CUT_CELL(ICC)%IJK(KAXIS)
               TMPV(ISIDE) = TMP(II,JJ,KK)
               RHOPV(ISIDE) = RHOP(II,JJ,KK)
               ZZM(ISIDE,1:N_TOTAL_SCALARS) = ZZP(II,JJ,KK,1:N_TOTAL_SCALARS)
            ENDIF
         ENDIF
      ENDDO
      DO N=1,N_TOTAL_SCALARS
         ZZPV(-1) = ZZM(-1,N)
         ZZPV(0) = ZZM(0,N)
         DO ISIDE=-1,0
            IF (ISIDE == -1) THEN
               IS = ILO; JS = JLO; KS = KLO
            ELSE
               IS = IHI; JS = JHI; KS = KHI
            ENDIF
            CALL GET_CC_CELL_DIFFUSIVITY(RHOPV(ISIDE),D_Z(:,N),MU(IS,JS,KS), &
                 MU_DNS(IS,JS,KS),TMPV(ISIDE),D_Z_TEMP(ISIDE))
         ENDDO
         DIFF_FACE = CCM1*RHOPV(-1)*D_Z_TEMP(-1)+CCP1*RHOPV(0)*D_Z_TEMP(0)
         FLUX(N) = DIFF_FACE*IDX*(ZZPV(0)-ZZPV(-1))
         ZZF(N) = CCM1*ZZPV(-1)+CCP1*ZZPV(0)
      ENDDO
      TMP_FACE = CCM1*TMPV(-1)+CCP1*TMPV(0)
      CALL APPLY_TRACKED_FIX
      CALL COMMIT_FACE_DIFF(IF_,TMP_FACE)
   END SELECT
ENDDO

! Wall faces. IRC>CC_NBBRCFACE_Z is the old boundary-RC loop. The CFACE test is
! the old internal-CFACE loop. OPEN regular faces keep the Cartesian flux.
DO IF_=1,FV%FACE%N_INT
   IF (FV%FACE%ROLE(IF_) /= CC_FACE_ROLE_EXTERNAL) CYCLE
   SELECT CASE(FV%FACE%FTYPE(IF_))
   CASE(CC_FTYPE_CFINB)
      ICF = FV%FACE%SRC_ICF(IF_)
      JCF = FV%FACE%SRC_JCF(IF_)
      IF (ICF > MESHES(NM)%N_CUTFACE_MESH) CYCLE
      IFACE = CUT_FACE(ICF)%CFACE_INDEX(JCF)
      IF (IFACE < INTERNAL_CFACE_CELLS_LB+1) CYCLE
      IF (IFACE > INTERNAL_CFACE_CELLS_LB+N_INTERNAL_CFACE_CELLS) CYCLE
      CFA => CFACE(IFACE)
      B1 => BOUNDARY_PROP1(CFA%B1_INDEX)
      N_ZZ_MAX = MAXLOC(B1%ZZ_F(1:N_TRACKED_SPECIES),1)
      DO N=1,N_TOTAL_SCALARS
         RHO_D_DZDN = 2._EB*B1%RHO_D_F(N)*(B1%ZZ_G(N)-B1%ZZ_F(N))*B1%RDN
         IF (N==N_ZZ_MAX) THEN
            ZZ_GET(1:N_TRACKED_SPECIES) = B1%ZZ_G(1:N_TRACKED_SPECIES)
            RHO_D_DZDN_GET(1:N_TRACKED_SPECIES) = 2._EB*B1%RHO_D_F(1:N_TRACKED_SPECIES)* &
               (ZZ_GET(1:N_TRACKED_SPECIES)-B1%ZZ_F(1:N_TRACKED_SPECIES))*B1%RDN
            RHO_D_DZDN = -(SUM(RHO_D_DZDN_GET(1:N_TRACKED_SPECIES))-RHO_D_DZDN)
         ENDIF
         FLUX(N) = RHO_D_DZDN
      ENDDO
      FV%FACE%DIFF_FLUX(1:N_TOTAL_SCALARS,IF_) = FLUX(1:N_TOTAL_SCALARS)
   CASE(CC_FTYPE_RGGAS)
      IF (FV%FACE%SRC_IREG(IF_) < 1) CYCLE
      IW = FV%FACE%IWC(IF_)
      IF (IW < 1) CYCLE
      SELECT CASE(WALL(IW)%BOUNDARY_TYPE)
      CASE(NULL_BOUNDARY,INTERPOLATED_BOUNDARY,PERIODIC_BOUNDARY)
         CYCLE
      CASE(OPEN_BOUNDARY)
         ILO = FV%FACE%IJK_FACE(IAXIS,IF_)
         JLO = FV%FACE%IJK_FACE(JAXIS,IF_)
         KLO = FV%FACE%IJK_FACE(KAXIS,IF_)
         AX = FV%FACE%X1AXIS(IF_)
         CALL APPLY_REGULAR_FIX(ILO,JLO,KLO,AX,IF_)
      CASE DEFAULT
         DO N=1,N_TOTAL_SCALARS
            CALL GET_BBREGFACE_RHO_D_DZDN
            FLUX(N) = RHO_D_DZDN
         ENDDO
         FV%FACE%DIFF_FLUX(1:N_TOTAL_SCALARS,IF_) = FLUX(1:N_TOTAL_SCALARS)
      END SELECT
   CASE(CC_FTYPE_RCGAS)
      IRC = FV%FACE%SRC_IRC(IF_)
      IF (IRC > MESHES(NM)%CC_NBBRCFACE_Z) CYCLE
      IW = RC_FACE(IRC)%IWC
      SELECT CASE(WALL(IW)%BOUNDARY_TYPE)
      CASE(NULL_BOUNDARY,INTERPOLATED_BOUNDARY,PERIODIC_BOUNDARY)
         CYCLE
      END SELECT
      IFACE = IRC
      I = RC_FACE(IRC)%IJK(IAXIS)
      J = RC_FACE(IRC)%IJK(JAXIS)
      K = RC_FACE(IRC)%IJK(KAXIS)
      X1AXIS = RC_FACE(IRC)%IJK(KAXIS+1)
      CALL GET_BBRCFACE_RHO_D_DZDN
      IF (WALL(IW)%BOUNDARY_TYPE==OPEN_BOUNDARY) CALL APPLY_TRACKED_FIX
      CALL COMMIT_FACE_DIFF(IF_,TMP_FACE)
   CASE(CC_FTYPE_CFGAS)
      ICF = FV%FACE%SRC_ICF(IF_)
      JCF = FV%FACE%SRC_JCF(IF_)
      IF (ICF > MESHES(NM)%N_CUTFACE_MESH) CYCLE
      IF (CUT_FACE(ICF)%STATUS /= CC_GASPHASE) CYCLE
      IF (CUT_FACE(ICF)%IWC < 1) CYCLE
      IW = CUT_FACE(ICF)%IWC
      SELECT CASE(WALL(IW)%BOUNDARY_TYPE)
      CASE(NULL_BOUNDARY,INTERPOLATED_BOUNDARY,PERIODIC_BOUNDARY)
         CYCLE
      END SELECT
      I = CUT_FACE(ICF)%IJK(IAXIS)
      J = CUT_FACE(ICF)%IJK(JAXIS)
      K = CUT_FACE(ICF)%IJK(KAXIS)
      X1AXIS = CUT_FACE(ICF)%IJK(KAXIS+1)
      IFACE = JCF
      ILO = I; JLO = J; KLO = K
      IHI = ILO; JHI = JLO; KHI = KLO
      SELECT CASE(X1AXIS)
      CASE(IAXIS); IHI = ILO+1
      CASE(JAXIS); JHI = JLO+1
      CASE(KAXIS); KHI = KLO+1
      END SELECT
      IF (WALL(IW)%BOUNDARY_TYPE==OPEN_BOUNDARY) THEN
         X1F = CUT_FACE(ICF)%XYZCEN(X1AXIS,JCF)
         IF (BOUNDARY_COORD(WALL(IW)%BC_INDEX)%IOR > 0) THEN
            IDX = 0.5_EB/(CUT_FACE(ICF)%XCENHIGH(X1AXIS,JCF)-X1F)
         ELSE
            IDX = 0.5_EB/(X1F-CUT_FACE(ICF)%XCENLOW(X1AXIS,JCF))
         ENDIF
         CCM1 = 0.5_EB
         CCP1 = 0.5_EB
         TMPV(-1) = TMP(ILO,JLO,KLO)
         TMPV(0) = TMP(IHI,JHI,KHI)
         RHOPV(-1) = RHOP(ILO,JLO,KLO)
         RHOPV(0) = RHOP(IHI,JHI,KHI)
         ZZM(-1,1:N_TOTAL_SCALARS) = ZZP(ILO,JLO,KLO,1:N_TOTAL_SCALARS)
         ZZM(0,1:N_TOTAL_SCALARS) = ZZP(IHI,JHI,KHI,1:N_TOTAL_SCALARS)
         DO ISIDE=-1,0
            IF (CUT_FACE(ICF)%CELL_LIST(1,ISIDE+2,JCF)==CC_FTYPE_CFGAS) THEN
               ICC = CUT_FACE(ICF)%CELL_LIST(2,ISIDE+2,JCF)
               JCC = CUT_FACE(ICF)%CELL_LIST(3,ISIDE+2,JCF)
               IG = CUT_CELL(ICC)%IG(JCC)
               IF (IG >= 1) THEN
                  TMPV(ISIDE) = CVTMP(IG)
                  RHOPV(ISIDE) = CVRHO(IG)
                  ZZM(ISIDE,1:N_TOTAL_SCALARS) = CVZZ(1:N_TOTAL_SCALARS,IG)
               ELSE
                  II = CUT_CELL(ICC)%IJK(IAXIS)
                  JJ = CUT_CELL(ICC)%IJK(JAXIS)
                  KK = CUT_CELL(ICC)%IJK(KAXIS)
                  TMPV(ISIDE) = TMP(II,JJ,KK)
                  RHOPV(ISIDE) = RHOP(II,JJ,KK)
                  ZZM(ISIDE,1:N_TOTAL_SCALARS) = ZZP(II,JJ,KK,1:N_TOTAL_SCALARS)
               ENDIF
            ENDIF
         ENDDO
         DO N=1,N_TOTAL_SCALARS
            ZZPV(-1) = ZZM(-1,N)
            ZZPV(0) = ZZM(0,N)
            DO ISIDE=-1,0
               IF (ISIDE == -1) THEN
                  IS = ILO; JS = JLO; KS = KLO
               ELSE
                  IS = IHI; JS = JHI; KS = KHI
               ENDIF
               CALL GET_CC_CELL_DIFFUSIVITY(RHOPV(ISIDE),D_Z(:,N),MU(IS,JS,KS), &
                    MU_DNS(IS,JS,KS),TMPV(ISIDE),D_Z_TEMP(ISIDE))
            ENDDO
            DIFF_FACE = CCM1*RHOPV(-1)*D_Z_TEMP(-1)+CCP1*RHOPV(0)*D_Z_TEMP(0)
            FLUX(N) = DIFF_FACE*IDX*(ZZPV(0)-ZZPV(-1))
            ZZF(N) = CCM1*ZZPV(-1)+CCP1*ZZPV(0)
         ENDDO
         TMP_FACE = CCM1*TMPV(-1)+CCP1*TMPV(0)
         CALL APPLY_TRACKED_FIX
         CALL COMMIT_FACE_DIFF(IF_,TMP_FACE)
      ELSE
         CALL GET_BBCUTFACE_RHO_D_DZDN
         CALL COMMIT_FACE_DIFF(IF_,TMP_FACE)
      ENDIF
   END SELECT
ENDDO

CONTAINS


SUBROUTINE APPLY_REGULAR_FIX(I0,J0,K0,AX0,IROW)
INTEGER, INTENT(IN) :: I0,J0,K0,AX0,IROW
INTEGER :: NMAX
REAL(EB) :: ZZ_FACE(1:N_TRACKED_SPECIES)
SELECT CASE(AX0)
CASE(IAXIS)
   ZZ_FACE(1:N_TRACKED_SPECIES) = 0.5_EB*(ZZP(I0+1,J0,K0,1:N_TRACKED_SPECIES)+ &
                                          ZZP(I0,J0,K0,1:N_TRACKED_SPECIES))
CASE(JAXIS)
   ZZ_FACE(1:N_TRACKED_SPECIES) = 0.5_EB*(ZZP(I0,J0+1,K0,1:N_TRACKED_SPECIES)+ &
                                          ZZP(I0,J0,K0,1:N_TRACKED_SPECIES))
CASE(KAXIS)
   ZZ_FACE(1:N_TRACKED_SPECIES) = 0.5_EB*(ZZP(I0,J0,K0+1,1:N_TRACKED_SPECIES)+ &
                                          ZZP(I0,J0,K0,1:N_TRACKED_SPECIES))
END SELECT
NMAX = MAXLOC(ZZ_FACE(1:N_TRACKED_SPECIES),1)
FV%FACE%DIFF_FLUX(NMAX,IROW) = -(SUM(FV%FACE%DIFF_FLUX(1:N_TRACKED_SPECIES,IROW))- &
                                 FV%FACE%DIFF_FLUX(NMAX,IROW))
END SUBROUTINE APPLY_REGULAR_FIX


SUBROUTINE APPLY_TRACKED_FIX
INTEGER :: NMAX
NMAX = MAXLOC(ZZF(1:N_TRACKED_SPECIES),1)
FLUX(NMAX) = -(SUM(FLUX(1:N_TRACKED_SPECIES))-FLUX(NMAX))
END SUBROUTINE APPLY_TRACKED_FIX

SUBROUTINE COMMIT_FACE_DIFF(IFACE_ROW,TMP_IN)
INTEGER, INTENT(IN) :: IFACE_ROW
REAL(EB), INTENT(IN) :: TMP_IN
REAL(EB) :: HLOCAL(1:N_TOTAL_SCALARS),HS
INTEGER :: NN
FV%FACE%DIFF_FLUX(1:N_TOTAL_SCALARS,IFACE_ROW) = FLUX(1:N_TOTAL_SCALARS)
DO NN=1,N_TOTAL_SCALARS
   CALL GET_SENSIBLE_ENTHALPY_Z(NN,TMP_IN,HS)
   HLOCAL(NN) = HS*FLUX(NN)
ENDDO
FV%FACE%DIFF_H_FLUX(IFACE_ROW) = SUM(HLOCAL(1:N_TOTAL_SCALARS))
END SUBROUTINE COMMIT_FACE_DIFF

SUBROUTINE GET_BBREGFACE_RHO_D_DZDN

INTEGER :: IIG,JJG,KKG,IOR,N_ZZ_MAX_LOC
REAL(EB) :: RHO_GET(1:N_TRACKED_SPECIES)
WC => WALL(IW)
B1 => BOUNDARY_PROP1(WC%B1_INDEX)
BC => BOUNDARY_COORD(WC%BC_INDEX)
IIG = BC%IIG
JJG = BC%JJG
KKG = BC%KKG
IOR = BC%IOR
N_ZZ_MAX_LOC = MAXLOC(B1%ZZ_F(1:N_TRACKED_SPECIES),1)
RHO_D_DZDN = 2._EB*B1%RHO_D_F(N)*(ZZP(IIG,JJG,KKG,N)-B1%ZZ_F(N))*B1%RDN
IF (N==N_ZZ_MAX_LOC) THEN
   RHO_GET = 2._EB*B1%RHO_D_F(:)*(ZZP(IIG,JJG,KKG,:)-B1%ZZ_F(:))*B1%RDN
   RHO_D_DZDN = -(SUM(RHO_GET(:))-RHO_D_DZDN)
ENDIF
IF (IOR < 0) RHO_D_DZDN = -RHO_D_DZDN

END SUBROUTINE GET_BBREGFACE_RHO_D_DZDN

SUBROUTINE GET_BBRCFACE_RHO_D_DZDN

INTEGER :: IIG,JJG,KKG,IOR,N_ZZ_MAX_LOC,IG,II,JJ,KK
REAL(EB) :: ZZ_G,ZZ_GV(1:N_TRACKED_SPECIES),RHO_GET(1:N_TRACKED_SPECIES)

WC => WALL(IW)
B1 => BOUNDARY_PROP1(WC%B1_INDEX)
BC => BOUNDARY_COORD(WC%BC_INDEX)
IIG = BC%IIG
JJG = BC%JJG
KKG = BC%KKG
IOR = BC%IOR
ISIDE = -1+(SIGN(1,IOR)+1)/2
SELECT CASE(X1AXIS)
CASE(IAXIS); X1F = MESHES(NM)%X(I)
CASE(JAXIS); X1F = MESHES(NM)%Y(J)
CASE(KAXIS); X1F = MESHES(NM)%Z(K)
END SELECT
IF (IOR > 0) THEN
   IDX = 1._EB/(RC_FACE(IFACE)%XCEN(X1AXIS,HIGH_IND)-X1F)
ELSE
   IDX = 1._EB/(X1F-RC_FACE(IFACE)%XCEN(X1AXIS,LOW_IND))
ENDIF
IG = 0
II = 0; JJ = 0; KK = 0
SELECT CASE(RC_FACE(IFACE)%CELL_LIST(1,ISIDE+2))
CASE(CC_FTYPE_RGGAS)
   ZZ_GV(1:N_TRACKED_SPECIES) = ZZP(IIG,JJG,KKG,1:N_TRACKED_SPECIES)
CASE(CC_FTYPE_CFGAS)
   ICC = RC_FACE(IFACE)%CELL_LIST(2,ISIDE+2)
   JCC = RC_FACE(IFACE)%CELL_LIST(3,ISIDE+2)
   IG = CUT_CELL(ICC)%IG(JCC)
   IF (IG >= 1) THEN
      ZZ_GV(1:N_TRACKED_SPECIES) = CVZZ(1:N_TRACKED_SPECIES,IG)
   ELSE
      II = CUT_CELL(ICC)%IJK(IAXIS)
      JJ = CUT_CELL(ICC)%IJK(JAXIS)
      KK = CUT_CELL(ICC)%IJK(KAXIS)
      ZZ_GV(1:N_TRACKED_SPECIES) = ZZP(II,JJ,KK,1:N_TRACKED_SPECIES)
   ENDIF
END SELECT
DO N=1,N_TOTAL_SCALARS
   SELECT CASE(RC_FACE(IFACE)%CELL_LIST(1,ISIDE+2))
   CASE(CC_FTYPE_RGGAS)
      ZZ_G = ZZP(IIG,JJG,KKG,N)
   CASE(CC_FTYPE_CFGAS)
      IF (IG >= 1) THEN
         ZZ_G = CVZZ(N,IG)
      ELSE
         ZZ_G = ZZP(II,JJ,KK,N)
      ENDIF
   END SELECT
   FLUX(N) = B1%RHO_D_F(N)*(ZZ_G-B1%ZZ_F(N))*IDX
   ZZF(N) = B1%ZZ_F(N)
ENDDO
N_ZZ_MAX_LOC = MAXLOC(B1%ZZ_F(1:N_TRACKED_SPECIES),1)
RHO_GET = B1%RHO_D_F(:)*(ZZ_GV(:)-B1%ZZ_F(:))*IDX
FLUX(N_ZZ_MAX_LOC) = -(SUM(RHO_GET(:))-FLUX(N_ZZ_MAX_LOC))
IF (IOR < 0) THEN
   DO N=1,N_TOTAL_SCALARS
      FLUX(N) = -FLUX(N)
   ENDDO
ENDIF
TMP_FACE = B1%TMP_F

END SUBROUTINE GET_BBRCFACE_RHO_D_DZDN

SUBROUTINE GET_BBCUTFACE_RHO_D_DZDN

INTEGER :: IOR,N_ZZ_MAX_LOC,IG,II,JJ,KK
REAL(EB) :: ZZ_G,ZZ_GV(1:N_TRACKED_SPECIES),RHO_GET(1:N_TRACKED_SPECIES)

WC => WALL(IW)
B1 => BOUNDARY_PROP1(WC%B1_INDEX)
IOR = BOUNDARY_COORD(WC%BC_INDEX)%IOR
X1F = CUT_FACE(ICF)%XYZCEN(X1AXIS,IFACE)
IF (IOR > 0) THEN
   IDX = 1._EB/(CUT_FACE(ICF)%XCENHIGH(X1AXIS,IFACE)-X1F)
ELSE
   IDX = 1._EB/(X1F-CUT_FACE(ICF)%XCENLOW(X1AXIS,IFACE))
ENDIF
ISIDE = -1+(SIGN(1,IOR)+1)/2
IG = 0
II = 0; JJ = 0; KK = 0
SELECT CASE(CUT_FACE(ICF)%CELL_LIST(1,ISIDE+2,IFACE))
CASE(CC_FTYPE_CFGAS)
   ICC = CUT_FACE(ICF)%CELL_LIST(2,ISIDE+2,IFACE)
   JCC = CUT_FACE(ICF)%CELL_LIST(3,ISIDE+2,IFACE)
   IG = CUT_CELL(ICC)%IG(JCC)
   IF (IG >= 1) THEN
      ZZ_GV(1:N_TRACKED_SPECIES) = CVZZ(1:N_TRACKED_SPECIES,IG)
   ELSE
      II = CUT_CELL(ICC)%IJK(IAXIS)
      JJ = CUT_CELL(ICC)%IJK(JAXIS)
      KK = CUT_CELL(ICC)%IJK(KAXIS)
      ZZ_GV(1:N_TRACKED_SPECIES) = ZZP(II,JJ,KK,1:N_TRACKED_SPECIES)
   ENDIF
END SELECT
DO N=1,N_TOTAL_SCALARS
   SELECT CASE(CUT_FACE(ICF)%CELL_LIST(1,ISIDE+2,IFACE))
   CASE(CC_FTYPE_CFGAS)
      IF (IG >= 1) THEN
         ZZ_G = CVZZ(N,IG)
      ELSE
         ZZ_G = ZZP(II,JJ,KK,N)
      ENDIF
   END SELECT
   FLUX(N) = B1%RHO_D_F(N)*(ZZ_G-B1%ZZ_F(N))*IDX
ENDDO
N_ZZ_MAX_LOC = MAXLOC(B1%ZZ_F(1:N_TRACKED_SPECIES),1)
RHO_GET = B1%RHO_D_F(:)*(ZZ_GV(:)-B1%ZZ_F(:))*IDX
FLUX(N_ZZ_MAX_LOC) = -(SUM(RHO_GET(:))-FLUX(N_ZZ_MAX_LOC))
IF (IOR < 0) THEN
   DO N=1,N_TOTAL_SCALARS
      FLUX(N) = -FLUX(N)
   ENDDO
ENDIF
TMP_FACE = B1%TMP_F

END SUBROUTINE GET_BBCUTFACE_RHO_D_DZDN

END SUBROUTINE CC_DIFFUSIVE_MASS_FLUXES


! ------------------------------ CC_DENSITY -------------------------------

SUBROUTINE CC_SET_DENSITY_LISTS
INTEGER :: PASS, NM, I, J, K, ICC, JCC, IG, IC, L, N0, SOL1, EXT1
INTEGER :: N_EXT, N_SOL, N_SRC, N_NBR, MAX_NBR
IF (ALLOCATED(GAS_EXT_PTR)) DEALLOCATE(GAS_EXT_PTR,GAS_EXT_J,GAS_EXT_K,GAS_EXT_I1,GAS_EXT_I2)
IF (ALLOCATED(SOLID_PTR)) DEALLOCATE(SOLID_PTR,SOLID_J,SOLID_K,SOLID_I1,SOLID_I2)
IF (ALLOCATED(CLIP_SRC_PTR)) DEALLOCATE(CLIP_SRC_PTR,CLIP_KIND,CLIP_I,CLIP_J,CLIP_K,CLIP_IG,CLIP_VOL)
IF (ALLOCATED(CLIP_NBR_PTR)) DEALLOCATE(CLIP_NBR_PTR,CLIP_DEST,CLIP_NI,CLIP_NJ,CLIP_NK,CLIP_NIG,CLIP_NVOL)
IF (ALLOCATED(CLIP_MASS)) DEALLOCATE(CLIP_MASS)
DO PASS=1,2
   N_EXT=0; N_SOL=0; N_SRC=0; N_NBR=0; MAX_NBR=0
   DO NM=1,NMESHES
      IF (NM>=LOWER_MESH_INDEX .AND. NM<=UPPER_MESH_INDEX) THEN
         CALL POINT_TO_MESH(NM)
         DO K=1,KBAR
            DO J=1,JBAR
               SOL1=0; EXT1=0
               DO I=1,IBAR
                  IF (CCVAR(I,J,K,CC_CGSC)==CC_SOLID) THEN
                     IF (EXT1>0) THEN
                        CALL DN_ADD_RUN(PASS,N_EXT,J,K,EXT1,I-1,.FALSE.)
                        EXT1=0
                     ENDIF
                     IF (SOL1==0) SOL1=I
                  ELSE
                     IF (SOL1>0) THEN
                        CALL DN_ADD_RUN(PASS,N_SOL,J,K,SOL1,I-1,.TRUE.)
                        SOL1=0
                     ENDIF
                     IF (DN_IS_EXTERIOR(I,J,K)) THEN
                        IF (EXT1==0) EXT1=I
                     ELSE IF (EXT1>0) THEN
                        CALL DN_ADD_RUN(PASS,N_EXT,J,K,EXT1,I-1,.FALSE.)
                        EXT1=0
                     ENDIF
                  ENDIF
               ENDDO
               IF (SOL1>0) CALL DN_ADD_RUN(PASS,N_SOL,J,K,SOL1,IBAR,.TRUE.)
               IF (EXT1>0) CALL DN_ADD_RUN(PASS,N_EXT,J,K,EXT1,IBAR,.FALSE.)
            ENDDO
         ENDDO
         DO ICC=1,MESHES(NM)%N_CUTCELL_MESH
            I=CUT_CELL(ICC)%IJK(IAXIS); J=CUT_CELL(ICC)%IJK(JAXIS); K=CUT_CELL(ICC)%IJK(KAXIS)
            IC=CELL_INDEX(I,J,K)
            IF (CELL(IC)%SOLID) CYCLE
            DO JCC=1,CUT_CELL(ICC)%NCELL
               IG=CUT_CELL(ICC)%IG(JCC)
               IF (IG<1) CYCLE
               N_SRC=N_SRC+1
               IF (PASS==2) THEN
                  CLIP_KIND(N_SRC)=DN_CUT
                  CLIP_I(N_SRC)=I; CLIP_J(N_SRC)=J; CLIP_K(N_SRC)=K; CLIP_IG(N_SRC)=IG
                  CLIP_VOL(N_SRC)=CUT_CELL(ICC)%VOLUME(JCC)
               ENDIF
               N0=N_NBR
               CALL CLIP_CUT_NEIGHBORS(PASS,NM,N_NBR,I,J,K,ICC,JCC,IC)
               IF (N_NBR-N0>MAX_NBR) MAX_NBR=N_NBR-N0
               IF (PASS==2) CLIP_NBR_PTR(N_SRC)=N_NBR
            ENDDO
         ENDDO
         DO L=1,SIZE(MESHES(NM)%TH_REG,2)
            I=MESHES(NM)%TH_REG(IAXIS,L); J=MESHES(NM)%TH_REG(JAXIS,L); K=MESHES(NM)%TH_REG(KAXIS,L)
            N_SRC=N_SRC+1
            IF (PASS==2) THEN
               CLIP_KIND(N_SRC)=DN_CART
               CLIP_I(N_SRC)=I; CLIP_J(N_SRC)=J; CLIP_K(N_SRC)=K; CLIP_IG(N_SRC)=0
               CLIP_VOL(N_SRC)=DX(I)*DY(J)*DZ(K)
            ENDIF
            N0=N_NBR
            IC=CELL_INDEX(I,J,K)
            CALL CLIP_REG_NEIGHBORS(PASS,NM,N_NBR,I,J,K,IC)
            IF (N_NBR-N0>MAX_NBR) MAX_NBR=N_NBR-N0
            IF (PASS==2) CLIP_NBR_PTR(N_SRC)=N_NBR
         ENDDO
      ENDIF
      IF (PASS==2) THEN
         GAS_EXT_PTR(NM)=N_EXT; SOLID_PTR(NM)=N_SOL; CLIP_SRC_PTR(NM)=N_SRC
      ENDIF
   ENDDO
   IF (PASS==1) CALL DN_ALLOCATE(N_EXT,N_SOL,N_SRC,N_NBR,MAX_NBR)
ENDDO
END SUBROUTINE CC_SET_DENSITY_LISTS

SUBROUTINE DN_ALLOCATE(N_EXT,N_SOL,N_SRC,N_NBR,MAX_NBR)
INTEGER, INTENT(IN) :: N_EXT,N_SOL,N_SRC,N_NBR,MAX_NBR
ALLOCATE(GAS_EXT_PTR(0:NMESHES),SOLID_PTR(0:NMESHES),CLIP_SRC_PTR(0:NMESHES))
GAS_EXT_PTR=0; SOLID_PTR=0; CLIP_SRC_PTR=0
ALLOCATE(GAS_EXT_J(1:N_EXT),GAS_EXT_K(1:N_EXT),GAS_EXT_I1(1:N_EXT),GAS_EXT_I2(1:N_EXT))
ALLOCATE(SOLID_J(1:N_SOL),SOLID_K(1:N_SOL),SOLID_I1(1:N_SOL),SOLID_I2(1:N_SOL))
ALLOCATE(CLIP_KIND(1:N_SRC),CLIP_I(1:N_SRC),CLIP_J(1:N_SRC),CLIP_K(1:N_SRC),CLIP_IG(1:N_SRC))
ALLOCATE(CLIP_VOL(1:N_SRC),CLIP_NBR_PTR(0:N_SRC))
ALLOCATE(CLIP_DEST(1:N_NBR),CLIP_NI(1:N_NBR),CLIP_NJ(1:N_NBR),CLIP_NK(1:N_NBR))
ALLOCATE(CLIP_NIG(1:N_NBR),CLIP_NVOL(1:N_NBR),CLIP_MASS(MAX(1,MAX_NBR)))
CLIP_NBR_PTR=0
END SUBROUTINE DN_ALLOCATE

SUBROUTINE DN_ADD_RUN(PASS,N,J,K,I1,I2,IS_SOLID)
INTEGER, INTENT(IN) :: PASS,J,K,I1,I2
INTEGER, INTENT(INOUT) :: N
LOGICAL, INTENT(IN) :: IS_SOLID
N=N+1
IF (PASS/=2) RETURN
IF (IS_SOLID) THEN
   SOLID_J(N)=J; SOLID_K(N)=K; SOLID_I1(N)=I1; SOLID_I2(N)=I2
ELSE
   GAS_EXT_J(N)=J; GAS_EXT_K(N)=K; GAS_EXT_I1(N)=I1; GAS_EXT_I2(N)=I2
ENDIF
END SUBROUTINE DN_ADD_RUN

LOGICAL FUNCTION DN_IS_EXTERIOR(I,J,K)
! Gas, not solid, and not a scalar-row cell. CC_SOLID is handled by the caller.
INTEGER, INTENT(IN) :: I,J,K
DN_IS_EXTERIOR=.FALSE.
IF (CELL(CELL_INDEX(I,J,K))%SOLID) RETURN
IF (CCVAR(I,J,K,CC_CGSC)/=CC_GASPHASE) RETURN
IF (CCVAR(I,J,K,CC_UNKZ)>0) RETURN
DN_IS_EXTERIOR=.TRUE.
END FUNCTION DN_IS_EXTERIOR

SUBROUTINE DN_STORE(PASS,N_NBR,DEST,I,J,K,IG,VOL)
INTEGER, INTENT(IN) :: PASS,DEST,I,J,K,IG
INTEGER, INTENT(INOUT) :: N_NBR
REAL(EB), INTENT(IN) :: VOL
N_NBR=N_NBR+1
IF (PASS/=2) RETURN
CLIP_DEST(N_NBR)=DEST
CLIP_NI(N_NBR)=I; CLIP_NJ(N_NBR)=J; CLIP_NK(N_NBR)=K; CLIP_NIG(N_NBR)=IG
CLIP_NVOL(N_NBR)=VOL
END SUBROUTINE DN_STORE

SUBROUTINE DN_STORE_CUT(PASS,NM,N_NBR,ICC1,JCC1)
INTEGER, INTENT(IN) :: PASS,NM,ICC1,JCC1
INTEGER, INTENT(INOUT) :: N_NBR
INTEGER :: IG1,IH,JH,KH,NCUT
NCUT=MESHES(NM)%N_CUTCELL_MESH+MESHES(NM)%N_GCCUTCELL_MESH
IF (ICC1<1 .OR. ICC1>NCUT) RETURN
IF (JCC1<1 .OR. JCC1>CUT_CELL(ICC1)%NCELL) RETURN
IG1=CUT_CELL(ICC1)%IG(JCC1)
IH=CUT_CELL(ICC1)%IJK(IAXIS); JH=CUT_CELL(ICC1)%IJK(JAXIS); KH=CUT_CELL(ICC1)%IJK(KAXIS)
CALL DN_STORE(PASS,N_NBR,DN_CUT,IH,JH,KH,IG1,CUT_CELL(ICC1)%VOLUME(JCC1))
END SUBROUTINE DN_STORE_CUT

SUBROUTINE CLIP_CUT_NEIGHBORS(PASS,NM,N_NBR,I,J,K,ICC,JCC,IC)
INTEGER, INTENT(IN) :: PASS,NM,I,J,K,ICC,JCC,IC
INTEGER, INTENT(INOUT) :: N_NBR
INTEGER :: IFC,IFACE,LOHI,ILH,X1AXIS,IFC1,JFC1,ICC1,JCC1,IRC
INTEGER :: II,JJ,KK,IIF,JJF,KKF,NF
DO IFC=2,CUT_CELL(ICC)%CCELEM(1,JCC)+1
   IFACE=CUT_CELL(ICC)%CCELEM(IFC,JCC)
   IF (CUT_CELL(ICC)%FACE_LIST(1,IFACE)==CC_FTYPE_CFINB) CYCLE
   LOHI=CUT_CELL(ICC)%FACE_LIST(2,IFACE)
   ILH=2*LOHI-3
   X1AXIS=CUT_CELL(ICC)%FACE_LIST(3,IFACE)
   IF (CELL(IC)%WALL_INDEX(ILH*X1AXIS)/=0) CYCLE
   SELECT CASE(CUT_CELL(ICC)%FACE_LIST(1,IFACE))
   CASE(CC_FTYPE_CFGAS)
      IFC1=CUT_CELL(ICC)%FACE_LIST(4,IFACE); JFC1=CUT_CELL(ICC)%FACE_LIST(5,IFACE)
      NF=MESHES(NM)%N_CUTFACE_MESH+MESHES(NM)%N_GCCUTFACE_MESH
      IF (IFC1<1 .OR. IFC1>NF) CYCLE
      IF (JFC1<1 .OR. JFC1>CUT_FACE(IFC1)%NFACE) CYCLE
      ICC1=CUT_FACE(IFC1)%CELL_LIST(2,LOHI,JFC1)
      JCC1=CUT_FACE(IFC1)%CELL_LIST(3,LOHI,JFC1)
      CALL DN_STORE_CUT(PASS,NM,N_NBR,ICC1,JCC1)
   CASE(CC_FTYPE_RCGAS)
      II=I; JJ=J; KK=K; IIF=I; JJF=J; KKF=K
      SELECT CASE(X1AXIS)
      CASE(IAXIS); IIF=IIF+LOHI-2; II=II+ILH
      CASE(JAXIS); JJF=JJF+LOHI-2; JJ=JJ+ILH
      CASE(KAXIS); KKF=KKF+LOHI-2; KK=KK+ILH
      END SELECT
      IRC=FCVAR(IIF,JJF,KKF,CC_IDRC,X1AXIS)
      IF (IRC<1 .OR. IRC>MESHES(NM)%CC_NRCFACE_Z) CYCLE
      SELECT CASE(RC_FACE(IRC)%CELL_LIST(1,LOHI))
      CASE(CC_FTYPE_RGGAS)
         CALL DN_STORE(PASS,N_NBR,DN_CART,II,JJ,KK,0,DX(II)*DY(JJ)*DZ(KK))
      CASE(CC_FTYPE_CFGAS)
         ICC1=RC_FACE(IRC)%CELL_LIST(2,LOHI); JCC1=RC_FACE(IRC)%CELL_LIST(3,LOHI)
         CALL DN_STORE_CUT(PASS,NM,N_NBR,ICC1,JCC1)
      END SELECT
   END SELECT
ENDDO
END SUBROUTINE CLIP_CUT_NEIGHBORS

SUBROUTINE CLIP_REG_NEIGHBORS(PASS,NM,N_NBR,I,J,K,IC)
INTEGER, INTENT(IN) :: PASS,NM,I,J,K,IC
INTEGER, INTENT(INOUT) :: N_NBR
INTEGER :: X1AXIS,LOHI,ILH,II,JJ,KK,IIF,JJF,KKF,IRC,ICC1,JCC1
DO X1AXIS=IAXIS,KAXIS
   DO LOHI=LOW_IND,HIGH_IND
      ILH=2*LOHI-3
      IF (CELL(IC)%WALL_INDEX(ILH*X1AXIS)/=0) CYCLE
      II=I; JJ=J; KK=K; IIF=I; JJF=J; KKF=K
      SELECT CASE(X1AXIS)
      CASE(IAXIS); IIF=IIF+LOHI-2; II=II+ILH
      CASE(JAXIS); JJF=JJF+LOHI-2; JJ=JJ+ILH
      CASE(KAXIS); KKF=KKF+LOHI-2; KK=KK+ILH
      END SELECT
      IRC=FCVAR(IIF,JJF,KKF,CC_IDRC,X1AXIS)
      IF (IRC>0) THEN
         IF (IRC<=MESHES(NM)%CC_NRCFACE_Z) THEN
            SELECT CASE(RC_FACE(IRC)%CELL_LIST(1,LOHI))
            CASE(CC_FTYPE_RGGAS)
               CALL DN_STORE(PASS,N_NBR,DN_CART,II,JJ,KK,0,DX(II)*DY(JJ)*DZ(KK))
            CASE(CC_FTYPE_CFGAS)
               ICC1=RC_FACE(IRC)%CELL_LIST(2,LOHI); JCC1=RC_FACE(IRC)%CELL_LIST(3,LOHI)
               CALL DN_STORE_CUT(PASS,NM,N_NBR,ICC1,JCC1)
            END SELECT
         ENDIF
      ELSE
         CALL DN_STORE(PASS,N_NBR,DN_CART,II,JJ,KK,0,DX(II)*DY(JJ)*DZ(KK))
      ENDIF
   ENDDO
ENDDO
END SUBROUTINE CLIP_REG_NEIGHBORS
SUBROUTINE CC_DENSITY(T,DT)

USE PHYSICAL_FUNCTIONS, ONLY : GET_SPECIFIC_GAS_CONSTANT
USE MATH_FUNCTIONS, ONLY : EVALUATE_RAMP
USE MPI_F08

REAL(EB), INTENT(IN) :: T,DT
INTEGER :: N,I,J,K,NM,ICC,ICC0,IG,JCC,I0,J0,K0,NSN,L
REAL(EB) :: TNOW,VOL,ACC_V,ACC_T,ACC_R,ACC_S
REAL(EB) :: ACC_Z(N_TRACKED_SPECIES)
TYPE(CC_FV_TYPE), POINTER :: FV

TNOW = T
IF (SOLID_PHASE_ONLY) RETURN
TNOW = CURRENT_TIME()

SELECT CASE (PERIODIC_TEST)
   CASE DEFAULT
      IF (ICYC<=1) RETURN
   CASE (5,8)
      RETURN
   CASE (4,7,11,21,22)
END SELECT

CALL CC_DENSITY_EXPLICIT(T,DT)

DO NM=LOWER_MESH_INDEX,UPPER_MESH_INDEX
   CALL POINT_TO_MESH(NM)
   FV=>MESHES(NM)%FV
   DO L=1,SIZE(MESHES(NM)%TH_REG,2)
      I=MESHES(NM)%TH_REG(IAXIS,L); J=MESHES(NM)%TH_REG(JAXIS,L); K=MESHES(NM)%TH_REG(KAXIS,L)
      CALL CC_DENSITY_EOS_REG(I,J,K)
   ENDDO
   IF (PREDICTOR) THEN
      IF (.NOT.ALLOCATED(MESHES(NM)%RHO_ZZN)) &
         ALLOCATE(MESHES(NM)%RHO_ZZN(0:IBP1,0:JBP1,0:KBP1,N_TOTAL_SCALARS))
      DO N=1,N_TOTAL_SCALARS
         MESHES(NM)%RHO_ZZN(0:IBP1,0:JBP1,0:KBP1,N)=RHO(0:IBP1,0:JBP1,0:KBP1)*ZZ(0:IBP1,0:JBP1,0:KBP1,N)
      ENDDO
   ENDIF
   ICC0=0; NSN=0; I0=0; J0=0; K0=0
   ACC_V=0._EB; ACC_T=0._EB; ACC_R=0._EB; ACC_S=0._EB; ACC_Z=0._EB
   DO IG=1,FV%GCELL%N_CUT
      ICC=FV%GCELL%ICC(IG)
      IF (ICC/=ICC0) THEN
         IF (NSN>0) CALL CC_DENSITY_PUBLISH(I0,J0,K0,ACC_V,ACC_T,ACC_R,ACC_S,ACC_Z)
         ICC0=ICC
         I0=FV%GCELL%IJK(IAXIS,IG); J0=FV%GCELL%IJK(JAXIS,IG); K0=FV%GCELL%IJK(KAXIS,IG)
         NSN=0; ACC_V=0._EB; ACC_T=0._EB; ACC_R=0._EB; ACC_S=0._EB; ACC_Z=0._EB
      ENDIF
      CALL CC_DENSITY_EOS_CUT(NM,IG)
      JCC=FV%GCELL%JCC(IG)
      VOL=CUT_CELL(ICC)%VOLUME(JCC)
      NSN=NSN+1
      ACC_V=ACC_V+VOL
      ACC_T=ACC_T+FV%CV%TMP(IG)*VOL
      ACC_S=ACC_S+FV%CV%RSUM(IG)*VOL
      IF (PREDICTOR) THEN
         ACC_R=ACC_R+FV%CV%RHOS(IG)*VOL
         DO N=1,N_TRACKED_SPECIES
            ACC_Z(N)=ACC_Z(N)+FV%CV%ZZS(N,IG)*VOL
         ENDDO
      ELSE
         ACC_R=ACC_R+FV%CV%RHO(IG)*VOL
         DO N=1,N_TRACKED_SPECIES
            ACC_Z(N)=ACC_Z(N)+FV%CV%ZZ(N,IG)*VOL
         ENDDO
      ENDIF
   ENDDO
   IF (NSN>0) CALL CC_DENSITY_PUBLISH(I0,J0,K0,ACC_V,ACC_T,ACC_R,ACC_S,ACC_Z)
   DO L=SOLID_PTR(NM-1)+1,SOLID_PTR(NM)
      TMP(SOLID_I1(L):SOLID_I2(L),SOLID_J(L),SOLID_K(L))=TMPA
   ENDDO
ENDDO

T_USED(14)=T_USED(14)+CURRENT_TIME()-TNOW
IF (TIME_CC_IBM) T_CC_USED(CC_DENSITY_TIME_INDEX)=T_CC_USED(CC_DENSITY_TIME_INDEX)+CURRENT_TIME()-TNOW
END SUBROUTINE CC_DENSITY

SUBROUTINE CC_DENSITY_EOS_REG(I,J,K)
USE PHYSICAL_FUNCTIONS, ONLY : GET_SPECIFIC_GAS_CONSTANT
INTEGER, INTENT(IN) :: I,J,K
REAL(EB) :: ZZ_GET(1:N_TRACKED_SPECIES),PBAR_K
IF (PREDICTOR) THEN
   ZZ_GET(1:N_TRACKED_SPECIES)=ZZS(I,J,K,1:N_TRACKED_SPECIES)
   CALL GET_SPECIFIC_GAS_CONSTANT(ZZ_GET,RSUM(I,J,K))
   PBAR_K=PBAR_S(K,PRESSURE_ZONE(I,J,K))-P_0(K)+P_0_CV(CCVAR(I,J,K,CC_UNKZ))
   TMP(I,J,K)=PBAR_K/(RSUM(I,J,K)*RHOS(I,J,K))
ELSE
   ZZ_GET(1:N_TRACKED_SPECIES)=ZZ(I,J,K,1:N_TRACKED_SPECIES)
   CALL GET_SPECIFIC_GAS_CONSTANT(ZZ_GET,RSUM(I,J,K))
   PBAR_K=PBAR(K,PRESSURE_ZONE(I,J,K))-P_0(K)+P_0_CV(CCVAR(I,J,K,CC_UNKZ))
   TMP(I,J,K)=PBAR_K/(RSUM(I,J,K)*RHO(I,J,K))
ENDIF
END SUBROUTINE CC_DENSITY_EOS_REG

SUBROUTINE CC_DENSITY_EOS_CUT(NM,IG)
USE PHYSICAL_FUNCTIONS, ONLY : GET_SPECIFIC_GAS_CONSTANT
INTEGER, INTENT(IN) :: NM,IG
INTEGER :: ICC,JCC,I,J,K
REAL(EB) :: ZZ_GET(1:N_TRACKED_SPECIES),PBAR_K
TYPE(CC_FV_TYPE), POINTER :: FV
FV=>MESHES(NM)%FV
ICC=FV%GCELL%ICC(IG); JCC=FV%GCELL%JCC(IG)
I=FV%GCELL%IJK(IAXIS,IG); J=FV%GCELL%IJK(JAXIS,IG); K=FV%GCELL%IJK(KAXIS,IG)
IF (PREDICTOR) THEN
   ZZ_GET(1:N_TRACKED_SPECIES)=FV%CV%ZZS(1:N_TRACKED_SPECIES,IG)
   CALL GET_SPECIFIC_GAS_CONSTANT(ZZ_GET,FV%CV%RSUM(IG))
   PBAR_K=PBAR_S(K,PRESSURE_ZONE(I,J,K))-P_0(K)+P_0_CV(CUT_CELL(ICC)%UNKZ(JCC))
   FV%CV%TMP(IG)=PBAR_K/(FV%CV%RSUM(IG)*FV%CV%RHOS(IG))
ELSE
   ZZ_GET(1:N_TRACKED_SPECIES)=FV%CV%ZZ(1:N_TRACKED_SPECIES,IG)
   CALL GET_SPECIFIC_GAS_CONSTANT(ZZ_GET,FV%CV%RSUM(IG))
   PBAR_K=PBAR(K,PRESSURE_ZONE(I,J,K))-P_0(K)+P_0_CV(CUT_CELL(ICC)%UNKZ(JCC))
   FV%CV%TMP(IG)=PBAR_K/(FV%CV%RSUM(IG)*FV%CV%RHO(IG))
ENDIF
END SUBROUTINE CC_DENSITY_EOS_CUT

SUBROUTINE CC_DENSITY_PUBLISH(I,J,K,ACC_V,ACC_T,ACC_R,ACC_S,ACC_Z)
INTEGER, INTENT(IN) :: I,J,K
REAL(EB), INTENT(IN) :: ACC_V,ACC_T,ACC_R,ACC_S,ACC_Z(:)
INTEGER :: N
TMP(I,J,K)=ACC_T/ACC_V
RSUM(I,J,K)=ACC_S/ACC_V
IF (PREDICTOR) THEN
   RHOS(I,J,K)=ACC_R/ACC_V
   DO N=1,N_TRACKED_SPECIES
      ZZS(I,J,K,N)=ACC_Z(N)/ACC_V
   ENDDO
ELSE
   RHO(I,J,K)=ACC_R/ACC_V
   DO N=1,N_TRACKED_SPECIES
      ZZ(I,J,K,N)=ACC_Z(N)/ACC_V
   ENDDO
ENDIF
END SUBROUTINE CC_DENSITY_PUBLISH

SUBROUTINE DENSITY_SUM_PARTIAL(NM)
INTEGER, INTENT(IN) :: NM
INTEGER :: IG,L,I,J,K
TYPE(CC_FV_TYPE), POINTER :: FV
FV=>MESHES(NM)%FV
DO IG=1,FV%GCELL%N_CUT
   IF (PREDICTOR) THEN
      FV%CV%RHOS(IG)=SUM(FV%CV%ZZS(1:N_TRACKED_SPECIES,IG))
   ELSE
      FV%CV%RHO(IG)=SUM(FV%CV%ZZ(1:N_TRACKED_SPECIES,IG))
   ENDIF
ENDDO
CALL DENSITY_EXT_SCALE(NM,.FALSE.)
DO L=1,SIZE(MESHES(NM)%TH_REG,2)
   I=MESHES(NM)%TH_REG(IAXIS,L); J=MESHES(NM)%TH_REG(JAXIS,L); K=MESHES(NM)%TH_REG(KAXIS,L)
   IF (PREDICTOR) THEN
      RHOS(I,J,K)=SUM(ZZS(I,J,K,1:N_TRACKED_SPECIES))
   ELSE
      RHO(I,J,K)=SUM(ZZ(I,J,K,1:N_TRACKED_SPECIES))
   ENDIF
ENDDO
END SUBROUTINE DENSITY_SUM_PARTIAL

SUBROUTINE DENSITY_EXT_SCALE(NM,DIVIDE)
! Each cell of the run, the same species-vector scaling as the old per-cell
! statement. A divide of the whole I-section is not that operation at -O1.
INTEGER, INTENT(IN) :: NM
LOGICAL, INTENT(IN) :: DIVIDE
INTEGER :: L,I,I1,I2,J,K
DO L=GAS_EXT_PTR(NM-1)+1,GAS_EXT_PTR(NM)
   I1=GAS_EXT_I1(L); I2=GAS_EXT_I2(L); J=GAS_EXT_J(L); K=GAS_EXT_K(L)
   DO I=I1,I2
      IF (PREDICTOR) THEN
         IF (DIVIDE) THEN
            ZZS(I,J,K,1:N_TRACKED_SPECIES)=ZZS(I,J,K,1:N_TRACKED_SPECIES)/RHOS(I,J,K)
         ELSE
            ZZS(I,J,K,1:N_TRACKED_SPECIES)=ZZS(I,J,K,1:N_TRACKED_SPECIES)*RHOS(I,J,K)
         ENDIF
      ELSE
         IF (DIVIDE) THEN
            ZZ(I,J,K,1:N_TRACKED_SPECIES)=ZZ(I,J,K,1:N_TRACKED_SPECIES)/RHO(I,J,K)
         ELSE
            ZZ(I,J,K,1:N_TRACKED_SPECIES)=ZZ(I,J,K,1:N_TRACKED_SPECIES)*RHO(I,J,K)
         ENDIF
      ENDIF
   ENDDO
ENDDO
END SUBROUTINE DENSITY_EXT_SCALE

SUBROUTINE DENSITY_ONE_SPECIES(NM)
INTEGER, INTENT(IN) :: NM
INTEGER :: IG
TYPE(CC_FV_TYPE), POINTER :: FV
FV=>MESHES(NM)%FV
DO IG=1,FV%GCELL%N_CUT
   IF (PREDICTOR) THEN
      FV%CV%ZZS(1,IG)=FV%CV%RHOS(IG)
   ELSE
      FV%CV%ZZ(1,IG)=FV%CV%RHO(IG)
   ENDIF
ENDDO
IF (PREDICTOR) THEN
   ZZS(1:IBAR,1:JBAR,1:KBAR,1)=RHOS(1:IBAR,1:JBAR,1:KBAR)
ELSE
   ZZ(1:IBAR,1:JBAR,1:KBAR,1)=RHO(1:IBAR,1:JBAR,1:KBAR)
ENDIF
END SUBROUTINE DENSITY_ONE_SPECIES

SUBROUTINE DENSITY_APPLY_RHO(NM)
INTEGER, INTENT(IN) :: NM
INTEGER :: IG
TYPE(CC_FV_TYPE), POINTER :: FV
FV=>MESHES(NM)%FV
DO IG=1,FV%GCELL%N_CUT
   IF (PREDICTOR) THEN
      FV%CV%RHOS(IG)=MIN(RHOMAX,MAX(RHOMIN,FV%CV%RHOS(IG)+FV%CV%DELTA_RHO(IG)))
   ELSE
      FV%CV%RHO(IG)=MIN(RHOMAX,MAX(RHOMIN,FV%CV%RHO(IG)+FV%CV%DELTA_RHO(IG)))
   ENDIF
ENDDO
IF (PREDICTOR) THEN
   RHOS(1:IBAR,1:JBAR,1:KBAR)=MIN(RHOMAX,MAX(RHOMIN, &
      RHOS(1:IBAR,1:JBAR,1:KBAR)+WORK4(1:IBAR,1:JBAR,1:KBAR)))
ELSE
   RHO(1:IBAR,1:JBAR,1:KBAR)=MIN(RHOMAX,MAX(RHOMIN, &
      RHO(1:IBAR,1:JBAR,1:KBAR)+WORK4(1:IBAR,1:JBAR,1:KBAR)))
ENDIF
END SUBROUTINE DENSITY_APPLY_RHO

SUBROUTINE DENSITY_APPLY_ZZ(NM,N)
INTEGER, INTENT(IN) :: NM,N
INTEGER :: IG,I,J,K
TYPE(CC_FV_TYPE), POINTER :: FV
FV=>MESHES(NM)%FV
DO IG=1,FV%GCELL%N_CUT
   IF (PREDICTOR) THEN
      FV%CV%ZZS(N,IG)=MIN(FV%CV%RHOS(IG),MAX(0._EB,FV%CV%ZZS(N,IG)+FV%CV%DELTA_RHO_ZZ(IG)))
   ELSE
      FV%CV%ZZ(N,IG)=MIN(FV%CV%RHO(IG),MAX(0._EB,FV%CV%ZZ(N,IG)+FV%CV%DELTA_RHO_ZZ(IG)))
   ENDIF
ENDDO
DO K=1,KBAR
   DO J=1,JBAR
      DO I=1,IBAR
         IF (PREDICTOR) THEN
            ZZS(I,J,K,N)=MIN(RHOS(I,J,K),MAX(0._EB,ZZS(I,J,K,N)+WORK5(I,J,K)))
         ELSE
            ZZ(I,J,K,N)=MIN(RHO(I,J,K),MAX(0._EB,ZZ(I,J,K,N)+WORK5(I,J,K)))
         ENDIF
      ENDDO
   ENDDO
ENDDO
END SUBROUTINE DENSITY_APPLY_ZZ

SUBROUTINE DENSITY_CLOSE(NM)
INTEGER, INTENT(IN) :: NM
INTEGER :: IG,L,I,J,K
TYPE(CC_FV_TYPE), POINTER :: FV
FV=>MESHES(NM)%FV
DO IG=1,FV%GCELL%N_CUT
   CALL DENSITY_CLOSE_CV(FV,IG)
ENDDO
DO L=1,SIZE(MESHES(NM)%TH_REG,2)
   I=MESHES(NM)%TH_REG(IAXIS,L); J=MESHES(NM)%TH_REG(JAXIS,L); K=MESHES(NM)%TH_REG(KAXIS,L)
   CALL DENSITY_CLOSE_CART(I,J,K)
ENDDO
DO L=GAS_EXT_PTR(NM-1)+1,GAS_EXT_PTR(NM)
   DO I=GAS_EXT_I1(L),GAS_EXT_I2(L)
      CALL DENSITY_CLOSE_CART(I,GAS_EXT_J(L),GAS_EXT_K(L))
   ENDDO
ENDDO
END SUBROUTINE DENSITY_CLOSE

SUBROUTINE DENSITY_CLOSE_CV(FV,IG)
TYPE(CC_FV_TYPE), POINTER :: FV
INTEGER, INTENT(IN) :: IG
INTEGER :: N,NS
REAL(EB) :: SUMZ,TEST
NS=N_TRACKED_SPECIES
IF (PREDICTOR) THEN
   SUMZ=SUM(FV%CV%ZZS(1:NS,IG))
   N=MAXLOC(FV%CV%ZZS(1:NS,IG),1)
   TEST=FV%CV%ZZS(N,IG)+FV%CV%RHOS(IG)-SUMZ
   IF (TEST<0._EB .OR. TEST>FV%CV%RHOS(IG)) THEN
      FV%CV%ZZS(1:NS,IG)=FV%CV%RHOS(IG)*FV%CV%ZZS(1:NS,IG)/SUMZ
   ELSE
      FV%CV%ZZS(N,IG)=TEST
   ENDIF
ELSE
   SUMZ=SUM(FV%CV%ZZ(1:NS,IG))
   N=MAXLOC(FV%CV%ZZ(1:NS,IG),1)
   TEST=FV%CV%ZZ(N,IG)+FV%CV%RHO(IG)-SUMZ
   IF (TEST<0._EB .OR. TEST>FV%CV%RHO(IG)) THEN
      FV%CV%ZZ(1:NS,IG)=FV%CV%RHO(IG)*FV%CV%ZZ(1:NS,IG)/SUMZ
   ELSE
      FV%CV%ZZ(N,IG)=TEST
   ENDIF
ENDIF
END SUBROUTINE DENSITY_CLOSE_CV

SUBROUTINE DENSITY_CLOSE_CART(I,J,K)
INTEGER, INTENT(IN) :: I,J,K
INTEGER :: N,NS
REAL(EB) :: SUMZ,TEST
NS=N_TRACKED_SPECIES
IF (PREDICTOR) THEN
   SUMZ=SUM(ZZS(I,J,K,1:NS))
   N=MAXLOC(ZZS(I,J,K,1:NS),1)
   TEST=ZZS(I,J,K,N)+RHOS(I,J,K)-SUMZ
   IF (TEST<0._EB .OR. TEST>RHOS(I,J,K)) THEN
      ZZS(I,J,K,1:NS)=RHOS(I,J,K)*ZZS(I,J,K,1:NS)/SUMZ
   ELSE
      ZZS(I,J,K,N)=TEST
   ENDIF
ELSE
   SUMZ=SUM(ZZ(I,J,K,1:NS))
   N=MAXLOC(ZZ(I,J,K,1:NS),1)
   TEST=ZZ(I,J,K,N)+RHO(I,J,K)-SUMZ
   IF (TEST<0._EB .OR. TEST>RHO(I,J,K)) THEN
      ZZ(I,J,K,1:NS)=RHO(I,J,K)*ZZ(I,J,K,1:NS)/SUMZ
   ELSE
      ZZ(I,J,K,N)=TEST
   ENDIF
ENDIF
END SUBROUTINE DENSITY_CLOSE_CART

SUBROUTINE RHOZZ_PUBLISH(NM,ICC,I,J,K,NSN,ACCR,ACCZ)
INTEGER, INTENT(IN) :: NM,ICC,I,J,K,NSN
REAL(EB), INTENT(IN) :: ACCR,ACCZ(:)
INTEGER :: N
REAL(EB) :: VOLTOT
IF (NSN/=MESHES(NM)%CUT_CELL(ICC)%NCELL) RETURN
VOLTOT=SUM(MESHES(NM)%CUT_CELL(ICC)%VOLUME(1:NSN))
IF (PREDICTOR) THEN
   RHOS(I,J,K)=ACCR/VOLTOT
   DO N=1,N_TOTAL_SCALARS
      ZZS(I,J,K,N)=ACCZ(N)/VOLTOT
   ENDDO
ELSE
   RHO(I,J,K)=ACCR/VOLTOT
   DO N=1,N_TOTAL_SCALARS
      ZZ(I,J,K,N)=ACCZ(N)/VOLTOT
   ENDDO
ENDIF
END SUBROUTINE RHOZZ_PUBLISH

SUBROUTINE RHOZZ_FIX_COLUMN(ZZ,RHOCOL,IG,PRED,NM,ICC,JCC,I,J,K)
REAL(EB), INTENT(INOUT) :: ZZ(:,:),RHOCOL(:)
INTEGER, INTENT(IN) :: IG,NM,ICC,JCC,I,J,K
LOGICAL, INTENT(IN) :: PRED
INTEGER :: N,NMX
REAL(EB) :: RHOV
RHOCOL(IG)=SUM(ZZ(1:N_TRACKED_SPECIES,IG))
RHOV=RHOCOL(IG)
IF (DEBUG_CC_SCALAR_TRANSPORT) THEN
   IF (RHOV<RHOMIN .OR. RHOV>RHOMAX) THEN
      IF (PRED) THEN
         WRITE(LU_ERR,*) 'GET_RHOZZ_CC_3D CC Pred:',ICC,JCC,', Vol Fraction=', &
            MESHES(NM)%CUT_CELL(ICC)%VOLUME(JCC)/(DX(I)*DY(J)*DZ(K)),', UNK_Z=', &
            MESHES(NM)%CUT_CELL(ICC)%UNKZ(JCC)
         WRITE(LU_ERR,*) 'CELL Location=',XC(I),YC(J),ZC(K)
      ELSE
         WRITE(LU_ERR,*) 'GET_RHOZZ_CC_3D CC Corr:',ICC,JCC,', Vol Fraction=', &
            MESHES(NM)%CUT_CELL(ICC)%VOLUME(JCC)/(DX(I)*DY(J)*DZ(K)),', UNK_Z=', &
            MESHES(NM)%CUT_CELL(ICC)%UNKZ(JCC)
      ENDIF
      WRITE(LU_ERR,*) 'RHOP,MIN,MAX=',RHOV,RHOMIN,RHOMAX
   ENDIF
ENDIF
ZZ(1:N_TOTAL_SCALARS,IG)=ZZ(1:N_TOTAL_SCALARS,IG)/RHOV
IF (DEBUG_CC_SCALAR_TRANSPORT) THEN
   DO N=1,N_TOTAL_SCALARS
      IF (ZZ(N,IG)<(0._EB-GEOMEPS) .OR. ZZ(N,IG)>(1._EB+GEOMEPS)) THEN
         IF (PRED) THEN
            WRITE(LU_ERR,*) 'GET_RHOZZ_CC_3D CC Pred:',ICC,JCC,N
         ELSE
            WRITE(LU_ERR,*) 'GET_RHOZZ_CC_3D CC Corr:',ICC,JCC,N
         ENDIF
         WRITE(LU_ERR,*) 'ZZP=',ZZ(N,IG)
      ENDIF
   ENDDO
ELSE
   NMX=MAXLOC(ZZ(1:N_TRACKED_SPECIES,IG),1)
   DO N=1,N_TRACKED_SPECIES
      IF (N==NMX) CYCLE
      IF (ZZ(N,IG)<(0._EB-TWENTY_EPSILON_EB)) THEN
         ZZ(NMX,IG)=ZZ(NMX,IG)+ZZ(N,IG)
         ZZ(N,IG)=0._EB
      ENDIF
   ENDDO
ENDIF
IF (N_PASSIVE_SCALARS>0) ZZ(ZETA_INDEX,IG)=MAX(0._EB,MIN(1._EB,ZZ(ZETA_INDEX,IG)))
END SUBROUTINE RHOZZ_FIX_COLUMN

SUBROUTINE RHOZZ_EXTRACT_REG(I,J,K)
INTEGER, INTENT(IN) :: I,J,K
INTEGER :: N,NMX
REAL(EB) :: RHOV
REAL(EB), POINTER, DIMENSION(:,:,:) :: R3
REAL(EB), POINTER, DIMENSION(:,:,:,:) :: Z4
IF (PREDICTOR) THEN
   R3=>RHOS; Z4=>ZZS
ELSE
   R3=>RHO; Z4=>ZZ
ENDIF
R3(I,J,K)=SUM(Z4(I,J,K,1:N_TRACKED_SPECIES))
RHOV=R3(I,J,K)
IF (DEBUG_CC_SCALAR_TRANSPORT) THEN
   IF (RHOV<RHOMIN .OR. RHOV>RHOMAX) THEN
      WRITE(LU_ERR,*) 'GET_RHOZZ_CC_3D Cart:',I,J,K
      WRITE(LU_ERR,*) 'RHOP,MIN,MAX=',RHOV,RHOMIN,RHOMAX
   ENDIF
ENDIF
Z4(I,J,K,1:N_TOTAL_SCALARS)=Z4(I,J,K,1:N_TOTAL_SCALARS)/RHOV
IF (DEBUG_CC_SCALAR_TRANSPORT) THEN
   DO N=1,N_TOTAL_SCALARS
      IF (Z4(I,J,K,N)<(0._EB-GEOMEPS) .OR. Z4(I,J,K,N)>(1._EB+GEOMEPS)) THEN
         WRITE(LU_ERR,*) 'GET_RHOZZ_CC_3D Cart:',I,J,K,N
         WRITE(LU_ERR,*) 'ZZP=',Z4(I,J,K,N)
      ENDIF
   ENDDO
ELSE
   NMX=MAXLOC(Z4(I,J,K,1:N_TRACKED_SPECIES),1)
   DO N=1,N_TRACKED_SPECIES
      IF (N==NMX) CYCLE
      IF (Z4(I,J,K,N)<(0._EB-TWENTY_EPSILON_EB)) THEN
         Z4(I,J,K,NMX)=Z4(I,J,K,NMX)+Z4(I,J,K,N)
         Z4(I,J,K,N)=0._EB
      ENDIF
   ENDDO
ENDIF
IF (N_PASSIVE_SCALARS>0) Z4(I,J,K,ZETA_INDEX)=MAX(0._EB,MIN(1._EB,Z4(I,J,K,ZETA_INDEX)))
END SUBROUTINE RHOZZ_EXTRACT_REG

SUBROUTINE DENSITY_CLIP(NM,N,HIT,LO,HI)
! N=0 clips density. N>0 clips species partial density. Neighbors come from the setup stencil.
INTEGER, INTENT(IN) :: NM,N
LOGICAL, INTENT(OUT) :: HIT,LO,HI
INTEGER :: S,B,NB,P,NN,I,J,K,IG
REAL(EB) :: VAL,VMIN,VMAX,VCUT,MASS_C,SUMN,CONST,SIGNF,VN,AMT
TYPE(CC_FV_TYPE), POINTER :: FV
FV=>MESHES(NM)%FV
HIT=.FALSE.; LO=.FALSE.; HI=.FALSE.
DO S=CLIP_SRC_PTR(NM-1)+1,CLIP_SRC_PTR(NM)
   I=CLIP_I(S); J=CLIP_J(S); K=CLIP_K(S); IG=CLIP_IG(S)
   CALL DN_CELL(FV,CLIP_KIND(S),I,J,K,IG,N,VAL,VMIN,VMAX)
   IF (VAL>=VMIN .AND. VAL<=VMAX) CYCLE
   HIT=.TRUE.
   IF (VAL<VMIN) THEN
      VCUT=VMIN; SIGNF=1._EB
      IF (N==0) LO=.TRUE.
   ELSE
      VCUT=VMAX; SIGNF=-1._EB
      IF (N==0) HI=.TRUE.
   ENDIF
   MASS_C=ABS(VCUT-VAL)*CLIP_VOL(S)
   P=CLIP_NBR_PTR(S-1)
   NN=CLIP_NBR_PTR(S)-P
   DO B=1,NN
      NB=P+B
      VN=DN_VALUE(FV,CLIP_DEST(NB),CLIP_NI(NB),CLIP_NJ(NB),CLIP_NK(NB),CLIP_NIG(NB),N)
      CLIP_MASS(B)=ABS(MIN(VMAX,MAX(VMIN,VN))-VCUT)*CLIP_NVOL(NB)
   ENDDO
   IF (NN>0) THEN
      SUMN=SUM(CLIP_MASS(1:NN))
   ELSE
      SUMN=0._EB
   ENDIF
   IF (SUMN<=TWENTY_EPSILON_EB) CYCLE
   CONST=SIGNF*MIN(1._EB,MASS_C/SUMN)
   CALL DN_ADD(FV,CLIP_KIND(S),I,J,K,IG,N,CONST*SUMN/CLIP_VOL(S))
   DO B=1,NN
      NB=P+B
      AMT=CONST*CLIP_MASS(B)/CLIP_NVOL(NB)
      CALL DN_ADD(FV,CLIP_DEST(NB),CLIP_NI(NB),CLIP_NJ(NB),CLIP_NK(NB),CLIP_NIG(NB),N,-AMT)
   ENDDO
ENDDO
END SUBROUTINE DENSITY_CLIP

SUBROUTINE DN_CELL(FV,KIND,I,J,K,IG,N,VAL,VMIN,VMAX)
TYPE(CC_FV_TYPE), POINTER :: FV
INTEGER, INTENT(IN) :: KIND,I,J,K,IG,N
REAL(EB), INTENT(OUT) :: VAL,VMIN,VMAX
REAL(EB) :: RHOV
IF (KIND==DN_CUT) THEN
   IF (PREDICTOR) THEN
      RHOV=FV%CV%RHOS(IG)
      IF (N==0) THEN; VAL=RHOV; ELSE; VAL=FV%CV%ZZS(N,IG); ENDIF
   ELSE
      RHOV=FV%CV%RHO(IG)
      IF (N==0) THEN; VAL=RHOV; ELSE; VAL=FV%CV%ZZ(N,IG); ENDIF
   ENDIF
ELSE
   IF (PREDICTOR) THEN
      RHOV=RHOS(I,J,K)
      IF (N==0) THEN; VAL=RHOV; ELSE; VAL=ZZS(I,J,K,N); ENDIF
   ELSE
      RHOV=RHO(I,J,K)
      IF (N==0) THEN; VAL=RHOV; ELSE; VAL=ZZ(I,J,K,N); ENDIF
   ENDIF
ENDIF
IF (N==0) THEN
   VMIN=RHOMIN; VMAX=RHOMAX
ELSE
   VMIN=0._EB; VMAX=RHOV
ENDIF
END SUBROUTINE DN_CELL

REAL(EB) FUNCTION DN_VALUE(FV,DEST,I,J,K,IG,N)
TYPE(CC_FV_TYPE), POINTER :: FV
INTEGER, INTENT(IN) :: DEST,I,J,K,IG,N
IF (DEST==DN_CUT .AND. IG>=1) THEN
   IF (PREDICTOR) THEN
      IF (N==0) THEN; DN_VALUE=FV%CV%RHOS(IG); ELSE; DN_VALUE=FV%CV%ZZS(N,IG); ENDIF
   ELSE
      IF (N==0) THEN; DN_VALUE=FV%CV%RHO(IG); ELSE; DN_VALUE=FV%CV%ZZ(N,IG); ENDIF
   ENDIF
ELSE
   IF (PREDICTOR) THEN
      IF (N==0) THEN; DN_VALUE=RHOS(I,J,K); ELSE; DN_VALUE=ZZS(I,J,K,N); ENDIF
   ELSE
      IF (N==0) THEN; DN_VALUE=RHO(I,J,K); ELSE; DN_VALUE=ZZ(I,J,K,N); ENDIF
   ENDIF
ENDIF
END FUNCTION DN_VALUE

SUBROUTINE DN_ADD(FV,DEST,I,J,K,IG,N,AMT)
TYPE(CC_FV_TYPE), POINTER :: FV
INTEGER, INTENT(IN) :: DEST,I,J,K,IG,N
REAL(EB), INTENT(IN) :: AMT
IF (DEST==DN_CUT) THEN
   IF (IG<1) RETURN
   IF (N==0) THEN
      FV%CV%DELTA_RHO(IG)=FV%CV%DELTA_RHO(IG)+AMT
   ELSE
      FV%CV%DELTA_RHO_ZZ(IG)=FV%CV%DELTA_RHO_ZZ(IG)+AMT
   ENDIF
ELSE
   IF (N==0) THEN
      WORK4(I,J,K)=WORK4(I,J,K)+AMT
   ELSE
      WORK5(I,J,K)=WORK5(I,J,K)+AMT
   ENDIF
ENDIF
END SUBROUTINE DN_ADD

! ----------------------------- CC_DENSITY_EXPLICIT ------------------------

SUBROUTINE CC_DENSITY_EXPLICIT(T,DT)

REAL(EB), INTENT(IN) :: T,DT

! Local variables:
INTEGER :: N
INTEGER :: IROW_LOC
REAL(EB):: DUMMYT

! Just to avoid compilation warnings: T might be used to define a time dependent source.
DUMMYT = T

! Loop through species:
! This loop performs an either implicit or explicit time advancement of the transport equations for each
! chemical species on the cut-cell implicit region, plus explicit reaction (as done on FDS).
! Scalar bounds are checked on the implicit region regular and cut-cells:
SPECIES_LOOP: DO N=1,N_TOTAL_SCALARS

   IF( (PREDICTOR.AND.FIRST_PASS) .OR. CORRECTOR) THEN
      ! RHS vector (Adv+diff)*zz+F_BC, derived from boundary conditions on immersed and domain Boundaries:
      F_Z(:) = 0._EB
      CALL BEGIN_FV_L2_SCALAR_RHS
      CALL GET_EXPLICIT_ADVDIFFVECTOR_SCALAR_3D(N)

      ! Add Advective fluxes for F_Z:
      CALL GET_ADVDIFFVECTOR_SCALAR_3D(N)

      ! Here add the reaction source term M_DOT_PPP, treated explicitly:
      CALL GET_M_DOT_PPP_SCALAR_3D(N)

      IF (PERIODIC_TEST==7) CALL GET_SHUNN3_QZ(T,N)
      IF (PERIODIC_TEST==21 .OR. PERIODIC_TEST==22 .OR. PERIODIC_TEST==23) CALL CC_ROTATED_CUBE_RHS_ZZ(T,N)
      CALL END_FV_L2_SCALAR_RHS

      ! Get rho*zz vector at step n:
      CALL GET_RHOZZVECTOR_SCALAR_3D(N)
   ENDIF

   IF (PREDICTOR) THEN
      IF (FIRST_PASS) THEN
         F_Z0(:,N) = F_Z(:)
         RZ_Z0(:,N) = RZ_Z(:)
      ELSE
         F_Z(:) = F_Z0(:,N)
         RZ_Z(:)= RZ_Z0(:,N)
      ENDIF
   ENDIF

   IF (PREDICTOR) THEN

      ! Here F_Z: (Adv+Diff)*(rho z)^n + F^n
      ! Advance with Explicit Euler: RZ_Z = RZ_Z - DT*M_MAT_Z^-1*F_Z: where initially
      ! RZ_Z = (rho z)^n, filled in GET_RHOZZVECTOR_SCALAR_3D
      DO IROW_LOC=1,NUNKZ_LOCAL
         RZ_Z(IROW_LOC) = RZ_Z(IROW_LOC) - DT * F_Z(IROW_LOC) / M_MAT_Z(IROW_LOC)
      ENDDO

   ELSE ! CORRECTOR

      ! Here F_Z: (Adv+Diff)*(rho z)^* + F^*
      ! Advance with Corrector SSPRK2: RZ_Z = RZ_Z - DT/2*M_MAT_Z^-1*F_Z: where initially
      ! RZ_Z = 1/2*((rho z)^n + (rho z)^*)
      DO IROW_LOC=1,NUNKZ_LOCAL
         RZ_Z(IROW_LOC) = RZ_Z(IROW_LOC) - 0.5_EB * DT * F_Z(IROW_LOC) / M_MAT_Z(IROW_LOC)
      ENDDO

   ENDIF

   ! Copy back to RHOZZP and CUT_CELL:
   CALL PUT_RHOZZVECTOR_SCALAR_3D(N)

ENDDO SPECIES_LOOP

! Redistribute densities if needed.
CALL CC_CHECK_MASS_DENSITY

! Recompute RHOP, and check for positivity, define mass fraction ZZ and clip if necessary:
CALL GET_RHOZZ_CC_3D

RETURN
END SUBROUTINE CC_DENSITY_EXPLICIT

! ---------------------------- GET_M_DOT_PPP_SCALAR_3D ---------------------------

SUBROUTINE GET_M_DOT_PPP_SCALAR_3D(N)

INTEGER, INTENT(IN) :: N
! Local Variables:
INTEGER :: NM,I,J,K,ICC,JCC,IGC,IUNK
TYPE(CC_FV_TYPE), POINTER :: FV

! Mesh Loop:
MESH_LOOP : DO NM=LOWER_MESH_INDEX,UPPER_MESH_INDEX

   ! D_SOURCE(:,:,:) and M_DOT_PPP(:,:,:,:) are allocated together,
   ! => if one is not allocated the other also is not allocated.
   IF(.NOT.ALLOCATED(MESHES(NM)%D_SOURCE)) CYCLE MESH_LOOP

   CALL POINT_TO_MESH(NM)
   FV=>MESHES(NM)%FV

   ! First add M_DOT_PPP on regular cells to source F_Z. L2 uses one unified GCELL pass below
   ! so contributions to a CV row owned by another mesh can be reduced to its owning rank.

   ! Then add cut-CV contributions to F_Z.
      DO IGC=1,FV%GCELL%N
         IUNK=FV%GCELL%ROW_Z(IGC)
         IF (IUNK<1) CYCLE
         I=FV%GCELL%IJK(IAXIS,IGC)
         J=FV%GCELL%IJK(JAXIS,IGC)
         K=FV%GCELL%IJK(KAXIS,IGC)
         IF (CELL(CELL_INDEX(I,J,K))%SOLID) CYCLE
         SELECT CASE(FV%GCELL%CELL_TYPE(IGC))
         CASE(CC_GCELL_CUT)
            ICC=FV%GCELL%ICC(IGC); JCC=FV%GCELL%JCC(IGC)
            CALL ADD_FV_L2_SCALAR_RHS(IUNK,-FV%CV%M_DOT_PPP(N,IGC)*FV%GCELL%VOLUME(IGC))
         CASE(CC_GCELL_REG)
            CALL ADD_FV_L2_SCALAR_RHS(IUNK,-M_DOT_PPP(I,J,K,N)*FV%GCELL%VOLUME(IGC))
         END SELECT
      ENDDO
      DO K=1,KBAR
         DO J=1,JBAR
            DO I=1,IBAR
               IUNK=CCVAR(I,J,K,CC_UNKZ)
               IF (IUNK<1 .OR. FV_L2_SCALAR_ROW_IS_FV(NM,IUNK)) CYCLE
               CALL ADD_FV_L2_SCALAR_RHS(IUNK,-M_DOT_PPP(I,J,K,N)*DX(I)*DY(J)*DZ(K))
            ENDDO
         ENDDO
      ENDDO

   ! Finally if Corrector zero out M_DOT_PPP and D_SOURCE:
   IF (CORRECTOR) THEN
      M_DOT_PPP(:,:,:,N) = 0._EB
      FV%CV%M_DOT_PPP(N,:)=0._EB
      IF (N==N_TOTAL_SCALARS) FV%CV%D_SOURCE=0._EB
      IF (N==N_TOTAL_SCALARS) D_SOURCE(:,:,:)=0._EB
   ENDIF

ENDDO MESH_LOOP

RETURN
END SUBROUTINE GET_M_DOT_PPP_SCALAR_3D


! ---------------------- GET_EXPLICIT_ADVDIFFVECTOR_SCALAR_3D --------------------

SUBROUTINE GET_EXPLICIT_ADVDIFFVECTOR_SCALAR_3D(N)
! Explicit scalar advection into the L2 right-hand side, one walk over external faces.
! Gas and periodic regular faces, gas RC faces, and gas cut faces. Real walls are the
! other routine. The I-axis flux still carries the cylindrical radius R(I).

INTEGER, INTENT(IN) :: N
INTEGER :: NM,I,J,K,AX,IREG,IRC,ICF,JCF,IW,IH,JH,KH,IF_,IFV,UNK_LO,UNK_HI
REAL(EB) :: PRFCT,AF,VELC,FN,RHOZZ
REAL(EB), POINTER, DIMENSION(:,:,:) :: RHOP
REAL(EB), POINTER, DIMENSION(:,:,:,:) :: ZZP
TYPE(CC_FV_TYPE), POINTER :: FV
LOGICAL :: DO_LO,DO_HI,FOUND

U_TEMP=>U_WORK; F_TEMP=>F_WORK; Z_TEMP=>Z_WORK

MESH_LOOP : DO NM=LOWER_MESH_INDEX,UPPER_MESH_INDEX
   CALL POINT_TO_MESH(NM)
   FV=>MESHES(NM)%FV
   IF (PREDICTOR) THEN
      ZZP=>ZZ; RHOP=>RHO; PRFCT=1._EB
   ELSE
      ZZP=>ZZS; RHOP=>RHOS; PRFCT=0._EB
   ENDIF
   ! Past N_INT: regular-face tail and unclaimed RC rows, as in the divergence walks.
   DO IF_=1,FV%FACE%N
      IF (FV%FACE%ROLE(IF_)/=CC_FACE_ROLE_EXTERNAL) CYCLE
      SELECT CASE(FV%FACE%FTYPE(IF_))
      CASE(CC_FTYPE_RGGAS)
         IREG=FV%FACE%SRC_IREG(IF_)
         IF (IREG<1) CYCLE
         AX=FV%FACE%X1AXIS(IF_)
         CALL EX_REG_IJK(AX,IREG,I,J,K,IW,DO_LO,DO_HI)
         IF (IW>0) THEN
            IF (WALL(IW)%BOUNDARY_TYPE/=INTERPOLATED_BOUNDARY) THEN
               IF (WALL(IW)%BOUNDARY_TYPE/=PERIODIC_BOUNDARY) CYCLE
            ENDIF
         ENDIF
         CALL EX_REG_FLUX(N,AX,I,J,K,RHOZZ,AF)
         CALL EX_HIGH(AX,I,J,K,IH,JH,KH)
         FOUND=.FALSE.
         IFV=EX_REG_FC(AX,IREG)
         IF (IFV>=1) CALL CC_FV_CACHE_ADVECTIVE_REGULAR_FACE(NM,IFV,RHOZZ,FOUND)
         IF (.NOT.FOUND) THEN
            IF (DO_LO) CALL ADD_FV_L2_SCALAR_RHS(CCVAR(I,J,K,CC_UNKZ),RHOZZ*AF)
            IF (DO_HI) CALL ADD_FV_L2_SCALAR_RHS(CCVAR(IH,JH,KH,CC_UNKZ),-RHOZZ*AF)
         ENDIF
      CASE(CC_FTYPE_RCGAS)
         IRC=FV%FACE%SRC_IRC(IF_)
         IF (IRC<1 .OR. IRC>MESHES(NM)%CC_NRCFACE_Z) CYCLE
         IF (RC_FACE(IRC)%IWC>0) CYCLE
         I=RC_FACE(IRC)%IJK(IAXIS); J=RC_FACE(IRC)%IJK(JAXIS); K=RC_FACE(IRC)%IJK(KAXIS)
         AX=RC_FACE(IRC)%IJK(KAXIS+1)
         CALL EX_AREA_VEL(AX,I,J,K,AF,VELC)
         CALL EX_LIMIT(NM,AX,I,J,K,IRC,0,0,VELC,RHOP,ZZP,PRFCT,N,FN)
         IFV=RC_FACE(IRC)%FC
         IF (IFV>=1) THEN
            IF (FV%FACE%FTYPE(IFV)==CC_FTYPE_RCGAS) THEN
               CALL CC_FV_ADD_ADVECTIVE_FACE(NM,IFV,FN*VELC)
               CYCLE
            ENDIF
         ENDIF
         CALL EX_SIDE_IUNK(NM,IF_,AX,LOW_IND,IRC,0,0,UNK_LO)
         CALL EX_SIDE_IUNK(NM,IF_,AX,HIGH_IND,IRC,0,0,UNK_HI)
         CALL ADD_FV_L2_SCALAR_RHS(UNK_LO,FN*VELC*AF)
         CALL ADD_FV_L2_SCALAR_RHS(UNK_HI,-FN*VELC*AF)
      CASE(CC_FTYPE_CFGAS)
         ICF=FV%FACE%SRC_ICF(IF_); JCF=FV%FACE%SRC_JCF(IF_)
         IF (ICF<1 .OR. ICF>MESHES(NM)%N_CUTFACE_MESH) CYCLE
         IF (CUT_FACE(ICF)%STATUS/=CC_GASPHASE) CYCLE
         IF (CUT_FACE(ICF)%IWC>0) CYCLE
         I=CUT_FACE(ICF)%IJK(IAXIS); J=CUT_FACE(ICF)%IJK(JAXIS); K=CUT_FACE(ICF)%IJK(KAXIS)
         AX=CUT_FACE(ICF)%IJK(KAXIS+1); AF=CUT_FACE(ICF)%AREA(JCF)
         VELC=PRFCT*CC_FV_CUTFACE_MOM(NM,ICF,JCF,CC_FV_MOM_VEL) + &
              (1._EB-PRFCT)*CC_FV_CUTFACE_MOM(NM,ICF,JCF,CC_FV_MOM_VELS)
         CALL EX_LIMIT(NM,AX,I,J,K,0,ICF,JCF,VELC,RHOP,ZZP,PRFCT,N,FN)
         IFV=CUT_FACE(ICF)%FC(JCF)
         IF (IFV>=1) THEN
            IF (FV%FACE%FTYPE(IFV)==CC_FTYPE_CFGAS) THEN
               CALL CC_FV_ADD_ADVECTIVE_FACE(NM,IFV,FN*VELC)
               CYCLE
            ENDIF
         ENDIF
         CALL EX_SIDE_IUNK(NM,IF_,AX,LOW_IND,0,ICF,JCF,UNK_LO)
         CALL EX_SIDE_IUNK(NM,IF_,AX,HIGH_IND,0,ICF,JCF,UNK_HI)
         CALL ADD_FV_L2_SCALAR_RHS(UNK_LO,FN*VELC*AF)
         CALL ADD_FV_L2_SCALAR_RHS(UNK_HI,-FN*VELC*AF)
      END SELECT
   ENDDO
   ! Diffusion on regular cells the FV map does not own. Cut CVs are the face walk below.
   DO K=1,KBAR
      DO J=1,JBAR
         DO I=1,IBAR
            IF (CCVAR(I,J,K,CC_UNKZ)<=0) CYCLE
            IF (FV_L2_SCALAR_ROW_IS_FV(NM,CCVAR(I,J,K,CC_UNKZ))) CYCLE
            CALL ADD_FV_L2_SCALAR_RHS(CCVAR(I,J,K,CC_UNKZ), &
                                      -DEL_RHO_D_DEL_Z(I,J,K,N)*DX(I)*DY(J)*DZ(K))
         ENDDO
      ENDDO
   ENDDO
   CALL GET_FV_L2_DIFFUSIVE_VECTOR(NM,N)
ENDDO MESH_LOOP
RETURN
END SUBROUTINE GET_EXPLICIT_ADVDIFFVECTOR_SCALAR_3D

SUBROUTINE CC_FV_CACHE_ADVECTIVE_REGULAR_FACE(NM,IF_,FLUX,FOUND)
INTEGER, INTENT(IN) :: NM,IF_
REAL(EB), INTENT(IN) :: FLUX
LOGICAL, INTENT(OUT) :: FOUND
TYPE(CC_FV_TYPE), POINTER :: FV

FV=>MESHES(NM)%FV
FOUND=.FALSE.
IF (FV%FACE%NBR_CV(IF_)<1) RETURN
IF (FV%FACE%NBR_CV_NM(IF_)==NM) THEN
   IF (FV%CV%N_MEMBER(FV%FACE%NBR_CV(IF_))<1) RETURN
ENDIF
CALL CC_FV_ADD_ADVECTIVE_FACE(NM,IF_,FLUX)
FOUND=.TRUE.
END SUBROUTINE CC_FV_CACHE_ADVECTIVE_REGULAR_FACE





SUBROUTINE GET_FV_L2_DIFFUSIVE_VECTOR(NM,N)
! Assemble the scalar diffusion row from canonical FV faces. ADD_FV_L2_SCALAR_RHS no-ops IUNK<1
! (boundary / unnumbered). Regular implicit halo outside the FV map stays on the Cartesian path.
INTEGER, INTENT(IN) :: NM,N
INTEGER :: IF_,AX,IUNK,OWN_NM,NBR_NM,IW
REAL(EB) :: ORIENT,AREA,ZF
TYPE(CC_FV_TYPE), POINTER :: FV

FV=>MESHES(NM)%FV
DO IF_=1,FV%FACE%N_INT
   IF (FV%FACE%ROLE(IF_)/=CC_FACE_ROLE_EXTERNAL) CYCLE
   OWN_NM=FV%FACE%OWNER_CV_NM(IF_); NBR_NM=FV%FACE%NBR_CV_NM(IF_)
   IF (FV%FACE%KIND(IF_)==CC_FACE_KIND_REMOTE .AND. NM/=MIN(OWN_NM,NBR_NM)) CYCLE
   IW = FV%FACE%IWC(IF_)
   IF (IW>0) THEN
      IF (WALL(IW)%BOUNDARY_TYPE==NULL_BOUNDARY) CYCLE
   ENDIF

   AX=FV%FACE%X1AXIS(IF_); ZF=FV%FACE%DIFF_FLUX(N,IF_)
   SELECT CASE(FV%FACE%FTYPE(IF_))
   CASE(CC_FTYPE_RGGAS,CC_FTYPE_RCGAS,CC_FTYPE_CFGAS)
      ORIENT=FV%FACE%NVEC(AX,IF_)
   CASE(CC_FTYPE_CFINB)
      ORIENT=-1._EB
   CASE DEFAULT
      CYCLE
   END SELECT

   AREA=FV%FACE%FLUX_AREA(IF_)
   IUNK=FV%FACE%UNKZ_OWN(IF_)
   CALL ADD_FV_L2_SCALAR_RHS(IUNK,-ORIENT*ZF*AREA)
   IUNK=FV%FACE%UNKZ_NBR(IF_)
   CALL ADD_FV_L2_SCALAR_RHS(IUNK,ORIENT*ZF*AREA)
ENDDO
END SUBROUTINE GET_FV_L2_DIFFUSIVE_VECTOR

! --------------------------- CC_CHECK_MASS_DENSITY ------------------------

SUBROUTINE CC_CHECK_MASS_DENSITY
INTEGER :: NM,N
LOGICAL :: RHO_LO,RHO_HI,HIT,LO,HI,ZZ_HIT
TYPE(CC_FV_TYPE), POINTER :: FV
DO NM=LOWER_MESH_INDEX,UPPER_MESH_INDEX
   CALL POINT_TO_MESH(NM)
   FV=>MESHES(NM)%FV
   WORK4=0._EB
   IF (ALLOCATED(FV%CV%DELTA_RHO)) FV%CV%DELTA_RHO=0._EB
   CALL DENSITY_SUM_PARTIAL(NM)
   CALL DENSITY_CLIP(NM,0,HIT,RHO_LO,RHO_HI)
   IF (RHO_LO .OR. RHO_HI) CALL DENSITY_APPLY_RHO(NM)
   CLIP_RHOMIN=CLIP_RHOMIN .OR. RHO_LO
   CLIP_RHOMAX=CLIP_RHOMAX .OR. RHO_HI
   IF (N_TRACKED_SPECIES==1) THEN
      IF (RHO_LO .OR. RHO_HI) CALL DENSITY_ONE_SPECIES(NM)
      CALL DENSITY_EXT_SCALE(NM,.TRUE.)
      CYCLE
   ENDIF
   ZZ_HIT=.FALSE.
   DO N=1,N_TRACKED_SPECIES
      WORK5=0._EB
      IF (ALLOCATED(FV%CV%DELTA_RHO_ZZ)) FV%CV%DELTA_RHO_ZZ=0._EB
      CALL DENSITY_CLIP(NM,N,HIT,LO,HI)
      IF (.NOT.HIT) CYCLE
      ZZ_HIT=.TRUE.
      CALL DENSITY_APPLY_ZZ(NM,N)
   ENDDO
   IF (.NOT.RHO_LO .AND. .NOT.RHO_HI .AND. .NOT.ZZ_HIT) THEN
      CALL DENSITY_EXT_SCALE(NM,.TRUE.)
      CYCLE
   ENDIF
   CALL DENSITY_CLOSE(NM)
   CALL DENSITY_EXT_SCALE(NM,.TRUE.)
ENDDO
CALL CC_FV_L2_RHOZZ_AVERAGE
RETURN
CONTAINS

SUBROUTINE CC_FV_L2_RHOZZ_AVERAGE
! Volume-average rho*Z over each scalar row (slots of CC_SET_THERMO_ROWS; Q(0,:) volume, Q(1:,:) rho*Z volume
! integral) and scatter the common state to every member. A shared row is summed on its owner's process and returned.
INTEGER :: NM,I,J,K,ICC,JCC,IS,L,IG,NS
REAL(EB) :: VOL
REAL(EB), ALLOCATABLE :: Q(:,:)
TYPE(MESH_TYPE), POINTER :: MFV
TYPE(CC_FV_TYPE), POINTER :: FV

NS=N_TRACKED_SPECIES
ALLOCATE(Q(0:NS,MAX(1,TH_NSLOT))); Q=0._EB
DO NM=LOWER_MESH_INDEX,UPPER_MESH_INDEX
   MFV=>MESHES(NM)
   FV=>MFV%FV
   DO L=1,SIZE(MFV%TH_REG,2)
      I=MFV%TH_REG(IAXIS,L); J=MFV%TH_REG(JAXIS,L); K=MFV%TH_REG(KAXIS,L); IS=MFV%TH_REG(4,L)
      VOL=MFV%DX(I)*MFV%DY(J)*MFV%DZ(K)
      Q(0,IS)=Q(0,IS)+VOL
      IF (PREDICTOR) THEN
         Q(1:NS,IS)=Q(1:NS,IS)+MFV%ZZS(I,J,K,1:NS)*VOL
      ELSE
         Q(1:NS,IS)=Q(1:NS,IS)+MFV%ZZ(I,J,K,1:NS)*VOL
      ENDIF
   ENDDO
   DO ICC=1,MFV%N_CUTCELL_MESH
      I=MFV%CUT_CELL(ICC)%IJK(IAXIS); J=MFV%CUT_CELL(ICC)%IJK(JAXIS); K=MFV%CUT_CELL(ICC)%IJK(KAXIS)
      IF (MFV%CELL(MFV%CELL_INDEX(I,J,K))%SOLID) CYCLE
      DO L=MFV%TH_CPTR(ICC),MFV%TH_CPTR(ICC+1)-1
         JCC=MFV%TH_CUT(1,L); IS=MFV%TH_CUT(2,L)
         VOL=MFV%CUT_CELL(ICC)%VOLUME(JCC)
         Q(0,IS)=Q(0,IS)+VOL
         IG=MFV%CUT_CELL(ICC)%IG(JCC)
         IF (IG<1) THEN
            IF (PREDICTOR) THEN
               Q(1:NS,IS)=Q(1:NS,IS)+MFV%ZZS(I,J,K,1:NS)*VOL
            ELSE
               Q(1:NS,IS)=Q(1:NS,IS)+MFV%ZZ(I,J,K,1:NS)*VOL
            ENDIF
         ELSE IF (PREDICTOR) THEN
            Q(1:NS,IS)=Q(1:NS,IS)+FV%CV%ZZS(1:NS,IG)*VOL
         ELSE
            Q(1:NS,IS)=Q(1:NS,IS)+FV%CV%ZZ(1:NS,IG)*VOL
         ENDIF
      ENDDO
   ENDDO
ENDDO
CALL SCALAR_ROWS_TO_OWNER(Q,TH_SSLOT,TH_SDEST,TH_RSLOT)
DO IS=1,TH_NSLOT
   IF (Q(0,IS)<=TWO_EPSILON_EB) CYCLE
   Q(1:NS,IS)=Q(1:NS,IS)/Q(0,IS)
ENDDO
CALL SCALAR_ROWS_FROM_OWNER(Q,TH_RSLOT,TH_RDEST,TH_BSLOT)
DO NM=LOWER_MESH_INDEX,UPPER_MESH_INDEX
   MFV=>MESHES(NM)
   FV=>MFV%FV
   DO L=1,SIZE(MFV%TH_REG,2)
      I=MFV%TH_REG(IAXIS,L); J=MFV%TH_REG(JAXIS,L); K=MFV%TH_REG(KAXIS,L); IS=MFV%TH_REG(4,L)
      IF (PREDICTOR) THEN
         MFV%ZZS(I,J,K,1:NS)=Q(1:NS,IS)
      ELSE
         MFV%ZZ(I,J,K,1:NS)=Q(1:NS,IS)
      ENDIF
   ENDDO
   DO ICC=1,MFV%N_CUTCELL_MESH
      I=MFV%CUT_CELL(ICC)%IJK(IAXIS); J=MFV%CUT_CELL(ICC)%IJK(JAXIS); K=MFV%CUT_CELL(ICC)%IJK(KAXIS)
      IF (MFV%CELL(MFV%CELL_INDEX(I,J,K))%SOLID) CYCLE
      DO L=MFV%TH_CPTR(ICC),MFV%TH_CPTR(ICC+1)-1
         JCC=MFV%TH_CUT(1,L); IS=MFV%TH_CUT(2,L)
         IG=MFV%CUT_CELL(ICC)%IG(JCC); IF (IG<1) CYCLE
         IF (PREDICTOR) THEN
            FV%CV%ZZS(1:NS,IG)=Q(1:NS,IS)
         ELSE
            FV%CV%ZZ(1:NS,IG)=Q(1:NS,IS)
         ENDIF
      ENDDO
   ENDDO
ENDDO
END SUBROUTINE CC_FV_L2_RHOZZ_AVERAGE

END SUBROUTINE CC_CHECK_MASS_DENSITY


! ------------------------------ GET_RHOZZ_CC_3D ---------------------------

SUBROUTINE GET_RHOZZ_CC_3D
INTEGER :: NM,IG,ICC,ICC0,JCC,NSN,I0,J0,K0,N,L,I,J,K
REAL(EB) :: ACCR,VOL
REAL(EB) :: ACCZ(N_TOTAL_SCALARS)
TYPE(CC_FV_TYPE), POINTER :: FV
DO NM=LOWER_MESH_INDEX,UPPER_MESH_INDEX
   CALL POINT_TO_MESH(NM)
   FV=>MESHES(NM)%FV
   ICC0=0; NSN=0; I0=0; J0=0; K0=0; ACCR=0._EB; ACCZ=0._EB
   DO IG=1,FV%GCELL%N_CUT
      ICC=FV%GCELL%ICC(IG)
      IF (ICC/=ICC0) THEN
         IF (NSN>0) CALL RHOZZ_PUBLISH(NM,ICC0,I0,J0,K0,NSN,ACCR,ACCZ)
         ICC0=ICC
         I0=FV%GCELL%IJK(IAXIS,IG); J0=FV%GCELL%IJK(JAXIS,IG); K0=FV%GCELL%IJK(KAXIS,IG)
         NSN=0; ACCR=0._EB; ACCZ=0._EB
      ENDIF
      JCC=FV%GCELL%JCC(IG)
      VOL=CUT_CELL(ICC)%VOLUME(JCC)
      IF (PREDICTOR) THEN
         CALL RHOZZ_FIX_COLUMN(FV%CV%ZZS,FV%CV%RHOS,IG,.TRUE.,NM,ICC,JCC,I0,J0,K0)
         ACCR=ACCR+FV%CV%RHOS(IG)*VOL
         DO N=1,N_TOTAL_SCALARS
            ACCZ(N)=ACCZ(N)+FV%CV%ZZS(N,IG)*VOL
         ENDDO
      ELSE
         CALL RHOZZ_FIX_COLUMN(FV%CV%ZZ,FV%CV%RHO,IG,.FALSE.,NM,ICC,JCC,I0,J0,K0)
         ACCR=ACCR+FV%CV%RHO(IG)*VOL
         DO N=1,N_TOTAL_SCALARS
            ACCZ(N)=ACCZ(N)+FV%CV%ZZ(N,IG)*VOL
         ENDDO
      ENDIF
      NSN=NSN+1
   ENDDO
   IF (NSN>0) CALL RHOZZ_PUBLISH(NM,ICC0,I0,J0,K0,NSN,ACCR,ACCZ)
   DO L=1,SIZE(MESHES(NM)%TH_REG,2)
      I=MESHES(NM)%TH_REG(IAXIS,L); J=MESHES(NM)%TH_REG(JAXIS,L); K=MESHES(NM)%TH_REG(KAXIS,L)
      CALL RHOZZ_EXTRACT_REG(I,J,K)
   ENDDO
ENDDO
END SUBROUTINE GET_RHOZZ_CC_3D



SUBROUTINE GET_FV_L2_RHOZZVECTOR_SCALAR_3D(N)
! Gather member scalar state by scalar row (slots of CC_SET_THERMO_ROWS; Q(1,:) state, Q(2,:) predictor state,
! Q(3,:) volume), summed on the row's owner process. Predictor rows are conservative volume averages. Corrector rows
! use the same volume-weighted midpoint state, replacing partition-local assignment order with a deterministic
! cross-mesh reduction.
INTEGER, INTENT(IN) :: N
INTEGER :: NM,I,J,K,ICC,JCC,IS,IROW,IG,L
REAL(EB) :: VOL
REAL(EB), ALLOCATABLE :: Q(:,:)
TYPE(MESH_TYPE), POINTER :: MFV
TYPE(CC_FV_TYPE), POINTER :: FV

ALLOCATE(Q(3,MAX(1,TH_NSLOT))); Q=0._EB
DO NM=LOWER_MESH_INDEX,UPPER_MESH_INDEX
   MFV=>MESHES(NM)
   FV=>MFV%FV
   DO L=1,SIZE(MFV%TH_REG,2)
      I=MFV%TH_REG(IAXIS,L); J=MFV%TH_REG(JAXIS,L); K=MFV%TH_REG(KAXIS,L); IS=MFV%TH_REG(4,L)
      VOL=MFV%DX(I)*MFV%DY(J)*MFV%DZ(K)
      Q(3,IS)=Q(3,IS)+VOL
      IF (PREDICTOR) THEN
         Q(1,IS)=Q(1,IS)+VOL*MFV%RHO(I,J,K)*MFV%ZZ(I,J,K,N)
      ELSE
         Q(1,IS)=Q(1,IS)+0.5_EB*VOL*(MFV%RHO_ZZN(I,J,K,N)+MFV%RHOS(I,J,K)*MFV%ZZS(I,J,K,N))
         Q(2,IS)=Q(2,IS)+VOL*MFV%RHOS(I,J,K)*MFV%ZZS(I,J,K,N)
      ENDIF
   ENDDO
   DO ICC=1,MFV%N_CUTCELL_MESH
      I=MFV%CUT_CELL(ICC)%IJK(IAXIS); J=MFV%CUT_CELL(ICC)%IJK(JAXIS); K=MFV%CUT_CELL(ICC)%IJK(KAXIS)
      IF (MFV%CELL(MFV%CELL_INDEX(I,J,K))%SOLID) CYCLE
      DO L=MFV%TH_CPTR(ICC),MFV%TH_CPTR(ICC+1)-1
         JCC=MFV%TH_CUT(1,L); IS=MFV%TH_CUT(2,L)
         VOL=MFV%CUT_CELL(ICC)%VOLUME(JCC); Q(3,IS)=Q(3,IS)+VOL
         IG=MFV%CUT_CELL(ICC)%IG(JCC)
         IF (IG<1) THEN
            IF (PREDICTOR) THEN
               Q(1,IS)=Q(1,IS)+VOL*MFV%RHO(I,J,K)*MFV%ZZ(I,J,K,N)
            ELSE
               Q(1,IS)=Q(1,IS)+0.5_EB*VOL*(MFV%RHO(I,J,K)*MFV%ZZ(I,J,K,N)+ &
                                           MFV%RHOS(I,J,K)*MFV%ZZS(I,J,K,N))
               Q(2,IS)=Q(2,IS)+VOL*MFV%RHOS(I,J,K)*MFV%ZZS(I,J,K,N)
            ENDIF
         ELSE IF (PREDICTOR) THEN
            Q(1,IS)=Q(1,IS)+VOL*FV%CV%RHO(IG)*FV%CV%ZZ(N,IG)
         ELSE
            Q(1,IS)=Q(1,IS)+0.5_EB*VOL*(FV%CV%RHO(IG)*FV%CV%ZZ(N,IG)+ &
                                        FV%CV%RHOS(IG)*FV%CV%ZZS(N,IG))
            Q(2,IS)=Q(2,IS)+VOL*FV%CV%RHOS(IG)*FV%CV%ZZS(N,IG)
         ENDIF
      ENDDO
   ENDDO
ENDDO
CALL SCALAR_ROWS_TO_OWNER(Q,TH_SSLOT,TH_SDEST,TH_RSLOT)
DO IROW=1,NUNKZ_LOCAL
   IS=TH_OSLOT(IROW); IF (IS<1) CYCLE
   IF (Q(3,IS)<=TWO_EPSILON_EB) CYCLE
   RZ_Z(IROW)=Q(1,IS)/Q(3,IS)
   IF (CORRECTOR) RZ_ZS(IROW)=Q(2,IS)/Q(3,IS)
ENDDO
END SUBROUTINE GET_FV_L2_RHOZZVECTOR_SCALAR_3D


SUBROUTINE PUT_FV_L2_RHOZZVECTOR_SCALAR_3D(N)
! Scatter the owner-row scalar results (RZ_Z) to every local member; a row owned on another process comes back from
! there (slots of CC_SET_THERMO_ROWS). On the corrector, ZZS remains the predictor state already scattered by the
! preceding predictor call; only the final ZZ state in RZ_Z is replaced, matching the non-L2 SSPRK2 path.
INTEGER, INTENT(IN) :: N
INTEGER :: NM,I,J,K,ICC,JCC,IS,IROW,ICV,IG,IPTR,L
REAL(EB), ALLOCATABLE :: Q(:,:)
TYPE(MESH_TYPE), POINTER :: MFV
TYPE(CC_FV_TYPE), POINTER :: FV

ALLOCATE(Q(1,MAX(1,TH_NSLOT))); Q=0._EB
DO IROW=1,NUNKZ_LOCAL
   IS=TH_OSLOT(IROW); IF (IS>0) Q(1,IS)=RZ_Z(IROW)
ENDDO
CALL SCALAR_ROWS_FROM_OWNER(Q,TH_RSLOT,TH_RDEST,TH_BSLOT)
DO NM=LOWER_MESH_INDEX,UPPER_MESH_INDEX
   MFV=>MESHES(NM)
   FV=>MFV%FV
   DO L=1,SIZE(MFV%TH_REG,2)
      I=MFV%TH_REG(IAXIS,L); J=MFV%TH_REG(JAXIS,L); K=MFV%TH_REG(KAXIS,L); IS=MFV%TH_REG(4,L)
      IF (PREDICTOR) THEN
         MFV%ZZS(I,J,K,N)=Q(1,IS)
      ELSE
         MFV%ZZ(I,J,K,N)=Q(1,IS)
      ENDIF
   ENDDO
   DO L=1,SIZE(MFV%TH_OCV,2)
      ICV=MFV%TH_OCV(1,L); IS=MFV%TH_OCV(2,L)
      IF (PREDICTOR) THEN
         FV%CV%ZZS(N,ICV)=Q(1,IS)
         DO IPTR=FV%CV%MEMBER_PTR(ICV),FV%CV%MEMBER_PTR(ICV+1)-1
            IG=FV%CV%MEMBER_LIST(IPTR)
            IF (IG>=1 .AND. IG/=ICV) FV%CV%ZZS(N,IG)=Q(1,IS)
         ENDDO
      ELSE
         FV%CV%ZZ(N,ICV)=Q(1,IS)
         DO IPTR=FV%CV%MEMBER_PTR(ICV),FV%CV%MEMBER_PTR(ICV+1)-1
            IG=FV%CV%MEMBER_LIST(IPTR)
            IF (IG>=1 .AND. IG/=ICV) FV%CV%ZZ(N,IG)=Q(1,IS)
         ENDDO
      ENDIF
   ENDDO
   DO ICC=1,MFV%N_CUTCELL_MESH
      DO L=MFV%TH_CPTR(ICC),MFV%TH_CPTR(ICC+1)-1
         JCC=MFV%TH_CUT(1,L); IS=MFV%TH_CUT(2,L)
         IG=MFV%CUT_CELL(ICC)%IG(JCC); IF (IG<1) CYCLE
         IF (PREDICTOR) THEN
            FV%CV%ZZS(N,IG)=Q(1,IS)
         ELSE
            FV%CV%ZZ(N,IG)=Q(1,IS)
         ENDIF
      ENDDO
   ENDDO
ENDDO
END SUBROUTINE PUT_FV_L2_RHOZZVECTOR_SCALAR_3D

! --------------------------- PUT_RHOZZVECTOR_SCALAR_3D --------------------------

SUBROUTINE PUT_RHOZZVECTOR_SCALAR_3D(N)

INTEGER, INTENT(IN) :: N


   CALL PUT_FV_L2_RHOZZVECTOR_SCALAR_3D(N)
END SUBROUTINE PUT_RHOZZVECTOR_SCALAR_3D


! --------------------------- GET_RHOZZVECTOR_SCALAR_3D --------------------------

SUBROUTINE GET_RHOZZVECTOR_SCALAR_3D(N)

INTEGER, INTENT(IN) :: N


! Initialize rho*z:
RZ_Z(:) = 0._EB
RZ_ZS(:) = 0._EB

   CALL GET_FV_L2_RHOZZVECTOR_SCALAR_3D(N)
END SUBROUTINE GET_RHOZZVECTOR_SCALAR_3D


! ----------------------------- GET_CCIFACE_SCALAR_LIM -------------------------
! At an INTERPOLATED-boundary face with a solid outer stencil cell, replace FN by the flux-limited bar{rho*Z_N},
! or bar{rho*h_s} for N=0, with that cell set to its neighbor. Both meshes see the same stencil.
SUBROUTINE GET_CCIFACE_SCALAR_LIM(X1AXIS,IFC,JFC,KFC,N,IW,PRFCT,FN)
USE PHYSICAL_FUNCTIONS, ONLY: GET_SENSIBLE_ENTHALPY

INTEGER, INTENT(IN) :: X1AXIS,IFC,JFC,KFC,N,IW
REAL(EB), INTENT(IN) :: PRFCT
REAL(EB), INTENT(INOUT):: FN
INTEGER :: DD,II,JJ,KK,SHFT(3)
LOGICAL :: SLD(-2:1)
REAL(EB) :: RZPV(-2:1),ZZ_GET(1:N_TRACKED_SPECIES),H_S
REAL(EB), POINTER, DIMENSION(:,:,:)   :: RHOP,UP
REAL(EB), POINTER, DIMENSION(:,:,:,:) :: ZZP
REAL(EB), TARGET  :: ZT(0:3,1,1),UT(1,1,1),FT(1,1,1)
REAL(EB), POINTER, DIMENSION(:,:,:) :: ZTP,UTP,FTP

IF (EXTERNAL_WALL(IW)%AREA_RATIO<=0.99_EB) RETURN

IF (PRFCT > 0.5_EB) THEN; RHOP=>RHO ; ZZP=>ZZ   ! PRFCT=1 -> n-level fields
ELSE                    ; RHOP=>RHOS; ZZP=>ZZS  ! PRFCT=0 -> star fields
ENDIF

SELECT CASE(X1AXIS)
CASE(IAXIS); SHFT=(/1,0,0/); IF (PREDICTOR) THEN; UP=>U; ELSE; UP=>US; ENDIF
CASE(JAXIS); SHFT=(/0,1,0/); IF (PREDICTOR) THEN; UP=>V; ELSE; UP=>VS; ENDIF
CASE(KAXIS); SHFT=(/0,0,1/); IF (PREDICTOR) THEN; UP=>W; ELSE; UP=>WS; ENDIF
END SELECT

! Solid test on the outer stencil cells DD=-2,1: cell(DD) = base_face_cell + (1+DD) along the face axis.
SLD = .FALSE.
DO DD=-2,1,3
   II=IFC+(1+DD)*SHFT(1); JJ=JFC+(1+DD)*SHFT(2); KK=KFC+(1+DD)*SHFT(3)
   SLD(DD)=CCVAR(II,JJ,KK,CC_CGSC)==CC_SOLID
   IF (II>=1.AND.II<=IBAR .AND. JJ>=1.AND.JJ<=JBAR .AND. KK>=1.AND.KK<=KBAR) SLD(DD)=SLD(DD).OR.CELL(CELL_INDEX(II,JJ,KK))%SOLID
ENDDO
IF (.NOT.SLD(-2) .AND. .NOT.SLD(1)) RETURN

! Cartesian rho*Z_N (rho*h_s) on the gas stencil cells; a solid outer cell takes its neighbor's value.
DO DD=-2,1
   IF (SLD(DD)) CYCLE
   II=IFC+(1+DD)*SHFT(1); JJ=JFC+(1+DD)*SHFT(2); KK=KFC+(1+DD)*SHFT(3)
   IF (N>0) THEN
      RZPV(DD)=RHOP(II,JJ,KK)*ZZP(II,JJ,KK,N)
   ELSE
      ZZ_GET(1:N_TRACKED_SPECIES)=ZZP(II,JJ,KK,1:N_TRACKED_SPECIES)
      CALL GET_SENSIBLE_ENTHALPY(ZZ_GET,H_S,TMP(II,JJ,KK))
      RZPV(DD)=RHOP(II,JJ,KK)*H_S
   ENDIF
ENDDO
IF (SLD(-2)) RZPV(-2)=RZPV(-1)
IF (SLD( 1)) RZPV( 1)=RZPV( 0)
ZT(0:3,1,1)=RZPV(-2:1); UT(1,1,1)=UP(IFC,JFC,KFC)
ZTP=>ZT; UTP=>UT; FTP=>FT
CALL GET_SCALAR_FACE_VALUE(UTP,ZTP,FTP,1,1,1,1,1,1,1,I_FLUX_LIMITER)
FN=FT(1,1,1)

RETURN
END SUBROUTINE GET_CCIFACE_SCALAR_LIM


! ------------------------- GET_ADVDIFFVECTOR_SCALAR_3D -------------------------

SUBROUTINE GET_ADVDIFFVECTOR_SCALAR_3D(N)
! Wall and in-boundary scalar advection into the L2 right-hand side, one face walk.
! Periodic and interpolated regular faces are gas faces and stay in the explicit routine.

INTEGER, INTENT(IN) :: N
INTEGER :: NM,I,J,K,AX,IREG,IRC,ICF,JCF,IW,IH,JH,KH,IF_,ILOC,IOR,ICC,JCC,ICFA,IUNK
REAL(EB) :: PRFCT,AF,VELC,FN,RHOZZ,FCT,RHO_Z
TYPE(CC_FV_TYPE), POINTER :: FV
TYPE(WALL_TYPE), POINTER :: WC
TYPE(BOUNDARY_PROP1_TYPE), POINTER :: B1
TYPE(BOUNDARY_COORD_TYPE), POINTER :: BC
TYPE(CFACE_TYPE), POINTER :: CFA
LOGICAL :: DO_LO,DO_HI

MESH_LOOP_DBND : DO NM=LOWER_MESH_INDEX,UPPER_MESH_INDEX
   CALL POINT_TO_MESH(NM)
   FV=>MESHES(NM)%FV
   IF (PREDICTOR) THEN; PRFCT=1._EB; ELSE; PRFCT=0._EB; ENDIF
   DO IF_=1,FV%FACE%N
      ! A mesh-interface RC face is internal to one CV. Each mesh visits its own copy and
      ! deposits that member's one-sided flux; the two signs are opposite and cancel in
      ! the cross-mesh sum.
      ! Internal RC faces are one side of a mesh-interface CV. Internal cut faces on a wall
      ! are the same one-sided deposit the old cut-face loop kept; a gas cut face with no
      ! wall still drops out below.
      IF (FV%FACE%ROLE(IF_)/=CC_FACE_ROLE_EXTERNAL .AND. FV%FACE%FTYPE(IF_)/=CC_FTYPE_RCGAS .AND. &
          FV%FACE%FTYPE(IF_)/=CC_FTYPE_CFGAS) CYCLE
      SELECT CASE(FV%FACE%FTYPE(IF_))
      CASE(CC_FTYPE_RGGAS)
         IREG=FV%FACE%SRC_IREG(IF_)
         IF (IREG<1) CYCLE
         AX=FV%FACE%X1AXIS(IF_)
         CALL EX_REG_IJK(AX,IREG,I,J,K,IW,DO_LO,DO_HI)
         IF (IW<1) CYCLE
         IF (WALL(IW)%BOUNDARY_TYPE==NULL_BOUNDARY) CYCLE
         IF (WALL(IW)%BOUNDARY_TYPE==INTERPOLATED_BOUNDARY) CYCLE
         IF (WALL(IW)%BOUNDARY_TYPE==PERIODIC_BOUNDARY) CYCLE
         CALL EX_REG_FLUX(N,AX,I,J,K,RHOZZ,AF)
         CALL EX_HIGH(AX,I,J,K,IH,JH,KH)
         IF (DO_LO) CALL ADD_FV_L2_SCALAR_RHS(CCVAR(I,J,K,CC_UNKZ),RHOZZ*AF)
         IF (DO_HI) CALL ADD_FV_L2_SCALAR_RHS(CCVAR(IH,JH,KH,CC_UNKZ),-RHOZZ*AF)
      CASE(CC_FTYPE_RCGAS)
         IRC=FV%FACE%SRC_IRC(IF_)
         IF (IRC<1 .OR. IRC>MESHES(NM)%CC_NRCFACE_Z) CYCLE
         IW=RC_FACE(IRC)%IWC
         IF (IW<1) CYCLE
         IF (WALL(IW)%BOUNDARY_TYPE==NULL_BOUNDARY) CYCLE
         WC=>WALL(IW); B1=>BOUNDARY_PROP1(WC%B1_INDEX); BC=>BOUNDARY_COORD(WC%BC_INDEX)
         I=RC_FACE(IRC)%IJK(IAXIS); J=RC_FACE(IRC)%IJK(JAXIS); K=RC_FACE(IRC)%IJK(KAXIS)
         AX=RC_FACE(IRC)%IJK(KAXIS+1)
         IOR=BC%IOR
         ILOC=1+(SIGN(1,IOR)+1)/2
         FCT=REAL(3-2*ILOC,EB)
         CALL EX_SIDE_IUNK(NM,IF_,AX,ILOC,IRC,0,0,IUNK)
         ! Mesh-interface copy: same Cartesian flux as the other mesh's regular face,
         ! with this member's outward sign, so the pair sums to zero.
         IF (FV%FACE%ROLE(IF_)==CC_FACE_ROLE_INTERNAL .AND. WC%BOUNDARY_TYPE==INTERPOLATED_BOUNDARY) THEN
            CALL EX_REG_FLUX(N,AX,I,J,K,RHOZZ,AF)
            CALL ADD_FV_L2_SCALAR_RHS(IUNK,FCT*RHOZZ*AF)
         ELSE
            CALL EX_WALL_STATE(AX,I,J,K,IW,WC,B1,PRFCT,N,AF,VELC,FN)
            CALL ADD_FV_L2_SCALAR_RHS(IUNK,FCT*FN*VELC*AF)
         ENDIF
      CASE(CC_FTYPE_CFGAS)
         ICF=FV%FACE%SRC_ICF(IF_); JCF=FV%FACE%SRC_JCF(IF_)
         IF (ICF<1 .OR. ICF>MESHES(NM)%N_CUTFACE_MESH) CYCLE
         IF (CUT_FACE(ICF)%STATUS/=CC_GASPHASE) CYCLE
         IW=CUT_FACE(ICF)%IWC
         IF (IW<1) CYCLE
         ! Two FV rows share a thin cut piece. The wall loop fluxes each, so the piece
         ! would be deposited twice. Keep the row CUT_FACE%FC names; it uses this same
         ! wall velocity and CUT_FACE%AREA.
         IF (CC_GRID_WALL_IS_THIN_BARRIER(NM,IW)) THEN
            IF (CUT_FACE(ICF)%FC(JCF)/=IF_) CYCLE
         ENDIF
         IF (WALL(IW)%BOUNDARY_TYPE==NULL_BOUNDARY) CYCLE
         WC=>WALL(IW); B1=>BOUNDARY_PROP1(WC%B1_INDEX); BC=>BOUNDARY_COORD(WC%BC_INDEX)
         I=CUT_FACE(ICF)%IJK(IAXIS); J=CUT_FACE(ICF)%IJK(JAXIS); K=CUT_FACE(ICF)%IJK(KAXIS)
         AX=CUT_FACE(ICF)%IJK(KAXIS+1)
         FN=B1%RHO_F*B1%ZZ_F(N)
         IF (WC%BOUNDARY_TYPE==INTERPOLATED_BOUNDARY) THEN
            CALL EX_CART_FLUX(AX,I,J,K,N,FN)
            CALL GET_CCIFACE_SCALAR_LIM(AX,I,J,K,N,IW,PRFCT,FN)
            VELC=FV%FACE%VEL_SAVE(CUT_FACE(ICF)%FC(JCF))
         ELSE
            VELC=PRFCT*CC_FV_CUTFACE_MOM(NM,ICF,JCF,CC_FV_MOM_VEL) + &
                 (1._EB-PRFCT)*CC_FV_CUTFACE_MOM(NM,ICF,JCF,CC_FV_MOM_VELS)
         ENDIF
         IOR=BC%IOR
         ILOC=1+(SIGN(1,IOR)+1)/2
         FCT=REAL(3-2*ILOC,EB)
         IF (CUT_FACE(ICF)%CELL_LIST(1,ILOC,JCF)/=CC_FTYPE_CFGAS) CYCLE
         AF=CUT_FACE(ICF)%AREA(JCF)
         CALL EX_SIDE_IUNK(NM,IF_,AX,ILOC,0,ICF,JCF,IUNK)
         CALL ADD_FV_L2_SCALAR_RHS(IUNK,FCT*FN*VELC*AF)
      CASE(CC_FTYPE_CFINB)
         ICF=FV%FACE%SRC_ICF(IF_); JCF=FV%FACE%SRC_JCF(IF_)
         IF (ICF<1 .OR. ICF>MESHES(NM)%N_CUTFACE_MESH) CYCLE
         ICFA=CUT_FACE(ICF)%CFACE_INDEX(JCF)
         IF (ICFA<INTERNAL_CFACE_CELLS_LB+1) CYCLE
         IF (ICFA>INTERNAL_CFACE_CELLS_LB+N_INTERNAL_CFACE_CELLS) CYCLE
         CFA=>CFACE(ICFA); B1=>BOUNDARY_PROP1(CFA%B1_INDEX)
         ICC=CUT_FACE(ICF)%CELL_LIST(2,LOW_IND,JCF); JCC=CUT_FACE(ICF)%CELL_LIST(3,LOW_IND,JCF)
         IF (PREDICTOR) THEN; VELC=B1%U_NORMAL; ELSE; VELC=B1%U_NORMAL_S; ENDIF
         IF (VELC>0._EB) THEN
            RHO_Z=GET_CUTCELL_RHOP(NM,ICC,JCC,PRFCT)*GET_CUTCELL_ZZP(NM,ICC,JCC,N,PRFCT)
         ELSE
            RHO_Z=B1%RHO_F*B1%ZZ_F(N)
         ENDIF
         CALL EX_SIDE_IUNK(NM,IF_,0,LOW_IND,0,0,0,IUNK)
         IF (IUNK<1) IUNK=CUT_CELL(ICC)%UNKZ(JCC)
         CALL ADD_FV_L2_SCALAR_RHS(IUNK,RHO_Z*VELC*CFA%AREA)
      END SELECT
   ENDDO
ENDDO MESH_LOOP_DBND
RETURN
END SUBROUTINE GET_ADVDIFFVECTOR_SCALAR_3D


SUBROUTINE EX_REG_IJK(AX,IREG,I,J,K,IW,DO_LO,DO_HI)
INTEGER, INTENT(IN) :: AX,IREG
INTEGER, INTENT(OUT) :: I,J,K,IW
LOGICAL, INTENT(OUT) :: DO_LO,DO_HI
I=0; J=0; K=0; IW=0; DO_LO=.FALSE.; DO_HI=.FALSE.
SELECT CASE(AX)
CASE(IAXIS)
   I=CC_REGFACE_IAXIS_Z(IREG)%IJK(IAXIS); J=CC_REGFACE_IAXIS_Z(IREG)%IJK(JAXIS)
   K=CC_REGFACE_IAXIS_Z(IREG)%IJK(KAXIS); IW=CC_REGFACE_IAXIS_Z(IREG)%IWC
   DO_LO=CC_REGFACE_IAXIS_Z(IREG)%DO_LO_IND; DO_HI=CC_REGFACE_IAXIS_Z(IREG)%DO_HI_IND
CASE(JAXIS)
   I=CC_REGFACE_JAXIS_Z(IREG)%IJK(IAXIS); J=CC_REGFACE_JAXIS_Z(IREG)%IJK(JAXIS)
   K=CC_REGFACE_JAXIS_Z(IREG)%IJK(KAXIS); IW=CC_REGFACE_JAXIS_Z(IREG)%IWC
   DO_LO=CC_REGFACE_JAXIS_Z(IREG)%DO_LO_IND; DO_HI=CC_REGFACE_JAXIS_Z(IREG)%DO_HI_IND
CASE(KAXIS)
   I=CC_REGFACE_KAXIS_Z(IREG)%IJK(IAXIS); J=CC_REGFACE_KAXIS_Z(IREG)%IJK(JAXIS)
   K=CC_REGFACE_KAXIS_Z(IREG)%IJK(KAXIS); IW=CC_REGFACE_KAXIS_Z(IREG)%IWC
   DO_LO=CC_REGFACE_KAXIS_Z(IREG)%DO_LO_IND; DO_HI=CC_REGFACE_KAXIS_Z(IREG)%DO_HI_IND
END SELECT
END SUBROUTINE EX_REG_IJK

INTEGER FUNCTION EX_REG_FC(AX,IREG)
INTEGER, INTENT(IN) :: AX,IREG
EX_REG_FC=0
SELECT CASE(AX)
CASE(IAXIS); EX_REG_FC=CC_REGFACE_IAXIS_Z(IREG)%FC
CASE(JAXIS); EX_REG_FC=CC_REGFACE_JAXIS_Z(IREG)%FC
CASE(KAXIS); EX_REG_FC=CC_REGFACE_KAXIS_Z(IREG)%FC
END SELECT
END FUNCTION EX_REG_FC

SUBROUTINE EX_REG_FLUX(N,AX,I,J,K,RHOZZ,AF)
! I-axis only: the cylindrical radius sits on that flux. J and K do not.
INTEGER, INTENT(IN) :: N,AX,I,J,K
REAL(EB), INTENT(OUT) :: RHOZZ,AF
RHOZZ=0._EB; AF=0._EB
SELECT CASE(AX)
CASE(IAXIS); RHOZZ=FX(I,J,K,N)*WORK_U(I,J,K)*R(I); AF=DY(J)*DZ(K)
CASE(JAXIS); RHOZZ=FY(I,J,K,N)*WORK_V(I,J,K); AF=DX(I)*DZ(K)
CASE(KAXIS); RHOZZ=FZ(I,J,K,N)*WORK_W(I,J,K); AF=DX(I)*DY(J)
END SELECT
END SUBROUTINE EX_REG_FLUX

SUBROUTINE EX_HIGH(AX,I,J,K,IH,JH,KH)
INTEGER, INTENT(IN) :: AX,I,J,K
INTEGER, INTENT(OUT) :: IH,JH,KH
IH=I; JH=J; KH=K
SELECT CASE(AX)
CASE(IAXIS); IH=I+1
CASE(JAXIS); JH=J+1
CASE(KAXIS); KH=K+1
END SELECT
END SUBROUTINE EX_HIGH

SUBROUTINE EX_AREA_VEL(AX,I,J,K,AF,VEL)
INTEGER, INTENT(IN) :: AX,I,J,K
REAL(EB), INTENT(OUT) :: AF,VEL
AF=0._EB; VEL=0._EB
SELECT CASE(AX)
CASE(IAXIS); AF=DY(J)*DZ(K); VEL=WORK_U(I,J,K)
CASE(JAXIS); AF=DX(I)*DZ(K); VEL=WORK_V(I,J,K)
CASE(KAXIS); AF=DX(I)*DY(J); VEL=WORK_W(I,J,K)
END SELECT
END SUBROUTINE EX_AREA_VEL

SUBROUTINE EX_OFF(AX,I,J,K,OFF,IS,JS,KS)
INTEGER, INTENT(IN) :: AX,I,J,K,OFF
INTEGER, INTENT(OUT) :: IS,JS,KS
IS=I; JS=J; KS=K
SELECT CASE(AX)
CASE(IAXIS); IS=I+OFF
CASE(JAXIS); JS=J+OFF
CASE(KAXIS); KS=K+OFF
END SELECT
END SUBROUTINE EX_OFF

SUBROUTINE EX_LIMIT(NM,AX,I,J,K,IRC,ICF,JCF,VEL,RHOP,ZZP,PRFCT,N,FN)
! Four-point stencil in increasing-index order. Velocity is the signed component.
! A cut face initializes the two center densities to -1, as the polygon loop did.
! Pointer dummies keep the Cartesian lower bound, which includes the ghost layer.
INTEGER, INTENT(IN) :: NM,AX,I,J,K,IRC,ICF,JCF,N
REAL(EB), INTENT(IN) :: VEL,PRFCT
REAL(EB), POINTER, INTENT(IN) :: RHOP(:,:,:),ZZP(:,:,:,:)
REAL(EB), INTENT(OUT) :: FN
REAL(EB) :: SIDE(-2:1),RHOV(-2:1),ZZN
INTEGER :: ISIDE,IS,JS,KS,ICC,JCC
DO ISIDE=-2,1
   CALL EX_OFF(AX,I,J,K,1+ISIDE,IS,JS,KS)
   RHOV(ISIDE)=RHOP(IS,JS,KS)
ENDDO
IF (ICF>0) RHOV(-1:0)=-1._EB
ZZN=0._EB
DO ISIDE=-1,0
   CALL EX_OFF(AX,I,J,K,1+ISIDE,IS,JS,KS)
   IF (IRC>0) THEN
      SELECT CASE(RC_FACE(IRC)%CELL_LIST(1,ISIDE+2))
      CASE(CC_FTYPE_RGGAS)
         ZZN=ZZP(IS,JS,KS,N)
      CASE(CC_FTYPE_CFGAS)
         ICC=RC_FACE(IRC)%CELL_LIST(2,ISIDE+2); JCC=RC_FACE(IRC)%CELL_LIST(3,ISIDE+2)
         RHOV(ISIDE)=GET_CUTCELL_RHOP(NM,ICC,JCC,PRFCT)
         ZZN=GET_CUTCELL_ZZP(NM,ICC,JCC,N,PRFCT)
      END SELECT
   ENDIF
   IF (ICF>0) THEN
      IF (CUT_FACE(ICF)%CELL_LIST(1,ISIDE+2,JCF)==CC_FTYPE_CFGAS) THEN
         ICC=CUT_FACE(ICF)%CELL_LIST(2,ISIDE+2,JCF); JCC=CUT_FACE(ICF)%CELL_LIST(3,ISIDE+2,JCF)
         RHOV(ISIDE)=GET_CUTCELL_RHOP(NM,ICC,JCC,PRFCT)
         ZZN=GET_CUTCELL_ZZP(NM,ICC,JCC,N,PRFCT)
      ENDIF
   ENDIF
   SIDE(ISIDE)=RHOV(ISIDE)*ZZN
ENDDO
CALL EX_OFF(AX,I,J,K,-1,IS,JS,KS)
IF (CELL(CELL_INDEX(IS,JS,KS))%SOLID .OR. CCVAR(IS,JS,KS,CC_CGSC)==CC_SOLID) THEN
   SIDE(-2)=SIDE(-1)
ELSE
   SIDE(-2)=RHOV(-2)*ZZP(IS,JS,KS,N)
ENDIF
CALL EX_OFF(AX,I,J,K,2,IS,JS,KS)
IF (CELL(CELL_INDEX(IS,JS,KS))%SOLID .OR. CCVAR(IS,JS,KS,CC_CGSC)==CC_SOLID) THEN
   SIDE(1)=SIDE(0)
ELSE
   SIDE(1)=RHOV(1)*ZZP(IS,JS,KS,N)
ENDIF
Z_TEMP(0:3,1,1)=SIDE(-2:1)
U_TEMP(1,1,1)=VEL
CALL GET_SCALAR_FACE_VALUE(U_TEMP,Z_TEMP,F_TEMP,1,1,1,1,1,1,1,I_FLUX_LIMITER)
FN=F_TEMP(1,1,1)
END SUBROUTINE EX_LIMIT

SUBROUTINE EX_CART_FLUX(AX,I,J,K,N,FN)
INTEGER, INTENT(IN) :: AX,I,J,K,N
REAL(EB), INTENT(OUT) :: FN
FN=0._EB
SELECT CASE(AX)
CASE(IAXIS); FN=FX(I,J,K,N)
CASE(JAXIS); FN=FY(I,J,K,N)
CASE(KAXIS); FN=FZ(I,J,K,N)
END SELECT
END SUBROUTINE EX_CART_FLUX

SUBROUTINE EX_WALL_STATE(AX,I,J,K,IW,WC,B1,PRFCT,N,AF,VEL,FN)
INTEGER, INTENT(IN) :: AX,I,J,K,IW,N
REAL(EB), INTENT(IN) :: PRFCT
TYPE(WALL_TYPE), POINTER, INTENT(IN) :: WC
TYPE(BOUNDARY_PROP1_TYPE), POINTER, INTENT(IN) :: B1
REAL(EB), INTENT(OUT) :: AF,VEL,FN
INTEGER :: IOR
TYPE(BOUNDARY_COORD_TYPE), POINTER :: BC
BC=>BOUNDARY_COORD(WC%BC_INDEX)
IOR=BC%IOR
CALL EX_AREA_VEL(AX,I,J,K,AF,VEL)
FN=B1%RHO_F*B1%ZZ_F(N)
IF (WC%BOUNDARY_TYPE==SOLID_BOUNDARY) THEN
   IF (PREDICTOR) VEL=-SIGN(1._EB,REAL(IOR,EB))*B1%U_NORMAL_S
   IF (CORRECTOR) VEL=-SIGN(1._EB,REAL(IOR,EB))*B1%U_NORMAL
ENDIF
IF (WC%BOUNDARY_TYPE==INTERPOLATED_BOUNDARY) THEN
   VEL=UVW_SAVE(IW)
   CALL EX_CART_FLUX(AX,I,J,K,N,FN)
   CALL GET_CCIFACE_SCALAR_LIM(AX,I,J,K,N,IW,PRFCT,FN)
ENDIF
END SUBROUTINE EX_WALL_STATE

SUBROUTINE EX_SIDE_IUNK(NM,IF_,AX,ISIDE,IRC,ICF,JCF,IUNK)
! Scalar row of one face side, from the face row. NVEC(axis) >= 0 means the owner CV is
! the low side. AX < 1 is an in-boundary face: the gas side is the owner. A seam or orphan
! row has no CV; the cell list is that same side and is not RC_FACE%UNKZ or CUT_FACE%UNKZ.
INTEGER, INTENT(IN) :: NM,IF_,AX,ISIDE,IRC,ICF,JCF
INTEGER, INTENT(OUT) :: IUNK
INTEGER :: OWN,NBR,II,JJ,KK,ICC,JCC
TYPE(CC_FV_TYPE), POINTER :: FV
FV=>MESHES(NM)%FV
OWN=FV%FACE%UNKZ_OWN(IF_)
NBR=FV%FACE%UNKZ_NBR(IF_)
IF (AX<1) THEN
   IUNK=OWN
ELSEIF (FV%FACE%NVEC(AX,IF_)>=0._EB) THEN
   IF (ISIDE==LOW_IND) THEN; IUNK=OWN; ELSE; IUNK=NBR; ENDIF
ELSE
   IF (ISIDE==LOW_IND) THEN; IUNK=NBR; ELSE; IUNK=OWN; ENDIF
ENDIF
IF (IUNK>=1) RETURN
IUNK=0
IF (IRC>0) THEN
   SELECT CASE(RC_FACE(IRC)%CELL_LIST(1,ISIDE))
   CASE(CC_FTYPE_RGGAS)
      II=RC_FACE(IRC)%CELL_LIST(2,ISIDE); JJ=RC_FACE(IRC)%CELL_LIST(3,ISIDE)
      KK=RC_FACE(IRC)%CELL_LIST(4,ISIDE)
      IUNK=CCVAR(II,JJ,KK,CC_UNKZ)
   CASE(CC_FTYPE_CFGAS)
      ICC=RC_FACE(IRC)%CELL_LIST(2,ISIDE); JCC=RC_FACE(IRC)%CELL_LIST(3,ISIDE)
      IUNK=CUT_CELL(ICC)%UNKZ(JCC)
   END SELECT
ENDIF
IF (IUNK<1 .AND. ICF>0) THEN
   IF (CUT_FACE(ICF)%CELL_LIST(1,ISIDE,JCF)==CC_FTYPE_CFGAS) THEN
      ICC=CUT_FACE(ICF)%CELL_LIST(2,ISIDE,JCF); JCC=CUT_FACE(ICF)%CELL_LIST(3,ISIDE,JCF)
      IUNK=CUT_CELL(ICC)%UNKZ(JCC)
   ENDIF
ENDIF
END SUBROUTINE EX_SIDE_IUNK

! ----------------------- CC_RESCALE_OMESH_STAGGERED_TO_CUTFACE --------------------------
SUBROUTINE CC_RESCALE_OMESH_STAGGERED_TO_CUTFACE(NM,APPLY_TO_ESTIMATED_VARIABLES)
INTEGER, INTENT(IN) :: NM
LOGICAL, INTENT(IN) :: APPLY_TO_ESTIMATED_VARIABLES
INTEGER :: NN,NOM,II,JJ,KK
TYPE(MESH_TYPE), POINTER :: MR,MS
TYPE(OMESH_TYPE), POINTER :: OM
REAL(EB) :: FAC
MR => MESHES(NM)
DO NN=1, MR%N_NEIGHBORING_MESHES
   NOM = MR%NEIGHBORING_MESH(NN); IF (NOM==NM .AND. MR%OMESH(NOM)%NIC_R==0) CYCLE
   OM => MR%OMESH(NOM)
   MS => MESHES(NOM); IF (.NOT.ALLOCATED(MS%FCVAR) .OR. .NOT.ALLOCATED(OM%U) .OR. OM%I_MAX_R<OM%I_MIN_R) CYCLE
   DO KK=OM%K_MIN_R, OM%K_MAX_R
      DO JJ=OM%J_MIN_R, OM%J_MAX_R
         DO II=OM%I_MIN_R, OM%I_MAX_R
            IF (APPLY_TO_ESTIMATED_VARIABLES) THEN
               FAC = OM_CART_TO_VEL_CF(MS,II,JJ,KK,IAXIS); OM%US(II,JJ,KK) = OM%US(II,JJ,KK)*FAC
               FAC = OM_CART_TO_VEL_CF(MS,II,JJ,KK,JAXIS); OM%VS(II,JJ,KK) = OM%VS(II,JJ,KK)*FAC
               FAC = OM_CART_TO_VEL_CF(MS,II,JJ,KK,KAXIS); OM%WS(II,JJ,KK) = OM%WS(II,JJ,KK)*FAC
            ELSE
               FAC = OM_CART_TO_VEL_CF(MS,II,JJ,KK,IAXIS); OM%U(II,JJ,KK) = OM%U(II,JJ,KK)*FAC
               FAC = OM_CART_TO_VEL_CF(MS,II,JJ,KK,JAXIS); OM%V(II,JJ,KK) = OM%V(II,JJ,KK)*FAC
               FAC = OM_CART_TO_VEL_CF(MS,II,JJ,KK,KAXIS); OM%W(II,JJ,KK) = OM%W(II,JJ,KK)*FAC
            ENDIF
         ENDDO
      ENDDO
   ENDDO
ENDDO

CONTAINS
REAL(EB) FUNCTION OM_CART_TO_VEL_CF(M2,II,JJ,KK,X1AXIS)
TYPE(MESH_TYPE), POINTER, INTENT(IN) :: M2
INTEGER, INTENT(IN) :: II,JJ,KK,X1AXIS
OM_CART_TO_VEL_CF = 1._EB
IF (M2%FCVAR(II,JJ,KK,CC_IDCF,X1AXIS) > 0) &
   OM_CART_TO_VEL_CF = 1._EB/MAX(M2%CUT_FACE(M2%FCVAR(II,JJ,KK,CC_IDCF,X1AXIS))%ALPHA_CF,TWO_EPSILON_EB)
END FUNCTION OM_CART_TO_VEL_CF

END SUBROUTINE CC_RESCALE_OMESH_STAGGERED_TO_CUTFACE

! ---------------------------- CC_VELOCITY_BC -------------------------------

SUBROUTINE CC_VELOCITY_BC(T,NM,APPLY_TO_ESTIMATED_VARIABLES,DO_IBEDGES,USE_OM_VEL_CF)

USE TURBULENCE, ONLY : WALL_MODEL
USE PHYSICAL_FUNCTIONS, ONLY: GET_VISCOSITY
REAL(EB), INTENT(IN) :: T
INTEGER, INTENT(IN) :: NM
LOGICAL, INTENT(IN) :: APPLY_TO_ESTIMATED_VARIABLES, DO_IBEDGES
LOGICAL, INTENT(IN), OPTIONAL :: USE_OM_VEL_CF

! Local Variables:
INTEGER :: IEDGE,EP,INPE,VIND
INTEGER :: I,J,K,II,JJ,KK,ICF,LCF,JCF,IF_,IE,IEC,I_SGN,ICD,ICD_SGN,IIF,JJF,KKF,FAXIS,ICDO,ICDO_SGN,IS
REAL(EB), ALLOCATABLE, DIMENSION(:,:,:) :: UVW_EP
REAL(EB), ALLOCATABLE, DIMENSION(:,:,:,:) :: DUVW_EP
REAL(EB), POINTER, DIMENSION(:,:,:) :: UU,VV,WW,RHOP
REAL(EB), POINTER, DIMENSION(:,:,:,:) :: ZZP
REAL(EB) :: NU,MU_FACE,RHO_FACE,DXN_STRM_UB,SLIP_FACTOR,SRGH,U_TAU,Y_PLUS,TNOW,MU_EP,MU_DUIDXJ_USE(2),DUIDXJ_USE(2),&
            DUIDXJ(-2:2),MU_DUIDXJ(-2:2),DXX(2),DF, DE, UE, UF, UB, VEL_CART, PRFCT
TYPE(CC_EDGE_TYPE), POINTER :: CC_EDGE
TYPE(CC_CUTEDGE_TYPE), POINTER :: CE
LOGICAL :: IS_RCEDGE, PRE_GHOST

TNOW = T
TNOW = CURRENT_TIME()

PRE_GHOST = .FALSE.; IF (PRESENT(USE_OM_VEL_CF)) PRE_GHOST = USE_OM_VEL_CF
IF (APPLY_TO_ESTIMATED_VARIABLES) THEN
   UU   => US
   VV   => VS
   WW   => WS
   ZZP  => ZZS
   RHOP => RHOS
   PRFCT=  1._EB
ELSE
   UU   => U
   VV   => V
   WW   => W
   ZZP  => ZZ
   RHOP => RHO
   PRFCT=  0._EB
ENDIF

ALLOCATE(UVW_EP(IAXIS:KAXIS,0:INT_N_EXT_PTS,0:0))
ALLOCATE(DUVW_EP(IAXIS:KAXIS,IAXIS:KAXIS,0:INT_N_EXT_PTS,0:0))

! Ghost cut-face velocities:
! This is done for cut-faces that live in the first layer of ghost-cells, needed in VELOCITY_FLUX.
! Note approximation from cartesian face velocities which have been filled in MESH_EXCHANGE before CC_END_STEP.
CUTFACE_LOOP : DO LCF=MESHES(NM)%CF_GSV_G,SIZE(MESHES(NM)%CF_GSV)
   ICF=MESHES(NM)%CF_GSV(LCF); CF => CUT_FACE(ICF)
   I = CF%IJK(IAXIS); J = CF%IJK(JAXIS); K = CF%IJK(KAXIS)
   SELECT CASE(CF%IJK(KAXIS+1))
   CASE(IAXIS); VEL_CART = UU(I,J,K)
   CASE(JAXIS); VEL_CART = VV(I,J,K)
   CASE(KAXIS); VEL_CART = WW(I,J,K)
   END SELECT
   IF (PRE_GHOST) THEN ! VEL_CART already cut-face velocity from neighbor (VELOCITY_BC OMESH rescale).
      CF%VEL_CF  = VEL_CART; CF%VEL_CRT = VEL_CART*CF%ALPHA_CF
   ELSE
      CF%VEL_CRT= VEL_CART; CF%VEL_CF = VEL_CART/CF%ALPHA_CF
   ENDIF
   ! Assign same VEL_CF to all cut-face segments (VELS predictor / VEL corrector).
   DO JCF=1,CF%NFACE
      IF_=CF%FC(JCF)
      IF (APPLY_TO_ESTIMATED_VARIABLES) THEN
         MESHES(NM)%FV%FACE%VELS(IF_)=CF%VEL_CF
      ELSE
         MESHES(NM)%FV%FACE%VEL(IF_)=CF%VEL_CF
      ENDIF
   ENDDO
ENDDO CUTFACE_LOOP

! Dump cut-face velocities in UU, VV, WW arrays in case of unstructured projection:
CALL CUTFACE_VELOCITIES(NM,UU,VV,WW,CUTFACES=.TRUE.)

! Compute initial DUIDXJ, MUDUIDXJ in RCEDGES:
IS_RCEDGE = .TRUE.
RCEDGE_LOOP_1 : DO IEDGE=1,MESHES(NM)%CC_NRCEDGE
   CC_EDGE => CC_RCEDGE(IEDGE)
   CALL CC_RCEDGE_DUIDXJ
ENDDO RCEDGE_LOOP_1

! Compute DUIDXJ in gas cut-edges:
CUTEDGE_LOOP_1 : DO IEDGE=1,MESHES(NM)%N_CUTEDGE_MESH
   CE => CUT_EDGE(IEDGE)
   CALL CC_CUTEDGE_DUIDXJ_TAU_OMG
ENDDO CUTEDGE_LOOP_1

! Wall Model to compute DUIDXJ, MUDUIDXJ in boundary B, extrapolate from External point and B to IBEDGE and compute TAU, OMG.
IF (DO_IBEDGES) THEN
   IS_RCEDGE = .FALSE.
   IBEDGE_LOOP_1 : DO IEDGE=1,MESHES(NM)%CC_NIBEDGE
      CC_EDGE => CC_IBEDGE(IEDGE)
      CALL CC_EDGE_TAU_OMG
   ENDDO IBEDGE_LOOP_1
ENDIF

! Recompute DUIDXJ, MUDUIDXJ in RCEDGES if needed:
IS_RCEDGE = .TRUE.
RCEDGE_LOOP_2 : DO IEDGE=1,MESHES(NM)%CC_NRCEDGE
   CC_EDGE => CC_RCEDGE(IEDGE)
   CALL CC_RCEDGE_TAU_OMG
ENDDO RCEDGE_LOOP_2

! Retrieve cartesian velocities in UU, VV, WW arrays in case of unstructured projection:
CALL CUTFACE_VELOCITIES(NM,UU,VV,WW,CUTFACES=.FALSE.)

DEALLOCATE(UVW_EP,DUVW_EP)

T_USED(14) = T_USED(14) + CURRENT_TIME() - TNOW

RETURN

CONTAINS

SUBROUTINE CC_CUTEDGE_DUIDXJ_TAU_OMG

INTEGER :: IOE,X1AXIS,X2AXIS,X3AXIS,X1BAR,X2BAR,X3BAR,ICF,JCF,JEDGE
REAL(EB):: VEL_GAS(-2:2),MU_RC
INTEGER, PARAMETER :: ICDOV(1:2) = (/2,1/)

! Drop non gasphase or ghost-cell cut-edges.
IF (CE%STATUS/=CC_GASPHASE .OR. TWO_D .OR. CE%IE==0) RETURN
X1AXIS=CE%IJK(KAXIS+1)
SELECT CASE(X1AXIS)
CASE(IAXIS); X1BAR=IBAR; X2AXIS=JAXIS; X2BAR=JBAR; X3AXIS=KAXIS; X3BAR=KBAR
CASE(JAXIS); X1BAR=JBAR; X2AXIS=KAXIS; X2BAR=KBAR; X3AXIS=IAXIS; X3BAR=IBAR
CASE(KAXIS); X1BAR=KBAR; X2AXIS=IAXIS; X2BAR=IBAR; X3AXIS=JAXIS; X3BAR=JBAR
END SELECT
IF(CE%IJK(X1AXIS)<1 .OR. CE%IJK(X1AXIS)>X1BAR) RETURN
IF(CE%IJK(X2AXIS)<0 .OR. CE%IJK(X2AXIS)>X2BAR) RETURN
IF(CE%IJK(X3AXIS)<0 .OR. CE%IJK(X3AXIS)>X3BAR) RETURN

IE     = CE%IE
II     = EDGE(IE)%I
JJ     = EDGE(IE)%J
KK     = EDGE(IE)%K
IEC    = EDGE(IE)%AXIS

! We Keep viscosity outside of JEDGE loop for the moment.
SELECT CASE(IEC)
   CASE(IAXIS); MU_RC = 0.25_EB*(MU(II,JJ,KK)+MU(II,JJ+1,KK)+MU(II,JJ+1,KK+1)+MU(II,JJ,KK+1))
   CASE(JAXIS); MU_RC = 0.25_EB*(MU(II,JJ,KK)+MU(II+1,JJ,KK)+MU(II+1,JJ,KK+1)+MU(II,JJ,KK+1))
   CASE(KAXIS); MU_RC = 0.25_EB*(MU(II,JJ,KK)+MU(II+1,JJ,KK)+MU(II+1,JJ+1,KK)+MU(II,JJ+1,KK))
END SELECT

DO JEDGE=1,CE%NEDGE
   VEL_GAS(-2:2) = 0._EB
   ORIENTATION_LOOP: DO IS=1,3
      IF (IS==IEC) CYCLE ORIENTATION_LOOP
      SIGN_LOOP: DO I_SGN=-1,1,2
         ! Determine Index_Coordinate_Direction
         ! IEC=1, ICD=1 refers to DWDY; ICD=2 refers to DVDZ
         ! IEC=2, ICD=1 refers to DUDZ; ICD=2 refers to DWDX
         ! IEC=3, ICD=1 refers to DVDX; ICD=2 refers to DUDY
         IF (IS>IEC) ICD = IS-IEC
         IF (IS<IEC) ICD = IS-IEC+3
         ICD_SGN = I_SGN * ICD

         ICF = CE%FACE_LIST(1,ICD_SGN,JEDGE) ! Only one gas cut-edge per cartesian edge.
         JCF = CE%FACE_LIST(2,ICD_SGN,JEDGE)
         IF(ICF>0) VEL_GAS(ICD_SGN) = PRFCT*CC_FV_CUTFACE_MOM(NM,ICF,JCF,CC_FV_MOM_VELS) + &
                                      (1._EB-PRFCT)*CC_FV_CUTFACE_MOM(NM,ICF,JCF,CC_FV_MOM_VEL)
      ENDDO SIGN_LOOP
   ENDDO ORIENTATION_LOOP

   ! IEC = IAXIS : DWDY (IOE=1), DVDZ (IOE=2):
   ! IEC = JAXIS : DUDZ (IOE=1), DWDX (IOE=2):
   ! IEC = KAXIS : DUDY (IOE=1), DVDX (IOE=2):
   DO IOE = 1,2
      CE%DUIDXJ((/-IOE,IOE/),JEDGE)    = (VEL_GAS(IOE)-VEL_GAS(-IOE))/CE%DXX(IOE,JEDGE)
      CE%MU_DUIDXJ((/-IOE,IOE/),JEDGE) = MU_RC*CE%DUIDXJ((/-IOE,IOE/),JEDGE)
   ENDDO
ENDDO

! For TAU OMGGA on the whole cartesian edge use value of JEDGE=1. Note this would be changed when each cut-edge
! contributes to corresponfing cut-faces forces (completely unstructured momentum).
JEDGE=1
SIGN_LOOP_2: DO I_SGN=-1,1,2
   ORIENTATION_LOOP_2: DO ICD=1,2
      ICDO = ICDOV(ICD)
      ICD_SGN = I_SGN*ICD
         DUIDXJ_USE(ICD) =     CE%DUIDXJ(ICD_SGN,JEDGE)
      MU_DUIDXJ_USE(ICD) =  CE%MU_DUIDXJ(ICD_SGN,JEDGE)
      ICDO_SGN = I_SGN*ICDO
         DUIDXJ_USE(ICDO)=    CE%DUIDXJ(ICDO_SGN,JEDGE)
      MU_DUIDXJ_USE(ICDO)= CE%MU_DUIDXJ(ICDO_SGN,JEDGE)
      EDGE(IE)%OMEGA(ICD_SGN) = DUIDXJ_USE(1) -    DUIDXJ_USE(2)
      EDGE(IE)%TAU(ICD_SGN)   = MU_DUIDXJ_USE(1) + MU_DUIDXJ_USE(2)
   ENDDO ORIENTATION_LOOP_2
ENDDO SIGN_LOOP_2

END SUBROUTINE CC_CUTEDGE_DUIDXJ_TAU_OMG


SUBROUTINE CC_RCEDGE_DUIDXJ

INTEGER :: IOE
REAL(EB):: VEL_GAS(-2:2),XB_IB(-2:2),MU_RC,DEL_RC

IE  = CC_EDGE%IE
II  = EDGE(IE)%I
JJ  = EDGE(IE)%J
KK  = EDGE(IE)%K
IEC = EDGE(IE)%AXIS

VEL_GAS(-2:2) = 0._EB; XB_IB(-2:2) = 0._EB
ORIENTATION_LOOP: DO IS=1,3
   IF (IS==IEC) CYCLE ORIENTATION_LOOP
   SIGN_LOOP: DO I_SGN=-1,1,2

      ! Determine Index_Coordinate_Direction
      ! IEC=1, ICD=1 refers to DWDY; ICD=2 refers to DVDZ
      ! IEC=2, ICD=1 refers to DUDZ; ICD=2 refers to DWDX
      ! IEC=3, ICD=1 refers to DVDX; ICD=2 refers to DUDY

      IF (IS>IEC) ICD = IS-IEC
      IF (IS<IEC) ICD = IS-IEC+3
      ICD_SGN = I_SGN * ICD

      ! With ICD_SGN check if face:
      ! IBEDGE IEC=IAXIS => ICD_SGN=-2 => FACE  low Z normal to JAXIS.
      !                     ICD_SGN=-1 => FACE  low Y normal to KAXIS.
      !                     ICD_SGN= 1 => FACE high Y normal to KAXIS.
      !                     ICD_SGN= 2 => FACE high Z normal to JAXIS.
      ! IBEDGE IEC=JAXIS => ICD_SGN=-2 => FACE  low X normal to KAXIS.
      !                     ICD_SGN=-1 => FACE  low Z normal to IAXIS.
      !                     ICD_SGN= 1 => FACE high Z normal to IAXIS.
      !                     ICD_SGN= 2 => FACE high X normal to KAXIS.
      ! IBEDGE IEC=KAXIS => ICD_SGN=-2 => FACE  low Y normal to IAXIS.
      !                     ICD_SGN=-1 => FACE  low X normal to JAXIS.
      !                     ICD_SGN= 1 => FACE high X normal to JAXIS.
      !                     ICD_SGN= 2 => FACE high Y normal to IAXIS.
      ! is GASPHASE cut-face.
      XB_IB(ICD_SGN) = CC_EDGE%XB_IB(ICD_SGN)
      IEC_SELECT: SELECT CASE(IEC)
         CASE(IAXIS)
            ! Define Face indexes and normal axis FAXIS.
            SELECT CASE(ICD_SGN)
               CASE(-2); IIF=II  ; JJF=JJ  ; KKF=KK  ; FAXIS=JAXIS
               CASE(-1); IIF=II  ; JJF=JJ  ; KKF=KK  ; FAXIS=KAXIS
               CASE( 1); IIF=II  ; JJF=JJ+1; KKF=KK  ; FAXIS=KAXIS
               CASE( 2); IIF=II  ; JJF=JJ  ; KKF=KK+1; FAXIS=JAXIS
            END SELECT
            !DXX(1)  = DY(JJF); DXX(2)  = DZ(KKF)
            IF (FAXIS==JAXIS) THEN
                VEL_GAS(ICD_SGN)   = VV(IIF,JJF,KKF)
            ELSE ! IF(FAXIS==KAXIS) THEN
                VEL_GAS(ICD_SGN)   = WW(IIF,JJF,KKF)
            ENDIF

         CASE(JAXIS)
            ! Define Face indexes and normal axis FAXIS.
            SELECT CASE(ICD_SGN)
               CASE(-2); IIF=II  ; JJF=JJ  ; KKF=KK  ; FAXIS=KAXIS
               CASE(-1); IIF=II  ; JJF=JJ  ; KKF=KK  ; FAXIS=IAXIS
               CASE( 1); IIF=II  ; JJF=JJ  ; KKF=KK+1; FAXIS=IAXIS
               CASE( 2); IIF=II+1; JJF=JJ  ; KKF=KK  ; FAXIS=KAXIS
            END SELECT
            !DXX(1)  = DZ(KKF); DXX(2)  = DX(IIF)
            IF (FAXIS==KAXIS) THEN
               VEL_GAS(ICD_SGN)   = WW(IIF,JJF,KKF)
            ELSE ! IF(FAXIS==IAXIS) THEN
               VEL_GAS(ICD_SGN)   = UU(IIF,JJF,KKF)
            ENDIF

         CASE(KAXIS)
            ! Define Face indexes and normal axis FAXIS.
            SELECT CASE(ICD_SGN)
               CASE(-2); IIF=II  ; JJF=JJ  ; KKF=KK  ; FAXIS=IAXIS
               CASE(-1); IIF=II  ; JJF=JJ  ; KKF=KK  ; FAXIS=JAXIS
               CASE( 1); IIF=II+1; JJF=JJ  ; KKF=KK  ; FAXIS=JAXIS
               CASE( 2); IIF=II  ; JJF=JJ+1; KKF=KK  ; FAXIS=IAXIS
            END SELECT
            !DXX(1)  = DX(IIF); DXX(2)  = DY(JJF)
            IF (FAXIS==IAXIS) THEN
               VEL_GAS(ICD_SGN)   = UU(IIF,JJF,KKF)
            ELSE ! IF(FAXIS==JAXIS) THEN
               VEL_GAS(ICD_SGN)   = VV(IIF,JJF,KKF)
            ENDIF

      END SELECT IEC_SELECT

      ! Divide distance to boundary (cut-face) or DXX (reg face) by 2 to get collocation point position:
      XB_IB(ICD_SGN) = XB_IB(ICD_SGN)/2._EB

   ENDDO SIGN_LOOP
ENDDO ORIENTATION_LOOP

SELECT CASE(IEC)
   CASE(IAXIS); MU_RC = 0.25_EB*(MU(II,JJ,KK)+MU(II,JJ+1,KK)+MU(II,JJ+1,KK+1)+MU(II,JJ,KK+1))
   CASE(JAXIS); MU_RC = 0.25_EB*(MU(II,JJ,KK)+MU(II+1,JJ,KK)+MU(II+1,JJ,KK+1)+MU(II,JJ,KK+1))
   CASE(KAXIS); MU_RC = 0.25_EB*(MU(II,JJ,KK)+MU(II+1,JJ,KK)+MU(II+1,JJ+1,KK)+MU(II,JJ+1,KK))
END SELECT

! IEC = IAXIS : DWDY (IOE=1), DVDZ (IOE=2):
! IEC = JAXIS : DUDZ (IOE=1), DWDX (IOE=2):
! IEC = KAXIS : DUDY (IOE=1), DVDX (IOE=2):
DO IOE = 1,2
   DEL_RC= XB_IB(-IOE)+XB_IB(IOE) ! Sum of 1/2*DY (IOE=1) or, 1/2*DZ (IOE=2), when IEC=IAXIS, etc.
   CC_EDGE%DUIDXJ((/-IOE,IOE/))    = (VEL_GAS(IOE)-VEL_GAS(-IOE))/DEL_RC
   CC_EDGE%MU_DUIDXJ((/-IOE,IOE/)) = MU_RC*CC_EDGE%DUIDXJ((/-IOE,IOE/))
ENDDO

RETURN
END SUBROUTINE CC_RCEDGE_DUIDXJ

SUBROUTINE CC_RCEDGE_TAU_OMG

IE = CC_EDGE%IE
SIGN_LOOP_2: DO I_SGN=-1,1,2
   ORIENTATION_LOOP_2: DO ICD=1,2
      IF (ICD==1) THEN
         ICDO=2
      ELSE ! ICD=2
         ICDO=1
      ENDIF
      ICD_SGN = I_SGN*ICD
         DUIDXJ_USE(ICD) =   CC_EDGE%DUIDXJ(ICD_SGN)
      MU_DUIDXJ_USE(ICD) = CC_EDGE%MU_DUIDXJ(ICD_SGN)
      ICDO_SGN = I_SGN*ICDO
         DUIDXJ_USE(ICDO)=   CC_EDGE%DUIDXJ(ICDO_SGN)
      MU_DUIDXJ_USE(ICDO)= CC_EDGE%MU_DUIDXJ(ICDO_SGN)
      EDGE(IE)%OMEGA(ICD_SGN) = DUIDXJ_USE(1) -    DUIDXJ_USE(2)
      EDGE(IE)%TAU(ICD_SGN)   = MU_DUIDXJ_USE(1) + MU_DUIDXJ_USE(2)

   ENDDO ORIENTATION_LOOP_2
ENDDO SIGN_LOOP_2

END SUBROUTINE CC_RCEDGE_TAU_OMG

SUBROUTINE CC_EDGE_TAU_OMG

REAL(EB) :: VEL_T,VEL_GHOST,MUA,UUP(2),UUM(2),DRAG_FACTOR,HT_SCALE_FACTOR,VEG_HT
INTEGER  :: IEP,JEP,KEP,SURF_INDEX,ITMP,SKIP_FCT,NPE_LIST_START,NPE_LIST_COUNT,IRCEDG,IRC,JRC,KRC,&
            N_SOLID_CELLS_ON_EDGE,IOR,IVL,IIGM,IIGP,JJGM,JJGP,KKGM,KKGP,ICMM,ICMP,ICPM,ICPP
LOGICAL :: ALTERED_GRADIENT(-2:2),CORNER_EDGE
REAL(EB):: XB_IB,OMEV_EP(-2:2),TAUV_EP(-2:2),DWDY,DVDZ,DUDZ,DWDX,DUDY,DVDX, &
           DUIDXJ_EP(-2:2),MU_DUIDXJ_EP(-2:2),EC_B(-2:2),EC_EP(-2:2),DEL_EP,VEL_GAS,CEP,CB,U1_T,U2_T
TYPE(SURFACE_TYPE), POINTER :: SF
REAL(EB) :: VLG(-2:2),NUV(-2:2),RGH(-2:2),UTA(-2:2)
VLG(-2:2)=0._EB; NUV(-2:2)=0._EB; RGH(-2:2)=0._EB; UTA(-2:2)=0._EB

! Set these to zero for now:
VEL_T = 0._EB; SRGH = 0._EB

IE   = CC_EDGE%IE
II   = EDGE(IE)%I
JJ   = EDGE(IE)%J
KK   = EDGE(IE)%K
IEC  = EDGE(IE)%AXIS
ICMM = EDGE(IE)%CELL_INDEX_MM
ICPM = EDGE(IE)%CELL_INDEX_PM
ICMP = EDGE(IE)%CELL_INDEX_MP
ICPP = EDGE(IE)%CELL_INDEX_PP

! Get the velocity components at the appropriate cell faces

COMPONENT: SELECT CASE(IEC)
   CASE(1) COMPONENT
      UUP(1)  = VV(II,JJ,KK+1)
      UUM(1)  = VV(II,JJ,KK)
      UUP(2)  = WW(II,JJ+1,KK)
      UUM(2)  = WW(II,JJ,KK)
      DXX(1)  = DY(JJ)
      DXX(2)  = DZ(KK)
   CASE(2) COMPONENT
      UUP(1)  = WW(II+1,JJ,KK)
      UUM(1)  = WW(II,JJ,KK)
      UUP(2)  = UU(II,JJ,KK+1)
      UUM(2)  = UU(II,JJ,KK)
      DXX(1)  = DZ(KK)
      DXX(2)  = DX(II)
   CASE(3) COMPONENT
      UUP(1)  = UU(II,JJ+1,KK)
      UUM(1)  = UU(II,JJ,KK)
      UUP(2)  = VV(II+1,JJ,KK)
      UUM(2)  = VV(II,JJ,KK)
      DXX(1)  = DX(II)
      DXX(2)  = DY(JJ)
END SELECT COMPONENT

! Loop over all possible orientations of edge and reassign velocity gradients if appropriate
EP=1
ALTERED_GRADIENT(-2:2) = .FALSE.
OMEV_EP(-2:2) = 0._EB; TAUV_EP(-2:2) = 0._EB; EC_B(-2:2) = 0._EB; EC_EP(-2:2) = 0._EB
DUIDXJ_EP(-2:2) = 0._EB; MU_DUIDXJ_EP(-2:2) = 0._EB; DUIDXJ(-2:2) = 0._EB; MU_DUIDXJ(-2:2) = 0._EB
ORIENTATION_LOOP: DO IS=1,3
   IF (IS==IEC) CYCLE ORIENTATION_LOOP
   SIGN_LOOP: DO I_SGN=-1,1,2

      ! IOR is the orientation of the wall cells adjacent to the edge

      IOR = I_SGN*IS

      ! Determine Index_Coordinate_Direction
      ! IEC=1, ICD=1 refers to DWDY; ICD=2 refers to DVDZ
      ! IEC=2, ICD=1 refers to DUDZ; ICD=2 refers to DWDX
      ! IEC=3, ICD=1 refers to DVDX; ICD=2 refers to DUDY

      IF (IS>IEC) ICD = IS-IEC
      IF (IS<IEC) ICD = IS-IEC+3
      ICD_SGN = I_SGN * ICD

      ! Define the appropriate gas and ghost velocity

      IF (ICD==1) THEN ! Used to pick the appropriate velocity component
         IVL=2
      ELSE !ICD==2
         IVL=1
      ENDIF

      IF (IOR<0) THEN
         VEL_GAS   = UUM(IVL)
         VEL_GHOST = UUP(IVL)
         IIGM = CELL(ICMM)%I
         JJGM = CELL(ICMM)%J
         KKGM = CELL(ICMM)%K
         IF (ICD==1) THEN
            IIGP = CELL(ICMP)%I
            JJGP = CELL(ICMP)%J
            KKGP = CELL(ICMP)%K
         ELSE ! ICD==2
            IIGP = CELL(ICPM)%I
            JJGP = CELL(ICPM)%J
            KKGP = CELL(ICPM)%K
         ENDIF
      ELSE
         VEL_GAS   = UUP(IVL)
         VEL_GHOST = UUM(IVL)
         IF (ICD==1) THEN
            IIGM = CELL(ICPM)%I
            JJGM = CELL(ICPM)%J
            KKGM = CELL(ICPM)%K
         ELSE ! ICD==2
            IIGM = CELL(ICMP)%I
            JJGM = CELL(ICMP)%J
            KKGM = CELL(ICMP)%K
         ENDIF
         IIGP = CELL(ICPP)%I
         JJGP = CELL(ICPP)%J
         KKGP = CELL(ICPP)%K
      ENDIF

      IF(.NOT.CC_EDGE%PROCESS_EDGE_ORIENTATION(ICD_SGN)) CYCLE SIGN_LOOP

      ! With ICD_SGN check if face:
      ! IBEDGE IEC=IAXIS => ICD_SGN=-2 => FACE  low Z normal to JAXIS.
      !                     ICD_SGN=-1 => FACE  low Y normal to KAXIS.
      !                     ICD_SGN= 1 => FACE high Y normal to KAXIS.
      !                     ICD_SGN= 2 => FACE high Z normal to JAXIS.
      ! IBEDGE IEC=JAXIS => ICD_SGN=-2 => FACE  low X normal to KAXIS.
      !                     ICD_SGN=-1 => FACE  low Z normal to IAXIS.
      !                     ICD_SGN= 1 => FACE high Z normal to IAXIS.
      !                     ICD_SGN= 2 => FACE high X normal to KAXIS.
      ! IBEDGE IEC=KAXIS => ICD_SGN=-2 => FACE  low Y normal to IAXIS.
      !                     ICD_SGN=-1 => FACE  low X normal to JAXIS.
      !                     ICD_SGN= 1 => FACE high X normal to JAXIS.
      !                     ICD_SGN= 2 => FACE high Y normal to IAXIS.
      ! is GASPHASE cut-face.
      XB_IB      = CC_EDGE%XB_IB(ICD_SGN) ! Coordinate centroid of IBEDGE resp to Boundary (note, either zero or negative).
      SURF_INDEX = CC_EDGE%SURF_INDEX(ICD_SGN)
      IEC_SELECT: SELECT CASE(IEC)
         CASE(IAXIS) IEC_SELECT
            ! Define Face indexes and normal axis FAXIS.
            SELECT CASE(ICD_SGN)
               CASE(-2); IIF=II  ; JJF=JJ  ; KKF=KK  ; FAXIS=JAXIS
               CASE(-1); IIF=II  ; JJF=JJ  ; KKF=KK  ; FAXIS=KAXIS
               CASE( 1); IIF=II  ; JJF=JJ+1; KKF=KK  ; FAXIS=KAXIS
               CASE( 2); IIF=II  ; JJF=JJ  ; KKF=KK+1; FAXIS=JAXIS
            END SELECT
            IF(FCVAR(IIF,JJF,KKF,CC_FGSC,FAXIS)/=CC_CUTCFE) CYCLE SIGN_LOOP
            DXX(1)  = DY(JJF); DXX(2)  = DZ(KKF)

            ! Compute TAUV_EP, OMEV_EP, MU_FC, DXN_STRM_UB, VEL_GAS:
            SKIP_FCT = 1
            IF (FAXIS==JAXIS) THEN
               ITMP = MIN(I_MAX_TEMP,NINT(0.5_EB*(TMP(IIF,JJF,KKF)+TMP(IIF,JJF+1,KKF))))
               MU_FACE = MU_RSQMW_Z(ITMP,1)/RSQ_MW_Z(1)
               RHO_FACE = 0.5_EB*(  RHOP(IIF,JJF,KKF)+  RHOP(IIF,JJF+1,KKF))
               MUA = 0.5_EB*(MU(IIF,JJF,KKF) + MU(IIF,JJF+1,KKF))

               DXN_STRM_UB = DXX(2)
               ! Linear :
               DF     = DXX(2) - ABS(XB_IB)
               DE     = DXN_STRM_UB
               UF     = VV(IIF,JJF,KKF);  UE     = UF
               IF (.NOT.( (KKF+I_SGN>KBP1) .OR. (KKF+I_SGN<0) )) THEN
                  DE     = DZ(KKF+I_SGN) ! Should be one up from DXX(2).
                  UE     = VV(IIF,JJF,KKF+I_SGN)
               ENDIF
               UB     = VEL_T
               VEL_GAS  = 2._EB/(DF+DE)*((DE/2._EB+DF)*UF-DF/2._EB*UE) - 2._EB/(DF+DE)*(UF-UE)*(DXN_STRM_UB/2._EB)

               DEL_EP = DXX(2) - ABS(XB_IB)
               IF( DEL_EP < THRES_FCT_EP*DXX(2) ) THEN; SKIP_FCT = 2; DEL_EP = DEL_EP + DXX(2); ENDIF
               IEP=II; JEP=JJ; KEP=KK+SKIP_FCT*I_SGN

            ELSE ! IF(FAXIS==KAXIS) THEN
               ITMP = MIN(I_MAX_TEMP,NINT(0.5_EB*(TMP(IIF,JJF,KKF)+TMP(IIF,JJF,KKF+1))))
               MU_FACE = MU_RSQMW_Z(ITMP,1)/RSQ_MW_Z(1)
               RHO_FACE = 0.5_EB*(  RHOP(IIF,JJF,KKF)+  RHOP(IIF,JJF,KKF+1))
               MUA = 0.5_EB*(MU(IIF,JJF,KKF) + MU(IIF,JJF,KKF+1))

               DXN_STRM_UB = DXX(1)
               ! Linear :
               DF     = DXX(1) - ABS(XB_IB)
               DE     = DXN_STRM_UB
               UF     = WW(IIF,JJF,KKF);  UE     = UF
               IF (.NOT.( (JJF+I_SGN>JBP1) .OR. (JJF+I_SGN<0) )) THEN
                  DE     = DY(JJF+I_SGN) ! Should be one up from DXX(1).
                  UE     = WW(IIF,JJF+I_SGN,KKF)
               ENDIF
               UB     = VEL_T
               VEL_GAS  = 2._EB/(DF+DE)*((DE/2._EB+DF)*UF-DF/2._EB*UE) - 2._EB/(DF+DE)*(UF-UE)*(DXN_STRM_UB/2._EB)

               DEL_EP = DXX(1) - ABS(XB_IB)
               IF( DEL_EP < THRES_FCT_EP*DXX(1) ) THEN; SKIP_FCT = 2; DEL_EP = DEL_EP + DXX(1); ENDIF
               IEP=II; JEP=JJ+SKIP_FCT*I_SGN; KEP=KK

            ENDIF

            IF (CC_EDGE%EDGE_IN_MESH(ICD_SGN)) THEN ! Regular computation of MU and velocity derivatives:
               MU_EP= 0.25_EB*(MU(IEP,JEP,KEP)+MU(IEP,JEP+1,KEP)+MU(IEP,JEP+1,KEP+1)+MU(IEP,JEP,KEP+1))
               IRCEDG = ECVAR(IEP,JEP,KEP,CC_IDCE,IEC)
               IF (IRCEDG>0) THEN
                  IF(ECVAR(IEP,JEP,KEP,CC_EGSC,IEC)==CC_GASPHASE) THEN
                     DWDY = CC_RCEDGE(IRCEDG)%DUIDXJ(1); DVDZ = CC_RCEDGE(IRCEDG)%DUIDXJ(2)
                  ELSEIF(ECVAR(IEP,JEP,KEP,CC_EGSC,IEC)==CC_CUTCFE) THEN
                     IF (CUT_EDGE(IRCEDG)%IE>0) THEN
                        DWDY = CUT_EDGE(IRCEDG)%DUIDXJ(1,1); DVDZ = CUT_EDGE(IRCEDG)%DUIDXJ(2,1)
                     ELSE
                        DWDY = (WW(IEP,JEP+1,KEP)-WW(IEP,JEP,KEP))/DXX(1)
                        DVDZ = (VV(IEP,JEP,KEP+1)-VV(IEP,JEP,KEP))/DXX(2)
                     ENDIF
                  ENDIF
               ELSE
                  DWDY = (WW(IEP,JEP+1,KEP)-WW(IEP,JEP,KEP))/DXX(1); DVDZ = (VV(IEP,JEP,KEP+1)-VV(IEP,JEP,KEP))/DXX(2)
               ENDIF
            ELSE
               MU_EP = 0._EB; DWDY = 0._EB; DVDZ = 0._EB
               ! First MU_EP:
               VIND=0
               NPE_LIST_START = CC_EDGE%INT_NPE(LOW_IND,VIND,EP,ICD_SGN)
               NPE_LIST_COUNT = CC_EDGE%INT_NPE(HIGH_IND,VIND,EP,ICD_SGN)
               IF (NPE_LIST_COUNT>0) THEN
                 DO INPE=NPE_LIST_START+1,NPE_LIST_START+NPE_LIST_COUNT
                    MU_EP = MU_EP + CC_EDGE%INT_CVARS(INT_MU_IND,INPE)
                 ENDDO
                 MU_EP = MU_EP / REAL(NPE_LIST_COUNT,EB)
               ENDIF
               ! Then DWDY:
               VIND=KAXIS
               NPE_LIST_START = CC_EDGE%INT_NPE(LOW_IND,VIND,EP,ICD_SGN)
               NPE_LIST_COUNT = CC_EDGE%INT_NPE(HIGH_IND,VIND,EP,ICD_SGN)
               DO INPE=NPE_LIST_START+1,NPE_LIST_START+NPE_LIST_COUNT
                  DWDY = DWDY + CC_EDGE%INT_DCOEF(INPE,1)*CC_EDGE%INT_FVARS(INT_VEL_IND,INPE)
               ENDDO
               ! Finally DVDZ:
               VIND=JAXIS
               NPE_LIST_START = CC_EDGE%INT_NPE(LOW_IND,VIND,EP,ICD_SGN)
               NPE_LIST_COUNT = CC_EDGE%INT_NPE(HIGH_IND,VIND,EP,ICD_SGN)
               DO INPE=NPE_LIST_START+1,NPE_LIST_START+NPE_LIST_COUNT
                  DVDZ = DVDZ + CC_EDGE%INT_DCOEF(INPE,1)*CC_EDGE%INT_FVARS(INT_VEL_IND,INPE)
               ENDDO
            ENDIF

            OMEV_EP(ICD_SGN) = DWDY - DVDZ
            TAUV_EP(ICD_SGN) = MU_EP*(DWDY + DVDZ)
            IF (FAXIS==JAXIS) THEN
               DUIDXJ_EP(ICD_SGN)    = DVDZ
            ELSE ! IF(FAXIS==KAXIS) THEN
               DUIDXJ_EP(ICD_SGN)    = DWDY
            ENDIF

         CASE(JAXIS) IEC_SELECT
            ! Define Face indexes and normal axis FAXIS.
            SELECT CASE(ICD_SGN)
               CASE(-2); IIF=II  ; JJF=JJ  ; KKF=KK  ; FAXIS=KAXIS
               CASE(-1); IIF=II  ; JJF=JJ  ; KKF=KK  ; FAXIS=IAXIS
               CASE( 1); IIF=II  ; JJF=JJ  ; KKF=KK+1; FAXIS=IAXIS
               CASE( 2); IIF=II+1; JJF=JJ  ; KKF=KK  ; FAXIS=KAXIS
            END SELECT
            IF(FCVAR(IIF,JJF,KKF,CC_FGSC,FAXIS)/=CC_CUTCFE) CYCLE SIGN_LOOP
            DXX(1)  = DZ(KKF); DXX(2)  = DX(IIF)

            ! Compute TAUV_EP, OMEV_EP, MU_FC, DXN_STRM_UB, VEL_GAS:
            SKIP_FCT = 1
            IF (FAXIS==KAXIS) THEN
               ITMP = MIN(I_MAX_TEMP,NINT(0.5_EB*(TMP(IIF,JJF,KKF)+TMP(IIF,JJF,KKF+1))))
               MU_FACE = MU_RSQMW_Z(ITMP,1)/RSQ_MW_Z(1)
               RHO_FACE = 0.5_EB*(  RHOP(IIF,JJF,KKF)+  RHOP(IIF,JJF,KKF+1))
               MUA = 0.5_EB*(MU(IIF,JJF,KKF) +  MU(IIF,JJF,KKF+1))

               DXN_STRM_UB = DXX(2)
               ! Linear :
               DF     = DXX(2) - ABS(XB_IB)
               DE     = DXN_STRM_UB
               UF     = WW(IIF,JJF,KKF);  UE     = UF
               IF (.NOT.( (IIF+I_SGN>IBP1) .OR. (IIF+I_SGN<0) )) THEN
                  DE     = DX(IIF+I_SGN) ! Should be one up from DXX(2).
                  UE     = WW(IIF+I_SGN,JJF,KKF)
               ENDIF
               UB     = VEL_T
               VEL_GAS  = 2._EB/(DF+DE)*((DE/2._EB+DF)*UF-DF/2._EB*UE) - 2._EB/(DF+DE)*(UF-UE)*(DXN_STRM_UB/2._EB)

               DEL_EP = DXX(2) - ABS(XB_IB)
               IF( DEL_EP < THRES_FCT_EP*DXX(2) ) THEN; SKIP_FCT = 2; DEL_EP = DEL_EP + DXX(2); ENDIF
               IEP=II+SKIP_FCT*I_SGN; JEP=JJ; KEP=KK

            ELSE ! IF(FAXIS==IAXIS) THEN
               ITMP = MIN(I_MAX_TEMP,NINT(0.5_EB*(TMP(IIF,JJF,KKF)+TMP(IIF+1,JJF,KKF))))
               MU_FACE = MU_RSQMW_Z(ITMP,1)/RSQ_MW_Z(1)
               RHO_FACE = 0.5_EB*(  RHOP(IIF,JJF,KKF)+  RHOP(IIF+1,JJF,KKF))
               MUA = 0.5_EB*(MU(IIF,JJF,KKF) +  MU(IIF+1,JJF,KKF))

               DXN_STRM_UB = DXX(1)
               ! Linear :
               DF     = DXX(1) - ABS(XB_IB)
               DE     = DXN_STRM_UB
               UF     = UU(IIF,JJF,KKF);  UE     = UF
               IF (.NOT.( (KKF+I_SGN>KBP1) .OR. (KKF+I_SGN<0) )) THEN
                  DE     = DZ(KKF+I_SGN) ! Should be one up from DXX(1).
                  UE     = UU(IIF,JJF,KKF+I_SGN)
               ENDIF
               UB     = VEL_T
               VEL_GAS  = 2._EB/(DF+DE)*((DE/2._EB+DF)*UF-DF/2._EB*UE) - 2._EB/(DF+DE)*(UF-UE)*(DXN_STRM_UB/2._EB)

               DEL_EP = DXX(1) - ABS(XB_IB)
               IF( DEL_EP < THRES_FCT_EP*DXX(1) ) THEN; SKIP_FCT = 2; DEL_EP = DEL_EP + DXX(1); ENDIF
               IEP=II; JEP=JJ; KEP=KK+SKIP_FCT*I_SGN

            ENDIF

            IF (CC_EDGE%EDGE_IN_MESH(ICD_SGN)) THEN ! Regular computation of MU and velocity derivatives:
               MU_EP= 0.25_EB*(MU(IEP,JEP,KEP)+MU(IEP+1,JEP,KEP)+MU(IEP+1,JEP,KEP+1)+MU(IEP,JEP,KEP+1))
               IRCEDG = ECVAR(IEP,JEP,KEP,CC_IDCE,IEC)
               IF (IRCEDG>0) THEN
                  IF(ECVAR(IEP,JEP,KEP,CC_EGSC,IEC)==CC_GASPHASE) THEN
                     DUDZ = CC_RCEDGE(IRCEDG)%DUIDXJ(1); DWDX = CC_RCEDGE(IRCEDG)%DUIDXJ(2)
                  ELSEIF(ECVAR(IEP,JEP,KEP,CC_EGSC,IEC)==CC_CUTCFE) THEN
                     IF (CUT_EDGE(IRCEDG)%IE>0) THEN
                        DUDZ = CUT_EDGE(IRCEDG)%DUIDXJ(1,1); DWDX = CUT_EDGE(IRCEDG)%DUIDXJ(2,1)
                     ELSE
                        DUDZ = (UU(IEP,JEP,KEP+1)-UU(IEP,JEP,KEP))/DXX(1)
                        DWDX = (WW(IEP+1,JEP,KEP)-WW(IEP,JEP,KEP))/DXX(2)
                     ENDIF
                  ENDIF
               ELSE
                  DUDZ = (UU(IEP,JEP,KEP+1)-UU(IEP,JEP,KEP))/DXX(1); DWDX = (WW(IEP+1,JEP,KEP)-WW(IEP,JEP,KEP))/DXX(2)
               ENDIF
            ELSE
               MU_EP = 0._EB; DUDZ = 0._EB; DWDX = 0._EB
               ! First MU_EP:
               VIND=0
               NPE_LIST_START = CC_EDGE%INT_NPE(LOW_IND,VIND,EP,ICD_SGN)
               NPE_LIST_COUNT = CC_EDGE%INT_NPE(HIGH_IND,VIND,EP,ICD_SGN)
               IF (NPE_LIST_COUNT>0) THEN
                 DO INPE=NPE_LIST_START+1,NPE_LIST_START+NPE_LIST_COUNT
                    MU_EP = MU_EP + CC_EDGE%INT_CVARS(INT_MU_IND,INPE)
                 ENDDO
                 MU_EP = MU_EP / REAL(NPE_LIST_COUNT,EB)
               ENDIF
               ! Then DUDZ:
               VIND=IAXIS
               NPE_LIST_START = CC_EDGE%INT_NPE(LOW_IND,VIND,EP,ICD_SGN)
               NPE_LIST_COUNT = CC_EDGE%INT_NPE(HIGH_IND,VIND,EP,ICD_SGN)
               DO INPE=NPE_LIST_START+1,NPE_LIST_START+NPE_LIST_COUNT
                  DUDZ = DUDZ + CC_EDGE%INT_DCOEF(INPE,1)*CC_EDGE%INT_FVARS(INT_VEL_IND,INPE)
               ENDDO
               ! Finally DWDX:
               VIND=KAXIS
               NPE_LIST_START = CC_EDGE%INT_NPE(LOW_IND,VIND,EP,ICD_SGN)
               NPE_LIST_COUNT = CC_EDGE%INT_NPE(HIGH_IND,VIND,EP,ICD_SGN)
               DO INPE=NPE_LIST_START+1,NPE_LIST_START+NPE_LIST_COUNT
                  DWDX = DWDX + CC_EDGE%INT_DCOEF(INPE,1)*CC_EDGE%INT_FVARS(INT_VEL_IND,INPE)
               ENDDO
            ENDIF

            OMEV_EP(ICD_SGN) = DUDZ - DWDX
            TAUV_EP(ICD_SGN) = MU_EP*(DUDZ + DWDX)
            IF (FAXIS==KAXIS) THEN
               DUIDXJ_EP(ICD_SGN)    = DWDX
            ELSE ! IF(FAXIS==IAXIS) THEN
               DUIDXJ_EP(ICD_SGN)    = DUDZ
            ENDIF

            !  IF(NM==1 .AND. II==41 .AND. JJ==20 .AND. KK==32 .AND. FAXIS==IAXIS) THEN
            !    WRITE(LU_ERR,*) '>>>> ICD_SGN, FAXIS, VEL_GAS=',ICD_SGN,FAXIS,IEP,JEP,KEP
            !    WRITE(LU_ERR,*) '                          =',XB_IB,DXN_STRM_UB,ZETA,USTR_1,USTR_2,VEL_GAS
            !    WRITE(LU_ERR,*) 'DF,DE,UF,VV(IIF,JJF,KKF),UE,UB=',DF,DE,UF,UU(IIF,JJF,KKF),UE,UB
            !    WRITE(LU_ERR,*) 'ICD_SGN,DUIDXJ_EP(ICD_SGN)=',ICD_SGN,DUIDXJ_EP(ICD_SGN)
            !    WRITE(LU_ERR,*) 'DE,DEZ+1=',KKF,I_SGN,DZ(KKF),DZ(KKF+I_SGN)
            ! ENDIF

         CASE(KAXIS) IEC_SELECT
            ! Define Face indexes and normal axis FAXIS.
            SELECT CASE(ICD_SGN)
               CASE(-2); IIF=II  ; JJF=JJ  ; KKF=KK  ; FAXIS=IAXIS
               CASE(-1); IIF=II  ; JJF=JJ  ; KKF=KK  ; FAXIS=JAXIS
               CASE( 1); IIF=II+1; JJF=JJ  ; KKF=KK  ; FAXIS=JAXIS
               CASE( 2); IIF=II  ; JJF=JJ+1; KKF=KK  ; FAXIS=IAXIS
            END SELECT
            IF(FCVAR(IIF,JJF,KKF,CC_FGSC,FAXIS)/=CC_CUTCFE) CYCLE SIGN_LOOP
            DXX(1)  = DX(IIF); DXX(2)  = DY(JJF)

            ! Compute TAUV_EP, OMEV_EP, MU_FC, DXN_STRM_UB, VEL_GAS:
            SKIP_FCT = 1
            IF (FAXIS==IAXIS) THEN
               ITMP = MIN(I_MAX_TEMP,NINT(0.5_EB*(TMP(IIF,JJF,KKF)+TMP(IIF+1,JJF,KKF))))
               MU_FACE = MU_RSQMW_Z(ITMP,1)/RSQ_MW_Z(1)
               RHO_FACE = 0.5_EB*(  RHOP(IIF,JJF,KKF)+  RHOP(IIF+1,JJF,KKF))
               MUA = 0.5_EB*(MU(IIF,JJF,KKF) +  MU(IIF+1,JJF,KKF))

               DXN_STRM_UB = DXX(2)
               ! Linear :
               DF     = DXX(2) - ABS(XB_IB)
               DE     = DXN_STRM_UB
               UF     = UU(IIF,JJF,KKF);  UE     = UF
               IF (.NOT.( (JJF+I_SGN>JBP1) .OR. (JJF+I_SGN<0) )) THEN
                  DE     = DY(JJF+I_SGN) ! Should be one up from DXX(2).
                  UE     = UU(IIF,JJF+I_SGN,KKF)
               ENDIF
               UB     = VEL_T
               VEL_GAS  = 2._EB/(DF+DE)*((DE/2._EB+DF)*UF-DF/2._EB*UE) - 2._EB/(DF+DE)*(UF-UE)*(DXN_STRM_UB/2._EB)

               DEL_EP = DXX(2) - ABS(XB_IB)
               IF( DEL_EP < THRES_FCT_EP*DXX(2) ) THEN; SKIP_FCT = 2; DEL_EP = DEL_EP + DXX(2); ENDIF
               IEP=II; JEP=JJ+SKIP_FCT*I_SGN; KEP=KK

            ELSE ! IF(FAXIS==JAXIS) THEN
               ITMP = MIN(I_MAX_TEMP,NINT(0.5_EB*(TMP(IIF,JJF,KKF)+TMP(IIF,JJF+1,KKF))))
               MU_FACE = MU_RSQMW_Z(ITMP,1)/RSQ_MW_Z(1)
               RHO_FACE = 0.5_EB*(  RHOP(IIF,JJF,KKF)+  RHOP(IIF,JJF+1,KKF))
               MUA = 0.5_EB*(MU(IIF,JJF,KKF) +  MU(IIF,JJF+1,KKF))

               DXN_STRM_UB = DXX(1)
               ! Linear :
               DF     = DXX(1) - ABS(XB_IB)
               DE     = DXN_STRM_UB
               UF     = VV(IIF,JJF,KKF);  UE     = UF
               IF (.NOT.( (IIF+I_SGN>IBP1) .OR. (IIF+I_SGN<0) )) THEN
                  DE     = DX(IIF+I_SGN) ! Should be one up from DXX(1).
                  UE     = VV(IIF+I_SGN,JJF,KKF)
               ENDIF
               UB     = VEL_T
               VEL_GAS  = 2._EB/(DF+DE)*((DE/2._EB+DF)*UF-DF/2._EB*UE) - 2._EB/(DF+DE)*(UF-UE)*(DXN_STRM_UB/2._EB)

               DEL_EP = DXX(1) - ABS(XB_IB)
               IF( DEL_EP < THRES_FCT_EP*DXX(1) ) THEN; SKIP_FCT = 2; DEL_EP = DEL_EP + DXX(1); ENDIF
               IEP=II+SKIP_FCT*I_SGN; JEP=JJ; KEP=KK

            ENDIF

            IF (CC_EDGE%EDGE_IN_MESH(ICD_SGN)) THEN ! Regular computation of MU and velocity derivatives:
               MU_EP= 0.25_EB*(MU(IEP,JEP,KEP)+MU(IEP+1,JEP,KEP)+MU(IEP+1,JEP+1,KEP)+MU(IEP,JEP+1,KEP))
               IRCEDG = ECVAR(IEP,JEP,KEP,CC_IDCE,IEC)
               IF (IRCEDG>0) THEN
                  IF(ECVAR(IEP,JEP,KEP,CC_EGSC,IEC)==CC_GASPHASE) THEN
                     DVDX = CC_RCEDGE(IRCEDG)%DUIDXJ(1); DUDY = CC_RCEDGE(IRCEDG)%DUIDXJ(2)
                  ELSEIF(ECVAR(IEP,JEP,KEP,CC_EGSC,IEC)==CC_CUTCFE) THEN
                     IF (CUT_EDGE(IRCEDG)%IE>0) THEN
                        DVDX = CUT_EDGE(IRCEDG)%DUIDXJ(1,1); DUDY = CUT_EDGE(IRCEDG)%DUIDXJ(2,1)
                     ELSE
                        DVDX = (VV(IEP+1,JEP,KEP)-VV(IEP,JEP,KEP))/DXX(1)
                        DUDY = (UU(IEP,JEP+1,KEP)-UU(IEP,JEP,KEP))/DXX(2)
                     ENDIF
                  ENDIF
               ELSE
                  DVDX = (VV(IEP+1,JEP,KEP)-VV(IEP,JEP,KEP))/DXX(1); DUDY = (UU(IEP,JEP+1,KEP)-UU(IEP,JEP,KEP))/DXX(2)
               ENDIF
            ELSE
               MU_EP = 0._EB; DVDX = 0._EB; DUDY = 0._EB
               ! First MU_EP:
               VIND=0
               NPE_LIST_START = CC_EDGE%INT_NPE(LOW_IND,VIND,EP,ICD_SGN)
               NPE_LIST_COUNT = CC_EDGE%INT_NPE(HIGH_IND,VIND,EP,ICD_SGN)
               IF (NPE_LIST_COUNT>0) THEN
                 DO INPE=NPE_LIST_START+1,NPE_LIST_START+NPE_LIST_COUNT
                    MU_EP = MU_EP + CC_EDGE%INT_CVARS(INT_MU_IND,INPE)
                 ENDDO
                 MU_EP = MU_EP / REAL(NPE_LIST_COUNT,EB)
               ENDIF
               ! Then DVDX:
               VIND=JAXIS
               NPE_LIST_START = CC_EDGE%INT_NPE(LOW_IND,VIND,EP,ICD_SGN)
               NPE_LIST_COUNT = CC_EDGE%INT_NPE(HIGH_IND,VIND,EP,ICD_SGN)
               DO INPE=NPE_LIST_START+1,NPE_LIST_START+NPE_LIST_COUNT
                  DVDX = DVDX + CC_EDGE%INT_DCOEF(INPE,1)*CC_EDGE%INT_FVARS(INT_VEL_IND,INPE)
               ENDDO
               ! Finally DUDY:
               VIND=IAXIS
               NPE_LIST_START = CC_EDGE%INT_NPE(LOW_IND,VIND,EP,ICD_SGN)
               NPE_LIST_COUNT = CC_EDGE%INT_NPE(HIGH_IND,VIND,EP,ICD_SGN)
               DO INPE=NPE_LIST_START+1,NPE_LIST_START+NPE_LIST_COUNT
                  DUDY = DUDY + CC_EDGE%INT_DCOEF(INPE,1)*CC_EDGE%INT_FVARS(INT_VEL_IND,INPE)
               ENDDO
            ENDIF

            OMEV_EP(ICD_SGN) = DVDX - DUDY
            TAUV_EP(ICD_SGN) = MU_EP*(DVDX + DUDY)
            IF (FAXIS==IAXIS) THEN
               DUIDXJ_EP(ICD_SGN)    = DUDY
            ELSE ! IF(FAXIS==JAXIS) THEN
               DUIDXJ_EP(ICD_SGN)    = DVDX
            ENDIF

      END SELECT IEC_SELECT

      ICF = FCVAR(IIF,JJF,KKF,CC_IDCF,FAXIS)
      !IF ( CUT_FACE(ICF)%ALPHA_CF < 0.05_EB ) CYCLE ! Cycle if cut-face size is less than 0.001 cartesian face.
      IF ( CUT_FACE(ICF)%ALPHA_CF > CCVOL_LINK ) THEN ! Large cut-face.
         VEL_GAS     = UF
         DXN_STRM_UB = DF
      ELSE
          VEL_GAS     = (UF*DF + UE*DE)/(DF+DE)
          DXN_STRM_UB = (DF+DE)
      ENDIF

      ! Make collocated velocity point distance, half DELTA gas CF size:
      DXN_STRM_UB = DXN_STRM_UB/2._EB

      ! Define mu*Gradient:
      MU_DUIDXJ_EP(ICD_SGN) = MU_EP*DUIDXJ_EP(ICD_SGN)

      ! Here we have a cut-face, and OME and TAU in an external EDGE for extrapolation to IBEDGE.
      ! Now get value at the boundary using wall model:
      VEL_GHOST = 0._EB
      SF=>SURFACE(SURF_INDEX)
      SELECT CASE(SF%VELOCITY_BC_INDEX)
         CASE (FREE_SLIP_BC)
            VEL_GHOST = VEL_GAS
            DUIDXJ(ICD_SGN) = I_SGN*(VEL_GAS-VEL_GHOST)/(2._EB*DXN_STRM_UB)
            MU_DUIDXJ(ICD_SGN) = MUA*DUIDXJ(ICD_SGN)
            ALTERED_GRADIENT(ICD_SGN) = .TRUE.
         CASE (NO_SLIP_BC)
            VEL_GHOST = 2._EB*VEL_T - VEL_GAS
            DUIDXJ(ICD_SGN) = I_SGN*(VEL_GAS-VEL_GHOST)/(2._EB*DXN_STRM_UB)
            MU_DUIDXJ(ICD_SGN) = MUA*DUIDXJ(ICD_SGN)
            ALTERED_GRADIENT(ICD_SGN) = .TRUE.
         CASE (WALL_MODEL_BC)
            ! Determine if the cell edge is an external corner:
            CORNER_EDGE=.FALSE.
            N_SOLID_CELLS_ON_EDGE=0
            SELECT CASE(IEC)
               CASE(1)
                  N_SOLID_CELLS_ON_EDGE=COUNT(CCVAR(II,JJ:JJ+1,KK:KK+1,CC_CGSC)==CC_SOLID)
               CASE(2)
                  N_SOLID_CELLS_ON_EDGE=COUNT(CCVAR(II:II+1,JJ,KK:KK+1,CC_CGSC)==CC_SOLID)
               CASE(3)
                  N_SOLID_CELLS_ON_EDGE=COUNT(CCVAR(II:II+1,JJ:JJ+1,KK,CC_CGSC)==CC_SOLID)
            END SELECT
            IF (N_SOLID_CELLS_ON_EDGE==1) CORNER_EDGE=.TRUE.

            NU = MU_FACE/RHO_FACE
            CALL WALL_MODEL(SLIP_FACTOR,U_TAU,Y_PLUS,NU,SF%ROUGHNESS,DXN_STRM_UB,VEL_GAS-VEL_T)
            ! Finally OMEGA, TAU:
            ! SLIP_COEF = -1, no slip,   VEL_GHOST = 2*VEL_T - VEL_GAS
            ! SLIP_COEF =  0, half slip, VEL_GHOST = VEL_T
            ! SLIP_COEF =  1, free slip, VEL_GHOST = VEL_GAS
            IF (CORNER_EDGE) SLIP_FACTOR = 0 ! corner (done to match VELOCITY_BC)
            VEL_GHOST = VEL_T + SLIP_FACTOR*(VEL_GAS-VEL_T)
            DUIDXJ(ICD_SGN) = I_SGN*(VEL_GAS-VEL_GHOST)/(2._EB*DXN_STRM_UB)
            MU_DUIDXJ(ICD_SGN) = RHO_FACE*U_TAU**2 * SIGN(1._EB,DUIDXJ(ICD_SGN))
            ALTERED_GRADIENT(ICD_SGN) = .TRUE.
         CASE (BOUNDARY_FUEL_MODEL_BC)
            U1_T = 0._EB; U2_T = 0._EB
            SELECT CASE(IEC)
               CASE(IAXIS);              U1_T = UU(IIGM,JJGM,KKGM)**2
                  IF(FAXIS==JAXIS) THEN; U2_T = VV(IIGM,JJGM,KKGM)**2; ELSE; U2_T = WW(IIGM,JJGM,KKGM)**2; ENDIF
               CASE(JAXIS);              U1_T = VV(IIGM,JJGM,KKGM)**2
                  IF(FAXIS==IAXIS) THEN; U2_T = UU(IIGM,JJGM,KKGM)**2; ELSE; U2_T = WW(IIGM,JJGM,KKGM)**2; ENDIF
               CASE(KAXIS);              U1_T = WW(IIGM,JJGM,KKGM)**2
                  IF(FAXIS==IAXIS) THEN; U2_T = UU(IIGM,JJGM,KKGM)**2; ELSE; U2_T = VV(IIGM,JJGM,KKGM)**2; ENDIF
            END SELECT
            VEL_T = SQRT(U1_T+U2_T)
            DUIDXJ(ICD_SGN)    = 0._EB
            IF (SF%VEG_LSET_SPREAD) THEN
               VEG_HT = SF%VEG_LSET_HT
               DRAG_FACTOR = 0.5_EB*SF%DRAG_COEFFICIENT*SF%SHAPE_FACTOR*SF%VEG_LSET_BETA*(SF%VEG_LSET_SIGMA*100._EB)
            ELSE
               VEG_HT = SF%LAYER_THICKNESS(1)
               DRAG_FACTOR = 0.5_EB*SF%DRAG_COEFFICIENT*SF%SHAPE_FACTOR*SF%PACKING_RATIO(1)*SF%SURFACE_VOLUME_RATIO(1)
            ENDIF
            HT_SCALE_FACTOR = MIN(1._EB,VEG_HT/ABS(TWENTY_EPSILON_EB+2._EB*DXN_STRM_UB))
            MU_DUIDXJ(ICD_SGN) = I_SGN*RHO_FACE*DRAG_FACTOR*VEG_HT*HT_SCALE_FACTOR**2*VEL_GAS*VEL_T
            DRAG_UVWMAX = MAX(DRAG_UVWMAX,DRAG_FACTOR*HT_SCALE_FACTOR**2*VEL_T)
            ALTERED_GRADIENT(ICD_SGN) = .TRUE.

      END SELECT

      ! VLG(ICD_SGN)=VEL_GAS
      ! NUV(ICD_SGN)=MU_FACE  ! NU
      ! RGH(ICD_SGN)=RHO_FACE ! SURFACE(SURF_INDEX)%ROUGHNESS
      ! UTA(ICD_SGN)=U_TAU

      ! Extrapolation coefficients for the IBEDGE:
      IF(DEL_EP > STM_THRESH_EXTRP*DE) THEN
         EC_B(ICD_SGN) = (DEL_EP + ABS(XB_IB))/DEL_EP
         EC_EP(ICD_SGN)= 1._EB - EC_B(ICD_SGN)
      ELSE
         EC_B(ICD_SGN) = 1._EB
         EC_EP(ICD_SGN)= 0._EB
      ENDIF

      ! If needed re-interpolate stress and duidxj to RC EDGE:
      IEC_SELECT_2: SELECT CASE(IEC)
         CASE(IAXIS) IEC_SELECT_2
            ! Define Face indexes and normal axis FAXIS.
            SELECT CASE(ICD_SGN)
               CASE(-2); IIF=II  ; JJF=JJ  ; KKF=KK  ; FAXIS=JAXIS
               CASE(-1); IIF=II  ; JJF=JJ  ; KKF=KK  ; FAXIS=KAXIS
               CASE( 1); IIF=II  ; JJF=JJ+1; KKF=KK  ; FAXIS=KAXIS
               CASE( 2); IIF=II  ; JJF=JJ  ; KKF=KK+1; FAXIS=JAXIS
            END SELECT
            IF(FCVAR(IIF,JJF,KKF,CC_FGSC,FAXIS)/=CC_CUTCFE) CYCLE SIGN_LOOP
            DXX(1)  = DY(JJF); DXX(2)  = DZ(KKF)
            IF (FAXIS==JAXIS) THEN
               DEL_EP = DXX(2) - ABS(XB_IB)
               IF( DEL_EP < THRES_FCT_EP*DXX(2) ) THEN
                  DEL_EP = DEL_EP + DXX(2);
                  IRC=II; JRC=JJ; KRC=KK+I_SGN
                  IRCEDG = ECVAR(IRC,JRC,KRC,CC_IDCE,IEC)
                  IF (IRCEDG>0 .AND. ECVAR(IRC,JRC,KRC,CC_EGSC,IEC)==CC_GASPHASE) THEN
                     CEP = (DXX(2) - ABS(XB_IB))/DEL_EP; CB=DXX(2)/DEL_EP
                     CC_RCEDGE(IRCEDG)%DUIDXJ((/ -ICD, ICD /))    = 0.5_EB*(CC_RCEDGE(IRCEDG)%DUIDXJ(ICD_SGN) + &
                                                                     CEP*   DUIDXJ_EP(ICD_SGN) + CB*   DUIDXJ(ICD_SGN))
                     CC_RCEDGE(IRCEDG)%MU_DUIDXJ((/ -ICD, ICD /)) = 0.5_EB*(CC_RCEDGE(IRCEDG)%MU_DUIDXJ(ICD_SGN) + &
                                                                     CEP*MU_DUIDXJ_EP(ICD_SGN) + CB*MU_DUIDXJ(ICD_SGN))
                  ENDIF
               ENDIF
            ELSE ! IF(FAXIS==KAXIS) THEN
               DEL_EP = DXX(1) - ABS(XB_IB)
               IF( DEL_EP < THRES_FCT_EP*DXX(1) ) THEN
                  DEL_EP = DEL_EP + DXX(1);
                  IRC=II; JRC=JJ+I_SGN; KRC=KK
                  IRCEDG = ECVAR(IRC,JRC,KRC,CC_IDCE,IEC)
                  IF (IRCEDG>0 .AND. ECVAR(IRC,JRC,KRC,CC_EGSC,IEC)==CC_GASPHASE) THEN
                     CEP = (DXX(1) - ABS(XB_IB))/DEL_EP; CB=DXX(1)/DEL_EP
                     CC_RCEDGE(IRCEDG)%DUIDXJ((/ -ICD, ICD /))    = 0.5_EB*(CC_RCEDGE(IRCEDG)%DUIDXJ(ICD_SGN) + &
                                                                     CEP*   DUIDXJ_EP(ICD_SGN) + CB*   DUIDXJ(ICD_SGN))
                     CC_RCEDGE(IRCEDG)%MU_DUIDXJ((/ -ICD, ICD /)) = 0.5_EB*(CC_RCEDGE(IRCEDG)%MU_DUIDXJ(ICD_SGN) + &
                                                                     CEP*MU_DUIDXJ_EP(ICD_SGN) + CB*MU_DUIDXJ(ICD_SGN))
                  ENDIF
               ENDIF
            ENDIF
         CASE(JAXIS) IEC_SELECT_2
            ! Define Face indexes and normal axis FAXIS.
            SELECT CASE(ICD_SGN)
               CASE(-2); IIF=II  ; JJF=JJ  ; KKF=KK  ; FAXIS=KAXIS
               CASE(-1); IIF=II  ; JJF=JJ  ; KKF=KK  ; FAXIS=IAXIS
               CASE( 1); IIF=II  ; JJF=JJ  ; KKF=KK+1; FAXIS=IAXIS
               CASE( 2); IIF=II+1; JJF=JJ  ; KKF=KK  ; FAXIS=KAXIS
            END SELECT
            IF(FCVAR(IIF,JJF,KKF,CC_FGSC,FAXIS)/=CC_CUTCFE) CYCLE SIGN_LOOP
            DXX(1)  = DZ(KKF); DXX(2)  = DX(IIF)
            IF (FAXIS==KAXIS) THEN
               DEL_EP = DXX(2) - ABS(XB_IB)
               IF( DEL_EP < THRES_FCT_EP*DXX(2) ) THEN
                  DEL_EP = DEL_EP + DXX(2);
                  IRC=II+I_SGN; JRC=JJ; KRC=KK
                  IRCEDG = ECVAR(IRC,JRC,KRC,CC_IDCE,IEC)
                  IF (IRCEDG>0 .AND. ECVAR(IRC,JRC,KRC,CC_EGSC,IEC)==CC_GASPHASE) THEN
                     CEP = (DXX(2) - ABS(XB_IB))/DEL_EP; CB=DXX(2)/DEL_EP
                     CC_RCEDGE(IRCEDG)%DUIDXJ((/ -ICD, ICD /))    = 0.5_EB*(CC_RCEDGE(IRCEDG)%DUIDXJ(ICD_SGN) + &
                                                                     CEP*   DUIDXJ_EP(ICD_SGN) + CB*   DUIDXJ(ICD_SGN))
                     CC_RCEDGE(IRCEDG)%MU_DUIDXJ((/ -ICD, ICD /)) = 0.5_EB*(CC_RCEDGE(IRCEDG)%MU_DUIDXJ(ICD_SGN) + &
                                                                     CEP*MU_DUIDXJ_EP(ICD_SGN) + CB*MU_DUIDXJ(ICD_SGN))
                  ENDIF
               ENDIF
            ELSE ! IF(FAXIS==IAXIS) THEN
               DEL_EP = DXX(1) - ABS(XB_IB)
               IF( DEL_EP < THRES_FCT_EP*DXX(1) ) THEN
                  DEL_EP = DEL_EP + DXX(1);
                  IRC=II; JRC=JJ; KRC=KK+I_SGN
                  IRCEDG = ECVAR(IRC,JRC,KRC,CC_IDCE,IEC)
                  IF (IRCEDG>0 .AND. ECVAR(IRC,JRC,KRC,CC_EGSC,IEC)==CC_GASPHASE) THEN
                     CEP = (DXX(1) - ABS(XB_IB))/DEL_EP; CB=DXX(1)/DEL_EP
                     ! WRITE(LU_ERR,*) ' '
                     ! WRITE(LU_ERR,*) 'EDGE JAXIS=',IRC,JRC,KRC,CEP,CB
                     ! WRITE(LU_ERR,*) 'OLD DUIDXJ=',CC_RCEDGE(IRCEDG)%DUIDXJ(ICD_SGN),CC_RCEDGE(IRCEDG)%MU_DUIDXJ(ICD_SGN)
                     ! WRITE(LU_ERR,*) 'EP  DUIDXJ=',DUIDXJ_EP(ICD_SGN),MU_DUIDXJ_EP(ICD_SGN)
                     ! WRITE(LU_ERR,*) 'B   DUIDXJ=',DUIDXJ (ICD_SGN),MU_DUIDXJ (ICD_SGN)
                     CC_RCEDGE(IRCEDG)%DUIDXJ((/ -ICD, ICD /))     = 0.5_EB*(CC_RCEDGE(IRCEDG)%DUIDXJ(ICD_SGN) + &
                                                                      CEP*   DUIDXJ_EP(ICD_SGN) + CB*   DUIDXJ(ICD_SGN))
                     CC_RCEDGE(IRCEDG)%MU_DUIDXJ((/ -ICD, ICD /))  = 0.5_EB*(CC_RCEDGE(IRCEDG)%MU_DUIDXJ(ICD_SGN) + &
                                                                      CEP*MU_DUIDXJ_EP(ICD_SGN) + CB*MU_DUIDXJ(ICD_SGN))
                     ! WRITE(LU_ERR,*) 'NEW   DUIDXJ=',CC_RCEDGE(IRCEDG)%DUIDXJ(ICD_SGN), CC_RCEDGE(IRCEDG)%MU_DUIDXJ(ICD_SGN)
                     ! WRITE(LU_ERR,*) 'OTHER DUIDXJ=',CC_RCEDGE(IRCEDG)%DUIDXJ(-ICD_SGN),CC_RCEDGE(IRCEDG)%MU_DUIDXJ(-ICD_SGN)
                  ENDIF
               ENDIF
            ENDIF
         CASE(KAXIS) IEC_SELECT_2
            ! Define Face indexes and normal axis FAXIS.
            SELECT CASE(ICD_SGN)
               CASE(-2); IIF=II  ; JJF=JJ  ; KKF=KK  ; FAXIS=IAXIS
               CASE(-1); IIF=II  ; JJF=JJ  ; KKF=KK  ; FAXIS=JAXIS
               CASE( 1); IIF=II+1; JJF=JJ  ; KKF=KK  ; FAXIS=JAXIS
               CASE( 2); IIF=II  ; JJF=JJ+1; KKF=KK  ; FAXIS=IAXIS
            END SELECT
            IF(FCVAR(IIF,JJF,KKF,CC_FGSC,FAXIS)/=CC_CUTCFE) CYCLE SIGN_LOOP
            DXX(1)  = DX(IIF); DXX(2)  = DY(JJF)

            IF (FAXIS==IAXIS) THEN
               DEL_EP = DXX(2) - ABS(XB_IB)
               IF( DEL_EP < THRES_FCT_EP*DXX(2) ) THEN
                  DEL_EP = DEL_EP + DXX(2);
                  IRC=II; JRC=JJ+I_SGN; KRC=KK
                  IRCEDG = ECVAR(IRC,JRC,KRC,CC_IDCE,IEC)
                  IF (IRCEDG>0 .AND. ECVAR(IRC,JRC,KRC,CC_EGSC,IEC)==CC_GASPHASE) THEN
                     CEP = (DXX(2) - ABS(XB_IB))/DEL_EP; CB=DXX(2)/DEL_EP
                     CC_RCEDGE(IRCEDG)%DUIDXJ((/ -ICD, ICD /))    = 0.5_EB*(CC_RCEDGE(IRCEDG)%DUIDXJ(ICD_SGN) + &
                                                                     CEP*   DUIDXJ_EP(ICD_SGN) + CB*   DUIDXJ(ICD_SGN))
                     CC_RCEDGE(IRCEDG)%MU_DUIDXJ((/ -ICD, ICD /)) = 0.5_EB*(CC_RCEDGE(IRCEDG)%MU_DUIDXJ(ICD_SGN) + &
                                                                     CEP*MU_DUIDXJ_EP(ICD_SGN) + CB*MU_DUIDXJ(ICD_SGN))
                  ENDIF
               ENDIF
            ELSE ! IF(FAXIS==JAXIS) THEN
               DEL_EP = DXX(1) - ABS(XB_IB)
               IF( DEL_EP < THRES_FCT_EP*DXX(1) ) THEN
                  DEL_EP = DEL_EP + DXX(1);
                  IRC=II+I_SGN; JRC=JJ; KRC=KK
                  IRCEDG = ECVAR(IRC,JRC,KRC,CC_IDCE,IEC)
                  IF (IRCEDG>0 .AND. ECVAR(IRC,JRC,KRC,CC_EGSC,IEC)==CC_GASPHASE) THEN
                     CEP = (DXX(1) - ABS(XB_IB))/DEL_EP; CB=DXX(1)/DEL_EP
                     CC_RCEDGE(IRCEDG)%DUIDXJ((/ -ICD, ICD /))    = 0.5_EB*(CC_RCEDGE(IRCEDG)%DUIDXJ(ICD_SGN) + &
                                                                     CEP*   DUIDXJ_EP(ICD_SGN) + CB*   DUIDXJ(ICD_SGN))
                     CC_RCEDGE(IRCEDG)%MU_DUIDXJ((/ -ICD, ICD /)) = 0.5_EB*(CC_RCEDGE(IRCEDG)%MU_DUIDXJ(ICD_SGN) + &
                                                                     CEP*MU_DUIDXJ_EP(ICD_SGN) + CB*MU_DUIDXJ(ICD_SGN))
                  ENDIF
               ENDIF
            ENDIF
      END SELECT IEC_SELECT_2

   ENDDO SIGN_LOOP
ENDDO ORIENTATION_LOOP

! Cycle out of the EDGE_LOOP if no tangential gradients have been altered.

IF (.NOT.ANY(ALTERED_GRADIENT)) RETURN

! Loop over all 4 normal directions and compute vorticity and stress tensor components for each

SIGN_LOOP_2: DO I_SGN=-1,1,2
   ORIENTATION_LOOP_2: DO ICD=1,2
      IF (ICD==1) THEN
         ICDO=2
      ELSE ! ICD=2
         ICDO=1
      ENDIF
      ICD_SGN = I_SGN*ICD
      IF (ALTERED_GRADIENT(ICD_SGN)) THEN ! Note, altered gradients are extrapolated to IB edge using boundary B and external EP.
            !DUIDXJ_USE(ICD) = EC_B(ICD_SGN)*DUIDXJ(ICD_SGN)  +  EC_EP(ICD_SGN)*DUIDXJ_EP(ICD_SGN)
            DUIDXJ_USE(ICD) =               DUIDXJ(ICD_SGN)
         MU_DUIDXJ_USE(ICD) = EC_B(ICD_SGN)*MU_DUIDXJ(ICD_SGN)  + EC_EP(ICD_SGN)*MU_DUIDXJ_EP(ICD_SGN)
      ELSEIF (ALTERED_GRADIENT(-ICD_SGN)) THEN
            !DUIDXJ_USE(ICD) = EC_B(-ICD_SGN)*DUIDXJ(-ICD_SGN) + EC_EP(-ICD_SGN)*DUIDXJ_EP(-ICD_SGN)
            DUIDXJ_USE(ICD) =                DUIDXJ(-ICD_SGN)
         MU_DUIDXJ_USE(ICD) = EC_B(-ICD_SGN)*MU_DUIDXJ(-ICD_SGN) + EC_EP(-ICD_SGN)*MU_DUIDXJ_EP(-ICD_SGN)
      ELSE
         CYCLE ORIENTATION_LOOP_2
      ENDIF
      ICDO_SGN = I_SGN*ICDO
      IF (ALTERED_GRADIENT(ICDO_SGN) .AND. .NOT.CC_EDGE%SIDE_IN_GEOM(ICDO_SGN)) THEN
            !DUIDXJ_USE(ICDO) = EC_B(ICDO_SGN)*DUIDXJ(ICDO_SGN)  +  EC_EP(ICDO_SGN)*DUIDXJ_EP(ICDO_SGN)
            DUIDXJ_USE(ICDO) =                 DUIDXJ(ICDO_SGN)
         MU_DUIDXJ_USE(ICDO) = EC_B(ICDO_SGN)*MU_DUIDXJ(ICDO_SGN) + EC_EP(ICDO_SGN)*MU_DUIDXJ_EP(ICDO_SGN)
      ELSEIF (ALTERED_GRADIENT(-ICDO_SGN) .AND. .NOT.CC_EDGE%SIDE_IN_GEOM(-ICDO_SGN)) THEN
            !DUIDXJ_USE(ICDO) = EC_B(-ICDO_SGN)*DUIDXJ(-ICDO_SGN) + EC_EP(-ICDO_SGN)*DUIDXJ_EP(-ICDO_SGN)
            DUIDXJ_USE(ICDO) =                 DUIDXJ(-ICDO_SGN)
         MU_DUIDXJ_USE(ICDO) = EC_B(-ICDO_SGN)*MU_DUIDXJ(-ICDO_SGN) + EC_EP(-ICDO_SGN)*MU_DUIDXJ_EP(-ICDO_SGN)
      ELSE
            DUIDXJ_USE(ICDO) = 0._EB
         MU_DUIDXJ_USE(ICDO) = 0._EB
      ENDIF
      EDGE(IE)%OMEGA(ICD_SGN) =    DUIDXJ_USE(1) -    DUIDXJ_USE(2)
      EDGE(IE)%TAU(ICD_SGN)   = MU_DUIDXJ_USE(1) + MU_DUIDXJ_USE(2)
   ENDDO ORIENTATION_LOOP_2
ENDDO SIGN_LOOP_2

END SUBROUTINE CC_EDGE_TAU_OMG

! SUBROUTINE GET_QUAD_VEL(DF,DE,UF,UE,UB,USTR_2)
!
! REAL(EB), INTENT(IN) :: DF,DE,UF,UE,UB
! REAL(EB), INTENT(OUT):: USTR_2
! ! Local variables:
! REAL(EB) :: B_POLY, C_POLY
!
! B_POLY = -(2._EB*(DE**2*UB + 2._EB*DF**2*UB - DE**2*UF + DF**2*UE - 3._EB*DF**2*UF + &
!                   3._EB*DE*DF*UB - 3._EB*DE*DF*UF))/(DF*(DE + DF)**2 + TWENTY_EPSILON_EB)
! C_POLY =  (3._EB*(DE*UB + DF*UB - DE*UF + DF*UE - 2._EB*DF*UF))/(DF*(DE + DF)**2 + TWENTY_EPSILON_EB)
! USTR_2  =  UB + B_POLY*DXN_STRM_UB/2._EB + C_POLY*(DXN_STRM_UB/2._EB)**2
!
! RETURN
! END SUBROUTINE GET_QUAD_VEL

END SUBROUTINE CC_VELOCITY_BC

! ! ------------------------- CC_RESCALE_FACE_FORCE ---------------------------
!
! SUBROUTINE CC_RESCALE_FACE_FORCE(NM)
!
! INTEGER, INTENT(IN) :: NM
!
! ! Local Vars:
! INTEGER :: ICF,I,J,K,X1AXIS
! !REAL(EB):: AREA_CF
!
! CUTFACE_LOOP : DO ICF=1,MESHES(NM)%N_CUTFACE_MESH
!
!    IF ( CUT_FACE(ICF)%STATUS /= CC_GASPHASE) CYCLE
!    ! IW = CUT_FACE(ICF)%IWC
!    ! IF ( (IW > 0) .AND. (WALL(IW)%BOUNDARY_TYPE==SOLID_BOUNDARY   .OR. &
!    !                      WALL(IW)%BOUNDARY_TYPE==NULL_BOUNDARY    .OR. &
!    !                      WALL(IW)%BOUNDARY_TYPE==MIRROR_BOUNDARY) ) CYCLE ! Here force Open boundaries.
!
!    I      = CUT_FACE(ICF)%IJK(IAXIS)
!    J      = CUT_FACE(ICF)%IJK(JAXIS)
!    K      = CUT_FACE(ICF)%IJK(KAXIS)
!    X1AXIS = CUT_FACE(ICF)%IJK(KAXIS+1)
!    ! AREA_CF   = SUM(CUT_FACE(ICF)%AREA(1:CUT_FACE(ICF)%NFACE))
!
!    SELECT CASE(X1AXIS)
!    CASE(IAXIS); FVX(I,J,K) = FVX(I,J,K)*CUT_FACE(ICF)%VOLFCT_CRF !AREA_CF/(DY(J)*DZ(K))
!    CASE(JAXIS); FVY(I,J,K) = FVY(I,J,K)*CUT_FACE(ICF)%VOLFCT_CRF !AREA_CF/(DX(I)*DZ(K))
!    CASE(KAXIS); FVZ(I,J,K) = FVZ(I,J,K)*CUT_FACE(ICF)%VOLFCT_CRF !AREA_CF/(DX(I)*DY(J))
!    END SELECT
!
! ENDDO CUTFACE_LOOP
!
!
! RETURN
! END SUBROUTINE CC_RESCALE_FACE_FORCE


! --------------------------- CC_VELOCITY_FLUX ------------------------------

SUBROUTINE CC_VELOCITY_FLUX(NM,DT,APPLY_TO_ESTIMATED_VARIABLES,RHOP,CORRECT_GRAV,GX,GY,GZ)

! Assumes POINT_TO_MESH has been called.

INTEGER, INTENT(IN) :: NM
LOGICAL, INTENT(IN) :: APPLY_TO_ESTIMATED_VARIABLES,CORRECT_GRAV
REAL(EB),INTENT(IN) :: DT
REAL(EB),INTENT(IN), OPTIONAL :: GX(0:IBAR_MAX),GY(0:IBAR_MAX),GZ(0:IBAR_MAX)
REAL(EB), INTENT(IN), POINTER, DIMENSION(:,:,:) :: RHOP

! Local Variables:
INTEGER  :: ICF,LCF,IRC,I,J,K,X1AXIS,JCF,ICC,JCC,ISIDE,IF_,IFACE
REAL(EB) :: TNOW, TNOW2, RRHO, X1F, IDX, CCM1, CCP1, RHOV(-1:0), RHO0V(-1:0), FVCC, PRFCT
TYPE(CC_FV_TYPE), POINTER :: FV

IF ( FREEZE_VELOCITY .OR. SOLID_PHASE_ONLY ) RETURN
IF (PERIODIC_TEST == 103 .OR. PERIODIC_TEST == 11 .OR. PERIODIC_TEST==7) RETURN
FV=>MESHES(NM)%FV

! Dummy for now:
TNOW = DT
TNOW = CURRENT_TIME()

CORRECT_GRAV_IF : IF(CORRECT_GRAV) THEN

PRFCT = 0._EB; IF(APPLY_TO_ESTIMATED_VARIABLES) PRFCT=1._EB
WHERE(FCVAR(0:IBAR,1:JBAR,1:KBAR,CC_FGSC,IAXIS)==CC_SOLID) FVX(0:IBAR,1:JBAR,1:KBAR) = 0._EB
WHERE(FCVAR(1:IBAR,0:JBAR,1:KBAR,CC_FGSC,JAXIS)==CC_SOLID) FVY(1:IBAR,0:JBAR,1:KBAR) = 0._EB
WHERE(FCVAR(1:IBAR,1:JBAR,0:KBAR,CC_FGSC,KAXIS)==CC_SOLID) FVZ(1:IBAR,1:JBAR,0:KBAR) = 0._EB
! Correct the gravity terms for RC and cut-faces:
CUTFACE_LOOP_0 : DO LCF=1,SIZE(MESHES(NM)%CF_GAS)
   ICF=MESHES(NM)%CF_GAS(LCF); CF => CUT_FACE(ICF)
   I = CF%IJK(IAXIS); J = CF%IJK(JAXIS); K = CF%IJK(KAXIS); X1AXIS = CF%IJK(KAXIS+1)
   FVCC = 0._EB
   DO JCF=1,CF%NFACE
      X1F= CF%XYZCEN(X1AXIS,JCF)
      IF_=CF%FC(JCF)
      IDX= GET_FV_FACE_RDN(NM,IF_,1._EB/(CF%XCENHIGH(X1AXIS,JCF)-CF%XCENLOW(X1AXIS,JCF)))
      CCM1= IDX*(CF%XCENHIGH(X1AXIS,JCF)-X1F); CCP1= IDX*(X1F-CF%XCENLOW(X1AXIS, JCF))
      RHOV(-1:0) = 0._EB; RHO0V(-1:0) = 0._EB
      DO ISIDE=-1,0
         SELECT CASE(CF%CELL_LIST(1,ISIDE+2,JCF))
         CASE(CC_FTYPE_CFGAS) ! Cut-cell -> use Temperature value from CUT_CELL data struct:
            ICC = CF%CELL_LIST(2,ISIDE+2,JCF); CC=>CUT_CELL(ICC)
            JCC = CF%CELL_LIST(3,ISIDE+2,JCF)
            RHOV(ISIDE) = GET_CUTCELL_RHOP(NM,ICC,JCC,1._EB-PRFCT)
            IF (CC%IG(JCC)>=1 .AND. CC%IG(JCC)<=FV%GCELL%N_INT) THEN
               RHO0V(ISIDE) = MESHES(NM)%FV%CV%RHO_0(CC%IG(JCC))
            ELSE
               RHO0V(ISIDE) = RHO_0(CC%IJK(KAXIS))
            ENDIF
         END SELECT
      ENDDO
      ! RHO_FACE =  CCM1*RHOV(-1) +  CCP1*RHOV(0); RHO0_FACE= CCM1*RHO0V(-1) + CCP1*RHO0V(0)
      FVCC = FVCC + CF%AREA(JCF)*((CCM1*RHO0V(-1)+CCP1*RHO0V(0))/(CCM1*RHOV(-1)+CCP1*RHOV(0)))
   ENDDO
   FVCC = FVCC/SUM(CF%AREA(1:CF%NFACE))
   ! Apply unstructured - cartesian correction:
   SELECT CASE(X1AXIS)
   CASE(IAXIS)
      RRHO       = 2._EB / (RHOP(I,J,K)+RHOP(I+1,J,K))
      FVX(I,J,K) = FVX(I,J,K) + GX(I)*(FVCC - RRHO*RHO_0(K))
   CASE(JAXIS)
      RRHO       = 2._EB / (RHOP(I,J,K)+RHOP(I,J+1,K))
      FVY(I,J,K) = FVY(I,J,K) + GY(I)*(FVCC - RRHO*RHO_0(K))
   CASE(KAXIS)
      RRHO       = 2._EB / (RHOP(I,J,K)+RHOP(I,J,K+1))
      FVZ(I,J,K) = FVZ(I,J,K) + GZ(I)*(FVCC - RRHO*0.5_EB*(RHO_0(K)+RHO_0(K+1)))
   END SELECT
ENDDO CUTFACE_LOOP_0

RC_FACE_LOOP : DO IRC=1,MESHES(NM)%CC_NRCFACE_Z
   RCF    =>RC_FACE(IRC)
   I      = RCF%IJK(IAXIS); J = RCF%IJK(JAXIS); K = RCF%IJK(KAXIS); X1AXIS = RCF%IJK(KAXIS+1)
   IDX = GET_FV_FACE_RDN(NM,RCF%FC,1._EB/(RCF%XCEN(X1AXIS,HIGH_IND)-RCF%XCEN(X1AXIS,LOW_IND)))
   SELECT CASE(X1AXIS)
   CASE(IAXIS)
      CCM1= IDX*(RCF%XCEN(X1AXIS,HIGH_IND)-X(I))
      CCP1= IDX*(X(I)-RCF%XCEN(X1AXIS,LOW_IND) )
      RHOV(-1:0) = RHOP(I:I+1,J,K); RHO0V(-1:0) = RHO_0(K)
      IF(CCVAR(I  ,J,K,CC_UNKZ)>0) RHO0V(-1)=RHO_0_CV(CCVAR(I  ,J,K,CC_UNKZ))
      IF(CCVAR(I+1,J,K,CC_UNKZ)>0) RHO0V( 0)=RHO_0_CV(CCVAR(I+1,J,K,CC_UNKZ))
      DO ISIDE=-1,0
         SELECT CASE(RCF%CELL_LIST(1,ISIDE+2))
         CASE(CC_FTYPE_CFGAS) ! Cut-cell
            ICC = RCF%CELL_LIST(2,ISIDE+2); JCC = RCF%CELL_LIST(3,ISIDE+2); CC=>CUT_CELL(ICC)
            RHOV(ISIDE) = GET_CUTCELL_RHOP(NM,ICC,JCC,1._EB-PRFCT)
            IF (CC%IG(JCC)>=1 .AND. CC%IG(JCC)<=FV%GCELL%N_INT) THEN
               RHO0V(ISIDE) = MESHES(NM)%FV%CV%RHO_0(CC%IG(JCC))
            ELSE
               RHO0V(ISIDE) = RHO_0(CC%IJK(KAXIS))
            ENDIF
         END SELECT
      ENDDO
      FVCC = (CCM1*RHO0V(-1) + CCP1*RHO0V(0)) / (CCM1*RHOV(-1) + CCP1*RHOV(0))
      RRHO = 2._EB / (RHOP(I,J,K)+RHOP(I+1,J,K))
      FVX(I,J,K) = FVX(I,J,K) + GX(I)*(FVCC - RRHO*RHO_0(K))
   CASE(JAXIS)
      CCM1= IDX*(RCF%XCEN(X1AXIS,HIGH_IND)-Y(J))
      CCP1= IDX*(Y(J)-RCF%XCEN(X1AXIS,LOW_IND) )
      RHOV(-1:0) = RHOP(I,J:J+1,K); RHO0V(-1:0) = RHO_0(K)
      IF(CCVAR(I,J  ,K,CC_UNKZ)>0) RHO0V(-1)=RHO_0_CV(CCVAR(I,J  ,K,CC_UNKZ))
      IF(CCVAR(I,J+1,K,CC_UNKZ)>0) RHO0V( 0)=RHO_0_CV(CCVAR(I,J+1,K,CC_UNKZ))
      DO ISIDE=-1,0
         SELECT CASE(RCF%CELL_LIST(1,ISIDE+2))
         CASE(CC_FTYPE_CFGAS) ! Cut-cell
            ICC = RCF%CELL_LIST(2,ISIDE+2); JCC = RCF%CELL_LIST(3,ISIDE+2); CC=>CUT_CELL(ICC)
            RHOV(ISIDE) = GET_CUTCELL_RHOP(NM,ICC,JCC,1._EB-PRFCT)
            IF (CC%IG(JCC)>=1 .AND. CC%IG(JCC)<=FV%GCELL%N_INT) THEN
               RHO0V(ISIDE) = MESHES(NM)%FV%CV%RHO_0(CC%IG(JCC))
            ELSE
               RHO0V(ISIDE) = RHO_0(CC%IJK(KAXIS))
            ENDIF
         END SELECT
      ENDDO
      FVCC = (CCM1*RHO0V(-1) + CCP1*RHO0V(0)) / (CCM1*RHOV(-1) + CCP1*RHOV(0))
      RRHO = 2._EB / (RHOP(I,J,K)+RHOP(I,J+1,K))
      FVY(I,J,K) = FVY(I,J,K) + GY(I)*(FVCC - RRHO*RHO_0(K))
   CASE(KAXIS)
      CCM1= IDX*(RCF%XCEN(X1AXIS,HIGH_IND)-Z(K))
      CCP1= IDX*(Z(K)-RCF%XCEN(X1AXIS,LOW_IND) )
      RHOV(-1:0) = RHOP(I,J,K:K+1); RHO0V(-1:0) = RHO_0(K:K+1)
      IF(CCVAR(I,J,K  ,CC_UNKZ)>0) RHO0V(-1)=RHO_0_CV(CCVAR(I,J,K  ,CC_UNKZ))
      IF(CCVAR(I,J,K+1,CC_UNKZ)>0) RHO0V( 0)=RHO_0_CV(CCVAR(I,J,K+1,CC_UNKZ))
      DO ISIDE=-1,0
         SELECT CASE(RCF%CELL_LIST(1,ISIDE+2))
         CASE(CC_FTYPE_CFGAS) ! Cut-cell
            ICC = RCF%CELL_LIST(2,ISIDE+2); JCC = RCF%CELL_LIST(3,ISIDE+2); CC=>CUT_CELL(ICC)
            RHOV(ISIDE) = GET_CUTCELL_RHOP(NM,ICC,JCC,1._EB-PRFCT)
            IF (CC%IG(JCC)>=1 .AND. CC%IG(JCC)<=FV%GCELL%N_INT) THEN
               RHO0V(ISIDE) = MESHES(NM)%FV%CV%RHO_0(CC%IG(JCC))
            ELSE
               RHO0V(ISIDE) = RHO_0(CC%IJK(KAXIS))
            ENDIF
         END SELECT
      ENDDO
      FVCC = (CCM1*RHO0V(-1) + CCP1*RHO0V(0)) / (CCM1*RHOV(-1) + CCP1*RHOV(0))
      RRHO = 2._EB / (RHOP(I,J,K)+RHOP(I,J,K+1))
      FVZ(I,J,K) = FVZ(I,J,K) + GZ(I)*(FVCC - RRHO*0.5_EB*(RHO_0(K)+RHO_0(K+1)))
   END SELECT
ENDDO RC_FACE_LOOP

! Faces with two regular gas cells, one of them belonging to a linked control volume (GRAV_FACE, set once):
CCM1=0.5_EB; CCP1=0.5_EB
DO IFACE=MESHES(NM)%GRAV_PTR(IAXIS),MESHES(NM)%GRAV_PTR(JAXIS)-1
   I = MESHES(NM)%GRAV_FACE(1,IFACE); J = MESHES(NM)%GRAV_FACE(2,IFACE); K = MESHES(NM)%GRAV_FACE(3,IFACE)
   RHOV(-1:0) = RHOP(I:I+1,J,K); RHO0V(-1:0) = RHO_0(K)
   IF(CCVAR(I  ,J,K,CC_UNKZ)>0) RHO0V(-1)=RHO_0_CV(CCVAR(I  ,J,K,CC_UNKZ))
   IF(CCVAR(I+1,J,K,CC_UNKZ)>0) RHO0V( 0)=RHO_0_CV(CCVAR(I+1,J,K,CC_UNKZ))
   FVCC = (CCM1*RHO0V(-1) + CCP1*RHO0V(0)) / (CCM1*RHOV(-1) + CCP1*RHOV(0))
   RRHO = 2._EB / (RHOP(I,J,K)+RHOP(I+1,J,K))
   FVX(I,J,K) = FVX(I,J,K) + GX(I)*(FVCC - RRHO*RHO_0(K))
ENDDO

DO IFACE=MESHES(NM)%GRAV_PTR(JAXIS),MESHES(NM)%GRAV_PTR(KAXIS)-1
   I = MESHES(NM)%GRAV_FACE(1,IFACE); J = MESHES(NM)%GRAV_FACE(2,IFACE); K = MESHES(NM)%GRAV_FACE(3,IFACE)
   RHOV(-1:0) = RHOP(I,J:J+1,K); RHO0V(-1:0) = RHO_0(K)
   IF(CCVAR(I,J  ,K,CC_UNKZ)>0) RHO0V(-1)=RHO_0_CV(CCVAR(I,J  ,K,CC_UNKZ))
   IF(CCVAR(I,J+1,K,CC_UNKZ)>0) RHO0V( 0)=RHO_0_CV(CCVAR(I,J+1,K,CC_UNKZ))
   FVCC = (CCM1*RHO0V(-1) + CCP1*RHO0V(0)) / (CCM1*RHOV(-1) + CCP1*RHOV(0))
   RRHO = 2._EB / (RHOP(I,J,K)+RHOP(I,J+1,K))
   FVY(I,J,K) = FVY(I,J,K) + GY(I)*(FVCC - RRHO*RHO_0(K))
ENDDO

DO IFACE=MESHES(NM)%GRAV_PTR(KAXIS),MESHES(NM)%GRAV_PTR(KAXIS+1)-1
   I = MESHES(NM)%GRAV_FACE(1,IFACE); J = MESHES(NM)%GRAV_FACE(2,IFACE); K = MESHES(NM)%GRAV_FACE(3,IFACE)
   RHOV(-1:0) = RHOP(I,J,K:K+1); RHO0V(-1:0) = RHO_0(K:K+1)
   IF(CCVAR(I,J,K  ,CC_UNKZ)>0) RHO0V(-1)=RHO_0_CV(CCVAR(I,J,K  ,CC_UNKZ))
   IF(CCVAR(I,J,K+1,CC_UNKZ)>0) RHO0V( 0)=RHO_0_CV(CCVAR(I,J,K+1,CC_UNKZ))
   FVCC = (CCM1*RHO0V(-1) + CCP1*RHO0V(0)) / (CCM1*RHOV(-1) + CCP1*RHOV(0))
   RRHO = 2._EB / (RHOP(I,J,K)+RHOP(I,J,K+1))
   FVZ(I,J,K) = FVZ(I,J,K) + GZ(I)*(FVCC - RRHO*0.5_EB*(RHO_0(K)+RHO_0(K+1)))
ENDDO

! Publish the corrected Cartesian FN onto the cut-face FACE rows.
DO LCF=1,SIZE(MESHES(NM)%CF_GAS)
   ICF=MESHES(NM)%CF_GAS(LCF); CF => CUT_FACE(ICF)
   I = CF%IJK(IAXIS); J = CF%IJK(JAXIS); K = CF%IJK(KAXIS); X1AXIS = CF%IJK(KAXIS+1)
   SELECT CASE(X1AXIS)
   CASE(IAXIS); FVCC = FVX(I,J,K)
   CASE(JAXIS); FVCC = FVY(I,J,K)
   CASE(KAXIS); FVCC = FVZ(I,J,K)
   END SELECT
   DO JCF=1,CF%NFACE
      IF_=MESHES(NM)%CUT_FACE(ICF)%FC(JCF)
      FV%FACE%FN(IF_)=FVCC
   ENDDO
ENDDO

ELSE CORRECT_GRAV_IF

! Add FV into the FACE FN row.
CALL CC_STORE_FACE_FV(NM,SUBSTRACT_BAROCLINIC=.FALSE.)

CUTFACE_LOOP : DO LCF=1,SIZE(MESHES(NM)%CF_GAS)
   ICF=MESHES(NM)%CF_GAS(LCF)
   DO JCF=1,CUT_FACE(ICF)%NFACE
      IF_=MESHES(NM)%CUT_FACE(ICF)%FC(JCF)
      FV%FACE%FN(IF_)=CUT_FACE(ICF)%FV
   ENDDO
ENDDO CUTFACE_LOOP

ENDIF CORRECT_GRAV_IF

T_USED(14) = T_USED(14) + CURRENT_TIME() - TNOW
IF (TIME_CC_IBM) T_CC_USED(CC_VELOCITY_FLUX_TIME_INDEX) = T_CC_USED(CC_VELOCITY_FLUX_TIME_INDEX) + CURRENT_TIME() - TNOW2
RETURN
END SUBROUTINE CC_VELOCITY_FLUX


SUBROUTINE GET_LINKED_FV(NM,DO_BAROCLINIC)

! Area mean of FN (or FN_B) over each face link group, written back to its members. Members are summed in one
! global order and groups held by several meshes take L2_CROSS_SUMS, which the caller runs first.

INTEGER, INTENT(IN) :: NM
LOGICAL, INTENT(IN) :: DO_BAROCLINIC

INTEGER :: I, J, K, ICF,LCF, JCF, IF_, N, KQ
REAL(EB) :: FMEAN
REAL(EB), ALLOCATABLE, DIMENSION(:) :: FLINK,ALINK
REAL(EB), POINTER, DIMENSION(:,:,:) :: FVXP, FVYP, FVZP
TYPE(CC_FV_TYPE), POINTER :: FV

CALL POINT_TO_MESH(NM)
FV=>MESHES(NM)%FV
ALLOCATE(FLINK(0:MESHES(NM)%NUNK_F),ALINK(0:MESHES(NM)%NUNK_F)); FLINK = 0._EB; ALINK = 0._EB

IF (DO_BAROCLINIC) THEN
   FVXP => FVX_B; FVYP => FVY_B; FVZP => FVZ_B; KQ = CC_FV_MOM_FN_B
ELSE
   FVXP => FVX  ; FVYP => FVY  ; FVZP => FVZ  ; KQ = CC_FV_MOM_FN
ENDIF
CALL ACCUM_L2_ORDERED_MEAN(NM,KQ,FLINK,ALINK)

! Area Average F:
FLINK(0) = 0._EB ! Unlinked small faces.
DO I=1,MESHES(NM)%NUNK_F
  IF (ALINK(I)>0._EB) FLINK(I) = FLINK(I) / ALINK(I)
ENDDO

! Linked Cartesian (regular and RC) faces.
DO N=1,SIZE(MESHES(NM)%LNK_CART)
   IF_ = MESHES(NM)%LNK_CART(N)
   I = FV%FACE%IJK_FACE(IAXIS,IF_); J = FV%FACE%IJK_FACE(JAXIS,IF_); K = FV%FACE%IJK_FACE(KAXIS,IF_)
   SELECT CASE(FV%FACE%X1AXIS(IF_))
   CASE(IAXIS); FVXP(I,J,K) = FLINK(FV%FACE%UNKF(IF_))
   CASE(JAXIS); FVYP(I,J,K) = FLINK(FV%FACE%UNKF(IF_))
   CASE(KAXIS); FVZP(I,J,K) = FLINK(FV%FACE%UNKF(IF_))
   END SELECT
ENDDO
! Gas cut faces: every piece (an unlinked small piece takes 0), then the Cartesian face takes their area mean.
DO LCF=1,SIZE(MESHES(NM)%CF_GAS)
   ICF=MESHES(NM)%CF_GAS(LCF); CF => CUT_FACE(ICF)
   IF(TWO_D .AND. CF%IJK(KAXIS+1)==JAXIS) CYCLE
   I = CF%IJK(IAXIS); J = CF%IJK(JAXIS); K = CF%IJK(KAXIS)
   DO JCF=1,CF%NFACE
      IF_=CF%FC(JCF)
      IF (DO_BAROCLINIC) THEN
         FV%FACE%FN_B(IF_)=FLINK(CC_FV_UNKF_CF(NM,ICF,JCF))
      ELSE
         FV%FACE%FN(IF_)=FLINK(CC_FV_UNKF_CF(NM,ICF,JCF))
      ENDIF
   ENDDO
   FMEAN = CC_FV_CUTFACE_MOM_AREA(NM,ICF,KQ)/SUM(CF%AREA(1:CF%NFACE))
   IF (DO_BAROCLINIC) THEN
      CF%FV_B = FMEAN
   ELSE
      CF%FV = FMEAN
   ENDIF
   SELECT CASE(CF%IJK(KAXIS+1))
   CASE(IAXIS); FVXP(I,J,K) = FMEAN
   CASE(JAXIS); FVYP(I,J,K) = FMEAN
   CASE(KAXIS); FVZP(I,J,K) = FMEAN
   END SELECT
ENDDO

DEALLOCATE(FLINK,ALINK)

END SUBROUTINE GET_LINKED_FV


