! ! ---------------------------- GET_LOCAL_VELOCITY ------------------------------

! SUBROUTINE GET_LOCAL_VELOCITY(U_RELA,NN,TT,SS,U_NORM,U_ORTH,U_STRM)
! USE MATH_FUNCTIONS, ONLY: CROSS_PRODUCT

! REAL(EB), INTENT(IN) :: NN(IAXIS:KAXIS), U_RELA(IAXIS:KAXIS)
! REAL(EB), INTENT(OUT):: TT(IAXIS:KAXIS), SS(IAXIS:KAXIS), U_NORM, U_ORTH, U_STRM

! ! Local Variables:
! REAL(EB), DIMENSION(3), PARAMETER :: E1=(/1._EB,0._EB,0._EB/),E2=(/0._EB,1._EB,0._EB/),E3=(/0._EB,0._EB,1._EB/)
! REAL(EB), DIMENSION(3,3) :: C

! ! find a vector TT in the tangent plane of the surface and orthogonal to U_VELO-U_SURF
! CALL CROSS_PRODUCT(TT,NN,U_RELA) ! TT = NN x U_RELA
! IF (ABS(NORM2(TT))<=TWENTY_EPSILON_EB) THEN
!    ! tangent vector is completely arbitrary, just perpendicular to NN
!    IF (ABS(NN(1))>=TWENTY_EPSILON_EB .OR.  ABS(NN(2))>=TWENTY_EPSILON_EB) TT = (/NN(2),-NN(1),0._EB/)
!    IF (ABS(NN(1))<=TWENTY_EPSILON_EB .AND. ABS(NN(2))<=TWENTY_EPSILON_EB) TT = (/NN(3),0._EB,-NN(1)/)
! ENDIF
! TT = TT/NORM2(TT) ! normalize to unit vector
! CALL CROSS_PRODUCT(SS,TT,NN) ! define the streamwise unit vector SS

! ! directional cosines (see Pope, Eq. A.11)
! C(1,1) = DOT_PRODUCT(E1,SS)
! C(1,2) = DOT_PRODUCT(E1,TT)
! C(1,3) = DOT_PRODUCT(E1,NN)
! C(2,1) = DOT_PRODUCT(E2,SS)
! C(2,2) = DOT_PRODUCT(E2,TT)
! C(2,3) = DOT_PRODUCT(E2,NN)
! C(3,1) = DOT_PRODUCT(E3,SS)
! C(3,2) = DOT_PRODUCT(E3,TT)
! C(3,3) = DOT_PRODUCT(E3,NN)

! ! transform velocity (see Pope, Eq. A.17)
! U_STRM = C(1,1)*U_RELA(1) + C(2,1)*U_RELA(2) + C(3,1)*U_RELA(3)
! U_ORTH = C(1,2)*U_RELA(1) + C(2,2)*U_RELA(2) + C(3,2)*U_RELA(3)
! U_NORM = C(1,3)*U_RELA(1) + C(2,3)*U_RELA(2) + C(3,3)*U_RELA(3)

! RETURN
! END SUBROUTINE GET_LOCAL_VELOCITY


! ------------------------------- CC_NO_FLUX ---------------------------------

SUBROUTINE CC_FV_SET_CUTFACE_FORCE(NM,ICF,JCF,FN_VALUE,FN_B_VALUE)
INTEGER, INTENT(IN) :: NM,ICF,JCF
REAL(EB), INTENT(IN), OPTIONAL :: FN_VALUE,FN_B_VALUE
INTEGER :: IF_
TYPE(CC_FV_TYPE), POINTER :: FV

FV=>MESHES(NM)%FV
IF_=MESHES(NM)%CUT_FACE(ICF)%FC(JCF)
IF (PRESENT(FN_VALUE)) FV%FACE%FN(IF_)=FN_VALUE
IF (PRESENT(FN_B_VALUE)) FV%FACE%FN_B(IF_)=FN_B_VALUE
END SUBROUTINE CC_FV_SET_CUTFACE_FORCE

SUBROUTINE CC_NO_FLUX(DT,NM,FORCE_FLG)

! Force to zero velocities on faces of type CC_SOLID.

INTEGER, INTENT(IN) :: NM
REAL(EB), INTENT(IN):: DT
LOGICAL, INTENT(IN) :: FORCE_FLG

! Local Variables:
REAL(EB), POINTER, DIMENSION(:,:,:) :: HP
REAL(EB):: U_IBM,DUUDT,RFODT,TNOW,UN,AFCT,IDX
INTEGER :: I,J,K,II,JJ,KK,IOR,IW,ICF,LCF,JCF,X1AXIS,NOM,IFACE,JFACE
TYPE(WALL_TYPE), POINTER :: WC
TYPE(EXTERNAL_WALL_TYPE), POINTER :: EWC
TYPE(CFACE_TYPE), POINTER :: CFA
REAL(EB) :: VEL_F,VELS_F


! This is the CCIBM forcing routine for momentum eqns.

IF (SOLID_PHASE_ONLY .OR. FREEZE_VELOCITY) RETURN
IF ( PERIODIC_TEST == 103 .OR. PERIODIC_TEST == 11 .OR. PERIODIC_TEST==7) RETURN

TNOW=CURRENT_TIME()

RFODT = RELAXATION_FACTOR/DT

CALL POINT_TO_MESH(NM)

IF (PREDICTOR) HP => H
IF (CORRECTOR) HP => HS

FORCE_IF : IF (FORCE_FLG) THEN

   U_IBM = 0._EB
   IF (PRESSURE_ITERATIONS==1) THEN
      CUTFACE_LOOP_2A : DO LCF=1,SIZE(MESHES(NM)%CF_GAS)
         ICF=MESHES(NM)%CF_GAS(LCF); CF => CUT_FACE(ICF)
         IF (CF%ALPHA_CF > A_THRESH_FORCING) CYCLE CUTFACE_LOOP_2A
         I = CF%IJK(IAXIS); J = CF%IJK(JAXIS); K = CF%IJK(KAXIS); X1AXIS = CF%IJK(KAXIS+1)
         II = I; JJ = J; KK = K
         SELECT CASE(X1AXIS)
         CASE(IAXIS); II = I+1
         CASE(JAXIS); JJ = J+1
         CASE(KAXIS); KK = K+1
         END SELECT
         DO JCF=1,CF%NFACE
            VEL_F=CC_FV_CUTFACE_MOM(NM,ICF,JCF,CC_FV_MOM_VEL)
            VELS_F=CC_FV_CUTFACE_MOM(NM,ICF,JCF,CC_FV_MOM_VELS)
            IF (PREDICTOR) DUUDT = (U_IBM-VEL_F)/DT
            IF (CORRECTOR) DUUDT = (2._EB*U_IBM-(VEL_F+VELS_F))/DT
            IDX=1._EB/(CF%XCENHIGH(X1AXIS,JCF)-CF%XCENLOW(X1AXIS,JCF))
            CALL CC_FV_SET_CUTFACE_FORCE(NM,ICF,JCF,-IDX*(HP(II,JJ,KK)-HP(I,J,K))-DUUDT,0._EB)
         ENDDO
      ENDDO CUTFACE_LOOP_2A
   ENDIF

ELSE FORCE_IF

! Here for External CFACEs use the unstructured acceleration in defining F:
CFACE_LOOP : DO ICF=1,N_EXTERNAL_CFACE_CELLS+N_INTWALL_CFACE_CELLS+N_INTERNAL_CFACE_CELLS
   CFA  =>CFACE(ICF)
   IW   =CUT_FACE(CFA%CUT_FACE_IND1)%IWC ! Index of underlaying wall cell.
   IFACE=CFA%CUT_FACE_IND1
   JFACE=CFA%CUT_FACE_IND2
   BC => BOUNDARY_COORD(CFA%BC_INDEX)
   II = BC%II; JJ = BC%JJ; KK = BC%KK; IOR = BC%IOR
   IF ( .NOT.(CFA%BOUNDARY_TYPE==INTERPOLATED_BOUNDARY .OR. CFA%BOUNDARY_TYPE==PERIODIC_BOUNDARY) ) THEN
      NOM=0; IF(ICF<=N_EXTERNAL_CFACE_CELLS) NOM = EXTERNAL_WALL(IW)%NOM
      II  = BC%II
      JJ  = BC%JJ
      KK  = BC%KK

      B1 => BOUNDARY_PROP1(CFA%B1_INDEX)
      IF (NOM/=0 .OR. ANY(CFA%BOUNDARY_TYPE==(/SOLID_BOUNDARY,NULL_BOUNDARY,MIRROR_BOUNDARY/))) THEN
         AFCT = 1._EB
         IF(ICF<=N_EXTERNAL_CFACE_CELLS+N_INTWALL_CFACE_CELLS) AFCT = -SIGN(1._EB,REAL(IOR,EB))
         VEL_F=CC_FV_CUTFACE_MOM(NM,IFACE,JFACE,CC_FV_MOM_VEL)
         VELS_F=CC_FV_CUTFACE_MOM(NM,IFACE,JFACE,CC_FV_MOM_VELS)
         IF (PREDICTOR) THEN
            UN    = AFCT*B1%U_NORMAL_S
            DUUDT = RFODT*(UN-VEL_F)
         ELSE
            UN = AFCT*B1%U_NORMAL
            DUUDT = 2._EB*RFODT*(UN-0.5_EB*(VEL_F+VELS_F))
         ENDIF
         CALL CC_FV_SET_CUTFACE_FORCE(NM,IFACE,JFACE,-DUUDT)
      ENDIF
   ENDIF
ENDDO CFACE_LOOP

! Now set WALL_WORK(IW) to zero in EXTERNAL WALL CELLS of type CC_SOLID:
! This Follows what is being done for external boundaries inside OBSTS (NULL_BOUNDARY).
EWC_LOOP : DO IW=1,N_EXTERNAL_WALL_CELLS
   WC => WALL(IW)
   IF (.NOT.(WC%BOUNDARY_TYPE==NULL_BOUNDARY .OR. WC%BOUNDARY_TYPE==INTERPOLATED_BOUNDARY)) CYCLE
   EWC=>EXTERNAL_WALL(IW)

   BC=>BOUNDARY_COORD(WC%BC_INDEX)
   II = BC%II
   JJ = BC%JJ
   KK = BC%KK
   IOR = BC%IOR

   ! The Cartesian face of the wall cell: at II,JJ,KK for IOR>0, one cell lower for IOR<0.
   SELECT CASE(IOR)
   CASE(-IAXIS); II = II-1
   CASE(-JAXIS); JJ = JJ-1
   CASE(-KAXIS); KK = KK-1
   END SELECT
   IF(FCVAR(II,JJ,KK,CC_FGSC,ABS(IOR))==CC_SOLID) WALL_WORK1(IW) = 0._EB

ENDDO EWC_LOOP

ENDIF FORCE_IF

T_USED(14) = T_USED(14) + CURRENT_TIME() - TNOW
IF (TIME_CC_IBM) T_CC_USED(CC_NO_FLUX_TIME_INDEX) = T_CC_USED(CC_NO_FLUX_TIME_INDEX) + CURRENT_TIME() - TNOW
RETURN
END SUBROUTINE CC_NO_FLUX

SUBROUTINE CC_STORE_FACE_FV(NM,SUBSTRACT_BAROCLINIC)
! CUT_FACE%FV of each gas cut face: the Cartesian F of its face, less the baroclinic part when asked; 0 on mirrors.

INTEGER, INTENT(IN) :: NM
LOGICAL, INTENT(IN) :: SUBSTRACT_BAROCLINIC

INTEGER :: ICF,LCF,I,J,K

DO LCF=1,SIZE(MESHES(NM)%CF_GAS)
   ICF=MESHES(NM)%CF_GAS(LCF)
   CUT_FACE(ICF)%FV = 0._EB
   IF(CUT_FACE(ICF)%IWC>0) THEN; IF(WALL(CUT_FACE(ICF)%IWC)%BOUNDARY_TYPE==MIRROR_BOUNDARY) CYCLE; ENDIF
   I = CUT_FACE(ICF)%IJK(IAXIS); J = CUT_FACE(ICF)%IJK(JAXIS); K = CUT_FACE(ICF)%IJK(KAXIS)
   SELECT CASE(CUT_FACE(ICF)%IJK(KAXIS+1))
   CASE(IAXIS)
      CUT_FACE(ICF)%FV = FVX(I,J,K)
      IF (SUBSTRACT_BAROCLINIC) CUT_FACE(ICF)%FV = FVX(I,J,K) - FVX_B(I,J,K)
   CASE(JAXIS)
      CUT_FACE(ICF)%FV = FVY(I,J,K)
      IF (SUBSTRACT_BAROCLINIC) CUT_FACE(ICF)%FV = FVY(I,J,K) - FVY_B(I,J,K)
   CASE(KAXIS)
      CUT_FACE(ICF)%FV = FVZ(I,J,K)
      IF (SUBSTRACT_BAROCLINIC) CUT_FACE(ICF)%FV = FVZ(I,J,K) - FVZ_B(I,J,K)
   END SELECT
ENDDO

END SUBROUTINE CC_STORE_FACE_FV

! ------------------------- CC_COMPUTE_VELOCITY_ERROR -------------------------

SUBROUTINE CC_COMPUTE_VELOCITY_ERROR(DT,NM)

! Compute velocity error on faces of type CC_SOLID.

INTEGER, INTENT(IN) :: NM
REAL(EB), INTENT(IN) :: DT

! Local Variables:
INTEGER :: I,J,K,IW,II,JJ,KK,IIG,JJG,KKG,IOR,X1AXIS,ICF,JCF,IIO,JJO,KKO,IIO1,IIO2,JJO1,JJO2,KKO1,KKO2,ICC_LO,ICC_HI,IF_,IRC
INTEGER :: IROW
REAL(EB):: ITERATIVE_FACTOR, UN_NEW, UN_NEW_OTHER, VELOCITY_ERROR, IDX, DUDT, DVDT, DWDT, DA_OTHER, AREA_FC, TNOW
REAL(EB):: X_LO, X_HI  ! Centroid coordinates for proper IDX calculation in RC faces
TYPE(OMESH_TYPE), POINTER :: OM
TYPE(MESH_TYPE), POINTER :: M2
TYPE(WALL_TYPE), POINTER :: WC
TYPE(BOUNDARY_COORD_TYPE), POINTER :: BC
TYPE(BOUNDARY_PROP1_TYPE), POINTER :: B1
TYPE(CC_CUTFACE_TYPE), POINTER :: CF,CF2

IF (SOLID_PHASE_ONLY) RETURN
IF (FREEZE_VELOCITY)  RETURN

TNOW = CURRENT_TIME()

CALL POINT_TO_MESH(NM)

! Here we recompute the average velocity error in external gas cut-faces, and test against other mesh.
! The corresponding WALL_WORK1(IW) term for pressure boundary conditions is updated where necessary.
IF (PREDICTOR) THEN
   ITERATIVE_FACTOR = 0.25_EB
ELSE
   ITERATIVE_FACTOR = 0.50_EB
ENDIF

! Loop over wall cells and check velocity error.

CHECK_WALL_LOOP: DO IW=1,N_EXTERNAL_WALL_CELLS

   WC=>WALL(IW)
   IF (.NOT.(WC%BOUNDARY_TYPE==INTERPOLATED_BOUNDARY .OR. WC%BOUNDARY_TYPE==PERIODIC_BOUNDARY)) CYCLE CHECK_WALL_LOOP

   BC => BOUNDARY_COORD(WC%BC_INDEX)

   IIG = BC%IIG; JJG = BC%JJG; KKG = BC%KKG
   II  = BC%II;  JJ  = BC%JJ;  KK  = BC%KK; IOR = BC%IOR

   ! Skip regular gas faces - only process faces where at least one cell is a cut-cell
   IF(ALL((/CCVAR(IIG,JJG,KKG,CC_CGSC),CCVAR(II,JJ,KK,CC_CGSC)/)==CC_GASPHASE)) CYCLE CHECK_WALL_LOOP

   EWC=>EXTERNAL_WALL(IW)
   IF (EWC%AREA_RATIO<0.9_EB) CYCLE CHECK_WALL_LOOP
   OM => OMESH(EWC%NOM)
   M2 => MESHES(EWC%NOM)
   B1 => BOUNDARY_PROP1(WC%B1_INDEX)
   I=IIG; J=JJG; K=KKG;
   SELECT CASE(IOR)
   CASE(1); I=I-1
   CASE(2); J=J-1
   CASE(3); K=K-1
   END SELECT
   X1AXIS = ABS(IOR)

   UN_NEW = 0._EB
   IF(WC%CUT_FACE_INDEX>0) THEN
      ICF = WC%CUT_FACE_INDEX; CF => CUT_FACE(ICF)
      ! Update normal component of velocity at the mesh boundary
      IF (PREDICTOR) THEN
         SELECT CASE(X1AXIS)
         CASE(IAXIS)
            DO JCF=1,CF%NFACE
               IF_=CF%FC(JCF)
               IDX = GET_FV_FACE_RDN(NM,IF_,1._EB/(CF%XCENHIGH(X1AXIS,JCF)-CF%XCENLOW(X1AXIS,JCF)))
               UN_NEW = UN_NEW + (CC_FV_CUTFACE_MOM(NM,ICF,JCF,CC_FV_MOM_VEL)- &
                                  DT*(CC_FV_CUTFACE_MOM(NM,ICF,JCF,CC_FV_MOM_FN)+IDX*(H(I+1,J,K)-H(I,J,K))))*CF%AREA(JCF)
            ENDDO
         CASE(JAXIS)
            DO JCF=1,CF%NFACE
               IF_=CF%FC(JCF)
               IDX = GET_FV_FACE_RDN(NM,IF_,1._EB/(CF%XCENHIGH(X1AXIS,JCF)-CF%XCENLOW(X1AXIS,JCF)))
               UN_NEW = UN_NEW + (CC_FV_CUTFACE_MOM(NM,ICF,JCF,CC_FV_MOM_VEL)- &
                                  DT*(CC_FV_CUTFACE_MOM(NM,ICF,JCF,CC_FV_MOM_FN)+IDX*(H(I,J+1,K)-H(I,J,K))))*CF%AREA(JCF)
            ENDDO
         CASE(KAXIS)
            DO JCF=1,CF%NFACE
               IF_=CF%FC(JCF)
               IDX = GET_FV_FACE_RDN(NM,IF_,1._EB/(CF%XCENHIGH(X1AXIS,JCF)-CF%XCENLOW(X1AXIS,JCF)))
               UN_NEW = UN_NEW + (CC_FV_CUTFACE_MOM(NM,ICF,JCF,CC_FV_MOM_VEL)- &
                                  DT*(CC_FV_CUTFACE_MOM(NM,ICF,JCF,CC_FV_MOM_FN)+IDX*(H(I,J,K+1)-H(I,J,K))))*CF%AREA(JCF)
            ENDDO
         END SELECT
      ELSE
         SELECT CASE(X1AXIS)
         CASE(IAXIS)
            DO JCF=1,CF%NFACE
               IF_=CF%FC(JCF)
               IDX = GET_FV_FACE_RDN(NM,IF_,1._EB/(CF%XCENHIGH(X1AXIS,JCF)-CF%XCENLOW(X1AXIS,JCF)))
               UN_NEW = UN_NEW + 0.5_EB*(CC_FV_CUTFACE_MOM(NM,ICF,JCF,CC_FV_MOM_VEL)+CC_FV_CUTFACE_MOM(NM,ICF,JCF,CC_FV_MOM_VELS)- &
                                         DT*(CC_FV_CUTFACE_MOM(NM,ICF,JCF,CC_FV_MOM_FN)+IDX*(HS(I+1,J,K)-HS(I,J,K))))*CF%AREA(JCF)
            ENDDO
         CASE(JAXIS)
            DO JCF=1,CF%NFACE
               IF_=CF%FC(JCF)
               IDX = GET_FV_FACE_RDN(NM,IF_,1._EB/(CF%XCENHIGH(X1AXIS,JCF)-CF%XCENLOW(X1AXIS,JCF)))
               UN_NEW = UN_NEW + 0.5_EB*(CC_FV_CUTFACE_MOM(NM,ICF,JCF,CC_FV_MOM_VEL)+CC_FV_CUTFACE_MOM(NM,ICF,JCF,CC_FV_MOM_VELS)- &
                                         DT*(CC_FV_CUTFACE_MOM(NM,ICF,JCF,CC_FV_MOM_FN)+IDX*(HS(I,J+1,K)-HS(I,J,K))))*CF%AREA(JCF)
            ENDDO
         CASE(KAXIS)
            DO JCF=1,CF%NFACE
               IF_=CF%FC(JCF)
               IDX = GET_FV_FACE_RDN(NM,IF_,1._EB/(CF%XCENHIGH(X1AXIS,JCF)-CF%XCENLOW(X1AXIS,JCF)))
               UN_NEW = UN_NEW + 0.5_EB*(CC_FV_CUTFACE_MOM(NM,ICF,JCF,CC_FV_MOM_VEL)+CC_FV_CUTFACE_MOM(NM,ICF,JCF,CC_FV_MOM_VELS)- &
                                         DT*(CC_FV_CUTFACE_MOM(NM,ICF,JCF,CC_FV_MOM_FN)+IDX*(HS(I,J,K+1)-HS(I,J,K))))*CF%AREA(JCF)
            ENDDO
         END SELECT

      ENDIF
      UN_NEW = UN_NEW / SUM(CF%AREA(1:CF%NFACE))
   ELSE
      ! RC_FACES: Compute velocity projection using centroid-to-centroid distance
      SELECT CASE(X1AXIS)
      CASE(IAXIS)
         ICC_LO = CCVAR(I,J,K,CC_IDCC); ICC_HI = CCVAR(I+1,J,K,CC_IDCC)
         IF (ICC_LO>0) THEN; X_LO=CUT_CELL(ICC_LO)%XYZCEN(IAXIS,1); ELSE; X_LO=XC(I); ENDIF
         IF (ICC_HI>0) THEN; X_HI=CUT_CELL(ICC_HI)%XYZCEN(IAXIS,1); ELSE; X_HI=XC(I+1); ENDIF
         IRC = FCVAR(I,J,K,CC_IDRC,X1AXIS); IF_=0; IF (IRC>0) IF_=RC_FACE(IRC)%FC
         IDX = GET_FV_FACE_RDN(NM,IF_,1._EB/(X_HI - X_LO))
         IF (PREDICTOR) THEN
            UN_NEW = U(I,J,K) - DT*(FVX(I,J,K) + IDX*(H(I+1,J,K)-H(I,J,K)))
         ELSE
            UN_NEW = 0.5_EB*( (U(I,J,K)+US(I,J,K)) - DT*(FVX(I,J,K) + IDX*(HS(I+1,J,K)-HS(I,J,K))) )
         ENDIF
      CASE(JAXIS)
         ICC_LO = CCVAR(I,J,K,CC_IDCC); ICC_HI = CCVAR(I,J+1,K,CC_IDCC)
         IF (ICC_LO>0) THEN; X_LO=CUT_CELL(ICC_LO)%XYZCEN(JAXIS,1); ELSE; X_LO=YC(J); ENDIF
         IF (ICC_HI>0) THEN; X_HI=CUT_CELL(ICC_HI)%XYZCEN(JAXIS,1); ELSE; X_HI=YC(J+1); ENDIF
         IRC = FCVAR(I,J,K,CC_IDRC,X1AXIS); IF_=0; IF (IRC>0) IF_=RC_FACE(IRC)%FC
         IDX = GET_FV_FACE_RDN(NM,IF_,1._EB/(X_HI - X_LO))
         IF (PREDICTOR) THEN
            UN_NEW = V(I,J,K) - DT*(FVY(I,J,K) + IDX*(H(I,J+1,K)-H(I,J,K)))
         ELSE
            UN_NEW = 0.5_EB*( (V(I,J,K)+VS(I,J,K)) - DT*(FVY(I,J,K) + IDX*(HS(I,J+1,K)-HS(I,J,K))) )
         ENDIF
      CASE(KAXIS)
         ICC_LO = CCVAR(I,J,K,CC_IDCC); ICC_HI = CCVAR(I,J,K+1,CC_IDCC)
         IF (ICC_LO>0) THEN; X_LO=CUT_CELL(ICC_LO)%XYZCEN(KAXIS,1); ELSE; X_LO=ZC(K); ENDIF
         IF (ICC_HI>0) THEN; X_HI=CUT_CELL(ICC_HI)%XYZCEN(KAXIS,1); ELSE; X_HI=ZC(K+1); ENDIF
         IRC = FCVAR(I,J,K,CC_IDRC,X1AXIS); IF_=0; IF (IRC>0) IF_=RC_FACE(IRC)%FC
         IDX = GET_FV_FACE_RDN(NM,IF_,1._EB/(X_HI - X_LO))
         IF (PREDICTOR) THEN
            UN_NEW = W(I,J,K) - DT*(FVZ(I,J,K) + IDX*(H(I,J,K+1)-H(I,J,K)))
         ELSE
            UN_NEW = 0.5_EB*( (W(I,J,K)+WS(I,J,K)) - DT*(FVZ(I,J,K) + IDX*(HS(I,J,K+1)-HS(I,J,K))) )
         ENDIF
      END SELECT
   ENDIF

   ! At interpolated boundaries, compare updated normal component of velocity with that of the other mesh

   ! NOTE: WC%BOUNDARY_TYPE==INTERPOLATED_BOUNDARY

   UN_NEW_OTHER = 0._EB
   DA_OTHER = 0._EB

   EWC  =>EXTERNAL_WALL(IW)
   IIO1 = EWC%IIO_MIN
   JJO1 = EWC%JJO_MIN
   KKO1 = EWC%KKO_MIN
   IIO2 = EWC%IIO_MAX
   JJO2 = EWC%JJO_MAX
   KKO2 = EWC%KKO_MAX

   PREDICTOR_IF: IF (PREDICTOR) THEN
      IOR_SELECT_1: SELECT CASE(IOR)
         CASE( 1)
            DO KKO=KKO1,KKO2
               DO JJO=JJO1,JJO2
                  DO IIO=IIO1,IIO2
                     IF (M2%CELL(M2%CELL_INDEX(IIO,JJO,KKO))%SOLID) CYCLE
                     IF (M2%FCVAR(IIO,JJO,KKO,CC_FGSC,X1AXIS)==CC_SOLID) CYCLE

                     ICF = M2%FCVAR(IIO,JJO,KKO,CC_IDCF,X1AXIS)
                     IF (ICF>0) THEN
                        CF2 =>M2%CUT_FACE(ICF); IDX = M2%RDXN(IIO)
                        DO JCF=1,CF2%NFACE
                              DA_OTHER = DA_OTHER  + CF2%AREA(JCF)
                              IF_=CF2%FC(JCF)
                              IROW = OM%CFHALO_ROW0(ICF)+JCF-1
